-- ==============================================================================
-- MIGRACIÓN 031: MOTOR DE TURNOS CON TEMPORIZADOR DE 10S Y LIMPIEZA DE MESAS
-- Proyecto: RASPANDO LA OLLA
-- Estado: PRODUCCIÓN / EJECUTAR EN SUPABASE SQL EDITOR DIRECTAMENTE
-- ==============================================================================

-- 1. Función RPC para Limpieza Transaccional de Mesas Huérfanas
CREATE OR REPLACE FUNCTION public.cleanup_orphaned_tables_and_sessions()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_closed_tables INT := 0;
  v_cancelled_sessions INT := 0;
  v_table RECORD;
BEGIN
  -- Buscar mesas activas o abiertas donde 0 jugadores estén en estado JOINED, READY o PLAYING
  FOR v_table IN
    SELECT t.id
    FROM public.game_tables t
    WHERE t.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
      AND NOT EXISTS (
        SELECT 1
        FROM public.game_table_players p
        WHERE p.table_id = t.id
          AND p.status IN ('JOINED', 'READY', 'PLAYING')
      )
  LOOP
    -- Cancelar sesiones activas de la mesa
    UPDATE public.game_sessions
    SET status = 'CANCELLED'::session_status_enum,
        ended_at = NOW()
    WHERE table_id = v_table.id
      AND status IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED');
    
    GET DIAGNOSTICS v_cancelled_sessions = ROW_COUNT;

    -- Cerrar la mesa
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        current_players_count = 0,
        updated_at = NOW()
    WHERE id = v_table.id;

    v_closed_tables := v_closed_tables + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'closed_tables', v_closed_tables,
    'cancelled_sessions', v_cancelled_sessions
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_orphaned_tables_and_sessions() TO authenticated, anon, service_role;

-- 2. RPC para Expiración Atómica de Turno de Dominó (Timeout de 10 segundos)
CREATE OR REPLACE FUNCTION public.expire_domino_turn_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_turn_user_id UUID;
  v_player_order JSONB;
  v_player_count INT;
  v_curr_idx INT := -1;
  v_next_idx INT;
  v_next_user_id UUID;
  v_passes_in_row INT;
  v_i INT;
  v_turn_deadline TIMESTAMPTZ;
  v_action_res JSONB;
BEGIN
  -- Bloquear sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: La sesión de juego no existe';
  END IF;

  IF v_session.status NOT IN ('ACTIVE', 'READY', 'STARTING') THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_NOT_ACTIVE');
  END IF;

  v_state := v_session.current_state;
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID
  );

  v_player_order := v_state->'playerOrder';
  v_player_count := jsonb_array_length(v_player_order);

  IF v_player_count IS NULL OR v_player_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'reason', 'NO_PLAYERS_IN_ORDER');
  END IF;

  -- Encontrar índice del jugador actual
  FOR v_i IN 0..(v_player_count - 1) LOOP
    IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
      v_curr_idx := v_i;
      EXIT;
    END IF;
  END LOOP;

  IF v_curr_idx = -1 THEN
    v_curr_idx := 0;
  END IF;

  -- Avanzar al siguiente jugador en orden de asientos
  v_next_idx := (v_curr_idx + 1) % v_player_count;
  v_next_user_id := (v_player_order->>v_next_idx)::UUID;

  v_passes_in_row := COALESCE((v_state->>'passesInRow')::INT, 0) + 1;
  v_turn_deadline := NOW() + INTERVAL '10 seconds';

  -- Actualizar el estado JSONB con el nuevo turno
  v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_next_user_id::text));
  v_state := jsonb_set(v_state, '{passesInRow}', to_jsonb(v_passes_in_row));

  -- Registrar la acción de TIMEOUT en el historial atómico
  v_action_res := public.submit_game_action_secure(
    p_session_id,
    'TIMEOUT',
    jsonb_build_object('expiredUserId', v_turn_user_id, 'nextUserId', v_next_user_id),
    'timeout_' || p_session_id::text || '_' || v_turn_user_id::text || '_' || extract(epoch from now())::text
  );

  -- Actualizar la sesión con el nuevo turno y la fecha límite de 10 segundos
  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_user_id,
      turn_deadline_at = v_turn_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TIMEOUT_PROCESSED',
    'expired_user_id', v_turn_user_id,
    'next_turn_user_id', v_next_user_id,
    'turn_deadline_at', v_turn_deadline
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.expire_domino_turn_secure(UUID) TO authenticated, anon, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 32: 032_game_turn_lives_and_timeout.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 032: MOTOR UNIFICADO DE TURNOS, TEMPORIZADOR, 3 VIDAS Y EXPIRACIÓN ATÓMICA
-- Proyecto: RASPANDO LA OLLA
-- Estado: PRODUCCIÓN / EJECUTAR EN SUPABASE SQL EDITOR DIRECTAMENTE
-- ==============================================================================

-- 1. RPC para Expiración Atómica de Turno con Deducción de 3 Vidas y Liquidación por Timeout
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_turn_user_id UUID;
  v_player_order JSONB := '[]'::jsonb;
  v_players JSONB := '[]'::jsonb;
  v_lives JSONB;
  v_curr_lives INT;
  v_player_count INT := 0;
  v_curr_idx INT := -1;
  v_next_idx INT;
  v_next_user_id UUID;
  v_winner_id UUID := NULL;
  v_is_game_over BOOLEAN := FALSE;
  v_i INT;
  v_turn_deadline TIMESTAMPTZ;
  v_action_res JSONB;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settle_res JSONB;
BEGIN
  -- Bloquear sesión transaccionalmente para evitar condiciones de carrera
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: La sesión de juego no existe';
  END IF;

  -- Verificar que la sesión esté en estado activo
  IF v_session.status NOT IN ('ACTIVE', 'READY', 'STARTING', 'in_progress') THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_NOT_ACTIVE');
  END IF;

  v_state := v_session.current_state;
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'NO_TURN_USER_DEFINED');
  END IF;

  -- Determinar lista de jugadores desde playerOrder o players array
  IF v_state ? 'playerOrder' AND jsonb_array_length(v_state->'playerOrder') > 0 THEN
    v_player_order := v_state->'playerOrder';
  ELSIF v_state ? 'players' AND jsonb_array_length(v_state->'players') > 0 THEN
    -- Extraer userIds de la estructura de jugadores
    FOR v_i IN 0..(jsonb_array_length(v_state->'players') - 1) LOOP
      v_player_order := v_player_order || to_jsonb((v_state->'players'->v_i->>'userId'));
    END LOOP;
  END IF;

  v_player_count := jsonb_array_length(v_player_order);

  -- Extraer o inicializar vidas (3 vidas por defecto por jugador)
  IF v_state ? 'lives' THEN
    v_lives := v_state->'lives';
  ELSE
    v_lives := '{}'::jsonb;
    FOR v_i IN 0..(v_player_count - 1) LOOP
      v_lives := jsonb_set(v_lives, ARRAY[(v_player_order->>v_i)], '3'::jsonb);
    END LOOP;
  END IF;

  -- Obtener vidas del jugador actual y restar 1
  v_curr_lives := COALESCE((v_lives->>v_turn_user_id::text)::INT, 3) - 1;
  IF v_curr_lives < 0 THEN
    v_curr_lives := 0;
  END IF;

  v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::text], to_jsonb(v_curr_lives));
  v_state := jsonb_set(v_state, '{lives}', v_lives);

  -- Registrar acción TIMEOUT_LIFE_LOST en game_actions de forma idempotente
  v_action_res := public.submit_game_action_secure(
    p_session_id,
    'TIMEOUT_LIFE_LOST',
    jsonb_build_object(
      'userId', v_turn_user_id,
      'remainingLives', v_curr_lives
    ),
    'timeout_life_' || p_session_id::text || '_' || v_turn_user_id::text || '_' || extract(epoch from now())::text
  );

  -- Si el jugador se queda sin vidas (0 vidas), pierde la mano/partida automáticamente
  IF v_curr_lives <= 0 THEN
    v_is_game_over := TRUE;
    
    -- El ganador es el oponente que aún conserva vidas
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID <> v_turn_user_id THEN
        v_winner_id := (v_player_order->>v_i)::UUID;
        EXIT;
      END IF;
    END LOOP;

    v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
    v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_winner_id::text));
    v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_LIVES_EXHAUSTED"'::jsonb);

    -- Liquidación automática 90% ganador / 10% plataforma
    v_gross_pool := v_session.gross_pool;
    v_prize_pool := v_session.winner_prize_amount;
    v_platform_fee := v_session.service_fee_amount;

    -- Ejecutar RPC de liquidación si existe
    BEGIN
      v_settle_res := public.settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL,
        'timeout_settle_' || p_session_id::text || '_' || extract(epoch from now())::text
      );
    EXCEPTION WHEN OTHERS THEN
      -- Fallback si ya estaba liquidado
    END;

    UPDATE public.game_sessions
    SET current_state = v_state,
        status = 'SETTLED'::session_status_enum,
        winner_user_id = v_winner_id,
        is_settled = TRUE,
        ended_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Cerrar la mesa asociada
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        updated_at = NOW()
    WHERE id = v_session.table_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ENDED_BY_TIMEOUT',
      'timed_out_user_id', v_turn_user_id,
      'remaining_lives', 0,
      'winner_user_id', v_winner_id,
      'is_game_over', true
    );
  END IF;

  -- Si conserva vidas (> 0), rotar turno al siguiente jugador
  FOR v_i IN 0..(v_player_count - 1) LOOP
    IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
      v_curr_idx := v_i;
      EXIT;
    END IF;
  END LOOP;

  IF v_curr_idx = -1 THEN
    v_curr_idx := 0;
  END IF;

  v_next_idx := (v_curr_idx + 1) % v_player_count;
  v_next_user_id := (v_player_order->>v_next_idx)::UUID;

  v_turn_deadline := NOW() + INTERVAL '30 seconds';

  v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_next_user_id::text));

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_user_id,
      turn_deadline_at = v_turn_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TIMEOUT_PROCESSED_LIFE_LOST',
    'timed_out_user_id', v_turn_user_id,
    'remaining_lives', v_curr_lives,
    'next_turn_user_id', v_next_user_id,
    'turn_deadline_at', v_turn_deadline,
    'is_game_over', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(UUID) TO authenticated, anon, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 33: 033_polla_venezolana_system.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 033: SISTEMA OFICIAL DE POLLA VENEZOLANA
-- ==============================================================================
-- Quiniela de Animalitos (00-76), Bloques Mañana/Tarde, Ventanas de Venta,
-- Compras Atómicas de 250 Bs con Ledger, Cierres Auditables y RLS.
-- ==============================================================================

-- 1. TABLA DE TICKETS/POLLAS COMPRADAS
CREATE TABLE IF NOT EXISTS public.polla_tickets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  block TEXT NOT NULL CHECK (block IN ('MAÑANA', 'TARDE')),
  draw_date DATE NOT NULL,
  animalitos TEXT[] NOT NULL CHECK (cardinality(animalitos) = 6),
  cost_bs NUMERIC(15,2) NOT NULL DEFAULT 250.00,
  hits INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'WINNER', 'NOT_WINNER', 'CANCELLED')),
  prize_bs NUMERIC(15,2) NOT NULL DEFAULT 0.00,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexación rápida para consultas por usuario y por bloque
CREATE INDEX IF NOT EXISTS idx_polla_tickets_user ON public.polla_tickets(user_id);
CREATE INDEX IF NOT EXISTS idx_polla_tickets_date_block ON public.polla_tickets(draw_date, block);

-- 2. TABLA DE RESULTADOS DE SORTEOS
CREATE TABLE IF NOT EXISTS public.polla_draw_results (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  draw_date DATE NOT NULL,
  block TEXT NOT NULL CHECK (block IN ('MAÑANA', 'TARDE')),
  draw_time TIME NOT NULL,
  lotteries JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_by UUID REFERENCES public.profiles(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(draw_date, block, draw_time)
);

-- 3. TABLA DE CIERRES AUDITABLES Y GANADORES
CREATE TABLE IF NOT EXISTS public.polla_block_closures (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  draw_date DATE NOT NULL,
  block TEXT NOT NULL CHECK (block IN ('MAÑANA', 'TARDE')),
  winner_user_id UUID REFERENCES public.profiles(id),
  winner_ticket_id UUID REFERENCES public.polla_tickets(id),
  hits INT NOT NULL DEFAULT 6,
  closure_reason TEXT NOT NULL DEFAULT 'REGULAR_6_HITS',
  closure_event_data JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(draw_date, block)
);

-- 4. HABILITAR ROW LEVEL SECURITY (RLS)
ALTER TABLE public.polla_tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.polla_draw_results ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.polla_block_closures ENABLE ROW LEVEL SECURITY;

-- Políticas para polla_tickets
DROP POLICY IF EXISTS "Usuarios ven sus propias pollas" ON public.polla_tickets;
CREATE POLICY "Usuarios ven sus propias pollas"
  ON public.polla_tickets FOR SELECT
  USING (auth.uid() = user_id OR public.is_admin(auth.uid()));

DROP POLICY IF EXISTS "Inserción vía RPC buy_polla_ticket_secure" ON public.polla_tickets;
DROP POLICY IF EXISTS "Sin inserción directa de usuarios" ON public.polla_tickets;
-- No INSERT policy for polla_tickets: Inserts are strictly reserved for SECURITY DEFINER RPC buy_polla_ticket_secure

-- Políticas para polla_draw_results (Lectura pública a usuarios autenticados)
DROP POLICY IF EXISTS "Lectura pública de resultados" ON public.polla_draw_results;
CREATE POLICY "Lectura pública de resultados"
  ON public.polla_draw_results FOR SELECT
  USING (auth.role() = 'authenticated');

DROP POLICY IF EXISTS "Solo administradores crean resultados" ON public.polla_draw_results;
CREATE POLICY "Solo administradores crean resultados"
  ON public.polla_draw_results FOR ALL
  USING (public.is_admin(auth.uid()));

-- Políticas para polla_block_closures
DROP POLICY IF EXISTS "Lectura pública de ganadores y cierres" ON public.polla_block_closures;
CREATE POLICY "Lectura pública de ganadores y cierres"
  ON public.polla_block_closures FOR SELECT
  USING (auth.role() = 'authenticated');

-- 5. RPC SERVER-AUTHORITATIVE PARA COMPRA ATÓMICA DE POLLA (250 Bs)
CREATE OR REPLACE FUNCTION public.buy_polla_ticket_secure(
  p_block TEXT,
  p_draw_date DATE,
  p_animalitos TEXT[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_user_id UUID;
  v_wallet_balance NUMERIC(15,2);
  v_ticket_count INT;
  v_ticket_id UUID;
  v_vet_now TIMESTAMPTZ;
  v_vet_time TIME;
  v_vet_date DATE;
  v_price NUMERIC(15,2) := 250.00;
  i INT;
  j INT;
BEGIN
  -- 1. Validar usuario autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  -- 2. Validar parámetro de bloque
  IF p_block NOT IN ('MAÑANA', 'TARDE') THEN
    RETURN jsonb_build_object('success', false, 'error', 'BLOQUE_INVALIDO');
  END IF;

  -- 3. Validar exactamente 6 animalitos
  IF p_animalitos IS NULL OR cardinality(p_animalitos) <> 6 THEN
    RETURN jsonb_build_object('success', false, 'error', 'DEBE_SELECCIONAR_EXACTAMENTE_6_ANIMALITOS');
  END IF;

  -- 4. Validar que no haya códigos duplicados ni fuera de rango ('00' a '76')
  FOR i IN 1..6 LOOP
    IF p_animalitos[i] !~ '^(0[0-9]|[1-6][0-9]|7[0-6])$' THEN
      RETURN jsonb_build_object('success', false, 'error', 'CODIGO_ANIMALITO_INVALIDO: ' || p_animalitos[i]);
    END IF;
    FOR j IN (i + 1)..6 LOOP
      IF p_animalitos[i] = p_animalitos[j] THEN
        RETURN jsonb_build_object('success', false, 'error', 'NO_SE_PERMITEN_ANIMALITOS_REPETIDOS');
      END IF;
    END LOOP;
  END LOOP;

  -- 5. Calcular fecha/hora en zona de Venezuela (UTC-4)
  v_vet_now := NOW() AT TIME ZONE 'America/Caracas';
  v_vet_time := v_vet_now::TIME;
  v_vet_date := v_vet_now::DATE;

  -- 6. Validar ventana de venta server-side
  -- BLOQUE MAÑANA: Cierre 07:55 AM del día del sorteo
  IF p_block = 'MAÑANA' THEN
    IF p_draw_date = v_vet_date AND v_vet_time > '07:55:00'::TIME THEN
      RETURN jsonb_build_object('success', false, 'error', 'VENTA_CERRADA_BLOQUE_MAÑANA');
    ELSIF p_draw_date < v_vet_date THEN
      RETURN jsonb_build_object('success', false, 'error', 'BLOQUE_PASADO');
    END IF;
  -- BLOQUE TARDE: Cierre 13:55 (01:55 PM) del día del sorteo
  ELSIF p_block = 'TARDE' THEN
    IF p_draw_date = v_vet_date AND v_vet_time > '13:55:00'::TIME THEN
      RETURN jsonb_build_object('success', false, 'error', 'VENTA_CERRADA_BLOQUE_TARDE');
    ELSIF p_draw_date < v_vet_date THEN
      RETURN jsonb_build_object('success', false, 'error', 'BLOQUE_PASADO');
    END IF;
  END IF;

  -- 7. Validar límite de 10 pollas por usuario por bloque
  SELECT COUNT(*) INTO v_ticket_count
  FROM public.polla_tickets
  WHERE user_id = v_user_id
    AND draw_date = p_draw_date
    AND block = p_block;

  IF v_ticket_count >= 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'LIMITE_ALCANZADO_MAX_10_POLLAS_POR_BLOQUE');
  END IF;

  -- 8. Validar y bloquear billetera del usuario
  SELECT balance INTO v_wallet_balance
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF v_wallet_balance IS NULL OR v_wallet_balance < v_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'SALDO_INSUFICIENTE_REQUIERE_250_BS');
  END IF;

  -- 9. Descontar 250 Bs de la billetera
  UPDATE public.wallets
  SET balance = balance - v_price,
      updated_at = NOW()
  WHERE user_id = v_user_id;

  -- 10. Registrar movimiento en ledger
  INSERT INTO public.ledger_entries (
    user_id,
    amount,
    entry_type,
    reference_type,
    notes,
    balance_after
  ) VALUES (
    v_user_id,
    -v_price,
    'DEBIT',
    'POLLA_PURCHASE',
    'Compra de Polla Venezolana - Bloque ' || p_block || ' (' || p_draw_date || ')',
    v_wallet_balance - v_price
  );

  -- 11. Crear ticket de Polla
  INSERT INTO public.polla_tickets (
    user_id,
    block,
    draw_date,
    animalitos,
    cost_bs,
    status
  ) VALUES (
    v_user_id,
    p_block,
    p_draw_date,
    p_animalitos,
    v_price,
    'PENDING'
  ) RETURNING id INTO v_ticket_id;

  -- 12. Retornar respuesta exitosa con confirmación explicita
  RETURN jsonb_build_object(
    'success', true,
    'ticket_id', v_ticket_id,
    'balance_after', v_wallet_balance - v_price,
    'message', 'SE DESCONTARON 250 Bs DE TU SALDO.'
  );
END;
$$;



