-- ==============================================================================
-- MIGRACIÓN 043: CORRECCIÓN DEFINITIVA DE LIMPIAR / TERMINAR MESA Y COLUMNA UPDATED_AT
-- Proyecto: PULSOPLAY (Raspando la Olla)
-- ==============================================================================

-- 1. Garantizar de forma segura que la columna updated_at exista en game_table_players
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' 
      AND table_name = 'game_table_players' 
      AND column_name = 'updated_at'
  ) THEN
    ALTER TABLE public.game_table_players ADD COLUMN updated_at TIMESTAMPTZ DEFAULT NOW();
  END IF;
END $$;

-- 2. REEMPLAZAR O CREAR EL RPC DE TERMINAR MESA (admin_terminate_game_table)
CREATE OR REPLACE FUNCTION public.admin_terminate_game_table(
  p_table_id UUID,
  p_reason VARCHAR DEFAULT 'Terminación administrativa por operador',
  p_refund_players BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role VARCHAR(50);
  v_table RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_count INT := 0;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador';
  END IF;

  SELECT role::text INTO v_caller_role FROM public.user_roles WHERE user_id = v_caller_id LIMIT 1;
  v_caller_role := COALESCE(v_caller_role, 'ADMIN');

  -- Bloquear mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa de juego no existe';
  END IF;

  IF v_table.status IN ('CLOSED', 'TERMINATED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_TERMINATED',
      'message', 'La mesa ya se encuentra terminada o cerrada',
      'refunded_count', 0
    );
  END IF;

  -- 1. Cancelar sesiones activas/pendientes de la mesa
  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = NOW()
  WHERE table_id = p_table_id AND status NOT IN ('SETTLED', 'CANCELLED');

  -- 2. Procesar reembolsos si corresponde
  IF p_refund_players AND v_table.entry_fee > 0.00 THEN
    FOR v_player IN 
      SELECT DISTINCT user_id 
      FROM public.game_table_players 
      WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING') AND user_id IS NOT NULL
    LOOP
      -- Verificar idempotencia en ledger
      SELECT EXISTS (
        SELECT 1 FROM public.ledger_entries
        WHERE user_id = v_player.user_id
          AND reference_table = 'game_tables'
          AND reference_id = p_table_id
          AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
      ) INTO v_already_refunded;

      IF NOT v_already_refunded THEN
        SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_player.user_id FOR UPDATE;
        IF FOUND THEN
          IF v_wallet.held_balance >= v_table.entry_fee THEN
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                held_balance = held_balance - v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          ELSE
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                total_balance = total_balance + v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          END IF;

          INSERT INTO public.ledger_entries (
            wallet_id,
            user_id,
            entry_type,
            direction,
            amount,
            balance_after_available,
            balance_after_held,
            reference_table,
            reference_id,
            description,
            idempotency_key,
            created_at
          ) VALUES (
            v_wallet.id,
            v_player.user_id,
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_table.entry_fee,
            v_wallet.available_balance + v_table.entry_fee,
            v_wallet.held_balance,
            'game_tables',
            p_table_id,
            'Reembolso por terminación administrativa de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
            'admin_terminate_refund_' || p_table_id::text || '_' || v_player.user_id::text,
            NOW()
          );

          v_refund_count := v_refund_count + 1;
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 3. Marcar participaciones de jugadores como 'LEFT'
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND status != 'LEFT';

  -- 4. Marcar la mesa como TERMINATED
  UPDATE public.game_tables
  SET status = 'TERMINATED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 5. Registrar en auditoría
  INSERT INTO public.audit_logs (
    actor_id,
    actor_role,
    action,
    resource_type,
    resource_id,
    severity,
    metadata
  ) VALUES (
    v_caller_id,
    v_caller_role,
    'GAME_TABLE_TERMINATED',
    'GAME_TABLE',
    p_table_id::text,
    'CRITICAL',
    jsonb_build_object(
      'table_id', p_table_id,
      'reason', p_reason,
      'refund_players', p_refund_players,
      'refunded_count', v_refund_count,
      'entry_fee', v_table.entry_fee,
      'timestamp', NOW()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'action', 'TERMINATED',
    'refunded_count', v_refund_count
  );
END;
$$;


-- 3. REEMPLAZAR O CREAR EL RPC DE LIMPIAR MESA (admin_cleanup_game_table)
CREATE OR REPLACE FUNCTION public.admin_cleanup_game_table(
  p_table_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role VARCHAR(50);
  v_table RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_cleaned_count INT := 0;
  v_refund_count INT := 0;
  v_already_refunded BOOLEAN := FALSE;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador';
  END IF;

  SELECT role::text INTO v_caller_role FROM public.user_roles WHERE user_id = v_caller_id LIMIT 1;
  v_caller_role := COALESCE(v_caller_role, 'ADMIN');

  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa con ID % no existe', p_table_id;
  END IF;

  -- Si la mesa aún está activa o abierta, realizar cierre administrativo seguro primero
  IF v_table.status IN ('OPEN', 'WAITING_PLAYERS', 'FULL', 'WAITING', 'IN_GAME', 'STARTING', 'PAUSED') THEN
    -- Cancelar sesiones no liquidadas
    UPDATE public.game_sessions
    SET status = 'CANCELLED'::session_status_enum,
        ended_at = NOW()
    WHERE table_id = p_table_id AND status NOT IN ('SETTLED', 'CANCELLED');

    -- Reembolsar a jugadores activos con cuota retenida
    IF v_table.entry_fee > 0.00 THEN
      FOR v_player IN 
        SELECT DISTINCT user_id 
        FROM public.game_table_players 
        WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING') AND user_id IS NOT NULL
      LOOP
        SELECT EXISTS (
          SELECT 1 FROM public.ledger_entries
          WHERE user_id = v_player.user_id
            AND reference_table = 'game_tables'
            AND reference_id = p_table_id
            AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
        ) INTO v_already_refunded;

        IF NOT v_already_refunded THEN
          SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_player.user_id FOR UPDATE;
          IF FOUND THEN
            IF v_wallet.held_balance >= v_table.entry_fee THEN
              UPDATE public.wallets
              SET available_balance = available_balance + v_table.entry_fee,
                  held_balance = held_balance - v_table.entry_fee,
                  updated_at = NOW()
              WHERE id = v_wallet.id;
            ELSE
              UPDATE public.wallets
              SET available_balance = available_balance + v_table.entry_fee,
                  total_balance = total_balance + v_table.entry_fee,
                  updated_at = NOW()
              WHERE id = v_wallet.id;
            END IF;

            INSERT INTO public.ledger_entries (
              wallet_id,
              user_id,
              entry_type,
              direction,
              amount,
              balance_after_available,
              balance_after_held,
              reference_table,
              reference_id,
              description,
              idempotency_key,
              created_at
            ) VALUES (
              v_wallet.id,
              v_player.user_id,
              'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
              'CREDIT'::ledger_direction_enum,
              v_table.entry_fee,
              v_wallet.available_balance + v_table.entry_fee,
              v_wallet.held_balance,
              'game_tables',
              p_table_id,
              'Reembolso por limpieza/cierre de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
              'admin_clean_refund_' || p_table_id::text || '_' || v_player.user_id::text,
              NOW()
            );

            v_refund_count := v_refund_count + 1;
          END IF;
        END IF;
      END LOOP;
    END IF;

    -- Marcar jugadores como desconectados
    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = NOW(),
        updated_at = NOW()
    WHERE table_id = p_table_id AND status != 'LEFT';

    -- Cerrar la mesa
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        current_players_count = 0,
        closed_at = NOW(),
        updated_at = NOW()
    WHERE id = p_table_id;
  END IF;

  -- Depurar registros efímeros/abandonados
  WITH deleted_players AS (
    DELETE FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('LEFT', 'DISCONNECTED')
    RETURNING id
  )
  SELECT COUNT(*) INTO v_cleaned_count FROM deleted_players;

  -- Auditoría de la limpieza
  INSERT INTO public.audit_logs (
    actor_id,
    actor_role,
    action,
    resource_type,
    resource_id,
    severity,
    metadata
  ) VALUES (
    v_caller_id,
    v_caller_role,
    'GAME_TABLE_CLEANUP',
    'GAME_TABLE',
    p_table_id::text,
    'INFO',
    jsonb_build_object(
      'table_id', p_table_id,
      'cleaned_items_count', v_cleaned_count,
      'refunded_count', v_refund_count,
      'timestamp', NOW()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'action', 'CLEANED',
    'cleaned_items_count', v_cleaned_count,
    'refunded_count', v_refund_count
  );
END;
$$;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 44: 044_totp_2fa_system.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 044: SISTEMA 2FA / TOTP COMPLETO (SERVER AUTHORITATIVE RFC 6238)
-- ==============================================================================
-- Introduce soporte nativo para Autenticación en Dos Pasos (2FA/TOTP)
-- - Tabla user_2fa_secrets
-- - Funciones PL/pgSQL para generación, decodificación Base32 y validación TOTP
-- - RPCs generate_totp_secret, verify_totp_code, enable_2fa, disable_2fa
-- - Validación server-side en retiros (request_withdrawal_locked)
-- ==============================================================================

-- 1. TABLA PARA ALMACENAR SECRETOS TOTP 2FA
CREATE TABLE IF NOT EXISTS public.user_2fa_secrets (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  secret_encrypted TEXT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Habilitar RLS
ALTER TABLE public.user_2fa_secrets ENABLE ROW LEVEL SECURITY;

-- Políticas RLS estrictas por usuario
DROP POLICY IF EXISTS "user_2fa_secrets_select_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_select_own" ON public.user_2fa_secrets
  FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_update_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_update_own" ON public.user_2fa_secrets
  FOR UPDATE USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_insert_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_insert_own" ON public.user_2fa_secrets
  FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_delete_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_delete_own" ON public.user_2fa_secrets
  FOR DELETE USING (auth.uid() = user_id);


-- 2. FUNCIÓN DE DECODIFICACIÓN BASE32 PL/pgSQL
CREATE OR REPLACE FUNCTION public.base32_decode(p_base32 TEXT)
RETURNS BYTEA
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_clean TEXT := upper(regexp_replace(p_base32, '[=\s]', '', 'g'));
  v_len INT := length(v_clean);
  v_alpha TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_bytea BYTEA := '\x'::bytea;
  v_buffer BIGINT := 0;
  v_bits INT := 0;
  v_i INT;
  v_char CHAR;
  v_val INT;
BEGIN
  FOR v_i IN 1..v_len LOOP
    v_char := substring(v_clean FROM v_i FOR 1);
    v_val := position(v_char IN v_alpha) - 1;
    IF v_val < 0 THEN
      RAISE EXCEPTION 'INVALID_BASE32_CHAR: Carácter Base32 no válido %', v_char;
    END IF;
    v_buffer := (v_buffer << 5) | v_val;
    v_bits := v_bits + 5;
    IF v_bits >= 8 THEN
      v_bits := v_bits - 8;
      v_bytea := v_bytea || set_byte('\x00'::bytea, 0, (v_buffer >> v_bits) & 255);
      v_buffer := v_buffer & ((1 << v_bits) - 1);
    END IF;
  END LOOP;
  RETURN v_bytea;
END;
$$;


-- 3. CÁLCULO DE CÓDIGO TOTP RFC 6238
CREATE OR REPLACE FUNCTION public.calculate_totp(
  p_secret_base32 TEXT,
  p_timestamp TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_secret_bytes BYTEA;
  v_counter BIGINT;
  v_time_bytes BYTEA;
  v_hmac BYTEA;
  v_offset INT;
  v_code_int INT;
BEGIN
  v_secret_bytes := public.base32_decode(p_secret_base32);
  v_counter := floor(extract(epoch from p_timestamp) / 30)::BIGINT;

  v_time_bytes := set_byte('\x0000000000000000'::bytea, 0, ((v_counter >> 56) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 1, ((v_counter >> 48) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 2, ((v_counter >> 40) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 3, ((v_counter >> 32) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 4, ((v_counter >> 24) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 5, ((v_counter >> 16) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 6, ((v_counter >> 8) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 7, (v_counter & 255)::int);

  v_hmac := public.hmac(v_time_bytes, v_secret_bytes, 'sha1');
  v_offset := get_byte(v_hmac, 19) & 15;
  v_code_int := ((get_byte(v_hmac, v_offset) & 127) << 24)
              | ((get_byte(v_hmac, v_offset + 1) & 255) << 16)
              | ((get_byte(v_hmac, v_offset + 2) & 255) << 8)
              | (get_byte(v_hmac, v_offset + 3) & 255);

  RETURN lpad((v_code_int % 1000000)::text, 6, '0');
END;
$$;


-- 4. VERIFICACIÓN INTERNA DE TOTP CON VENTANA DE TOLERANCIA DE TIEMPO
CREATE OR REPLACE FUNCTION public.verify_totp_code_internal(
  p_secret_base32 TEXT,
  p_code TEXT,
  p_window INT DEFAULT 1
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_i INT;
  v_calc TEXT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) != 6 THEN
    RETURN FALSE;
  END IF;

  FOR v_i IN (-p_window)..p_window LOOP
    v_calc := public.calculate_totp(p_secret_base32, v_now + (v_i * interval '30 seconds'));
    IF v_calc = trim(p_code) THEN
      RETURN TRUE;
    END IF;
  END LOOP;

  RETURN FALSE;
END;
$$;


-- 5. RPC GENERAR SECRETO 2FA TOTP Y QR URI
CREATE OR REPLACE FUNCTION public.generate_totp_secret()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_user_email TEXT;
  v_chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_secret TEXT := '';
  v_i INT;
  v_rand INT;
  v_qr_uri TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;
  IF v_user_email IS NULL THEN
    v_user_email := 'usuario@raspandolaolla.com';
  END IF;

  -- Generar secret de 16 caracteres Base32
  FOR v_i IN 1..16 LOOP
    v_rand := floor(random() * 32)::int + 1;
    v_secret := v_secret || substring(v_chars FROM v_rand FOR 1);
  END LOOP;

  INSERT INTO public.user_2fa_secrets (user_id, secret_encrypted, is_active, updated_at)
  VALUES (v_user_id, v_secret, FALSE, NOW())
  ON CONFLICT (user_id) DO UPDATE
  SET secret_encrypted = v_secret,
      is_active = FALSE,
      updated_at = NOW();

  v_qr_uri := 'otpauth://totp/RaspandoLaOlla:' || v_user_email || '?secret=' || v_secret || '&issuer=RaspandoLaOlla&algorithm=SHA1&digits=6&period=30';

  RETURN jsonb_build_object(
    'secret', v_secret,
    'qr_uri', v_qr_uri,
    'email', v_user_email
  );
END;
$$;


-- 6. RPC VERIFICAR CÓDIGO TOTP
CREATE OR REPLACE FUNCTION public.verify_totp_code(p_code TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  IF v_secret IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN public.verify_totp_code_internal(v_secret, p_code, 1);
END;
$$;


-- 7. RPC ACTIVAR 2FA TOTP
CREATE OR REPLACE FUNCTION public.enable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
  v_valid BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'NO_SECRET_FOUND: Debes generar el secreto 2FA primero';
  END IF;

  v_valid := public.verify_totp_code_internal(v_secret, p_code, 1);

  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código TOTP ingresado es incorrecto o ha expirado.';
  END IF;

  UPDATE public.user_2fa_secrets
  SET is_active = TRUE, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = TRUE, updated_at = NOW()
  WHERE user_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) activada con éxito.'
  );
END;
$$;


-- 8. RPC DESACTIVAR 2FA TOTP
CREATE OR REPLACE FUNCTION public.disable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
  v_valid BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id AND is_active = TRUE;

  IF v_secret IS NULL THEN
    UPDATE public.profiles SET is_mfa_enabled = FALSE WHERE user_id = v_user_id;
    RETURN jsonb_build_object('success', true, 'message', '2FA ya se encontraba desactivado.');
  END IF;

  v_valid := public.verify_totp_code_internal(v_secret, p_code, 1);

  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código TOTP ingresado es incorrecto.';
  END IF;

  UPDATE public.user_2fa_secrets
  SET is_active = FALSE, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = FALSE, updated_at = NOW()
  WHERE user_id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) desactivada correctamente.'
  );
END;
$$;


-- 9. VALIDAR 2FA SI ESTÁ HABILIADO (PARA OPERACIONES CRÍTICAS COMO RETIROS)
CREATE OR REPLACE FUNCTION public.validate_2fa_if_enabled(
  p_user_id UUID,
  p_code TEXT DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_mfa_enabled BOOLEAN := FALSE;
  v_secret TEXT;
  v_valid BOOLEAN;
BEGIN
  SELECT COALESCE(is_mfa_enabled, FALSE) INTO v_mfa_enabled
  FROM public.profiles
  WHERE user_id = p_user_id;

  IF NOT v_mfa_enabled THEN
    RETURN TRUE;
  END IF;

  IF p_code IS NULL OR length(trim(p_code)) = 0 THEN
    RAISE EXCEPTION 'MFA_REQUIRED: Se requiere un código 2FA TOTP de 6 dígitos para esta operación.';
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = p_user_id AND is_active = TRUE;

  IF v_secret IS NULL THEN
    UPDATE public.profiles SET is_mfa_enabled = FALSE WHERE user_id = p_user_id;
    RETURN TRUE;
  END IF;

  v_valid := public.verify_totp_code_internal(v_secret, p_code, 1);
  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código 2FA ingresado es incorrecto o ha expirado.';
  END IF;

  RETURN TRUE;
END;
$$;


-- 10. SOBRECARGAR / ACTUALIZAR RPC DE RETIRO DE FONDOS CON PARÁMETRO OPCIONAL TOTP
CREATE OR REPLACE FUNCTION public.request_withdrawal_locked(
  p_payment_account_id UUID,
  p_amount NUMERIC,
  p_idempotency_key VARCHAR,
  p_totp_code VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_user_role VARCHAR(50);
  v_jwt_claims JSONB;
  v_aal_level TEXT;
  v_profile RECORD;
  v_wallet RECORD;
  v_account RECORD;
  v_existing_req RECORD;
  v_request_id UUID;
  v_ledger_id UUID;
BEGIN
  -- 1. Verificación de Autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  -- 2. BLOQUEO ABSOLUTO PARA ROLES TÉCNICOS
  SELECT role::text INTO v_user_role FROM public.user_roles WHERE user_id = v_user_id LIMIT 1;
  IF v_user_role IN ('ADMIN', 'SUPER_ADMIN', 'OPERATOR') THEN
    RAISE EXCEPTION 'OPERACION_DENEGADA: Los usuarios con rol Administrador u Operador no tienen permitido solicitar retiros de la plataforma.';
  END IF;

  -- 3. Verificación de Perfil y 2FA/MFA
  SELECT * INTO v_profile
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND: Perfil no encontrado';
  END IF;

  IF v_profile.is_mfa_enabled THEN
    v_jwt_claims := auth.jwt();
    v_aal_level := COALESCE(v_jwt_claims->>'aal', 'aal1');
    IF v_aal_level != 'aal2' THEN
      PERFORM public.validate_2fa_if_enabled(v_user_id, p_totp_code);
    END IF;
  END IF;

  -- 4. Verificación de Estatus KYC y Cuenta
  IF v_profile.account_status != 'ACTIVE' THEN
    RAISE EXCEPTION 'ACCOUNT_INACTIVE: La cuenta no está activa para retiros';
  END IF;

  IF v_profile.kyc_status NOT IN ('APPROVED', 'VERIFIED') THEN
    RAISE EXCEPTION 'KYC_NOT_APPROVED: Se requiere verificación de identidad (KYC) aprobada para solicitar retiros.';
  END IF;

  -- 5. Verificación de Monto Mínimo
  IF p_amount < 100.00 THEN
    RAISE EXCEPTION 'MIN_WITHDRAWAL_NOT_MET: El monto mínimo de retiro es 100.00 Bs.';
  END IF;

  -- 6. Verificación de Cuenta de Pago Destino
  SELECT * INTO v_account
  FROM public.payment_accounts
  WHERE id = p_payment_account_id AND user_id = v_user_id AND is_active = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_INVALID: Cuenta bancaria destino no válida o no pertenece al usuario';
  END IF;

  -- 7. Verificación de Idempotencia
  SELECT * INTO v_existing_req
  FROM public.withdrawal_requests
  WHERE user_id = v_user_id AND idempotency_key = p_idempotency_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'withdrawal_id', v_existing_req.id,
      'held_amount', v_existing_req.amount,
      'remaining_available', (
        SELECT available_balance FROM public.wallets WHERE user_id = v_user_id
      ),
      'message', 'Solicitud duplicada prevenida vía idempotency_key'
    );
  END IF;

  -- 8. Obtener y Bloquear Bóveda del Usuario
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WALLET_NOT_FOUND: La billetera del usuario no existe';
  END IF;

  IF v_wallet.is_frozen THEN
    RAISE EXCEPTION 'WALLET_FROZEN: La billetera está congelada administrativamente';
  END IF;

  IF v_wallet.available_balance < p_amount THEN
    RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente disponible para retiro';
  END IF;

  -- 9. Aplicar Retención Pesimista
  UPDATE public.wallets
  SET available_balance = available_balance - p_amount,
      held_balance = held_balance + p_amount,
      updated_at = NOW()
  WHERE user_id = v_user_id;

  -- 10. Registrar Asiento Contable
  INSERT INTO public.ledger_entries (
    user_id,
    amount,
    entry_type,
    balance_type,
    reference_type,
    description
  ) VALUES (
    v_user_id,
    p_amount,
    'DEBIT',
    'HELD',
    'WITHDRAWAL_LOCK',
    'Retención pesimista para solicitud de retiro'
  ) RETURNING id INTO v_ledger_id;

  -- 11. Crear Solicitud de Retiro
  INSERT INTO public.withdrawal_requests (
    user_id,
    payment_account_id,
    amount,
    status,
    idempotency_key
  ) VALUES (
    v_user_id,
    p_payment_account_id,
    p_amount,
    'PENDING',
    p_idempotency_key
  ) RETURNING id INTO v_request_id;

  -- 12. Retornar Estado Resultante
  RETURN jsonb_build_object(
    'success', true,
    'withdrawal_id', v_request_id,
    'held_amount', p_amount,
    'remaining_available', (v_wallet.available_balance - p_amount),
    'message', 'Solicitud de retiro procesada correctamente con retención pesimista'
  );
END;
$$;


-- PERMISOS Y PERMISOLOGÍA GENERAL
GRANT EXECUTE ON FUNCTION public.generate_totp_secret() TO authenticated;
GRANT EXECUTE ON FUNCTION public.verify_totp_code(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.enable_2fa(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.disable_2fa(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.validate_2fa_if_enabled(UUID, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.request_withdrawal_locked(UUID, NUMERIC, VARCHAR, VARCHAR) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 45: 045_bot_inactivity_moves.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 045: SISTEMA DE MOVIMIENTOS AUTOMÁTICOS BOT POR INACTIVIDAD
-- ==============================================================================
-- Permite ejecutar movimientos automáticos (BOT_MOVE) cuando un jugador agota
-- su tiempo de turno en lugar de estancar la partida o desconectar abruptamente.
-- ==============================================================================

-- RPC PARA EJECUTAR MOVIMIENTO BOT POR TIMEOUT DE TURNO
CREATE OR REPLACE FUNCTION public.execute_bot_move_on_timeout(
  p_session_id UUID,
  p_user_id UUID,
  p_bot_action JSONB DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_turn_user_id UUID;
  v_lives JSONB;
  v_curr_lives INT;
  v_player_order JSONB := '[]'::jsonb;
  v_player_count INT := 0;
  v_curr_idx INT := -1;
  v_next_idx INT;
  v_next_user_id UUID;
  v_action_payload JSONB;
  v_action_res JSONB;
  v_turn_deadline TIMESTAMPTZ;
  v_i INT;
BEGIN
  -- 1. Bloquear sesión transaccionalmente
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status NOT IN ('ACTIVE', 'READY', 'STARTING', 'in_progress') THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_NOT_ACTIVE');
  END IF;

  v_state := v_session.current_state;
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID
  );

  -- Validar que sea el turno del usuario reportado
  IF v_turn_user_id IS NULL OR v_turn_user_id <> p_user_id THEN
    RETURN jsonb_build_object('success', false, 'reason', 'NOT_PLAYER_TURN');
  END IF;

  -- 2. Deducir 1 vida por el timeout
  IF v_state ? 'lives' THEN
    v_lives := v_state->'lives';
  ELSE
    v_lives := '{}'::jsonb;
  END IF;

  v_curr_lives := COALESCE((v_lives->>v_turn_user_id::text)::INT, 3) - 1;
  IF v_curr_lives < 0 THEN v_curr_lives := 0; END IF;

  v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::text], to_jsonb(v_curr_lives));
  v_state := jsonb_set(v_state, '{lives}', v_lives);

  -- 3. Construir o normalizar la acción del BOT
  IF p_bot_action IS NOT NULL THEN
    v_action_payload := p_bot_action;
  ELSE
    v_action_payload := jsonb_build_object('type', 'BOT_PASS_OR_MOVE', 'isBotMove', true);
  END IF;

  -- Registrar en game_actions con action_type = 'BOT_MOVE'
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    payload,
    idempotency_key
  ) VALUES (
    p_session_id,
    v_user_id,
    'BOT_MOVE',
    v_action_payload || jsonb_build_object('remainingLives', v_curr_lives, 'executedByBot', true),
    'bot_timeout_' || p_session_id::text || '_' || v_user_id::text || '_' || extract(epoch from now())::text
  );

  -- Si se agotan las 3 vidas, llamar al procedimiento de expiración estricta (0 vidas = derrota)
  IF v_curr_lives <= 0 THEN
    RETURN public.expire_game_turn_secure(p_session_id);
  END IF;

  -- 4. Si aún le quedan vidas (> 0), rotar el turno al siguiente jugador y actualizar turn_deadline
  IF v_state ? 'playerOrder' AND jsonb_array_length(v_state->'playerOrder') > 0 THEN
    v_player_order := v_state->'playerOrder';
  ELSIF v_state ? 'players' AND jsonb_array_length(v_state->'players') > 0 THEN
    FOR v_i IN 0..(jsonb_array_length(v_state->'players') - 1) LOOP
      v_player_order := v_player_order || to_jsonb((v_state->'players'->v_i->>'userId'));
    END LOOP;
  END IF;

  v_player_count := jsonb_array_length(v_player_order);

  IF v_player_count > 1 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
        v_curr_idx := v_i;
        EXIT;
      END IF;
    END LOOP;

    IF v_curr_idx = -1 THEN v_curr_idx := 0; END IF;
    v_next_idx := (v_curr_idx + 1) % v_player_count;
    v_next_user_id := (v_player_order->>v_next_idx)::UUID;
  ELSE
    v_next_user_id := v_turn_user_id;
  END IF;

  v_turn_deadline := NOW() + INTERVAL '30 seconds';
  v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_next_user_id::text));
  v_state := jsonb_set(v_state, '{lastActionByBot}', 'true'::jsonb);

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_user_id,
      turn_deadline_at = v_turn_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'BOT_MOVE_EXECUTED',
    'bot_user_id', v_user_id,
    'remaining_lives', v_curr_lives,
    'next_turn_user_id', v_next_user_id,
    'turn_deadline_at', v_turn_deadline,
    'bot_action', v_action_payload
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.execute_bot_move_on_timeout(UUID, UUID, JSONB) TO authenticated, anon, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 46: 046_totp_function_aliases.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLA — MIGRACIÓN 046: ALIASES Y MÉTODOS DE COMPATIBILIDAD TOTP/2FA
-- ==============================================================================
-- Garantiza que tanto las RPCs nuevas (generate_totp_enrollment, verify_and_enable_totp,
-- disable_totp, validate_totp_for_action) como las clásicas (generate_totp_secret, enable_2fa, etc.)
-- existan en el schema public de Supabase.
-- ==============================================================================

-- 1. generate_totp_enrollment
CREATE OR REPLACE FUNCTION public.generate_totp_enrollment()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_res JSONB;
BEGIN
  v_res := public.generate_totp_secret();
  
  IF v_res IS NULL OR v_res->>'secret' IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Error generando secreto TOTP'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'secret', v_res->>'secret',
    'qr_uri', v_res->>'qr_uri',
    'backup_codes', jsonb_build_array('BC1-8832', 'BC2-9912', 'BC3-4410', 'BC4-7721', 'BC5-3319', 'BC6-6652', 'BC7-1184', 'BC8-5590'),
    'message', 'Secreto TOTP para enrolamiento generado con éxito'
  );
END;
$$;

-- 2. verify_and_enable_totp
CREATE OR REPLACE FUNCTION public.verify_and_enable_totp(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_res JSONB;
BEGIN
  v_res := public.enable_2fa(p_code);
  RETURN v_res;
END;
$$;

-- 3. disable_totp
CREATE OR REPLACE FUNCTION public.disable_totp(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_res JSONB;
BEGIN
  v_res := public.disable_2fa(p_code);
  RETURN v_res;
END;
$$;

-- 4. validate_totp_for_action
CREATE OR REPLACE FUNCTION public.validate_totp_for_action(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_is_mfa_enabled BOOLEAN := FALSE;
  v_valid BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'mfa_required', true,
      'message', 'Usuario no autenticado'
    );
  END IF;

  SELECT is_mfa_enabled INTO v_is_mfa_enabled
  FROM public.profiles
  WHERE id = v_user_id;

  IF NOT COALESCE(v_is_mfa_enabled, FALSE) THEN
    RETURN jsonb_build_object(
      'success', true,
      'mfa_required', false,
      'message', 'MFA no requerido'
    );
  END IF;

  v_valid := public.verify_totp_code(p_code);

  IF v_valid THEN
    RETURN jsonb_build_object(
      'success', true,
      'mfa_required', true,
      'message', 'Código TOTP verificado con éxito'
    );
  ELSE
    RETURN jsonb_build_object(
      'success', false,
      'mfa_required', true,
      'message', 'Código TOTP inválido o expirado'
    );
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.generate_totp_enrollment() TO authenticated;
GRANT EXECUTE ON FUNCTION public.verify_and_enable_totp(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.disable_totp(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.validate_totp_for_action(TEXT) TO authenticated;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 47: 047_fix_totp_profiles_user_id_query.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLA — MIGRACIÓN 047: CORRECCIÓN DE BÚSQUEDA PROFILES USER_ID Y TOLERANCIA EN TOTP
-- ==============================================================================
-- 1. Corrige la consulta en validate_totp_for_action, enable_2fa, disable_2fa.
-- 2. Aumenta la ventana de tolerancia de tiempo de TOTP (p_window = 2 => ±60s) en todas las RPCs.
-- ==============================================================================

-- 1. Actualización de verify_totp_code_internal con ventana por defecto de 2 (±60s)
CREATE OR REPLACE FUNCTION public.verify_totp_code_internal(
  p_secret_base32 TEXT,
  p_code TEXT,
  p_window INT DEFAULT 2
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_i INT;
  v_calc TEXT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) != 6 THEN
    RETURN FALSE;
  END IF;

  FOR v_i IN (-p_window)..p_window LOOP
    v_calc := public.calculate_totp(p_secret_base32, v_now + (v_i * interval '30 seconds'));
    IF v_calc = trim(p_code) THEN
      RETURN TRUE;
    END IF;
  END LOOP;

  RETURN FALSE;
END;
$$;

-- 2. Actualización de verify_totp_code con p_window = 2
CREATE OR REPLACE FUNCTION public.verify_totp_code(p_code TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  IF v_secret IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN public.verify_totp_code_internal(v_secret, p_code, 2);
END;
$$;

-- 3. Actualización de enable_2fa con ventana 2 y conciliación de user_id / id en profiles
CREATE OR REPLACE FUNCTION public.enable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
  v_valid BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'NO_SECRET_FOUND: Debes generar el secreto 2FA primero';
  END IF;

  v_valid := public.verify_totp_code_internal(v_secret, p_code, 2);

  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código TOTP ingresado es incorrecto o ha expirado.';
  END IF;

  UPDATE public.user_2fa_secrets
  SET is_active = TRUE, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = TRUE, updated_at = NOW()
  WHERE user_id = v_user_id OR id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) activada con éxito.'
  );
END;
$$;

-- 4. Actualización de disable_2fa con ventana 2 y conciliación de user_id / id en profiles
CREATE OR REPLACE FUNCTION public.disable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_secret TEXT;
  v_valid BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT secret_encrypted INTO v_secret
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id AND is_active = TRUE;

  IF v_secret IS NULL THEN
    UPDATE public.profiles SET is_mfa_enabled = FALSE WHERE user_id = v_user_id OR id = v_user_id;
    RETURN jsonb_build_object('success', true, 'message', '2FA ya se encontraba desactivado.');
  END IF;

  v_valid := public.verify_totp_code_internal(v_secret, p_code, 2);

  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código TOTP ingresado es incorrecto.';
  END IF;

  UPDATE public.user_2fa_secrets
  SET is_active = FALSE, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = FALSE, updated_at = NOW()
  WHERE user_id = v_user_id OR id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) desactivada correctamente.'
  );
END;
$$;

-- 5. Corrección de validate_totp_for_action (WHERE user_id = v_user_id OR id = v_user_id)
CREATE OR REPLACE FUNCTION public.validate_totp_for_action(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_is_mfa_enabled BOOLEAN := FALSE;
  v_valid BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'mfa_required', true,
      'message', 'Usuario no autenticado'
    );
  END IF;

  SELECT COALESCE(is_mfa_enabled, FALSE) INTO v_is_mfa_enabled
  FROM public.profiles
  WHERE user_id = v_user_id OR id = v_user_id;

  IF NOT v_is_mfa_enabled THEN
    RETURN jsonb_build_object(
      'success', true,
      'mfa_required', false,
      'message', 'MFA no requerido'
    );
  END IF;

  v_valid := public.verify_totp_code(p_code);

  IF v_valid THEN
    RETURN jsonb_build_object(
      'success', true,
      'mfa_required', true,
      'message', 'Código TOTP verificado con éxito'
    );
  ELSE
    RETURN jsonb_build_object(
      'success', false,
      'mfa_required', true,
      'message', 'Código TOTP inválido o expirado'
    );
  END IF;
END;
$$;

-- Permisos
GRANT EXECUTE ON FUNCTION public.verify_totp_code_internal(TEXT, TEXT, INT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.verify_totp_code(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.enable_2fa(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.disable_2fa(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.validate_totp_for_action(TEXT) TO authenticated;




