-- MIGRACIÓN 53: 051_audit_system_test_suite.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 051: SISTEMA DE AUDITORÍA Y TEST DEL SISTEMA (Raspando La Olla)
-- ==============================================================================
-- Proporciona funciones RPC para inspección y limpieza segura de datos de prueba (AUDIT_TEST)
-- con control de roles (OPERATOR, ADMIN, SUPER_ADMIN) preservando intactos todos los registros reales.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.admin_get_audit_test_summary(
  p_test_prefix VARCHAR DEFAULT 'AUDIT_TEST'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_test_tables_count INT := 0;
  v_test_actions_count INT := 0;
  v_test_tickets_count INT := 0;
  v_test_logs_count INT := 0;
  v_real_tables_count INT := 0;
  v_real_wallets_count INT := 0;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador';
  END IF;

  SELECT COUNT(*) INTO v_test_tables_count
  FROM public.game_tables
  WHERE name LIKE p_test_prefix || '%' OR invite_code LIKE 'AUDIT%';

  SELECT COUNT(*) INTO v_test_actions_count
  FROM public.game_actions ga
  JOIN public.game_tables gt ON ga.table_id = gt.id
  WHERE gt.name LIKE p_test_prefix || '%';

  SELECT COUNT(*) INTO v_test_tickets_count
  FROM public.polla_tickets
  WHERE transaction_id LIKE p_test_prefix || '%';

  SELECT COUNT(*) INTO v_test_logs_count
  FROM public.audit_logs
  WHERE action LIKE p_test_prefix || '%';

  SELECT COUNT(*) INTO v_real_tables_count
  FROM public.game_tables
  WHERE (name IS NULL OR name NOT LIKE p_test_prefix || '%');

  SELECT COUNT(*) INTO v_real_wallets_count
  FROM public.wallets;

  RETURN jsonb_build_object(
    'success', true,
    'test_prefix', p_test_prefix,
    'test_tables_count', v_test_tables_count,
    'test_actions_count', v_test_actions_count,
    'test_tickets_count', v_test_tickets_count,
    'test_logs_count', v_test_logs_count,
    'real_tables_count', v_real_tables_count,
    'real_wallets_count', v_real_wallets_count
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_cleanup_audit_test_data(
  p_test_prefix VARCHAR DEFAULT 'AUDIT_TEST'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role VARCHAR(50);
  v_deleted_tables INT := 0;
  v_deleted_actions INT := 0;
  v_deleted_tickets INT := 0;
  v_deleted_logs INT := 0;
  v_remaining_real_tables INT := 0;
  v_remaining_real_wallets INT := 0;
  v_test_table_ids UUID[];
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador';
  END IF;

  SELECT role::text INTO v_caller_role FROM public.user_roles WHERE user_id = v_caller_id LIMIT 1;

  SELECT ARRAY_AGG(id) INTO v_test_table_ids
  FROM public.game_tables
  WHERE name LIKE p_test_prefix || '%' OR invite_code LIKE 'AUDIT%';

  IF v_test_table_ids IS NOT NULL AND ARRAY_LENGTH(v_test_table_ids, 1) > 0 THEN
    WITH deleted_a AS (
      DELETE FROM public.game_actions
      WHERE table_id = ANY(v_test_table_ids)
      RETURNING id
    )
    SELECT COUNT(*) INTO v_deleted_actions FROM deleted_a;

    DELETE FROM public.game_table_players
    WHERE table_id = ANY(v_test_table_ids);

    DELETE FROM public.game_sessions
    WHERE table_id = ANY(v_test_table_ids);

    WITH deleted_t AS (
      DELETE FROM public.game_tables
      WHERE id = ANY(v_test_table_ids)
      RETURNING id
    )
    SELECT COUNT(*) INTO v_deleted_tables FROM deleted_t;
  END IF;

  WITH deleted_p AS (
    DELETE FROM public.polla_tickets
    WHERE transaction_id LIKE p_test_prefix || '%'
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_tickets FROM deleted_p;

  WITH deleted_l AS (
    DELETE FROM public.audit_logs
    WHERE action LIKE p_test_prefix || '%'
    RETURNING id
  )
  SELECT COUNT(*) INTO v_deleted_logs FROM deleted_l;

  INSERT INTO public.audit_logs (user_id, action, entity_type, details)
  VALUES (
    v_caller_id,
    'ADMIN_CLEANUP_AUDIT_TEST_DATA',
    'SYSTEM',
    jsonb_build_object(
      'prefix', p_test_prefix,
      'deleted_tables', v_deleted_tables,
      'deleted_actions', v_deleted_actions,
      'deleted_tickets', v_deleted_tickets,
      'deleted_logs', v_deleted_logs,
      'executor_role', v_caller_role
    )
  );

  SELECT COUNT(*) INTO v_remaining_real_tables
  FROM public.game_tables;

  SELECT COUNT(*) INTO v_remaining_real_wallets
  FROM public.wallets;

  RETURN jsonb_build_object(
    'success', true,
    'deleted_tables', v_deleted_tables,
    'deleted_actions', v_deleted_actions,
    'deleted_tickets', v_deleted_tickets,
    'deleted_logs', v_deleted_logs,
    'remaining_real_tables', v_remaining_real_tables,
    'remaining_real_wallets', v_remaining_real_wallets,
    'message', 'Limpieza de datos de auditoría completada con éxito. Todos los datos reales, cuentas de usuario, monederos y partidas normales se preservaron intactos.'
  );
END;
$$;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 54: 052_fix_duplicate_players_and_problem_tables.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 052: PREVENCIÓN DE JUGADORES DUPLICADOS, LIMPIEZA DE MESAS BLOQUEADAS
-- Y CORRECCIÓN DE METRICAS DEL DASHBOARD (HTTP 400)
-- Proyecto: PULSOPLAY (Raspando la Olla)
-- ==============================================================================

-- 1. CORRECCIÓN DE HTTP 400 EN get_admin_dashboard_metrics()
-- Se agregan conversiones explicitas status::text para evitar fallos por valores ENUM
CREATE OR REPLACE FUNCTION public.get_admin_dashboard_metrics()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_registered_users INT := 0;
  v_active_users INT := 0;
  v_connected_users INT := 0;
  v_active_tables INT := 0;
  v_active_matches INT := 0;
  v_finished_matches INT := 0;
  v_pending_deposits INT := 0;
  v_pending_withdrawals INT := 0;
  v_pending_tickets INT := 0;
  v_total_volume NUMERIC := 0;
  v_total_prizes NUMERIC := 0;
  v_total_fees NUMERIC := 0;
  v_security_alerts INT := 0;
BEGIN
  -- Limpieza de presencias inactivas
  PERFORM public.cleanup_inactive_user_presence(2);

  -- Conteo de usuarios
  SELECT COUNT(*) INTO v_registered_users FROM public.profiles;
  SELECT COUNT(*) INTO v_connected_users FROM public.profiles WHERE is_online = TRUE AND last_seen_at >= (NOW() - INTERVAL '2 minutes');
  SELECT COUNT(*) INTO v_active_users FROM public.profiles WHERE last_seen_at >= (NOW() - INTERVAL '24 hours');

  -- Conteo de mesas con cast seguro status::text (Evita HTTP 400 por enum invalido)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_tables') THEN
    SELECT COUNT(*) INTO v_active_tables 
    FROM public.game_tables 
    WHERE status::text IN ('OPEN', 'WAITING_PLAYERS', 'FULL', 'WAITING', 'IN_GAME', 'STARTING', 'PLAYING', 'ACTIVE');
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_sessions') THEN
    SELECT COUNT(*) INTO v_active_matches FROM public.game_sessions WHERE status::text IN ('IN_PROGRESS', 'WAITING', 'STARTING', 'ACTIVE', 'PAUSED');
    SELECT COUNT(*) INTO v_finished_matches FROM public.game_sessions WHERE status::text IN ('SETTLED', 'COMPLETED', 'FINISHED');
  END IF;

  -- Solicitudes pendientes
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'deposit_requests') THEN
    SELECT COUNT(*) INTO v_pending_deposits FROM public.deposit_requests WHERE status::text = 'PENDING';
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'withdrawal_requests') THEN
    SELECT COUNT(*) INTO v_pending_withdrawals FROM public.withdrawal_requests WHERE status::text = 'PENDING';
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'support_tickets') THEN
    SELECT COUNT(*) INTO v_pending_tickets FROM public.support_tickets WHERE status::text IN ('OPEN', 'IN_PROGRESS');
  END IF;

  -- Volúmenes y comisiones
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_settlements') THEN
    SELECT COALESCE(SUM(gross_pool), 0), COALESCE(SUM(prize_pool), 0), COALESCE(SUM(platform_fee), 0)
    INTO v_total_volume, v_total_prizes, v_total_fees
    FROM public.game_settlements;
  END IF;

  -- Alertas de seguridad
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'audit_logs') THEN
    SELECT COUNT(*) INTO v_security_alerts 
    FROM public.audit_logs 
    WHERE severity::text IN ('CRITICAL', 'SECURITY_ALERT') AND created_at >= (NOW() - INTERVAL '7 days');
  END IF;

  RETURN jsonb_build_object(
    'registeredUsersCount', v_registered_users,
    'activeUsersCount', GREATEST(v_active_users, v_connected_users),
    'connectedUsersCount', v_connected_users,
    'activeTablesCount', v_active_tables,
    'activeMatchesCount', v_active_matches,
    'finishedMatchesCount', v_finished_matches,
    'pendingDepositsCount', v_pending_deposits,
    'pendingWithdrawalsCount', v_pending_withdrawals,
    'pendingTicketsCount', v_pending_tickets,
    'totalVolumePlayed', v_total_volume,
    'totalPrizesAwarded', v_total_prizes,
    'totalServiceFeesCollected', v_total_fees,
    'securityAlertsCount', v_security_alerts
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_admin_dashboard_metrics() TO authenticated, service_role;


-- 2. LIMPIEZA DE JUGADORES DUPLICADOS EXISTENTES EN BASE DE DATOS
-- Marcar como 'LEFT' los registros duplicados de un mismo usuario en una misma mesa manteniéndose sólo el más reciente.
WITH ranked_players AS (
  SELECT id, table_id, user_id, seat_number, status,
         ROW_NUMBER() OVER (
           PARTITION BY table_id, user_id 
           ORDER BY joined_at DESC, created_at DESC, id DESC
         ) as rank_num
  FROM public.game_table_players
  WHERE status IN ('JOINED', 'READY', 'PLAYING') AND user_id IS NOT NULL
)
UPDATE public.game_table_players
SET status = 'LEFT'::player_table_status_enum,
    left_at = NOW(),
    updated_at = NOW()
WHERE id IN (SELECT id FROM ranked_players WHERE rank_num > 1);


-- 3. BINDING DE ÍNDICES ÚNICOS PARCIALES PARA GARANTIZAR REGLA: UN USUARIO = UN SOLO ASIENTO POR MESA
-- Esto impide físicamente que el mismo usuario o el mismo asiento contenga más de un registro activo simultáneo.
DROP INDEX IF EXISTS public.idx_uq_active_player_per_table;
CREATE UNIQUE INDEX idx_uq_active_player_per_table 
ON public.game_table_players (table_id, user_id) 
WHERE status IN ('JOINED', 'READY', 'PLAYING');

DROP INDEX IF EXISTS public.idx_uq_active_seat_per_table;
CREATE UNIQUE INDEX idx_uq_active_seat_per_table 
ON public.game_table_players (table_id, seat_number) 
WHERE status IN ('JOINED', 'READY', 'PLAYING');


-- 4. RPC MEJORADO: join_table_transaction CON PROTECCIÓN ANTI-DUPLICACIÓN Y CONCURRENCIA
CREATE OR REPLACE FUNCTION public.join_table_transaction(
  p_table_id UUID,
  p_seat_number SMALLINT,
  p_idempotency_key VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile RECORD;
  v_table RECORD;
  v_wallet RECORD;
  v_existing_active_player RECORD;
  v_existing_left_player RECORD;
  v_active_players_count INT;
  v_ledger_id UUID;
  v_player_id UUID;
BEGIN
  -- 1. Verificación de Autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  -- 2. Verificación de Estado de Cuenta del Perfil
  SELECT * INTO v_profile
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND: Perfil de usuario no registrado';
  END IF;

  IF v_profile.account_status != 'ACTIVE' THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Cuenta no habilitada para unirse a mesas (estado: %)', v_profile.account_status;
  END IF;

  -- 3. BLOQUEO PESIMISTA DE LA MESA Y REVISIÓN DE CONCURRENCIA
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  IF v_table.status NOT IN ('OPEN', 'WAITING', 'WAITING_PLAYERS') THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La mesa no está disponible para unirse (estado: %)', v_table.status;
  END IF;

  IF v_table.expires_at <= NOW() THEN
    RAISE EXCEPTION 'TABLE_EXPIRED: La mesa ha expirado';
  END IF;

  -- 4. VERIFICAR SI EL JUGADOR YA TIENE UN ASIENTO ACTIVO EN ESTA MESA (UN USUARIO = UN ASIENTO)
  SELECT * INTO v_existing_active_player
  FROM public.game_table_players
  WHERE table_id = p_table_id 
    AND user_id = v_user_id 
    AND status IN ('JOINED', 'READY', 'PLAYING');

  IF FOUND THEN
    -- Retornar el asiento existente. ¡NUNCA CREAR UN SEGUNDO ASIENTO!
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'already_seated', true,
      'player_id', v_existing_active_player.id,
      'table_id', p_table_id,
      'seat_number', v_existing_active_player.seat_number,
      'message', 'El jugador ya ocupa el asiento #' || v_existing_active_player.seat_number || ' en esta mesa.'
    );
  END IF;

  -- 5. VERIFICACIÓN DE LÍMITE DE CAPACIDAD Y ASIENTO SOLICITADO
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  IF v_active_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: La mesa ha alcanzado su capacidad máxima (%/%)', v_active_players_count, v_table.max_players;
  END IF;

  IF p_seat_number < 1 OR p_seat_number > v_table.max_players THEN
    RAISE EXCEPTION 'INVALID_SEAT: Número de asiento fuera de rango permitido (1..%)', v_table.max_players;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.game_table_players 
    WHERE table_id = p_table_id 
      AND seat_number = p_seat_number 
      AND status IN ('JOINED', 'READY', 'PLAYING')
  ) THEN
    RAISE EXCEPTION 'SEAT_TAKEN: El asiento % ya está ocupado', p_seat_number;
  END IF;

  -- 6. APLICACIÓN DE HOLD Y ASIENTO EN LEDGER SI LA MESA TIENE COSTO Y NO TENÍA RETENCIÓN PREVIA
  IF v_table.entry_fee > 0.00 THEN
    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'WALLET_NOT_FOUND: Billetera de usuario no encontrada';
    END IF;

    IF v_wallet.available_balance < v_table.entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo disponible insuficiente (requerido: %, disponible: %)', 
        v_table.entry_fee, v_wallet.available_balance;
    END IF;

    UPDATE public.wallets
    SET 
      available_balance = available_balance - v_table.entry_fee,
      held_balance = held_balance + v_table.entry_fee,
      updated_at = NOW()
    WHERE id = v_wallet.id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_id,
      idempotency_key,
      description,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet.id,
      v_user_id,
      'TABLE_ENTRY_HOLD',
      'HOLD',
      v_table.entry_fee,
      v_wallet.available_balance - v_table.entry_fee,
      v_wallet.held_balance + v_table.entry_fee,
      'game_tables',
      p_table_id,
      p_idempotency_key,
      'Retención de entrada a mesa ' || p_table_id::text || ' asiento ' || p_seat_number::text,
      v_user_id
    );
  END IF;

  -- 7. REUTILIZAR O INSERTAR REGISTRO DEL JUGADOR
  SELECT * INTO v_existing_left_player
  FROM public.game_table_players
  WHERE table_id = p_table_id AND user_id = v_user_id;

  IF FOUND THEN
    -- Reactivar registro previo liberando flag LEFT
    v_player_id := v_existing_left_player.id;
    UPDATE public.game_table_players
    SET 
      seat_number = p_seat_number,
      status = 'JOINED'::player_table_status_enum,
      entry_held_entry_id = COALESCE(v_ledger_id, entry_held_entry_id),
      left_at = NULL,
      updated_at = NOW()
    WHERE id = v_player_id;
  ELSE
    -- Insertar nuevo asiento de jugador
    v_player_id := gen_random_uuid();
    INSERT INTO public.game_table_players (
      id,
      table_id,
      user_id,
      seat_number,
      status,
      entry_held_entry_id
    ) VALUES (
      v_player_id,
      p_table_id,
      v_user_id,
      p_seat_number,
      'JOINED'::player_table_status_enum,
      v_ledger_id
    );
  END IF;

  -- 8. RECONCILIACIÓN ATÓMICA DEL CONTADOR Y ESTADO DE LA MESA
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  UPDATE public.game_tables
  SET 
    current_players_count = v_active_players_count,
    status = CASE 
      WHEN v_active_players_count >= max_players THEN 'FULL'::table_status_enum 
      ELSE 'OPEN'::table_status_enum 
    END,
    updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'player_id', v_player_id,
    'table_id', p_table_id,
    'seat_number', p_seat_number,
    'active_players_count', v_active_players_count
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_table_transaction(UUID, SMALLINT, VARCHAR) TO authenticated, service_role;


-- 5. RPC ADMINISTRATIVO PARA LIMPIEZA SEGURA DE MESAS BLOQUEADAS
-- Reembolsa retenciones activas si la partida no se jugó y limpia referencias sin tocar el historial financiero.
CREATE OR REPLACE FUNCTION public.admin_fix_and_cleanup_problematic_table(
  p_table_id UUID,
  p_reason TEXT DEFAULT 'Limpieza administrativa de mesa con problemas / bloqueada'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role VARCHAR(50);
  v_table RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_count INT := 0;
  v_cleaned_seats_count INT := 0;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador';
  END IF;

  SELECT role::text INTO v_caller_role FROM public.user_roles WHERE user_id = v_caller_id LIMIT 1;
  v_caller_role := COALESCE(v_caller_role, 'ADMIN');

  -- Bloquear la mesa para concurrencia
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'MESA_NO_ENCONTRADA',
      'message', 'La mesa de juego especificada no existe o ya fue eliminada'
    );
  END IF;

  -- 1. Reparar/Marcar como 'LEFT' registros duplicados de jugadores activos en esta mesa
  WITH ranked_players AS (
    SELECT id,
           ROW_NUMBER() OVER (
             PARTITION BY user_id 
             ORDER BY joined_at DESC, created_at DESC, id DESC
           ) as rank_num
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING') AND user_id IS NOT NULL
  )
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum, left_at = NOW(), updated_at = NOW()
  WHERE id IN (SELECT id FROM ranked_players WHERE rank_num > 1);

  -- 2. Procesar reembolsos seguros si la mesa tiene costo y los jugadores tienen dinero retenido
  IF v_table.entry_fee > 0.00 THEN
    FOR v_player IN 
      SELECT DISTINCT user_id 
      FROM public.game_table_players 
      WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING') AND user_id IS NOT NULL
    LOOP
      SELECT EXISTS (
        SELECT 1 FROM public.ledger_entries
        WHERE user_id = v_player.user_id
          AND reference_table = 'game_tables'
          AND reference_id = p_table_id
          AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
      ) INTO v_already_refunded;

      IF NOT v_already_refunded THEN
        SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_player.user_id FOR UPDATE;
        IF FOUND THEN
          IF v_wallet.held_balance >= v_table.entry_fee THEN
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                held_balance = held_balance - v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          ELSE
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                total_balance = total_balance + v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          END IF;

          INSERT INTO public.ledger_entries (
            wallet_id,
            user_id,
            entry_type,
            direction,
            amount,
            balance_after_available,
            balance_after_held,
            reference_table,
            reference_id,
            description,
            idempotency_key,
            created_at
          ) VALUES (
            v_wallet.id,
            v_player.user_id,
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_table.entry_fee,
            v_wallet.available_balance + v_table.entry_fee,
            v_wallet.held_balance,
            'game_tables',
            p_table_id,
            'Reembolso por limpieza de mesa con problemas #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
            'problem_cleanup_refund_' || p_table_id::text || '_' || v_player.user_id::text || '_' || extract(epoch from now())::text,
            NOW()
          );

          v_refund_count := v_refund_count + 1;
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 3. Cancelar sesiones asociadas a esta mesa
  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum, ended_at = NOW()
  WHERE table_id = p_table_id AND status NOT IN ('SETTLED', 'CANCELLED');

  -- 4. Liberar todos los asientos marcándolos como LEFT
  SELECT COUNT(*) INTO v_cleaned_seats_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND status != 'LEFT';

  -- 5. Terminar la mesa
  UPDATE public.game_tables
  SET status = 'TERMINATED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 6. Auditoría
  INSERT INTO public.audit_logs (
    actor_id,
    actor_role,
    action,
    resource_type,
    resource_id,
    severity,
    metadata
  ) VALUES (
    v_caller_id,
    v_caller_role,
    'MESA_PROBLEMATICA_LIMPIADA',
    'GAME_TABLE',
    p_table_id::text,
    'WARNING',
    jsonb_build_object(
      'table_id', p_table_id,
      'invite_code', v_table.invite_code,
      'game_type', v_table.game_type,
      'reason', p_reason,
      'refunded_players', v_refund_count,
      'cleaned_seats', v_cleaned_seats_count,
      'timestamp', NOW()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'action', 'MESA_PROBLEMATICA_LIMPIADA',
    'refunded_count', v_refund_count,
    'cleaned_seats', v_cleaned_seats_count,
    'message', 'Mesa limpiada y asientos liberados exitosamente.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_fix_and_cleanup_problematic_table(UUID, TEXT) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 55: 053_fix_closed_at_has_role_and_audit_cleanup.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 053: COLUMNAS DE MESA, OVERLOAD HAS_ROLE Y LIMPIEZA
-- ==============================================================================
-- 1. Agrega columnas faltantes `closed_at` y `updated_at` a `game_tables`
-- 2. Define overload para `public.has_role(p_role)` usando auth.uid()
-- 3. Asegura el funcionamiento correcto de las RPCs de limpieza de mesas sin eliminar registros
-- ==============================================================================

-- 1. AGREGAR COLUMNAS FALTANTES A GAME_TABLES
ALTER TABLE public.game_tables ADD COLUMN IF NOT EXISTS closed_at TIMESTAMPTZ NULL;
ALTER TABLE public.game_tables ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NULL DEFAULT NOW();

CREATE INDEX IF NOT EXISTS idx_game_tables_closed_at ON public.game_tables(closed_at) WHERE closed_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_game_tables_updated_at ON public.game_tables(updated_at);

-- 2. OVERLOAD DE LA FUNCIÓN HAS_ROLE
-- Permite invocar public.has_role(p_role TEXT) sin requerir p_user_id
CREATE OR REPLACE FUNCTION public.has_role(p_role TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN EXISTS (
    SELECT 1 
    FROM public.user_roles 
    WHERE user_id = v_uid 
      AND role::text = UPPER(p_role)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.has_role(p_role app_role_enum)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN FALSE;
  END IF;

  RETURN EXISTS (
    SELECT 1 
    FROM public.user_roles 
    WHERE user_id = v_uid 
      AND role = p_role
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.has_role(TEXT) TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.has_role(app_role_enum) TO authenticated, service_role, anon;

-- 3. REVISIÓN Y REFUERZO DE LA RPC ADMIN_TERMINATE_GAME_TABLE
CREATE OR REPLACE FUNCTION public.admin_terminate_game_table(
  p_table_id UUID,
  p_reason TEXT DEFAULT 'Terminada por administración',
  p_refund_players BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_table RECORD;
  v_player RECORD;
  v_refunded_count INT := 0;
  v_refund_amount NUMERIC(14,2);
  v_caller_id UUID;
  v_is_admin BOOLEAN;
BEGIN
  v_caller_id := auth.uid();

  -- Verificar permisos de administración
  IF v_caller_id IS NOT NULL THEN
    SELECT (
      public.is_admin(v_caller_id) OR 
      public.is_operator_or_above(v_caller_id) OR 
      public.has_role('ADMIN') OR 
      public.has_role('SUPER_ADMIN')
    ) INTO v_is_admin;

    IF NOT v_is_admin THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'No tiene permisos de administrador para finalizar la mesa.'
      );
    END IF;
  END IF;

  -- Obtener y bloquear la mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Mesa no encontrada.'
    );
  END IF;

  v_refund_amount := COALESCE(v_table.entry_fee, 0.00);

  -- Reembolsar si fue solicitado y la mesa tenía costo de entrada
  IF p_refund_players AND v_refund_amount > 0 THEN
    FOR v_player IN 
      SELECT DISTINCT user_id FROM public.game_table_players 
      WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING')
    LOOP
      UPDATE public.wallets 
      SET available_balance = available_balance + v_refund_amount,
          updated_at = NOW()
      WHERE user_id = v_player.user_id;

      INSERT INTO public.ledger_entries (
        user_id,
        amount,
        type,
        reference_type,
        reference_id,
        description
      ) VALUES (
        v_player.user_id,
        v_refund_amount,
        'REFUND',
        'GAME_CANCELLED',
        p_table_id::text,
        'Reembolso administrativo por cancelación de mesa: ' || COALESCE(p_reason, 'Cancelación')
      );

      v_refunded_count := v_refunded_count + 1;
    END LOOP;
  END IF;

  -- Actualizar la mesa utilizando las columnas reales
  UPDATE public.game_tables
  SET status = 'TERMINATED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  -- Actualizar estado de jugadores en la mesa
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_status_enum,
      left_at = NOW()
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  -- Finalizar sesiones asociadas si existen
  UPDATE public.game_sessions
  SET status = 'ABANDONED'::session_status_enum,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND status IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED');

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refunded_count', v_refunded_count,
    'refund_amount', v_refund_amount,
    'reason', p_reason
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_terminate_game_table(UUID, TEXT, BOOLEAN) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 56: 054_fix_finished_tables_and_prevent_multi_tables.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 054
-- CORRECCIÓN DEFINITIVA DE MESAS QUE PERMANECEN OPEN POST-FINALIZACIÓN,
-- PREVENCIÓN DE MÚLTIPLES MESAS ACTIVAS POR USUARIO Y LIMPIEZA ATÓMICA
-- ==============================================================================

-- 1. TRIGGER AUTOMÁTICO EN game_sessions PARA CERRAR MESAS EN TRANSICIÓN A FINISHED/SETTLED/CANCELLED
CREATE OR REPLACE FUNCTION public.fn_sync_table_status_on_session_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF NEW.status IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED') THEN
    -- Actualizar mesa a CLOSED
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = COALESCE(closed_at, NOW()),
        updated_at = NOW()
    WHERE id = NEW.table_id
      AND status NOT IN ('CLOSED', 'TERMINATED', 'CANCELLED');

    -- Liberar asientos activos de jugadores
    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = COALESCE(left_at, NOW()),
        updated_at = NOW()
    WHERE table_id = NEW.table_id
      AND status IN ('JOINED', 'READY', 'PLAYING');
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_table_status_on_session_change ON public.game_sessions;
CREATE TRIGGER trg_sync_table_status_on_session_change
  AFTER INSERT OR UPDATE OF status ON public.game_sessions
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_table_status_on_session_change();


-- 2. ACTUALIZACIÓN DE create_game_table_secure CON VERIFICACIÓN DE MESAS ACTIVAS PREVIAS (REGLA 2)
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 0.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- REGLA 2: Bloquear si el usuario ya participa en una mesa activa del mismo juego
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND (gs.status IS NULL OR gs.status IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED'));

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya te encuentras participando en una mesa activa de este juego. Debes salir o terminar esa mesa antes de crear otra.';
  END IF;

  IF p_entry_fee < 0.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de entrada no puede ser negativo';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de entrada % Bs. no está autorizado en el sistema', p_entry_fee;
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, máximo 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players = 4 THEN 2 
    WHEN p_max_players > 4 THEN 2
    ELSE p_max_players 
  END;

  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_expires_at := NOW() + INTERVAL '2 hours';
  v_table_id := gen_random_uuid();
  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || v_enum_game_type::text);

  INSERT INTO public.game_tables (
    id,
    game_type,
    host_user_id,
    visibility,
    invite_code,
    entry_fee,
    min_players,
    max_players,
    current_players_count,
    status,
    config,
    expires_at
  ) VALUES (
    v_table_id,
    v_enum_game_type,
    v_user_id,
    p_visibility,
    v_invite_code,
    p_entry_fee,
    v_min_players,
    p_max_players,
    0,
    'OPEN'::table_status_enum,
    p_config,
    v_expires_at
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'created_at', NOW()
  );
END;
$$;


-- 3. ACTUALIZACIÓN DE join_table_transaction CON CONTROLES ESTRICTOS (REGLAS 2, 3 Y ESTADO MESA)
CREATE OR REPLACE FUNCTION public.join_table_transaction(
  p_table_id UUID,
  p_seat_number SMALLINT,
  p_idempotency_key VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile RECORD;
  v_table RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_existing_active_player RECORD;
  v_other_active_table RECORD;
  v_active_players_count INT;
  v_ledger_id UUID;
  v_player_id UUID;
BEGIN
  -- 1. Autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  -- 2. Perfil
  SELECT * INTO v_profile FROM public.profiles WHERE user_id = v_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND: Perfil de usuario no registrado';
  END IF;

  IF v_profile.account_status != 'ACTIVE' THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Cuenta no habilitada para unirse a mesas (estado: %)', v_profile.account_status;
  END IF;

  -- 3. Bloqueo pesimista de la mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  -- REGLA 1: Verificar si la sesión asociada ya finalizó
  SELECT * INTO v_session FROM public.game_sessions WHERE table_id = p_table_id ORDER BY created_at DESC LIMIT 1;
  IF v_session.id IS NOT NULL AND v_session.status IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED') THEN
    UPDATE public.game_tables SET status = 'CLOSED'::table_status_enum, closed_at = NOW(), updated_at = NOW() WHERE id = p_table_id;
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La partida de esta mesa ya finalizó y no acepta nuevos jugadores.';
  END IF;

  IF v_table.status NOT IN ('OPEN', 'WAITING', 'WAITING_PLAYERS') THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La mesa no está disponible para unirse (estado: %)', v_table.status;
  END IF;

  IF v_table.expires_at <= NOW() THEN
    UPDATE public.game_tables SET status = 'EXPIRED'::table_status_enum, closed_at = NOW(), updated_at = NOW() WHERE id = p_table_id;
    RAISE EXCEPTION 'TABLE_EXPIRED: La mesa ha expirado';
  END IF;

  -- 4. REGLA 3: ¿Ya participa el usuario en ESTA mesa? (Un usuario = Un solo asiento)
  SELECT * INTO v_existing_active_player
  FROM public.game_table_players
  WHERE table_id = p_table_id 
    AND user_id = v_user_id 
    AND status IN ('JOINED', 'READY', 'PLAYING');

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'already_seated', true,
      'table_player_id', v_existing_active_player.id,
      'player_id', v_existing_active_player.id,
      'table_id', p_table_id,
      'seat_number', v_existing_active_player.seat_number,
      'message', 'El jugador ya ocupa el asiento #' || v_existing_active_player.seat_number || ' en esta mesa.'
    );
  END IF;

  -- 5. REGLA 2: ¿Ya participa en OTRA mesa activa del MISMO juego?
  SELECT gt.id INTO v_other_active_table
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.id != p_table_id
    AND gt.game_type = v_table.game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND (gs.status IS NULL OR gs.status IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED'))
  LIMIT 1;

  IF v_other_active_table.id IS NOT NULL THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya te encuentras participando en otra mesa activa de este juego. Debes salir o terminar esa mesa primero.';
  END IF;

  -- 6. Capacidad y Asiento
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  IF v_active_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: La mesa ha alcanzado su capacidad máxima (%/%)', v_active_players_count, v_table.max_players;
  END IF;

  IF p_seat_number < 1 OR p_seat_number > v_table.max_players THEN
    RAISE EXCEPTION 'INVALID_SEAT: Número de asiento fuera de rango permitido (1..%)', v_table.max_players;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.game_table_players 
    WHERE table_id = p_table_id 
      AND seat_number = p_seat_number 
      AND status IN ('JOINED', 'READY', 'PLAYING')
  ) THEN
    RAISE EXCEPTION 'SEAT_TAKEN: El asiento % ya está ocupado', p_seat_number;
  END IF;

  -- 7. Retención y Ledger si la mesa requiere costo de entrada
  IF v_table.entry_fee > 0.00 THEN
    SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_user_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'WALLET_NOT_FOUND: Billetera de usuario no encontrada';
    END IF;

    IF v_wallet.available_balance < v_table.entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo disponible insuficiente (requerido: %, disponible: %)', 
        v_table.entry_fee, v_wallet.available_balance;
    END IF;

    UPDATE public.wallets
    SET available_balance = available_balance - v_table.entry_fee,
        held_balance = held_balance + v_table.entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet.id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id, wallet_id, user_id, entry_type, direction, amount,
      balance_after_available, balance_after_held, reference_table,
      reference_id, idempotency_key, description, actor_id
    ) VALUES (
      v_ledger_id, v_wallet.id, v_user_id, 'TABLE_ENTRY_HOLD', 'HOLD', v_table.entry_fee,
      v_wallet.available_balance - v_table.entry_fee, v_wallet.held_balance + v_table.entry_fee,
      'game_tables', p_table_id, p_idempotency_key,
      'Retención de entrada a mesa ' || p_table_id::text || ' asiento ' || p_seat_number::text, v_user_id
    );
  END IF;

  -- 8. Insertar nuevo asiento de jugador
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id
  ) VALUES (
    v_player_id, p_table_id, v_user_id, p_seat_number, 'JOINED'::player_table_status_enum, v_ledger_id
  );

  -- 9. Reconciliación del contador y estado
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('JOINED', 'READY', 'PLAYING');

  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count >= max_players THEN 'FULL'::table_status_enum
        ELSE 'OPEN'::table_status_enum
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_player_id', v_player_id,
    'player_id', v_player_id,
    'table_id', p_table_id,
    'seat_number', p_seat_number,
    'active_players_count', v_active_players_count
  );
END;
$$;


-- 4. RPC DE LIMPIEZA ATÓMICA DE TODAS LAS MESAS INVÁLIDAS
CREATE OR REPLACE FUNCTION public.admin_cleanup_all_invalid_tables()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_rec RECORD;
  v_cleaned_count INT := 0;
  v_cleaned_ids UUID[] := ARRAY[]::UUID[];
BEGIN
  FOR v_rec IN 
    SELECT DISTINCT gt.id
    FROM public.game_tables gt
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE 
      -- Caso 1: Mesa OPEN/FULL/ACTIVE pero sesión FINISHED/SETTLED/CANCELLED
      (gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND gs.status IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED'))
      -- Caso 2: Mesa OPEN/FULL expirada
      OR (gt.status IN ('OPEN', 'FULL', 'WAITING') AND gt.expires_at <= NOW())
      -- Caso 3: Mesa OPEN antigua abandonada con <= 1 jugador
      OR (gt.status = 'OPEN' AND gt.created_at < NOW() - INTERVAL '30 minutes' AND gt.current_players_count <= 1)
  LOOP
    PERFORM public.admin_terminate_game_table(v_rec.id, 'Limpieza automática de mesas inválidas o abandonadas', TRUE);
    v_cleaned_count := v_cleaned_count + 1;
    v_cleaned_ids := array_append(v_cleaned_ids, v_rec.id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'cleaned_count', v_cleaned_count,
    'cleaned_table_ids', v_cleaned_ids
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_cleanup_all_invalid_tables() TO authenticated, service_role;


-- 5. LIMPIEZA Y SANEAMIENTO DIRECTO EN BASE DE DATOS PARA MESAS PROBLEMÁTICAS EXISTENTES
-- Cierre de todas las mesas cuya sesión ya esté FINISHED / SETTLED / CANCELLED
UPDATE public.game_tables
SET status = 'CLOSED'::table_status_enum,
    closed_at = COALESCE(closed_at, NOW()),
    updated_at = NOW()
WHERE id IN (
  SELECT table_id FROM public.game_sessions WHERE status IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED')
) AND status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE');

-- Saneamiento específico de las mesas reportadas en la evidencia
UPDATE public.game_tables
SET status = 'CLOSED'::table_status_enum,
    closed_at = COALESCE(closed_at, NOW()),
    updated_at = NOW()
WHERE id IN (
  'ab13967f-bf6f-4fea-ab24-a8edef62bb07'::UUID,
  '6ffcbdfa-87b4-4be0-bb96-20df77c66582'::UUID,
  '6ffcbdfa-87b4-4be0-82bd-ce237913cfc7'::UUID
);

UPDATE public.game_table_players
SET status = 'LEFT'::player_table_status_enum,
    left_at = COALESCE(left_at, NOW()),
    updated_at = NOW()
WHERE table_id IN (
  'ab13967f-bf6f-4fea-ab24-a8edef62bb07'::UUID,
  '6ffcbdfa-87b4-4be0-bb96-20df77c66582'::UUID,
  '6ffcbdfa-87b4-4be0-82bd-ce237913cfc7'::UUID
) AND status IN ('JOINED', 'READY', 'PLAYING');

-- Recarga del esquema PostgREST
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 57: 055_fix_polla_single_pool_system.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 055: POZO ÚNICO POR DÍA Y TURNO EN POLLA VENEZOLANA
-- ==============================================================================
-- Consolidación estricta de compras por (draw_date + block) en UN SOLO POZO.
-- Distribución 90% Ganador / 10% Plataforma calculada obligatoriamente en servidor.
-- Operación transaccional con bloqueos pesimistas e idempotencia garantizada.
-- ==============================================================================

-- 1. ESTRUCTURA Y COLUMNAS EN POLLA_BLOCK_CLOSURES
ALTER TABLE public.polla_block_closures
  ADD COLUMN IF NOT EXISTS total_collected_bs NUMERIC(15,2) DEFAULT 0.00,
  ADD COLUMN IF NOT EXISTS prize_bs NUMERIC(15,2) DEFAULT 0.00,
  ADD COLUMN IF NOT EXISTS commission_bs NUMERIC(15,2) DEFAULT 0.00,
  ADD COLUMN IF NOT EXISTS total_tickets INT DEFAULT 0,
  ADD COLUMN IF NOT EXISTS is_settled BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS settled_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS settled_by UUID REFERENCES auth.users(id);

-- 2. RPC PARA CONSULTAR EL POZO ÚNICO Y ACUMULADO DEL TURNO (FECHA + BLOQUE)
CREATE OR REPLACE FUNCTION public.get_polla_shift_pool_summary(
  p_draw_date DATE,
  p_block TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_total_tickets INT := 0;
  v_total_collected NUMERIC(15,2) := 0.00;
  v_prize_90 NUMERIC(15,2) := 0.00;
  v_commission_10 NUMERIC(15,2) := 0.00;
  v_closure RECORD;
  v_winner_name TEXT := NULL;
BEGIN
  -- 1. Sumar todas las compras válidas y confirmadas del turno
  SELECT 
    COUNT(*),
    COALESCE(SUM(cost_bs), 0.00)
  INTO 
    v_total_tickets,
    v_total_collected
  FROM public.polla_tickets
  WHERE draw_date = p_draw_date 
    AND block = p_block
    AND status != 'CANCELLED'
    AND (validation_status IS NULL OR validation_status != 'REJECTED');

  -- 2. Calcular pozo 90% para el ganador y 10% para la plataforma
  v_prize_90 := ROUND(v_total_collected * 0.90, 2);
  v_commission_10 := v_total_collected - v_prize_90;

  -- 3. Obtener registro de cierre si el turno ya fue liquidado
  SELECT * INTO v_closure
  FROM public.polla_block_closures
  WHERE draw_date = p_draw_date AND block = p_block;

  IF v_closure.winner_user_id IS NOT NULL THEN
    SELECT COALESCE(TRIM(p.first_name || ' ' || p.last_name), p.display_name, 'JUGADOR SIN NOMBRE')
    INTO v_winner_name
    FROM public.profiles p
    WHERE p.id = v_closure.winner_user_id;
  END IF;

  RETURN jsonb_build_object(
    'draw_date', p_draw_date,
    'block', p_block,
    'total_tickets', v_total_tickets,
    'total_collected_bs', v_total_collected,
    'prize_90_bs', v_prize_90,
    'commission_10_bs', v_commission_10,
    'is_settled', COALESCE(v_closure.is_settled, false),
    'winner_user_id', v_closure.winner_user_id,
    'winner_name', UPPER(COALESCE(v_winner_name, '')),
    'winner_ticket_id', v_closure.winner_ticket_id,
    'settled_at', v_closure.settled_at
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_polla_shift_pool_summary(DATE, TEXT) TO authenticated, service_role;

-- 3. RPC ACREDITACIÓN DE PREMIO SERVER-AUTHORITATIVE Y CONSOLIDACIÓN DE POZO
CREATE OR REPLACE FUNCTION public.credit_polla_prize_secure(
  p_ticket_id UUID,
  p_prize_bs NUMERIC DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_admin_id UUID;
  v_ticket RECORD;
  v_draw_date DATE;
  v_block TEXT;
  v_winner_user_id UUID;
  v_wallet_id UUID;
  v_wallet_available NUMERIC(14,2);
  v_wallet_held NUMERIC(14,2);
  v_winner_ledger_id UUID;
  v_total_tickets INT := 0;
  v_total_collected_bs NUMERIC(15,2) := 0.00;
  v_prize_90 NUMERIC(15,2) := 0.00;
  v_commission_10 NUMERIC(15,2) := 0.00;
  v_existing_closure RECORD;
BEGIN
  -- 1. Validar permisos de administrador
  v_admin_id := auth.uid();
  IF NOT public.is_admin(v_admin_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'REQUIERE_ACCESO_ADMINISTRATIVO');
  END IF;

  -- 2. Obtener ticket con bloqueo pesimista
  SELECT * INTO v_ticket 
  FROM public.polla_tickets 
  WHERE id = p_ticket_id 
  FOR UPDATE;

  IF v_ticket.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'TICKET_NO_ENCONTRADO');
  END IF;

  v_draw_date := v_ticket.draw_date;
  v_block := v_ticket.block;
  v_winner_user_id := v_ticket.user_id;

  -- 3. BLOQUEO TRANSACCIONAL POR TURNO (PREVENIR CONDICIONES DE CARRERA)
  PERFORM pg_advisory_xact_lock(hashtext('polla_closure_' || v_draw_date::text || '_' || v_block));

  -- 4. VERIFICAR IDEMPOTENCIA Y PREVENIR DOBLE LIQUIDACIÓN
  SELECT * INTO v_existing_closure
  FROM public.polla_block_closures
  WHERE draw_date = v_draw_date AND block = v_block AND is_settled = TRUE
  FOR UPDATE;

  IF v_existing_closure.id IS NOT NULL OR v_ticket.validation_status = 'CREDITED' OR v_ticket.credited_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'TURNO_YA_LIQUIDADO',
      'message', 'El turno (' || v_draw_date::text || ' ' || v_block || ') ya fue liquidado previamente. Se evitó un pago o comisión duplicados.'
    );
  END IF;

  -- 5. CÁLCULO DEL POZO ÚNICO EN EL SERVIDOR (90% GANADOR / 10% PLATAFORMA)
  SELECT 
    COUNT(*),
    COALESCE(SUM(cost_bs), 0.00)
  INTO 
    v_total_tickets,
    v_total_collected_bs
  FROM public.polla_tickets
  WHERE draw_date = v_draw_date 
    AND block = v_block
    AND status != 'CANCELLED'
    AND (validation_status IS NULL OR validation_status != 'REJECTED');

  IF v_total_collected_bs <= 0 THEN
    v_total_collected_bs := COALESCE(v_ticket.cost_bs, 250.00);
    v_total_tickets := 1;
  END IF;

  v_prize_90 := ROUND(v_total_collected_bs * 0.90, 2);
  v_commission_10 := v_total_collected_bs - v_prize_90;

  -- 6. BLOQUEAR BILLETERA DEL JUGADOR GANADOR
  SELECT id, available_balance, held_balance 
  INTO v_wallet_id, v_wallet_available, v_wallet_held
  FROM public.wallets
  WHERE user_id = v_winner_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (user_id, available_balance, held_balance) 
    VALUES (v_winner_user_id, 0.00, 0.00) 
    RETURNING id, available_balance, held_balance 
    INTO v_wallet_id, v_wallet_available, v_wallet_held;
  END IF;

  -- 7. ACREDITAR ÚNICO PREMIO DEL TURNO EN LA BILLETERA DEL GANADOR
  UPDATE public.wallets
  SET available_balance = available_balance + v_prize_90,
      updated_at = NOW()
  WHERE id = v_wallet_id;

  -- 8. REGISTRAR ENTRADA EN LEDGER PARA EL GANADOR (90%)
  INSERT INTO public.ledger_entries (
    wallet_id,
    user_id,
    entry_type,
    direction,
    amount,
    balance_after_available,
    balance_after_held,
    reference_table,
    reference_id,
    idempotency_key,
    description
  ) VALUES (
    v_wallet_id,
    v_winner_user_id,
    'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
    'CREDIT'::ledger_direction_enum,
    v_prize_90,
    v_wallet_available + v_prize_90,
    v_wallet_held,
    'polla_tickets',
    v_ticket.id,
    'polla_prize_' || v_draw_date::text || '_' || v_block,
    'Premio Polla Venezolana (90% Pozo Turno ' || v_block || ' ' || v_draw_date::text || ')'
  ) RETURNING id INTO v_winner_ledger_id;

  -- 9. REGISTRAR ENTRADA EN LEDGER PARA LA COMISIÓN DE PLATAFORMA (10%)
  IF v_commission_10 > 0 THEN
    INSERT INTO public.ledger_entries (
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_id,
      idempotency_key,
      description
    ) VALUES (
      v_wallet_id,
      v_winner_user_id,
      'PLATFORM_FEE_CREDIT'::ledger_entry_type_enum,
      'CREDIT'::ledger_direction_enum,
      v_commission_10,
      v_wallet_available + v_prize_90,
      v_wallet_held,
      'polla_block_closures',
      v_ticket.id,
      'polla_commission_' || v_draw_date::text || '_' || v_block,
      'Comisión Plataforma Polla (10% Pozo Turno ' || v_block || ' ' || v_draw_date::text || ')'
    );
  END IF;

  -- 10. MARCAR TICKETS DEL TURNO Y DEL USUARIO COMO PAGADOS
  UPDATE public.polla_tickets
  SET validation_status = 'CREDITED',
      status = 'WINNER',
      prize_bs = CASE WHEN id = v_ticket.id THEN v_prize_90 ELSE 0.00 END,
      credited_at = NOW(),
      ledger_entry_id = v_winner_ledger_id
  WHERE draw_date = v_draw_date 
    AND block = v_block 
    AND user_id = v_winner_user_id
    AND status IN ('PENDING', 'WINNER');

  -- Marcar tickets restantes de otros usuarios en el turno como NO_GANADORES
  UPDATE public.polla_tickets
  SET status = 'NOT_WINNER'
  WHERE draw_date = v_draw_date 
    AND block = v_block 
    AND user_id != v_winner_user_id
    AND status = 'PENDING';

  -- 11. REGISTRAR EL CIERRE DEFINITIVO DEL TURNO EN POLLA_BLOCK_CLOSURES
  INSERT INTO public.polla_block_closures (
    draw_date,
    block,
    winner_user_id,
    winner_ticket_id,
    hits,
    closure_reason,
    total_collected_bs,
    prize_bs,
    commission_bs,
    total_tickets,
    is_settled,
    settled_at,
    settled_by,
    closure_event_data
  ) VALUES (
    v_draw_date,
    v_block,
    v_winner_user_id,
    v_ticket.id,
    COALESCE(v_ticket.hits, 6),
    'SINGLE_POOL_SHIFT_SETTLEMENT',
    v_total_collected_bs,
    v_prize_90,
    v_commission_10,
    v_total_tickets,
    TRUE,
    NOW(),
    v_admin_id,
    jsonb_build_object(
      'total_collected_bs', v_total_collected_bs,
      'prize_bs', v_prize_90,
      'commission_bs', v_commission_10,
      'total_tickets', v_total_tickets,
      'settled_by', v_admin_id,
      'settled_at', NOW()
    )
  ) ON CONFLICT (draw_date, block) DO UPDATE
    SET winner_user_id = EXCLUDED.winner_user_id,
        winner_ticket_id = EXCLUDED.winner_ticket_id,
        closure_reason = EXCLUDED.closure_reason,
        total_collected_bs = EXCLUDED.total_collected_bs,
        prize_bs = EXCLUDED.prize_bs,
        commission_bs = EXCLUDED.commission_bs,
        total_tickets = EXCLUDED.total_tickets,
        is_settled = TRUE,
        settled_at = NOW(),
        settled_by = EXCLUDED.settled_by,
        closure_event_data = EXCLUDED.closure_event_data;

  RETURN jsonb_build_object(
    'success', true,
    'draw_date', v_draw_date,
    'block', v_block,
    'winner_user_id', v_winner_user_id,
    'total_collected_bs', v_total_collected_bs,
    'prize_bs', v_prize_90,
    'commission_bs', v_commission_10,
    'total_tickets', v_total_tickets,
    'balance_after', v_wallet_available + v_prize_90,
    'message', 'LIQUIDACIÓN EXITOSA: Pozo Total de ' || v_total_collected_bs || ' Bs consolidado. Premio 90%: ' || v_prize_90 || ' Bs. Comisión 10%: ' || v_commission_10 || ' Bs.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.credit_polla_prize_secure(UUID, NUMERIC) TO authenticated, service_role;

-- 4. RPC DE AUDITORÍA DE CONSISTENCIA DE POZOS HISTÓRICOS DE POLLA
CREATE OR REPLACE FUNCTION public.audit_polla_shift_pools()
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_record RECORD;
  v_inconsistencies INT := 0;
  v_details JSONB := '[]'::jsonb;
BEGIN
  FOR v_record IN 
    SELECT 
      c.draw_date,
      c.block,
      c.total_collected_bs,
      c.prize_bs,
      c.commission_bs,
      c.total_tickets,
      c.is_settled,
      (c.prize_bs + c.commission_bs) AS sum_check
    FROM public.polla_block_closures c
    WHERE c.is_settled = TRUE
  LOOP
    IF v_record.sum_check <> v_record.total_collected_bs THEN
      v_inconsistencies := v_inconsistencies + 1;
      v_details := v_details || jsonb_build_object(
        'draw_date', v_record.draw_date,
        'block', v_record.block,
        'total_collected_bs', v_record.total_collected_bs,
        'prize_bs', v_record.prize_bs,
        'commission_bs', v_record.commission_bs,
        'sum_check', v_record.sum_check
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'audit_status', CASE WHEN v_inconsistencies = 0 THEN 'PASS' ELSE 'WARNING' END,
    'inconsistencies_count', v_inconsistencies,
    'details', v_details
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.audit_polla_shift_pools() TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 58: 056_global_presence_and_operator_users_visibility.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 056: FUENTE ÚNICA DE VERDAD Y VISIBILIDAD DE PRESENCIA GLOBAL
-- ==============================================================================
-- 1. Actualiza RLS de user_roles y wallets para permitir acceso SELECT a Operadores.
-- 2. Ajusta la ventana de presencia inactiva a 4 minutos en cleanup_inactive_user_presence.
-- 3. Actualiza record_user_heartbeat para sincronizar profiles y user_activity_sessions.
-- 4. Actualiza get_admin_dashboard_metrics con ventana de 4 minutos.
-- 5. Crea RPC get_admin_users_list() para consulta atómica y garantizada de usuarios por Admins y Operadores.
-- ==============================================================================

-- 1. Actualización de Políticas RLS para user_roles y wallets (Permitir Operadores)
DROP POLICY IF EXISTS p_user_roles_select ON public.user_roles;
CREATE POLICY p_user_roles_select ON public.user_roles
  FOR SELECT
  USING (
    auth.uid() = user_id 
    OR public.is_operator_or_above(auth.uid())
  );

DROP POLICY IF EXISTS p_wallets_select ON public.wallets;
CREATE POLICY p_wallets_select ON public.wallets
  FOR SELECT
  USING (
    auth.uid() = user_id 
    OR public.is_operator_or_above(auth.uid())
  );

-- 2. Limpieza de presencias inactivas con tolerancia de 4 minutos (resiliente a redes móviles / PWA)
CREATE OR REPLACE FUNCTION public.cleanup_inactive_user_presence(p_timeout_minutes INT DEFAULT 4)
RETURNS INT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cleaned INT := 0;
BEGIN
  UPDATE public.profiles
  SET 
    is_online = FALSE,
    updated_at = NOW()
  WHERE 
    is_online = TRUE 
    AND (last_seen_at IS NULL OR last_seen_at < NOW() - (p_timeout_minutes || ' minutes')::INTERVAL);

  GET DIAGNOSTICS v_cleaned = ROW_COUNT;
  RETURN v_cleaned;
END;
$$;

-- 3. RPC record_user_heartbeat con sincronización garantizada de profiles y user_activity_sessions
CREATE OR REPLACE FUNCTION public.record_user_heartbeat(p_activity_type TEXT DEFAULT 'PAGE_ACTIVE')
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_now TIMESTAMPTZ := NOW();
  v_session_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No autenticado');
  END IF;

  -- 3.1 Actualizar presencia única en public.profiles
  UPDATE public.profiles
  SET 
    is_online = TRUE,
    last_seen_at = v_now,
    updated_at = v_now
  WHERE user_id = v_user_id OR id = v_user_id;

  -- 3.2 Sincronizar user_activity_sessions si la tabla existe
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'user_activity_sessions') THEN
    UPDATE public.user_activity_sessions
    SET 
      status = 'DISCONNECTED',
      ended_at = last_seen_at,
      session_duration_seconds = EXTRACT(EPOCH FROM (last_seen_at - started_at))::BIGINT,
      updated_at = v_now
    WHERE user_id = v_user_id 
      AND status IN ('ACTIVE', 'IDLE')
      AND last_seen_at < (v_now - INTERVAL '10 minutes');

    SELECT id INTO v_session_id
    FROM public.user_activity_sessions
    WHERE user_id = v_user_id 
      AND status IN ('ACTIVE', 'IDLE')
      AND last_seen_at >= (v_now - INTERVAL '10 minutes')
    ORDER BY last_seen_at DESC
    LIMIT 1;

    IF v_session_id IS NOT NULL THEN
      UPDATE public.user_activity_sessions
      SET 
        last_seen_at = v_now,
        last_activity_type = COALESCE(p_activity_type, 'PAGE_ACTIVE'),
        status = 'ACTIVE',
        session_duration_seconds = EXTRACT(EPOCH FROM (v_now - started_at))::BIGINT,
        updated_at = v_now
      WHERE id = v_session_id;
    ELSE
      INSERT INTO public.user_activity_sessions (
        id,
        user_id,
        started_at,
        last_seen_at,
        status,
        session_duration_seconds,
        last_activity_type
      ) VALUES (
        gen_random_uuid(),
        v_user_id,
        v_now,
        v_now,
        'ACTIVE',
        0,
        COALESCE(p_activity_type, 'PAGE_ACTIVE')
      );
    END IF;
  END IF;

  -- 3.3 Limpiar usuarios inactivos por más de 4 min
  PERFORM public.cleanup_inactive_user_presence(4);

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_user_id,
    'timestamp', v_now
  );
END;
$$;

-- 4. Métricas de Dashboard con ventana de presencia global de 4 minutos
CREATE OR REPLACE FUNCTION public.get_admin_dashboard_metrics()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_registered_users INT := 0;
  v_active_users INT := 0;
  v_connected_users INT := 0;
  v_active_tables INT := 0;
  v_active_matches INT := 0;
  v_finished_matches INT := 0;
  v_pending_deposits INT := 0;
  v_pending_withdrawals INT := 0;
  v_pending_tickets INT := 0;
  v_total_volume NUMERIC := 0;
  v_total_prizes NUMERIC := 0;
  v_total_fees NUMERIC := 0;
  v_security_alerts INT := 0;
BEGIN
  -- Limpiar inactivos (> 4 min)
  PERFORM public.cleanup_inactive_user_presence(4);

  -- Registrados vs Conectados globales
  SELECT COUNT(*) INTO v_registered_users FROM public.profiles;
  SELECT COUNT(*) INTO v_connected_users 
  FROM public.profiles 
  WHERE is_online = TRUE 
     OR (last_seen_at IS NOT NULL AND last_seen_at >= (NOW() - INTERVAL '4 minutes'));
  
  -- Usuarios activos en las últimas 24h
  SELECT COUNT(*) INTO v_active_users 
  FROM public.profiles 
  WHERE last_seen_at >= (NOW() - INTERVAL '24 hours');

  -- Mesas y Partidas
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_tables') THEN
    SELECT COUNT(*) INTO v_active_tables FROM public.game_tables WHERE status IN ('OPEN', 'WAITING_PLAYERS', 'FULL', 'WAITING', 'IN_GAME', 'STARTING');
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_sessions') THEN
    SELECT COUNT(*) INTO v_active_matches FROM public.game_sessions WHERE status IN ('IN_PROGRESS', 'WAITING', 'STARTING');
    SELECT COUNT(*) INTO v_finished_matches FROM public.game_sessions WHERE status IN ('SETTLED', 'COMPLETED', 'FINISHED');
  END IF;

  -- Solicitudes pendientes
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'deposit_requests') THEN
    SELECT COUNT(*) INTO v_pending_deposits FROM public.deposit_requests WHERE status = 'PENDING';
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'withdrawal_requests') THEN
    SELECT COUNT(*) INTO v_pending_withdrawals FROM public.withdrawal_requests WHERE status = 'PENDING';
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'support_tickets') THEN
    SELECT COUNT(*) INTO v_pending_tickets FROM public.support_tickets WHERE status IN ('OPEN', 'IN_PROGRESS');
  END IF;

  -- Volúmenes y comisiones
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'game_settlements') THEN
    SELECT COALESCE(SUM(gross_pool), 0), COALESCE(SUM(prize_pool), 0), COALESCE(SUM(platform_fee), 0)
    INTO v_total_volume, v_total_prizes, v_total_fees
    FROM public.game_settlements;
  END IF;

  -- Alertas de seguridad
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'audit_logs') THEN
    SELECT COUNT(*) INTO v_security_alerts FROM public.audit_logs WHERE severity IN ('CRITICAL', 'SECURITY_ALERT') AND created_at >= (NOW() - INTERVAL '7 days');
  END IF;

  RETURN jsonb_build_object(
    'registeredUsersCount', v_registered_users,
    'activeUsersCount', GREATEST(v_active_users, v_connected_users),
    'connectedUsersCount', v_connected_users,
    'activeTablesCount', v_active_tables,
    'activeMatchesCount', v_active_matches,
    'finishedMatchesCount', v_finished_matches,
    'pendingDepositsCount', v_pending_deposits,
    'pendingWithdrawalsCount', v_pending_withdrawals,
    'pendingTicketsCount', v_pending_tickets,
    'totalVolumePlayed', v_total_volume,
    'totalPrizesAwarded', v_total_prizes,
    'totalServiceFeesCollected', v_total_fees,
    'securityAlertsCount', v_security_alerts
  );
END;
$$;

-- 5. RPC get_admin_users_list() - Fuente de verdad absoluta para el listado de usuarios
CREATE OR REPLACE FUNCTION public.get_admin_users_list()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID := auth.uid();
  v_result JSONB;
BEGIN
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'UNAUTHORIZED: Requiere rol de Operador o Administrador.';
  END IF;

  -- Ejecutar limpieza previa de presencias inactivas (> 4 min)
  PERFORM public.cleanup_inactive_user_presence(4);

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'user_id', p.user_id,
        'first_name', COALESCE(p.first_name, 'Jugador'),
        'last_name', COALESCE(p.last_name, ''),
        'display_name', COALESCE(p.display_name, p.first_name, 'Jugador'),
        'email', p.email,
        'phone_number', p.phone_number,
        'cedula_last4', p.cedula_last4,
        'state_venezuela', COALESCE(p.state_venezuela, 'Distrito Capital'),
        'account_status', COALESCE(p.account_status, 'ACTIVE'),
        'kyc_status', COALESCE(p.kyc_status, 'UNSUBMITTED'),
        'is_online', (
          COALESCE(p.is_online, FALSE) 
          OR (p.last_seen_at IS NOT NULL AND p.last_seen_at >= (NOW() - INTERVAL '4 minutes'))
        ),
        'last_seen_at', COALESCE(p.last_seen_at, p.updated_at, p.created_at),
        'created_at', p.created_at,
        'updated_at', p.updated_at,
        'role', COALESCE(r.role, 'PLAYER'),
        'available_balance', COALESCE(w.available_balance, 0),
        'held_balance', COALESCE(w.held_balance, 0),
        'total_balance', COALESCE(w.available_balance + w.held_balance, 0)
      ) ORDER BY p.created_at DESC
    ),
    '[]'::jsonb
  ) INTO v_result
  FROM public.profiles p
  LEFT JOIN (
    SELECT DISTINCT ON (user_id) user_id, role 
    FROM public.user_roles 
    ORDER BY user_id, 
             CASE role 
               WHEN 'SUPER_ADMIN' THEN 1 
               WHEN 'ADMIN' THEN 2 
               WHEN 'OPERATOR' THEN 3 
               ELSE 4 
             END
  ) r ON p.user_id = r.user_id
  LEFT JOIN public.wallets w ON p.user_id = w.user_id;

  RETURN v_result;
END;
$$;

-- Otorgar Permisos de Ejecución
GRANT EXECUTE ON FUNCTION public.cleanup_inactive_user_presence(INT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.record_user_heartbeat(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_admin_dashboard_metrics() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_admin_users_list() TO authenticated;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 59: 057_secure_totp_2fa_system.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 057: SISTEMA 2FA / TOTP Y RECOVERY CODES COMPLETO
-- ==============================================================================
-- - Tabla user_2fa_secrets para secretos Base32, recovery_codes e intentos fallidos
-- - Autenticación TOTP (RFC 6238, SHA1, 30s) en PL/pgSQL
-- - Bloqueo anti-fuerza bruta (5 intentos fallidos consecutivas -> 15 min bloqueo)
-- - RPCs: generate_totp_secret, get_2fa_status, enable_2fa, disable_2fa, regenerate_recovery_codes
-- - RPCs de validación: validate_2fa_if_enabled, validate_admin_2fa_action
-- - Protección 2FA en retiros de jugadores y acciones administrativas sensibles
-- ==============================================================================

-- 1. Agregar columna is_mfa_enabled en public.profiles
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS is_mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE;

-- 2. Tabla para Almacenar Secretos TOTP 2FA y Códigos de Recuperación
CREATE TABLE IF NOT EXISTS public.user_2fa_secrets (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  secret_encrypted TEXT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT FALSE,
  recovery_codes JSONB DEFAULT '[]'::jsonb,
  failed_attempts INT NOT NULL DEFAULT 0,
  locked_until TIMESTAMPTZ DEFAULT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Habilitar RLS
ALTER TABLE public.user_2fa_secrets ENABLE ROW LEVEL SECURITY;

-- Políticas RLS por usuario
DROP POLICY IF EXISTS "user_2fa_secrets_select_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_select_own" ON public.user_2fa_secrets
  FOR SELECT USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_update_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_update_own" ON public.user_2fa_secrets
  FOR UPDATE USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_insert_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_insert_own" ON public.user_2fa_secrets
  FOR INSERT WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "user_2fa_secrets_delete_own" ON public.user_2fa_secrets;
CREATE POLICY "user_2fa_secrets_delete_own" ON public.user_2fa_secrets
  FOR DELETE USING (auth.uid() = user_id);


-- 3. Función de Decodificación Base32 PL/pgSQL
CREATE OR REPLACE FUNCTION public.base32_decode(p_base32 TEXT)
RETURNS BYTEA
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_clean TEXT := upper(regexp_replace(p_base32, '[=\s]', '', 'g'));
  v_len INT := length(v_clean);
  v_alpha TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_bytea BYTEA := '\x'::bytea;
  v_buffer BIGINT := 0;
  v_bits INT := 0;
  v_i INT;
  v_char CHAR;
  v_val INT;
BEGIN
  FOR v_i IN 1..v_len LOOP
    v_char := substring(v_clean FROM v_i FOR 1);
    v_val := position(v_char IN v_alpha) - 1;
    IF v_val < 0 THEN
      RAISE EXCEPTION 'INVALID_BASE32_CHAR: Carácter Base32 no válido %', v_char;
    END IF;
    v_buffer := (v_buffer << 5) | v_val;
    v_bits := v_bits + 5;
    IF v_bits >= 8 THEN
      v_bits := v_bits - 8;
      v_bytea := v_bytea || set_byte('\x00'::bytea, 0, (v_buffer >> v_bits) & 255);
      v_buffer := v_buffer & ((1 << v_bits) - 1);
    END IF;
  END LOOP;
  RETURN v_bytea;
END;
$$;


-- 4. Cálculo de Código TOTP RFC 6238
CREATE OR REPLACE FUNCTION public.calculate_totp(
  p_secret_base32 TEXT,
  p_timestamp TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_secret_bytes BYTEA;
  v_counter BIGINT;
  v_time_bytes BYTEA;
  v_hmac BYTEA;
  v_offset INT;
  v_code_int INT;
BEGIN
  v_secret_bytes := public.base32_decode(p_secret_base32);
  v_counter := floor(extract(epoch from p_timestamp) / 30)::BIGINT;

  v_time_bytes := set_byte('\x0000000000000000'::bytea, 0, ((v_counter >> 56) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 1, ((v_counter >> 48) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 2, ((v_counter >> 40) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 3, ((v_counter >> 32) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 4, ((v_counter >> 24) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 5, ((v_counter >> 16) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 6, ((v_counter >> 8) & 255)::int);
  v_time_bytes := set_byte(v_time_bytes, 7, (v_counter & 255)::int);

  v_hmac := public.hmac(v_time_bytes, v_secret_bytes, 'sha1');
  v_offset := get_byte(v_hmac, 19) & 15;
  v_code_int := ((get_byte(v_hmac, v_offset) & 127) << 24)
              | ((get_byte(v_hmac, v_offset + 1) & 255) << 16)
              | ((get_byte(v_hmac, v_offset + 2) & 255) << 8)
              | (get_byte(v_hmac, v_offset + 3) & 255);

  RETURN lpad((v_code_int % 1000000)::text, 6, '0');
END;
$$;


-- 5. Verificación Interna de TOTP con Ventana de Tolerancia
CREATE OR REPLACE FUNCTION public.verify_totp_code_internal(
  p_secret_base32 TEXT,
  p_code TEXT,
  p_window INT DEFAULT 1
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_i INT;
  v_calc TEXT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) != 6 THEN
    RETURN FALSE;
  END IF;

  FOR v_i IN (-p_window)..p_window LOOP
    v_calc := public.calculate_totp(p_secret_base32, v_now + (v_i * interval '30 seconds'));
    IF v_calc = trim(p_code) THEN
      RETURN TRUE;
    END IF;
  END LOOP;

  RETURN FALSE;
END;
$$;


-- 6. Verificación Interna de Código de Recuperación
CREATE OR REPLACE FUNCTION public.verify_recovery_code_internal(
  p_user_id UUID,
  p_code TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_clean_code TEXT;
  v_code_hash TEXT;
  v_codes JSONB;
  v_item JSONB;
  v_new_codes JSONB := '[]'::jsonb;
  v_found BOOLEAN := FALSE;
BEGIN
  IF p_code IS NULL OR length(trim(p_code)) < 6 THEN
    RETURN FALSE;
  END IF;

  -- Normalizar código de recuperación (mayúsculas sin espacios/guiones)
  v_clean_code := upper(regexp_replace(trim(p_code), '[\s\-]', '', 'g'));
  v_code_hash := encode(digest(v_clean_code, 'sha256'), 'hex');

  SELECT recovery_codes INTO v_codes
  FROM public.user_2fa_secrets
  WHERE user_id = p_user_id AND is_active = TRUE;

  IF v_codes IS NULL OR jsonb_array_length(v_codes) = 0 THEN
    RETURN FALSE;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_codes) LOOP
    IF (v_item->>'code_hash') = v_code_hash AND (v_item->>'used')::boolean = FALSE THEN
      v_found := TRUE;
      -- Marcar como usado
      v_new_codes := v_new_codes || jsonb_build_object(
        'code_hash', v_item->>'code_hash',
        'used', true,
        'used_at', NOW()
      );
    ELSE
      v_new_codes := v_new_codes || v_item;
    END IF;
  END LOOP;

  IF v_found THEN
    UPDATE public.user_2fa_secrets
    SET recovery_codes = v_new_codes, updated_at = NOW()
    WHERE user_id = p_user_id;
  END IF;

  RETURN v_found;
END;
$$;


-- 7. Generación Interna de 8 Códigos de Recuperación
CREATE OR REPLACE FUNCTION public.generate_recovery_codes_internal(p_user_id UUID)
RETURNS TEXT[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_chars TEXT := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  v_raw_codes TEXT[] := ARRAY[]::TEXT[];
  v_json_codes JSONB := '[]'::jsonb;
  v_code TEXT;
  v_clean_code TEXT;
  v_code_hash TEXT;
  v_i INT;
  v_j INT;
  v_rand INT;
BEGIN
  FOR v_i IN 1..8 LOOP
    v_code := '';
    FOR v_j IN 1..8 LOOP
      IF v_j = 5 THEN
        v_code := v_code || '-';
      END IF;
      v_rand := floor(random() * 32)::int + 1;
      v_code := v_code || substring(v_chars FROM v_rand FOR 1);
    END LOOP;

    v_raw_codes := array_append(v_raw_codes, v_code);
    v_clean_code := upper(regexp_replace(v_code, '[\s\-]', '', 'g'));
    v_code_hash := encode(digest(v_clean_code, 'sha256'), 'hex');
    v_json_codes := v_json_codes || jsonb_build_object(
      'code_hash', v_code_hash,
      'used', false
    );
  END LOOP;

  UPDATE public.user_2fa_secrets
  SET recovery_codes = v_json_codes, updated_at = NOW()
  WHERE user_id = p_user_id;

  RETURN v_raw_codes;
END;
$$;


-- 8. RPC GENERAR SECRETO 2FA TOTP Y QR URI
CREATE OR REPLACE FUNCTION public.generate_totp_secret()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_user_email TEXT;
  v_chars TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_secret TEXT := '';
  v_i INT;
  v_rand INT;
  v_qr_uri TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;
  IF v_user_email IS NULL OR length(v_user_email) = 0 THEN
    SELECT email INTO v_user_email FROM public.profiles WHERE user_id = v_user_id OR id = v_user_id;
  END IF;
  IF v_user_email IS NULL THEN
    v_user_email := 'usuario@raspandolaolla.com';
  END IF;

  -- Generar secret de 16 caracteres Base32
  FOR v_i IN 1..16 LOOP
    v_rand := floor(random() * 32)::int + 1;
    v_secret := v_secret || substring(v_chars FROM v_rand FOR 1);
  END LOOP;

  INSERT INTO public.user_2fa_secrets (user_id, secret_encrypted, is_active, failed_attempts, locked_until, updated_at)
  VALUES (v_user_id, v_secret, FALSE, 0, NULL, NOW())
  ON CONFLICT (user_id) DO UPDATE
  SET secret_encrypted = v_secret,
      is_active = FALSE,
      failed_attempts = 0,
      locked_until = NULL,
      updated_at = NOW();

  v_qr_uri := 'otpauth://totp/RaspandoLaOlla:' || v_user_email || '?secret=' || v_secret || '&issuer=RaspandoLaOlla&algorithm=SHA1&digits=6&period=30';

  RETURN jsonb_build_object(
    'secret', v_secret,
    'qr_uri', v_qr_uri,
    'email', v_user_email
  );
END;
$$;


-- 9. RPC OBTENER ESTADO 2FA
CREATE OR REPLACE FUNCTION public.get_2fa_status()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_mfa_enabled BOOLEAN := FALSE;
  v_has_secret BOOLEAN := FALSE;
  v_locked_until TIMESTAMPTZ := NULL;
  v_is_locked BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('is_enabled', false, 'has_secret', false, 'is_locked', false);
  END IF;

  SELECT COALESCE(is_mfa_enabled, FALSE) INTO v_mfa_enabled
  FROM public.profiles
  WHERE user_id = v_user_id OR id = v_user_id;

  SELECT is_active, (locked_until IS NOT NULL AND locked_until > NOW()), locked_until
  INTO v_has_secret, v_is_locked, v_locked_until
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  RETURN jsonb_build_object(
    'is_enabled', COALESCE(v_mfa_enabled, false),
    'has_secret', COALESCE(v_has_secret, false),
    'is_locked', COALESCE(v_is_locked, false),
    'locked_until', v_locked_until
  );
END;
$$;


-- 10. RPC ACTIVAR 2FA TOTP
CREATE OR REPLACE FUNCTION public.enable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_sec_record RECORD;
  v_valid BOOLEAN;
  v_recovery_codes TEXT[];
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT * INTO v_sec_record
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id;

  IF v_sec_record.secret_encrypted IS NULL THEN
    RAISE EXCEPTION 'NO_SECRET_FOUND: Debes generar la configuración 2FA primero.';
  END IF;

  IF v_sec_record.locked_until IS NOT NULL AND v_sec_record.locked_until > NOW() THEN
    RAISE EXCEPTION 'MFA_LOCKED: Demasiados intentos fallidos. Intente nuevamente después de %', v_sec_record.locked_until;
  END IF;

  v_valid := public.verify_totp_code_internal(v_sec_record.secret_encrypted, p_code, 1);

  IF NOT v_valid THEN
    UPDATE public.user_2fa_secrets
    SET failed_attempts = failed_attempts + 1,
        locked_until = CASE WHEN failed_attempts + 1 >= 5 THEN NOW() + INTERVAL '15 minutes' ELSE locked_until END,
        updated_at = NOW()
    WHERE user_id = v_user_id;

    IF v_sec_record.failed_attempts + 1 >= 5 THEN
      INSERT INTO public.security_events (user_id, event_type, severity, details)
      VALUES (v_user_id, '2FA_BRUTE_FORCE_LOCK', 'CRITICAL', 'Bloqueo temporal de 2FA por 5 intentos fallidos consecutivos al activar.');
      RAISE EXCEPTION 'MFA_LOCKED: Demasiados intentos fallidos. La activación 2FA ha sido bloqueada por 15 minutos.';
    END IF;

    RAISE EXCEPTION 'INVALID_TOTP_CODE: El código 2FA ingresado es incorrecto o ha expirado.';
  END IF;

  -- Resetear intentos fallidos y activar
  UPDATE public.user_2fa_secrets
  SET is_active = TRUE, failed_attempts = 0, locked_until = NULL, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = TRUE, updated_at = NOW()
  WHERE user_id = v_user_id OR id = v_user_id;

  -- Generar 8 códigos de recuperación de emergencia
  v_recovery_codes := public.generate_recovery_codes_internal(v_user_id);

  INSERT INTO public.audit_logs (actor_id, action, target_table, new_data)
  VALUES (v_user_id, '2FA_ACTIVATED', 'user_2fa_secrets', jsonb_build_object('event', 'Autenticación 2FA activada con éxito'));

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) activada con éxito.',
    'recovery_codes', to_jsonb(v_recovery_codes)
  );
END;
$$;


-- 11. RPC DESACTIVAR 2FA TOTP
CREATE OR REPLACE FUNCTION public.disable_2fa(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_sec_record RECORD;
  v_valid BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT * INTO v_sec_record
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id AND is_active = TRUE;

  IF v_sec_record.secret_encrypted IS NULL THEN
    UPDATE public.profiles SET is_mfa_enabled = FALSE WHERE user_id = v_user_id OR id = v_user_id;
    RETURN jsonb_build_object('success', true, 'message', '2FA ya se encontraba desactivado.');
  END IF;

  IF v_sec_record.locked_until IS NOT NULL AND v_sec_record.locked_until > NOW() THEN
    RAISE EXCEPTION 'MFA_LOCKED: Demasiados intentos fallidos. Intente nuevamente en unos minutos.';
  END IF;

  -- Validar TOTP o Código de recuperación
  v_valid := public.verify_totp_code_internal(v_sec_record.secret_encrypted, p_code, 1);
  IF NOT v_valid THEN
    v_valid := public.verify_recovery_code_internal(v_user_id, p_code);
  END IF;

  IF NOT v_valid THEN
    UPDATE public.user_2fa_secrets
    SET failed_attempts = failed_attempts + 1,
        locked_until = CASE WHEN failed_attempts + 1 >= 5 THEN NOW() + INTERVAL '15 minutes' ELSE locked_until END,
        updated_at = NOW()
    WHERE user_id = v_user_id;

    RAISE EXCEPTION 'INVALID_TOTP_CODE: Código 2FA o de recuperación incorrecto.';
  END IF;

  UPDATE public.user_2fa_secrets
  SET is_active = FALSE, recovery_codes = '[]'::jsonb, failed_attempts = 0, locked_until = NULL, updated_at = NOW()
  WHERE user_id = v_user_id;

  UPDATE public.profiles
  SET is_mfa_enabled = FALSE, updated_at = NOW()
  WHERE user_id = v_user_id OR id = v_user_id;

  INSERT INTO public.audit_logs (actor_id, action, target_table, new_data)
  VALUES (v_user_id, '2FA_DISABLED', 'user_2fa_secrets', jsonb_build_object('event', 'Autenticación 2FA desactivada'));

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Autenticación en Dos Pasos (2FA) desactivada correctamente.'
  );
END;
$$;


-- 12. RPC REGENERAR CÓDIGOS DE RECUPERACIÓN
CREATE OR REPLACE FUNCTION public.regenerate_recovery_codes(p_code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_sec_record RECORD;
  v_valid BOOLEAN := FALSE;
  v_new_codes TEXT[];
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT * INTO v_sec_record
  FROM public.user_2fa_secrets
  WHERE user_id = v_user_id AND is_active = TRUE;

  IF v_sec_record.secret_encrypted IS NULL THEN
    RAISE EXCEPTION '2FA_NOT_ENABLED: Debes tener 2FA activado para regenerar códigos de recuperación.';
  END IF;

  IF v_sec_record.locked_until IS NOT NULL AND v_sec_record.locked_until > NOW() THEN
    RAISE EXCEPTION 'MFA_LOCKED: Intente nuevamente en unos minutos.';
  END IF;

  v_valid := public.verify_totp_code_internal(v_sec_record.secret_encrypted, p_code, 1);
  IF NOT v_valid THEN
    RAISE EXCEPTION 'INVALID_TOTP_CODE: Código 2FA TOTP incorrecto.';
  END IF;

  v_new_codes := public.generate_recovery_codes_internal(v_user_id);

  INSERT INTO public.audit_logs (actor_id, action, target_table, new_data)
  VALUES (v_user_id, 'RECOVERY_CODES_REGENERATED', 'user_2fa_secrets', jsonb_build_object('event', 'Nuevos códigos de recuperación generados'));

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Códigos de recuperación regenerados con éxito.',
    'recovery_codes', to_jsonb(v_new_codes)
  );
END;
$$;


-- 13. RPC VALIDAR 2FA SI ESTÁ HABILITADO EN OPERACIONES
CREATE OR REPLACE FUNCTION public.validate_2fa_if_enabled(
  p_user_id UUID,
  p_code TEXT DEFAULT NULL,
  p_action_name TEXT DEFAULT 'GENERAL'
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_mfa_enabled BOOLEAN := FALSE;
  v_sec_record RECORD;
  v_valid BOOLEAN := FALSE;
BEGIN
  SELECT COALESCE(is_mfa_enabled, FALSE) INTO v_mfa_enabled
  FROM public.profiles
  WHERE user_id = p_user_id OR id = p_user_id;

  IF NOT v_mfa_enabled THEN
    RETURN TRUE;
  END IF;

  IF p_code IS NULL OR length(trim(p_code)) = 0 THEN
    RAISE EXCEPTION 'MFA_REQUIRED: Se requiere un código 2FA TOTP de 6 dígitos para confirmar esta operación.';
  END IF;

  SELECT * INTO v_sec_record
  FROM public.user_2fa_secrets
  WHERE user_id = p_user_id AND is_active = TRUE;

  IF v_sec_record.secret_encrypted IS NULL THEN
    UPDATE public.profiles SET is_mfa_enabled = FALSE WHERE user_id = p_user_id OR id = p_user_id;
    RETURN TRUE;
  END IF;

  IF v_sec_record.locked_until IS NOT NULL AND v_sec_record.locked_until > NOW() THEN
    RAISE EXCEPTION 'MFA_LOCKED: Demasiados intentos 2FA fallidos. Intente nuevamente en unos minutos.';
  END IF;

  -- 1. Intentar validar como TOTP
  v_valid := public.verify_totp_code_internal(v_sec_record.secret_encrypted, p_code, 1);

  -- 2. Si falla TOTP, intentar código de recuperación
  IF NOT v_valid THEN
    v_valid := public.verify_recovery_code_internal(p_user_id, p_code);
  END IF;

  IF NOT v_valid THEN
    UPDATE public.user_2fa_secrets
    SET failed_attempts = failed_attempts + 1,
        locked_until = CASE WHEN failed_attempts + 1 >= 5 THEN NOW() + INTERVAL '15 minutes' ELSE locked_until END,
        updated_at = NOW()
    WHERE user_id = p_user_id;

    IF v_sec_record.failed_attempts + 1 >= 5 THEN
      INSERT INTO public.security_events (user_id, event_type, severity, details)
      VALUES (p_user_id, '2FA_BRUTE_FORCE_LOCK', 'CRITICAL', 'Bloqueo temporal de 2FA por 5 intentos fallidos en acción: ' || p_action_name);
      RAISE EXCEPTION 'MFA_LOCKED: Demasiados intentos fallidos. La verificación 2FA se ha bloqueado por 15 minutos.';
    END IF;

    RAISE EXCEPTION 'INVALID_TOTP_CODE: Código 2FA o de recuperación incorrecto o expirado.';
  END IF;

  -- Resetear intentos fallidos tras éxito
  UPDATE public.user_2fa_secrets
  SET failed_attempts = 0, locked_until = NULL, updated_at = NOW()
  WHERE user_id = p_user_id;

  INSERT INTO public.audit_logs (actor_id, action, target_table, new_data)
  VALUES (p_user_id, '2FA_ACTION_VERIFIED', 'user_2fa_secrets', jsonb_build_object('action_name', p_action_name));

  RETURN TRUE;
END;
$$;


-- 14. RPC VALIDAR ACCIÓN ADMINISTRATIVA SENSIBLE CON 2FA
CREATE OR REPLACE FUNCTION public.validate_admin_2fa_action(
  p_totp_code TEXT,
  p_action_name TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_role TEXT;
  v_mfa_enabled BOOLEAN := FALSE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  SELECT role::text INTO v_role FROM public.user_roles WHERE user_id = v_user_id LIMIT 1;
  IF v_role NOT IN ('ADMIN', 'SUPER_ADMIN', 'OPERATOR') THEN
    RAISE EXCEPTION 'UNAUTHORIZED: Solamente Administradores y Operadores pueden ejecutar esta acción.';
  END IF;

  SELECT COALESCE(is_mfa_enabled, FALSE) INTO v_mfa_enabled
  FROM public.profiles
  WHERE user_id = v_user_id OR id = v_user_id;

  IF NOT v_mfa_enabled THEN
    RAISE EXCEPTION 'MFA_SETUP_REQUIRED: Para realizar acciones administrativas sensibles debes configurar la autenticación de dos factores (2FA) en tu perfil.';
  END IF;

  IF p_totp_code IS NULL OR length(trim(p_totp_code)) = 0 THEN
    RAISE EXCEPTION 'MFA_CODE_REQUIRED: Se requiere tu código 2FA TOTP de 6 dígitos para autorizar esta acción administrativa.';
  END IF;

  PERFORM public.validate_2fa_if_enabled(v_user_id, p_totp_code, 'ADMIN_' || p_action_name);

  RETURN jsonb_build_object(
    'success', true,
    'authorized_action', p_action_name,
    'timestamp', NOW()
  );
END;
$$;


-- 15. RPC SOLICITUD DE RETIRO CON VERIFICACIÓN 2FA ATÓMICA
CREATE OR REPLACE FUNCTION public.request_withdrawal_locked(
  p_payment_account_id UUID,
  p_amount NUMERIC,
  p_idempotency_key VARCHAR,
  p_totp_code VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_user_role VARCHAR(50);
  v_profile RECORD;
  v_wallet RECORD;
  v_account RECORD;
  v_existing_req RECORD;
  v_request_id UUID;
  v_ledger_id UUID;
BEGIN
  -- 1. Verificación de Autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Usuario no autenticado';
  END IF;

  -- 2. BLOQUEO ABSOLUTO PARA ROLES TÉCNICOS
  SELECT role::text INTO v_user_role FROM public.user_roles WHERE user_id = v_user_id LIMIT 1;
  IF v_user_role IN ('ADMIN', 'SUPER_ADMIN', 'OPERATOR') THEN
    RAISE EXCEPTION 'OPERACION_DENEGADA: Los usuarios con rol Administrador u Operador no tienen permitido solicitar retiros de la plataforma.';
  END IF;

  -- 3. Verificación de Perfil y 2FA/MFA
  SELECT * INTO v_profile
  FROM public.profiles
  WHERE user_id = v_user_id OR id = v_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PROFILE_NOT_FOUND: Perfil no encontrado';
  END IF;

  -- Validación 2FA si el jugador lo tiene activado
  IF COALESCE(v_profile.is_mfa_enabled, FALSE) THEN
    PERFORM public.validate_2fa_if_enabled(v_user_id, p_totp_code, 'WITHDRAWAL_REQUEST');
  END IF;

  -- 4. Verificación de Estatus KYC y Cuenta
  IF v_profile.account_status != 'ACTIVE' THEN
    RAISE EXCEPTION 'ACCOUNT_INACTIVE: La cuenta no está activa para retiros';
  END IF;

  IF v_profile.kyc_status NOT IN ('APPROVED', 'VERIFIED') THEN
    RAISE EXCEPTION 'KYC_NOT_APPROVED: Se requiere verificación de identidad (KYC) aprobada para solicitar retiros.';
  END IF;

  -- 5. Verificación de Monto Mínimo
  IF p_amount < 100.00 THEN
    RAISE EXCEPTION 'MIN_WITHDRAWAL_NOT_MET: El monto mínimo de retiro es 100.00 Bs.';
  END IF;

  -- 6. Verificación de Cuenta de Pago Destino
  SELECT * INTO v_account
  FROM public.payment_accounts
  WHERE id = p_payment_account_id AND user_id = v_user_id AND is_active = TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_ACCOUNT_INVALID: Cuenta bancaria destino no válida o no pertenece al usuario';
  END IF;

  -- 7. Idempotencia: Verificar si la solicitud ya existe
  SELECT * INTO v_existing_req
  FROM public.withdrawal_requests
  WHERE idempotency_key = p_idempotency_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'withdrawal_id', v_existing_req.id,
      'held_amount', v_existing_req.amount,
      'message', 'Solicitud de retiro procesada previamente (Idempotente).'
    );
  END IF;

  -- 8. Obtener y Bloquear Billetera del Usuario
  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WALLET_NOT_FOUND: Billetera del usuario no encontrada';
  END IF;

  IF v_wallet.available_balance < p_amount THEN
    RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo disponible insuficiente para este retiro.';
  END IF;

  -- 9. Retención Atómica de Fondos en Wallet
  UPDATE public.wallets
  SET 
    available_balance = available_balance - p_amount,
    held_balance = held_balance + p_amount,
    updated_at = NOW()
  WHERE user_id = v_user_id;

  -- 10. Registrar Asiento Contable
  INSERT INTO public.ledger_entries (
    user_id,
    entry_type,
    amount,
    balance_before_available,
    balance_after_available,
    balance_before_held,
    balance_after_held,
    description,
    idempotency_key
  ) VALUES (
    v_user_id,
    'WITHDRAWAL_HOLD',
    p_amount,
    v_wallet.available_balance,
    v_wallet.available_balance - p_amount,
    v_wallet.held_balance,
    v_wallet.held_balance + p_amount,
    'Retención de fondos para solicitud de retiro Pago Móvil',
    p_idempotency_key || '_ledger'
  ) RETURNING id INTO v_ledger_id;

  -- 11. Crear Registro de Solicitud de Retiro
  INSERT INTO public.withdrawal_requests (
    user_id,
    payment_account_id,
    amount,
    status,
    idempotency_key,
    ledger_entry_id
  ) VALUES (
    v_user_id,
    p_payment_account_id,
    p_amount,
    'PENDING',
    p_idempotency_key,
    v_ledger_id
  ) RETURNING id INTO v_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'withdrawal_id', v_request_id,
    'held_amount', p_amount,
    'remaining_available', v_wallet.available_balance - p_amount,
    'message', 'Solicitud de retiro registrada y procesada en retención exitosamente.'
  );
END;
$$;


-- 16. RPC COMPLETAR RETIROS CON VALIDACIÓN 2FA DE OPERADOR
CREATE OR REPLACE FUNCTION public.process_withdrawal_completion(
  p_withdrawal_id UUID,
  p_bank_reference VARCHAR,
  p_idempotency_key VARCHAR,
  p_totp_code VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_operator_id UUID;
  v_withdrawal RECORD;
  v_wallet RECORD;
  v_ledger_id UUID;
BEGIN
  v_operator_id := auth.uid();
  IF v_operator_id IS NULL OR NOT public.is_operator_or_above(v_operator_id) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: Se requiere rol OPERATOR o superior';
  END IF;

  -- Validar 2FA del operador para esta acción sensible
  PERFORM public.validate_admin_2fa_action(p_totp_code, 'WITHDRAWAL_COMPLETION');

  SELECT * INTO v_withdrawal
  FROM public.withdrawal_requests
  WHERE id = p_withdrawal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WITHDRAWAL_NOT_FOUND: Solicitud de retiro no encontrada';
  END IF;

  IF v_withdrawal.status != 'PENDING' AND v_withdrawal.status != 'PROCESSING' THEN
    RAISE EXCEPTION 'INVALID_WITHDRAWAL_STATUS: La solicitud ya fue procesada (estado: %)', v_withdrawal.status;
  END IF;

  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_withdrawal.user_id
  FOR UPDATE;

  UPDATE public.wallets
  SET 
    held_balance = held_balance - v_withdrawal.amount,
    updated_at = NOW()
  WHERE id = v_wallet.id;

  v_ledger_id := gen_random_uuid();
  INSERT INTO public.ledger_entries (
    id,
    wallet_id,
    user_id,
    entry_type,
    direction,
    amount,
    balance_after_available,
    balance_after_held,
    reference_table,
    reference_id,
    idempotency_key,
    description,
    actor_id
  ) VALUES (
    v_ledger_id,
    v_wallet.id,
    v_withdrawal.user_id,
    'WITHDRAWAL_CAPTURE',
    'DEBIT',
    v_withdrawal.amount,
    v_wallet.available_balance,
    v_wallet.held_balance - v_withdrawal.amount,
    'withdrawal_requests',
    p_withdrawal_id,
    p_idempotency_key,
    'Débito definitivo por retiro completado ref: ' || p_bank_reference,
    v_operator_id
  );

  UPDATE public.withdrawal_requests
  SET 
    status = 'COMPLETED',
    bank_reference = p_bank_reference,
    processed_by = v_operator_id,
    completed_at = NOW()
  WHERE id = p_withdrawal_id;

  RETURN jsonb_build_object(
    'success', true,
    'withdrawal_id', p_withdrawal_id,
    'status', 'COMPLETED',
    'bank_reference', p_bank_reference
  );
END;
$$;


-- 17. RPC RECHAZAR RETIROS CON VALIDACIÓN 2FA DE OPERADOR
CREATE OR REPLACE FUNCTION public.process_withdrawal_rejection(
  p_withdrawal_id UUID,
  p_rejection_reason TEXT,
  p_idempotency_key VARCHAR,
  p_totp_code VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_operator_id UUID;
  v_withdrawal RECORD;
  v_wallet RECORD;
  v_ledger_id UUID;
BEGIN
  v_operator_id := auth.uid();
  IF v_operator_id IS NULL OR NOT public.is_operator_or_above(v_operator_id) THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: Se requiere rol OPERATOR o superior';
  END IF;

  -- Validar 2FA del operador para esta acción sensible
  PERFORM public.validate_admin_2fa_action(p_totp_code, 'WITHDRAWAL_REJECTION');

  SELECT * INTO v_withdrawal
  FROM public.withdrawal_requests
  WHERE id = p_withdrawal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WITHDRAWAL_NOT_FOUND: Solicitud de retiro no encontrada';
  END IF;

  IF v_withdrawal.status != 'PENDING' AND v_withdrawal.status != 'PROCESSING' THEN
    RAISE EXCEPTION 'INVALID_WITHDRAWAL_STATUS: La solicitud ya fue procesada (estado: %)', v_withdrawal.status;
  END IF;

  SELECT * INTO v_wallet
  FROM public.wallets
  WHERE user_id = v_withdrawal.user_id
  FOR UPDATE;

  UPDATE public.wallets
  SET 
    available_balance = available_balance + v_withdrawal.amount,
    held_balance = held_balance - v_withdrawal.amount,
    updated_at = NOW()
  WHERE id = v_wallet.id;

  v_ledger_id := gen_random_uuid();
  INSERT INTO public.ledger_entries (
    id,
    wallet_id,
    user_id,
    entry_type,
    direction,
    amount,
    balance_after_available,
    balance_after_held,
    reference_table,
    reference_id,
    idempotency_key,
    description,
    actor_id
  ) VALUES (
    v_ledger_id,
    v_wallet.id,
    v_withdrawal.user_id,
    'WITHDRAWAL_RELEASE',
    'CREDIT',
    v_withdrawal.amount,
    v_wallet.available_balance + v_withdrawal.amount,
    v_wallet.held_balance - v_withdrawal.amount,
    'withdrawal_requests',
    p_withdrawal_id,
    p_idempotency_key,
    'Liberación de fondos por retiro rechazado: ' || COALESCE(p_rejection_reason, 'Sin motivo especificado'),
    v_operator_id
  );

  UPDATE public.withdrawal_requests
  SET 
    status = 'REJECTED',
    rejection_reason = p_rejection_reason,
    processed_by = v_operator_id,
    completed_at = NOW()
  WHERE id = p_withdrawal_id;

  RETURN jsonb_build_object(
    'success', true,
    'withdrawal_id', p_withdrawal_id,
    'status', 'REJECTED'
  );
END;
$$;


