-- MIGRACIÓN 76: 074_fix_game_tables_schema_and_abandon.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 074 — CORRECCIÓN DE ENUMS EN TABLES, RPC START GAME Y ABANDONOS
-- ==============================================================================
-- Esta migración resuelve dos fallos clave detectados en producción de Supabase:
-- 
-- 1. ERROR: column "started_at" of relation "game_tables" does not exist
--    Se redefine `start_game_session_secure` para no intentar actualizar la columna inexistente
--    `started_at` en `public.game_tables`. Solamente se actualizan `status` y `updated_at`.
-- 
-- 2. ERROR: invalid input value for enum table_status_enum: "WAITING"
--    Se redefinen `abandon_game_table_secure`, `admin_disconnect_player_secure` y
--    `admin_cleanup_all_invalid_tables` utilizando castings seguros `status::text`
--    en las comparaciones de estados de mesas para prevenir errores de validación de enums
--    cuando se comparan con estados del frontend que no existen físicamente en la DB.
-- ==============================================================================

-- 1. Redefinición Segura de start_game_session_secure (Remover actualizacion de started_at en game_tables)
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_players JSONB := '[]'::jsonb;
  v_player_order JSONB := '[]'::jsonb;
  v_lives JSONB := '{}'::jsonb;
  v_scores JSONB := '{}'::jsonb;
  v_player_record RECORD;
  v_session_id UUID;
  v_first_turn_user_id UUID;
  v_initial_state JSONB;
  v_deadline TIMESTAMPTZ;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión';
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  IF v_table.host_user_id <> v_user_id THEN
    RAISE EXCEPTION 'ONLY_HOST_CAN_START: Únicamente el Anfitrión de la mesa puede iniciar la partida';
  END IF;

  -- Si ya existe una sesión activa o en curso, retornarla
  -- Se aplica casting seguro (status::text) para evitar error 22P02 con 'IN_PROGRESS'
  SELECT id INTO v_session_id
  FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS');

  IF v_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'session_id', v_session_id,
      'table_id', p_table_id,
      'already_active', true
    );
  END IF;

  -- Compilar lista de jugadores activos
  FOR v_player_record IN (
    SELECT gtp.user_id, gtp.seat_number, p.display_name, p.first_name, p.last_name, p.avatar_url
    FROM public.game_table_players gtp
    JOIN public.profiles p ON p.user_id = gtp.user_id
    WHERE gtp.table_id = p_table_id
      AND gtp.status != 'LEFT'::player_table_status_enum
    ORDER BY gtp.seat_number ASC
  ) LOOP
    IF v_first_turn_user_id IS NULL THEN
      v_first_turn_user_id := v_player_record.user_id;
    END IF;

    v_player_order := v_player_order || to_jsonb(v_player_record.user_id::text);
    v_lives := jsonb_set(v_lives, ARRAY[v_player_record.user_id::text], '3'::jsonb);
    v_scores := jsonb_set(v_scores, ARRAY[v_player_record.user_id::text], '0'::jsonb);

    v_players := v_players || jsonb_build_object(
      'userId', v_player_record.user_id,
      'seatNumber', v_player_record.seat_number,
      'displayName', COALESCE(NULLIF(trim(v_player_record.display_name), ''), trim(COALESCE(v_player_record.first_name, '') || ' ' || COALESCE(v_player_record.last_name, ''))),
      'avatarUrl', v_player_record.avatar_url,
      'lives', 3
    );
  END LOOP;

  IF v_first_turn_user_id IS NULL THEN
    v_first_turn_user_id := v_user_id;
  END IF;

  v_deadline := NOW() + INTERVAL '10 seconds';
  v_session_id := gen_random_uuid();

  v_initial_state := jsonb_build_object(
    'status', 'PLAYING',
    'playerOrder', v_player_order,
    'players', v_players,
    'currentTurnUserId', v_first_turn_user_id,
    'lives', v_lives,
    'scores', v_scores,
    'round', 1
  );

  -- Crear sesión en game_sessions usando el estado ACTIVE del enum
  INSERT INTO public.game_sessions (
    id, table_id, game_type, session_number, status, current_state,
    current_turn_user_id, turn_deadline_at, started_at
  ) VALUES (
    v_session_id, p_table_id, v_table.game_type, 1, 'ACTIVE'::session_status_enum,
    v_initial_state, v_first_turn_user_id, v_deadline, NOW()
  );

  -- Actualizar estado de la mesa a ACTIVE de forma segura (sin started_at que no existe en el esquema de tablas)
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'table_id', p_table_id,
    'current_turn_user_id', v_first_turn_user_id,
    'turn_deadline_at', v_deadline,
    'already_active', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID) TO authenticated, service_role, anon;


-- 2. Redefinición Segura de abandon_game_table_secure (con castings status::text seguros)
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_active_players_count INT;
  v_remaining_player RECORD;
  v_effective_idempotency VARCHAR(100);
  v_settle_result JSONB;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_amount NUMERIC(15, 2) := 0.00;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para abandonar la mesa';
  END IF;

  -- Bloquear mesa y verificar existencia
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa de juego no existe';
  END IF;

  -- Verificar si el jugador pertenece a la mesa
  SELECT * INTO v_player 
  FROM public.game_table_players 
  WHERE table_id = p_table_id AND user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_LEFT_OR_NOT_IN_TABLE'
    );
  END IF;

  -- Cambiar el estado del participante en game_table_players a 'LEFT'
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND user_id = v_caller_id;

  -- Buscar sesión de juego asociada
  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  ELSE
    SELECT * INTO v_session FROM public.game_sessions
    WHERE table_id = p_table_id AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED')
    ORDER BY created_at DESC LIMIT 1
    FOR UPDATE;
  END IF;

  -- Procesar liberación/devolución de entrada si la partida NO ha sido liquidada/capturada y la mesa tiene entrada
  IF v_table.entry_fee > 0.00 AND (v_session.id IS NULL OR v_session.status NOT IN ('SETTLED', 'ACTIVE')) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ledger_entries
      WHERE user_id = v_caller_id
        AND reference_table = 'game_tables'
        AND reference_id = p_table_id
        AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
    ) INTO v_already_refunded;

    IF NOT v_already_refunded THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_caller_id FOR UPDATE;
      IF FOUND THEN
        IF v_wallet.held_balance >= v_table.entry_fee THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              held_balance = held_balance - v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        ELSE
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              total_balance = total_balance + v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        END IF;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_id,
          description,
          idempotency_key,
          created_at
        ) VALUES (
          v_wallet.id,
          v_caller_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          v_wallet.held_balance,
          'game_tables',
          p_table_id,
          'Reembolso por abandono de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
          'abandon_refund_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text,
          NOW()
        );
        v_refund_amount := v_table.entry_fee;
      END IF;
    END IF;
  END IF;

  -- Contar jugadores activos restantes
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

  -- Actualizar el contador de la mesa y estado (con casting status::text seguro contra WAITING)
  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  -- Si la sesión estaba activa y queda un ÚNICO jugador restante -> Declarar ganador por abandono
  IF v_active_players_count = 1 AND v_session.id IS NOT NULL AND v_session.status::text = 'ACTIVE' THEN
    SELECT user_id INTO v_remaining_player
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY')
    LIMIT 1;

    IF v_remaining_player.user_id IS NOT NULL THEN
      v_settle_result := public.settle_game_session(
        v_session.id,
        ARRAY[v_remaining_player.user_id],
        1,
        'SETTLE_ABANDON_' || v_effective_idempotency
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'WINNER_DECLARED_BY_ABANDON',
        'winner_user_id', v_remaining_player.user_id,
        'refund_amount', v_refund_amount,
        'settlement', v_settle_result
      );
    END IF;
  END IF;

  -- Si quedan 0 jugadores activos -> Cerrar mesa y cancelar sesión huérfana
  IF v_active_players_count = 0 THEN
    IF v_session.id IS NOT NULL AND v_session.status::text NOT IN ('SETTLED', 'CANCELLED') THEN
      UPDATE public.game_sessions
      SET status = 'CANCELLED'::session_status_enum, ended_at = NOW()
      WHERE id = v_session.id;
    END IF;

    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum, closed_at = NOW(), updated_at = NOW()
    WHERE id = p_table_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'TABLE_CLOSED_NO_PLAYERS',
      'refund_amount', v_refund_amount
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'LEFT_SUCCESSFULLY',
    'refund_amount', v_refund_amount
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, VARCHAR) TO authenticated, anon, service_role;


-- 3. Redefinición Segura de admin_disconnect_player_secure (con castings status::text seguros)
CREATE OR REPLACE FUNCTION public.admin_disconnect_player_secure(
  p_table_id UUID,
  p_user_id UUID,
  p_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_caller_role VARCHAR(50);
  v_table RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_active_players_count INT;
  v_already_refunded BOOLEAN := FALSE;
  v_refunded BOOLEAN := FALSE;
  v_effective_reason TEXT;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR NOT public.is_operator_or_above(v_caller_id) THEN
    RAISE EXCEPTION 'ACCESO_RESTRINGIDO: Se requieren permisos de Operador o Administrador para desconectar jugadores';
  END IF;

  SELECT role::text INTO v_caller_role FROM public.user_roles WHERE user_id = v_caller_id LIMIT 1;
  v_caller_role := COALESCE(v_caller_role, 'ADMIN');

  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  SELECT * INTO v_player 
  FROM public.game_table_players 
  WHERE table_id = p_table_id AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'El jugador no se encuentra en la mesa');
  END IF;

  v_effective_reason := COALESCE(NULLIF(trim(p_reason), ''), 'Desconexión ejecutada por administración');

  -- Actualizar estado del jugador
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND user_id = p_user_id;

  -- Comprobar si corresponde reembolso
  IF COALESCE(v_table.entry_fee, 0) > 0 THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ledger_entries
      WHERE user_id = p_user_id
        AND reference_table = 'game_tables'
        AND reference_id = p_table_id
        AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
    ) INTO v_already_refunded;

    IF NOT v_already_refunded THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id FOR UPDATE;
      IF FOUND THEN
        IF v_wallet.held_balance >= v_table.entry_fee THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              held_balance = held_balance - v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        ELSE
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              total_balance = total_balance + v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        END IF;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_id,
          description,
          idempotency_key,
          created_at
        ) VALUES (
          v_wallet.id,
          p_user_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          v_wallet.held_balance,
          'game_tables',
          p_table_id,
          'Reembolso por desconexión administrativa de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
          'admin_disconnect_' || p_table_id::text || '_' || p_user_id::text || '_' || extract(epoch from now())::text,
          NOW()
        );
        v_refunded := TRUE;
      END IF;
    END IF;
  END IF;

  -- Recalcular jugadores activos
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

  -- Actualizar mesa (con castings status::text seguros contra WAITING)
  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  -- Registro en auditoría
  INSERT INTO public.audit_logs (
    actor_id,
    actor_role,
    action,
    resource_type,
    resource_id,
    severity,
    metadata
  ) VALUES (
    v_caller_id,
    v_caller_role,
    'ADMIN_DISCONNECT_PLAYER',
    'GAME_TABLE',
    p_table_id::text,
    'WARNING'::audit_severity_enum,
    jsonb_build_object(
      'admin_user_id', v_caller_id,
      'disconnected_user_id', p_user_id,
      'table_id', p_table_id,
      'reason', v_effective_reason,
      'refunded', v_refunded
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', 'DISCONNECTED_SUCCESSFULLY',
    'refunded', v_refunded
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_disconnect_player_secure(UUID, UUID, TEXT) TO authenticated, service_role;


-- 4. Redefinición Segura de admin_cleanup_all_invalid_tables (con castings status::text seguros)
CREATE OR REPLACE FUNCTION public.admin_cleanup_all_invalid_tables()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_rec RECORD;
  v_cleaned_count INT := 0;
  v_cleaned_ids UUID[] := ARRAY[]::UUID[];
BEGIN
  FOR v_rec IN 
    SELECT DISTINCT gt.id
    FROM public.game_tables gt
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE 
      -- Caso 1: Mesa OPEN/FULL/ACTIVE pero sesión FINISHED/SETTLED/CANCELLED (con castings seguros)
      (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED'))
      -- Caso 2: Mesa OPEN/FULL expirada
      OR (gt.status::text IN ('OPEN', 'FULL', 'WAITING') AND gt.expires_at <= NOW())
      -- Caso 3: Mesa OPEN antigua abandonada con <= 1 jugador
      OR (gt.status::text = 'OPEN' AND gt.created_at < NOW() - INTERVAL '30 minutes' AND gt.current_players_count <= 1)
  LOOP
    PERFORM public.admin_terminate_game_table(v_rec.id, 'Limpieza automática de mesas inválidas o abandonadas', TRUE);
    v_cleaned_count := v_cleaned_count + 1;
    v_cleaned_ids := array_append(v_cleaned_ids, v_rec.id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'cleaned_count', v_cleaned_count,
    'cleaned_table_ids', v_cleaned_ids
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_cleanup_all_invalid_tables() TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 77: 075_bingo_automated_rate_limit.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 075: EXTRACCIÓN AUTOMATIZADA DE BALOTAS Y SEGURIDAD
-- ==============================================================================
-- Esta migración actualiza `rpc_draw_bingo_ball_secure` para permitir que mesas
-- automatizadas/sistemas (sin anfitrión humano) auto-extraigan balotas de forma segura.
-- Valida que el emisor sea un jugador legítimo de la mesa si es automatizada,
-- aplica rate-limiting basado en `call_interval_ms` para evitar spam,
-- y activa la sesión de juego y la mesa de forma atómica en el primer tiro.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.rpc_draw_bingo_ball_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_total_balls INT;
  v_available INT[];
  v_next_ball INT;
  v_idx INT;
  v_event_id TEXT;
  v_commitment_hash TEXT;
  v_new_seq INT;
  v_result_json JSONB;
  v_idempotency_key TEXT;
  v_existing_event RECORD;
  v_is_automated BOOLEAN;
  v_call_interval INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  v_idempotency_key := COALESCE(p_idempotency_key, 'draw_ball_' || p_session_id::text || '_' || encode(gen_random_bytes(6), 'hex'));

  -- 1. Validar idempotencia primero
  SELECT * INTO v_existing_event
  FROM public.rng_events
  WHERE session_id = p_session_id AND idempotency_key = v_idempotency_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent', true,
      'ball', (v_existing_event.result->>'ball')::INT,
      'event_id', v_existing_event.event_id,
      'commitment_hash', v_existing_event.commitment_hash
    );
  END IF;

  -- 2. Obtener y bloquear la Sesión
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  -- 3. Obtener la Mesa de Juego
  SELECT * INTO v_table FROM public.game_tables WHERE id = v_session.table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'MESA_DE_JUEGO_NO_ENCONTRADA');
  END IF;

  v_is_automated := COALESCE((v_table.config->>'automated')::boolean, false);

  -- 4. Validar permisos de extracción (Host, creador, operador, admin, o jugador en mesas automatizadas)
  IF NOT (
    (v_table.host_user_id IS NOT NULL AND v_user_id = v_table.host_user_id)
    OR (v_table.host_user_id IS NULL AND v_table.created_by IS NOT NULL AND v_user_id = v_table.created_by)
    OR (v_is_automated AND EXISTS (
         SELECT 1 FROM public.game_table_players
         WHERE table_id = v_table.id AND user_id = v_user_id AND status != 'LEFT'::player_table_status_enum
       ))
    OR public.is_operator_or_above(v_user_id)
    OR auth.role() = 'service_role'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'HOST_ONLY: Solo el anfitrión legítimo o jugadores activos en mesas automatizadas pueden extraer balotas.');
  END IF;

  -- 5. Rate-Limiting para Sorteos Automatizados
  IF v_is_automated THEN
    v_call_interval := COALESCE((v_table.config->>'call_interval_ms')::INT, 3500);
    IF v_session.updated_at IS NOT NULL AND NOW() < (v_session.updated_at + (v_call_interval || ' milliseconds')::INTERVAL) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'RATE_LIMIT: Debes esperar el intervalo establecido entre balotas (' || (v_call_interval::numeric / 1000.0) || 's).'
      );
    END IF;
  END IF;

  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_total_balls := COALESCE((v_current_state->>'totalBalls')::INT, 75);

  -- Extraer bolas ya jugadas
  SELECT ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_current_state->'drawnBalls', '[]'::jsonb))::INT)
  INTO v_drawn_balls;

  -- Calcular balotas disponibles
  SELECT ARRAY(
    SELECT s FROM generate_series(1, v_total_balls) s
    WHERE NOT (s = ANY(v_drawn_balls))
  ) INTO v_available;

  IF array_length(v_available, 1) IS NULL OR array_length(v_available, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Se han extraído todas las balotas de la balotera.'
    );
  END IF;

  -- Seleccionar bola usando RNG seguro
  v_idx := public.fn_secure_rng_int(1, array_length(v_available, 1));
  v_next_ball := v_available[v_idx];

  v_event_id := 'rng_bingo_' || encode(gen_random_bytes(8), 'hex');
  v_commitment_hash := encode(digest(p_session_id::text || '_' || v_next_ball::text || '_' || v_event_id, 'sha256'), 'hex');

  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_new_seq
  FROM public.rng_events WHERE session_id = p_session_id;

  v_result_json := jsonb_build_object(
    'ball', v_next_ball,
    'total_drawn', array_length(v_drawn_balls, 1) + 1,
    'drawn_by', v_user_id
  );

  -- Registrar auditoría RNG
  INSERT INTO public.rng_events (
    event_id,
    session_id,
    table_id,
    user_id,
    game_type,
    event_type,
    sequence_number,
    result,
    commitment_hash,
    idempotency_key
  ) VALUES (
    v_event_id,
    p_session_id,
    v_session.table_id,
    v_user_id,
    v_session.game_type,
    'DRAW_BINGO_BALL',
    v_new_seq,
    v_result_json,
    v_commitment_hash,
    v_idempotency_key
  );

  -- Actualizar estado de la partida
  v_drawn_balls := array_append(v_drawn_balls, v_next_ball);
  v_current_state := jsonb_set(v_current_state, '{drawnBalls}', to_jsonb(v_drawn_balls));
  v_current_state := jsonb_set(v_current_state, '{currentBall}', to_jsonb(v_next_ball));

  -- 6. Activación Atómica de la Mesa y Sesión al Extraer la Primera Balota
  IF array_length(v_drawn_balls, 1) = 1 THEN
    -- Cambiar mesa a ACTIVE
    UPDATE public.game_tables
    SET status = 'ACTIVE'::table_status_enum,
        updated_at = NOW()
    WHERE id = v_session.table_id;

    -- Cambiar sesión a ACTIVE
    UPDATE public.game_sessions
    SET status = 'ACTIVE'::session_status_enum,
        started_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Actualizar config de la mesa si es necesario
    UPDATE public.game_tables
    SET config = config || jsonb_build_object('status', 'ACTIVE')
    WHERE id = v_session.table_id;

    -- Actualizar estado del juego en la sesión
    v_current_state := jsonb_set(v_current_state, '{status}', '"in_progress"'::jsonb);
  ELSE
    -- Solo actualizar sesión timestamps
    UPDATE public.game_sessions
    SET updated_at = NOW()
    WHERE id = p_session_id;
  END IF;

  UPDATE public.game_sessions
  SET current_state = v_current_state,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'is_idempotent', false,
    'ball', v_next_ball,
    'event_id', v_event_id,
    'commitment_hash', v_commitment_hash
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_draw_bingo_ball_secure(UUID, TEXT) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 78: 076_fix_already_in_active_table_lobby.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- RASPANDO LA OLLA — MIGRACIÓN 076: CORRECCIÓN DE ALREADY_IN_ACTIVE_TABLE EN LOBBY
--
-- Esta migración soluciona de forma definitiva el error ALREADY_IN_ACTIVE_TABLE cuando un usuario intenta
-- crear una mesa pero tiene una participación huérfana o inactiva en una mesa del mismo juego que nunca inició.
-- En lugar de arrojar un error y bloquear al jugador indefinidamente, la función create_game_table_secure
-- detecta y auto-abandona de forma limpia y segura (reembolsando su entrada) cualquier mesa previa no iniciada.

CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_balance NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- AUTO-ABANDONO SEGURO DE MESAS HUÉRFANAS O NO INICIADAS:
  -- Si el usuario tiene participaciones activas en mesas del mismo juego que aún no han iniciado su partida
  -- (es decir, mesas OPEN o FULL, donde la sesión es nula o está en espera/esperando), las abandonamos de forma
  -- transparente y segura llamando a abandon_game_table_secure para reembolsar la entrada al saldo disponible.
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
      AND (gs.id IS NULL OR gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
  LOOP
    BEGIN
      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      -- Silenciador seguro para evitar romper el flujo principal si un abandono específico falla
      NULL;
    END;
  END LOOP;

  -- Prevenir si ya tiene una mesa activa REAL (es decir, con una sesión en curso/activa)
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND gs.status::text = 'ACTIVE';

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego.';
  END IF;

  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, máximo 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players >= 4 THEN 2
    ELSE p_max_players 
  END;

  -- Verificar saldo para la retención del anfitrión si p_entry_fee > 0
  IF p_entry_fee > 0 THEN
    SELECT available_balance INTO v_wallet_balance
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_balance IS NULL OR v_wallet_balance < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para crear la mesa (% Bs.)', p_entry_fee;
    END IF;
  END IF;

  -- Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || p_game_type);
  v_expires_at := NOW() + INTERVAL '24 hours';
  v_table_id := gen_random_uuid();

  -- 1. Insertar mesa
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, visibility, entry_fee, min_players, max_players,
    current_players_count, status, invite_code, expires_at, config
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, p_visibility, p_entry_fee, v_min_players, p_max_players,
    1, 'OPEN'::table_status_enum, v_invite_code, v_expires_at,
    COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name)
  );

  -- 2. Deducir saldo y crear ledger entry si hay cuota
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE user_id = v_user_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id, user_id, entry_type, amount, balance_after, reference_id, description, status
    ) VALUES (
      v_ledger_id, v_user_id, 'GAME_ENTRY_HOLD'::ledger_entry_type_enum, -p_entry_fee,
      (v_wallet_balance - p_entry_fee), v_table_id,
      'Retención de entrada al crear mesa #' || substring(v_table_id::text from 1 for 8),
      'COMPLETED'::ledger_status_enum
    );
  END IF;

  -- 3. Auto-asentar al Anfitrión en Asiento #1
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'host_user_id', v_user_id,
    'seat_number', 1,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'current_players_count', 1,
    'status', 'OPEN',
    'created_at', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 79: 077_fix_active_table_detection.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 077
-- CORRECCIÓN COGNITIVA Y DEFINITIVA DE DETECCIÓN DE MESAS ACTIVAS EN LOBBY
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_balance NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- Bloquear billetera al inicio para consistencia transaccional y evitar condiciones de carrera concurrentes
  -- Esto cumple con los Requisitos de Concurrencia de Múltiples Hilos (Test 07)
  IF p_entry_fee > 0 THEN
    SELECT available_balance INTO v_wallet_balance
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- 2. AUTO-ABANDONO SEGURO DE PARTICIPACIONES HUÉRFANAS, OBSOLETAS O COMPLETADAS DE FACTO:
  -- Recorre todas las mesas del mismo juego donde el usuario esté registrado como participante activo,
  -- pero que de acuerdo a las reglas del negocio o por inactividad prolongada (stale), ya no sean válidas.
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        -- Caso A: La mesa está abierta o llena pero no tiene sesión (huérfana)
        (gt.status::text IN ('OPEN', 'FULL') AND gs.id IS NULL)
        -- Caso B: La sesión existe pero no ha iniciado la partida (lista, en espera, pausada)
        OR (gs.id IS NOT NULL AND gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
        -- Caso C: La sesión está finalizada o liquidada de facto en la base de datos
        OR (gs.id IS NOT NULL AND (
             gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED')
             -- O ya cuenta con un ganador definido en el estado JSONB (como en Bingo al finalizar)
             OR (gs.current_state->>'winnerUserId') IS NOT NULL AND (gs.current_state->>'winnerUserId') <> ''
           ))
        -- Caso D: La mesa o sesión está colgada/stale por antigüedad o inactividad superior a 1 hora
        OR (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND (
             gt.created_at < NOW() - INTERVAL '1 hour'
             OR (gs.id IS NOT NULL AND gs.updated_at < NOW() - INTERVAL '1 hour')
           ))
        -- Caso E: La mesa ya cumplió su fecha límite de expiración
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      -- Si la sesión está colgada en estado ACTIVE pero es obsoleta/terminada de facto, la forzamos a 'CANCELLED'
      -- para que abandon_game_table_secure sepa que NO es un juego activo vivo y realice el reembolso seguro.
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              updated_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      -- Llamada segura para realizar el reembolso correspondiente al saldo disponible (previniendo doble reembolso)
      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_077_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      -- Silenciador seguro para evitar romper el flujo principal si una mesa específica falla en abandonar
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL:
  -- Solo se bloquea al usuario si realmente tiene un juego en curso, activo, reciente, no expirado y sin ganador.
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    -- La sesión de juego debe estar activa y sin ganador
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    -- Excluir sesiones/mesas obsoletas de más de 1 hora
    AND gs.updated_at >= NOW() - INTERVAL '1 hour'
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    -- Y no haber expirado
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites de Jugadores
  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, maximum 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players >= 4 THEN 2
    ELSE p_max_players 
  END;

  -- 5. Validación de Saldo Disponible para Cuota de Entrada (si p_entry_fee > 0)
  IF p_entry_fee > 0 THEN
    -- v_wallet_balance ya fue bloqueado mediante SELECT ... FOR UPDATE al inicio de la función
    IF v_wallet_balance IS NULL OR v_wallet_balance < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para crear la mesa (% Bs.)', p_entry_fee;
    END IF;
  END IF;

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || p_game_type);
  v_expires_at := NOW() + INTERVAL '24 hours';
  v_table_id := gen_random_uuid();

  -- 7. Insertar Nueva Mesa de Juego
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, visibility, entry_fee, min_players, max_players,
    current_players_count, status, invite_code, expires_at, config
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, p_visibility, p_entry_fee, v_min_players, p_max_players,
    1, 'OPEN'::table_status_enum, v_invite_code, v_expires_at,
    COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name)
  );

  -- 8. Deducción de Saldo de la Olla y Creación de Ledger Entry
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE user_id = v_user_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id, user_id, entry_type, amount, balance_after, reference_id, description, status
    ) VALUES (
      v_ledger_id, v_user_id, 'GAME_ENTRY_HOLD'::ledger_entry_type_enum, -p_entry_fee,
      (v_wallet_balance - p_entry_fee), v_table_id,
      'Retención de entrada al crear mesa #' || substring(v_table_id::text from 1 for 8),
      'COMPLETED'::ledger_status_enum
    );
  END IF;

  -- 9. Asentamiento del Anfitrión de la Mesa en Asiento #1
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'host_user_id', v_user_id,
    'seat_number', 1,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'current_players_count', 1,
    'status', 'OPEN',
    'created_at', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 80: 078_fix_create_game_table_alias_and_bingo_updated_at.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 078
-- CORRECCIÓN DEFINITIVA DE REFERENCIA DE ALIAS SQL (gt.updated_at vs gs.updated_at)
-- ==============================================================================
-- Causa Raíz Identificada (Error 42703):
-- La tabla `public.game_tables` (alias `gt`) contiene la columna `updated_at`
-- (añadida en migración 053), mientras que `public.game_sessions` (alias `gs`)
-- utiliza `created_at`, `started_at` y `ended_at` (definidos en migración 009).
-- La función `create_game_table_secure` (migración 077) referenció erróneamente
-- el alias `gs.updated_at` en lugar de `gt.updated_at`.
-- Esta migración corrige las funciones RPC para utilizar las columnas canónicas
-- del esquema sin alterar innecesariamente las tablas.
-- ==============================================================================

-- 1. CORREGIR FUNCIÓN RPC: create_game_table_secure
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_balance NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- Bloquear billetera al inicio para consistencia transaccional y evitar condiciones de carrera concurrentes
  IF p_entry_fee > 0 THEN
    SELECT available_balance INTO v_wallet_balance
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- 2. AUTO-ABANDONO SEGURO DE PARTICIPACIONES HUÉRFANAS, OBSOLETAS O COMPLETADAS DE FACTO:
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        -- Caso A: La mesa está abierta o llena pero no tiene sesión (huérfana)
        (gt.status::text IN ('OPEN', 'FULL') AND gs.id IS NULL)
        -- Caso B: La sesión existe pero no ha iniciado la partida (lista, en espera, pausada)
        OR (gs.id IS NOT NULL AND gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
        -- Caso C: La sesión está finalizada o liquidada de facto en la base de datos
        OR (gs.id IS NOT NULL AND (
             gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED')
             -- O ya cuenta con un ganador definido en el estado JSONB (como en Bingo al finalizar)
             OR (gs.current_state->>'winnerUserId') IS NOT NULL AND (gs.current_state->>'winnerUserId') <> ''
           ))
        -- Caso D: La mesa o sesión está colgada/stale por antigüedad o inactividad superior a 1 hora (usa gt.updated_at)
        OR (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND (
             gt.created_at < NOW() - INTERVAL '1 hour'
             OR (gt.updated_at IS NOT NULL AND gt.updated_at < NOW() - INTERVAL '1 hour')
           ))
        -- Caso E: La mesa ya cumplió su fecha límite de expiración
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      -- Si la sesión está colgada en estado ACTIVE pero es obsoleta/terminada de facto, la forzamos a 'CANCELLED'
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              ended_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      -- Llamada segura para realizar el reembolso correspondiente al saldo disponible
      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_078_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL:
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    -- La sesión de juego debe estar activa y sin ganador
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    -- Excluir sesiones/mesas obsoletas de más de 1 hora (referenciando gt.updated_at y gt.created_at)
    AND (gt.updated_at IS NULL OR gt.updated_at >= NOW() - INTERVAL '1 hour')
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    -- Y no haber expirado
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites de Jugadores
  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, maximum 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players >= 4 THEN 2
    ELSE p_max_players 
  END;

  -- 5. Validación de Saldo Disponible para Cuota de Entrada (si p_entry_fee > 0)
  IF p_entry_fee > 0 THEN
    IF v_wallet_balance IS NULL OR v_wallet_balance < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para crear la mesa (% Bs.)', p_entry_fee;
    END IF;
  END IF;

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || p_game_type);
  v_expires_at := NOW() + INTERVAL '24 hours';
  v_table_id := gen_random_uuid();

  -- 7. Insertar Nueva Mesa de Juego
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, visibility, entry_fee, min_players, max_players,
    current_players_count, status, invite_code, expires_at, config
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, p_visibility, p_entry_fee, v_min_players, p_max_players,
    1, 'OPEN'::table_status_enum, v_invite_code, v_expires_at,
    COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name)
  );

  -- 8. Deducción de Saldo de la Olla y Creación de Ledger Entry
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE user_id = v_user_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id, user_id, entry_type, amount, balance_after, reference_id, description, status
    ) VALUES (
      v_ledger_id, v_user_id, 'GAME_ENTRY_HOLD'::ledger_entry_type_enum, -p_entry_fee,
      (v_wallet_balance - p_entry_fee), v_table_id,
      'Retención de entrada al crear mesa #' || substring(v_table_id::text from 1 for 8),
      'COMPLETED'::ledger_status_enum
    );
  END IF;

  -- 9. Asentamiento del Anfitrión de la Mesa en Asiento #1
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'host_user_id', v_user_id,
    'seat_number', 1,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'current_players_count', 1,
    'status', 'OPEN',
    'created_at', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;


-- 2. CORREGIR FUNCIÓN RPC: rpc_draw_bingo_ball_secure (RATE LIMIT SOBRE game_tables.updated_at)
CREATE OR REPLACE FUNCTION public.rpc_draw_bingo_ball_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_total_balls INT;
  v_available INT[];
  v_next_ball INT;
  v_idx INT;
  v_event_id TEXT;
  v_commitment_hash TEXT;
  v_new_seq INT;
  v_result_json JSONB;
  v_idempotency_key TEXT;
  v_existing_event RECORD;
  v_is_automated BOOLEAN;
  v_call_interval INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  v_idempotency_key := COALESCE(p_idempotency_key, 'draw_ball_' || p_session_id::text || '_' || encode(gen_random_bytes(6), 'hex'));

  -- 1. Validar idempotencia primero
  SELECT * INTO v_existing_event
  FROM public.rng_events
  WHERE session_id = p_session_id AND idempotency_key = v_idempotency_key;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent', true,
      'ball', (v_existing_event.result->>'ball')::INT,
      'event_id', v_existing_event.event_id,
      'commitment_hash', v_existing_event.commitment_hash
    );
  END IF;

  -- 2. Obtener y bloquear la Sesión
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  -- 3. Obtener la Mesa de Juego
  SELECT * INTO v_table FROM public.game_tables WHERE id = v_session.table_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'MESA_DE_JUEGO_NO_ENCONTRADA');
  END IF;

  v_is_automated := COALESCE((v_table.config->>'automated')::boolean, false);

  -- 4. Validar permisos de extracción (Host, creador, operador, admin, o jugador en mesas automatizadas)
  IF NOT (
    (v_table.host_user_id IS NOT NULL AND v_user_id = v_table.host_user_id)
    OR (v_table.host_user_id IS NULL AND v_table.created_by IS NOT NULL AND v_user_id = v_table.created_by)
    OR (v_is_automated AND EXISTS (
         SELECT 1 FROM public.game_table_players
         WHERE table_id = v_table.id AND user_id = v_user_id AND status != 'LEFT'::player_table_status_enum
       ))
    OR public.is_operator_or_above(v_user_id)
    OR auth.role() = 'service_role'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'HOST_ONLY: Solo el anfitrión legítimo o jugadores activos en mesas automatizadas pueden extraer balotas.');
  END IF;

  -- 5. Rate-Limiting para Sorteos Automatizados (utiliza v_table.updated_at)
  IF v_is_automated THEN
    v_call_interval := COALESCE((v_table.config->>'call_interval_ms')::INT, 3500);
    IF v_table.updated_at IS NOT NULL AND NOW() < (v_table.updated_at + (v_call_interval || ' milliseconds')::INTERVAL) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'RATE_LIMIT: Debes esperar el intervalo establecido entre balotas (' || (v_call_interval::numeric / 1000.0) || 's).'
      );
    END IF;
  END IF;

  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_total_balls := COALESCE((v_current_state->>'totalBalls')::INT, 75);

  -- Extraer bolas ya jugadas
  SELECT ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_current_state->'drawnBalls', '[]'::jsonb))::INT)
  INTO v_drawn_balls;

  -- Calcular balotas disponibles
  SELECT ARRAY(
    SELECT s FROM generate_series(1, v_total_balls) s
    WHERE NOT (s = ANY(v_drawn_balls))
  ) INTO v_available;

  IF array_length(v_available, 1) IS NULL OR array_length(v_available, 1) = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Se han extraído todas las balotas de la balotera.'
    );
  END IF;

  -- Seleccionar bola usando RNG seguro
  v_idx := public.fn_secure_rng_int(1, array_length(v_available, 1));
  v_next_ball := v_available[v_idx];

  v_event_id := 'rng_bingo_' || encode(gen_random_bytes(8), 'hex');
  v_commitment_hash := encode(digest(p_session_id::text || '_' || v_next_ball::text || '_' || v_event_id, 'sha256'), 'hex');

  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_new_seq
  FROM public.rng_events WHERE session_id = p_session_id;

  v_result_json := jsonb_build_object(
    'ball', v_next_ball,
    'total_drawn', array_length(v_drawn_balls, 1) + 1,
    'drawn_by', v_user_id
  );

  -- Registrar auditoría RNG
  INSERT INTO public.rng_events (
    event_id,
    session_id,
    table_id,
    user_id,
    game_type,
    event_type,
    sequence_number,
    result,
    commitment_hash,
    idempotency_key
  ) VALUES (
    v_event_id,
    p_session_id,
    v_session.table_id,
    v_user_id,
    v_session.game_type,
    'DRAW_BINGO_BALL',
    v_new_seq,
    v_result_json,
    v_commitment_hash,
    v_idempotency_key
  );

  -- Actualizar estado de la partida
  v_drawn_balls := array_append(v_drawn_balls, v_next_ball);
  v_current_state := jsonb_set(v_current_state, '{drawnBalls}', to_jsonb(v_drawn_balls));
  v_current_state := jsonb_set(v_current_state, '{currentBall}', to_jsonb(v_next_ball));

  -- 6. Activación Atómica de la Mesa y Sesión al Extraer la Primera Balota
  IF array_length(v_drawn_balls, 1) = 1 THEN
    -- Cambiar mesa a ACTIVE y refrescar updated_at
    UPDATE public.game_tables
    SET status = 'ACTIVE'::table_status_enum,
        updated_at = NOW()
    WHERE id = v_session.table_id;

    -- Cambiar sesión a ACTIVE con started_at
    UPDATE public.game_sessions
    SET status = 'ACTIVE'::session_status_enum,
        started_at = NOW()
    WHERE id = p_session_id;

    -- Actualizar config de la mesa si es necesario
    UPDATE public.game_tables
    SET config = config || jsonb_build_object('status', 'ACTIVE')
    WHERE id = v_session.table_id;

    -- Actualizar estado del juego en la sesión
    v_current_state := jsonb_set(v_current_state, '{status}', '"in_progress"'::jsonb);
  ELSE
    -- Refrescar updated_at de la mesa
    UPDATE public.game_tables
    SET updated_at = NOW()
    WHERE id = v_session.table_id;
  END IF;

  UPDATE public.game_sessions
  SET current_state = v_current_state
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'is_idempotent', false,
    'ball', v_next_ball,
    'event_id', v_event_id,
    'commitment_hash', v_commitment_hash
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_draw_bingo_ball_secure(UUID, TEXT) TO authenticated, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 81: 079_fix_ledger_entries_balance_after.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 079
-- CORRECCIÓN DEFINITIVA DE COMPATIBILIDAD LEDGER_ENTRIES: BALANCE_AFTER Y ESQUEMA CANÓNICO
-- ==============================================================================
-- Causa Raíz Identificada (Error: column "balance_after" of relation "ledger_entries" does not exist):
-- La tabla `public.ledger_entries` fue creada originalmente (migración 004) con las columnas
-- `balance_after_available` y `balance_after_held`. Sin embargo, funciones RPC y auditorías
-- financieras (como create_game_table_secure y join_table_transaction) invocaban o insertaban
-- directamente el campo unificado `balance_after`.
-- 
-- Esta migración:
-- 1. Añade de forma segura e incremental `balance_after NUMERIC(14,2)` a `public.ledger_entries`.
-- 2. Añade columnas auxiliares de compatibilidad (`status`, `reference_type`, `currency`).
-- 3. Crea un trigger BEFORE INSERT que reconcilia y normaliza automáticamente cualquier inserción
--    al libro mayor (asegurando idempotencia, wallet_id, direction, balance_after y balance_after_available).
-- 4. Reconcilia y blinda las funciones RPC críticas: `create_game_table_secure`,
--    `join_table_transaction` y `abandon_game_table_secure`.
-- ==============================================================================

-- 1. ADICIÓN SEGURA DE COLUMNA BALANCE_AFTER Y CAMPOS AUXILIARES
ALTER TABLE public.ledger_entries 
  ADD COLUMN IF NOT EXISTS balance_after NUMERIC(14,2);

COMMENT ON COLUMN public.ledger_entries.balance_after IS 'Saldo posterior a la transacción para auditoría financiera.';

ALTER TABLE public.ledger_entries 
  ADD COLUMN IF NOT EXISTS status VARCHAR(50) DEFAULT 'COMPLETED';

COMMENT ON COLUMN public.ledger_entries.status IS 'Estado del registro contable (COMPLETED, PENDING, REVERSED).';

ALTER TABLE public.ledger_entries 
  ADD COLUMN IF NOT EXISTS reference_type VARCHAR(50);

COMMENT ON COLUMN public.ledger_entries.reference_type IS 'Tipo o nombre de la entidad referenciada (alias de reference_table).';

ALTER TABLE public.ledger_entries 
  ADD COLUMN IF NOT EXISTS currency VARCHAR(3) DEFAULT 'VES';

-- Flexibilizar constraints para inserciones desde cualquier variante de RPC previa
ALTER TABLE public.ledger_entries ALTER COLUMN direction DROP NOT NULL;
ALTER TABLE public.ledger_entries ALTER COLUMN reference_table DROP NOT NULL;
ALTER TABLE public.ledger_entries ALTER COLUMN idempotency_key DROP NOT NULL;
ALTER TABLE public.ledger_entries ALTER COLUMN balance_after_available DROP NOT NULL;
ALTER TABLE public.ledger_entries ALTER COLUMN balance_after_held DROP NOT NULL;

-- 2. TRIGGER DE NORMALIZACIÓN Y RELLENO AUTOMÁTICO EN LEDGER_ENTRIES
CREATE OR REPLACE FUNCTION public.fn_ledger_entries_reconcile_defaults()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_derived_wallet_id UUID;
BEGIN
  -- Reconciliar balance_after y balance_after_available
  IF NEW.balance_after IS NULL THEN
    NEW.balance_after := COALESCE(NEW.balance_after_available, 0.00);
  END IF;
  
  IF NEW.balance_after_available IS NULL THEN
    NEW.balance_after_available := COALESCE(NEW.balance_after, 0.00);
  END IF;

  IF NEW.balance_after_held IS NULL THEN
    NEW.balance_after_held := 0.00;
  END IF;

  -- Garantizar monto positivo
  NEW.amount := ABS(COALESCE(NEW.amount, 0.00));

  -- Rellenar wallet_id automáticamente si no fue provisto
  IF NEW.wallet_id IS NULL AND NEW.user_id IS NOT NULL THEN
    SELECT id INTO v_derived_wallet_id FROM public.wallets WHERE user_id = NEW.user_id LIMIT 1;
    NEW.wallet_id := v_derived_wallet_id;
  END IF;

  -- Rellenar currency
  IF NEW.currency IS NULL OR NEW.currency = '' THEN
    NEW.currency := 'VES';
  END IF;

  -- Rellenar status
  IF NEW.status IS NULL OR NEW.status = '' THEN
    NEW.status := 'COMPLETED';
  END IF;

  -- Reconciliar reference_table y reference_type
  IF NEW.reference_table IS NULL AND NEW.reference_type IS NOT NULL THEN
    NEW.reference_table := NEW.reference_type;
  ELSIF NEW.reference_table IS NULL THEN
    NEW.reference_table := 'game_tables';
  END IF;

  IF NEW.reference_type IS NULL THEN
    NEW.reference_type := NEW.reference_table;
  END IF;

  -- Rellenar idempotency_key
  IF NEW.idempotency_key IS NULL OR NEW.idempotency_key = '' THEN
    NEW.idempotency_key := 'ledger_' || gen_random_uuid()::text;
  END IF;

  -- Rellenar description
  IF NEW.description IS NULL OR NEW.description = '' THEN
    NEW.description := 'Movimiento contable de billetera';
  END IF;

  -- Rellenar direction
  IF NEW.direction IS NULL THEN
    IF NEW.entry_type::text LIKE '%REFUND%' OR NEW.entry_type::text LIKE '%CREDIT%' OR NEW.entry_type::text LIKE '%DEPOSIT%' THEN
      NEW.direction := 'CREDIT'::ledger_direction_enum;
    ELSE
      NEW.direction := 'HOLD'::ledger_direction_enum;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ledger_entries_reconcile_defaults ON public.ledger_entries;
CREATE TRIGGER trg_ledger_entries_reconcile_defaults
  BEFORE INSERT ON public.ledger_entries
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_ledger_entries_reconcile_defaults();


-- 3. RECONCILIAR FUNCIÓN RPC: create_game_table_secure
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- Bloqueo pesimista FOR UPDATE en billetera para prevenir condiciones de carrera y dobles débitos
  IF p_entry_fee > 0 THEN
    SELECT id, available_balance, held_balance 
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL THEN
      -- Asegurar existencia de billetera si es usuario nuevo
      INSERT INTO public.wallets (user_id, available_balance, held_balance, currency)
      VALUES (v_user_id, 0.00, 0.00, 'VES')
      ON CONFLICT (user_id) DO NOTHING;

      SELECT id, available_balance, held_balance 
      INTO v_wallet_id, v_wallet_available, v_wallet_held
      FROM public.wallets
      WHERE user_id = v_user_id FOR UPDATE;
    END IF;
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- 2. AUTO-ABANDONO SEGURO DE PARTICIPACIONES OBSOLETAS O HUÉRFANAS:
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        (gt.status::text IN ('OPEN', 'FULL') AND gs.id IS NULL)
        OR (gs.id IS NOT NULL AND gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
        OR (gs.id IS NOT NULL AND (
             gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED')
             OR (gs.current_state->>'winnerUserId') IS NOT NULL AND (gs.current_state->>'winnerUserId') <> ''
           ))
        OR (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND (
             gt.created_at < NOW() - INTERVAL '1 hour'
             OR (gt.updated_at IS NOT NULL AND gt.updated_at < NOW() - INTERVAL '1 hour')
           ))
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              ended_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_079_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL:
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    AND (gt.updated_at IS NULL OR gt.updated_at >= NOW() - INTERVAL '1 hour')
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites
  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, máximo 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players >= 4 THEN 2
    ELSE p_max_players 
  END;

  -- 5. Validación de Saldo Disponible para Cuota de Entrada
  IF p_entry_fee > 0 THEN
    IF v_wallet_available IS NULL OR v_wallet_available < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para crear la mesa (% Bs.)', p_entry_fee;
    END IF;
  END IF;

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || p_game_type);
  v_expires_at := NOW() + INTERVAL '24 hours';
  v_table_id := gen_random_uuid();

  -- 7. Insertar Nueva Mesa de Juego
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, visibility, entry_fee, min_players, max_players,
    current_players_count, status, invite_code, expires_at, config
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, p_visibility, p_entry_fee, v_min_players, p_max_players,
    1, 'OPEN'::table_status_enum, v_invite_code, v_expires_at,
    COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name)
  );

  -- 8. Deducción de Saldo y Asiento en Ledger Inmutable
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_type,
      reference_id,
      idempotency_key,
      description,
      status,
      currency,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'HOLD'::ledger_direction_enum,
      p_entry_fee,
      (v_wallet_available - p_entry_fee),
      (v_wallet_available - p_entry_fee),
      (v_wallet_held + p_entry_fee),
      'game_tables',
      'game_tables',
      v_table_id,
      'HOLD_' || v_table_id::text || '_' || v_user_id::text,
      'Retención de entrada al crear mesa #' || substring(v_table_id::text from 1 for 8),
      'COMPLETED',
      'VES',
      v_user_id
    );
  END IF;

  -- 9. Asignación del Anfitrión en Asiento #1
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'host_user_id', v_user_id,
    'seat_number', 1,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'current_players_count', 1,
    'status', 'OPEN',
    'created_at', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;


-- 4. RECONCILIAR FUNCIÓN RPC: join_table_transaction
CREATE OR REPLACE FUNCTION public.join_table_transaction(
  p_table_id UUID,
  p_seat_number SMALLINT DEFAULT NULL,
  p_idempotency_key VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_existing_player RECORD;
  v_assigned_seat SMALLINT;
  v_seat_iter SMALLINT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_new_count INT;
  v_effective_key VARCHAR(100);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para unirte a una mesa';
  END IF;

  -- 1. Bloqueo de la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  IF v_table.status::text NOT IN ('OPEN', 'WAITING') THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La mesa no está abierta para nuevos jugadores (estado: %)', v_table.status;
  END IF;

  IF v_table.current_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: La mesa ya ha alcanzado su capacidad máxima';
  END IF;

  -- 2. Verificar si el usuario ya está en la mesa
  SELECT * INTO v_existing_player
  FROM public.game_table_players
  WHERE table_id = p_table_id AND user_id = v_user_id;

  IF FOUND THEN
    IF v_existing_player.status IN ('JOINED', 'READY', 'PLAYING') THEN
      RETURN jsonb_build_object(
        'success', true,
        'table_id', p_table_id,
        'seat_number', v_existing_player.seat_number,
        'message', 'Ya perteneces a esta mesa',
        'is_already_joined', true
      );
    END IF;
  END IF;

  -- 3. Asignar asiento
  IF p_seat_number IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = p_table_id
        AND seat_number = p_seat_number
        AND status != 'LEFT'::player_table_status_enum
    ) THEN
      RAISE EXCEPTION 'SEAT_TAKEN: El asiento % ya está ocupado', p_seat_number;
    END IF;
    v_assigned_seat := p_seat_number;
  ELSE
    FOR v_seat_iter IN 1..v_table.max_players LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.game_table_players
        WHERE table_id = p_table_id
          AND seat_number = v_seat_iter
          AND status != 'LEFT'::player_table_status_enum
      ) THEN
        v_assigned_seat := v_seat_iter;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_assigned_seat IS NULL THEN
    RAISE EXCEPTION 'NO_AVAILABLE_SEAT: No hay asientos disponibles en esta mesa';
  END IF;

  -- 4. Retención de saldo en Ledger si la mesa tiene costo
  IF v_table.entry_fee > 0 THEN
    SELECT id, available_balance, held_balance
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL OR v_wallet_available < v_table.entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para unirse a la mesa (% Bs.)', v_table.entry_fee;
    END IF;

    UPDATE public.wallets
    SET available_balance = available_balance - v_table.entry_fee,
        held_balance = held_balance + v_table.entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_effective_key := COALESCE(NULLIF(trim(p_idempotency_key), ''), 'JOIN_' || p_table_id::text || '_' || v_user_id::text);
    v_ledger_id := gen_random_uuid();

    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_type,
      reference_id,
      idempotency_key,
      description,
      status,
      currency,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'HOLD'::ledger_direction_enum,
      v_table.entry_fee,
      (v_wallet_available - v_table.entry_fee),
      (v_wallet_available - v_table.entry_fee),
      (v_wallet_held + v_table.entry_fee),
      'game_tables',
      'game_tables',
      p_table_id,
      v_effective_key,
      'Retención de entrada al unirse a mesa #' || substring(p_table_id::text from 1 for 8),
      'COMPLETED',
      'VES',
      v_user_id
    );
  END IF;

  -- 5. Insertar o Reactivar al Jugador
  IF v_existing_player.id IS NOT NULL THEN
    UPDATE public.game_table_players
    SET seat_number = v_assigned_seat,
        status = 'JOINED'::player_table_status_enum,
        entry_held_entry_id = COALESCE(v_ledger_id, entry_held_entry_id),
        joined_at = NOW(),
        left_at = NULL
    WHERE id = v_existing_player.id;
  ELSE
    v_player_id := gen_random_uuid();
    INSERT INTO public.game_table_players (
      id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
    ) VALUES (
      v_player_id, p_table_id, v_user_id, v_assigned_seat, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
    );
  END IF;

  -- 6. Actualizar conteo de mesa
  v_new_count := v_table.current_players_count + 1;
  UPDATE public.game_tables
  SET current_players_count = v_new_count,
      status = CASE WHEN v_new_count >= max_players THEN 'FULL'::table_status_enum ELSE 'OPEN'::table_status_enum END,
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'user_id', v_user_id,
    'seat_number', v_assigned_seat,
    'current_players_count', v_new_count,
    'status', CASE WHEN v_new_count >= v_table.max_players THEN 'FULL' ELSE 'OPEN' END
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_table_transaction(UUID, SMALLINT, VARCHAR) TO authenticated, service_role;


-- 5. RECONCILIAR FUNCIÓN RPC: abandon_game_table_secure
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_amount NUMERIC := 0.00;
  v_active_players_count INT;
  v_remaining_player RECORD;
  v_effective_idempotency TEXT;
  v_settle_result JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes estar autenticado para abandonar la mesa';
  END IF;

  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND user_id = v_caller_id;

  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  ELSE
    SELECT * INTO v_session FROM public.game_sessions
    WHERE table_id = p_table_id AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED')
    ORDER BY created_at DESC LIMIT 1
    FOR UPDATE;
  END IF;

  -- Devolución de fondos si la partida no ha sido liquidada
  IF v_table.entry_fee > 0.00 AND (v_session.id IS NULL OR v_session.status NOT IN ('SETTLED', 'ACTIVE')) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ledger_entries
      WHERE user_id = v_caller_id
        AND (reference_table = 'game_tables' OR reference_type = 'game_tables')
        AND (reference_id = p_table_id::text OR reference_id = p_table_id::uuid::text)
        AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
    ) INTO v_already_refunded;

    IF NOT v_already_refunded THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_caller_id FOR UPDATE;
      IF FOUND THEN
        IF v_wallet.held_balance >= v_table.entry_fee THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              held_balance = held_balance - v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        ELSE
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              total_balance = total_balance + v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        END IF;

        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_type,
          reference_id,
          description,
          idempotency_key,
          status,
          currency,
          actor_id
        ) VALUES (
          gen_random_uuid(),
          v_wallet.id,
          v_caller_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          GREATEST(0.00, v_wallet.held_balance - v_table.entry_fee),
          'game_tables',
          'game_tables',
          p_table_id,
          'Reembolso por abandono de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
          'abandon_refund_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text,
          'COMPLETED',
          'VES',
          v_caller_id
        );
        v_refund_amount := v_table.entry_fee;
      END IF;
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  IF v_active_players_count = 1 AND v_session.id IS NOT NULL AND v_session.status::text = 'ACTIVE' THEN
    SELECT user_id INTO v_remaining_player
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY')
    LIMIT 1;

    IF v_remaining_player.user_id IS NOT NULL THEN
      v_settle_result := public.settle_game_session(
        v_session.id,
        ARRAY[v_remaining_player.user_id],
        1,
        'SETTLE_ABANDON_' || v_effective_idempotency
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'WINNER_DECLARED_BY_ABANDON',
        'winner_user_id', v_remaining_player.user_id,
        'refund_amount', v_refund_amount,
        'settlement', v_settle_result
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refund_amount', v_refund_amount,
    'remaining_players', v_active_players_count
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 82: 080_fix_multiplayer_seats_started_at_and_abandon_signature.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 080
-- CORRECCIÓN MULTIJUGADOR: UNICIDAD DE ASIENTOS, COLUMNA STARTED_AT Y FIRMA CANÓNICA DE ABANDON RPC
-- ==============================================================================
-- Causa Raíz Identificada:
-- 1. Asignación Duplicada de Asientos: En partidas 1v1 (ej. Ajedrez / Damas), un jugador
--    podía ser asignado erróneamente en múltiples asientos (Seat 1 y Seat 2) si la sesión
--    iniciaba antes de tiempo o si el motor duplicaba el jugador en asientos vacíos.
-- 2. Columna started_at en game_tables: El esquema de game_tables carecía de started_at,
--    provocando inconsistencias cuando repositorios consultaban la fecha de inicio.
-- 3. Sobrecarga Polimórfica de RPC: Existían firmas duplicadas en PostgreSQL para
--    `abandon_game_table_secure` (con VARCHAR y TEXT), generando ambigüedad en Supabase.
-- 4. Inicio Prematuro de Sesión: La RPC `start_game_session_secure` no validaba que
--    hubiese suficientes jugadores DISTINTOS (COUNT DISTINCT user_id >= min_players).
-- ==============================================================================

-- 1. ADICIÓN SEGURA DE COLUMNA STARTED_AT EN GAME_TABLES
ALTER TABLE public.game_tables 
  ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ;

COMMENT ON COLUMN public.game_tables.started_at IS 'Fecha y hora en la que la mesa inició su primera sesión de juego activa.';


-- 2. GARANTIZAR UNICIDAD DE USUARIO POR MESA (UN SOLO ASIENTO POR JUGADOR)
-- Limpieza preventiva de asientos duplicados huérfanos históricos
DELETE FROM public.game_table_players a
USING public.game_table_players b
WHERE a.id > b.id 
  AND a.table_id = b.table_id 
  AND a.user_id = b.user_id;

-- Asegurar Constraint UNIQUE(table_id, user_id)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint 
    WHERE conname = 'uq_game_table_players_user' 
      AND conrelid = 'public.game_table_players'::regclass
  ) THEN
    ALTER TABLE public.game_table_players 
      ADD CONSTRAINT uq_game_table_players_user UNIQUE (table_id, user_id);
  END IF;
END $$;


-- 3. ELIMINAR TODAS LAS FIRMAS POLIMÓRFICAS PREVIAS DE ABANDON_GAME_TABLE_SECURE
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, VARCHAR);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, TEXT);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID, VARCHAR);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID, TEXT);


-- 4. DEFINIR LA VERSIÓN CANÓNICA Y BLINDADA DE ABANDON_GAME_TABLE_SECURE
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_amount NUMERIC := 0.00;
  v_active_players_count INT;
  v_remaining_player RECORD;
  v_effective_idempotency TEXT;
  v_settle_result JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes estar autenticado para abandonar la mesa';
  END IF;

  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- Marcar jugador como LEFT
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND user_id = v_caller_id;

  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  ELSE
    SELECT * INTO v_session FROM public.game_sessions
    WHERE table_id = p_table_id AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED')
    ORDER BY created_at DESC LIMIT 1
    FOR UPDATE;
  END IF;

  -- Devolución de fondos si la partida no ha sido liquidada
  IF v_table.entry_fee > 0.00 AND (v_session.id IS NULL OR v_session.status NOT IN ('SETTLED', 'ACTIVE')) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.ledger_entries
      WHERE user_id = v_caller_id
        AND (reference_table = 'game_tables' OR reference_type = 'game_tables')
        AND (reference_id = p_table_id::text OR reference_id = p_table_id::uuid::text)
        AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
    ) INTO v_already_refunded;

    IF NOT v_already_refunded THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_caller_id FOR UPDATE;
      IF FOUND THEN
        IF v_wallet.held_balance >= v_table.entry_fee THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              held_balance = held_balance - v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        ELSE
          UPDATE public.wallets
          SET available_balance = available_balance + v_table.entry_fee,
              total_balance = total_balance + v_table.entry_fee,
              updated_at = NOW()
          WHERE id = v_wallet.id;
        END IF;

        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_type,
          reference_id,
          description,
          idempotency_key,
          status,
          currency,
          actor_id
        ) VALUES (
          gen_random_uuid(),
          v_wallet.id,
          v_caller_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          v_wallet.available_balance + v_table.entry_fee,
          GREATEST(0.00, v_wallet.held_balance - v_table.entry_fee),
          'game_tables',
          'game_tables',
          p_table_id,
          'Reembolso por abandono de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
          'abandon_refund_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text,
          'COMPLETED',
          'VES',
          v_caller_id
        );
        v_refund_amount := v_table.entry_fee;
      END IF;
    END IF;
  END IF;

  -- Contar jugadores distintos activos
  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  IF v_active_players_count = 1 AND v_session.id IS NOT NULL AND v_session.status::text = 'ACTIVE' THEN
    SELECT user_id INTO v_remaining_player
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY')
    LIMIT 1;

    IF v_remaining_player.user_id IS NOT NULL THEN
      v_settle_result := public.settle_game_session(
        v_session.id,
        ARRAY[v_remaining_player.user_id],
        1,
        'SETTLE_ABANDON_' || v_effective_idempotency
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'WINNER_DECLARED_BY_ABANDON',
        'winner_user_id', v_remaining_player.user_id,
        'refund_amount', v_refund_amount,
        'settlement', v_settle_result
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refund_amount', v_refund_amount,
    'remaining_players', v_active_players_count
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role;


-- 5. RECONCILIACIÓN Y BLINDAJE DE CREATE_GAME_TABLE_SECURE (HOST EN SEAT 1 ÚNICAMENTE)
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- Bloqueo pesimista FOR UPDATE en billetera
  IF p_entry_fee > 0 THEN
    SELECT id, available_balance, held_balance 
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, available_balance, held_balance, currency)
      VALUES (v_user_id, 0.00, 0.00, 'VES')
      ON CONFLICT (user_id) DO NOTHING;

      SELECT id, available_balance, held_balance 
      INTO v_wallet_id, v_wallet_available, v_wallet_held
      FROM public.wallets
      WHERE user_id = v_user_id FOR UPDATE;
    END IF;
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- 2. AUTO-ABANDONO SEGURO DE PARTICIPACIONES OBSOLETAS O HUÉRFANAS
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        (gt.status::text IN ('OPEN', 'FULL') AND gs.id IS NULL)
        OR (gs.id IS NOT NULL AND gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
        OR (gs.id IS NOT NULL AND (
             gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED')
             OR (gs.current_state->>'winnerUserId') IS NOT NULL AND (gs.current_state->>'winnerUserId') <> ''
           ))
        OR (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND (
             gt.created_at < NOW() - INTERVAL '1 hour'
             OR (gt.updated_at IS NOT NULL AND gt.updated_at < NOW() - INTERVAL '1 hour')
           ))
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              ended_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_080_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    AND (gt.updated_at IS NULL OR gt.updated_at >= NOW() - INTERVAL '1 hour')
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites
  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_max_players < 2 OR p_max_players > 1000 THEN
    RAISE EXCEPTION 'INVALID_PLAYERS_COUNT: Cantidad de jugadores inválida (mínimo 2, máximo 1000)';
  END IF;

  v_min_players := CASE 
    WHEN p_max_players >= 4 THEN 2
    ELSE p_max_players 
  END;

  -- 5. Validación de Saldo Disponible
  IF p_entry_fee > 0 THEN
    IF v_wallet_available IS NULL OR v_wallet_available < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para crear la mesa (% Bs.)', p_entry_fee;
    END IF;
  END IF;

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    IF p_visibility = 'PRIVATE' THEN
      v_code_candidate := 'TRK-' || (1000 + floor(random() * 9000))::text;
    ELSE
      v_code_candidate := 'PUB-' || (1000 + floor(random() * 9000))::text;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.game_tables WHERE invite_code = v_code_candidate) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;

    IF v_code_attempts > 20 THEN
      v_invite_code := CASE WHEN p_visibility = 'PRIVATE' THEN 'TRK-' ELSE 'PUB-' END || substring(encode(gen_random_bytes(3), 'hex') from 1 for 5);
      EXIT;
    END IF;
  END LOOP;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || p_game_type);
  v_expires_at := NOW() + INTERVAL '24 hours';
  v_table_id := gen_random_uuid();

  -- 7. Insertar Nueva Mesa de Juego
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, visibility, entry_fee, min_players, max_players,
    current_players_count, status, invite_code, expires_at, config
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, p_visibility, p_entry_fee, v_min_players, p_max_players,
    1, 'OPEN'::table_status_enum, v_invite_code, v_expires_at,
    COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name)
  );

  -- 8. Deducción de Saldo y Asiento en Ledger
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_type,
      reference_id,
      idempotency_key,
      description,
      status,
      currency,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'HOLD'::ledger_direction_enum,
      p_entry_fee,
      (v_wallet_available - p_entry_fee),
      (v_wallet_available - p_entry_fee),
      (v_wallet_held + p_entry_fee),
      'game_tables',
      'game_tables',
      v_table_id,
      'HOLD_' || v_table_id::text || '_' || v_user_id::text,
      'Retención de entrada al crear mesa #' || substring(v_table_id::text from 1 for 8),
      'COMPLETED',
      'VES',
      v_user_id
    );
  END IF;

  -- 9. Asignación EXCLUSIVA del Anfitrión en Asiento #1 (UN SOLO ASIENTO)
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
  )
  ON CONFLICT (table_id, user_id) DO UPDATE
  SET seat_number = 1,
      status = 'JOINED'::player_table_status_enum,
      left_at = NULL;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'host_user_id', v_user_id,
    'seat_number', 1,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'entry_fee', p_entry_fee,
    'max_players', p_max_players,
    'current_players_count', 1,
    'status', 'OPEN',
    'created_at', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;


-- 6. RECONCILIACIÓN Y BLINDAJE DE JOIN_TABLE_TRANSACTION (UNICIDAD DE ASIENTOS)
CREATE OR REPLACE FUNCTION public.join_table_transaction(
  p_table_id UUID,
  p_seat_number SMALLINT DEFAULT NULL,
  p_idempotency_key VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_existing_player RECORD;
  v_assigned_seat SMALLINT;
  v_seat_iter SMALLINT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_new_count INT;
  v_effective_key VARCHAR(100);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para unirte a una mesa';
  END IF;

  -- 1. Bloqueo de la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  IF v_table.status::text NOT IN ('OPEN', 'WAITING') THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La mesa no está abierta para nuevos jugadores (estado: %)', v_table.status;
  END IF;

  -- 2. REGLA OBLIGATORIA: Verificar si el usuario ya pertenece a esta mesa
  SELECT * INTO v_existing_player
  FROM public.game_table_players
  WHERE table_id = p_table_id AND user_id = v_user_id;

  IF FOUND AND v_existing_player.status IN ('JOINED', 'READY', 'PLAYING') THEN
    RETURN jsonb_build_object(
      'success', true,
      'table_id', p_table_id,
      'seat_number', v_existing_player.seat_number,
      'message', 'Ya perteneces a esta mesa',
      'is_already_joined', true,
      'current_players_count', v_table.current_players_count
    );
  END IF;

  IF v_table.current_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: La mesa ya ha alcanzado su capacidad máxima';
  END IF;

  -- 3. Asignar asiento disponible
  IF p_seat_number IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = p_table_id
        AND seat_number = p_seat_number
        AND status != 'LEFT'::player_table_status_enum
    ) THEN
      RAISE EXCEPTION 'SEAT_TAKEN: El asiento % ya está ocupado', p_seat_number;
    END IF;
    v_assigned_seat := p_seat_number;
  ELSE
    FOR v_seat_iter IN 1..v_table.max_players LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.game_table_players
        WHERE table_id = p_table_id
          AND seat_number = v_seat_iter
          AND status != 'LEFT'::player_table_status_enum
      ) THEN
        v_assigned_seat := v_seat_iter;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_assigned_seat IS NULL THEN
    RAISE EXCEPTION 'NO_AVAILABLE_SEAT: No hay asientos disponibles en esta mesa';
  END IF;

  -- 4. Retención de saldo en Ledger si la mesa tiene costo
  IF v_table.entry_fee > 0 THEN
    SELECT id, available_balance, held_balance
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL OR v_wallet_available < v_table.entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo insuficiente para unirse a la mesa (% Bs.)', v_table.entry_fee;
    END IF;

    UPDATE public.wallets
    SET available_balance = available_balance - v_table.entry_fee,
        held_balance = held_balance + v_table.entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_effective_key := COALESCE(NULLIF(trim(p_idempotency_key), ''), 'JOIN_' || p_table_id::text || '_' || v_user_id::text);
    v_ledger_id := gen_random_uuid();

    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_type,
      reference_id,
      idempotency_key,
      description,
      status,
      currency,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'HOLD'::ledger_direction_enum,
      v_table.entry_fee,
      (v_wallet_available - v_table.entry_fee),
      (v_wallet_available - v_table.entry_fee),
      (v_wallet_held + v_table.entry_fee),
      'game_tables',
      'game_tables',
      p_table_id,
      v_effective_key,
      'Retención de entrada al unirse a mesa #' || substring(p_table_id::text from 1 for 8),
      'COMPLETED',
      'VES',
      v_user_id
    );
  END IF;

  -- 5. Insertar o Reactivar al Jugador (Garantizando Unicidad)
  IF v_existing_player.id IS NOT NULL THEN
    UPDATE public.game_table_players
    SET seat_number = v_assigned_seat,
        status = 'JOINED'::player_table_status_enum,
        entry_held_entry_id = COALESCE(v_ledger_id, entry_held_entry_id),
        joined_at = NOW(),
        left_at = NULL
    WHERE id = v_existing_player.id;
  ELSE
    v_player_id := gen_random_uuid();
    INSERT INTO public.game_table_players (
      id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at
    ) VALUES (
      v_player_id, p_table_id, v_user_id, v_assigned_seat, 'JOINED'::player_table_status_enum, v_ledger_id, NOW()
    )
    ON CONFLICT (table_id, user_id) DO UPDATE
    SET seat_number = v_assigned_seat,
        status = 'JOINED'::player_table_status_enum,
        entry_held_entry_id = COALESCE(v_ledger_id, public.game_table_players.entry_held_entry_id),
        left_at = NULL;
  END IF;

  -- 6. Actualizar conteo exacto de jugadores activos en la mesa
  SELECT COUNT(DISTINCT user_id) INTO v_new_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

  UPDATE public.game_tables
  SET current_players_count = v_new_count,
      status = CASE WHEN v_new_count >= max_players THEN 'FULL'::table_status_enum ELSE 'OPEN'::table_status_enum END,
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'user_id', v_user_id,
    'seat_number', v_assigned_seat,
    'current_players_count', v_new_count,
    'status', CASE WHEN v_new_count >= v_table.max_players THEN 'FULL' ELSE 'OPEN' END
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_table_transaction(UUID, SMALLINT, VARCHAR) TO authenticated, service_role;


-- 7. RECONCILIACIÓN Y BLINDAJE DE START_GAME_SESSION_SECURE (VALIDACIÓN DE JUGADORES DISTINTOS)
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_unique_players_count INT;
  v_players JSONB := '[]'::jsonb;
  v_player_order JSONB := '[]'::jsonb;
  v_lives JSONB := '{}'::jsonb;
  v_scores JSONB := '{}'::jsonb;
  v_player_record RECORD;
  v_session_id UUID;
  v_first_turn_user_id UUID;
  v_initial_state JSONB;
  v_deadline TIMESTAMPTZ;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para iniciar la partida';
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  IF v_table.host_user_id <> v_user_id THEN
    RAISE EXCEPTION 'ONLY_HOST_CAN_START: Únicamente el Anfitrión de la mesa puede iniciar la partida';
  END IF;

  -- Si ya existe una sesión activa o en curso, retornarla
  SELECT id INTO v_session_id
  FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS');

  IF v_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'session_id', v_session_id,
      'table_id', p_table_id,
      'already_active', true
    );
  END IF;

  -- Validar cantidad de jugadores DISTINTOS activos en la mesa
  SELECT COUNT(DISTINCT gtp.user_id) INTO v_unique_players_count
  FROM public.game_table_players gtp
  WHERE gtp.table_id = p_table_id
    AND gtp.status != 'LEFT'::player_table_status_enum;

  IF v_unique_players_count < v_table.min_players THEN
    RAISE EXCEPTION 'NOT_ENOUGH_PLAYERS: Se requieren al menos % jugadores diferentes para iniciar la partida (actualmente hay %)', v_table.min_players, v_unique_players_count;
  END IF;

  -- Compilar lista de jugadores activos (sin duplicados, ordenados por asiento)
  FOR v_player_record IN (
    SELECT DISTINCT ON (gtp.user_id)
      gtp.user_id, gtp.seat_number, p.display_name, p.first_name, p.last_name, p.avatar_url
    FROM public.game_table_players gtp
    JOIN public.profiles p ON p.user_id = gtp.user_id
    WHERE gtp.table_id = p_table_id
      AND gtp.status != 'LEFT'::player_table_status_enum
    ORDER BY gtp.user_id, gtp.seat_number ASC
  ) LOOP
    IF v_first_turn_user_id IS NULL THEN
      v_first_turn_user_id := v_player_record.user_id;
    END IF;

    v_player_order := v_player_order || to_jsonb(v_player_record.user_id::text);
    v_lives := jsonb_set(v_lives, ARRAY[v_player_record.user_id::text], '3'::jsonb);
    v_scores := jsonb_set(v_scores, ARRAY[v_player_record.user_id::text], '0'::jsonb);

    v_players := v_players || jsonb_build_object(
      'userId', v_player_record.user_id,
      'seatNumber', v_player_record.seat_number,
      'displayName', COALESCE(NULLIF(trim(v_player_record.display_name), ''), trim(COALESCE(v_player_record.first_name, '') || ' ' || COALESCE(v_player_record.last_name, ''))),
      'avatarUrl', v_player_record.avatar_url,
      'lives', 3
    );
  END LOOP;

  IF v_first_turn_user_id IS NULL THEN
    v_first_turn_user_id := v_user_id;
  END IF;

  v_deadline := NOW() + INTERVAL '10 seconds';
  v_session_id := gen_random_uuid();

  v_initial_state := jsonb_build_object(
    'status', 'PLAYING',
    'playerOrder', v_player_order,
    'players', v_players,
    'currentTurnUserId', v_first_turn_user_id,
    'lives', v_lives,
    'scores', v_scores,
    'round', 1
  );

  -- Crear sesión en game_sessions usando el estado ACTIVE del enum
  INSERT INTO public.game_sessions (
    id, table_id, game_type, session_number, status, current_state,
    current_turn_user_id, turn_deadline_at, started_at
  ) VALUES (
    v_session_id, p_table_id, v_table.game_type, 1, 'ACTIVE'::session_status_enum,
    v_initial_state, v_first_turn_user_id, v_deadline, NOW()
  );

  -- Actualizar estado de la mesa a ACTIVE y registrar started_at de forma segura
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      started_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'table_id', p_table_id,
    'current_turn_user_id', v_first_turn_user_id,
    'turn_deadline_at', v_deadline,
    'already_active', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 83: 081_fix_settle_game_session_signature.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 081
-- CORRECCIÓN DEFINITIVA DE FIRMA RPC Y COMPATIBILIDAD: SETTLE_GAME_SESSION & REFUND_GAME_SESSION
-- ==============================================================================
-- Causa Raíz Identificada:
-- Error: "function public.settle_game_session(uuid, uuid[], integer, text) does not exist"
-- En la migración 018 se definió el parámetro `p_winner_team` como `SMALLINT`. Al ser invocado
-- desde clientes JavaScript/PostgREST o desde funciones PL/pgSQL con literales enteros, PostgREST
-- envía `INTEGER` (int4) y `TEXT`, lo que causaba un fallo de resolución de tipos.
--
-- Esta migración:
-- 1. Normaliza `settle_game_session` con `p_winner_team INTEGER DEFAULT NULL` y `p_idempotency_key TEXT DEFAULT NULL`.
-- 2. Añade sobrecargas seguras (UUID[], TEXT[], SMALLINT) para compatibilidad total e inquebrantable.
-- 3. Reconcilia `refund_game_session` con `p_reason TEXT` y `p_idempotency_key TEXT`.
-- 4. Garantiza permisos de ejecución a authenticated, anon y service_role.
-- ==============================================================================

-- 1. FUNCIÓN CANÓNICA: SETTLE_GAME_SESSION (UUID, UUID[], INTEGER, TEXT)
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_winner_id UUID;
  v_winner_wallet RECORD;
  v_winner_count INT;
  v_individual_prize NUMERIC(14,2);
  v_distributed_sum NUMERIC(14,2) := 0.00;
  v_winner_ledger_id UUID;
  v_settlement_type settlement_type_enum;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
BEGIN
  -- 1. Control de Autorización (Participante de la mesa, Rol Operador+ o Motor Servidor)
  v_caller_id := auth.uid();
  
  -- Verificar si la sesión existe primero
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión de juego % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa de juego no encontrada';
  END IF;

  IF v_caller_id IS NOT NULL THEN
    IF public.is_operator_or_above(v_caller_id) THEN
      v_is_participant := TRUE;
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.game_table_players
        WHERE table_id = v_table.id AND user_id = v_caller_id
      ) INTO v_is_participant;
    END IF;

    IF NOT v_is_participant THEN
      RAISE EXCEPTION 'PERMISSION_DENIED: Solo los jugadores participantes o un operador pueden liquidar partidas';
    END IF;
  END IF;

  -- 2. Idempotencia y Replay Seguro
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'settle_' || p_session_id::text || '_' || COALESCE(v_caller_id::text, 'sys')
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id OR idempotency_key = v_effective_idempotency;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'settlement_id', v_existing_settlement.id,
      'gross_pool', v_existing_settlement.gross_pool,
      'prize_pool', v_existing_settlement.prize_pool,
      'platform_fee', v_existing_settlement.platform_fee
    );
  END IF;

  -- 3. Verificación de Estado de la Sesión
  IF v_session.status IN ('SETTLED', 'CANCELLED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_already_settled', true,
      'session_status', v_session.status
    );
  END IF;

  -- 4. Validación de Participantes
  SELECT COUNT(*) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  IF v_player_count < 1 THEN
    RAISE EXCEPTION 'INVALID_PLAYER_COUNT: Partida sin participantes';
  END IF;

  -- 5. Validación de Ganadores
  v_winner_count := COALESCE(array_length(p_winner_user_ids, 1), 0);
  IF v_winner_count < 1 THEN
    RAISE EXCEPTION 'NO_WINNERS_SPECIFIED: Se requiere al menos un ganador para liquidar';
  END IF;

  FOREACH v_winner_id IN ARRAY p_winner_user_ids LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.game_table_players 
      WHERE table_id = v_table.id AND user_id = v_winner_id
    ) THEN
      RAISE EXCEPTION 'INVALID_WINNER: El usuario % no participó en esta mesa', v_winner_id;
    END IF;
  END LOOP;

  -- 6. Cálculo Financiero Server-Side (Regla 90% Premio / 10% Comisión Plataforma)
  v_gross_pool := v_table.entry_fee * v_player_count;
  v_prize_pool := ROUND(v_gross_pool * 0.90, 2);
  v_platform_fee := v_gross_pool - v_prize_pool;
  v_settlement_type := CASE WHEN v_winner_count > 1 THEN 'SPLIT_PAYOUT'::settlement_type_enum ELSE 'STANDARD_PAYOUT'::settlement_type_enum END;

  -- 7. Creación de la Liquidación Principal
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_by
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    v_settlement_type,
    v_gross_pool,
    v_prize_pool,
    v_platform_fee,
    v_prize_pool,
    v_effective_idempotency,
    COALESCE(v_caller_id::text, 'SERVER_ENGINE')
  );

  -- 8. Captura de Entrada (Held Balance) de todos los participantes
  IF v_table.entry_fee > 0.00 THEN
    FOR v_player IN (SELECT user_id FROM public.game_table_players WHERE table_id = v_table.id) LOOP
      UPDATE public.wallets
      SET 
        held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
        updated_at = NOW()
      WHERE user_id = v_player.user_id;

      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        entry_type,
        direction,
        amount,
        balance_after,
        balance_after_available,
        balance_after_held,
        reference_table,
        reference_id,
        idempotency_key,
        description,
        actor_id
      )
      SELECT 
        w.id,
        w.user_id,
        'TABLE_ENTRY_CAPTURE'::ledger_entry_type_enum,
        'DEBIT'::ledger_direction_enum,
        v_table.entry_fee,
        w.available_balance,
        w.available_balance,
        w.held_balance,
        'game_settlements',
        v_settlement_id,
        'CAPTURE_' || p_session_id::text || '_' || v_player.user_id::text,
        'Captura de entrada para liquidación de partida ' || p_session_id::text,
        v_caller_id
      FROM public.wallets w
      WHERE w.user_id = v_player.user_id;
    END LOOP;
  END IF;

  -- 9. Acreditación de Premio a Ganadores (1v1 o Reparto)
  IF v_prize_pool > 0.00 THEN
    FOR i IN 1..v_winner_count LOOP
      v_winner_id := p_winner_user_ids[i];
      
      -- En caso de división con centavos impares, el último ganador absorbe la diferencia exacta
      IF i = v_winner_count THEN
        v_individual_prize := v_prize_pool - v_distributed_sum;
      ELSE
        v_individual_prize := ROUND(v_prize_pool / v_winner_count, 2);
        v_distributed_sum := v_distributed_sum + v_individual_prize;
      END IF;

      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_winner_id
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET 
          available_balance = available_balance + v_individual_prize,
          updated_at = NOW()
        WHERE id = v_winner_wallet.id;

        v_winner_ledger_id := gen_random_uuid();
        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_id,
          idempotency_key,
          description,
          actor_id
        ) VALUES (
          v_winner_ledger_id,
          v_winner_wallet.id,
          v_winner_id,
          'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_individual_prize,
          v_winner_wallet.available_balance + v_individual_prize,
          v_winner_wallet.available_balance + v_individual_prize,
          v_winner_wallet.held_balance,
          'game_settlements',
          v_settlement_id,
          'PRIZE_' || p_session_id::text || '_' || v_winner_id::text,
          'Premio por victoria en partida ' || p_session_id::text,
          v_caller_id
        );

        INSERT INTO public.game_settlement_recipients (
          settlement_id,
          user_id,
          team_number,
          payout_amount,
          ledger_entry_id,
          payout_status
        ) VALUES (
          v_settlement_id,
          v_winner_id,
          p_winner_team,
          v_individual_prize,
          v_winner_ledger_id,
          'COMPLETED'
        );
      END IF;
    END LOOP;
  END IF;

  -- 10. Actualizar Estado de la Sesión y Mesa
  UPDATE public.game_sessions
  SET 
    status = 'SETTLED'::session_status_enum,
    winner_user_id = p_winner_user_ids[1],
    ended_at = NOW(),
    updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET 
    status = 'CLOSED'::table_status_enum,
    updated_at = NOW()
  WHERE id = v_table.id;

  -- 11. Registrar en Historial Público si existe la tabla
  BEGIN
    INSERT INTO public.public_match_history (
      session_id,
      table_id,
      game_type,
      winner_user_id,
      prize_pool,
      player_count,
      ended_at
    ) VALUES (
      p_session_id,
      v_table.id,
      v_table.game_type,
      p_winner_user_ids[1],
      v_prize_pool,
      v_player_count,
      NOW()
    )
    ON CONFLICT (session_id) DO UPDATE SET
      winner_user_id = EXCLUDED.winner_user_id,
      prize_pool = EXCLUDED.prize_pool,
      ended_at = EXCLUDED.ended_at;
  EXCEPTION WHEN OTHERS THEN
    -- Silenciar error de ticker público para no bloquear la liquidación
    NULL;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'settlement_id', v_settlement_id,
    'gross_pool', v_gross_pool,
    'prize_pool', v_prize_pool,
    'platform_fee', v_platform_fee,
    'winner_count', v_winner_count
  );
END;
$$;

-- 4. FUNCIÓN CANÓNICA: REFUND_GAME_SESSION (UUID, TEXT, TEXT)
CREATE OR REPLACE FUNCTION public.refund_game_session(
  p_session_id UUID,
  p_reason TEXT DEFAULT 'CANCELLED',
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_player_wallet RECORD;
  v_refund_ledger_id UUID;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
  v_refunded_count INT := 0;
BEGIN
  -- 1. Control de Autorización
  v_caller_id := auth.uid();

  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  IF v_caller_id IS NOT NULL THEN
    IF public.is_operator_or_above(v_caller_id) THEN
      v_is_participant := TRUE;
    ELSE
      SELECT EXISTS (
        SELECT 1 FROM public.game_table_players
        WHERE table_id = v_table.id AND user_id = v_caller_id
      ) INTO v_is_participant;
    END IF;

    IF NOT v_is_participant THEN
      RAISE EXCEPTION 'PERMISSION_DENIED: Solo los jugadores participantes o un operador pueden reembolsar partidas';
    END IF;
  END IF;

  -- 2. Idempotencia
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'refund_' || p_session_id::text || '_' || COALESCE(v_caller_id::text, 'sys')
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id OR idempotency_key = v_effective_idempotency;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  -- 3. Verificación de Estado
  IF v_session.status = 'SETTLED' THEN
    RAISE EXCEPTION 'INVALID_SESSION_STATUS: No se puede reembolsar una sesión ya liquidada';
  END IF;

  IF v_session.status = 'CANCELLED' THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_already_cancelled', true
    );
  END IF;

  -- 4. Conteo de Participantes y Cálculo de Pozo
  SELECT COUNT(*) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  v_gross_pool := v_table.entry_fee * COALESCE(v_player_count, 0);

  -- 5. Creación de Registro de Reembolso
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_by
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    'CANCELLED_REFUND'::settlement_type_enum,
    v_gross_pool,
    0.00,
    0.00,
    v_gross_pool,
    v_effective_idempotency,
    COALESCE(v_caller_id::text, 'SERVER_ENGINE')
  );

  -- 6. Liberación de Saldos Retenidos (Held Balance)
  IF v_table.entry_fee > 0.00 THEN
    FOR v_player IN (SELECT user_id FROM public.game_table_players WHERE table_id = v_table.id) LOOP
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player.user_id
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET 
          available_balance = available_balance + v_table.entry_fee,
          held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
          updated_at = NOW()
        WHERE id = v_player_wallet.id;

        v_refund_ledger_id := gen_random_uuid();
        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_id,
          idempotency_key,
          description,
          actor_id
        ) VALUES (
          v_refund_ledger_id,
          v_player_wallet.id,
          v_player.user_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          v_player_wallet.available_balance + v_table.entry_fee,
          v_player_wallet.available_balance + v_table.entry_fee,
          GREATEST(0.00, v_player_wallet.held_balance - v_table.entry_fee),
          'game_settlements',
          v_settlement_id,
          'REFUND_' || p_session_id::text || '_' || v_player.user_id::text,
          'Reembolso de entrada por empate o cancelación: ' || COALESCE(p_reason, 'Sin motivo'),
          v_caller_id
        );

        v_refunded_count := v_refunded_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- 7. Actualización de Estados
  UPDATE public.game_sessions
  SET 
    status = 'CANCELLED'::session_status_enum,
    ended_at = NOW(),
    updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET 
    status = 'CLOSED'::table_status_enum,
    updated_at = NOW()
  WHERE id = v_table.id;

  RETURN jsonb_build_object(
    'success', true,
    'settlement_id', v_settlement_id,
    'refunded_count', v_refunded_count,
    'gross_refunded', v_gross_pool
  );
END;
$$;

-- 5. SOBRECARGA PARA VARCHAR (COMPATIBILIDAD CON ESQUEMAS PREVIOS)
CREATE OR REPLACE FUNCTION public.refund_game_session(
  p_session_id UUID,
  p_reason VARCHAR,
  p_idempotency_key VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.refund_game_session(
    p_session_id,
    p_reason::TEXT,
    p_idempotency_key::TEXT
  );
END;
$$;

-- 6. PERMISOS DE EJECUCIÓN
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], SMALLINT, VARCHAR) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, TEXT[], INTEGER, TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.refund_game_session(UUID, TEXT, TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.refund_game_session(UUID, VARCHAR, VARCHAR) TO authenticated, anon, service_role;



