-- MIGRACIÓN 84: 082_fix_controlled_game_abandonment_and_settlement.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 082
-- MEJORA CONTROLADA DE ABANDONO DE PARTIDAS + LIQUIDACIÓN AUTOMÁTICA POR FORFEIT
-- ==============================================================================
-- 1. Permite abandono voluntario seguro con resolución autoritativa del servidor.
-- 2. En partidas 1v1 activas: Al abandonar el Jugador A, el Jugador B es declarado
--    ganador inmediato y se liquida la partida (90% ganador / 10% plataforma) mediante ledger.
-- 3. En partidas multijugador (3-4 jugadores): El jugador es eliminado de la mesa activa,
--    la partida continúa con los jugadores restantes y se rota el turno si correspondía al saliente.
-- 4. En salas de espera (partida no iniciada): Se realiza el reembolso íntegro de la entrada retenida.
-- 5. Blindaje de idempotencia, FOR UPDATE y prevención estricta de doble liquidación.
-- ==============================================================================

-- 1. FUNCIÓN CANÓNICA: ABANDON_GAME_TABLE_SECURE
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_player RECORD;
  v_already_refunded BOOLEAN := FALSE;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_active_players_count INT := 0;
  v_remaining_player RECORD;
  v_next_player RECORD;
  v_effective_idempotency TEXT;
  v_settle_result JSONB := NULL;
  v_session_is_active BOOLEAN := FALSE;
BEGIN
  -- 1. Validar autenticación
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes estar autenticado para abandonar la mesa';
  END IF;

  -- 2. Bloquear mesa con FOR UPDATE
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- 3. Verificar estado actual del participante
  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id AND user_id = v_caller_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'El usuario no pertenece a la mesa o ya no es participante',
      'table_id', p_table_id
    );
  END IF;

  -- 4. Marcar jugador como LEFT en la mesa
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND user_id = v_caller_id;

  -- 5. Obtener sesión de juego
  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE id = p_session_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'PAUSED', 'IN_PROGRESS')
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  v_session_is_active := (v_session.id IS NOT NULL AND v_session.status::text IN ('ACTIVE', 'IN_PROGRESS', 'PLAYING'));

  -- 6. Clave de idempotencia efectiva
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  -- 7. REGLA DE RETENCIÓN / REEMBOLSO SEGÚN ESTADO DE PARTIDA
  IF v_table.entry_fee > 0.00 THEN
    IF NOT v_session_is_active AND (v_session.id IS NULL OR v_session.status::text NOT IN ('SETTLED', 'ACTIVE')) THEN
      -- Sala de espera o partida no iniciada: Devolver fondos retenidos a available_balance
      SELECT EXISTS (
        SELECT 1 FROM public.ledger_entries
        WHERE user_id = v_caller_id
          AND (reference_table = 'game_tables' OR reference_type = 'game_tables')
          AND (reference_id = p_table_id::text OR reference_id = p_table_id::uuid::text)
          AND entry_type = 'TABLE_ENTRY_REFUND'::ledger_entry_type_enum
      ) INTO v_already_refunded;

      IF NOT v_already_refunded THEN
        SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_caller_id FOR UPDATE;
        IF FOUND THEN
          IF v_wallet.held_balance >= v_table.entry_fee THEN
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                held_balance = held_balance - v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          ELSE
            UPDATE public.wallets
            SET available_balance = available_balance + v_table.entry_fee,
                total_balance = total_balance + v_table.entry_fee,
                updated_at = NOW()
            WHERE id = v_wallet.id;
          END IF;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            entry_type,
            direction,
            amount,
            balance_after,
            balance_after_available,
            balance_after_held,
            reference_table,
            reference_type,
            reference_id,
            description,
            idempotency_key,
            status,
            currency,
            actor_id
          ) VALUES (
            gen_random_uuid(),
            v_wallet.id,
            v_caller_id,
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_table.entry_fee,
            v_wallet.available_balance + v_table.entry_fee,
            v_wallet.available_balance + v_table.entry_fee,
            GREATEST(0.00, v_wallet.held_balance - v_table.entry_fee),
            'game_tables',
            'game_tables',
            p_table_id,
            'Reembolso por abandono voluntario de mesa #' || COALESCE(v_table.invite_code, substring(p_table_id::text from 1 for 6)),
            'refund_' || v_effective_idempotency,
            'COMPLETED',
            'VES',
            v_caller_id
          );
          v_refund_amount := v_table.entry_fee;
        END IF;
      END IF;
    END IF;
  END IF;

  -- 8. Contar jugadores activos restantes
  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND status IN ('PLAYING', 'JOINED', 'READY');

  -- 9. Actualizar contador y estado en game_tables
  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 10. EVALUACIÓN Y LIQUIDACIÓN EN PARTIDA ACTIVA
  IF v_session_is_active THEN
    -- Caso 1v1 o solo queda 1 jugador activo restante: VICTORIA AUTOMÁTICA POR ABANDONO
    IF v_active_players_count = 1 THEN
      SELECT user_id INTO v_remaining_player
      FROM public.game_table_players
      WHERE table_id = p_table_id
        AND status IN ('PLAYING', 'JOINED', 'READY')
      LIMIT 1;

      IF v_remaining_player.user_id IS NOT NULL THEN
        -- Liquidar la partida asignando victoria al jugador restante
        v_settle_result := public.settle_game_session(
          v_session.id,
          ARRAY[v_remaining_player.user_id],
          1,
          'SETTLE_FORFEIT_' || v_effective_idempotency
        );

        -- Registrar en log de auditoría
        INSERT INTO public.audit_logs (
          id, action, user_id, target_table, record_id, metadata, created_at
        ) VALUES (
          gen_random_uuid(),
          'GAME_SESSION_FORFEIT_SETTLED',
          v_caller_id,
          'game_sessions',
          v_session.id::text,
          jsonb_build_object(
            'table_id', p_table_id,
            'abandoned_user_id', v_caller_id,
            'winner_user_id', v_remaining_player.user_id,
            'settlement', v_settle_result
          ),
          NOW()
        );

        RETURN jsonb_build_object(
          'success', true,
          'action', 'WINNER_DECLARED_BY_ABANDON',
          'abandoned_user_id', v_caller_id,
          'winner_user_id', v_remaining_player.user_id,
          'refund_amount', v_refund_amount,
          'settlement', v_settle_result
        );
      END IF;

    -- Caso Multijugador (3 o más jugadores): La partida continúa con los restantes
    ELSIF v_active_players_count > 1 THEN
      -- Si era el turno del jugador que abandona, avanzar el turno al siguiente jugador activo
      IF v_session.current_turn_user_id = v_caller_id THEN
        SELECT user_id INTO v_next_player
        FROM public.game_table_players
        WHERE table_id = p_table_id
          AND status IN ('PLAYING', 'JOINED', 'READY')
          AND user_id <> v_caller_id
        ORDER BY seat_number ASC
        LIMIT 1;

        IF v_next_player.user_id IS NOT NULL THEN
          UPDATE public.game_sessions
          SET current_turn_user_id = v_next_player.user_id,
              turn_deadline_at = NOW() + INTERVAL '30 seconds',
              updated_at = NOW()
          WHERE id = v_session.id;
        END IF;
      END IF;

      -- Registrar auditoría del abandono multijugador
      INSERT INTO public.audit_logs (
        id, action, user_id, target_table, record_id, metadata, created_at
      ) VALUES (
        gen_random_uuid(),
        'MULTIPLAYER_PLAYER_ABANDONED',
        v_caller_id,
        'game_tables',
        p_table_id::text,
        jsonb_build_object(
          'session_id', v_session.id,
          'remaining_players', v_active_players_count
        ),
        NOW()
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'PLAYER_ABANDONED_CONTINUE',
        'abandoned_user_id', v_caller_id,
        'remaining_players', v_active_players_count,
        'table_id', p_table_id
      );

    -- Caso extraordinario: Todos abandonaron
    ELSE
      UPDATE public.game_sessions
      SET status = 'CANCELLED'::session_status_enum,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = v_session.id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          updated_at = NOW()
      WHERE id = p_table_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'ALL_ABANDONED_CLOSED',
        'table_id', p_table_id,
        'remaining_players', 0
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refund_amount', v_refund_amount,
    'remaining_players', v_active_players_count
  );
END;
$$;

-- Permisos de ejecución
GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role, anon;

-- Sobrecargas de compatibilidad para evitar cualquier error de resolución de tipos
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_idempotency_key TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.abandon_game_table_secure(p_table_id, NULL, p_idempotency_key);
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, TEXT) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 85: 083_fix_settle_game_session_ambiguity_and_chess_sync.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 083
-- CORRECCIÓN DEFINITIVA DE AMBIGÜEDAD EN SETTLE_GAME_SESSION & INICIO SINCRONIZADO AJEDREZ
-- ==============================================================================
-- 1. Elimina la ambigüedad en PostgREST que causaba el error "Multiple functions: public.settle_game_session".
-- 2. Elimina sobrecargas duplicadas (UUID, TEXT[], INTEGER, TEXT) y (UUID, UUID[], SMALLINT, VARCHAR).
-- 3. Define la función canónica única public.settle_game_session(UUID, UUID[], INTEGER, TEXT).
-- 4. Actualiza public.start_game_session_secure para soportar el inicio sincronizado de Ajedrez (15s por turno).
-- ==============================================================================

-- 1. ELIMINACIÓN EXPLÍCITA DE TODAS LAS SOBRECARGAS CONFLICTIVAS
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, TEXT[], INTEGER, TEXT);
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, UUID[], SMALLINT, VARCHAR);
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, UUID[], INTEGER, TEXT);

-- 2. FUNCIÓN CANÓNICA ÚNICA: SETTLE_GAME_SESSION
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_winner_id UUID;
  v_winner_wallet RECORD;
  v_winner_count INT;
  v_individual_prize NUMERIC(14,2);
  v_distributed_sum NUMERIC(14,2) := 0.00;
  v_winner_ledger_id UUID;
  v_settlement_type settlement_type_enum;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
BEGIN
  -- 1. Control de Autorización (Participante de la mesa, Rol Operador+ o Motor Servidor)
  v_caller_id := auth.uid();
  
  -- Verificar si la sesión existe primero
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión de juego % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa de juego no encontrada';
  END IF;

  IF v_caller_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = v_table.id AND user_id = v_caller_id
    ) INTO v_is_participant;

    IF NOT v_is_participant AND NOT public.has_role(v_caller_id, 'OPERATOR') AND NOT public.has_role(v_caller_id, 'ADMIN') AND NOT public.has_role(v_caller_id, 'SUPER_ADMIN') THEN
      RAISE EXCEPTION 'UNAUTHORIZED: No tienes permisos para liquidar esta partida';
    END IF;
  END IF;

  -- 2. Idempotencia Estricta
  v_effective_idempotency := COALESCE(p_idempotency_key, 'settle_' || p_session_id::text);

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id OR idempotency_key = v_effective_idempotency
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'settlement_id', v_existing_settlement.id,
      'gross_pool', v_existing_settlement.gross_pool,
      'prize_pool', v_existing_settlement.prize_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'winner_count', array_length(p_winner_user_ids, 1)
    );
  END IF;

  -- 3. Calcular Pozos Oficiales (90% Ganador / 10% Plataforma)
  SELECT COUNT(DISTINCT user_id) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  IF v_player_count < 1 THEN
    v_player_count := GREATEST(1, v_table.current_players);
  END IF;

  v_gross_pool := ROUND((v_table.entry_fee * v_player_count)::numeric, 2);
  v_platform_fee := ROUND((v_gross_pool * 0.10)::numeric, 2);
  v_prize_pool := ROUND((v_gross_pool - v_platform_fee)::numeric, 2);

  v_winner_count := COALESCE(array_length(p_winner_user_ids, 1), 0);
  IF v_winner_count < 1 THEN
    RAISE EXCEPTION 'INVALID_WINNERS: Se requiere al menos un ganador para liquidar la partida';
  END IF;

  v_individual_prize := ROUND((v_prize_pool / v_winner_count)::numeric, 2);

  -- Determinar tipo de liquidación
  IF v_winner_count = 1 THEN
    v_settlement_type := 'STANDARD_WIN'::settlement_type_enum;
  ELSE
    v_settlement_type := 'SPLIT_POT'::settlement_type_enum;
  END IF;

  -- 4. Registrar Liquidación Principal en game_settlements
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id, session_id, table_id, game_type, total_pot, gross_pool, prize_pool, platform_fee,
    settlement_type, status, idempotency_key, metadata, created_at, updated_at
  ) VALUES (
    v_settlement_id, p_session_id, v_table.id, v_table.game_type, v_gross_pool, v_gross_pool, v_prize_pool, v_platform_fee,
    v_settlement_type, 'COMPLETED'::settlement_status_enum, v_effective_idempotency,
    jsonb_build_object(
      'winner_user_ids', p_winner_user_ids,
      'winner_team', p_winner_team,
      'player_count', v_player_count,
      'settled_by', v_caller_id
    ),
    NOW(), NOW()
  );

  -- 5. Acreditar Premio(s) a Billetera y Registrar en Ledger con balance_after
  FOREACH v_winner_id IN ARRAY p_winner_user_ids LOOP
    SELECT * INTO v_winner_wallet
    FROM public.wallets
    WHERE user_id = v_winner_id
    FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.wallets (user_id, balance, bonus_balance, is_active, created_at, updated_at)
      VALUES (v_winner_id, v_individual_prize, 0.00, true, NOW(), NOW())
      RETURNING * INTO v_winner_wallet;
    ELSE
      UPDATE public.wallets
      SET balance = balance + v_individual_prize,
          updated_at = NOW()
      WHERE id = v_winner_wallet.id
      RETURNING * INTO v_winner_wallet;
    END IF;

    -- Registrar Entrada en Ledger para el Ganador
    v_winner_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id, wallet_id, user_id, type, amount, balance_after,
      reference_id, reference_type, description, metadata, created_at
    ) VALUES (
      v_winner_ledger_id, v_winner_wallet.id, v_winner_id,
      'PRIZE_CREDIT'::ledger_entry_type_enum, v_individual_prize, v_winner_wallet.balance,
      p_session_id, 'game_session',
      'Premio acreditado por victoria en ' || v_table.game_type::text,
      jsonb_build_object(
        'table_id', v_table.id,
        'gross_pool', v_gross_pool,
        'prize_pool', v_prize_pool,
        'platform_fee', v_platform_fee,
        'settlement_id', v_settlement_id
      ),
      NOW()
    );

    -- Registrar Destinatario en game_settlement_recipients
    INSERT INTO public.game_settlement_recipients (
      id, settlement_id, user_id, amount_won, payout_amount,
      ledger_entry_id, status, created_at
    ) VALUES (
      gen_random_uuid(), v_settlement_id, v_winner_id, v_individual_prize, v_individual_prize,
      v_winner_ledger_id, 'PAID'::recipient_payout_status_enum, NOW()
    );

    v_distributed_sum := v_distributed_sum + v_individual_prize;
  END LOOP;

  -- 6. Cerrar Sesión y Mesa de Juego
  UPDATE public.game_sessions
  SET status = 'SETTLED'::session_status_enum,
      winner_user_id = p_winner_user_ids[1],
      winner_team = p_winner_team,
      gross_pool = v_gross_pool,
      prize_pool = v_prize_pool,
      platform_fee = v_platform_fee,
      ended_at = NOW(),
      is_settled = TRUE
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'settlement_id', v_settlement_id,
    'gross_pool', v_gross_pool,
    'prize_pool', v_prize_pool,
    'platform_fee', v_platform_fee,
    'winner_count', v_winner_count
  );
END;
$$;

-- Permisos de Ejecución
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, service_role, anon;

-- 3. RECONCILIACIÓN Y SOPORTE DE INICIO SINCRONIZADO PARA AJEDREZ (15S POR TURNO)
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_unique_players_count INT;
  v_players JSONB := '[]'::jsonb;
  v_player_order JSONB := '[]'::jsonb;
  v_lives JSONB := '{}'::jsonb;
  v_scores JSONB := '{}'::jsonb;
  v_player_record RECORD;
  v_session_id UUID;
  v_first_turn_user_id UUID;
  v_white_player_id UUID;
  v_black_player_id UUID;
  v_initial_state JSONB;
  v_deadline TIMESTAMPTZ;
  v_turn_seconds INT := 10;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para iniciar la partida';
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  IF v_table.host_user_id <> v_user_id THEN
    RAISE EXCEPTION 'ONLY_HOST_CAN_START: Únicamente el Anfitrión de la mesa puede iniciar la partida';
  END IF;

  -- Si ya existe una sesión activa o en curso, retornarla
  SELECT id INTO v_session_id
  FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS');

  IF v_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'session_id', v_session_id,
      'table_id', p_table_id,
      'already_active', true
    );
  END IF;

  -- Validar cantidad de jugadores DISTINTOS activos en la mesa
  SELECT COUNT(DISTINCT gtp.user_id) INTO v_unique_players_count
  FROM public.game_table_players gtp
  WHERE gtp.table_id = p_table_id
    AND gtp.status != 'LEFT'::player_table_status_enum;

  IF v_unique_players_count < v_table.min_players THEN
    RAISE EXCEPTION 'NOT_ENOUGH_PLAYERS: Se requieren al menos % jugadores diferentes para iniciar la partida (actualmente hay %)', v_table.min_players, v_unique_players_count;
  END IF;

  -- Compilar lista de jugadores activos
  FOR v_player_record IN (
    SELECT DISTINCT ON (gtp.user_id)
      gtp.user_id, gtp.seat_number, p.display_name, p.first_name, p.last_name, p.avatar_url
    FROM public.game_table_players gtp
    JOIN public.profiles p ON p.user_id = gtp.user_id
    WHERE gtp.table_id = p_table_id
      AND gtp.status != 'LEFT'::player_table_status_enum
    ORDER BY gtp.user_id, gtp.seat_number ASC
  ) LOOP
    IF v_first_turn_user_id IS NULL THEN
      v_first_turn_user_id := v_player_record.user_id;
      v_white_player_id := v_player_record.user_id;
    ELSEIF v_black_player_id IS NULL THEN
      v_black_player_id := v_player_record.user_id;
    END IF;

    v_player_order := v_player_order || to_jsonb(v_player_record.user_id::text);
    v_lives := jsonb_set(v_lives, ARRAY[v_player_record.user_id::text], '3'::jsonb);
    v_scores := jsonb_set(v_scores, ARRAY[v_player_record.user_id::text], '0'::jsonb);

    v_players := v_players || jsonb_build_object(
      'userId', v_player_record.user_id,
      'seatNumber', v_player_record.seat_number,
      'displayName', COALESCE(NULLIF(trim(v_player_record.display_name), ''), trim(COALESCE(v_player_record.first_name, '') || ' ' || COALESCE(v_player_record.last_name, ''))),
      'avatarUrl', v_player_record.avatar_url,
      'lives', 3
    );
  END LOOP;

  -- Configuración Específica para Ajedrez (CHESS)
  IF v_table.game_type::text = 'CHESS' OR v_table.game_type = 'CHESS'::game_type_enum THEN
    v_white_player_id := v_table.host_user_id;
    IF v_black_player_id IS NULL OR v_black_player_id = v_white_player_id THEN
      SELECT gtp.user_id INTO v_black_player_id
      FROM public.game_table_players gtp
      WHERE gtp.table_id = p_table_id
        AND gtp.status != 'LEFT'::player_table_status_enum
        AND gtp.user_id != v_white_player_id
      LIMIT 1;
    END IF;
    v_first_turn_user_id := v_white_player_id;
    v_turn_seconds := 15; -- Mínimo 15s para Ajedrez
    v_deadline := NOW() + (v_turn_seconds || ' seconds')::interval;

    v_initial_state := jsonb_build_object(
      'fen', 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
      'playerWhiteUserId', v_white_player_id,
      'playerBlackUserId', v_black_player_id,
      'currentTurnUserId', v_first_turn_user_id,
      'turnExpiresAt', v_deadline,
      'moveHistory', '[]'::jsonb,
      'winnerUserId', NULL,
      'isDraw', false
    );
  ELSE
    v_deadline := NOW() + INTERVAL '10 seconds';
    v_initial_state := jsonb_build_object(
      'status', 'PLAYING',
      'playerOrder', v_player_order,
      'players', v_players,
      'currentTurnUserId', v_first_turn_user_id,
      'lives', v_lives,
      'scores', v_scores,
      'round', 1
    );
  END IF;

  v_session_id := gen_random_uuid();

  -- Crear sesión en game_sessions usando el estado ACTIVE del enum
  INSERT INTO public.game_sessions (
    id, table_id, game_type, session_number, status, current_state,
    current_turn_user_id, turn_deadline_at, started_at
  ) VALUES (
    v_session_id, p_table_id, v_table.game_type, 1, 'ACTIVE'::session_status_enum,
    v_initial_state, v_first_turn_user_id, v_deadline, NOW()
  );

  -- Actualizar estado de la mesa a ACTIVE y registrar started_at de forma segura
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      started_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'table_id', p_table_id,
    'current_turn_user_id', v_first_turn_user_id,
    'turn_deadline_at', v_deadline,
    'already_active', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 86: 084_canonical_settle_game_session_fix.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 084
-- CORRECCIÓN DEFINITIVA DE FIRMAS Y DUPLICADOS EN RPC SETTLE_GAME_SESSION
-- ==============================================================================
-- 1. Elimina explícitamente cualquier sobrecarga antigua que cause ambigüedad en PostgREST:
--    - settle_game_session(UUID, TEXT[], INTEGER, TEXT)
--    - settle_game_session(UUID, UUID[], SMALLINT, VARCHAR)
--    - settle_game_session(UUID, UUID[], INTEGER, TEXT)
-- 2. Crea UNA SOLA función canónica oficial con tipos estrictos:
--    public.settle_game_session(
--      p_session_id UUID,
--      p_winner_user_ids UUID[],
--      p_winner_team INTEGER DEFAULT NULL,
--      p_idempotency_key TEXT DEFAULT NULL
--    )
-- 3. Mantiene intactos: SECURITY DEFINER, search_path seguro, regla financiera 90/10,
--    ledger inmutable, wallet, idempotencia, RLS y liquidación de mesas.
-- 4. Asigna permisos canónicos a: authenticated, anon, service_role.
-- ==============================================================================

-- 1. ELIMINACIÓN DE SOBRECARGAS INCOMPATIBLES
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, TEXT[], INTEGER, TEXT);
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, UUID[], SMALLINT, VARCHAR);
DROP FUNCTION IF EXISTS public.settle_game_session(UUID, UUID[], INTEGER, TEXT);

-- 2. CREACIÓN DE LA FUNCIÓN CANÓNICA ÚNICA
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_winner_id UUID;
  v_winner_wallet RECORD;
  v_winner_count INT;
  v_individual_prize NUMERIC(14,2);
  v_distributed_sum NUMERIC(14,2) := 0.00;
  v_winner_ledger_id UUID;
  v_settlement_type settlement_type_enum;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
BEGIN
  -- 1. Identificación del invocador y control de autorización
  v_caller_id := auth.uid();
  
  -- Verificar existencia de la sesión con bloqueo de fila para evitar condiciones de carrera (TOCTOU)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión de juego % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa de juego no encontrada';
  END IF;

  -- Si es invocado por un usuario autenticado, validar que sea participante o rol administrativo
  IF v_caller_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = v_table.id AND user_id = v_caller_id
    ) INTO v_is_participant;

    IF NOT v_is_participant AND NOT public.has_role(v_caller_id, 'OPERATOR') AND NOT public.has_role(v_caller_id, 'ADMIN') AND NOT public.has_role(v_caller_id, 'SUPER_ADMIN') THEN
      RAISE EXCEPTION 'UNAUTHORIZED: No tienes permisos para liquidar esta partida';
    END IF;
  END IF;

  -- 2. Manejo de Idempotencia estricta
  v_effective_idempotency := COALESCE(p_idempotency_key, 'settle_' || p_session_id::TEXT);

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE idempotency_key = v_effective_idempotency
     OR session_id = p_session_id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'settlement_id', v_existing_settlement.id,
      'gross_pool', v_existing_settlement.gross_pool,
      'prize_pool', v_existing_settlement.prize_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'message', 'Partida ya liquidada previamente de forma segura'
    );
  END IF;

  -- 3. Cálculo de Pozos Financieros (Regla 90% Ganador / 10% Plataforma)
  SELECT COUNT(*) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  IF v_player_count < 1 THEN
    v_player_count := 2; -- Fallback seguro de quorum
  END IF;

  v_gross_pool := ROUND((v_table.entry_fee * v_player_count)::NUMERIC, 2);
  v_prize_pool := ROUND((v_gross_pool * 0.90)::NUMERIC, 2);
  v_platform_fee := ROUND((v_gross_pool - v_prize_pool)::NUMERIC, 2);

  v_winner_count := COALESCE(array_length(p_winner_user_ids, 1), 0);

  -- 4. Determinar tipo de liquidación
  IF v_winner_count = 0 THEN
    v_settlement_type := 'REFUND_TECHNICAL_DRAW'::settlement_type_enum;
  ELSIF v_winner_count = 1 THEN
    v_settlement_type := 'WINNER_TAKES_ALL'::settlement_type_enum;
  ELSE
    v_settlement_type := 'SPLIT_POT'::settlement_type_enum;
  END IF;

  -- 5. Crear Registro Maestro de Liquidación en game_settlements
  INSERT INTO public.game_settlements (
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    currency,
    idempotency_key,
    created_at
  ) VALUES (
    p_session_id,
    v_table.id,
    v_settlement_type,
    v_gross_pool,
    v_prize_pool,
    v_platform_fee,
    v_table.currency,
    v_effective_idempotency,
    NOW()
  ) RETURNING id INTO v_settlement_id;

  -- 6. Distribución y Acreditación de Ganadores
  IF v_winner_count > 0 THEN
    v_individual_prize := TRUNC((v_prize_pool / v_winner_count)::NUMERIC, 2);

    FOREACH v_winner_id IN ARRAY p_winner_user_ids
    LOOP
      -- Obtener o inicializar billetera con bloqueo de fila
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_winner_id AND currency = v_table.currency
      FOR UPDATE;

      IF NOT FOUND THEN
        INSERT INTO public.wallets (user_id, currency, balance, created_at, updated_at)
        VALUES (v_winner_id, v_table.currency, 0.00, NOW(), NOW())
        RETURNING * INTO v_winner_wallet;
      END IF;

      -- Actualizar saldo de la billetera
      UPDATE public.wallets
      SET balance = balance + v_individual_prize,
          updated_at = NOW()
      WHERE id = v_winner_wallet.id;

      -- Registrar transacción inmutable en el Ledger
      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        reference_id,
        reference_type,
        balance_before,
        balance_after,
        metadata,
        created_at
      ) VALUES (
        v_winner_wallet.id,
        v_winner_id,
        v_individual_prize,
        v_table.currency,
        'PRIZE_PAYOUT'::ledger_entry_type_enum,
        v_settlement_id,
        'game_settlement',
        v_winner_wallet.balance,
        v_winner_wallet.balance + v_individual_prize,
        jsonb_build_object(
          'session_id', p_session_id,
          'table_id', v_table.id,
          'game_type', v_table.game_type,
          'idempotency_key', v_effective_idempotency,
          'description', 'Premio de victoria en ' || v_table.game_type
        ),
        NOW()
      ) RETURNING id INTO v_winner_ledger_id;

      -- Registrar detalle en settlement_recipients
      INSERT INTO public.settlement_recipients (
        settlement_id,
        user_id,
        payout_amount,
        ledger_entry_id,
        created_at
      ) VALUES (
        v_settlement_id,
        v_winner_id,
        v_individual_prize,
        v_winner_ledger_id,
        NOW()
      );

      v_distributed_sum := v_distributed_sum + v_individual_prize;
    END LOOP;
  ELSE
    -- Reembolso íntegro en caso de empate técnico o sin ganadores
    FOR v_player IN (
      SELECT DISTINCT user_id FROM public.game_table_players WHERE table_id = v_table.id
    ) LOOP
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_player.user_id AND currency = v_table.currency
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET balance = balance + v_table.entry_fee,
            updated_at = NOW()
        WHERE id = v_winner_wallet.id;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          amount,
          currency,
          entry_type,
          reference_id,
          reference_type,
          balance_before,
          balance_after,
          metadata,
          created_at
        ) VALUES (
          v_winner_wallet.id,
          v_player.user_id,
          v_table.entry_fee,
          v_table.currency,
          'REFUND'::ledger_entry_type_enum,
          v_settlement_id,
          'game_settlement',
          v_winner_wallet.balance,
          v_winner_wallet.balance + v_table.entry_fee,
          jsonb_build_object(
            'session_id', p_session_id,
            'table_id', v_table.id,
            'reason', 'Empate técnico o anulación segura'
          ),
          NOW()
        );
      END IF;
    END LOOP;
  END IF;

  -- 7. Actualizar Estados de Sesión y Mesa
  UPDATE public.game_sessions
  SET status = 'SETTLED'::game_session_status_enum,
      winner_user_id = p_winner_user_ids[1],
      winner_team = p_winner_team,
      gross_pool = v_gross_pool,
      prize_pool = v_prize_pool,
      platform_fee = v_platform_fee,
      ended_at = NOW(),
      is_settled = TRUE
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'settlement_id', v_settlement_id,
    'gross_pool', v_gross_pool,
    'prize_pool', v_prize_pool,
    'platform_fee', v_platform_fee,
    'winner_count', v_winner_count
  );
END;
$$;

-- 3. PERMISOS DE EJECUCIÓN ESTRICTOS
REVOKE ALL ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 87: 085_cleanup_audit_game_session.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 085
-- FUNCIÓN RPC DE LIMPIEZA SEGURA PARA AUDITORÍAS DE JUEGO (cleanup_audit_game_session)
-- ==============================================================================
-- 1. Permite cerrar y sanear de forma segura mesas y sesiones de prueba (AUDIT_TEST)
--    asociadas al usuario auditor para prevenir el bloqueo por ALREADY_IN_ACTIVE_TABLE.
-- 2. REGLA ESTRICTA DE SEGURIDAD: NUNCA altera, borra ni cierra mesas de dinero real
--    o partidas activas legítimas de los usuarios.
-- 3. Si el usuario participa en una partida real, reporta real_active_tables > 0
--    sin modificar ningún registro.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.cleanup_audit_game_session(
  p_user_id UUID DEFAULT NULL,
  p_game_type TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_target_user_id UUID;
  v_cleaned_tables_count INT := 0;
  v_cleaned_sessions_count INT := 0;
  v_real_active_tables_count INT := 0;
  v_audit_table_ids UUID[];
  v_game_type_clean TEXT;
BEGIN
  -- 1. Identificar el usuario objetivo (parámetro o invocador autenticado)
  v_target_user_id := COALESCE(p_user_id, auth.uid());
  
  IF v_target_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'USER_REQUIRED: Se requiere un UUID de usuario válido',
      'cleaned_tables', 0,
      'cleaned_sessions', 0,
      'real_active_tables', 0
    );
  END IF;

  v_game_type_clean := NULLIF(TRIM(LOWER(p_game_type)), '');

  -- 2. Detectar si el usuario tiene partidas REALES activas en este juego
  SELECT COUNT(DISTINCT gt.id) INTO v_real_active_tables_count
  FROM public.game_tables gt
  JOIN public.game_table_players gtp ON gtp.table_id = gt.id
  WHERE gtp.user_id = v_target_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
    AND (v_game_type_clean IS NULL OR gt.game_type::text = v_game_type_clean)
    AND NOT (
      gt.name ILIKE '%AUDIT_TEST%' 
      OR gt.name ILIKE 'Mesa AUDIT%' 
      OR gt.invite_code ILIKE 'AUDIT%'
      OR gt.share_token ILIKE 'AUDIT%'
    );

  -- 3. Identificar mesas de AUDITORÍA (AUDIT_TEST) asociadas al usuario
  SELECT ARRAY_AGG(DISTINCT gt.id) INTO v_audit_table_ids
  FROM public.game_tables gt
  LEFT JOIN public.game_table_players gtp ON gtp.table_id = gt.id
  WHERE (gtp.user_id = v_target_user_id OR gt.host_user_id = v_target_user_id)
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
    AND (v_game_type_clean IS NULL OR gt.game_type::text = v_game_type_clean)
    AND (
      gt.name ILIKE '%AUDIT_TEST%' 
      OR gt.name ILIKE 'Mesa AUDIT%' 
      OR gt.invite_code ILIKE 'AUDIT%'
      OR gt.share_token ILIKE 'AUDIT%'
    );

  -- 4. Cerrar de forma segura las mesas de auditoría detectadas
  IF v_audit_table_ids IS NOT NULL AND ARRAY_LENGTH(v_audit_table_ids, 1) > 0 THEN
    -- Actualizar estado de jugadores en mesas de auditoría
    UPDATE public.game_table_players
    SET status = 'LEFT'
    WHERE table_id = ANY(v_audit_table_ids);

    -- Actualizar sesiones de juego asociadas a auditoría
    WITH closed_s AS (
      UPDATE public.game_sessions
      SET status = 'SETTLED'::game_session_status_enum,
          ended_at = NOW(),
          is_settled = TRUE
      WHERE table_id = ANY(v_audit_table_ids)
        AND status::text NOT IN ('SETTLED', 'CLOSED', 'CANCELLED', 'FINISHED')
      RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned_sessions_count FROM closed_s;

    -- Actualizar y cerrar mesas de prueba
    WITH closed_t AS (
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          updated_at = NOW()
      WHERE id = ANY(v_audit_table_ids)
      RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned_tables_count FROM closed_t;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_target_user_id,
    'game_type', v_game_type_clean,
    'cleaned_tables', v_cleaned_tables_count,
    'cleaned_sessions', v_cleaned_sessions_count,
    'real_active_tables', v_real_active_tables_count,
    'message', CASE 
      WHEN v_real_active_tables_count > 0 THEN 'Usuario participa en partida real de ' || COALESCE(v_game_type_clean, 'juego') || '. Auditoría omitida.'
      WHEN v_cleaned_tables_count > 0 THEN 'Mesas de auditoría previas cerradas correctamente (' || v_cleaned_tables_count || ' mesas).'
      ELSE 'No se requirió limpieza previa.'
    END
  );
END;
$$;

-- Permisos estrictos
REVOKE ALL ON FUNCTION public.cleanup_audit_game_session(UUID, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cleanup_audit_game_session(UUID, TEXT) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 88: 086_fix_get_or_create_automated_bingo_table_and_audit_isolation.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 086
-- CORRECCIÓN CONTROLADA RPC get_or_create_automated_bingo_table
-- Y AISLAMIENTO IDEMPOTENTE AUDIT_TEST vs PARTIDAS REALES
-- ==============================================================================
-- 1. Actualiza public.get_or_create_automated_bingo_table() para:
--    a) Limpieza idempotente previa de residuos de auditoría (AUDIT_TEST).
--    b) Búsqueda robusta de mesas automáticas activas (OPEN, READY, WAITING, STARTING).
--    c) Protección estricta: NUNCA altera ni borra partidas reales de dinero real.
-- 2. Asegura que create_game_table_secure y join_game_table_secure aíslen
--    estrictamente registros de prueba (AUDIT_TEST) de partidas reales.
-- 3. Mantiene intactos: Wallet, Ledger, RLS, permisos y compatibilidad con Frontend.
-- ==============================================================================

-- 1. ACTUALIZACIÓN CANÓNICA DE get_or_create_automated_bingo_table
CREATE OR REPLACE FUNCTION public.get_or_create_automated_bingo_table(
  p_variant TEXT DEFAULT '75',
  p_entry_fee NUMERIC DEFAULT 10.00
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_variant TEXT;
  v_table RECORD;
  v_table_id UUID;
  v_session_id UUID;
  v_invite_code TEXT;
  v_name TEXT;
  v_total_balls INT;
  v_audit_table_ids UUID[];
BEGIN
  v_caller_id := auth.uid();
  v_variant := COALESCE(p_variant, '75');
  IF v_variant NOT IN ('75', '80', '90') THEN
    v_variant := '75';
  END IF;

  v_total_balls := CASE WHEN v_variant = '90' THEN 90 WHEN v_variant = '80' THEN 80 ELSE 75 END;

  -- 1. LIMPIEZA IDEMPOTENTE DE RESIDUOS AUDIT_TEST DEL INVOCADOR (SI EXISTEN)
  IF v_caller_id IS NOT NULL THEN
    SELECT ARRAY_AGG(DISTINCT gt.id) INTO v_audit_table_ids
    FROM public.game_tables gt
    LEFT JOIN public.game_table_players gtp ON gtp.table_id = gt.id
    WHERE (gtp.user_id = v_caller_id OR gt.host_user_id = v_caller_id)
      AND gt.game_type::text IN ('BINGO', 'bingo')
      AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
      AND (
        gt.name ILIKE '%AUDIT_TEST%' 
        OR gt.name ILIKE 'Mesa AUDIT%' 
        OR gt.invite_code ILIKE 'AUDIT%'
        OR gt.share_token ILIKE 'AUDIT%'
      );

    IF v_audit_table_ids IS NOT NULL AND ARRAY_LENGTH(v_audit_table_ids, 1) > 0 THEN
      UPDATE public.game_table_players
      SET status = 'LEFT',
          left_at = COALESCE(left_at, NOW()),
          updated_at = NOW()
      WHERE table_id = ANY(v_audit_table_ids);

      UPDATE public.game_sessions
      SET status = 'SETTLED'::game_session_status_enum,
          ended_at = NOW(),
          is_settled = TRUE
      WHERE table_id = ANY(v_audit_table_ids)
        AND status::text NOT IN ('SETTLED', 'CLOSED', 'CANCELLED', 'FINISHED');

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          updated_at = NOW()
      WHERE id = ANY(v_audit_table_ids);
    END IF;
  END IF;

  -- 2. BUSCAR MESA AUTOMATIZADA ACTIVA EXISTENTE PARA ESTA VARIANTE
  -- (Excluyendo mesas de prueba AUDIT_TEST)
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE game_type::text IN ('BINGO', 'bingo')
    AND (config->>'variant') = v_variant
    AND (config->>'automated')::boolean IS TRUE
    AND status IN ('OPEN'::table_status_enum, 'READY'::table_status_enum, 'WAITING'::table_status_enum, 'STARTING'::table_status_enum)
    AND NOT (
      name ILIKE '%AUDIT_TEST%' 
      OR name ILIKE 'Mesa AUDIT%' 
      OR invite_code ILIKE 'AUDIT%'
    )
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'table_id', v_table.id,
      'variant', v_variant,
      'status', v_table.status,
      'current_players_count', v_table.current_players_count,
      'min_players', v_table.min_players,
      'max_players', v_table.max_players,
      'entry_fee', v_table.entry_fee,
      'config', v_table.config
    );
  END IF;

  -- 3. CREAR NUEVA MESA PÚBLICA AUTOMATIZADA DE BINGO VIRTUAL
  v_invite_code := 'PUB-BINGO-' || v_variant || '-' || UPPER(encode(gen_random_bytes(3), 'hex'));
  v_name := 'Sorteo Bingo Virtual ' || v_variant || ' Bolas';

  INSERT INTO public.game_tables (
    game_type,
    name,
    mode,
    currency,
    min_players,
    max_players,
    current_players_count,
    status,
    is_private,
    invite_code,
    join_code,
    entry_fee,
    config,
    created_at,
    updated_at
  ) VALUES (
    'BINGO'::game_type_enum,
    v_name,
    'INDIVIDUAL',
    'VES',
    2,
    1000,
    0,
    'OPEN'::table_status_enum,
    false,
    v_invite_code,
    v_invite_code,
    COALESCE(p_entry_fee, 25.00),
    jsonb_build_object(
      'variant', v_variant,
      'automated', true,
      'total_balls', v_total_balls,
      'call_interval_ms', 3500,
      'min_players_required', 2
    ),
    NOW(),
    NOW()
  )
  RETURNING id INTO v_table_id;

  -- 4. CREAR SESIÓN DE JUEGO ASOCIADA
  INSERT INTO public.game_sessions (
    table_id,
    current_turn_seat,
    current_state,
    created_at,
    updated_at
  ) VALUES (
    v_table_id,
    1,
    jsonb_build_object(
      'variant', v_variant,
      'status', 'WAITING_FOR_PLAYERS',
      'totalBalls', v_total_balls,
      'drawnBalls', '[]'::jsonb,
      'currentBall', null,
      'callIntervalMs', 3500,
      'winnerUserId', null
    ),
    NOW(),
    NOW()
  )
  RETURNING id INTO v_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'session_id', v_session_id,
    'variant', v_variant,
    'status', 'OPEN',
    'current_players_count', 0,
    'min_players', 2,
    'max_players', 1000,
    'entry_fee', COALESCE(p_entry_fee, 25.00)
  );
END;
$$;

-- PERMISOS DE EJECUCIÓN
REVOKE ALL ON FUNCTION public.get_or_create_automated_bingo_table(TEXT, NUMERIC) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_or_create_automated_bingo_table(TEXT, NUMERIC) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 89: 087_fix_table_lifecycle_and_immediate_lobby_cleanup.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 087
-- CORRECCIÓN DEL CICLO DE VIDA Y LIMPIEZA INMEDIATA DE MESAS PÚBLICAS
-- ==============================================================================
-- 1. Actualiza settle_game_session para:
--    - Marcar game_tables con status = 'CLOSED', closed_at = NOW() y current_players_count = 0.
--    - Liberar atómicamente todos los asientos en game_table_players (status = 'LEFT', left_at = NOW()).
--    - Blindar la rama de idempotencia para asegurar que mesas previamente liquidadas
--      queden marcadas como CLOSED, con closed_at y jugadores como LEFT.
--    - Usar los ENUMs y tablas reales del esquema (session_status_enum, settlement_type_enum,
--      game_settlement_recipients, ledger_entries).
-- 2. Actualiza abandon_game_table_secure para:
--    - Asignar closed_at = NOW() y current_players_count = 0 en cualquier escenario donde
--      la mesa pase a estado CLOSED.
--    - Liberar asientos y liquidar por abandono canónico (1v1 forfeit).
-- 3. Crea RPC canónica get_public_available_tables(TEXT) para filtrado de alta precisión en DB:
--    - Comprueba visibilidad pública exclusiva con visibility = 'PUBLIC' (sin gt.is_private).
--    - Comprueba status = 'OPEN', closed_at IS NULL, current_players_count < max_players.
--    - Excluye cualquier mesa con sesión terminal o liquidada.
-- 4. Actualiza cleanup_audit_game_session y get_or_create_automated_bingo_table
--    para alinearlas con el esquema real de enums y columnas.
-- 5. Concilia y limpia de forma conservadora cualquier mesa huérfana o finalizada
--    sin usar cierres ciegos por antigüedad.
-- ==============================================================================

-- 1. ACTUALIZACIÓN CANÓNICA DE SETTLE_GAME_SESSION
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_winner_id UUID;
  v_winner_wallet RECORD;
  v_winner_count INT;
  v_individual_prize NUMERIC(14,2);
  v_distributed_sum NUMERIC(14,2) := 0.00;
  v_winner_ledger_id UUID;
  v_settlement_type settlement_type_enum;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
BEGIN
  -- 1. Identificación del invocador y control de autorización
  v_caller_id := auth.uid();
  
  -- Verificar existencia de la sesión con bloqueo de fila para evitar condiciones de carrera (TOCTOU)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión de juego % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa de juego no encontrada';
  END IF;

  -- Si es invocado por un usuario autenticado, validar que sea participante o rol administrativo
  IF v_caller_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = v_table.id AND user_id = v_caller_id
    ) INTO v_is_participant;

    IF NOT v_is_participant AND NOT public.has_role(v_caller_id, 'OPERATOR') AND NOT public.has_role(v_caller_id, 'ADMIN') AND NOT public.has_role(v_caller_id, 'SUPER_ADMIN') THEN
      RAISE EXCEPTION 'UNAUTHORIZED: No tienes permisos para liquidar esta partida';
    END IF;
  END IF;

  -- 2. Manejo de Idempotencia estricta
  v_effective_idempotency := COALESCE(p_idempotency_key, 'settle_' || p_session_id::TEXT);

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE idempotency_key = v_effective_idempotency
     OR session_id = p_session_id;

  IF FOUND THEN
    -- Garantizar que mesa y jugadores queden en estado terminal limpio
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = COALESCE(closed_at, NOW()),
        current_players_count = 0,
        updated_at = NOW()
    WHERE id = v_table.id;

    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = COALESCE(left_at, NOW()),
        updated_at = NOW()
    WHERE table_id = v_table.id
      AND status != 'LEFT'::player_table_status_enum;

    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'settlement_id', v_existing_settlement.id,
      'gross_pool', v_existing_settlement.gross_pool,
      'prize_pool', v_existing_settlement.prize_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'message', 'Partida ya liquidada previamente de forma segura'
    );
  END IF;

  -- 3. Cálculo de Pozos Financieros (Regla 90% Ganador / 10% Plataforma)
  SELECT COUNT(*) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  IF v_player_count < 1 THEN
    v_player_count := 2; -- Fallback seguro de quorum
  END IF;

  v_gross_pool := ROUND((v_table.entry_fee * v_player_count)::NUMERIC, 2);
  v_prize_pool := ROUND((v_gross_pool * 0.90)::NUMERIC, 2);
  v_platform_fee := ROUND((v_gross_pool - v_prize_pool)::NUMERIC, 2);

  v_winner_count := COALESCE(array_length(p_winner_user_ids, 1), 0);

  -- 4. Determinar tipo de liquidación según los enums reales (settlement_type_enum)
  IF v_winner_count = 0 THEN
    v_settlement_type := 'DRAW_REFUND'::settlement_type_enum;
  ELSIF v_winner_count = 1 THEN
    v_settlement_type := 'STANDARD_PAYOUT'::settlement_type_enum;
  ELSE
    v_settlement_type := 'SPLIT_PAYOUT'::settlement_type_enum;
  END IF;

  -- 5. Crear Registro Maestro de Liquidación en public.game_settlements
  INSERT INTO public.game_settlements (
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_at,
    settled_by
  ) VALUES (
    p_session_id,
    v_table.id,
    v_settlement_type,
    v_gross_pool,
    v_prize_pool,
    v_platform_fee,
    CASE WHEN v_winner_count > 0 THEN v_prize_pool ELSE v_gross_pool END,
    v_effective_idempotency,
    NOW(),
    COALESCE(v_caller_id::text, 'SERVER_ENGINE')
  ) RETURNING id INTO v_settlement_id;

  -- 6. Distribución y Acreditación de Ganadores
  IF v_winner_count > 0 THEN
    v_individual_prize := TRUNC((v_prize_pool / v_winner_count)::NUMERIC, 2);

    FOREACH v_winner_id IN ARRAY p_winner_user_ids
    LOOP
      -- Obtener o inicializar billetera con bloqueo de fila
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_winner_id AND currency = 'VES'
      FOR UPDATE;

      IF NOT FOUND THEN
        INSERT INTO public.wallets (user_id, currency, balance, created_at, updated_at)
        VALUES (v_winner_id, 'VES', 0.00, NOW(), NOW())
        RETURNING * INTO v_winner_wallet;
      END IF;

      -- Actualizar saldo de la billetera
      UPDATE public.wallets
      SET balance = balance + v_individual_prize,
          updated_at = NOW()
      WHERE id = v_winner_wallet.id;

      -- Registrar transacción inmutable en el Ledger
      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        reference_id,
        reference_type,
        balance_before,
        balance_after,
        metadata,
        created_at
      ) VALUES (
        v_winner_wallet.id,
        v_winner_id,
        v_individual_prize,
        'VES',
        'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
        v_settlement_id,
        'game_settlement',
        v_winner_wallet.balance,
        v_winner_wallet.balance + v_individual_prize,
        jsonb_build_object(
          'session_id', p_session_id,
          'table_id', v_table.id,
          'game_type', v_table.game_type,
          'idempotency_key', v_effective_idempotency,
          'description', 'Premio de victoria en ' || v_table.game_type
        ),
        NOW()
      ) RETURNING id INTO v_winner_ledger_id;

      -- Registrar detalle en public.game_settlement_recipients
      INSERT INTO public.game_settlement_recipients (
        settlement_id,
        user_id,
        payout_amount,
        ledger_entry_id,
        created_at
      ) VALUES (
        v_settlement_id,
        v_winner_id,
        v_individual_prize,
        v_winner_ledger_id,
        NOW()
      );

      v_distributed_sum := v_distributed_sum + v_individual_prize;
    END LOOP;
  ELSE
    -- Reembolso íntegro en caso de empate técnico o sin ganadores
    FOR v_player IN (
      SELECT DISTINCT user_id FROM public.game_table_players WHERE table_id = v_table.id
    ) LOOP
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_player.user_id AND currency = 'VES'
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET balance = balance + v_table.entry_fee,
            updated_at = NOW()
        WHERE id = v_winner_wallet.id;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          amount,
          currency,
          entry_type,
          reference_id,
          reference_type,
          balance_before,
          balance_after,
          metadata,
          created_at
        ) VALUES (
          v_winner_wallet.id,
          v_player.user_id,
          v_table.entry_fee,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          v_settlement_id,
          'game_settlement',
          v_winner_wallet.balance,
          v_winner_wallet.balance + v_table.entry_fee,
          jsonb_build_object(
            'session_id', p_session_id,
            'table_id', v_table.id,
            'reason', 'Empate técnico o anulación segura'
          ),
          NOW()
        );
      END IF;
    END LOOP;
  END IF;

  -- 7. Actualizar Estados de Sesión y Mesa de forma inmediata
  UPDATE public.game_sessions
  SET status = 'SETTLED'::session_status_enum,
      winner_user_id = p_winner_user_ids[1],
      winner_team = p_winner_team,
      ended_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      closed_at = NOW(),
      current_players_count = 0,
      updated_at = NOW()
  WHERE id = v_table.id;

  -- 8. Liberar inmediatamente todos los asientos de los jugadores
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = COALESCE(left_at, NOW()),
      updated_at = NOW()
  WHERE table_id = v_table.id
    AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'settlement_id', v_settlement_id,
    'gross_pool', v_gross_pool,
    'prize_pool', v_prize_pool,
    'platform_fee', v_platform_fee,
    'winner_count', v_winner_count
  );
END;
$$;

-- 2. ACTUALIZACIÓN DE ABANDON_GAME_TABLE_SECURE PARA ASIGNAR CLOSED_AT Y LIBERAR ASIENTOS
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_active_players_count INT;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_effective_idempotency TEXT;
  v_settle_result JSONB;
  v_remaining_player RECORD;
  v_next_player RECORD;
  v_session_is_active BOOLEAN := FALSE;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para abandonar o salir de la mesa.';
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada.';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE id = p_session_id AND table_id = p_table_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS')
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  v_session_is_active := (v_session.id IS NOT NULL AND v_session.status::text IN ('ACTIVE', 'IN_PROGRESS'));

  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND user_id = v_caller_id
    AND status IN ('PLAYING', 'JOINED', 'READY')
  FOR UPDATE;

  IF NOT FOUND THEN
    SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

    RETURN jsonb_build_object(
      'success', true,
      'already_left', true,
      'table_id', p_table_id,
      'remaining_players', v_active_players_count
    );
  END IF;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE id = v_player.id;

  IF NOT v_session_is_active THEN
    IF v_table.entry_fee > 0 THEN
      SELECT * INTO v_wallet
      FROM public.wallets
      WHERE user_id = v_caller_id AND currency = 'VES'
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET balance = balance + v_table.entry_fee,
            updated_at = NOW()
        WHERE id = v_wallet.id;

        INSERT INTO public.ledger_entries (
          wallet_id, user_id, amount, currency, entry_type,
          reference_id, reference_type, balance_before, balance_after,
          metadata, created_at
        ) VALUES (
          v_wallet.id, v_caller_id, v_table.entry_fee, 'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          p_table_id, 'game_tables',
          v_wallet.balance, v_wallet.balance + v_table.entry_fee,
          jsonb_build_object('reason', 'Reembolso por abandono voluntario de mesa previa al inicio'),
          NOW()
        );
        v_refund_amount := v_table.entry_fee;
      END IF;
    END IF;
  END IF;

  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND status IN ('PLAYING', 'JOINED', 'READY');

  UPDATE public.game_tables
  SET current_players_count = v_active_players_count,
      status = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN 'CLOSED'::table_status_enum
        WHEN status::text = 'FULL' AND v_active_players_count < max_players THEN 'OPEN'::table_status_enum
        ELSE status
      END,
      closed_at = CASE
        WHEN v_active_players_count = 0 AND status::text IN ('OPEN', 'FULL', 'WAITING') THEN NOW()
        ELSE closed_at
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  IF v_session_is_active THEN
    IF v_active_players_count = 1 THEN
      SELECT user_id INTO v_remaining_player
      FROM public.game_table_players
      WHERE table_id = p_table_id
        AND status IN ('PLAYING', 'JOINED', 'READY')
      LIMIT 1;

      IF v_remaining_player.user_id IS NOT NULL THEN
        v_settle_result := public.settle_game_session(
          v_session.id,
          ARRAY[v_remaining_player.user_id],
          1,
          'SETTLE_FORFEIT_' || v_effective_idempotency
        );

        RETURN jsonb_build_object(
          'success', true,
          'action', 'WINNER_DECLARED_BY_ABANDON',
          'abandoned_user_id', v_caller_id,
          'winner_user_id', v_remaining_player.user_id,
          'refund_amount', v_refund_amount,
          'settlement', v_settle_result
        );
      END IF;
    ELSIF v_active_players_count > 1 THEN
      IF v_session.current_turn_user_id = v_caller_id THEN
        SELECT user_id INTO v_next_player
        FROM public.game_table_players
        WHERE table_id = p_table_id
          AND status IN ('PLAYING', 'JOINED', 'READY')
          AND user_id <> v_caller_id
        ORDER BY seat_number ASC
        LIMIT 1;

        IF v_next_player.user_id IS NOT NULL THEN
          UPDATE public.game_sessions
          SET current_turn_user_id = v_next_player.user_id,
              turn_deadline_at = NOW() + INTERVAL '10 seconds'
          WHERE id = v_session.id;
        END IF;
      END IF;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'PLAYER_ABANDONED_CONTINUE',
        'abandoned_user_id', v_caller_id,
        'remaining_players', v_active_players_count,
        'table_id', p_table_id
      );
    ELSE
      UPDATE public.game_sessions
      SET status = 'CANCELLED'::session_status_enum,
          ended_at = NOW()
      WHERE id = v_session.id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;

      UPDATE public.game_table_players
      SET status = 'LEFT'::player_table_status_enum,
          left_at = COALESCE(left_at, NOW()),
          updated_at = NOW()
      WHERE table_id = p_table_id
        AND status != 'LEFT'::player_table_status_enum;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'ALL_ABANDONED_CLOSED',
        'table_id', p_table_id,
        'remaining_players', 0
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refund_amount', v_refund_amount,
    'remaining_players', v_active_players_count
  );
END;
$$;

-- Permisos canónicos
GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role, anon;

-- 3. RPC CANÓNICA PARA OBTENER MESAS PÚBLICAS DISPONIBLES DE FORMA PURA
CREATE OR REPLACE FUNCTION public.get_public_available_tables(
  p_game_type TEXT DEFAULT NULL
)
RETURNS SETOF public.game_tables
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
STABLE
AS $$
  SELECT gt.*
  FROM public.game_tables gt
  WHERE (gt.visibility = 'PUBLIC'::table_visibility_enum OR gt.visibility IS NULL)
    AND gt.status = 'OPEN'::table_status_enum
    AND gt.closed_at IS NULL
    AND gt.current_players_count < gt.max_players
    AND (gt.expires_at IS NULL OR gt.expires_at > NOW())
    AND (
      p_game_type IS NULL
      OR p_game_type = 'all'
      OR gt.game_type::text ILIKE p_game_type
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.game_sessions gs
      WHERE gs.table_id = gt.id
        AND (
          gs.ended_at IS NOT NULL
          OR gs.status::text IN ('SETTLED', 'FINISHED', 'CANCELLED', 'COMPLETED', 'ABANDONED', 'CLOSED', 'ACTIVE', 'IN_PROGRESS', 'IN_GAME')
        )
    )
  ORDER BY gt.created_at DESC;
$$;

GRANT EXECUTE ON FUNCTION public.get_public_available_tables(TEXT) TO authenticated, service_role, anon;

-- 4. ACTUALIZACIÓN CANÓNICA DE CLEANUP_AUDIT_GAME_SESSION
CREATE OR REPLACE FUNCTION public.cleanup_audit_game_session(
  p_user_id UUID DEFAULT NULL,
  p_game_type TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_target_user_id UUID;
  v_cleaned_tables_count INT := 0;
  v_cleaned_sessions_count INT := 0;
  v_real_active_tables_count INT := 0;
  v_audit_table_ids UUID[];
  v_game_type_clean TEXT;
BEGIN
  v_target_user_id := COALESCE(p_user_id, auth.uid());
  
  IF v_target_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'USER_REQUIRED: Se requiere un UUID de usuario válido',
      'cleaned_tables', 0,
      'cleaned_sessions', 0,
      'real_active_tables', 0
    );
  END IF;

  v_game_type_clean := NULLIF(TRIM(LOWER(p_game_type)), '');

  -- Detectar si el usuario tiene partidas REALES activas en este juego
  SELECT COUNT(DISTINCT gt.id) INTO v_real_active_tables_count
  FROM public.game_tables gt
  JOIN public.game_table_players gtp ON gtp.table_id = gt.id
  WHERE gtp.user_id = v_target_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
    AND (v_game_type_clean IS NULL OR gt.game_type::text = v_game_type_clean)
    AND NOT (
      gt.config->>'name' ILIKE '%AUDIT_TEST%' 
      OR gt.invite_code ILIKE 'AUDIT%'
    );

  -- Identificar mesas de AUDITORÍA (AUDIT_TEST) asociadas al usuario
  SELECT ARRAY_AGG(DISTINCT gt.id) INTO v_audit_table_ids
  FROM public.game_tables gt
  LEFT JOIN public.game_table_players gtp ON gtp.table_id = gt.id
  WHERE (gtp.user_id = v_target_user_id OR gt.host_user_id = v_target_user_id)
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
    AND (v_game_type_clean IS NULL OR gt.game_type::text = v_game_type_clean)
    AND (
      gt.config->>'name' ILIKE '%AUDIT_TEST%' 
      OR gt.invite_code ILIKE 'AUDIT%'
    );

  -- Cerrar de forma segura las mesas de auditoría detectadas
  IF v_audit_table_ids IS NOT NULL AND ARRAY_LENGTH(v_audit_table_ids, 1) > 0 THEN
    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = COALESCE(left_at, NOW()),
        updated_at = NOW()
    WHERE table_id = ANY(v_audit_table_ids);

    WITH closed_s AS (
      UPDATE public.game_sessions
      SET status = 'SETTLED'::session_status_enum,
          ended_at = NOW()
      WHERE table_id = ANY(v_audit_table_ids)
        AND status::text NOT IN ('SETTLED', 'CLOSED', 'CANCELLED', 'FINISHED')
      RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned_sessions_count FROM closed_s;

    WITH closed_t AS (
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = ANY(v_audit_table_ids)
      RETURNING id
    )
    SELECT COUNT(*) INTO v_cleaned_tables_count FROM closed_t;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'cleaned_tables', v_cleaned_tables_count,
    'cleaned_sessions', v_cleaned_sessions_count,
    'real_active_tables', v_real_active_tables_count
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_audit_game_session(UUID, TEXT) TO authenticated, service_role, anon;

-- 5. ACTUALIZACIÓN CANÓNICA DE GET_OR_CREATE_AUTOMATED_BINGO_TABLE
CREATE OR REPLACE FUNCTION public.get_or_create_automated_bingo_table(
  p_variant TEXT DEFAULT '75',
  p_entry_fee NUMERIC DEFAULT 10.00
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_host_id UUID;
  v_variant TEXT;
  v_table RECORD;
  v_table_id UUID;
  v_session_id UUID;
  v_invite_code TEXT;
  v_name TEXT;
  v_total_balls INT;
  v_audit_table_ids UUID[];
BEGIN
  v_caller_id := auth.uid();
  v_variant := COALESCE(p_variant, '75');
  IF v_variant NOT IN ('75', '80', '90') THEN
    v_variant := '75';
  END IF;

  v_total_balls := CASE WHEN v_variant = '90' THEN 90 WHEN v_variant = '80' THEN 80 ELSE 75 END;

  -- 1. LIMPIEZA IDEMPOTENTE DE RESIDUOS AUDIT_TEST DEL INVOCADOR (SI EXISTEN)
  IF v_caller_id IS NOT NULL THEN
    SELECT ARRAY_AGG(DISTINCT gt.id) INTO v_audit_table_ids
    FROM public.game_tables gt
    LEFT JOIN public.game_table_players gtp ON gtp.table_id = gt.id
    WHERE (gtp.user_id = v_caller_id OR gt.host_user_id = v_caller_id)
      AND gt.game_type::text IN ('BINGO', 'bingo')
      AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE', 'WAITING', 'IN_GAME')
      AND (
        gt.config->>'name' ILIKE '%AUDIT_TEST%' 
        OR gt.invite_code ILIKE 'AUDIT%'
      );

    IF v_audit_table_ids IS NOT NULL AND ARRAY_LENGTH(v_audit_table_ids, 1) > 0 THEN
      UPDATE public.game_table_players
      SET status = 'LEFT'::player_table_status_enum,
          left_at = COALESCE(left_at, NOW()),
          updated_at = NOW()
      WHERE table_id = ANY(v_audit_table_ids);

      UPDATE public.game_sessions
      SET status = 'SETTLED'::session_status_enum,
          ended_at = NOW()
      WHERE table_id = ANY(v_audit_table_ids)
        AND status::text NOT IN ('SETTLED', 'CLOSED', 'CANCELLED', 'FINISHED');

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = ANY(v_audit_table_ids);
    END IF;
  END IF;

  -- 2. BUSCAR MESA AUTOMATIZADA ACTIVA EXISTENTE PARA ESTA VARIANTE
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE game_type::text IN ('BINGO', 'bingo')
    AND (config->>'variant') = v_variant
    AND (config->>'automated')::boolean IS TRUE
    AND status IN ('OPEN'::table_status_enum, 'STARTING'::table_status_enum)
    AND closed_at IS NULL
    AND NOT (
      config->>'name' ILIKE '%AUDIT_TEST%' 
      OR invite_code ILIKE 'AUDIT%'
    )
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'table_id', v_table.id,
      'variant', v_variant,
      'status', v_table.status,
      'current_players_count', v_table.current_players_count,
      'min_players', v_table.min_players,
      'max_players', v_table.max_players,
      'entry_fee', v_table.entry_fee,
      'config', v_table.config
    );
  END IF;

  -- 3. CREAR NUEVA MESA PÚBLICA AUTOMATIZADA DE BINGO VIRTUAL
  v_invite_code := 'PUB-BINGO-' || v_variant || '-' || UPPER(encode(gen_random_bytes(3), 'hex'));
  v_name := 'Sorteo Bingo Virtual ' || v_variant || ' Bolas';
  
  v_host_id := COALESCE(
    v_caller_id,
    (SELECT user_id FROM public.profiles WHERE role IN ('SUPER_ADMIN', 'ADMIN', 'OPERATOR') LIMIT 1),
    (SELECT user_id FROM public.profiles LIMIT 1)
  );

  INSERT INTO public.game_tables (
    game_type,
    host_user_id,
    visibility,
    entry_fee,
    min_players,
    max_players,
    current_players_count,
    status,
    invite_code,
    expires_at,
    config,
    created_at,
    updated_at
  ) VALUES (
    'BINGO'::game_type_enum,
    v_host_id,
    'PUBLIC'::table_visibility_enum,
    COALESCE(p_entry_fee, 25.00),
    2,
    1000,
    0,
    'OPEN'::table_status_enum,
    v_invite_code,
    NOW() + INTERVAL '30 days',
    jsonb_build_object(
      'name', v_name,
      'mode', 'INDIVIDUAL',
      'variant', v_variant,
      'automated', true,
      'total_balls', v_total_balls,
      'call_interval_ms', 3500,
      'min_players_required', 2
    ),
    NOW(),
    NOW()
  )
  RETURNING id INTO v_table_id;

  -- 4. CREAR SESIÓN DE JUEGO ASOCIADA
  INSERT INTO public.game_sessions (
    table_id,
    game_type,
    session_number,
    status,
    current_state,
    created_at
  ) VALUES (
    v_table_id,
    'BINGO'::game_type_enum,
    1,
    'WAITING'::session_status_enum,
    jsonb_build_object(
      'variant', v_variant,
      'status', 'WAITING_FOR_PLAYERS',
      'totalBalls', v_total_balls,
      'drawnBalls', '[]'::jsonb,
      'currentBall', null,
      'callIntervalMs', 3500,
      'winnerUserId', null
    ),
    NOW()
  )
  RETURNING id INTO v_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'session_id', v_session_id,
    'variant', v_variant,
    'status', 'OPEN',
    'current_players_count', 0,
    'min_players', 2,
    'max_players', 1000,
    'entry_fee', COALESCE(p_entry_fee, 25.00)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_or_create_automated_bingo_table(TEXT, NUMERIC) TO authenticated, service_role, anon;

-- 6. CONCILIACIÓN INICIAL CONSERVADORA DE RESIDUOS Y MESAS TERMINADAS
-- Cierra únicamente mesas con sesiones finalizadas/liquidadas, expiradas o sin jugadores
UPDATE public.game_tables gt
SET status = 'CLOSED'::table_status_enum,
    closed_at = COALESCE(gt.closed_at, NOW()),
    current_players_count = 0,
    updated_at = NOW()
WHERE gt.status::text NOT IN ('CLOSED', 'TERMINATED', 'CANCELLED', 'EXPIRED')
  AND (
    EXISTS (
      SELECT 1 FROM public.game_sessions gs
      WHERE gs.table_id = gt.id
        AND (
          gs.ended_at IS NOT NULL
          OR gs.status::text IN ('SETTLED', 'FINISHED', 'CANCELLED', 'COMPLETED', 'ABANDONED', 'CLOSED')
        )
    )
    OR (gt.expires_at IS NOT NULL AND gt.expires_at <= NOW())
    OR NOT EXISTS (
      SELECT 1 FROM public.game_table_players gtp
      WHERE gtp.table_id = gt.id
        AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING')
    )
  );

-- Liberar asientos de cualquier jugador en mesas cerradas/terminadas/canceladas/expiradas
UPDATE public.game_table_players gtp
SET status = 'LEFT'::player_table_status_enum,
    left_at = COALESCE(gtp.left_at, NOW()),
    updated_at = NOW()
FROM public.game_tables gt
WHERE gtp.table_id = gt.id
  AND gt.status::text IN ('CLOSED', 'TERMINATED', 'CANCELLED', 'EXPIRED')
  AND gtp.status != 'LEFT'::player_table_status_enum;

-- Sincronizar contador real de jugadores en mesas que permanezcan abiertas
UPDATE public.game_tables gt
SET current_players_count = (
  SELECT COUNT(DISTINCT gtp.user_id)
  FROM public.game_table_players gtp
  WHERE gtp.table_id = gt.id
    AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING')
),
updated_at = NOW()
WHERE gt.status::text IN ('OPEN', 'FULL', 'WAITING');



