-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 91: 089_fix_wallet_balance_column_in_settle_and_abandon.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 089
-- CORRECCIÓN DEFINITIVA DE COLUMNA WALLETS (AVAILABLE_BALANCE) EN SETTLEMENT Y ABANDON
-- ==============================================================================
-- Causa Raíz Identificada (Error: column "balance" does not exist):
-- La tabla `public.wallets` contiene `available_balance`, `held_balance` y `total_balance`.
-- Las RPCs settle_game_session y abandon_game_table_secure referenciaron `balance`
-- provocando fallos al abandonar mesas o liquidar partidas.
--
-- Esta migración:
-- 1. Añade columna de compatibilidad `balance NUMERIC(14,2)` a `public.wallets` y sincroniza con trigger.
-- 2. Actualiza `settle_game_session` con `available_balance` y `ledger_entries` canónico.
-- 3. Actualiza `abandon_game_table_secure` con `available_balance` y `ledger_entries` canónico.
-- ==============================================================================

-- 1. ADICIÓN SEGURA DE COLUMNA DE COMPATIBILIDAD BALANCE EN WALLETS
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' 
      AND table_name = 'wallets' 
      AND column_name = 'balance'
  ) THEN
    ALTER TABLE public.wallets ADD COLUMN balance NUMERIC(14,2) DEFAULT 0.00;
    UPDATE public.wallets SET balance = available_balance;
  END IF;
END $$;

-- Trigger bidireccional para mantener balance sincronizado con available_balance
CREATE OR REPLACE FUNCTION public.fn_wallets_sync_balance_column()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF NEW.available_balance IS NOT NULL AND (NEW.balance IS NULL OR NEW.balance != NEW.available_balance) THEN
    NEW.balance := NEW.available_balance;
  ELSIF NEW.balance IS NOT NULL AND NEW.available_balance IS NULL THEN
    NEW.available_balance := NEW.balance;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_wallets_sync_balance_column ON public.wallets;
CREATE TRIGGER trg_wallets_sync_balance_column
BEFORE INSERT OR UPDATE ON public.wallets
FOR EACH ROW
EXECUTE FUNCTION public.fn_wallets_sync_balance_column();

-- 2. ACTUALIZACIÓN CANÓNICA DE SETTLE_GAME_SESSION
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_player_count INT;
  v_gross_pool NUMERIC(14,2);
  v_prize_pool NUMERIC(14,2);
  v_platform_fee NUMERIC(14,2);
  v_settlement_id UUID;
  v_player RECORD;
  v_winner_id UUID;
  v_winner_wallet RECORD;
  v_winner_count INT;
  v_individual_prize NUMERIC(14,2);
  v_distributed_sum NUMERIC(14,2) := 0.00;
  v_winner_ledger_id UUID;
  v_settlement_type settlement_type_enum;
  v_existing_settlement RECORD;
  v_is_participant BOOLEAN := FALSE;
  v_effective_idempotency TEXT;
BEGIN
  -- 1. Identificación del invocador y control de autorización
  v_caller_id := auth.uid();
  
  -- Bloqueo pesimista de fila para evitar condiciones de carrera (TOCTOU)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión de juego % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa de juego no encontrada';
  END IF;

  IF v_caller_id IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = v_table.id AND user_id = v_caller_id
    ) INTO v_is_participant;

    IF NOT v_is_participant AND NOT public.has_role(v_caller_id, 'OPERATOR') AND NOT public.has_role(v_caller_id, 'ADMIN') AND NOT public.has_role(v_caller_id, 'SUPER_ADMIN') THEN
      RAISE EXCEPTION 'UNAUTHORIZED: No tienes permisos para liquidar esta partida';
    END IF;
  END IF;

  -- 2. Manejo de Idempotencia estricta
  v_effective_idempotency := COALESCE(p_idempotency_key, 'settle_' || p_session_id::TEXT);

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE idempotency_key = v_effective_idempotency
     OR session_id = p_session_id;

  IF FOUND THEN
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = COALESCE(closed_at, NOW()),
        current_players_count = 0,
        updated_at = NOW()
    WHERE id = v_table.id;

    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = COALESCE(left_at, NOW()),
        updated_at = NOW()
    WHERE table_id = v_table.id
      AND status != 'LEFT'::player_table_status_enum;

    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'settlement_id', v_existing_settlement.id,
      'gross_pool', v_existing_settlement.gross_pool,
      'prize_pool', v_existing_settlement.prize_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'message', 'Partida ya liquidada previamente de forma segura'
    );
  END IF;

  -- 3. Cálculo de Pozos Financieros (Regla 90% Ganador / 10% Plataforma)
  SELECT COUNT(*) INTO v_player_count
  FROM public.game_table_players
  WHERE table_id = v_table.id;

  IF v_player_count < 1 THEN
    v_player_count := 2;
  END IF;

  v_gross_pool := ROUND((v_table.entry_fee * v_player_count)::NUMERIC, 2);
  v_prize_pool := ROUND((v_gross_pool * 0.90)::NUMERIC, 2);
  v_platform_fee := ROUND((v_gross_pool - v_prize_pool)::NUMERIC, 2);

  v_winner_count := COALESCE(array_length(p_winner_user_ids, 1), 0);

  -- 4. Determinar tipo de liquidación
  IF v_winner_count = 0 THEN
    v_settlement_type := 'DRAW_REFUND'::settlement_type_enum;
  ELSIF v_winner_count = 1 THEN
    v_settlement_type := 'STANDARD_PAYOUT'::settlement_type_enum;
  ELSE
    v_settlement_type := 'SPLIT_PAYOUT'::settlement_type_enum;
  END IF;

  -- 5. Crear Registro Maestro en public.game_settlements
  INSERT INTO public.game_settlements (
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_at,
    settled_by
  ) VALUES (
    p_session_id,
    v_table.id,
    v_settlement_type,
    v_gross_pool,
    v_prize_pool,
    v_platform_fee,
    CASE WHEN v_winner_count > 0 THEN v_prize_pool ELSE v_gross_pool END,
    v_effective_idempotency,
    NOW(),
    COALESCE(v_caller_id::text, 'SERVER_ENGINE')
  ) RETURNING id INTO v_settlement_id;

  -- 6. Distribución y Acreditación de Ganadores
  IF v_winner_count > 0 THEN
    v_individual_prize := TRUNC((v_prize_pool / v_winner_count)::NUMERIC, 2);

    FOREACH v_winner_id IN ARRAY p_winner_user_ids
    LOOP
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_winner_id AND currency = 'VES'
      FOR UPDATE;

      IF NOT FOUND THEN
        INSERT INTO public.wallets (user_id, currency, available_balance, held_balance, balance, created_at, updated_at)
        VALUES (v_winner_id, 'VES', 0.00, 0.00, 0.00, NOW(), NOW())
        RETURNING * INTO v_winner_wallet;
      END IF;

      UPDATE public.wallets
      SET available_balance = available_balance + v_individual_prize,
          balance = available_balance + v_individual_prize,
          updated_at = NOW()
      WHERE id = v_winner_wallet.id;

      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_before,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        metadata,
        created_at
      ) VALUES (
        v_winner_wallet.id,
        v_winner_id,
        v_individual_prize,
        'VES',
        'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        v_settlement_id,
        'game_settlements',
        'game_settlement',
        COALESCE(v_winner_wallet.available_balance, 0.00),
        COALESCE(v_winner_wallet.available_balance, 0.00) + v_individual_prize,
        COALESCE(v_winner_wallet.available_balance, 0.00) + v_individual_prize,
        COALESCE(v_winner_wallet.held_balance, 0.00),
        v_effective_idempotency || '_payout_' || v_winner_id::text,
        'Premio de victoria en ' || v_table.game_type,
        jsonb_build_object(
          'session_id', p_session_id,
          'table_id', v_table.id,
          'game_type', v_table.game_type,
          'idempotency_key', v_effective_idempotency,
          'description', 'Premio de victoria en ' || v_table.game_type
        ),
        NOW()
      ) RETURNING id INTO v_winner_ledger_id;

      INSERT INTO public.game_settlement_recipients (
        settlement_id,
        user_id,
        payout_amount,
        ledger_entry_id,
        created_at
      ) VALUES (
        v_settlement_id,
        v_winner_id,
        v_individual_prize,
        v_winner_ledger_id,
        NOW()
      );

      v_distributed_sum := v_distributed_sum + v_individual_prize;
    END LOOP;
  ELSE
    -- Reembolso íntegro en caso de empate técnico o sin ganadores
    FOR v_player IN (
      SELECT DISTINCT user_id FROM public.game_table_players WHERE table_id = v_table.id
    ) LOOP
      SELECT * INTO v_winner_wallet
      FROM public.wallets
      WHERE user_id = v_player.user_id AND currency = 'VES'
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_table.entry_fee,
            balance = available_balance + v_table.entry_fee,
            updated_at = NOW()
        WHERE id = v_winner_wallet.id;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          amount,
          currency,
          entry_type,
          direction,
          reference_id,
          reference_table,
          reference_type,
          balance_before,
          balance_after,
          balance_after_available,
          balance_after_held,
          idempotency_key,
          description,
          metadata,
          created_at
        ) VALUES (
          v_winner_wallet.id,
          v_player.user_id,
          v_table.entry_fee,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_settlement_id,
          'game_settlements',
          'game_settlement',
          COALESCE(v_winner_wallet.available_balance, 0.00),
          COALESCE(v_winner_wallet.available_balance, 0.00) + v_table.entry_fee,
          COALESCE(v_winner_wallet.available_balance, 0.00) + v_table.entry_fee,
          COALESCE(v_winner_wallet.held_balance, 0.00),
          v_effective_idempotency || '_refund_' || v_player.user_id::text,
          'Reembolso por empate técnico o anulación segura',
          jsonb_build_object(
            'session_id', p_session_id,
            'table_id', v_table.id,
            'reason', 'Empate técnico o anulación segura'
          ),
          NOW()
        );
      END IF;
    END LOOP;
  END IF;

  -- 7. Actualizar Estados de Sesión y Mesa
  UPDATE public.game_sessions
  SET status = 'SETTLED'::session_status_enum,
      winner_user_id = p_winner_user_ids[1],
      winner_team = p_winner_team,
      ended_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      closed_at = NOW(),
      current_players_count = 0,
      updated_at = NOW()
  WHERE id = v_table.id;

  -- 8. Liberar asientos de los jugadores
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = COALESCE(left_at, NOW()),
      updated_at = NOW()
  WHERE table_id = v_table.id
    AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'already_settled', false,
    'settlement_id', v_settlement_id,
    'gross_pool', v_gross_pool,
    'prize_pool', v_prize_pool,
    'platform_fee', v_platform_fee,
    'winner_count', v_winner_count
  );
END;
$$;

-- 3. ACTUALIZACIÓN CANÓNICA DE ABANDON_GAME_TABLE_SECURE
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_active_players_count INT;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_effective_idempotency TEXT;
  v_settle_result JSONB;
  v_remaining_player RECORD;
  v_next_player RECORD;
  v_session_is_active BOOLEAN := FALSE;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para abandonar o salir de la mesa.';
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abandon_' || p_table_id::text || '_' || v_caller_id::text || '_' || extract(epoch from now())::text
  );

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada.';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE id = p_session_id AND table_id = p_table_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS')
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  v_session_is_active := (v_session.id IS NOT NULL AND v_session.status::text IN ('ACTIVE', 'IN_PROGRESS'));

  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND user_id = v_caller_id
    AND status IN ('PLAYING', 'JOINED', 'READY')
  FOR UPDATE;

  IF NOT FOUND THEN
    SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

    RETURN jsonb_build_object(
      'success', true,
      'already_left', true,
      'table_id', p_table_id,
      'remaining_players', v_active_players_count
    );
  END IF;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE id = v_player.id;

  IF NOT v_session_is_active THEN
    IF v_table.entry_fee > 0 THEN
      SELECT * INTO v_wallet
      FROM public.wallets
      WHERE user_id = v_caller_id AND currency = 'VES'
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_table.entry_fee,
            balance = available_balance + v_table.entry_fee,
            updated_at = NOW()
        WHERE id = v_wallet.id;

        INSERT INTO public.ledger_entries (
          wallet_id,
          user_id,
          amount,
          currency,
          entry_type,
          direction,
          reference_id,
          reference_table,
          reference_type,
          balance_before,
          balance_after,
          balance_after_available,
          balance_after_held,
          idempotency_key,
          description,
          metadata,
          created_at
        ) VALUES (
          v_wallet.id,
          v_caller_id,
          v_table.entry_fee,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          p_table_id,
          'game_tables',
          'game_tables',
          COALESCE(v_wallet.available_balance, 0.00),
          COALESCE(v_wallet.available_balance, 0.00) + v_table.entry_fee,
          COALESCE(v_wallet.available_balance, 0.00) + v_table.entry_fee,
          COALESCE(v_wallet.held_balance, 0.00),
          v_effective_idempotency || '_refund',
          'Reembolso por abandono voluntario de mesa previa al inicio',
          jsonb_build_object('reason', 'Reembolso por abandono voluntario de mesa previa al inicio'),
          NOW()
        );
        v_refund_amount := v_table.entry_fee;
      END IF;
    END IF;
  END IF;

  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY');

  IF v_session_is_active THEN
    IF v_active_players_count = 1 THEN
      SELECT user_id INTO v_remaining_player
      FROM public.game_table_players
      WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY')
      LIMIT 1;

      IF v_remaining_player.user_id IS NOT NULL THEN
        v_settle_result := public.settle_game_session(
          v_session.id,
          ARRAY[v_remaining_player.user_id],
          NULL,
          'forfeit_' || v_session.id::text || '_' || v_remaining_player.user_id::text
        );
      END IF;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;

      RETURN jsonb_build_object(
        'success', true,
        'table_id', p_table_id,
        'session_id', v_session.id,
        'action', 'FORFEIT_SETTLED',
        'winner_user_id', v_remaining_player.user_id,
        'settlement', v_settle_result
      );
    ELSIF v_active_players_count = 0 THEN
      UPDATE public.game_sessions
      SET status = 'ABANDONED'::session_status_enum,
          ended_at = NOW()
      WHERE id = v_session.id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;

      RETURN jsonb_build_object(
        'success', true,
        'table_id', p_table_id,
        'session_id', v_session.id,
        'action', 'TABLE_ABANDONED_ALL'
      );
    ELSE
      IF v_session.current_turn_user_id = v_caller_id THEN
        SELECT user_id INTO v_next_player
        FROM public.game_table_players
        WHERE table_id = p_table_id AND status IN ('PLAYING', 'JOINED', 'READY')
        ORDER BY seat_number ASC
        LIMIT 1;

        UPDATE public.game_sessions
        SET current_turn_user_id = v_next_player.user_id,
            turn_deadline_at = NOW() + INTERVAL '10 seconds'
        WHERE id = v_session.id;
      END IF;

      UPDATE public.game_tables
      SET current_players_count = v_active_players_count,
          updated_at = NOW()
      WHERE id = p_table_id;

      RETURN jsonb_build_object(
        'success', true,
        'table_id', p_table_id,
        'session_id', v_session.id,
        'action', 'PLAYER_LEFT_MULTIPLAYER',
        'remaining_players', v_active_players_count
      );
    END IF;
  ELSE
    IF v_active_players_count = 0 THEN
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;
    ELSE
      UPDATE public.game_tables
      SET current_players_count = v_active_players_count,
          updated_at = NOW()
      WHERE id = p_table_id;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'table_id', p_table_id,
      'refund_amount', v_refund_amount,
      'remaining_players', v_active_players_count
    );
  END IF;
END;
$$;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 92: 090_server_authoritative_session_start.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 090: BLINDAJE SERVER-AUTHORITATIVE DE INICIO DE SESIÓN Y TURNOS
-- Proyecto: RASPANDO LA OLLA
-- ==============================================================================
-- 1. Redefine start_game_session_secure para soportar creación atómica con
--    estado inicial canónico completo (p_initial_state) y duración de turno.
-- 2. Elimina la ventana de vulnerabilidad donde una sesión quedaba en ACTIVE
--    con current_state incompleto.
-- 3. Crea repair_game_session_initial_state_secure para rehidrataciones
--    idempotentes y seguras protegidas con bloqueo FOR UPDATE.
-- ==============================================================================

-- 1. Limpieza de firmas obsoletas/sobrecargadas
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INT);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB, UUID, INT);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB, UUID);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB);

CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID,
  p_initial_state JSONB DEFAULT NULL,
  p_turn_duration_seconds INT DEFAULT 30
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_unique_players_count INT;
  v_players JSONB := '[]'::jsonb;
  v_player_order JSONB := '[]'::jsonb;
  v_player_record RECORD;
  v_session_id UUID;
  v_first_turn_user_id UUID;
  v_white_player_id UUID;
  v_black_player_id UUID;
  v_initial_state JSONB;
  v_deadline TIMESTAMPTZ;
  v_turn_seconds INT := 30;
  v_game_type_str TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para iniciar la partida';
  END IF;

  -- 1. Bloqueo transaccional de la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- 2. Verificación estricta de anfitrión
  IF v_table.host_user_id <> v_user_id THEN
    RAISE EXCEPTION 'ONLY_HOST_CAN_START: Únicamente el Anfitrión de la mesa puede iniciar la partida';
  END IF;

  -- 3. Si ya existe una sesión activa o en curso, retornarla idempotentemente
  SELECT id, current_turn_user_id, turn_deadline_at INTO v_session_id, v_first_turn_user_id, v_deadline
  FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'session_id', v_session_id,
      'table_id', p_table_id,
      'current_turn_user_id', v_first_turn_user_id,
      'turn_deadline_at', v_deadline,
      'already_active', true
    );
  END IF;

  -- 4. Validar cantidad de jugadores DISTINTOS activos en la mesa
  SELECT COUNT(DISTINCT gtp.user_id) INTO v_unique_players_count
  FROM public.game_table_players gtp
  WHERE gtp.table_id = p_table_id
    AND gtp.status != 'LEFT'::player_table_status_enum;

  IF v_unique_players_count < v_table.min_players THEN
    RAISE EXCEPTION 'NOT_ENOUGH_PLAYERS: Se requieren al menos % jugadores diferentes para iniciar la partida (actualmente hay %)', v_table.min_players, v_unique_players_count;
  END IF;

  -- 5. Compilar lista ordenada de jugadores activos
  FOR v_player_record IN (
    SELECT DISTINCT ON (gtp.user_id)
      gtp.user_id, gtp.seat_number, p.display_name, p.first_name, p.last_name, p.avatar_url
    FROM public.game_table_players gtp
    JOIN public.profiles p ON p.user_id = gtp.user_id
    WHERE gtp.table_id = p_table_id
      AND gtp.status != 'LEFT'::player_table_status_enum
    ORDER BY gtp.user_id, gtp.seat_number ASC
  ) LOOP
    IF v_first_turn_user_id IS NULL THEN
      v_first_turn_user_id := v_player_record.user_id;
      v_white_player_id := v_player_record.user_id;
    ELSEIF v_black_player_id IS NULL THEN
      v_black_player_id := v_player_record.user_id;
    END IF;

    v_player_order := v_player_order || to_jsonb(v_player_record.user_id::text);

    v_players := v_players || jsonb_build_object(
      'userId', v_player_record.user_id,
      'seatNumber', v_player_record.seat_number,
      'displayName', COALESCE(NULLIF(trim(v_player_record.display_name), ''), trim(COALESCE(v_player_record.first_name, '') || ' ' || COALESCE(v_player_record.last_name, ''))),
      'avatarUrl', v_player_record.avatar_url
    );
  END LOOP;

  -- 6. Determinar duración de turno
  v_game_type_str := UPPER(v_table.game_type::text);
  IF v_game_type_str = 'CHESS' THEN
    v_turn_seconds := 15;
  ELSEIF p_turn_duration_seconds IS NOT NULL AND p_turn_duration_seconds > 0 THEN
    v_turn_seconds := p_turn_duration_seconds;
  ELSE
    v_turn_seconds := 30;
  END IF;

  v_deadline := NOW() + (v_turn_seconds || ' seconds')::interval;

  -- 7. Determinar estado inicial canónico completo
  IF p_initial_state IS NOT NULL AND jsonb_typeof(p_initial_state) = 'object' AND p_initial_state <> '{}'::jsonb THEN
    -- Respetar el primer turno indicado por el motor si es un jugador válido de la mesa
    IF p_initial_state ? 'turnUserId' AND (p_initial_state->>'turnUserId') IS NOT NULL THEN
      v_first_turn_user_id := (p_initial_state->>'turnUserId')::uuid;
    ELSEIF p_initial_state ? 'currentTurnUserId' AND (p_initial_state->>'currentTurnUserId') IS NOT NULL THEN
      v_first_turn_user_id := (p_initial_state->>'currentTurnUserId')::uuid;
    END IF;

    -- Inyectar turnExpiresAt autoritativo en el estado
    v_initial_state := jsonb_set(
      jsonb_set(
        jsonb_set(p_initial_state, '{currentTurnUserId}', to_jsonb(v_first_turn_user_id::text)),
        '{turnUserId}', to_jsonb(v_first_turn_user_id::text)
      ),
      '{turnExpiresAt}', to_jsonb(to_char(v_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
    );
  ELSE
    -- Generación canónica server-side según tipo de juego
    IF v_game_type_str = 'CHESS' THEN
      v_white_player_id := v_table.host_user_id;
      IF v_black_player_id IS NULL OR v_black_player_id = v_white_player_id THEN
        SELECT gtp.user_id INTO v_black_player_id
        FROM public.game_table_players gtp
        WHERE gtp.table_id = p_table_id
          AND gtp.status != 'LEFT'::player_table_status_enum
          AND gtp.user_id != v_white_player_id
        LIMIT 1;
      END IF;
      v_first_turn_user_id := v_white_player_id;

      v_initial_state := jsonb_build_object(
        'fen', 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
        'playerWhiteUserId', v_white_player_id,
        'playerBlackUserId', v_black_player_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline,
        'moveHistory', '[]'::jsonb,
        'winnerUserId', NULL,
        'isDraw', false,
        'status', 'playing'
      );
    ELSEIF v_game_type_str IN ('TRES_EN_RAYA', 'TIC_TAC_TOE') THEN
      v_initial_state := jsonb_build_object(
        'board', '[null,null,null,null,null,null,null,null,null]'::jsonb,
        'playerSymbols', jsonb_build_object(v_white_player_id::text, 'X', COALESCE(v_black_player_id, v_white_player_id)::text, 'O'),
        'scores', jsonb_build_object(v_white_player_id::text, 0, COALESCE(v_black_player_id, v_white_player_id)::text, 0),
        'round', 1,
        'status', 'playing',
        'turnUserId', v_first_turn_user_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline
      );
    ELSEIF v_game_type_str IN ('PIEDRA_PAPEL_TIJERA', 'ROCK_PAPER_SCISSORS') THEN
      v_initial_state := jsonb_build_object(
        'playerChoices', '{}'::jsonb,
        'phase', 'CHOOSING',
        'round', 1,
        'scores', jsonb_build_object(v_white_player_id::text, 0, COALESCE(v_black_player_id, v_white_player_id)::text, 0),
        'status', 'playing',
        'turnUserId', v_first_turn_user_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline
      );
    ELSE
      v_initial_state := jsonb_build_object(
        'status', 'playing',
        'playerOrder', v_player_order,
        'players', v_players,
        'currentTurnUserId', v_first_turn_user_id,
        'turnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline,
        'round', 1
      );
    END IF;
  END IF;

  v_session_id := gen_random_uuid();

  -- 8. Inserción atómica en game_sessions
  INSERT INTO public.game_sessions (
    id, table_id, game_type, session_number, status, current_state,
    current_turn_user_id, turn_deadline_at, started_at
  ) VALUES (
    v_session_id, p_table_id, v_table.game_type, 1, 'ACTIVE'::session_status_enum,
    v_initial_state, v_first_turn_user_id, v_deadline, NOW()
  );

  -- 9. Actualización atómica en game_tables
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      started_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'table_id', p_table_id,
    'current_turn_user_id', v_first_turn_user_id,
    'turn_deadline_at', v_deadline,
    'already_active', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID, JSONB, INT) TO authenticated, service_role, anon;

-- ==============================================================================
-- 2. RPC Segura e Idempotente para Reparación de Estado Inicial si hiciera falta
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.repair_game_session_initial_state_secure(
  p_session_id UUID,
  p_initial_state JSONB,
  p_turn_user_id UUID,
  p_turn_duration_seconds INT DEFAULT 30
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_action_count INT;
  v_deadline TIMESTAMPTZ;
  v_turn_sec INT := COALESCE(p_turn_duration_seconds, 30);
  v_final_state JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión';
  END IF;

  -- Bloquear sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión no encontrada';
  END IF;

  IF v_session.status::text NOT IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS') THEN
    RETURN jsonb_build_object('success', false, 'repaired', false, 'message', 'Session is terminal');
  END IF;

  -- Verificar si ya hay acciones registradas
  SELECT COUNT(*) INTO v_action_count
  FROM public.game_actions
  WHERE session_id = p_session_id;

  IF v_action_count > 0 THEN
    -- No reparar si la partida ya avanzó con acciones
    RETURN jsonb_build_object('success', true, 'repaired', false, 'message', 'Actions already exist');
  END IF;

  -- Si el estado actual ya tiene contenido sustancial, no sobrescribir
  IF v_session.current_state IS NOT NULL
     AND (v_session.current_state ? 'board' OR v_session.current_state ? 'playerChoices' OR v_session.current_state ? 'hands' OR v_session.current_state ? 'fen' OR v_session.current_state ? 'pieces') THEN
    RETURN jsonb_build_object('success', true, 'repaired', false, 'message', 'State already complete');
  END IF;

  -- Reparación atómica de estado
  v_deadline := NOW() + (v_turn_sec || ' seconds')::interval;
  v_final_state := jsonb_set(
    jsonb_set(
      jsonb_set(p_initial_state, '{currentTurnUserId}', to_jsonb(p_turn_user_id::text)),
      '{turnUserId}', to_jsonb(p_turn_user_id::text)
    ),
    '{turnExpiresAt}', to_jsonb(to_char(v_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  );

  UPDATE public.game_sessions
  SET current_state = v_final_state,
      current_turn_user_id = p_turn_user_id,
      turn_deadline_at = v_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'repaired', true,
    'session_id', p_session_id,
    'current_turn_user_id', p_turn_user_id,
    'turn_deadline_at', v_deadline
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.repair_game_session_initial_state_secure(UUID, JSONB, UUID, INT) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 93: 091_fix_start_game_session_secure_signature_and_schema_cache.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 091: RECONCILIACIÓN CANÓNICA DE RPC START_GAME_SESSION_SECURE Y SCHEMA CACHE
-- Proyecto: RASPANDO LA OLLA
-- ==============================================================================
-- 1. Elimina explícitamente todas las sobrecargas previas de start_game_session_secure
--    para erradicar el error PostgREST PGRST202.
-- 2. Define la firma canónica autoritativa:
--    public.start_game_session_secure(UUID, JSONB, INT)
-- 3. Unifica atómicamente:
--    - Bloqueo transaccional FOR UPDATE sobre game_tables.
--    - Verificación estricta de Anfitrión (host_user_id = auth.uid()).
--    - Mapeo determinista de turnUserId canónico generado por el motor.
--    - turn_deadline_at calculado server-side con started_at = NOW().
--    - Estado inicial canónico completo persistido en current_state.
--    - Transición atómica de game_tables.status = 'ACTIVE'.
-- 4. Notifica recarga inmediata del schema cache a PostgREST.
-- ==============================================================================

-- 1. Limpieza de firmas obsoletas/sobrecargadas
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INT);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB, UUID, INT);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB, UUID);
DROP FUNCTION IF EXISTS public.repair_game_session_initial_state_secure(UUID, JSONB);

-- 2. Creación canónica de start_game_session_secure
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID,
  p_initial_state JSONB DEFAULT NULL,
  p_turn_duration_seconds INT DEFAULT 30
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_unique_players_count INT;
  v_players JSONB := '[]'::jsonb;
  v_player_order JSONB := '[]'::jsonb;
  v_player_record RECORD;
  v_session_id UUID;
  v_first_turn_user_id UUID;
  v_white_player_id UUID;
  v_black_player_id UUID;
  v_initial_state JSONB;
  v_deadline TIMESTAMPTZ;
  v_turn_seconds INT := 30;
  v_game_type_str TEXT;
  v_is_turn_user_valid BOOLEAN := false;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para iniciar la partida';
  END IF;

  -- 1. Bloqueo transaccional de la mesa (SELECT ... FOR UPDATE)
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- 2. Verificación estricta de anfitrión
  IF v_table.host_user_id <> v_user_id THEN
    RAISE EXCEPTION 'ONLY_HOST_CAN_START: Únicamente el Anfitrión de la mesa puede iniciar la partida';
  END IF;

  -- 3. Si ya existe una sesión activa o en curso, retornarla idempotentemente
  SELECT id, current_turn_user_id, turn_deadline_at INTO v_session_id, v_first_turn_user_id, v_deadline
  FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS')
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_session_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'session_id', v_session_id,
      'table_id', p_table_id,
      'current_turn_user_id', v_first_turn_user_id,
      'turn_deadline_at', v_deadline,
      'already_active', true,
      'status', 'ACTIVE'
    );
  END IF;

  -- 4. Validar cantidad de jugadores DISTINTOS activos en la mesa
  SELECT COUNT(DISTINCT gtp.user_id) INTO v_unique_players_count
  FROM public.game_table_players gtp
  WHERE gtp.table_id = p_table_id
    AND gtp.status != 'LEFT'::player_table_status_enum;

  IF v_unique_players_count < v_table.min_players THEN
    RAISE EXCEPTION 'NOT_ENOUGH_PLAYERS: Se requieren al menos % jugadores diferentes para iniciar la partida (actualmente hay %)', v_table.min_players, v_unique_players_count;
  END IF;

  -- 5. Compilar lista ordenada de jugadores activos por número de asiento
  FOR v_player_record IN (
    SELECT gtp.user_id, gtp.seat_number, p.display_name, p.first_name, p.last_name, p.avatar_url
    FROM (
      SELECT DISTINCT ON (user_id) user_id, seat_number, joined_at
      FROM public.game_table_players
      WHERE table_id = p_table_id
        AND status != 'LEFT'::player_table_status_enum
      ORDER BY user_id, seat_number ASC
    ) gtp
    JOIN public.profiles p ON p.user_id = gtp.user_id
    ORDER BY gtp.seat_number ASC, gtp.joined_at ASC
  ) LOOP
    IF v_first_turn_user_id IS NULL THEN
      v_first_turn_user_id := v_player_record.user_id;
      v_white_player_id := v_player_record.user_id;
    ELSEIF v_black_player_id IS NULL THEN
      v_black_player_id := v_player_record.user_id;
    END IF;

    v_player_order := v_player_order || to_jsonb(v_player_record.user_id::text);

    v_players := v_players || jsonb_build_object(
      'userId', v_player_record.user_id,
      'seatNumber', v_player_record.seat_number,
      'displayName', COALESCE(NULLIF(trim(v_player_record.display_name), ''), trim(COALESCE(v_player_record.first_name, '') || ' ' || COALESCE(v_player_record.last_name, ''))),
      'avatarUrl', v_player_record.avatar_url
    );
  END LOOP;

  -- 6. Determinar duración de turno
  v_game_type_str := UPPER(v_table.game_type::text);
  IF v_game_type_str = 'CHESS' THEN
    v_turn_seconds := 15;
  ELSEIF p_turn_duration_seconds IS NOT NULL AND p_turn_duration_seconds > 0 THEN
    v_turn_seconds := p_turn_duration_seconds;
  ELSE
    v_turn_seconds := 30;
  END IF;

  v_deadline := NOW() + (v_turn_seconds || ' seconds')::interval;

  -- 7. Determinar estado inicial canónico completo y turno unificado
  IF p_initial_state IS NOT NULL AND jsonb_typeof(p_initial_state) = 'object' AND p_initial_state <> '{}'::jsonb THEN
    -- Respetar el primer turno indicado por el motor si es un jugador de la mesa
    IF p_initial_state ? 'turnUserId' AND (p_initial_state->>'turnUserId') IS NOT NULL THEN
      BEGIN
        v_first_turn_user_id := (p_initial_state->>'turnUserId')::uuid;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END IF;
    ELSEIF p_initial_state ? 'currentTurnUserId' AND (p_initial_state->>'currentTurnUserId') IS NOT NULL THEN
      BEGIN
        v_first_turn_user_id := (p_initial_state->>'currentTurnUserId')::uuid;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END IF;
    END IF;

    -- Validar que el turno pertenezca a un jugador activo en la mesa
    SELECT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = p_table_id
        AND user_id = v_first_turn_user_id
        AND status != 'LEFT'::player_table_status_enum
    ) INTO v_is_turn_user_valid;

    IF NOT v_is_turn_user_valid THEN
      -- Si no es válido, reasignar al primer jugador sentado
      SELECT user_id INTO v_first_turn_user_id
      FROM public.game_table_players
      WHERE table_id = p_table_id
        AND status != 'LEFT'::player_table_status_enum
      ORDER BY seat_number ASC
      LIMIT 1;
    END IF;

    -- Inyectar turnExpiresAt autoritativo y turnUserId en el estado
    v_initial_state := jsonb_set(
      jsonb_set(
        jsonb_set(p_initial_state, '{currentTurnUserId}', to_jsonb(v_first_turn_user_id::text)),
        '{turnUserId}', to_jsonb(v_first_turn_user_id::text)
      ),
      '{turnExpiresAt}', to_jsonb(to_char(v_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
    );
  ELSE
    -- Generación canónica server-side según tipo de juego
    IF v_game_type_str = 'CHESS' THEN
      v_white_player_id := v_table.host_user_id;
      IF v_black_player_id IS NULL OR v_black_player_id = v_white_player_id THEN
        SELECT gtp.user_id INTO v_black_player_id
        FROM public.game_table_players gtp
        WHERE gtp.table_id = p_table_id
          AND gtp.status != 'LEFT'::player_table_status_enum
          AND gtp.user_id != v_white_player_id
        LIMIT 1;
      END IF;
      v_first_turn_user_id := v_white_player_id;

      v_initial_state := jsonb_build_object(
        'fen', 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',
        'playerWhiteUserId', v_white_player_id,
        'playerBlackUserId', v_black_player_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline,
        'moveHistory', '[]'::jsonb,
        'winnerUserId', NULL,
        'isDraw', false,
        'status', 'playing'
      );
    ELSEIF v_game_type_str IN ('TRES_EN_RAYA', 'TIC_TAC_TOE') THEN
      v_initial_state := jsonb_build_object(
        'board', '[null,null,null,null,null,null,null,null,null]'::jsonb,
        'playerSymbols', jsonb_build_object(v_white_player_id::text, 'X', COALESCE(v_black_player_id, v_white_player_id)::text, 'O'),
        'scores', jsonb_build_object(v_white_player_id::text, 0, COALESCE(v_black_player_id, v_white_player_id)::text, 0),
        'round', 1,
        'status', 'playing',
        'turnUserId', v_first_turn_user_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline
      );
    ELSEIF v_game_type_str IN ('PIEDRA_PAPEL_TIJERA', 'ROCK_PAPER_SCISSORS') THEN
      v_initial_state := jsonb_build_object(
        'playerChoices', '{}'::jsonb,
        'phase', 'CHOOSING',
        'round', 1,
        'scores', jsonb_build_object(v_white_player_id::text, 0, COALESCE(v_black_player_id, v_white_player_id)::text, 0),
        'status', 'playing',
        'turnUserId', v_first_turn_user_id,
        'currentTurnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline
      );
    ELSE
      v_initial_state := jsonb_build_object(
        'status', 'playing',
        'playerOrder', v_player_order,
        'players', v_players,
        'currentTurnUserId', v_first_turn_user_id,
        'turnUserId', v_first_turn_user_id,
        'turnExpiresAt', v_deadline,
        'round', 1
      );
    END IF;
  END IF;

  v_session_id := gen_random_uuid();

  -- 8. Inserción atómica en game_sessions
  INSERT INTO public.game_sessions (
    id, table_id, game_type, session_number, status, current_state,
    current_turn_user_id, turn_deadline_at, started_at
  ) VALUES (
    v_session_id, p_table_id, v_table.game_type, 1, 'ACTIVE'::session_status_enum,
    v_initial_state, v_first_turn_user_id, v_deadline, NOW()
  );

  -- 9. Actualización atómica en game_tables
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      started_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', v_session_id,
    'table_id', p_table_id,
    'current_turn_user_id', v_first_turn_user_id,
    'turn_deadline_at', v_deadline,
    'already_active', false,
    'status', 'ACTIVE'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID, JSONB, INT) TO authenticated, service_role, anon;

-- ==============================================================================
-- 3. RPC Segura e Idempotente para Reparación de Estado Inicial
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.repair_game_session_initial_state_secure(
  p_session_id UUID,
  p_initial_state JSONB,
  p_turn_user_id UUID,
  p_turn_duration_seconds INT DEFAULT 30
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_action_count INT;
  v_deadline TIMESTAMPTZ;
  v_turn_sec INT := COALESCE(p_turn_duration_seconds, 30);
  v_final_state JSONB;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión';
  END IF;

  -- Bloquear sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión no encontrada';
  END IF;

  IF v_session.status::text NOT IN ('WAITING', 'READY', 'STARTING', 'ACTIVE', 'IN_PROGRESS') THEN
    RETURN jsonb_build_object('success', false, 'repaired', false, 'message', 'Session is terminal');
  END IF;

  -- Verificar si ya hay acciones registradas (REGLA: sólo reparar si 0 acciones)
  SELECT COUNT(*) INTO v_action_count
  FROM public.game_actions
  WHERE session_id = p_session_id;

  IF v_action_count > 0 THEN
    -- No reparar si la partida ya avanzó con acciones
    RETURN jsonb_build_object('success', true, 'repaired', false, 'message', 'Actions already exist');
  END IF;

  -- Si el estado actual ya tiene contenido sustancial completo, no sobrescribir
  IF v_session.current_state IS NOT NULL
     AND (v_session.current_state ? 'board' OR v_session.current_state ? 'playerChoices' OR v_session.current_state ? 'hands' OR v_session.current_state ? 'fen' OR v_session.current_state ? 'pieces') THEN
    RETURN jsonb_build_object('success', true, 'repaired', false, 'message', 'State already complete');
  END IF;

  -- Reparación atómica de estado
  v_deadline := NOW() + (v_turn_sec || ' seconds')::interval;
  v_final_state := jsonb_set(
    jsonb_set(
      jsonb_set(p_initial_state, '{currentTurnUserId}', to_jsonb(p_turn_user_id::text)),
      '{turnUserId}', to_jsonb(p_turn_user_id::text)
    ),
    '{turnExpiresAt}', to_jsonb(to_char(v_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
  );

  UPDATE public.game_sessions
  SET current_state = v_final_state,
      current_turn_user_id = p_turn_user_id,
      turn_deadline_at = v_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'repaired', true,
    'session_id', p_session_id,
    'current_turn_user_id', p_turn_user_id,
    'turn_deadline_at', v_deadline
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.repair_game_session_initial_state_secure(UUID, JSONB, UUID, INT) TO authenticated, service_role, anon;

-- 4. Notificación para recarga inmediata de cache de esquemas en PostgREST
NOTIFY pgrst, 'reload schema';



