-- MIGRACIÓN 103: 101_add_name_column_to_game_tables_and_fix_create_secure.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 101: Corrección de Columna "name" en game_tables y create_game_table_secure
-- Soluciona el error 42703 (column "name" of relation "game_tables" does not exist)
-- Asegura compatibilidad dual: columna "name" dedicada + "config->>'name'"
-- ==============================================================================

-- 1. Agregar columna name a public.game_tables si no existe y ajustar constraint de rango de jugadores
ALTER TABLE public.game_tables 
ADD COLUMN IF NOT EXISTS name VARCHAR(100);

-- Flexibilizar la restricción para admitir min_players >= 1 y max_players >= min_players
ALTER TABLE public.game_tables DROP CONSTRAINT IF EXISTS chk_game_tables_players_range;
ALTER TABLE public.game_tables ADD CONSTRAINT chk_game_tables_players_range CHECK (max_players >= min_players AND min_players >= 1);

-- 2. Migrar retroactivamente los nombres guardados en config hacia la columna name
UPDATE public.game_tables
SET name = config->>'name'
WHERE name IS NULL AND config ? 'name';

-- 3. Redefinición blindada de create_game_table_secure
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
  v_effective_config JSONB;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- AUTO-LIMPIEZA SELF-HEALING: Limpia estados huérfanos previos del usuario antes de comprobar mesas activas
  PERFORM public.cleanup_stale_user_game_participation(v_user_id);

  -- Bloqueo pesimista FOR UPDATE en billetera
  IF p_entry_fee > 0 THEN
    SELECT id, available_balance, held_balance 
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, available_balance, held_balance, currency)
      VALUES (v_user_id, 0.00, 0.00, 'VES')
      ON CONFLICT (user_id) DO NOTHING;

      SELECT id, available_balance, held_balance 
      INTO v_wallet_id, v_wallet_available, v_wallet_held
      FROM public.wallets
      WHERE user_id = v_user_id FOR UPDATE;
    END IF;
  END IF;

  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE user_id = v_user_id;

  IF v_profile_status IS NULL THEN
    PERFORM public.ensure_current_user_profile();
    SELECT account_status INTO v_profile_status
    FROM public.profiles
    WHERE user_id = v_user_id;
  END IF;

  IF v_profile_status::text NOT IN ('ACTIVE', 'PENDING_VERIFICATION') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta no está autorizada para crear mesas';
  END IF;

  v_enum_game_type := public.fn_normalize_game_type_enum(p_game_type);

  -- 2. AUTO-ABANDONO SEGURO DE PARTICIPACIONES OBSOLETAS O HUÉRFANAS
  FOR v_stale_rec IN
    SELECT DISTINCT gt.id as table_id, gs.id as session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        (gt.status::text IN ('OPEN', 'FULL') AND gs.id IS NULL)
        OR (gs.id IS NOT NULL AND gs.status::text IN ('WAITING', 'READY', 'STARTING', 'PAUSED'))
        OR (gs.id IS NOT NULL AND (
             gs.status::text IN ('FINISHED', 'SETTLED', 'COMPLETED', 'CANCELLED', 'REFUNDED', 'ABANDONED')
             OR (gs.current_state->>'winnerUserId') IS NOT NULL AND (gs.current_state->>'winnerUserId') <> ''
           ))
        OR (gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE') AND (
             gt.created_at < NOW() - INTERVAL '1 hour'
             OR (gt.updated_at IS NOT NULL AND gt.updated_at < NOW() - INTERVAL '1 hour')
           ))
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              ended_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_101_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    AND (gt.updated_at IS NULL OR gt.updated_at >= NOW() - INTERVAL '1 hour')
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego. Sal de esa mesa o espera a que finalice antes de crear otra.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites
  IF p_entry_fee < 25.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF NOT public.is_valid_entry_fee(p_entry_fee, v_enum_game_type) THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 25 Bs. y 5.000 Bs.';
  END IF;

  IF p_entry_fee > 0 AND COALESCE(v_wallet_available, 0.00) < p_entry_fee THEN
    RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Saldo disponible insuficiente (%.2f Bs.) para cubrir la entrada de %.2f Bs.', COALESCE(v_wallet_available, 0.00), p_entry_fee;
  END IF;

  -- 5. Configuración de Jugadores
  IF p_max_players < 2 OR p_max_players > 100 THEN
    RAISE EXCEPTION 'INVALID_MAX_PLAYERS: El número de jugadores permitidos es entre 2 y 100';
  END IF;

  IF v_enum_game_type = 'BINGO'::game_type_enum THEN
    v_min_players := CASE WHEN p_max_players = 1 THEN 1 ELSE 2 END;
  ELSIF p_max_players >= 4 THEN
    v_min_players := 2;
  ELSE
    v_min_players := p_max_players;
  END IF;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || v_enum_game_type::text);
  v_table_id := gen_random_uuid();
  v_expires_at := NOW() + INTERVAL '1 hour';
  v_effective_config := COALESCE(p_config, '{}'::jsonb) || jsonb_build_object('name', v_table_name);

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    v_code_candidate := upper(substring(replace(gen_random_uuid()::text, '-', '') from 1 for 6));
    IF NOT EXISTS (
      SELECT 1 FROM public.game_tables 
      WHERE invite_code = v_code_candidate 
        AND status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    ) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;
    IF v_code_attempts > 20 THEN
      v_invite_code := upper(substring(replace(gen_random_uuid()::text, '-', '') from 1 for 10));
      EXIT;
    END IF;
  END LOOP;

  -- 7. Inserción Atómica de la Mesa de Juego (Con columna "name" y "config->'name'")
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, name, visibility,
    status, entry_fee, min_players, max_players,
    current_players_count, invite_code, config,
    created_at, updated_at, expires_at
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, v_table_name, p_visibility,
    'OPEN'::table_status_enum, p_entry_fee, v_min_players, p_max_players,
    1, v_invite_code, v_effective_config,
    NOW(), NOW(), v_expires_at
  );

  -- 8. Deducción Segura de Fondos en Billetera y Registro Canónico en Ledger
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_after,
      balance_after_available,
      balance_after_held,
      reference_table,
      reference_type,
      reference_id,
      idempotency_key,
      description,
      status,
      currency,
      actor_id
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'HOLD'::ledger_direction_enum,
      p_entry_fee,
      (COALESCE(v_wallet_available, 0.00) - p_entry_fee),
      (COALESCE(v_wallet_available, 0.00) - p_entry_fee),
      (COALESCE(v_wallet_held, 0.00) + p_entry_fee),
      'game_tables',
      'game_tables',
      v_table_id,
      'HOLD_' || v_table_id::text || '_' || v_user_id::text,
      'Retención de entrada al crear la mesa ' || v_table_name,
      'COMPLETED',
      'VES',
      v_user_id
    );
  END IF;

  -- 9. Inserción del Creador como Jugador (Asiento 1 garantizado con referencia a ledger)
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, entry_held_entry_id, joined_at, updated_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'JOINED'::player_table_status_enum, v_ledger_id, NOW(), NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'game_type', v_enum_game_type,
    'entry_fee', p_entry_fee,
    'player_id', v_player_id,
    'seat_number', 1,
    'max_players', p_max_players,
    'min_players', v_min_players
  );
END;
$$;

-- Permisos de ejecución
GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB)
TO authenticated, service_role;

-- Notificar recarga de schema cache
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 104: 102_bingo_server_authoritative_draw.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 102: Bingo 100% Server-Authoritative Draw Engine
-- ==============================================================================
-- Asegura que la extracción de balotas se realice de forma autoritativa en el servidor
-- sin depender del cliente web, emitiendo eventos a game_actions para Realtime.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.server_bingo_operation(
  p_session_id UUID,
  p_operation TEXT DEFAULT 'draw_ball',
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_session RECORD;
  v_table RECORD;
  v_state JSONB;
  v_drawn_balls JSONB;
  v_available_balls INTEGER[];
  v_new_ball INTEGER;
  v_new_state JSONB;
  v_max_ball INTEGER;
  v_variant TEXT;
  v_caller_id UUID;
BEGIN
  -- 1. Obtener sesión activa de Bingo
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id 
    AND status::text IN ('ACTIVE', 'PLAYING', 'DRAWING', 'in_progress', 'WAITING');

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND_OR_INACTIVE');
  END IF;

  -- 2. Obtener información de la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;

  -- 3. Verificar que la mesa sea de Bingo
  IF UPPER(v_table.game_type::text) != 'BINGO' THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_BINGO_TABLE');
  END IF;

  -- 4. Obtener estado actual
  v_state := COALESCE(v_session.current_state, '{}'::jsonb);

  -- Si la sesión ya tiene un ganador o está terminada, detener sorteo
  IF (v_state->>'winnerUserId') IS NOT NULL OR (v_state->>'status') = 'finished' THEN
    RETURN jsonb_build_object('success', false, 'error', 'GAME_ALREADY_FINISHED');
  END IF;

  v_drawn_balls := COALESCE(v_state->'drawnBalls', '[]'::jsonb);
  v_variant := COALESCE(v_state->>'variant', '75');
  
  -- 5. Determinar máximo de bolas según variante
  v_max_ball := CASE 
    WHEN v_variant = '75' THEN 75
    WHEN v_variant = '80' THEN 80
    WHEN v_variant = '90' THEN 90
    ELSE 75
  END;

  -- 6. Generar array de bolas disponibles
  SELECT array_agg(n) INTO v_available_balls
  FROM generate_series(1, v_max_ball) AS n
  WHERE NOT (v_drawn_balls @> to_jsonb(n));

  IF v_available_balls IS NULL OR array_length(v_available_balls, 1) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALL_BALLS_DRAWN', 'totalDrawn', jsonb_array_length(v_drawn_balls));
  END IF;

  -- 7. Seleccionar bola aleatoria criptográficamente segura o pseudoaleatoria
  v_new_ball := v_available_balls[floor(random() * array_length(v_available_balls, 1) + 1)::int];

  -- 8. Construir nuevo estado
  v_new_state := jsonb_set(
    v_state,
    '{drawnBalls}',
    v_drawn_balls || to_jsonb(v_new_ball)
  );

  v_new_state := jsonb_set(
    v_new_state,
    '{currentBall}',
    to_jsonb(v_new_ball)
  );

  v_new_state := jsonb_set(
    v_new_state,
    '{status}',
    '"PLAYING"'::jsonb
  );

  v_new_state := jsonb_set(
    v_new_state,
    '{lastActionLog}',
    to_jsonb('🎱 Balota cantada por el Servidor: ' || v_new_ball::text)
  );

  -- 9. Actualizar sesión en base de datos
  UPDATE public.game_sessions
  SET 
    current_state = v_new_state,
    status = 'ACTIVE',
    updated_at = NOW()
  WHERE id = p_session_id;

  -- 10. Registrar acción en auditoría y emisión Realtime
  v_caller_id := COALESCE(p_user_id, '00000000-0000-0000-0000-000000000000'::uuid);

  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    action_data,
    is_valid,
    created_at
  ) VALUES (
    p_session_id,
    v_caller_id,
    'DRAW_BALL',
    jsonb_build_object(
      'ball', v_new_ball,
      'ball_number', v_new_ball,
      'variant', v_variant,
      'totalDrawn', jsonb_array_length(v_new_state->'drawnBalls'),
      'serverAuthoritative', true
    ),
    true,
    NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'ball', v_new_ball,
    'ball_number', v_new_ball,
    'variant', v_variant,
    'totalDrawn', jsonb_array_length(v_new_state->'drawnBalls')
  );
END;
$$;

-- Permisos de ejecución
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(UUID, TEXT, UUID) TO service_role;
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(UUID, TEXT, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(UUID, TEXT, UUID) TO anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 105: 102_expire_game_turn_secure_with_cron.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 102: Sistema Robusto de Expiración de Turnos, Sincronización y Cron
-- Proyecto: RASPANDO LA OLLA 🇻🇪 (PulsoPLAY)
-- ==============================================================================

-- ------------------------------------------------------------------------------
-- 1. Función Auxiliar: Ejecutar movimiento de Bot / Pase de turno en Timeout
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.execute_bot_move_on_timeout(
  p_session_id UUID,
  p_user_id UUID,
  p_action_type TEXT DEFAULT 'PASS_TURN'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_new_state JSONB;
  v_next_turn_user_id UUID;
  v_turn_duration INT := 30;
  v_game_type TEXT;
BEGIN
  -- Obtener sesión bloqueada para actualización
  SELECT id, table_id, game_type, current_state, current_turn_user_id, status
  INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  v_game_type := UPPER(v_session.game_type::text);
  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);

  -- Determinar siguiente jugador activo en la mesa
  SELECT user_id INTO v_next_turn_user_id
  FROM public.game_table_players
  WHERE table_id = v_session.table_id
    AND user_id <> p_user_id
    AND status::text <> 'LEFT'
  ORDER BY seat_number ASC
  LIMIT 1;

  -- Si no hay otro jugador, cerrar o finalizar la sesión
  IF v_next_turn_user_id IS NULL THEN
    UPDATE public.game_sessions
    SET status = 'FINISHED'::session_status_enum,
        current_state = jsonb_set(v_current_state, '{status}', '"finished"'),
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true, 'action', 'GAME_ENDED_NO_OPPONENT');
  END IF;

  -- Actualizar el estado con el siguiente turno
  v_new_state := jsonb_set(
    v_current_state,
    '{currentTurnUserId}',
    to_jsonb(v_next_turn_user_id::text)
  );

  v_new_state := jsonb_set(
    v_new_state,
    '{turnUserId}',
    to_jsonb(v_next_turn_user_id::text)
  );

  v_new_state := jsonb_set(
    v_new_state,
    '{turnExpiresAt}',
    to_jsonb((NOW() + (v_turn_duration || ' seconds')::interval)::text)
  );

  UPDATE public.game_sessions
  SET 
    current_state = v_new_state,
    current_turn_user_id = v_next_turn_user_id,
    turn_deadline_at = NOW() + (v_turn_duration || ' seconds')::interval,
    updated_at = NOW()
  WHERE id = p_session_id;

  -- Registrar acción de BOT_MOVE en game_actions
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    action_data,
    created_at
  ) VALUES (
    p_session_id,
    p_user_id,
    'BOT_MOVE',
    jsonb_build_object(
      'action_type', p_action_type,
      'next_turn_user_id', v_next_turn_user_id,
      'executed_at', NOW()
    ),
    NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action_type,
    'next_turn_user_id', v_next_turn_user_id
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- ------------------------------------------------------------------------------
-- 2. Función Principal para Sesión Específica (p_session_id UUID)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_turn_user_id UUID;
  v_player_order JSONB := '[]'::jsonb;
  v_lives JSONB;
  v_curr_lives INT;
  v_player_count INT := 0;
  v_curr_idx INT := -1;
  v_next_idx INT;
  v_next_user_id UUID;
  v_winner_id UUID := NULL;
  v_turn_deadline TIMESTAMPTZ;
  v_i INT;
  v_settle_res JSONB;
BEGIN
  -- Bloquear la sesión para evitar concurrencia
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_LOCKED_OR_NOT_FOUND');
  END IF;

  -- Comprobar estado activo
  IF v_session.status::text NOT IN ('ACTIVE', 'READY', 'STARTING', 'in_progress') THEN
    RETURN jsonb_build_object('success', false, 'reason', 'SESSION_NOT_ACTIVE');
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'NO_TURN_USER_DEFINED');
  END IF;

  -- Extraer lista ordenada de jugadores
  IF v_state ? 'playerOrder' AND jsonb_array_length(v_state->'playerOrder') > 0 THEN
    v_player_order := v_state->'playerOrder';
  ELSIF v_state ? 'players' AND jsonb_array_length(v_state->'players') > 0 THEN
    FOR v_i IN 0..(jsonb_array_length(v_state->'players') - 1) LOOP
      v_player_order := v_player_order || to_jsonb((v_state->'players'->v_i->>'userId'));
    END LOOP;
  ELSE
    -- Buscar desde game_table_players
    FOR v_next_user_id IN (
      SELECT user_id FROM public.game_table_players
      WHERE table_id = v_session.table_id AND status::text <> 'LEFT'
      ORDER BY seat_number ASC
    ) LOOP
      v_player_order := v_player_order || to_jsonb(v_next_user_id::text);
    END LOOP;
  END IF;

  v_player_count := jsonb_array_length(v_player_order);

  -- Si es dominó o truco, o juego por turnos con vidas
  IF v_state ? 'lives' THEN
    v_lives := v_state->'lives';
  ELSE
    v_lives := '{}'::jsonb;
    IF v_player_count > 0 THEN
      FOR v_i IN 0..(v_player_count - 1) LOOP
        v_lives := jsonb_set(v_lives, ARRAY[(v_player_order->>v_i)], '3'::jsonb);
      END LOOP;
    END IF;
  END IF;

  v_curr_lives := COALESCE((v_lives->>v_turn_user_id::text)::INT, 3) - 1;
  IF v_curr_lives < 0 THEN
    v_curr_lives := 0;
  END IF;

  v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::text], to_jsonb(v_curr_lives));
  v_state := jsonb_set(v_state, '{lives}', v_lives);

  -- Registrar acción TURN_EXPIRED / TIMEOUT_LIFE_LOST
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    action_data,
    created_at
  ) VALUES (
    p_session_id,
    v_turn_user_id,
    'TURN_EXPIRED',
    jsonb_build_object(
      'userId', v_turn_user_id,
      'remainingLives', v_curr_lives,
      'expiredAt', NOW()
    ),
    NOW()
  );

  -- Si se agotaron las vidas
  IF v_curr_lives <= 0 AND v_player_count > 1 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID <> v_turn_user_id THEN
        v_winner_id := (v_player_order->>v_i)::UUID;
        EXIT;
      END IF;
    END LOOP;

    v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
    v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_winner_id::text));
    v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_LIVES_EXHAUSTED"'::jsonb);

    -- Liquidar partida si settle_game_session existe
    BEGIN
      PERFORM public.settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL,
        'timeout_settle_' || p_session_id::text || '_' || extract(epoch from now())::text
      );
    EXCEPTION WHEN OTHERS THEN
      -- Settle fallback
    END;

    UPDATE public.game_sessions
    SET current_state = v_state,
        status = 'SETTLED'::session_status_enum,
        winner_user_id = v_winner_id,
        ended_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Cerrar la mesa asociada
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        updated_at = NOW()
    WHERE id = v_session.table_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ENDED_BY_TIMEOUT',
      'timed_out_user_id', v_turn_user_id,
      'remaining_lives', 0,
      'winner_user_id', v_winner_id,
      'is_game_over', true
    );
  END IF;

  -- Si aún tiene vidas, rotar el turno al siguiente jugador
  IF v_player_count > 1 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
        v_curr_idx := v_i;
        EXIT;
      END IF;
    END LOOP;

    IF v_curr_idx = -1 THEN
      v_curr_idx := 0;
    END IF;

    v_next_idx := (v_curr_idx + 1) % v_player_count;
    v_next_user_id := (v_player_order->>v_next_idx)::UUID;
  ELSE
    v_next_user_id := v_turn_user_id;
  END IF;

  v_turn_deadline := NOW() + INTERVAL '30 seconds';

  v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_next_user_id::text));
  v_state := jsonb_set(v_state, '{currentTurnUserId}', to_jsonb(v_next_user_id::text));
  v_state := jsonb_set(v_state, '{turnExpiresAt}', to_jsonb(v_turn_deadline::text));

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_user_id,
      turn_deadline_at = v_turn_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TURN_ROTATED',
    'timed_out_user_id', v_turn_user_id,
    'next_turn_user_id', v_next_user_id,
    'remaining_lives', v_curr_lives,
    'is_game_over', false
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- ------------------------------------------------------------------------------
-- 3. Función Sobrecargada por Lotes (0 argumentos) para Cron / Worker / Daemon
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_row RECORD;
  v_count INT := 0;
  v_res JSONB;
BEGIN
  -- Buscar sesiones activas por turnos donde el deadline haya expirado
  FOR v_row IN (
    SELECT gs.id
    FROM public.game_sessions gs
    JOIN public.game_tables gt ON gt.id = gs.table_id
    WHERE gs.status::text IN ('ACTIVE', 'READY', 'STARTING')
      AND gt.game_type::text NOT IN ('BINGO', 'POLLA') -- Bingo y Polla tienen su propio motor autónomo
      AND gs.current_turn_user_id IS NOT NULL
      AND gs.turn_deadline_at IS NOT NULL
      AND gs.turn_deadline_at < NOW()
    ORDER BY gs.turn_deadline_at ASC
    LIMIT 20
  ) LOOP
    BEGIN
      v_res := public.expire_game_turn_secure(v_row.id);
      IF (v_res->>'success')::boolean IS TRUE THEN
        v_count := v_count + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error expirando sesión %: %', v_row.id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'expired_count', v_count,
    'processed_at', NOW()
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error', SQLERRM,
    'processed_at', NOW()
  );
END;
$$;

-- ------------------------------------------------------------------------------
-- 4. Detección de Jugadores Desconectados (heartbeat > 45s de inactividad)
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.detect_disconnected_players()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_player RECORD;
  v_count INT := 0;
BEGIN
  FOR v_player IN (
    SELECT 
      gtp.user_id,
      gtp.table_id,
      gt.game_type,
      gs.id AS session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id AND gs.status::text IN ('ACTIVE', 'READY', 'STARTING')
    LEFT JOIN public.user_activity_sessions uas ON uas.user_id = gtp.user_id AND uas.status::text = 'ACTIVE'
    WHERE gtp.status::text IN ('JOINED', 'READY', 'PLAYING')
      AND gt.status::text IN ('ACTIVE', 'STARTING')
      AND (
        uas.last_seen_at IS NULL 
        OR uas.last_seen_at < NOW() - INTERVAL '45 seconds'
      )
    LIMIT 20
  ) LOOP
    -- Marcar jugador como DISCONNECTED en game_table_players
    UPDATE public.game_table_players
    SET status = 'DISCONNECTED'::player_table_status_enum
    WHERE table_id = v_player.table_id
      AND user_id = v_player.user_id
      AND status::text <> 'DISCONNECTED';

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'disconnected_count', v_count,
    'checked_at', NOW()
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- ------------------------------------------------------------------------------
-- 5. Bucle de Expiración para Cron
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.cron_expire_turns_loop()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_start_time TIMESTAMPTZ := NOW();
  v_i INT := 0;
BEGIN
  -- Ejecutar cada 5 segundos durante 1 minuto
  WHILE v_i < 12 LOOP
    PERFORM public.expire_game_turn_secure();
    PERFORM public.detect_disconnected_players();
    v_i := v_i + 1;

    PERFORM pg_sleep(5);

    IF EXTRACT(EPOCH FROM (NOW() - v_start_time)) >= 58 THEN
      EXIT;
    END IF;
  END LOOP;
END;
$$;

-- ------------------------------------------------------------------------------
-- 6. Programación del Cron Job en Supabase (si pg_cron está activo)
-- ------------------------------------------------------------------------------
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    -- Desagendar job previo si existe
    BEGIN
      PERFORM cron.unschedule('expire-game-turns-job');
    EXCEPTION WHEN OTHERS THEN
      -- Silencioso
    END;

    -- Agendar loop de expiración cada minuto (corre internamente cada 5s)
    BEGIN
      PERFORM cron.schedule(
        'expire-game-turns-job',
        '* * * * *',
        'SELECT public.cron_expire_turns_loop();'
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'No se pudo programar expire-game-turns-job en pg_cron: %', SQLERRM;
    END;
  END IF;
END $$;

-- ------------------------------------------------------------------------------
-- 7. Permisos de Ejecución
-- ------------------------------------------------------------------------------
GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(UUID) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure() TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.execute_bot_move_on_timeout(UUID, UUID, TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.detect_disconnected_players() TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.cron_expire_turns_loop() TO service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 106: 103_fix_server_bingo_operation_overload.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 103: RESOLVER SOBRECARGA AMBIGUA EN SERVER_BINGO_OPERATION
-- ==============================================================================
-- Elimina la función sobrecargada redundante (uuid, text, uuid) para permitir
-- que PostgREST resuelva inequívocamente las llamadas RPC con parámetros nombrados
-- (p_operation, p_session_id, p_user_id) sin conflicto PGRST203.
-- ==============================================================================

DROP FUNCTION IF EXISTS public.server_bingo_operation(uuid, text, uuid);

-- Asegurar permisos EXECUTE para authenticated y anon en la variante canónica
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(text, uuid, uuid) TO anon, authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 107: 103_server_bingo_operation_with_rate_limit.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 103: server_bingo_operation con Rate Limiting y RNG Seguro
-- ==============================================================================
-- 1. Bloquea la fila (FOR UPDATE) para prevenir condiciones de carrera.
-- 2. Valida que hayan transcurrido 4 segundos desde la última bola (Rate Limiting).
-- 3. Genera una bola aleatoria autoritativa (RNG) que no haya salido antes.
-- 4. Actualiza el estado en game_sessions y registra DRAW_BALL en game_actions
--    para propagación inmediata a todos los clientes vía Supabase Realtime.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.server_bingo_operation(
  p_operation TEXT,
  p_session_id UUID,
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_new_ball INT;
  v_total_balls INT;
  v_last_drawn_at TIMESTAMPTZ;
  v_seconds_since_last NUMERIC;
  v_available_balls INT[];
BEGIN
  -- 1. Validar operación
  IF p_operation != 'draw_ball' THEN
    RAISE EXCEPTION 'INVALID_OPERATION: Operación no soportada. Use ''draw_ball''';
  END IF;

  -- 2. Obtener y bloquear la sesión (Previene Race Conditions)
  SELECT id, current_state, status
  INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión no encontrada';
  END IF;

  IF UPPER(v_session.status::text) NOT IN ('ACTIVE', 'IN_PROGRESS', 'PLAYING', 'WAITING', 'DRAWING') THEN
    RAISE EXCEPTION 'SESSION_NOT_ACTIVE: La sesión de bingo no está activa';
  END IF;

  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);

  -- Si el juego ya tiene ganador o está finalizado, detener
  IF (v_current_state->>'winnerUserId') IS NOT NULL OR (v_current_state->>'status') = 'finished' THEN
    RAISE EXCEPTION 'GAME_ALREADY_FINISHED: La partida ya ha concluido';
  END IF;
  
  -- Extraer bolas ya cantadas (manejo seguro de JSONB a Array)
  v_drawn_balls := COALESCE(
    ARRAY(SELECT jsonb_array_elements_text(v_current_state->'drawnBalls')::INT), 
    '{}'::INT[]
  );
  
  -- Determinar total de bolas (75, 80 o 90, defecto 75)
  v_total_balls := COALESCE(
    (v_current_state->>'totalBalls')::INT, 
    CASE 
      WHEN (v_current_state->>'variant') = '90' THEN 90
      WHEN (v_current_state->>'variant') = '80' THEN 80
      ELSE 75
    END
  );
  
  v_last_drawn_at := (v_current_state->>'lastDrawnAt')::TIMESTAMPTZ;

  -- 3. VALIDACIÓN DE TIEMPO (Rate Limiting Server-Authoritative de 4 segundos)
  IF v_last_drawn_at IS NOT NULL THEN
    v_seconds_since_last := EXTRACT(EPOCH FROM (NOW() - v_last_drawn_at));
    
    IF v_seconds_since_last < 4.0 THEN
      RAISE EXCEPTION 'TOO_FAST: Debes esperar 4 segundos entre cada bola. Tiempo restante: % s', ROUND(4.0 - v_seconds_since_last, 1);
    END IF;
  END IF;

  -- 4. Verificar si el juego ya terminó (todas las bolas cantadas)
  IF array_length(v_drawn_balls, 1) >= v_total_balls THEN
    RAISE EXCEPTION 'BINGO_COMPLETE: Ya se han cantado todas las bolas';
  END IF;

  -- 5. Generar bola aleatoria segura (RNG)
  -- Crea un array de bolas disponibles (1 a total_balls) excluyendo las ya sorteadas
  SELECT array_agg(n)
  INTO v_available_balls
  FROM generate_series(1, v_total_balls) AS n
  WHERE NOT (n = ANY(v_drawn_balls));

  IF v_available_balls IS NULL OR array_length(v_available_balls, 1) = 0 THEN
    RAISE EXCEPTION 'BINGO_COMPLETE: Ya se han cantado todas las bolas';
  END IF;

  -- Selecciona una aleatoria de las disponibles
  SELECT n INTO v_new_ball
  FROM unnest(v_available_balls) AS n
  ORDER BY random()
  LIMIT 1;

  -- 6. Actualizar el estado de la sesión en la base de datos
  v_current_state := jsonb_set(
    v_current_state,
    '{currentBall}',
    to_jsonb(v_new_ball)
  );
  
  v_current_state := jsonb_set(
    v_current_state,
    '{drawnBalls}',
    COALESCE(v_current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_new_ball)
  );

  v_current_state := jsonb_set(
    v_current_state,
    '{lastDrawnAt}',
    to_jsonb(NOW())
  );

  v_current_state := jsonb_set(
    v_current_state,
    '{status}',
    '"PLAYING"'::jsonb
  );

  UPDATE public.game_sessions
  SET current_state = v_current_state,
      status = 'ACTIVE',
      updated_at = NOW()
  WHERE id = p_session_id;

  -- 7. Registrar en game_actions para auditoría y para disparar el Realtime del frontend
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    action_data,
    created_at
  ) VALUES (
    p_session_id,
    COALESCE(p_user_id, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid),
    'DRAW_BALL',
    jsonb_build_object(
      'ball_number', v_new_ball,
      'ball', v_new_ball,
      'drawn_at', NOW()
    ),
    NOW()
  );

  RETURN jsonb_build_object(
    'success', true,
    'ball_number', v_new_ball,
    'ball', v_new_ball,
    'drawn_at', NOW(),
    'remaining_balls', v_total_balls - COALESCE(array_length(v_drawn_balls, 1), 0) - 1
  );

EXCEPTION WHEN OTHERS THEN
  -- Re-lanzar la excepción para que el frontend la reciba (ej. TOO_FAST)
  RAISE;
END;
$$;

-- Compatibilidad dual de parámetros (orden alternativo)
CREATE OR REPLACE FUNCTION public.server_bingo_operation(
  p_session_id UUID,
  p_operation TEXT DEFAULT 'draw_ball',
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.server_bingo_operation(p_operation, p_session_id, p_user_id);
END;
$$;

-- Permisos de ejecución
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(TEXT, UUID, UUID) TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(UUID, TEXT, UUID) TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 108: 109_centralized_bingo_draw.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 109: CENTRALIZED SERVER-AUTHORITATIVE BINGO DRAW
-- ==============================================================================
-- 1. Pre-genera la secuencia completa de bolas al iniciar el sorteo.
-- 2. Bloquea ventas y establece status en 'DRAWING'.
-- 3. Revela las bolas una por una de manera autoritativa.
-- ==============================================================================

-- 0. Asegurar valor 'DRAWING' en session_status_enum si no existe
ALTER TYPE public.session_status_enum ADD VALUE IF NOT EXISTS 'DRAWING';

-- 1. Agregar columnas necesarias a game_sessions si no existen
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'game_sessions' AND column_name = 'draw_sequence') THEN
    ALTER TABLE public.game_sessions ADD COLUMN draw_sequence INT[];
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'game_sessions' AND column_name = 'current_ball_index') THEN
    ALTER TABLE public.game_sessions ADD COLUMN current_ball_index INT DEFAULT 0;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'game_sessions' AND column_name = 'last_revealed_ball') THEN
    ALTER TABLE public.game_sessions ADD COLUMN last_revealed_ball INT;
  END IF;
END $$;

-- 2. RPC: Preparar el sorteo (Genera la secuencia, bloquea ventas y firma)
CREATE OR REPLACE FUNCTION public.prepare_bingo_draw(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_total_balls INT;
  v_sequence INT[];
  v_hash TEXT;
BEGIN
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SESSION_NOT_FOUND'; END IF;

  v_total_balls := COALESCE((v_session.current_state->>'totalBalls')::INT, 90);

  -- Generar secuencia aleatoria de 1 a total_balls
  SELECT array_agg(n ORDER BY random()) INTO v_sequence
  FROM generate_series(1, v_total_balls) AS n;

  v_hash := md5(v_sequence::text || p_session_id::text || NOW()::text);

  UPDATE public.game_sessions
  SET 
    draw_sequence = v_sequence,
    current_ball_index = 0,
    last_revealed_ball = NULL,
    current_state = jsonb_set(current_state, '{status}', '"DRAWING"'),
    status = 'DRAWING'::session_status_enum,
    updated_at = NOW()
  WHERE id = p_session_id;

  -- Bloquear mesa en 'ACTIVE' para cerrar compras de cartones
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;

  RETURN jsonb_build_object('success', true, 'total_balls', v_total_balls, 'hash', v_hash);
END;
$$;

-- 3. RPC: Revelar la siguiente bola y verificar ganador (Llamada por Cron)
CREATE OR REPLACE FUNCTION public.reveal_next_bingo_ball(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_next_index INT;
  v_revealed_ball INT;
  v_has_winner BOOLEAN := false;
  v_winner_user_id UUID;
BEGIN
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND OR v_session.status != 'DRAWING' THEN 
    RETURN jsonb_build_object('success', false, 'reason', 'NOT_DRAWING'); 
  END IF;

  -- Bloquear inmediatamente la mesa en 'ACTIVE' para cerrar compras
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;

  v_next_index := v_session.current_ball_index + 1;
  
  IF v_next_index > array_length(v_session.draw_sequence, 1) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'DRAW_COMPLETE');
  END IF;

  v_revealed_ball := v_session.draw_sequence[v_next_index];

  -- Actualizar sesión
  UPDATE public.game_sessions
  SET 
    current_ball_index = v_next_index,
    last_revealed_ball = v_revealed_ball,
    current_state = jsonb_set(
      jsonb_set(current_state, '{currentBall}', to_jsonb(v_revealed_ball)),
      '{drawnBalls}', COALESCE(current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_revealed_ball)
    ),
    updated_at = NOW()
  WHERE id = p_session_id;

  -- TODO (Simplificado): Aquí iría la lógica para recorrer `bingo_card_purchases` 
  -- y verificar si algún cartón tiene línea o bingo completo con las bolas en `current_state->'drawnBalls'`.
  -- Si hay ganador, actualizar v_has_winner = true y v_winner_user_id = ... y llamar a settle_game_session.

  RETURN jsonb_build_object(
    'success', true,
    'ball_number', v_revealed_ball,
    'index', v_next_index,
    'has_winner', v_has_winner,
    'winner_user_id', v_winner_user_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.prepare_bingo_draw(UUID) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.reveal_next_bingo_ball(UUID) TO anon, authenticated, service_role;
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 109: 110_add_game_variant_column_to_game_tables.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 110: COLUMNA GAME_VARIANT EN GAME_TABLES Y GAME_SESSIONS
-- ==============================================================================
-- 1. Añade columna game_variant con valor por defecto '90' en game_tables y game_sessions.
-- 2. Retro-migra variantes existentes guardadas en config/current_state.
-- 3. Actualiza create_game_table_secure para guardar explícitamente game_variant.
-- ==============================================================================

-- 1. Agregar la columna si no existe
ALTER TABLE public.game_tables ADD COLUMN IF NOT EXISTS game_variant TEXT DEFAULT '90';
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS game_variant TEXT DEFAULT '90';

-- 2. Retrocompatibilidad: Población de variantes desde JSONB
UPDATE public.game_tables
SET game_variant = COALESCE(config->>'gameVariant', config->>'variant', '90')
WHERE config ? 'gameVariant' OR config ? 'variant';

UPDATE public.game_sessions
SET game_variant = COALESCE(current_state->>'variant', current_state->>'gameVariant', '90')
WHERE current_state ? 'variant' OR current_state ? 'gameVariant';

-- 3. Índice para consultas rápidas por variante de juego
CREATE INDEX IF NOT EXISTS idx_game_tables_variant ON public.game_tables(game_type, game_variant);
CREATE INDEX IF NOT EXISTS idx_game_sessions_variant ON public.game_sessions(game_variant);

-- 4. Actualización de create_game_table_secure para persistir game_variant
CREATE OR REPLACE FUNCTION public.create_game_table_secure(
  p_game_type TEXT,
  p_name VARCHAR DEFAULT NULL,
  p_visibility table_visibility_enum DEFAULT 'PUBLIC',
  p_entry_fee NUMERIC DEFAULT 25.00,
  p_max_players SMALLINT DEFAULT 2,
  p_config JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_profile_status account_status_enum;
  v_enum_game_type game_type_enum;
  v_table_id UUID;
  v_invite_code VARCHAR(32);
  v_table_name VARCHAR(100);
  v_min_players SMALLINT;
  v_expires_at TIMESTAMPTZ;
  v_code_attempts INT := 0;
  v_code_candidate VARCHAR(32);
  v_active_table_count INT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID;
  v_player_id UUID;
  v_stale_rec RECORD;
  v_stale_session_status TEXT;
  v_effective_config JSONB;
  v_game_variant TEXT;
BEGIN
  -- 1. Identificación y Validación del Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para crear una mesa';
  END IF;

  -- AUTO-LIMPIEZA SELF-HEALING: Limpia estados huérfanos previos del usuario antes de comprobar mesas activas
  PERFORM public.cleanup_stale_user_game_participation(v_user_id);

  -- Bloqueo pesimista FOR UPDATE en billetera
  IF p_entry_fee > 0 THEN
    SELECT id, available_balance, held_balance 
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id FOR UPDATE;

    IF v_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, available_balance, held_balance, currency)
      VALUES (v_user_id, 0.00, 0.00, 'VES')
      ON CONFLICT (user_id) DO NOTHING;

      SELECT id, available_balance, held_balance 
      INTO v_wallet_id, v_wallet_available, v_wallet_held
      FROM public.wallets
      WHERE user_id = v_user_id FOR UPDATE;
    END IF;

    IF v_wallet_available < p_entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Tu saldo disponible (% Bs.) es insuficiente para cubrir la entrada (% Bs.)',
        COALESCE(v_wallet_available, 0.00), p_entry_fee;
    END IF;
  END IF;

  -- Verificar estado de la cuenta
  SELECT account_status INTO v_profile_status
  FROM public.profiles
  WHERE id = v_user_id;

  IF v_profile_status IS NOT NULL AND v_profile_status IN ('SUSPENDED', 'BANNED') THEN
    RAISE EXCEPTION 'ACCOUNT_BLOCKED: Tu cuenta se encuentra temporalmente restringida';
  END IF;

  -- Convertir tipo de juego a enum de forma segura
  BEGIN
    v_enum_game_type := p_game_type::game_type_enum;
  EXCEPTION WHEN OTHERS THEN
    CASE upper(p_game_type)
      WHEN 'DOMINO_VENEZOLANO' THEN v_enum_game_type := 'DOMINO'::game_type_enum;
      WHEN 'DOMINO' THEN v_enum_game_type := 'DOMINO'::game_type_enum;
      WHEN 'TRUCO_VENEZOLANO' THEN v_enum_game_type := 'TRUCO'::game_type_enum;
      WHEN 'TRUCO' THEN v_enum_game_type := 'TRUCO'::game_type_enum;
      WHEN 'LUDO' THEN v_enum_game_type := 'LUDO'::game_type_enum;
      WHEN 'BINGO' THEN v_enum_game_type := 'BINGO'::game_type_enum;
      WHEN 'POLLA' THEN v_enum_game_type := 'POLLA'::game_type_enum;
      WHEN 'POLLA_ENCUESTADORA' THEN v_enum_game_type := 'POLLA'::game_type_enum;
      WHEN 'ATRAPAITO' THEN v_enum_game_type := 'ATRAPAITO'::game_type_enum;
      WHEN 'UNA_OLLA' THEN v_enum_game_type := 'UNA_OLLA'::game_type_enum;
      ELSE RAISE EXCEPTION 'INVALID_GAME_TYPE: Tipo de juego no reconocido: %', p_game_type;
    END CASE;
  END;

  -- Extraer la variante de juego (e.g. '75' | '90')
  v_game_variant := COALESCE(p_config->>'gameVariant', p_config->>'variant', '90');

  -- 2. Limpieza de mesas huérfanas
  FOR v_stale_rec IN
    SELECT gtp.table_id, gs.id AS session_id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
    WHERE gtp.user_id = v_user_id
      AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
      AND gt.game_type = v_enum_game_type
      AND (
        gt.status IN ('CLOSED', 'CANCELLED')
        OR (gs.id IS NOT NULL AND gs.status::text IN ('FINISHED', 'CANCELLED', 'ABANDONED'))
        OR (gt.updated_at IS NOT NULL AND gt.updated_at < NOW() - INTERVAL '4 hours')
        OR (gt.expires_at IS NOT NULL AND gt.expires_at < NOW())
      )
  LOOP
    BEGIN
      IF v_stale_rec.session_id IS NOT NULL THEN
        SELECT status::text INTO v_stale_session_status FROM public.game_sessions WHERE id = v_stale_rec.session_id;
        IF v_stale_session_status = 'ACTIVE' THEN
          UPDATE public.game_sessions
          SET status = 'CANCELLED'::session_status_enum,
              ended_at = NOW()
          WHERE id = v_stale_rec.session_id;
        END IF;
      END IF;

      PERFORM public.abandon_game_table_secure(
        v_stale_rec.table_id,
        v_stale_rec.session_id,
        'auto_cleanup_create_110_' || v_stale_rec.table_id::text
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;

  -- 3. CONTROL ESTRICTO DE OTRA MESA ACTIVA REAL
  SELECT COUNT(*) INTO v_active_table_count
  FROM public.game_table_players gtp
  JOIN public.game_tables gt ON gt.id = gtp.table_id
  LEFT JOIN public.game_sessions gs ON gs.table_id = gt.id
  WHERE gtp.user_id = v_user_id
    AND gtp.status IN ('JOINED', 'READY', 'PLAYING')
    AND gt.game_type = v_enum_game_type
    AND gt.status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    AND gs.id IS NOT NULL
    AND gs.status::text = 'ACTIVE'
    AND (gs.current_state->>'winnerUserId' IS NULL OR gs.current_state->>'winnerUserId' = '')
    AND (gt.updated_at IS NULL OR gt.updated_at >= NOW() - INTERVAL '1 hour')
    AND gt.created_at >= NOW() - INTERVAL '1 hour'
    AND (gt.expires_at IS NULL OR gt.expires_at >= NOW());

  IF v_active_table_count > 0 THEN
    RAISE EXCEPTION 'ALREADY_IN_ACTIVE_TABLE: Ya estás participando en una mesa activa de este juego. Sal de esa mesa o espera a que finalice antes de crear otra.';
  END IF;

  -- 4. Validaciones de Tarifas y Límites
  IF p_entry_fee < 10.00 OR p_entry_fee > 5000.00 THEN
    RAISE EXCEPTION 'INVALID_ENTRY_FEE: El monto de participación debe estar entre 10 Bs. y 5.000 Bs.';
  END IF;

  -- 5. Determinación de Límites de Jugadores y Nombre
  v_min_players := 2;
  IF v_enum_game_type = 'BINGO'::game_type_enum THEN
    v_min_players := 2;
  END IF;

  IF p_max_players < v_min_players THEN
    RAISE EXCEPTION 'INVALID_PLAYER_LIMIT: La mesa requiere mínimo % jugadores', v_min_players;
  END IF;

  v_table_name := COALESCE(NULLIF(trim(p_name), ''), 'Mesa de ' || v_enum_game_type::text);
  v_table_id := gen_random_uuid();
  v_expires_at := NOW() + INTERVAL '1 hour';
  v_effective_config := COALESCE(p_config, '{}'::jsonb) || jsonb_build_object(
    'name', v_table_name,
    'gameVariant', v_game_variant,
    'variant', v_game_variant
  );

  -- 6. Generación de Código de Invitación Único
  LOOP
    v_code_attempts := v_code_attempts + 1;
    v_code_candidate := upper(substring(replace(gen_random_uuid()::text, '-', '') from 1 for 6));
    IF NOT EXISTS (
      SELECT 1 FROM public.game_tables 
      WHERE invite_code = v_code_candidate 
        AND status IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE')
    ) THEN
      v_invite_code := v_code_candidate;
      EXIT;
    END IF;
    IF v_code_attempts > 20 THEN
      v_invite_code := upper(substring(replace(gen_random_uuid()::text, '-', '') from 1 for 10));
      EXIT;
    END IF;
  END LOOP;

  -- 7. Inserción Atómica de la Mesa de Juego (Con columna "name", "config" y "game_variant")
  INSERT INTO public.game_tables (
    id, host_user_id, game_type, name, visibility,
    status, entry_fee, min_players, max_players,
    current_players_count, invite_code, config, game_variant,
    created_at, updated_at, expires_at
  ) VALUES (
    v_table_id, v_user_id, v_enum_game_type, v_table_name, p_visibility,
    'OPEN'::table_status_enum, p_entry_fee, v_min_players, p_max_players,
    1, v_invite_code, v_effective_config, v_game_variant,
    NOW(), NOW(), v_expires_at
  );

  -- 8. Deducción Segura de Fondos en Billetera y Registro Canónico en Ledger
  IF p_entry_fee > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance - p_entry_fee,
        held_balance = held_balance + p_entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_ledger_id := gen_random_uuid();
    INSERT INTO public.ledger_entries (
      id,
      wallet_id,
      user_id,
      entry_type,
      direction,
      amount,
      balance_before,
      balance_after,
      currency,
      reference_id,
      reference_table,
      status,
      description,
      metadata,
      created_at
    ) VALUES (
      v_ledger_id,
      v_wallet_id,
      v_user_id,
      'GAME_ENTRY_HOLD',
      'HOLD',
      p_entry_fee,
      v_wallet_available,
      v_wallet_available - p_entry_fee,
      'VES',
      v_table_id,
      'game_tables',
      'HELD',
      'Retención por creación de mesa ' || v_table_name,
      jsonb_build_object(
        'table_id', v_table_id,
        'game_type', v_enum_game_type::text,
        'game_variant', v_game_variant,
        'invite_code', v_invite_code,
        'entry_fee', p_entry_fee
      ),
      NOW()
    );
  END IF;

  -- 9. Asignar al creador como Asiento #1 (Host)
  v_player_id := gen_random_uuid();
  INSERT INTO public.game_table_players (
    id, table_id, user_id, seat_number, status, joined_at
  ) VALUES (
    v_player_id, v_table_id, v_user_id, 1, 'READY', NOW()
  );

  -- 10. Retornar Estado Completo
  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'invite_code', v_invite_code,
    'name', v_table_name,
    'game_type', v_enum_game_type::text,
    'game_variant', v_game_variant,
    'status', 'OPEN',
    'entry_fee', p_entry_fee,
    'seat_number', 1,
    'ledger_id', v_ledger_id
  );
END;
$$;

REVOKE ALL ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_game_table_secure(TEXT, VARCHAR, table_visibility_enum, NUMERIC, SMALLINT, JSONB) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 110: 110_fix_server_bingo_operation_idempotency_key.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 110: AGREGAR IDEMPOTENCY_KEY A SERVER_BINGO_OPERATION
-- ==============================================================================
-- Parchea la función legacy server_bingo_operation agregando la columna obligatoria
-- NOT NULL idempotency_key en el INSERT a public.game_actions.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.server_bingo_operation(
  p_operation TEXT,
  p_session_id UUID,
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_new_ball INT;
  v_total_balls INT;
  v_last_drawn_at TIMESTAMPTZ;
  v_seconds_since_last NUMERIC;
  v_available_balls INT[];
  v_has_updated_at BOOLEAN;
  v_next_sequence INT;
  v_action_payload JSONB;
  v_state_hash TEXT;
BEGIN
  IF p_operation != 'draw_ball' THEN
    RAISE EXCEPTION 'INVALID_OPERATION: Use ''draw_ball''';
  END IF;

  SELECT id, current_state, status INTO v_session
  FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'SESSION_NOT_FOUND'; END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'IN_PROGRESS', 'playing', 'SALES', 'WAITING', 'READY', 'DRAWING') THEN
    RAISE EXCEPTION 'SESSION_NOT_ACTIVE';
  END IF;

  v_current_state := v_session.current_state;
  v_drawn_balls := COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_current_state->'drawnBalls')::INT), '{}'::INT[]);
  v_total_balls := COALESCE((v_current_state->>'totalBalls')::INT, 90);
  v_last_drawn_at := (v_current_state->>'lastDrawnAt')::TIMESTAMPTZ;

  IF v_last_drawn_at IS NOT NULL THEN
    v_seconds_since_last := EXTRACT(EPOCH FROM (NOW() - v_last_drawn_at));
    IF v_seconds_since_last < 4.0 THEN
      RAISE EXCEPTION 'TOO_FAST: Debes esperar 4 segundos.';
    END IF;
  END IF;

  IF array_length(v_drawn_balls, 1) >= v_total_balls THEN
    RAISE EXCEPTION 'BINGO_COMPLETE';
  END IF;

  SELECT array_agg(n) INTO v_available_balls
  FROM generate_series(1, v_total_balls) AS n WHERE NOT (n = ANY(v_drawn_balls));

  SELECT n INTO v_new_ball FROM unnest(v_available_balls) AS n ORDER BY random() LIMIT 1;

  v_current_state := jsonb_set(v_current_state, '{currentBall}', to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{drawnBalls}', COALESCE(v_current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{lastDrawnAt}', to_jsonb(NOW()));

  SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'game_sessions' AND column_name = 'updated_at') INTO v_has_updated_at;

  IF v_has_updated_at THEN
    UPDATE public.game_sessions SET current_state = v_current_state, updated_at = NOW() WHERE id = p_session_id;
  ELSE
    UPDATE public.game_sessions SET current_state = v_current_state WHERE id = p_session_id;
  END IF;

  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_sequence FROM public.game_actions WHERE session_id = p_session_id;

  v_action_payload := jsonb_build_object('ball_number', v_new_ball, 'drawn_at', NOW());
  v_state_hash := md5(v_action_payload::text || p_session_id::text || v_new_ball::text);

  -- Inserción autoritativa con todas las columnas NOT NULL satisfechas
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    payload,
    server_state_hash,
    idempotency_key,
    created_at,
    sequence_number
  ) VALUES (
    p_session_id,
    COALESCE(p_user_id, auth.uid()),
    'DRAW_BALL',
    v_action_payload,
    v_state_hash,
    gen_random_uuid()::text,
    NOW(),
    v_next_sequence
  );

  RETURN jsonb_build_object('success', true, 'ball_number', v_new_ball, 'remaining_balls', v_total_balls - array_length(v_drawn_balls, 1) - 1);

EXCEPTION WHEN OTHERS THEN
  RAISE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.server_bingo_operation(TEXT, UUID, UUID) TO anon, authenticated, service_role;
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 111: 111_bingo_fairness_lock_purchases_when_drawing.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 111: BINGO FAIRNESS LOCK (BLOQUEO DE COMPRAS)
-- ==============================================================================
-- 🔒 PASO 1: Bloquear compras de cartones si el sorteo ya comenzó (DRAWING/FINISHED/COMPLETED)
-- 🔒 PASO 2: Actualizar reveal_next_bingo_ball y prepare_bingo_draw para bloquear la mesa en 'ACTIVE'
-- ==============================================================================

-- 1. SOBRESCRITURA DE buy_bingo_cards_secure CON CANDADO ESTRICTO DE FAIRNESS
CREATE OR REPLACE FUNCTION public.buy_bingo_cards_secure(
  p_game_table_id UUID,
  p_card_count INT,
  p_variant TEXT,
  p_price_per_card NUMERIC(14,2) DEFAULT 10.00,
  p_cards_data JSONB DEFAULT '[]'::jsonb,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_wallet_id UUID;
  v_wallet_available NUMERIC(14,2);
  v_total_cost NUMERIC(14,2);
  v_winner_pool NUMERIC(14,2);
  v_system_fee NUMERIC(14,2);
  v_purchase_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_session_status TEXT;
  v_online_count INT := 0;
  v_countdown_duration INT := 120;
  v_scheduled_start TIMESTAMPTZ;
  v_config JSONB;
  v_new_cards JSONB := '[]'::jsonb;
  v_card_item JSONB;
  v_card_hash TEXT;
  v_c INT;
  v_player_exists BOOLEAN := false;
  v_seat_assigned INT := 1;
  v_existing_purchase RECORD;
  v_table_variant TEXT;
  v_already_owned INT := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  -- 🔐 RATE LIMIT EN COMPRAS: Máximo 10 compras por minuto (60 segundos)
  IF NOT public.check_rate_limit('buy_bingo_cards', v_user_id::text, 10, INTERVAL '60 seconds') THEN
    RETURN jsonb_build_object('success', false, 'error', 'RATE_LIMIT_EXCEEDED: Has realizado demasiadas transacciones en poco tiempo. Espera un momento.');
  END IF;

  -- Validación estricta del formato de variante
  IF p_variant NOT IN ('75', '80', '90') THEN
    RETURN jsonb_build_object('success', false, 'error', 'VARIANTE_BINGO_INVALIDA');
  END IF;

  IF p_card_count < 1 OR p_card_count > 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'CANTIDAD_CARTONES_INVALIDA_MAX_20');
  END IF;

  -- Validar idempotencia de compra antes de cualquier transacción
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_existing_purchase 
    FROM public.bingo_card_purchases 
    WHERE idempotency_key = p_idempotency_key;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true,
        'is_idempotent', true,
        'purchase_id', v_existing_purchase.id,
        'variant', v_existing_purchase.variant,
        'card_count', v_existing_purchase.card_count,
        'cards', v_existing_purchase.cards_data,
        'total_cost', v_existing_purchase.total_cost,
        'winner_pool', v_existing_purchase.winner_pool,
        'system_fee', v_existing_purchase.system_fee
      );
    END IF;
  END IF;

  -- 1. Bloquear Mesa y Verificar Estado
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_game_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'MESA_NO_ENCONTRADA');
  END IF;

  -- 🔒 PASO 1 (CANDADO DE FAIRNESS): Bloquear compras si la mesa o el sorteo ya comenzaron
  IF v_table.status IN ('FINISHED'::table_status_enum, 'CLOSED'::table_status_enum, 'ACTIVE'::table_status_enum) THEN
    RAISE EXCEPTION 'MESA_NO_DISPONIBLE: La partida ya comenzó o finalizó. No se pueden comprar más cartones.';
  END IF;

  -- Verificar el estado de la sesión activa de la mesa
  SELECT status::text INTO v_session_status
  FROM public.game_sessions
  WHERE table_id = p_game_table_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_session_status IS NOT NULL AND v_session_status IN ('DRAWING', 'FINISHED', 'COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'El sorteo ya comenzó. No se pueden comprar más cartones.';
  END IF;

  -- Validación de variante autorizada de la mesa contra el cartón comprado
  v_config := COALESCE(v_table.config, '{}'::jsonb);
  v_table_variant := COALESCE(v_config->>'variant', '75');
  IF p_variant <> v_table_variant THEN
    RETURN jsonb_build_object('success', false, 'error', 'VARIANTE_BINGO_INVALIDA_MESA: El tipo de cartón no coincide con la variante autorizada de la mesa.');
  END IF;

  -- Límite acumulativo de cartones por mesa (máximo 20 por usuario/mesa)
  SELECT COALESCE(SUM(card_count), 0) INTO v_already_owned
  FROM public.bingo_card_purchases
  WHERE game_table_id = p_game_table_id AND user_id = v_user_id;

  IF v_already_owned + p_card_count > 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'EXCEDE_MAXIMO_DE_20_CARTONES_ACUMULADOS: El límite acumulado permitido es de 20 cartones por jugador.');
  END IF;

  -- Verificar si las ventas están cerradas (últimos 10 segundos antes del inicio programado)
  IF (v_config->>'scheduled_start_at') IS NOT NULL THEN
    v_scheduled_start := (v_config->>'scheduled_start_at')::TIMESTAMPTZ;
    IF NOW() >= (v_scheduled_start - INTERVAL '10 seconds') THEN
      RAISE EXCEPTION 'SALES_CLOSED: Ventas cerradas. El sorteo comenzará en menos de 10 segundos.';
    END IF;
  END IF;

  -- 2. Calcular costos exclusivamente usando el precio autoritativo (v_table.entry_fee)
  v_total_cost := ROUND(p_card_count * COALESCE(v_table.entry_fee, 10.00), 2);
  v_winner_pool := ROUND(v_total_cost * 0.90, 2);
  v_system_fee := ROUND(v_total_cost * 0.10, 2);

  -- 3. Bloquear Billetera y Descontar Saldo
  SELECT id, available_balance INTO v_wallet_id, v_wallet_available
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (user_id, available_balance, held_balance)
    VALUES (v_user_id, 0.00, 0.00)
    RETURNING id, available_balance INTO v_wallet_id, v_wallet_available;
  END IF;

  IF v_wallet_available < v_total_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'SALDO_INSUFICIENTE_PARA_COMPRA_DE_CARTONES');
  END IF;

  UPDATE public.wallets
  SET available_balance = available_balance - v_total_cost,
      updated_at = NOW()
  WHERE id = v_wallet_id;

  -- 4. Generar Cartones Únicos para el Usuario
  FOR v_c IN 1..p_card_count LOOP
    v_card_item := public.generate_single_bingo_card_jsonb(p_variant, p_game_table_id, v_c);
    v_new_cards := v_new_cards || jsonb_build_array(v_card_item);
  END LOOP;

  v_card_hash := encode(digest(v_new_cards::text, 'sha256'), 'hex');

  -- 5. Registrar la Compra
  INSERT INTO public.bingo_card_purchases (
    user_id,
    game_table_id,
    variant,
    card_count,
    price_per_card,
    total_cost,
    winner_pool,
    system_fee,
    cards_data,
    unique_card_hash,
    idempotency_key
  ) VALUES (
    v_user_id,
    p_game_table_id,
    p_variant,
    p_card_count,
    COALESCE(v_table.entry_fee, 10.00),
    v_total_cost,
    v_winner_pool,
    v_system_fee,
    v_new_cards,
    v_card_hash,
    p_idempotency_key
  )
  RETURNING id INTO v_purchase_id;

  -- Registrar Ledger de Retención
  INSERT INTO public.wallet_ledgers (
    wallet_id,
    user_id,
    amount,
    entry_type,
    reference_type,
    reference_id,
    idempotency_key,
    description
  ) VALUES (
    v_wallet_id,
    v_user_id,
    -v_total_cost,
    'GAME_ENTRY_HOLD',
    'bingo_card_purchases',
    v_purchase_id::text,
    'bingo_buy_' || v_purchase_id::text,
    'Compra de ' || p_card_count || ' cartón(es) de Bingo ' || p_variant || ' Bolas'
  );

  -- 6. Asentar al Jugador en game_table_players si aún no está presente
  SELECT EXISTS (
    SELECT 1 FROM public.game_table_players
    WHERE table_id = p_game_table_id AND user_id = v_user_id AND status != 'LEFT'::player_table_status_enum
  ) INTO v_player_exists;

  IF NOT v_player_exists THEN
    SELECT COALESCE(MAX(seat_number), 0) + 1 INTO v_seat_assigned
    FROM public.game_table_players
    WHERE table_id = p_game_table_id AND status != 'LEFT'::player_table_status_enum;

    INSERT INTO public.game_table_players (
      table_id,
      user_id,
      seat_number,
      seat_index,
      team_index,
      status
    ) VALUES (
      p_game_table_id,
      v_user_id,
      v_seat_assigned,
      v_seat_assigned - 1,
      0,
      'READY'::player_table_status_enum
    );

    UPDATE public.game_tables
    SET current_players_count = current_players_count + 1,
        updated_at = NOW()
    WHERE id = p_game_table_id;
  END IF;

  -- 7. Lógica del Temporizador Server-Authoritative (Mínimo 2 Jugadores)
  IF (v_table.current_players_count + (CASE WHEN v_player_exists THEN 0 ELSE 1 END)) >= 2 THEN
    IF (v_config->>'scheduled_start_at') IS NULL THEN
      v_countdown_duration := CASE WHEN COALESCE((v_config->>'online_users_count')::INT, 0) > 100 THEN 180 ELSE 120 END;
      v_scheduled_start := NOW() + (v_countdown_duration || ' seconds')::INTERVAL;

      v_config := v_config || jsonb_build_object(
        'countdown_started_at', NOW(),
        'countdown_duration', v_countdown_duration,
        'scheduled_start_at', v_scheduled_start,
        'status', 'COUNTDOWN'
      );

      UPDATE public.game_tables
      SET config = v_config,
          status = 'READY'::table_status_enum,
          updated_at = NOW()
      WHERE id = p_game_table_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'purchase_id', v_purchase_id,
    'variant', p_variant,
    'card_count', p_card_count,
    'cards', v_new_cards,
    'total_cost', v_total_cost,
    'winner_pool', v_winner_pool,
    'system_fee', v_system_fee,
    'scheduled_start_at', v_config->>'scheduled_start_at'
  );
END;
$$;

-- 🔒 PASO 2: Actualizar reveal_next_bingo_ball para bloquear la mesa en 'ACTIVE' al revelar bolas
CREATE OR REPLACE FUNCTION public.reveal_next_bingo_ball(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_next_index INT;
  v_revealed_ball INT;
  v_has_winner BOOLEAN := false;
  v_winner_user_id UUID;
BEGIN
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND OR v_session.status != 'DRAWING' THEN 
    RETURN jsonb_build_object('success', false, 'reason', 'NOT_DRAWING'); 
  END IF;

  -- 🔒 CANDADO DE FAIRNESS: Bloquear inmediatamente la mesa en 'ACTIVE' para cerrar compras y nuevas uniones
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;

  v_next_index := v_session.current_ball_index + 1;
  
  IF v_next_index > array_length(v_session.draw_sequence, 1) THEN
    RETURN jsonb_build_object('success', false, 'reason', 'DRAW_COMPLETE');
  END IF;

  v_revealed_ball := v_session.draw_sequence[v_next_index];

  -- Actualizar sesión
  UPDATE public.game_sessions
  SET 
    current_ball_index = v_next_index,
    last_revealed_ball = v_revealed_ball,
    current_state = jsonb_set(
      jsonb_set(current_state, '{currentBall}', to_jsonb(v_revealed_ball)),
      '{drawnBalls}', COALESCE(current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_revealed_ball)
    ),
    updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'ball_number', v_revealed_ball,
    'index', v_next_index,
    'has_winner', v_has_winner,
    'winner_user_id', v_winner_user_id
  );
END;
$$;

-- También asegurar que al preparar el sorteo (prepare_bingo_draw), la mesa pase de inmediato a 'ACTIVE'
CREATE OR REPLACE FUNCTION public.prepare_bingo_draw(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_total_balls INT;
  v_sequence INT[];
  v_hash TEXT;
BEGIN
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'SESSION_NOT_FOUND'; END IF;

  v_total_balls := COALESCE((v_session.current_state->>'totalBalls')::INT, 90);

  -- Generar secuencia aleatoria de 1 a total_balls
  SELECT array_agg(n ORDER BY random()) INTO v_sequence
  FROM generate_series(1, v_total_balls) AS n;

  v_hash := md5(v_sequence::text || p_session_id::text || NOW()::text);

  UPDATE public.game_sessions
  SET 
    draw_sequence = v_sequence,
    current_ball_index = 0,
    last_revealed_ball = NULL,
    current_state = jsonb_set(current_state, '{status}', '"DRAWING"'),
    status = 'DRAWING'::session_status_enum,
    updated_at = NOW()
  WHERE id = p_session_id;

  -- 🔒 Bloquear la mesa en 'ACTIVE' al preparar el sorteo
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;

  RETURN jsonb_build_object('success', true, 'total_balls', v_total_balls, 'hash', v_hash);
END;
$$;

