-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 112: 112_bingo_strict_countdown_and_draw.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 112: SISTEMA DE CUENTA REGRESIVA CON VALIDACIONES ESTRICTAS
-- ==============================================================================
-- 1. Agrega columna countdown_ends_at a game_sessions
-- 2. check_and_start_bingo_countdown: Solo activa cuenta regresiva si hay >= 2 cartones Y >= 2 jugadores únicos
-- 3. reveal_next_bingo_ball: Solo revela bolas si la cuenta regresiva de 2 minutos terminó
-- ==============================================================================

-- 1. Agregar columna para la cuenta regresiva (si no existe)
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS countdown_ends_at TIMESTAMPTZ;

-- 2. Función corregida: Solo inicia cuenta regresiva si hay >= 2 cartones comprados Y >= 2 jugadores únicos
CREATE OR REPLACE FUNCTION public.check_and_start_bingo_countdown()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_cards_count INT;
  v_unique_players INT;
BEGIN
  -- Buscar sesiones que CUMPLAN TODAS estas condiciones:
  -- 1. Son de tipo Bingo
  -- 2. Están en estado WAITING, READY o SALES (aún no han empezado a extraer bolas)
  -- 3. NO tienen cuenta regresiva activa
  -- 4. Tienen al menos 2 cartones comprados
  -- 5. Tienen al menos 2 jugadores únicos con cartones
  
  FOR v_session IN
    SELECT gs.id, gs.table_id, gs.status, gs.countdown_ends_at
    FROM public.game_sessions gs
    WHERE LOWER(gs.game_type::text) = 'bingo'
      AND gs.status::text IN ('WAITING', 'READY', 'SALES', 'waiting', 'ready', 'sales')
      AND gs.countdown_ends_at IS NULL
      AND gs.status != 'DRAWING'::session_status_enum
  LOOP
    -- Contar cartones comprados en esta sesión
    SELECT COUNT(*) INTO v_cards_count
    FROM public.bingo_card_purchases
    WHERE session_id = v_session.id;
    
    -- Contar jugadores únicos con cartones
    SELECT COUNT(DISTINCT user_id) INTO v_unique_players
    FROM public.bingo_card_purchases
    WHERE session_id = v_session.id;
    
    -- 👇 VALIDACIÓN ESTRICTA: Mínimo 2 cartones Y 2 jugadores únicos
    IF v_cards_count >= 2 AND v_unique_players >= 2 THEN
      -- Activar cuenta regresiva de 2 minutos
      UPDATE public.game_sessions
      SET countdown_ends_at = NOW() + INTERVAL '2 minutes',
          updated_at = NOW()
      WHERE id = v_session.id;
      
      RAISE NOTICE 'Cuenta regresiva iniciada para sesión % (fin en 2 minutos)', v_session.id;
    END IF;
  END LOOP;
END;
$$;

-- 3. Función corregida: Solo revela bolas si la cuenta regresiva terminó
CREATE OR REPLACE FUNCTION public.reveal_next_bingo_ball(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_new_ball INT;
  v_total_balls INT;
  v_last_drawn_at TIMESTAMPTZ;
  v_seconds_since_last NUMERIC;
  v_available_balls INT[];
  v_next_sequence INT;
  v_action_payload JSONB;
  v_state_hash TEXT;
BEGIN
  SELECT id, table_id, current_state, status, countdown_ends_at INTO v_session 
  FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  
  IF NOT FOUND THEN RAISE EXCEPTION 'SESSION_NOT_FOUND'; END IF;
  
  -- 👇 VALIDACIÓN CRÍTICA: Solo revelar bolas si la cuenta regresiva terminó
  IF v_session.status::text != 'DRAWING' THEN
    -- Verificar si es hora de iniciar el sorteo
    IF v_session.countdown_ends_at IS NOT NULL AND v_session.countdown_ends_at <= NOW() THEN
      -- La cuenta regresiva terminó, iniciar el sorteo
      UPDATE public.game_sessions
      SET status = 'DRAWING'::session_status_enum,
          current_state = jsonb_set(COALESCE(current_state, '{}'::jsonb), '{status}', '"DRAWING"'),
          updated_at = NOW()
      WHERE id = p_session_id;
      
      -- Bloquear mesa en 'ACTIVE' para cerrar compras de cartones
      IF v_session.table_id IS NOT NULL THEN
        UPDATE public.game_tables
        SET status = 'ACTIVE'::table_status_enum,
            updated_at = NOW()
        WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;
      END IF;

      RAISE NOTICE 'Sorteo iniciado para sesión %', p_session_id;
    ELSE
      -- Aún no es hora o no se cumplen las condiciones
      RETURN jsonb_build_object(
        'success', false, 
        'reason', 'COUNTDOWN_NOT_FINISHED',
        'countdown_ends_at', v_session.countdown_ends_at,
        'seconds_remaining', CASE 
          WHEN v_session.countdown_ends_at IS NOT NULL THEN EXTRACT(EPOCH FROM (v_session.countdown_ends_at - NOW()))
          ELSE NULL 
        END
      );
    END IF;
  END IF;
  
  -- Re-obtener la sesión actualizada
  SELECT current_state INTO v_current_state FROM public.game_sessions WHERE id = p_session_id;
  IF v_current_state IS NULL THEN
    v_current_state := '{}'::jsonb;
  END IF;
  
  v_drawn_balls := COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_current_state->'drawnBalls')::INT), '{}'::INT[]);
  v_total_balls := COALESCE((v_current_state->>'totalBalls')::INT, 90);
  v_last_drawn_at := (v_current_state->>'lastDrawnAt')::TIMESTAMPTZ;

  -- Validar tiempo (2 segundos entre bolas)
  IF v_last_drawn_at IS NOT NULL THEN
    v_seconds_since_last := EXTRACT(EPOCH FROM (NOW() - v_last_drawn_at));
    IF v_seconds_since_last < 2.0 THEN 
      RETURN jsonb_build_object('success', false, 'reason', 'TOO_FAST');
    END IF;
  END IF;

  IF array_length(v_drawn_balls, 1) >= v_total_balls THEN 
    RAISE EXCEPTION 'BINGO_COMPLETE';
  END IF;

  -- Generar bola aleatoria disponible
  SELECT array_agg(n) INTO v_available_balls 
  FROM generate_series(1, v_total_balls) AS n 
  WHERE NOT (n = ANY(v_drawn_balls));
  
  SELECT n INTO v_new_ball FROM unnest(v_available_balls) AS n ORDER BY random() LIMIT 1;

  -- Actualizar estado
  v_current_state := jsonb_set(v_current_state, '{currentBall}', to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{drawnBalls}', COALESCE(v_current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{lastDrawnAt}', to_jsonb(NOW()));

  UPDATE public.game_sessions SET current_state = v_current_state, updated_at = NOW() WHERE id = p_session_id;

  -- Registrar acción de auditoría
  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_sequence FROM public.game_actions WHERE session_id = p_session_id;
  v_action_payload := jsonb_build_object('ball_number', v_new_ball, 'drawn_at', NOW());
  v_state_hash := md5(v_action_payload::text || p_session_id::text || v_new_ball::text);

  INSERT INTO public.game_actions (session_id, user_id, action_type, payload, server_state_hash, idempotency_key, created_at, sequence_number)
  VALUES (p_session_id, '00000000-0000-0000-0000-000000000000'::uuid, 'DRAW_BALL', v_action_payload, v_state_hash, gen_random_uuid()::text, NOW(), v_next_sequence);

  RETURN jsonb_build_object('success', true, 'ball_number', v_new_ball);

EXCEPTION WHEN OTHERS THEN RAISE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.check_and_start_bingo_countdown() TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.reveal_next_bingo_ball(UUID) TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 113: 113_bingo_definitive_countdown_and_draw.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 113: CUENTA REGRESIVA DE 3 MINUTOS Y BLOQUEO A 10S
-- ==============================================================================
-- 1. Columna countdown_ends_at en game_sessions
-- 2. check_and_start_bingo_countdown: Mínimo 2 jugadores distintos con cartones -> 3 minutos
-- 3. reveal_next_bingo_ball: Revela bolas SOLO cuando los 3 minutos terminan
-- 4. buy_bingo_cards_secure: Bloqueo estricto de compras si faltan <= 10 segundos o sorteo activo
-- 5. server_bingo_operation: Delegación segura y estricta a reveal_next_bingo_ball
-- ==============================================================================

-- 1. Asegurar que exista la columna de cuenta regresiva
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS countdown_ends_at TIMESTAMPTZ;

-- 2. Función que verifica si hay 2 jugadores distintos con cartones para iniciar los 3 minutos
CREATE OR REPLACE FUNCTION public.check_and_start_bingo_countdown()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_unique_players INT;
  v_total_cards INT;
BEGIN
  FOR v_session IN
    SELECT gs.id, gs.table_id
    FROM public.game_sessions gs
    WHERE LOWER(gs.game_type::text) = 'bingo'
      AND gs.status::text IN ('WAITING', 'READY', 'SALES', 'IN_PROGRESS', 'waiting', 'ready', 'sales', 'in_progress')
      AND gs.countdown_ends_at IS NULL -- Solo si aún no ha iniciado la cuenta
  LOOP
    -- Contar jugadores ÚNICOS con al menos 1 cartón
    SELECT COUNT(DISTINCT user_id) INTO v_unique_players
    FROM public.bingo_card_purchases
    WHERE session_id = v_session.id OR game_table_id = v_session.table_id;
    
    -- Contar total de cartones
    SELECT COUNT(*) INTO v_total_cards
    FROM public.bingo_card_purchases
    WHERE session_id = v_session.id OR game_table_id = v_session.table_id;
    
    -- 👇 REGLA ESTRICTA: Mínimo 2 jugadores distintos con cartones y mínimo 2 cartones en total
    IF v_unique_players >= 2 AND v_total_cards >= 2 THEN
      UPDATE public.game_sessions
      SET countdown_ends_at = NOW() + INTERVAL '3 minutes', -- 3 MINUTOS DE RETROCESO
          updated_at = NOW()
      WHERE id = v_session.id;

      -- También reflejar en la configuración de la mesa para compatibilidad
      IF v_session.table_id IS NOT NULL THEN
        UPDATE public.game_tables
        SET config = COALESCE(config, '{}'::jsonb) || jsonb_build_object(
          'scheduled_start_at', NOW() + INTERVAL '3 minutes',
          'countdown_duration', 180,
          'status', 'COUNTDOWN'
        ),
        updated_at = NOW()
        WHERE id = v_session.table_id;
      END IF;
      
      RAISE NOTICE 'Cuenta regresiva de 3 minutos iniciada para sesión %', v_session.id;
    END IF;
  END LOOP;
END;
$$;

-- 3. Función que revela la bola SOLO cuando los 3 minutos terminan
CREATE OR REPLACE FUNCTION public.reveal_next_bingo_ball(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_new_ball INT;
  v_total_balls INT;
  v_last_drawn_at TIMESTAMPTZ;
  v_seconds_since_last NUMERIC;
  v_available_balls INT[];
  v_next_sequence INT;
  v_action_payload JSONB;
  v_state_hash TEXT;
  v_seconds_left NUMERIC;
BEGIN
  SELECT id, table_id, current_state, status, countdown_ends_at INTO v_session 
  FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  
  IF NOT FOUND THEN RAISE EXCEPTION 'SESSION_NOT_FOUND'; END IF;
  
  -- Si no está en DRAWING, verificar la cuenta regresiva
  IF v_session.status::text != 'DRAWING' THEN
    IF v_session.countdown_ends_at IS NOT NULL THEN
      v_seconds_left := EXTRACT(EPOCH FROM (v_session.countdown_ends_at - NOW()));
      
      IF v_seconds_left > 0 THEN
        -- Aún no es hora, devolver cuántos segundos faltan
        RETURN jsonb_build_object(
          'success', false, 
          'reason', 'COUNTDOWN_ACTIVE',
          'seconds_remaining', CEIL(v_seconds_left)
        );
      END IF;
      
      -- ¡La cuenta regresiva terminó! Iniciar sorteo
      UPDATE public.game_sessions
      SET status = 'DRAWING'::session_status_enum,
          current_state = jsonb_set(COALESCE(current_state, '{}'::jsonb), '{status}', '"DRAWING"'),
          updated_at = NOW()
      WHERE id = p_session_id;

      -- Bloquear mesa en 'ACTIVE' para cerrar permanentemente ventas
      IF v_session.table_id IS NOT NULL THEN
        UPDATE public.game_tables
        SET status = 'ACTIVE'::table_status_enum,
            updated_at = NOW()
        WHERE id = v_session.table_id AND status != 'ACTIVE'::table_status_enum;
      END IF;
      
      SELECT current_state INTO v_current_state FROM public.game_sessions WHERE id = p_session_id;
    ELSE
      RETURN jsonb_build_object('success', false, 'reason', 'NO_COUNTDOWN');
    END IF;
  ELSE
    v_current_state := v_session.current_state;
  END IF;
  
  IF v_current_state IS NULL THEN
    v_current_state := '{}'::jsonb;
  END IF;

  v_drawn_balls := COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_current_state->'drawnBalls')::INT), '{}'::INT[]);
  v_total_balls := COALESCE((v_current_state->>'totalBalls')::INT, 90);
  v_last_drawn_at := (v_current_state->>'lastDrawnAt')::TIMESTAMPTZ;

  -- Validar tiempo entre bolas (mínimo 2 segundos)
  IF v_last_drawn_at IS NOT NULL THEN
    v_seconds_since_last := EXTRACT(EPOCH FROM (NOW() - v_last_drawn_at));
    IF v_seconds_since_last < 2.0 THEN 
      RETURN jsonb_build_object('success', false, 'reason', 'TOO_FAST');
    END IF;
  END IF;

  IF array_length(v_drawn_balls, 1) >= v_total_balls THEN 
    RAISE EXCEPTION 'BINGO_COMPLETE';
  END IF;

  -- Generar bola aleatoria disponible
  SELECT array_agg(n) INTO v_available_balls FROM generate_series(1, v_total_balls) AS n WHERE NOT (n = ANY(v_drawn_balls));
  SELECT n INTO v_new_ball FROM unnest(v_available_balls) AS n ORDER BY random() LIMIT 1;

  -- Actualizar estado
  v_current_state := jsonb_set(v_current_state, '{currentBall}', to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{drawnBalls}', COALESCE(v_current_state->'drawnBalls', '[]'::jsonb) || to_jsonb(v_new_ball));
  v_current_state := jsonb_set(v_current_state, '{lastDrawnAt}', to_jsonb(NOW()));

  UPDATE public.game_sessions SET current_state = v_current_state, updated_at = NOW() WHERE id = p_session_id;

  -- Registrar acción de auditoría y propagación Realtime
  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_sequence FROM public.game_actions WHERE session_id = p_session_id;
  v_action_payload := jsonb_build_object('ball_number', v_new_ball, 'drawn_at', NOW());
  v_state_hash := md5(v_action_payload::text || p_session_id::text || v_new_ball::text);

  INSERT INTO public.game_actions (session_id, user_id, action_type, payload, server_state_hash, idempotency_key, created_at, sequence_number)
  VALUES (p_session_id, '00000000-0000-0000-0000-000000000000'::uuid, 'DRAW_BALL', v_action_payload, v_state_hash, gen_random_uuid()::text, NOW(), v_next_sequence);

  RETURN jsonb_build_object('success', true, 'ball_number', v_new_ball);

EXCEPTION WHEN OTHERS THEN RAISE;
END;
$$;

-- 4. Actualizar buy_bingo_cards_secure con CANDADO ESTRICTO DE 10 SEGUNDOS
CREATE OR REPLACE FUNCTION public.buy_bingo_cards_secure(
  p_game_table_id UUID,
  p_card_count INT,
  p_variant TEXT,
  p_price_per_card NUMERIC(14,2) DEFAULT 10.00,
  p_cards_data JSONB DEFAULT '[]'::jsonb,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_wallet_id UUID;
  v_wallet_available NUMERIC(14,2);
  v_total_cost NUMERIC(14,2);
  v_winner_pool NUMERIC(14,2);
  v_system_fee NUMERIC(14,2);
  v_purchase_id UUID;
  v_table RECORD;
  v_session RECORD;
  v_session_status TEXT;
  v_countdown_ends_at TIMESTAMPTZ;
  v_seconds_left NUMERIC;
  v_scheduled_start TIMESTAMPTZ;
  v_config JSONB;
  v_new_cards JSONB := '[]'::jsonb;
  v_card_item JSONB;
  v_card_hash TEXT;
  v_c INT;
  v_player_exists BOOLEAN := false;
  v_seat_assigned INT := 1;
  v_existing_purchase RECORD;
  v_table_variant TEXT;
  v_already_owned INT := 0;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  -- 🔐 CANDADO ESTRICTO 1: Verificar cuenta regresiva en game_sessions
  SELECT countdown_ends_at, status::text INTO v_countdown_ends_at, v_session_status
  FROM public.game_sessions 
  WHERE table_id = p_game_table_id
  ORDER BY created_at DESC LIMIT 1;
  
  IF v_session_status IS NOT NULL AND v_session_status IN ('DRAWING', 'FINISHED', 'COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'El sorteo ya comenzó. No se pueden comprar más cartones.';
  END IF;

  IF v_countdown_ends_at IS NOT NULL THEN
    -- Calcular cuántos segundos faltan
    v_seconds_left := EXTRACT(EPOCH FROM (v_countdown_ends_at - NOW()));
    
    -- 👇 BLOQUEO ESTRICTO: Si faltan 10 segundos o menos, o ya inició
    IF v_seconds_left <= 10 THEN
      RAISE EXCEPTION 'VENTAS_CERRADAS: Las ventas de cartones se bloquean 10 segundos antes del sorteo.';
    END IF;
  END IF;

  -- 🔐 RATE LIMIT EN COMPRAS: Máximo 10 compras por minuto
  IF NOT public.check_rate_limit('buy_bingo_cards', v_user_id::text, 10, INTERVAL '60 seconds') THEN
    RETURN jsonb_build_object('success', false, 'error', 'RATE_LIMIT_EXCEEDED: Has realizado demasiadas transacciones en poco tiempo. Espera un momento.');
  END IF;

  -- Validación estricta del formato de variante
  IF p_variant NOT IN ('75', '80', '90') THEN
    RETURN jsonb_build_object('success', false, 'error', 'VARIANTE_BINGO_INVALIDA');
  END IF;

  IF p_card_count < 1 OR p_card_count > 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'CANTIDAD_CARTONES_INVALIDA_MAX_20');
  END IF;

  -- Validar idempotencia de compra antes de cualquier transacción
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_existing_purchase 
    FROM public.bingo_card_purchases 
    WHERE idempotency_key = p_idempotency_key;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true,
        'is_idempotent', true,
        'purchase_id', v_existing_purchase.id,
        'variant', v_existing_purchase.variant,
        'card_count', v_existing_purchase.card_count,
        'cards', v_existing_purchase.cards_data,
        'total_cost', v_existing_purchase.total_cost,
        'winner_pool', v_existing_purchase.winner_pool,
        'system_fee', v_existing_purchase.system_fee
      );
    END IF;
  END IF;

  -- 1. Bloquear Mesa y Verificar Estado
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_game_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'MESA_NO_ENCONTRADA');
  END IF;

  -- Bloquear compras si la mesa ya comenzó
  IF v_table.status IN ('FINISHED'::table_status_enum, 'CLOSED'::table_status_enum, 'ACTIVE'::table_status_enum) THEN
    RAISE EXCEPTION 'MESA_NO_DISPONIBLE: La partida ya comenzó o finalizó. No se pueden comprar más cartones.';
  END IF;

  -- Validación de variante autorizada de la mesa contra el cartón comprado
  v_config := COALESCE(v_table.config, '{}'::jsonb);
  v_table_variant := COALESCE(v_config->>'variant', '75');
  IF p_variant <> v_table_variant THEN
    RETURN jsonb_build_object('success', false, 'error', 'VARIANTE_BINGO_INVALIDA_MESA: El tipo de cartón no coincide con la variante autorizada de la mesa.');
  END IF;

  -- Límite acumulativo de cartones por mesa (máximo 20 por usuario/mesa)
  SELECT COALESCE(SUM(card_count), 0) INTO v_already_owned
  FROM public.bingo_card_purchases
  WHERE game_table_id = p_game_table_id AND user_id = v_user_id;

  IF v_already_owned + p_card_count > 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'EXCEDE_MAXIMO_DE_20_CARTONES_ACUMULADOS: El límite acumulado permitido es de 20 cartones por jugador.');
  END IF;

  -- 2. Calcular costos usando el precio autoritativo
  v_total_cost := ROUND(p_card_count * COALESCE(v_table.entry_fee, 10.00), 2);
  v_winner_pool := ROUND(v_total_cost * 0.90, 2);
  v_system_fee := ROUND(v_total_cost * 0.10, 2);

  -- 3. Bloquear Billetera y Descontar Saldo
  SELECT id, available_balance INTO v_wallet_id, v_wallet_available
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF v_wallet_id IS NULL THEN
    INSERT INTO public.wallets (user_id, available_balance, held_balance)
    VALUES (v_user_id, 0.00, 0.00)
    RETURNING id, available_balance INTO v_wallet_id, v_wallet_available;
  END IF;

  IF v_wallet_available < v_total_cost THEN
    RETURN jsonb_build_object('success', false, 'error', 'SALDO_INSUFICIENTE_PARA_COMPRA_DE_CARTONES');
  END IF;

  UPDATE public.wallets
  SET available_balance = available_balance - v_total_cost,
      updated_at = NOW()
  WHERE id = v_wallet_id;

  -- 4. Generar Cartones Únicos para el Usuario
  FOR v_c IN 1..p_card_count LOOP
    v_card_item := public.generate_single_bingo_card_jsonb(p_variant, p_game_table_id, v_c);
    v_new_cards := v_new_cards || jsonb_build_array(v_card_item);
  END LOOP;

  v_card_hash := encode(digest(v_new_cards::text, 'sha256'), 'hex');

  -- 5. Registrar la Compra
  INSERT INTO public.bingo_card_purchases (
    user_id,
    game_table_id,
    variant,
    card_count,
    price_per_card,
    total_cost,
    winner_pool,
    system_fee,
    cards_data,
    unique_card_hash,
    idempotency_key
  ) VALUES (
    v_user_id,
    p_game_table_id,
    p_variant,
    p_card_count,
    COALESCE(v_table.entry_fee, 10.00),
    v_total_cost,
    v_winner_pool,
    v_system_fee,
    v_new_cards,
    v_card_hash,
    p_idempotency_key
  )
  RETURNING id INTO v_purchase_id;

  -- Registrar Ledger de Retención
  INSERT INTO public.wallet_ledgers (
    wallet_id,
    user_id,
    amount,
    entry_type,
    reference_type,
    reference_id,
    idempotency_key,
    description
  ) VALUES (
    v_wallet_id,
    v_user_id,
    -v_total_cost,
    'GAME_ENTRY_HOLD',
    'bingo_card_purchases',
    v_purchase_id::text,
    'bingo_buy_' || v_purchase_id::text,
    'Compra de ' || p_card_count || ' cartón(es) de Bingo ' || p_variant || ' Bolas'
  );

  -- 6. Asentar al Jugador en game_table_players si aún no está presente
  SELECT EXISTS (
    SELECT 1 FROM public.game_table_players
    WHERE table_id = p_game_table_id AND user_id = v_user_id AND status != 'LEFT'::player_table_status_enum
  ) INTO v_player_exists;

  IF NOT v_player_exists THEN
    SELECT COALESCE(MAX(seat_number), 0) + 1 INTO v_seat_assigned
    FROM public.game_table_players
    WHERE table_id = p_game_table_id AND status != 'LEFT'::player_table_status_enum;

    INSERT INTO public.game_table_players (
      table_id,
      user_id,
      seat_number,
      seat_index,
      team_index,
      status
    ) VALUES (
      p_game_table_id,
      v_user_id,
      v_seat_assigned,
      v_seat_assigned - 1,
      0,
      'READY'::player_table_status_enum
    );

    UPDATE public.game_tables
    SET current_players_count = current_players_count + 1,
        updated_at = NOW()
    WHERE id = p_game_table_id;
  END IF;

  -- 7. Disparar verificación de inicio de cuenta regresiva (3 minutos si hay >= 2 jugadores)
  PERFORM public.check_and_start_bingo_countdown();

  RETURN jsonb_build_object(
    'success', true,
    'purchase_id', v_purchase_id,
    'variant', p_variant,
    'card_count', p_card_count,
    'cards', v_new_cards,
    'total_cost', v_total_cost,
    'winner_pool', v_winner_pool,
    'system_fee', v_system_fee
  );
END;
$$;

-- 5. BLINDAR server_bingo_operation PARA QUE NUNCA FORZAR EL SORTEO ANTES DE TIEMPO
CREATE OR REPLACE FUNCTION public.server_bingo_operation(
  p_operation TEXT,
  p_session_id UUID,
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  IF p_operation = 'draw_ball' THEN
    -- Delegar estrictamente a reveal_next_bingo_ball que respeta la cuenta regresiva de 3 minutos
    RETURN public.reveal_next_bingo_ball(p_session_id);
  ELSE
    RAISE EXCEPTION 'INVALID_OPERATION: Operación no soportada';
  END IF;
END;
$$;

-- Permisos
GRANT EXECUTE ON FUNCTION public.check_and_start_bingo_countdown() TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.reveal_next_bingo_ball(UUID) TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.buy_bingo_cards_secure(UUID, INT, TEXT, NUMERIC, JSONB, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.server_bingo_operation(TEXT, UUID, UUID) TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 114: 114_bingo_engine_tick_rpc.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 114: RPC TICK UNIFICADO PARA MOTOR DE BINGO
-- Permite que el servidor ejecute el ciclo completo vía HTTP REST seguro (Supabase client)
-- o conexión directa sin riesgo de timeouts de socket TCP no disponibles.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.run_bingo_engine_tick()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_balls_drawn INT := 0;
  v_draw_res JSONB;
BEGIN
  -- 1. Verificar y arrancar cuenta regresiva en mesas con >= 2 jugadores
  PERFORM public.check_and_start_bingo_countdown();

  -- 2. Buscar sesiones activas con cuenta regresiva finalizada
  FOR v_session IN
    SELECT id
    FROM public.game_sessions
    WHERE LOWER(game_type::text) = 'bingo'
      AND status::text IN ('WAITING', 'READY', 'SALES', 'DRAWING', 'waiting', 'ready', 'sales', 'drawing')
      AND countdown_ends_at IS NOT NULL
      AND countdown_ends_at <= NOW()
    LIMIT 5
  LOOP
    BEGIN
      v_draw_res := public.reveal_next_bingo_ball(v_session.id);
      IF (v_draw_res->>'success')::boolean IS TRUE THEN
        v_balls_drawn := v_balls_drawn + 1;
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        -- Tolerar excepciones de concurrencia o fin de partida
        NULL;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'balls_drawn', v_balls_drawn,
    'timestamp', NOW()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.run_bingo_engine_tick() TO authenticated, anon, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 115: 115_atrapaito_realtime_multiplayer_and_abandon.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 115: SISTEMA COMPLETO DE ATRAPAITO CRIOLLO ONLINE EN TIEMPO REAL
-- Proyecto: RASPANDO LA OLLA 🇻🇪 (PulsoPLAY)
-- Estado: PRODUCCIÓN / EJECUTAR EN SUPABASE SQL EDITOR DIRECTAMENTE
-- ==============================================================================
-- 1. Campos adicionales en game_sessions para soporte de turnos en tiempo real
-- 2. Función `start_atrapaito_session`: Inicia la partida con posiciones iniciales y 15s
-- 3. Función `submit_atrapaito_action`: Valida turnos, movimientos de canicas y muros
-- 4. Función `credit_atrapaito_winner`: Liquidación del 90% al ganador y 10% plataforma
-- 5. Función `abandon_atrapaito_game`: Cierre por abandono y liquidación al rival
-- 6. Función `get_atrapaito_state`: Reconexión instantánea y obtención de estado autoritativo
-- 7. Funciones de compatibilidad `handle_atrapaito_abandon` y `submit_atrapaito_action_secure`
-- ==============================================================================

-- 1. ASEGURAR COLUMNAS EN game_sessions
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS turn_expires_at TIMESTAMPTZ;
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS current_turn_user_id UUID;
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS winner_user_id UUID;
ALTER TABLE public.game_sessions ADD COLUMN IF NOT EXISTS game_variant TEXT DEFAULT 'atrapaito';

-- 2. FUNCIÓN PARA INICIAR UNA SESIÓN DE ATRAPAITO
CREATE OR REPLACE FUNCTION public.start_atrapaito_session(
  p_session_id UUID,
  p_blue_user_id UUID,
  p_red_user_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_initial_state JSONB;
BEGIN
  -- Estado inicial del juego
  v_initial_state := jsonb_build_object(
    'bluePos', jsonb_build_object('col', 4, 'row', 14),
    'redPos', jsonb_build_object('col', 3, 'row', 14),
    'walls', '[]'::jsonb,
    'blueWalls', 10,
    'redWalls', 10,
    'turn', 'BLUE',
    'action', 'MOVE',
    'wallOrientation', 'HORIZONTAL',
    'pendingWall', null,
    'winner', null,
    'mode', 'ONLINE',
    'isAiThinking', false,
    'consecutiveDraws', 0,
    'blueUserId', p_blue_user_id,
    'redUserId', p_red_user_id
  );

  -- Actualizar la sesión con el estado inicial
  UPDATE public.game_sessions
  SET 
    current_state = v_initial_state,
    current_turn_user_id = p_blue_user_id, -- Azul comienza
    turn_expires_at = NOW() + INTERVAL '15 seconds',
    status = 'ACTIVE',
    updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'initial_state', v_initial_state
  );
END;
$$;

-- 3. FUNCIÓN PARA ACREDITAR PREMIO AL GANADOR (90% GANADOR / 10% PLATAFORMA)
CREATE OR REPLACE FUNCTION public.credit_atrapaito_winner(
  p_session_id UUID,
  p_winner_user_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_table_id UUID;
  v_entry_fee NUMERIC := 0;
  v_gross_pool NUMERIC := 0;
  v_prize_pool NUMERIC := 0;
  v_platform_fee NUMERIC := 0;
BEGIN
  IF p_winner_user_id IS NULL THEN
    RETURN;
  END IF;

  SELECT table_id INTO v_table_id
  FROM public.game_sessions
  WHERE id = p_session_id;

  IF v_table_id IS NOT NULL THEN
    SELECT COALESCE(entry_fee, 0) INTO v_entry_fee
    FROM public.game_tables
    WHERE id = v_table_id;
  END IF;

  v_gross_pool := v_entry_fee * 2;
  v_prize_pool := ROUND(v_gross_pool * 0.90, 2);
  v_platform_fee := ROUND(v_gross_pool * 0.10, 2);

  -- Actualizar billetera del ganador
  IF v_prize_pool > 0 THEN
    UPDATE public.wallets
    SET available_balance = available_balance + v_prize_pool,
        updated_at = NOW()
    WHERE user_id = p_winner_user_id;

    -- Registrar en el libro mayor (ledger)
    INSERT INTO public.ledger_entries (
      user_id,
      amount,
      type,
      description,
      reference_id,
      created_at
    ) VALUES (
      p_winner_user_id,
      v_prize_pool,
      'GAME_WIN',
      'Ganancia en Atrapaito Criollo (Pozo neto 90%)',
      p_session_id::text,
      NOW()
    );
  END IF;

  -- Actualizar montos en la sesión
  UPDATE public.game_sessions
  SET winner_user_id = p_winner_user_id,
      winner_prize_amount = v_prize_pool,
      service_fee_amount = v_platform_fee,
      gross_pool = v_gross_pool,
      is_settled = TRUE,
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Actualizar la mesa
  IF v_table_id IS NOT NULL THEN
    UPDATE public.game_tables
    SET status = 'FINISHED', updated_at = NOW()
    WHERE id = v_table_id;

    UPDATE public.game_table_players
    SET status = 'WON', updated_at = NOW()
    WHERE table_id = v_table_id AND user_id = p_winner_user_id;
  END IF;
END;
$$;

-- 4. FUNCIÓN PRINCIPAL PARA ENVIAR JUGADAS (CANICAS Y MUROS)
CREATE OR REPLACE FUNCTION public.submit_atrapaito_action(
  p_session_id UUID,
  p_user_id UUID,
  p_action_type TEXT, -- 'MOVE_MARBLE' o 'PLACE_WALL'
  p_action_data JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_current_state JSONB;
  v_new_state JSONB;
  v_is_my_turn BOOLEAN;
  v_time_left NUMERIC;
  v_opponent_id UUID;
  v_next_turn_user_id UUID;
  v_blue_pos JSONB;
  v_red_pos JSONB;
  v_walls JSONB;
  v_blue_walls INT;
  v_red_walls INT;
  v_turn TEXT;
  v_action TEXT;
  v_wall_orientation TEXT;
  v_pending_wall JSONB;
  v_winner TEXT;
  v_blue_user_id UUID;
  v_red_user_id UUID;
  v_new_wall JSONB;
  v_walls_array JSONB;
  v_new_col INT;
  v_new_row INT;
  v_current_pos JSONB;
  v_new_pos JSONB;
BEGIN
  -- 1. Obtener sesión con bloqueo
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 2. Validar que el juego esté activo
  IF v_session.status::text IN ('FINISHED', 'completed', 'CANCELLED') THEN
    RETURN jsonb_build_object('success', false, 'error', 'GAME_ALREADY_FINISHED');
  END IF;

  -- 3. Obtener estado actual
  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);
  
  -- Extraer datos del estado
  v_blue_pos := COALESCE(v_current_state->'bluePos', jsonb_build_object('col', 4, 'row', 14));
  v_red_pos := COALESCE(v_current_state->'redPos', jsonb_build_object('col', 3, 'row', 14));
  v_walls := COALESCE(v_current_state->'walls', '[]'::jsonb);
  v_blue_walls := COALESCE((v_current_state->>'blueWalls')::INT, 10);
  v_red_walls := COALESCE((v_current_state->>'redWalls')::INT, 10);
  v_turn := COALESCE(v_current_state->>'turn', 'BLUE');
  v_blue_user_id := (v_current_state->>'blueUserId')::UUID;
  v_red_user_id := (v_current_state->>'redUserId')::UUID;

  -- Resolver IDs si no estaban en el JSON
  IF v_blue_user_id IS NULL OR v_red_user_id IS NULL THEN
    SELECT user_id INTO v_opponent_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id != p_user_id
      AND status != 'LEFT'
    LIMIT 1;

    IF v_turn = 'BLUE' THEN
      v_blue_user_id := p_user_id;
      v_red_user_id := v_opponent_id;
    ELSE
      v_red_user_id := p_user_id;
      v_blue_user_id := v_opponent_id;
    END IF;
  ELSE
    v_opponent_id := CASE WHEN p_user_id = v_blue_user_id THEN v_red_user_id ELSE v_blue_user_id END;
  END IF;

  -- 4. Validar turno
  IF v_session.current_turn_user_id IS NOT NULL AND v_session.current_turn_user_id != p_user_id THEN
    -- Fallback tolerante si el turno corresponde por color
    IF (v_turn = 'BLUE' AND p_user_id != v_blue_user_id) OR (v_turn = 'RED' AND p_user_id != v_red_user_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'NOT_YOUR_TURN');
    END IF;
  END IF;

  -- 5. Procesar la acción
  IF p_action_type = 'MOVE_MARBLE' THEN
    v_new_col := (p_action_data->>'col')::INT;
    v_new_row := (p_action_data->>'row')::INT;

    IF v_turn = 'BLUE' THEN
      v_new_pos := jsonb_build_object('col', v_new_col, 'row', v_new_row);
      v_new_state := jsonb_set(v_current_state, '{bluePos}', v_new_pos);

      -- Verificar meta (fila 0)
      IF v_new_row = 0 THEN
        v_new_state := jsonb_set(v_new_state, '{winner}', '"BLUE"'::jsonb);
        v_new_state := jsonb_set(v_new_state, '{status}', '"FINISHED"'::jsonb);

        UPDATE public.game_sessions
        SET current_state = v_new_state,
            status = 'FINISHED',
            winner_user_id = p_user_id,
            turn_expires_at = NULL,
            current_turn_user_id = NULL,
            updated_at = NOW()
        WHERE id = p_session_id;

        PERFORM public.credit_atrapaito_winner(p_session_id, p_user_id);

        RETURN jsonb_build_object('success', true, 'winner', 'BLUE', 'message', '¡Victoria Azul!');
      END IF;
    ELSE
      v_new_pos := jsonb_build_object('col', v_new_col, 'row', v_new_row);
      v_new_state := jsonb_set(v_current_state, '{redPos}', v_new_pos);

      IF v_new_row = 0 THEN
        v_new_state := jsonb_set(v_new_state, '{winner}', '"RED"'::jsonb);
        v_new_state := jsonb_set(v_new_state, '{status}', '"FINISHED"'::jsonb);

        UPDATE public.game_sessions
        SET current_state = v_new_state,
            status = 'FINISHED',
            winner_user_id = p_user_id,
            turn_expires_at = NULL,
            current_turn_user_id = NULL,
            updated_at = NOW()
        WHERE id = p_session_id;

        PERFORM public.credit_atrapaito_winner(p_session_id, p_user_id);

        RETURN jsonb_build_object('success', true, 'winner', 'RED', 'message', '¡Victoria Roja!');
      END IF;
    END IF;

    -- Cambiar turno al oponente
    v_next_turn_user_id := CASE WHEN v_turn = 'BLUE' THEN v_red_user_id ELSE v_blue_user_id END;
    v_new_state := jsonb_set(v_new_state, '{turn}', to_jsonb(CASE WHEN v_turn = 'BLUE' THEN 'RED' ELSE 'BLUE' END));
    v_new_state := jsonb_set(v_new_state, '{action}', '"MOVE"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{pendingWall}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turn_expires_at}', to_jsonb((NOW() + INTERVAL '15 seconds')::text));
    v_new_state := jsonb_set(v_new_state, '{current_turn_user_id}', to_jsonb(v_next_turn_user_id::text));

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_expires_at = NOW() + INTERVAL '15 seconds',
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true, 'message', 'Movimiento registrado', 'newState', v_new_state);

  ELSIF p_action_type = 'PLACE_WALL' THEN
    v_new_wall := p_action_data;

    IF v_turn = 'BLUE' AND v_blue_walls <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'NO_WALLS_LEFT');
    END IF;
    IF v_turn = 'RED' AND v_red_walls <= 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'NO_WALLS_LEFT');
    END IF;

    v_walls_array := v_walls || jsonb_build_array(v_new_wall);
    v_new_state := jsonb_set(v_current_state, '{walls}', v_walls_array);

    IF v_turn = 'BLUE' THEN
      v_new_state := jsonb_set(v_new_state, '{blueWalls}', to_jsonb(GREATEST(0, v_blue_walls - 1)));
    ELSE
      v_new_state := jsonb_set(v_new_state, '{redWalls}', to_jsonb(GREATEST(0, v_red_walls - 1)));
    END IF;

    v_next_turn_user_id := CASE WHEN v_turn = 'BLUE' THEN v_red_user_id ELSE v_blue_user_id END;
    v_new_state := jsonb_set(v_new_state, '{turn}', to_jsonb(CASE WHEN v_turn = 'BLUE' THEN 'RED' ELSE 'BLUE' END));
    v_new_state := jsonb_set(v_new_state, '{action}', '"MOVE"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{pendingWall}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turn_expires_at}', to_jsonb((NOW() + INTERVAL '15 seconds')::text));
    v_new_state := jsonb_set(v_new_state, '{current_turn_user_id}', to_jsonb(v_next_turn_user_id::text));

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_expires_at = NOW() + INTERVAL '15 seconds',
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true, 'message', 'Muro colocado', 'newState', v_new_state);

  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'UNKNOWN_ACTION_TYPE');
  END IF;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- 5. FUNCIÓN PARA ABANDONO DE ATRAPAITO
CREATE OR REPLACE FUNCTION public.abandon_atrapaito_game(
  p_session_id UUID,
  p_leaving_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_effective_leaver_id UUID;
  v_winner_id UUID;
  v_session RECORD;
  v_blue_user_id UUID;
  v_red_user_id UUID;
BEGIN
  v_effective_leaver_id := COALESCE(p_leaving_user_id, auth.uid());

  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id FOR UPDATE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status IN ('FINISHED', 'completed', 'CANCELLED') THEN
    RETURN jsonb_build_object('success', true, 'message', 'ALREADY_FINISHED');
  END IF;

  v_blue_user_id := (v_session.current_state->>'blueUserId')::UUID;
  v_red_user_id := (v_session.current_state->>'redUserId')::UUID;

  IF v_effective_leaver_id = v_blue_user_id THEN
    v_winner_id := v_red_user_id;
  ELSIF v_effective_leaver_id = v_red_user_id THEN
    v_winner_id := v_blue_user_id;
  ELSE
    SELECT user_id INTO v_winner_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id != v_effective_leaver_id
      AND status != 'LEFT'
    LIMIT 1;
  END IF;

  UPDATE public.game_sessions
  SET status = 'FINISHED',
      winner_user_id = v_winner_id,
      current_state = COALESCE(current_state, '{}'::jsonb) || jsonb_build_object(
        'winner', CASE WHEN v_winner_id = v_blue_user_id THEN 'BLUE' ELSE 'RED' END,
        'winner_user_id', v_winner_id,
        'abandoned_by', v_effective_leaver_id,
        'status', 'FINISHED'
      ),
      turn_expires_at = NULL,
      current_turn_user_id = NULL,
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Acreditar premio del 90% al rival que no abandonó
  IF v_winner_id IS NOT NULL THEN
    PERFORM public.credit_atrapaito_winner(p_session_id, v_winner_id);
  END IF;

  -- Marcar jugador que abandonó
  UPDATE public.game_table_players
  SET status = 'LEFT', updated_at = NOW()
  WHERE table_id = v_session.table_id AND user_id = v_effective_leaver_id;

  RETURN jsonb_build_object('success', true, 'winner_user_id', v_winner_id);
END;
$$;

-- 6. FUNCIÓN PARA RECONEXIÓN Y OBTENCIÓN DE ESTADO AUTORITATIVO
CREATE OR REPLACE FUNCTION public.get_atrapaito_state(
  p_session_id UUID,
  p_user_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_player_color TEXT;
  v_blue_user_id UUID;
  v_red_user_id UUID;
BEGIN
  SELECT * INTO v_session FROM public.game_sessions WHERE id = p_session_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  v_blue_user_id := (v_session.current_state->>'blueUserId')::UUID;
  v_red_user_id := (v_session.current_state->>'redUserId')::UUID;

  IF p_user_id = v_blue_user_id THEN
    v_player_color := 'BLUE';
  ELSIF p_user_id = v_red_user_id THEN
    v_player_color := 'RED';
  ELSE
    -- Asignar por posición de unión a la mesa si no estaba en el estado
    v_player_color := 'BLUE';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'state', v_session.current_state,
    'playerColor', v_player_color,
    'currentTurnUserId', v_session.current_turn_user_id,
    'turnExpiresAt', v_session.turn_expires_at,
    'status', v_session.status
  );
END;
$$;

-- 7. ALIAS DE COMPATIBILIDAD CON FUNCIONES PREVIAS
CREATE OR REPLACE FUNCTION public.handle_atrapaito_abandon(
  p_session_id UUID,
  p_leaving_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.abandon_atrapaito_game(p_session_id, p_leaving_user_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_atrapaito_action_secure(
  p_session_id UUID,
  p_user_id UUID,
  p_action_type VARCHAR,
  p_action_data JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.submit_atrapaito_action(p_session_id, p_user_id, p_action_type::TEXT, p_action_data);
END;
$$;

-- 8. HABILITAR REALTIME EN game_sessions (SEGURO E IDEMPOTENTE)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables 
    WHERE pubname = 'supabase_realtime' 
      AND schemaname = 'public' 
      AND tablename = 'game_sessions'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.game_sessions;
  END IF;
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;

