-- MIGRACIÓN 116: 116_fix_abandon_game_table_secure_ambiguity.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ================================================================
-- MIGRACIÓN 116: ELIMINAR AMBIGÜEDAD EN RPC abandon_game_table_secure
-- Proyecto: RASPANDO LA OLLA 🇻🇪
-- Fecha: 2026-09-03
-- Descripción:
--   1. Elimina todas las sobrecargas conflictivas de abandon_game_table_secure
--      que usaban (UUID, UUID, VARCHAR), (UUID, VARCHAR), (UUID, UUID) etc.,
--      evitando el error de PostgREST:
--      "Could not choose the best candidate function between ... character varying ... text".
--   2. Establece la versión definitiva canónica con p_idempotency_key TEXT DEFAULT NULL.
--   3. Integra resolución atómica para partidas activas (incluyendo Atrapaíto y juegos 1v1),
--      reembolso de entradas pre-partida y notificación de recarga de esquema.
-- ================================================================

-- 1. ELIMINAR TODAS LAS FIRMAS ANTERIORES Y AMBIGUAS
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID, CHARACTER VARYING);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID, VARCHAR);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, CHARACTER VARYING);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, VARCHAR);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID, TEXT);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, TEXT);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID, UUID);
DROP FUNCTION IF EXISTS public.abandon_game_table_secure(UUID);

-- 2. CREAR LA VERSIÓN DEFINITIVA Y CANÓNICA CON TEXT
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_player RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_active_players_count INTEGER;
  v_remaining_player RECORD;
  v_effective_idempotency TEXT;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_session_is_active BOOLEAN := false;
  v_settle_result JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTHENTICATED');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || p_table_id::text || '_' || v_caller_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  -- 1. Obtener mesa con bloqueo pesimista
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;

  -- 2. Obtener sesión activa si existe
  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE id = p_session_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status IN ('ACTIVE'::session_status_enum, 'READY'::session_status_enum, 'STARTING'::session_status_enum, 'PAUSED'::session_status_enum)
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF v_session.id IS NOT NULL AND v_session.status = 'ACTIVE'::session_status_enum THEN
    v_session_is_active := true;
  END IF;

  -- 3. Obtener y actualizar registro del jugador a 'LEFT'
  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND user_id = v_caller_id
    AND status IN ('JOINED'::player_table_status_enum, 'READY'::player_table_status_enum, 'PLAYING'::player_table_status_enum)
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.game_table_players
    SET status = 'LEFT'::player_table_status_enum,
        left_at = NOW(),
        updated_at = NOW()
    WHERE id = v_player.id;
  ELSE
    -- Verificar si ya estaba marcado como LEFT
    SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

    RETURN jsonb_build_object(
      'success', true,
      'already_left', true,
      'table_id', p_table_id,
      'remaining_players', v_active_players_count
    );
  END IF;

  -- 4. Reembolso pre-partida si la partida NO ha comenzado y había cuota de entrada
  IF NOT v_session_is_active AND v_table.entry_fee > 0.00 THEN
    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_caller_id AND currency = 'VES'
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.wallets
      SET available_balance = available_balance + v_table.entry_fee,
          updated_at = NOW()
      WHERE id = v_wallet.id;

      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        v_wallet.id,
        v_caller_id,
        v_table.entry_fee,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        p_table_id,
        'game_tables',
        'game_tables',
        COALESCE(v_wallet.available_balance, 0.00) + v_table.entry_fee,
        COALESCE(v_wallet.available_balance, 0.00) + v_table.entry_fee,
        COALESCE(v_wallet.held_balance, 0.00),
        v_effective_idempotency || '_refund',
        'Reembolso por abandono de mesa antes del inicio',
        NOW()
      );
      v_refund_amount := v_table.entry_fee;
    END IF;
  END IF;

  -- 5. Contar jugadores restantes en la mesa
  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

  -- 6. Si la partida estaba activa y queda 1 solo jugador: victoria por abandono (Forfeit)
  IF v_session_is_active AND v_session.id IS NOT NULL THEN
    IF v_active_players_count = 1 THEN
      SELECT user_id INTO v_remaining_player
      FROM public.game_table_players
      WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum
      LIMIT 1;

      IF v_remaining_player.user_id IS NOT NULL THEN
        -- Si es Atrapaíto, usar liquidación especializada si existe
        IF v_table.game_type::text = 'atrapaito' THEN
          BEGIN
            PERFORM public.credit_atrapaito_winner(v_session.id, v_remaining_player.user_id);
          EXCEPTION WHEN OTHERS THEN
            -- Fallback a settle_game_session estándar
            PERFORM public.settle_game_session(
              v_session.id,
              ARRAY[v_remaining_player.user_id],
              NULL,
              'forfeit_' || v_session.id::text || '_' || v_remaining_player.user_id::text
            );
          END;
        ELSE
          PERFORM public.settle_game_session(
            v_session.id,
            ARRAY[v_remaining_player.user_id],
            NULL,
            'forfeit_' || v_session.id::text || '_' || v_remaining_player.user_id::text
          );
        END IF;

        UPDATE public.game_sessions
        SET status = 'FINISHED'::session_status_enum,
            winner_user_id = v_remaining_player.user_id,
            ended_at = NOW()
        WHERE id = v_session.id;
      END IF;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;

    ELSIF v_active_players_count = 0 THEN
      UPDATE public.game_sessions
      SET status = 'CANCELLED'::session_status_enum,
          ended_at = NOW()
      WHERE id = v_session.id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;
    END IF;
  ELSE
    -- Si la mesa previa quedó con 0 jugadores, cerrarla
    IF v_active_players_count = 0 THEN
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;
    ELSE
      UPDATE public.game_tables
      SET current_players_count = v_active_players_count,
          updated_at = NOW()
      WHERE id = p_table_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'session_id', v_session.id,
    'remaining_players', v_active_players_count,
    'refund_amount', v_refund_amount
  );
END;
$$;

-- Otorgar permisos a los roles necesarios
GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role, anon;

-- Notificar a PostgREST para recargar el esquema inmediatamente
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 117: 117_universal_game_abandonment.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 117: SISTEMA UNIVERSAL DE ABANDONO DE PARTIDA (VOLUNTARIO E INVOLUNTARIO)
-- ==============================================================================
-- 1. Asegurar valores 'ABANDONED' en tipos enumerados player_table_status_enum y session_status_enum
-- 2. Compatibilidad en game_actions para admitir action_data además de payload
-- 3. Función canónica public.abandon_game_secure(p_session_id UUID, p_idempotency_key TEXT)
-- 4. Función de daemon public.process_expired_turns() para abandono por tiempo agotado
-- ==============================================================================

DO $$
BEGIN
  -- Agregar ABANDONED a player_table_status_enum si no existe
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum
    WHERE enumtypid = 'public.player_table_status_enum'::regtype
      AND enumlabel = 'ABANDONED'
  ) THEN
    ALTER TYPE public.player_table_status_enum ADD VALUE 'ABANDONED';
  END IF;

  -- Agregar ABANDONED a session_status_enum si no existe
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum
    WHERE enumtypid = 'public.session_status_enum'::regtype
      AND enumlabel = 'ABANDONED'
  ) THEN
    ALTER TYPE public.session_status_enum ADD VALUE 'ABANDONED';
  END IF;
END $$;

-- Asegurar columnas y restricciones flexibles en game_actions para auditoría universal
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'game_actions') THEN
    ALTER TABLE public.game_actions ADD COLUMN IF NOT EXISTS action_data JSONB;
    ALTER TABLE public.game_actions ALTER COLUMN payload DROP NOT NULL;
    ALTER TABLE public.game_actions ALTER COLUMN server_state_hash DROP NOT NULL;
    ALTER TABLE public.game_actions ALTER COLUMN sequence_number DROP NOT NULL;
    ALTER TABLE public.game_actions ALTER COLUMN idempotency_key DROP NOT NULL;
  END IF;
END $$;

-- ==============================================================================
-- FUNCIÓN UNIFICADA DE ABANDONO DE PARTIDA (Todos los juegos)
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.abandon_game_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_game_type TEXT;
  v_entry_fee NUMERIC(14,2) := 0.00;
  v_opponent_id UUID;
  v_prize_pool NUMERIC(14,2) := 0.00;
  v_effective_idempotency TEXT;
  v_next_seq INT := 1;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTENTICADO');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || p_session_id::text || '_' || v_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  -- 1. Obtener datos con bloqueo para evitar condiciones de carrera
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  v_game_type := LOWER(COALESCE(v_table.game_type::text, v_session.game_type::text, ''));
  v_entry_fee := COALESCE(v_table.entry_fee, 0.00);

  IF v_session.status::text IN ('FINISHED', 'finished', 'CANCELLED', 'cancelled', 'ABANDONED', 'abandoned', 'SETTLED', 'settled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'JUEGO_YA_FINALIZADO');
  END IF;

  -- 2. Marcar al jugador como ABANDONED en la mesa
  UPDATE public.game_table_players
  SET status = 'ABANDONED'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_session.table_id 
    AND user_id = v_user_id 
    AND status::text NOT IN ('ABANDONED', 'LEFT');

  -- 3. Lógica específica según el tipo de juego
  IF v_game_type IN ('atrapaito', 'chess', 'checkers', 'tictactoe', 'tic_tac_toe', 'rps', 'rock_paper_scissors', 'domino', 'domino_venezolano', 'truco', 'truco_venezolano', 'una_olla', 'unaolla') THEN
    -- Para juegos 1vs1 / tablero: buscar al oponente restante activo
    SELECT user_id INTO v_opponent_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id 
      AND user_id != v_user_id 
      AND status::text NOT IN ('ABANDONED', 'LEFT')
    LIMIT 1;

    IF v_opponent_id IS NOT NULL THEN
      -- Liquidar de manera segura usando settle_game_session si está disponible
      BEGIN
        PERFORM public.settle_game_session(
          p_session_id,
          ARRAY[v_opponent_id],
          NULL,
          v_effective_idempotency || '_settle'
        );
      EXCEPTION WHEN OTHERS THEN
        -- Fallback de liquidación directa 90/10
        v_prize_pool := (v_entry_fee * 2.00) * 0.90;
        IF v_prize_pool > 0.00 THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_prize_pool,
              updated_at = NOW()
          WHERE user_id = v_opponent_id AND currency = 'VES';
        END IF;
      END;
      
      -- Finalizar sesión y declarar ganador por abandono
      UPDATE public.game_sessions
      SET status = 'FINISHED'::session_status_enum,
          winner_user_id = v_opponent_id,
          current_state = jsonb_set(
            COALESCE(current_state, '{}'::jsonb),
            '{winner}',
            '"OPPONENT_BY_ABANDON"'::jsonb
          ),
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      -- Cerrar la mesa correspondiente
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = v_session.table_id;
    ELSE
      -- Si no quedó ningún oponente, cancelar la sesión y cerrar la mesa
      UPDATE public.game_sessions
      SET status = 'CANCELLED'::session_status_enum,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = v_session.table_id;
    END IF;

  ELSIF v_game_type = 'bingo' THEN
    -- En Bingo, abandonar no detiene el juego para el resto de la sala
    UPDATE public.game_sessions
    SET current_state = jsonb_set(
        COALESCE(current_state, '{}'::jsonb),
        '{abandonedPlayers}', 
        COALESCE(current_state->'abandonedPlayers', '[]'::jsonb) || to_jsonb(v_user_id::text)
    ),
    updated_at = NOW()
    WHERE id = p_session_id;
  END IF;

  -- 4. Registrar la acción de abandono en el historial de jugadas
  BEGIN
    SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_seq
    FROM public.game_actions
    WHERE session_id = p_session_id;

    INSERT INTO public.game_actions (
      session_id, user_id, sequence_number, action_type, payload, action_data,
      is_valid, server_state_hash, idempotency_key, created_at
    ) VALUES (
      p_session_id, v_user_id, v_next_seq, 'ABANDON',
      jsonb_build_object('reason', 'VOLUNTARY', 'user_id', v_user_id),
      jsonb_build_object('reason', 'VOLUNTARY', 'user_id', v_user_id),
      true, 'abandon_hash', v_effective_idempotency || '_act', NOW()
    );
  EXCEPTION WHEN OTHERS THEN
    -- Si falla el registro secundario en game_actions, no bloquear la transacción principal
    NULL;
  END;

  RETURN jsonb_build_object('success', true, 'message', 'Has abandonado la partida correctamente');
END;
$$;

-- ==============================================================================
-- FUNCIÓN PARA DETECTAR ABANDONO POR TIEMPO AGOTADO (Para el Daemon de Backend)
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.process_expired_turns()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_expired_session RECORD;
  v_opponent_id UUID;
  v_prize_pool NUMERIC(14,2);
  v_entry_fee NUMERIC(14,2);
  v_next_seq INT := 1;
BEGIN
  FOR v_expired_session IN 
    SELECT gs.id, gs.table_id, gs.current_turn_user_id, gt.game_type, gt.entry_fee
    FROM public.game_sessions gs
    JOIN public.game_tables gt ON gt.id = gs.table_id
    WHERE gs.status::text IN ('ACTIVE', 'active', 'IN_PROGRESS', 'in_progress', 'STARTING', 'starting', 'READY', 'ready')
      AND gs.turn_expires_at IS NOT NULL
      AND gs.turn_expires_at < NOW()
      AND gs.current_turn_user_id IS NOT NULL
    FOR UPDATE OF gs SKIP LOCKED
  LOOP
    -- Si es un juego 1vs1 y se acaba el tiempo, el rival gana automáticamente
    IF LOWER(v_expired_session.game_type::text) IN ('atrapaito', 'chess', 'checkers', 'tictactoe', 'tic_tac_toe', 'rps', 'rock_paper_scissors', 'domino', 'domino_venezolano', 'truco', 'truco_venezolano') THEN
      SELECT user_id INTO v_opponent_id
      FROM public.game_table_players
      WHERE table_id = v_expired_session.table_id 
        AND user_id != v_expired_session.current_turn_user_id 
        AND status::text NOT IN ('ABANDONED', 'LEFT')
      LIMIT 1;

      IF v_opponent_id IS NOT NULL THEN
        v_entry_fee := COALESCE(v_expired_session.entry_fee, 0.00);

        BEGIN
          PERFORM public.settle_game_session(
            v_expired_session.id,
            ARRAY[v_opponent_id],
            NULL,
            'timeout_' || v_expired_session.id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
          );
        EXCEPTION WHEN OTHERS THEN
          v_prize_pool := (v_entry_fee * 2.00) * 0.90;
          IF v_prize_pool > 0.00 THEN
            UPDATE public.wallets
            SET available_balance = available_balance + v_prize_pool,
                updated_at = NOW()
            WHERE user_id = v_opponent_id AND currency = 'VES';
          END IF;
        END;
        
        UPDATE public.game_sessions
        SET status = 'FINISHED'::session_status_enum,
            winner_user_id = v_opponent_id,
            current_state = jsonb_set(
              COALESCE(current_state, '{}'::jsonb),
              '{winner}',
              '"OPPONENT_BY_ABANDON"'::jsonb
            ),
            ended_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_session.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            current_players_count = 0,
            updated_at = NOW()
        WHERE id = v_expired_session.table_id;

        BEGIN
          SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_seq
          FROM public.game_actions
          WHERE session_id = v_expired_session.id;

          INSERT INTO public.game_actions (
            session_id, user_id, sequence_number, action_type, payload, action_data,
            is_valid, server_state_hash, idempotency_key, created_at
          ) VALUES (
            v_expired_session.id,
            v_expired_session.current_turn_user_id,
            v_next_seq,
            'TIMEOUT_ABANDON',
            jsonb_build_object('reason', 'TURN_EXPIRED', 'winner_id', v_opponent_id),
            jsonb_build_object('reason', 'TURN_EXPIRED', 'winner_id', v_opponent_id),
            true, 'timeout_hash', 'timeout_' || v_expired_session.id::text || '_' || EXTRACT(EPOCH FROM NOW())::text, NOW()
          );
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
      END IF;
    END IF;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_secure(UUID, TEXT) TO authenticated, service_role, anon;
GRANT EXECUTE ON FUNCTION public.process_expired_turns() TO service_role, authenticated, anon;
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 118: 118_fix_2fa_totp_bytea_cast.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ============================================================================
-- MIGRACIÓN 118: CORRECCIÓN DEFINITIVA DE CASTING EN 2FA (set_byte / get_byte)
-- ============================================================================
-- Problema: "function set_byte(bytea, integer, bigint) does not exist"
-- Causa: PostgreSQL exige estrictamente que el 3er parámetro de set_byte sea INTEGER.
--        En base32_decode y generación TOTP, operaciones sobre variables BIGINT
--        o expresiones sin casteo explícito producían BIGINT al pasarse a set_byte.
-- Solución: Reemplazo de funciones con casting explícito ::INTEGER y eliminación de ambigüedades.
-- ============================================================================

-- 1. Función canónica y blindada para generar secreto TOTP (Base32)
CREATE OR REPLACE FUNCTION public.generate_2fa_secret(secret_length INTEGER DEFAULT 20)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_bytes BYTEA;
    v_result TEXT := '';
    v_base32 TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    i INTEGER;
    v_val INTEGER;
BEGIN
    -- Generar bytes aleatorios criptográficamente seguros
    v_bytes := gen_random_bytes(secret_length);
    
    FOR i IN 0..(secret_length - 1) LOOP
        -- ✅ CORRECCIÓN CRÍTICA: 
        -- get_byte devuelve INTEGER. La operación bitwise (& 31) mantiene el tipo INTEGER.
        -- Se evita CUALQUIER uso implícito de ::bigint, numeric o funciones como floor() sin castear.
        v_val := get_byte(v_bytes, i) & 31;
        v_result := v_result || substr(v_base32, v_val + 1, 1);
    END LOOP;
    
    RETURN v_result;
END;
$$;

-- 2. Corrección blindada de base32_decode (elimina set_byte(bytea, integer, bigint))
CREATE OR REPLACE FUNCTION public.base32_decode(p_base32 TEXT)
RETURNS BYTEA
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $$
DECLARE
  v_clean TEXT := upper(regexp_replace(p_base32, '[=\s]', '', 'g'));
  v_len INT := length(v_clean);
  v_alpha TEXT := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_bytea BYTEA := '\x'::bytea;
  v_buffer BIGINT := 0;
  v_bits INT := 0;
  v_i INT;
  v_char CHAR;
  v_val INT;
BEGIN
  FOR v_i IN 1..v_len LOOP
    v_char := substring(v_clean FROM v_i FOR 1);
    v_val := position(v_char IN v_alpha) - 1;
    IF v_val < 0 THEN
      RAISE EXCEPTION 'INVALID_BASE32_CHAR: Carácter Base32 no válido %', v_char;
    END IF;
    v_buffer := (v_buffer << 5) | v_val;
    v_bits := v_bits + 5;
    IF v_bits >= 8 THEN
      v_bits := v_bits - 8;
      -- ✅ CORRECCIÓN CRÍTICA: Casteo explícito a ::INTEGER para evitar set_byte(bytea, integer, bigint)
      v_bytea := v_bytea || set_byte('\x00'::bytea, 0, (((v_buffer >> v_bits) & 255)::INTEGER));
      v_buffer := v_buffer & ((1 << v_bits) - 1);
    END IF;
  END LOOP;
  RETURN v_bytea;
END;
$$;

-- 3. Corrección blindada de calculate_totp con casteo explícito a INTEGER en todos los set_byte
CREATE OR REPLACE FUNCTION public.calculate_totp(
  p_secret_base32 TEXT,
  p_timestamp TIMESTAMPTZ DEFAULT NOW()
)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $$
DECLARE
  v_secret_bytes BYTEA;
  v_counter BIGINT;
  v_time_bytes BYTEA;
  v_hmac BYTEA;
  v_offset INT;
  v_code_int INT;
BEGIN
  v_secret_bytes := public.base32_decode(p_secret_base32);
  v_counter := floor(extract(epoch from p_timestamp) / 30)::BIGINT;

  v_time_bytes := set_byte('\x0000000000000000'::bytea, 0, (((v_counter >> 56) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 1, (((v_counter >> 48) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 2, (((v_counter >> 40) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 3, (((v_counter >> 32) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 4, (((v_counter >> 24) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 5, (((v_counter >> 16) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 6, (((v_counter >> 8) & 255)::INTEGER));
  v_time_bytes := set_byte(v_time_bytes, 7, ((v_counter & 255)::INTEGER));

  v_hmac := public.hmac(v_time_bytes, v_secret_bytes, 'sha1'::TEXT);
  v_offset := get_byte(v_hmac, 19) & 15;
  v_code_int := ((get_byte(v_hmac, v_offset) & 127) << 24)
              | ((get_byte(v_hmac, v_offset + 1) & 255) << 16)
              | ((get_byte(v_hmac, v_offset + 2) & 255) << 8)
              | (get_byte(v_hmac, v_offset + 3) & 255);

  RETURN lpad((v_code_int % 1000000)::text, 6, '0');
END;
$$;

-- 4. Gestión de Permisos (Principio de Menor Privilegio)
REVOKE EXECUTE ON FUNCTION public.generate_2fa_secret(INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.generate_2fa_secret(INTEGER) TO authenticated;
GRANT EXECUTE ON FUNCTION public.generate_2fa_secret(INTEGER) TO service_role;

GRANT EXECUTE ON FUNCTION public.base32_decode(TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.calculate_totp(TEXT, TIMESTAMPTZ) TO authenticated, anon, service_role;

-- 5. Forzar recarga de caché de PostgREST para aplicar los cambios inmediatamente
NOTIFY pgrst, 'reload schema';

