  EXCEPTION WHEN duplicate_object THEN NULL; END;
  
  BEGIN
    ALTER TYPE public.game_type_enum ADD VALUE 'tictactoe';
  EXCEPTION WHEN duplicate_object THEN NULL; END;
  
  BEGIN
    ALTER TYPE public.game_type_enum ADD VALUE 'rps';
  EXCEPTION WHEN duplicate_object THEN NULL; END;
  
