    IF NOT EXISTS (
        SELECT 1 FROM pg_enum 
        WHERE enumlabel = 'WAITING' 
        AND enumtypid = 'public.table_status_enum'::regtype
    ) THEN
        ALTER TYPE public.table_status_enum ADD VALUE 'WAITING';
