-- ==============================================================================
-- MIGRACIÓN 140: BLINDAJE DE SEGURIDAD INTEGRAL Y MITIGACIONES CRÍTICAS
-- Proyecto: RASPANDO LA OLLA 🇻🇪 (PulsoPLAY)
-- Estado: PRODUCCIÓN / EJECUTAR EN SUPABASE SQL EDITOR
-- ==============================================================================

-- 1. BLINDAJE DE RATE LIMITING EN draw_next_bingo_ball_client (Vulnerabilidad #1)
-- Evita manipulación de frecuencia por clientes o daemons de bingo maliciosos.
CREATE OR REPLACE FUNCTION public.draw_next_bingo_ball_client(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_host_id UUID;
  v_table_id UUID;
  v_status TEXT;
  v_last_draw TIMESTAMPTZ;
  v_min_interval INTERVAL := INTERVAL '2 seconds';
  v_result JSONB;
BEGIN
  -- 1. Verificar anfitrión de la mesa o admin
  SELECT gs.table_id, gt.host_user_id, gs.status::text INTO v_table_id, v_host_id, v_status
  FROM public.game_sessions gs
  JOIN public.game_tables gt ON gs.table_id = gt.id
  WHERE gs.id = p_session_id;

  IF v_table_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sesión de juego no encontrada.');
  END IF;

  IF v_host_id IS NULL OR (v_host_id != auth.uid() AND NOT public.is_admin(auth.uid())) THEN
    RETURN jsonb_build_object('success', false, 'message', 'No autorizado para extraer balotas.');
  END IF;

  IF UPPER(COALESCE(v_status, '')) != 'DRAWING' THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'El sorteo no está en estado activo de extracción (Estado: ' || COALESCE(v_status, 'NULL') || ').'
    );
  END IF;

  -- 2. Validar intervalo estricto entre extracciones (mínimo 2 segundos)
  SELECT created_at INTO v_last_draw
  FROM public.game_actions
  WHERE session_id = p_session_id
    AND action_type = 'DRAW_BALL'
  ORDER BY sequence_number DESC, created_at DESC
  LIMIT 1;

  IF v_last_draw IS NOT NULL AND (NOW() - v_last_draw) < v_min_interval THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'TOO_FAST',
      'message', 'Debe esperar al menos 2 segundos entre extracciones de balota.'
    );
  END IF;

  -- 3. Llamar de forma segura al motor server-authoritative
  BEGIN
    SELECT public.server_bingo_operation('draw_ball', p_session_id, auth.uid()) INTO v_result;
    RETURN v_result;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%BINGO_COMPLETE%' THEN
      RETURN jsonb_build_object(
        'success', false,
        'game_over', true,
        'reason', 'BINGO_COMPLETE',
        'message', 'Todas las balotas han sido extraídas exitosamente.'
      );
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'message', 'Error en extracción de balota: ' || SQLERRM
      );
    END IF;
  END;
END;
$$;


-- 2. REFUERZO DE INMUTABILIDAD DEL LIBRO MAYOR CONTABLE (Vulnerabilidad #2)
-- Garantiza que source_type y todas las columnas contables sean estrictamente inmutables.
CREATE OR REPLACE FUNCTION public.enforce_ledger_immutability()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  -- Solo se permite purga administrativa de registros etiquetados como TEST_BONUS ejecutada por el sistema
  IF TG_OP = 'DELETE' AND OLD.source_type = 'TEST_BONUS' THEN
    IF NOT public.is_admin(auth.uid()) AND current_user != 'postgres' THEN
      RAISE EXCEPTION 'NO_AUTORIZADO: Solo un administrador puede depurar registros de prueba.';
    END IF;
    RETURN OLD;
  END IF;

  RAISE EXCEPTION 'LEDGER_IMMUTABLE_VIOLATION: El libro mayor contable es estrictamente inmutable. No se permite UPDATE ni DELETE.';
END;
$$;

DROP TRIGGER IF EXISTS trg_ledger_prevent_modification ON public.ledger_entries;
CREATE TRIGGER trg_ledger_prevent_modification
  BEFORE UPDATE OR DELETE ON public.ledger_entries
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_ledger_immutability();


-- 3. BLINDAJE DE CONCURRENCIA EN INSCRIPCIÓN DE TORNEOS (Vulnerabilidad #3)
-- Bloquea con FOR UPDATE tanto la fila del torneo como la billetera del usuario.
CREATE OR REPLACE FUNCTION public.register_for_tournament(p_tournament_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_tournament RECORD;
  v_entry_fee NUMERIC;
  v_wallet_id UUID;
  v_available NUMERIC(14,2);
  v_current_registrations INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NO_AUTENTICADO';
  END IF;

  -- 1. Bloquear la fila del torneo para evitar sobrecupo concurrente
  SELECT * INTO v_tournament 
  FROM public.tournaments 
  WHERE id = p_tournament_id
  FOR UPDATE;
  
  IF v_tournament IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Torneo no encontrado.');
  END IF;

  IF v_tournament.status != 'REGISTRATION' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Las inscripciones no están abiertas.');
  END IF;

  IF NOW() > v_tournament.registration_deadline THEN
    RETURN jsonb_build_object('success', false, 'message', 'El plazo de inscripción ha vencido.');
  END IF;

  SELECT COUNT(*) INTO v_current_registrations
  FROM public.tournament_registrations
  WHERE tournament_id = p_tournament_id;

  IF v_current_registrations >= v_tournament.max_participants THEN
    RETURN jsonb_build_object('success', false, 'message', 'El torneo ya alcanzó su capacidad máxima de participantes.');
  END IF;

  -- Verificar si el usuario ya está inscrito
  IF EXISTS (
    SELECT 1 FROM public.tournament_registrations 
    WHERE tournament_id = p_tournament_id AND user_id = v_user_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ya estás registrado en este torneo.');
  END IF;

  -- 2. Cobrar entrada con bloqueo serial de billetera
  v_entry_fee := COALESCE(v_tournament.entry_fee, 0);
  IF v_entry_fee > 0 THEN
    SELECT id, available_balance INTO v_wallet_id, v_available
    FROM public.wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF v_wallet_id IS NULL OR v_available < v_entry_fee THEN
      RETURN jsonb_build_object(
        'success', false, 
        'message', 'Saldo insuficiente en billetera para cubrir la entrada (' || v_entry_fee || ' Bs).'
      );
    END IF;

    UPDATE public.wallets
    SET available_balance = available_balance - v_entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    -- Asentar debito en ledger_entries
    BEGIN
      INSERT INTO public.ledger_entries (
        wallet_id, user_id, entry_type, direction, amount, 
        balance_after_available, balance_after_held, 
        reference_table, reference_id, idempotency_key, description
      ) VALUES (
        v_wallet_id, v_user_id, 'GAME_ENTRY_HOLD'::ledger_entry_type_enum, 'DEBIT'::ledger_direction_enum, v_entry_fee,
        (v_available - v_entry_fee), 0.00,
        'tournaments', p_tournament_id, 'tourn_reg_' || p_tournament_id::text || '_' || v_user_id::text,
        'Inscripción al Torneo: ' || v_tournament.name
      );
    EXCEPTION WHEN OTHERS THEN
      -- Compatibilidad con variaciones en schema de ledger_entries
      NULL;
    END;
  END IF;

  -- 3. Registrar al participante
  INSERT INTO public.tournament_registrations (tournament_id, user_id, status)
  VALUES (p_tournament_id, v_user_id, 'REGISTERED');

  UPDATE public.tournaments
  SET current_participants = v_current_registrations + 1,
      updated_at = NOW()
  WHERE id = p_tournament_id;

  RETURN jsonb_build_object('success', true, 'message', 'Inscripción confirmada exitosamente.');
END;
$$;


-- 4. REEMBOLSOS AUTOMÁTICOS EN CANCELACIÓN DE TORNEOS (Vulnerabilidad #7)
-- Reintegra automáticamente la cuota a cada usuario registrado al cancelar un torneo.
CREATE OR REPLACE FUNCTION public.cancel_tournament_with_refund(p_tournament_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_tournament RECORD;
  v_reg RECORD;
  v_entry_fee NUMERIC;
  v_refunded_count INT := 0;
  v_wallet_id UUID;
  v_cur_balance NUMERIC;
BEGIN
  -- Solo administradores pueden cancelar torneos
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'NO_AUTORIZADO: Solo un administrador puede cancelar torneos.';
  END IF;

  SELECT * INTO v_tournament 
  FROM public.tournaments 
  WHERE id = p_tournament_id
  FOR UPDATE;

  IF v_tournament IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Torneo no encontrado.');
  END IF;

  IF v_tournament.status = 'CANCELLED' THEN
    RETURN jsonb_build_object('success', false, 'message', 'El torneo ya se encuentra cancelado.');
  END IF;

  v_entry_fee := COALESCE(v_tournament.entry_fee, 0);

  -- Si el torneo tenía cuota de entrada, reembolsar a cada participante inscrito
  IF v_entry_fee > 0 THEN
    FOR v_reg IN 
      SELECT id, user_id 
      FROM public.tournament_registrations
      WHERE tournament_id = p_tournament_id 
        AND status IN ('REGISTERED', 'CONFIRMED')
    LOOP
      -- Bloquear billetera para acreditación segura
      SELECT id, available_balance INTO v_wallet_id, v_cur_balance
      FROM public.wallets
      WHERE user_id = v_reg.user_id
      FOR UPDATE;

      IF v_wallet_id IS NOT NULL THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_entry_fee,
            updated_at = NOW()
        WHERE id = v_wallet_id;

        -- Registrar asiento de reembolso en libro mayor
        BEGIN
          INSERT INTO public.ledger_entries (
            wallet_id, user_id, entry_type, direction, amount,
            balance_after_available, balance_after_held,
            reference_table, reference_id, idempotency_key, description
          ) VALUES (
            v_wallet_id, v_reg.user_id, 'PRIZE_PAYOUT'::ledger_entry_type_enum, 'CREDIT'::ledger_direction_enum, v_entry_fee,
            (v_cur_balance + v_entry_fee), 0.00,
            'tournaments', p_tournament_id, 'tourn_ref_' || p_tournament_id::text || '_' || v_reg.user_id::text,
            'Reembolso por cancelación de Torneo: ' || v_tournament.name
          );
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;

        v_refunded_count := v_refunded_count + 1;
      END IF;

      -- Marcar registro como reembolsado
      UPDATE public.tournament_registrations
      SET status = 'REFUNDED'
      WHERE id = v_reg.id;
    END LOOP;
  END IF;

  -- Actualizar estado del torneo a CANCELLED
  UPDATE public.tournaments
  SET status = 'CANCELLED',
      updated_at = NOW()
  WHERE id = p_tournament_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Torneo cancelado exitosamente.',
    'refunded_participants', v_refunded_count,
    'refund_amount_per_user', v_entry_fee
  );
END;
$$;

-- Integrar el reembolso automático en update_tournament_status
CREATE OR REPLACE FUNCTION public.update_tournament_status(
  p_tournament_id UUID,
  p_status TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'NO_AUTORIZADO: Se requieren privilegios de administrador.';
  END IF;

  IF UPPER(p_status) = 'CANCELLED' THEN
    RETURN public.cancel_tournament_with_refund(p_tournament_id);
  END IF;

  UPDATE public.tournaments
  SET status = p_status, updated_at = NOW()
  WHERE id = p_tournament_id;

  RETURN jsonb_build_object('success', true, 'message', 'Estado actualizado a ' || p_status);
END;
$$;


-- 5. RATE LIMITING EN ACCIONES DE JUEGO EN VIVO (Vulnerabilidad #9)
-- Protege submit_game_action_secure contra bombardeo o inundación de acciones.
CREATE OR REPLACE FUNCTION public.submit_game_action_secure(
  p_session_id UUID,
  p_action_type VARCHAR(50),
  p_payload JSONB DEFAULT '{}'::jsonb,
  p_idempotency_key VARCHAR(100) DEFAULT NULL,
  p_server_state_hash VARCHAR(64) DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_effective_idempotency VARCHAR(100);
  v_next_seq INT;
  v_action_id UUID;
  v_existing_action RECORD;
  v_recent_actions INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para registrar una jugada';
  END IF;

  -- Control de frecuencia: máximo 30 acciones por minuto por usuario en la sesión
  SELECT COUNT(*) INTO v_recent_actions
  FROM public.game_actions
  WHERE session_id = p_session_id
    AND user_id = v_user_id
    AND created_at > (NOW() - INTERVAL '60 seconds');

  IF v_recent_actions >= 30 THEN
    RETURN jsonb_build_object(
      'success', false,
      'reason', 'RATE_LIMIT_EXCEEDED',
      'message', 'Demasiados movimientos registrados en poco tiempo. Por favor espera unos segundos.'
    );
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'act_' || p_session_id::text || '_' || v_user_id::text || '_' || extract(epoch from now())::text
  );

  -- 1. Verificar idempotencia
  SELECT id, sequence_number INTO v_existing_action
  FROM public.game_actions
  WHERE idempotency_key = v_effective_idempotency;

  IF v_existing_action.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'action_id', v_existing_action.id,
      'sequence_number', v_existing_action.sequence_number,
      'is_duplicate', true
    );
  END IF;

  -- 2. Incrementar secuencia atómica por sesión
  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_next_seq
  FROM public.game_actions
  WHERE session_id = p_session_id;

  -- 3. Registrar la acción
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    action_type,
    payload,
    server_state_hash,
    idempotency_key,
    sequence_number,
    created_at
  ) VALUES (
    p_session_id,
    v_user_id,
    p_action_type,
    p_payload,
    p_server_state_hash,
    v_effective_idempotency,
    v_next_seq,
    NOW()
  )
  RETURNING id INTO v_action_id;

  RETURN jsonb_build_object(
    'success', true,
    'action_id', v_action_id,
    'sequence_number', v_next_seq
  );
END;
$$;


-- 6. LIMPIEZA DE DESCONEXIONES EN PARTIDAS (Vulnerabilidad #10)
CREATE OR REPLACE FUNCTION public.cleanup_disconnected_players()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cleaned INT := 0;
BEGIN
  -- Marcar como LEFT a jugadores en partidas activas cuyo perfil no registre actividad reciente (> 60 seg)
  UPDATE public.game_table_players gtp
  SET status = 'LEFT'
  FROM public.profiles p
  WHERE gtp.user_id = p.user_id
    AND gtp.status = 'PLAYING'
    AND p.last_seen_at < (NOW() - INTERVAL '60 seconds');

  GET DIAGNOSTICS v_cleaned = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'cleaned_players', v_cleaned);
END;
$$;


-- 7. OTORGAR PERMISOS Y RECARGAR SCHEMA
GRANT EXECUTE ON FUNCTION public.draw_next_bingo_ball_client(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.register_for_tournament(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.cancel_tournament_with_refund(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_tournament_status(UUID, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.submit_game_action_secure(UUID, VARCHAR, JSONB, VARCHAR, VARCHAR) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.cleanup_disconnected_players() TO authenticated;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 144: 141_fix_rps_pgcrypto_commit_reveal.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 141: RESOLUCIÓN DEFINITIVA DE PGCRYPTO, GEN_RANDOM_BYTES Y COMMIT-REVEAL RPS
-- Proyecto: RASPANDO LA OLLA 🇻🇪 (PulsoPLAY)
-- Estado: PRODUCCIÓN / CRÍTICO
-- ==============================================================================
-- Causa Raíz Identificada:
-- 1. En Supabase/PostgreSQL, la extensión pgcrypto se aloja en el esquema 'extensions'.
-- 2. La función submit_rps_choice_secure fue declarada con "SET search_path = public, auth".
-- 3. Al no incluir 'extensions' en el search_path, cualquier llamada a gen_random_bytes(32)
--    fallaba con el error: "function gen_random_bytes(integer) does not exist".
-- 4. Además, el valor por defecto de server_seed en game_session_secrets invocaba
--    gen_random_bytes(32) sin calificación de esquema.
--
-- Solución Centralizada y Blindada:
-- 1. Asegurar extensión pgcrypto de forma idempotente.
-- 2. Crear una función de enlace público public.gen_random_bytes(integer) que delegue
--    a extensions.gen_random_bytes(integer) si existe en 'extensions' y no en 'public'.
--    Esto garantiza que CUALQUIER función en la base de datos que opere bajo
--    search_path = public resuelva gen_random_bytes sin error.
-- 3. Actualizar el search_path de submit_rps_choice_secure, next_rps_round_secure
--    y process_expired_turns a: "public, extensions, auth".
-- 4. Cualificar explícitamente las llamadas a extensions.gen_random_bytes(...)
--    en la inicialización de server_seed y en el default de la tabla game_session_secrets.
-- 5. Preservar la arquitectura Commit-Reveal simultánea de RPS con current_turn_user_id = NULL.
-- ==============================================================================

-- 1. Asegurar que la extensión pgcrypto esté habilitada
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 2. Puente Centralizado de Esquema para gen_random_bytes
-- Si pgcrypto reside en 'extensions' y no en 'public', creamos una función envoltorio en 'public'
-- para compatibilidad universal con todas las RPCs existentes que usen search_path=public.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'gen_random_bytes'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'extensions' AND p.proname = 'gen_random_bytes'
    ) THEN
      CREATE OR REPLACE FUNCTION public.gen_random_bytes(p_len integer)
      RETURNS bytea
      LANGUAGE sql
      PARALLEL SAFE
      STABLE
      AS $fn$ SELECT extensions.gen_random_bytes(p_len) $fn$;
      
      GRANT EXECUTE ON FUNCTION public.gen_random_bytes(integer) TO authenticated, anon, service_role, postgres;
    END IF;
  END IF;
END $$;

-- 3. Asegurar estructura y default blindado de game_session_secrets
CREATE TABLE IF NOT EXISTS public.game_session_secrets (
  session_id UUID PRIMARY KEY REFERENCES public.game_sessions(id) ON DELETE CASCADE,
  secret_state JSONB NOT NULL DEFAULT '{}'::jsonb,
  server_seed VARCHAR(64) NOT NULL DEFAULT encode(extensions.gen_random_bytes(32), 'hex'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Actualizar el DEFAULT de server_seed para garantizar resolución en cualquier contexto
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_session_secrets' AND column_name = 'server_seed'
  ) THEN
    BEGIN
      ALTER TABLE public.game_session_secrets 
      ALTER COLUMN server_seed SET DEFAULT encode(extensions.gen_random_bytes(32), 'hex');
    EXCEPTION WHEN OTHERS THEN
      ALTER TABLE public.game_session_secrets 
      ALTER COLUMN server_seed SET DEFAULT encode(public.gen_random_bytes(32), 'hex');
    END;
  END IF;
END $$;

-- ==============================================================================
-- 4. RPC: SUBMIT_RPS_CHOICE_SECURE (BLINDADA CON SEARCH_PATH Y RESOLUCIÓN PGCRYPTO)
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.submit_rps_choice_secure(
  p_session_id UUID,
  p_choice VARCHAR(20)
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_user_id UUID;
  v_norm_choice VARCHAR(20);
  v_session RECORD;
  v_secret_row RECORD;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_secret_choices JSONB;
  v_c1 TEXT;
  v_c2 TEXT;
  v_round_winner TEXT;
  v_round_winner_user_id UUID;
  v_match_winner TEXT;
  v_winner_user_id UUID;
  v_is_game_over BOOLEAN := false;
  v_p1_lives INT;
  v_p2_lives INT;
  v_curr_round INT;
  v_history_entry JSONB;
  v_new_history JSONB;
  v_new_state JSONB;
  v_player_choices JSONB;
  v_generated_seed VARCHAR(64);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'AUTH_REQUIRED: Debes iniciar sesión');
  END IF;

  v_norm_choice := UPPER(TRIM(p_choice));
  IF v_norm_choice NOT IN ('ROCK', 'PAPER', 'SCISSORS') THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_CHOICE: La jugada debe ser ROCK, PAPER o SCISSORS');
  END IF;

  -- 1. Bloquear la sesión para evitar condiciones de carrera concurrentes
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  -- 2. Asegurar o bloquear registro en game_session_secrets
  SELECT * INTO v_secret_row
  FROM public.game_session_secrets
  WHERE session_id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Generación de semilla aleatoria segura con resolución blindada
    BEGIN
      v_generated_seed := encode(extensions.gen_random_bytes(32), 'hex');
    EXCEPTION WHEN OTHERS THEN
      v_generated_seed := encode(public.gen_random_bytes(32), 'hex');
    END;

    INSERT INTO public.game_session_secrets (session_id, secret_state, server_seed)
    VALUES (p_session_id, '{}'::jsonb, v_generated_seed)
    RETURNING * INTO v_secret_row;
  END IF;

  -- 3. Identificar Jugadores 1 y 2
  v_p1_id := COALESCE(
    v_session.current_state->>'player1Id',
    (SELECT user_id::text FROM public.game_table_players WHERE table_id = v_session.table_id ORDER BY seat_number ASC, created_at ASC LIMIT 1)
  );
  v_p2_id := COALESCE(
    v_session.current_state->>'player2Id',
    (SELECT user_id::text FROM public.game_table_players WHERE table_id = v_session.table_id AND user_id::text != v_p1_id LIMIT 1)
  );

  IF v_user_id::text != v_p1_id AND v_user_id::text != v_p2_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_A_PLAYER_IN_THIS_MATCH');
  END IF;

  -- Validar fase de compromiso
  IF COALESCE(v_session.current_state->>'status', 'ROUND_COMMIT') NOT IN ('ROUND_COMMIT', 'selecting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ROUND_NOT_ACCEPTING_CHOICES');
  END IF;

  -- 4. Validar si el jugador ya eligió en esta ronda (Anti-double submit e idempotencia estricta)
  v_secret_choices := COALESCE(v_secret_row.secret_state->'rps_choices', '{}'::jsonb);
  IF (v_secret_choices ? v_user_id::text AND v_secret_choices->>v_user_id::text IS NOT NULL) OR
     (COALESCE((v_session.current_state->'playerChoices'->(v_user_id::text)->>'committed')::boolean, false) IS TRUE) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'ALREADY_COMMITTED',
      'message', 'Ya has enviado tu jugada para esta ronda'
    );
  END IF;

  -- 5. Guardar la jugada privada en game_session_secrets
  v_secret_choices := jsonb_set(v_secret_choices, ARRAY[v_user_id::text], to_jsonb(v_norm_choice));

  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(secret_state, '{rps_choices}', v_secret_choices),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  -- 6. Verificar si ambos jugadores ya han completado su compromiso
  v_c1 := v_secret_choices->>v_p1_id;
  v_c2 := v_secret_choices->>v_p2_id;

  IF v_c1 IS NOT NULL AND v_c2 IS NOT NULL THEN
    -- =========================================================================
    -- ¡AMBOS JUGADORES HAN ELEGIDO! REVELACIÓN SIMULTÁNEA Y CÁLCULO DE RESULTADO
    -- =========================================================================
    IF v_c1 = v_c2 THEN
      v_round_winner := 'DRAW';
      v_round_winner_user_id := NULL;
    ELSIF (v_c1 = 'ROCK' AND v_c2 = 'SCISSORS') OR
          (v_c1 = 'PAPER' AND v_c2 = 'ROCK') OR
          (v_c1 = 'SCISSORS' AND v_c2 = 'PAPER') THEN
      v_round_winner := 'PLAYER1';
      v_round_winner_user_id := v_p1_id::uuid;
    ELSE
      v_round_winner := 'PLAYER2';
      v_round_winner_user_id := v_p2_id::uuid;
    END IF;

    -- Vidas
    v_p1_lives := COALESCE((v_session.current_state->>'player1Lives')::int, 3);
    v_p2_lives := COALESCE((v_session.current_state->>'player2Lives')::int, 3);

    IF v_round_winner = 'PLAYER1' THEN
      v_p2_lives := GREATEST(0, v_p2_lives - 1);
    ELSIF v_round_winner = 'PLAYER2' THEN
      v_p1_lives := GREATEST(0, v_p1_lives - 1);
    END IF;

    -- Fin de partida
    IF v_p1_lives <= 0 THEN
      v_match_winner := 'PLAYER2';
      v_winner_user_id := v_p2_id::uuid;
      v_is_game_over := true;
    ELSIF v_p2_lives <= 0 THEN
      v_match_winner := 'PLAYER1';
      v_winner_user_id := v_p1_id::uuid;
      v_is_game_over := true;
    ELSE
      v_match_winner := NULL;
      v_winner_user_id := NULL;
      v_is_game_over := false;
    END IF;

    v_curr_round := COALESCE((v_session.current_state->>'roundNumber')::int, (v_session.current_state->>'round')::int, 1);

    v_history_entry := jsonb_build_object(
      'roundNumber', v_curr_round,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'winner', v_round_winner,
      'winnerUserId', v_round_winner_user_id,
      'timestamp', FLOOR(EXTRACT(EPOCH FROM NOW()) * 1000)
    );

    v_new_history := COALESCE(v_session.current_state->'history', '[]'::jsonb) || v_history_entry;

    v_new_state := v_session.current_state;
    v_new_state := jsonb_set(v_new_state, '{player1Choice}', to_jsonb(v_c1));
    v_new_state := jsonb_set(v_new_state, '{player2Choice}', to_jsonb(v_c2));
    v_new_state := jsonb_set(v_new_state, '{player1Lives}', to_jsonb(v_p1_lives));
    v_new_state := jsonb_set(v_new_state, '{player2Lives}', to_jsonb(v_p2_lives));
    v_new_state := jsonb_set(v_new_state, '{lives}', jsonb_build_object(v_p1_id, v_p1_lives, v_p2_id, v_p2_lives));
    v_new_state := jsonb_set(v_new_state, '{roundWinner}', to_jsonb(v_round_winner));
    v_new_state := jsonb_set(v_new_state, '{roundWinnerUserId}', to_jsonb(v_round_winner_user_id));
    v_new_state := jsonb_set(v_new_state, '{matchWinner}', to_jsonb(v_match_winner));
    v_new_state := jsonb_set(v_new_state, '{winnerUserId}', to_jsonb(v_winner_user_id));
    v_new_state := jsonb_set(v_new_state, '{status}', to_jsonb(CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END));
    v_new_state := jsonb_set(v_new_state, '{phase}', to_jsonb(CASE WHEN v_is_game_over THEN 'match_ended' ELSE 'round_result' END));
    v_new_state := jsonb_set(v_new_state, '{history}', v_new_history);
    v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{playerChoices}', jsonb_build_object(
      v_p1_id, jsonb_build_object('committed', true, 'choice', v_c1),
      v_p2_id, jsonb_build_object('committed', true, 'choice', v_c2)
    ));

    -- Actualizar sesión pública: current_turn_user_id permanece NULL para RPS
    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        status = CASE WHEN v_is_game_over THEN 'FINISHED'::session_status_enum ELSE 'ACTIVE'::session_status_enum END,
        winner_user_id = v_winner_user_id,
        turn_expires_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        turn_deadline_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        ended_at = CASE WHEN v_is_game_over THEN NOW() ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Si el match terminó, cerrar la mesa asociada
    IF v_is_game_over THEN
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          updated_at = NOW()
      WHERE id = v_session.table_id;
    END IF;

    -- Limpiar elecciones secretas para la próxima ronda
    UPDATE public.game_session_secrets
    SET secret_state = jsonb_set(secret_state, '{rps_choices}', '{}'::jsonb),
        updated_at = NOW()
    WHERE session_id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'isGameOver', v_is_game_over,
      'winnerUserId', v_winner_user_id,
      'roundWinner', v_round_winner,
      'roundWinnerUserId', v_round_winner_user_id,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'bothChosen', true
    );

  ELSE
    -- =========================================================================
    -- SOLO UNO HA ELEGIDO: REGISTRAR COMMIT PROTEGIENDO EL SECRETO
    -- =========================================================================
    v_player_choices := COALESCE(v_session.current_state->'playerChoices', '{}'::jsonb);
    v_player_choices := jsonb_set(
      v_player_choices,
      ARRAY[v_user_id::text],
      jsonb_build_object('committed', true)
    );

    v_new_state := v_session.current_state;
    v_new_state := jsonb_set(v_new_state, '{playerChoices}', v_player_choices);
    v_new_state := jsonb_set(v_new_state, '{player1Choice}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{player2Choice}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{status}', '"ROUND_COMMIT"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{phase}', '"selecting"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', 'ROUND_COMMIT',
      'isGameOver', false,
      'bothChosen', false,
      'committed', true
    );
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) TO authenticated, anon, service_role;

-- ==============================================================================
-- 5. RPC: NEXT_RPS_ROUND_SECURE (REINICIO ATÓMICO CON SEARCH_PATH EXTENSIONS)
-- ==============================================================================
CREATE OR REPLACE FUNCTION public.next_rps_round_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_session RECORD;
  v_curr_round INT;
  v_new_round INT;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_new_state JSONB;
BEGIN
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  -- Solo avanzar si estaba en fase de resultado de ronda
  IF COALESCE(v_session.current_state->>'status', '') != 'ROUND_REVEAL' AND
     COALESCE(v_session.current_state->>'phase', '') != 'round_result' THEN
    RETURN jsonb_build_object('success', true, 'message', 'ALREADY_ADVANCED');
  END IF;

  v_curr_round := COALESCE((v_session.current_state->>'roundNumber')::int, (v_session.current_state->>'round')::int, 1);
  v_new_round := v_curr_round + 1;

  v_p1_id := COALESCE(v_session.current_state->>'player1Id', '');
  v_p2_id := COALESCE(v_session.current_state->>'player2Id', '');

  v_new_state := v_session.current_state;
  v_new_state := jsonb_set(v_new_state, '{roundNumber}', to_jsonb(v_new_round));
  v_new_state := jsonb_set(v_new_state, '{round}', to_jsonb(v_new_round));
  v_new_state := jsonb_set(v_new_state, '{player1Choice}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{player2Choice}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{roundWinner}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{roundWinnerUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{status}', '"ROUND_COMMIT"'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{phase}', '"selecting"'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{playerChoices}', jsonb_build_object(
    v_p1_id, jsonb_build_object('committed', false),
    v_p2_id, jsonb_build_object('committed', false)
  ));

  UPDATE public.game_sessions
  SET current_state = v_new_state,
      current_turn_user_id = NULL,
      turn_expires_at = NOW() + INTERVAL '15 seconds',
      turn_deadline_at = NOW() + INTERVAL '15 seconds',
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Limpiar cualquier secreto residual
  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(secret_state, '{rps_choices}', '{}'::jsonb),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  RETURN jsonb_build_object('success', true, 'round', v_new_round);
END;
$$;

GRANT EXECUTE ON FUNCTION public.next_rps_round_secure(UUID) TO authenticated, anon, service_role;

-- ==============================================================================
-- 6. ACTUALIZACIÓN DE PROCESS_EXPIRED_TURNS: ROUND_DEADLINE CON IDEMPOTENCIA
-- ==============================================================================
DROP FUNCTION IF EXISTS public.process_expired_turns();

CREATE OR REPLACE FUNCTION public.process_expired_turns()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_expired_row RECORD;
  v_table RECORD;
  v_p1_id UUID;
  v_p2_id UUID;
  v_p1_committed BOOLEAN;
  v_p2_committed BOOLEAN;
  v_winner_id UUID;
  v_loser_id UUID;
  v_secret_choices JSONB;
  v_idempotency_key VARCHAR(100);
  v_curr_round INT;
BEGIN
  -- ---------------------------------------------------------------------------
  -- A. PROCESAMIENTO DE EXPIRACIONES PARA JUEGOS SECUENCIALES (DOMINÓ, TRUCO, ETC.)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_turn_user_id, t.game_type, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND s.current_turn_user_id IS NOT NULL
      AND t.game_type NOT IN ('rock_paper_scissors', 'rps')
      AND s.turn_expires_at IS NOT NULL
      AND s.turn_expires_at < NOW()
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      -- Clave determinista de idempotencia para timeout secuencial
      v_idempotency_key := 'seq_timeout_' || v_expired_row.id::text || '_' || v_expired_row.current_turn_user_id::text || '_' || EXTRACT(EPOCH FROM v_expired_row.turn_expires_at)::bigint::text;
      
      PERFORM public.record_turn_timeout_secure(
        v_expired_row.id,
        v_expired_row.current_turn_user_id,
        v_idempotency_key
      );
    EXCEPTION WHEN OTHERS THEN
      -- Evitar que una sesión bloquee el bucle daemon
      NULL;
    END;
  END LOOP;

  -- ---------------------------------------------------------------------------
  -- B. PROCESAMIENTO DE ROUND_DEADLINE PARA JUEGOS SIMULTÁNEOS (RPS)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_state, s.created_at, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND t.game_type IN ('rock_paper_scissors', 'rps')
      AND s.turn_expires_at IS NOT NULL
      AND s.turn_expires_at < NOW()
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      SELECT * INTO v_table FROM public.game_tables WHERE id = v_expired_row.table_id;
      
      -- Obtener ronda actual para clave determinista
      v_curr_round := COALESCE((v_expired_row.current_state->>'roundNumber')::int, (v_expired_row.current_state->>'round')::int, 1);
      v_idempotency_key := 'rps_timeout_' || v_expired_row.id::text || '_rnd_' || v_curr_round::text;

      -- Obtener IDs de jugadores
      BEGIN
        v_p1_id := (v_expired_row.current_state->>'player1Id')::uuid;
        v_p2_id := (v_expired_row.current_state->>'player2Id')::uuid;
      EXCEPTION WHEN OTHERS THEN
        v_p1_id := NULL;
        v_p2_id := NULL;
      END;

      IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
        SELECT user_id INTO v_p1_id FROM public.game_table_players WHERE table_id = v_expired_row.table_id ORDER BY seat_number ASC, created_at ASC LIMIT 1;
        SELECT user_id INTO v_p2_id FROM public.game_table_players WHERE table_id = v_expired_row.table_id AND user_id != v_p1_id LIMIT 1;
      END IF;

      -- Verificar compromisos consultando tanto secrets como current_state
      SELECT secret_state->'rps_choices' INTO v_secret_choices
      FROM public.game_session_secrets
      WHERE session_id = v_expired_row.id;

      v_p1_committed := COALESCE((v_expired_row.current_state->'playerChoices'->(v_p1_id::text)->>'committed')::boolean, false)
                        OR (v_secret_choices IS NOT NULL AND v_secret_choices ? v_p1_id::text);
      v_p2_committed := COALESCE((v_expired_row.current_state->'playerChoices'->(v_p2_id::text)->>'committed')::boolean, false)
                        OR (v_secret_choices IS NOT NULL AND v_secret_choices ? v_p2_id::text);

      IF v_p1_committed AND NOT v_p2_committed THEN
        -- Jugador 1 jugó a tiempo; Jugador 2 agotó su tiempo (abandono/timeout de ronda)
        v_winner_id := v_p1_id;
        v_loser_id := v_p2_id;

        UPDATE public.game_sessions
        SET status = 'FINISHED'::session_status_enum,
            winner_user_id = v_winner_id,
            ended_at = NOW(),
            current_state = jsonb_set(
              jsonb_set(current_state, '{winnerUserId}', to_jsonb(v_winner_id)),
              '{abandonedBy}', to_jsonb(v_loser_id)
            ),
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_row.table_id;

        -- Liquidación autoritativa e idempotente mediante settle_game_session
        PERFORM public.settle_game_session(
          v_expired_row.id,
          ARRAY[v_winner_id]::uuid[],
          'ROUND_TIMEOUT_FORFEIT',
          v_idempotency_key
        );

      ELSIF v_p2_committed AND NOT v_p1_committed THEN
        -- Jugador 2 jugó a tiempo; Jugador 1 agotó su tiempo (abandono/timeout de ronda)
        v_winner_id := v_p2_id;
        v_loser_id := v_p1_id;

        UPDATE public.game_sessions
        SET status = 'FINISHED'::session_status_enum,
            winner_user_id = v_winner_id,
            ended_at = NOW(),
            current_state = jsonb_set(
              jsonb_set(current_state, '{winnerUserId}', to_jsonb(v_winner_id)),
              '{abandonedBy}', to_jsonb(v_loser_id)
            ),
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_row.table_id;

        -- Liquidación autoritativa e idempotente mediante settle_game_session
        PERFORM public.settle_game_session(
          v_expired_row.id,
          ARRAY[v_winner_id]::uuid[],
          'ROUND_TIMEOUT_FORFEIT',
          v_idempotency_key
        );

      ELSIF NOT v_p1_committed AND NOT v_p2_committed THEN
        -- Ninguno de los dos jugadores envió jugada: cancelar por inactividad y reembolsar entradas
        UPDATE public.game_sessions
        SET status = 'CANCELLED'::session_status_enum,
            ended_at = NOW(),
            current_state = jsonb_set(current_state, '{cancelledReason}', '"DUAL_ROUND_TIMEOUT"'::jsonb),
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_row.table_id;

        -- Liquidación con arreglo de ganadores vacío (provoca reembolso de fondos retenidos en ledger)
        PERFORM public.settle_game_session(
          v_expired_row.id,
          ARRAY[]::uuid[],
          'DUAL_ROUND_TIMEOUT_CANCEL',
          v_idempotency_key
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      -- Evitar que una sesión bloquee el bucle daemon
      NULL;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.process_expired_turns() TO authenticated, anon, service_role, postgres;

COMMENT ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) IS 
'Registra jugadas de Piedra, Papel o Tijera bajo protocolo Commit-Reveal autoritativo en servidor con resolución blindada de pgcrypto en esquema extensions/public.';

COMMENT ON FUNCTION public.process_expired_turns() IS 
'Daemon de expiración de turnos. Discrimina estrictamente entre turnos secuenciales y Round Deadlines simultáneos de RPS con claves de idempotencia deterministas.';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 145: 142_fix_rps_player_resolution_and_secrets.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 142: CORRECCIÓN DEFINITIVA DE RESOLUCIÓN DE JUGADORES EN RPS
-- Y RECONCILIACIÓN ESTRUCTURAL DE TABLAS (GAME_TABLE_PLAYERS / GAME_SESSION_SECRETS)
-- Proyecto: RASPANDO LA OLLA 🇻🇪 / PulsoPLAY
--
-- PROBLEMA IDENTIFICADO:
-- 1. En submit_rps_choice_secure y process_expired_turns se utilizaba la consulta:
--    SELECT user_id FROM public.game_table_players ORDER BY seat_number ASC, created_at ASC;
--    La columna `created_at` NO EXISTE en `game_table_players` (creada en migración 008
--    con la columna canónica `joined_at` y el orden de asientos `seat_number`).
--    Esto provocaba el error en producción: column "created_at" does not exist.
-- 2. Asegura que `public.game_sessions` disponga de la columna `updated_at`.
-- 3. Reconcilia de forma idempotente las columnas de `public.game_session_secrets`
--    (secret_state, server_seed, created_at, updated_at).
-- 4. Preserva el modelo COMMIT-REVEAL simultáneo de RPS (current_turn_user_id = NULL).
-- ==============================================================================

-- 1. ASEGURAR EXTENSIÓN PGCRYPTO Y ENLACE CANÓNICO
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'gen_random_bytes'
  ) THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'extensions' AND p.proname = 'gen_random_bytes'
    ) THEN
      CREATE OR REPLACE FUNCTION public.gen_random_bytes(p_count integer)
      RETURNS bytea
      LANGUAGE sql
      SECURITY DEFINER
      SET search_path = extensions, public
      AS $func$
        SELECT extensions.gen_random_bytes(p_count);
      $func$;

      GRANT EXECUTE ON FUNCTION public.gen_random_bytes(integer) TO authenticated, anon, service_role, postgres;
    END IF;
  END IF;
END $$;

-- 2. RECONCILIACIÓN ESTRUCTURAL IDEMPOTENTE DE GAME_SESSIONS
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_sessions' AND column_name = 'updated_at'
  ) THEN
    ALTER TABLE public.game_sessions ADD COLUMN updated_at TIMESTAMPTZ DEFAULT NOW();
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_sessions' AND column_name = 'turn_expires_at'
  ) THEN
    ALTER TABLE public.game_sessions ADD COLUMN turn_expires_at TIMESTAMPTZ NULL;
  END IF;
END $$;

-- 3. RECONCILIACIÓN ESTRUCTURAL IDEMPOTENTE DE GAME_SESSION_SECRETS
DO $$
BEGIN
  -- Asegurar tabla base si no existiera
  CREATE TABLE IF NOT EXISTS public.game_session_secrets (
    session_id UUID PRIMARY KEY REFERENCES public.game_sessions(id) ON DELETE CASCADE,
    secret_state JSONB NOT NULL DEFAULT '{}'::jsonb,
    server_seed VARCHAR(64) NOT NULL DEFAULT encode(extensions.gen_random_bytes(32), 'hex'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );

  -- Asegurar columnas si la tabla fue creada por migraciones históricas previas
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_session_secrets' AND column_name = 'secret_state'
  ) THEN
    ALTER TABLE public.game_session_secrets ADD COLUMN secret_state JSONB NOT NULL DEFAULT '{}'::jsonb;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_session_secrets' AND column_name = 'server_seed'
  ) THEN
    ALTER TABLE public.game_session_secrets ADD COLUMN server_seed VARCHAR(64) NOT NULL DEFAULT encode(extensions.gen_random_bytes(32), 'hex');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_session_secrets' AND column_name = 'created_at'
  ) THEN
    ALTER TABLE public.game_session_secrets ADD COLUMN created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' AND table_name = 'game_session_secrets' AND column_name = 'updated_at'
  ) THEN
    ALTER TABLE public.game_session_secrets ADD COLUMN updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
  END IF;
END $$;

-- 4. RPC CANÓNICA: SUBMIT_RPS_CHOICE_SECURE (RESOLUCIÓN DETERMINISTA SIN CREATED_AT)
CREATE OR REPLACE FUNCTION public.submit_rps_choice_secure(
  p_session_id UUID,
  p_choice VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_user_id UUID;
  v_norm_choice VARCHAR;
  v_session RECORD;
  v_secret_row RECORD;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_secret_choices JSONB;
  v_c1 TEXT;
  v_c2 TEXT;
  v_round_winner TEXT;
  v_round_winner_user_id UUID;
  v_p1_lives INT;
  v_p2_lives INT;
  v_match_winner TEXT;
  v_winner_user_id UUID;
  v_is_game_over BOOLEAN := false;
  v_new_state JSONB;
  v_history_entry JSONB;
  v_new_history JSONB;
  v_player_choices JSONB;
  v_curr_round INT;
  v_generated_seed VARCHAR(64);
BEGIN
  -- 1. Validar autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'AUTH_REQUIRED');
  END IF;

  -- Normalizar y validar jugada
  v_norm_choice := UPPER(TRIM(p_choice));
  IF v_norm_choice NOT IN ('ROCK', 'PAPER', 'SCISSORS') THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_CHOICE', 'valid', ARRAY['ROCK', 'PAPER', 'SCISSORS']);
  END IF;

  -- 2. Obtener y bloquear la sesión de juego
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  -- 3. Obtener o crear de forma segura el registro de secretos
  SELECT * INTO v_secret_row
  FROM public.game_session_secrets
  WHERE session_id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    BEGIN
      v_generated_seed := encode(extensions.gen_random_bytes(32), 'hex');
    EXCEPTION WHEN OTHERS THEN
      v_generated_seed := encode(public.gen_random_bytes(32), 'hex');
    END;

    INSERT INTO public.game_session_secrets (session_id, secret_state, server_seed)
    VALUES (p_session_id, '{}'::jsonb, v_generated_seed)
    RETURNING * INTO v_secret_row;
  END IF;

  -- 4. IDENTIFICAR JUGADORES 1 Y 2 DE FORMA CANÓNICA Y DETERMINISTA
  -- Prioridad 1: IDs registrados en el JSONB current_state de la partida
  v_p1_id := NULLIF(TRIM(v_session.current_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_session.current_state->>'player2Id'), '');

  -- Prioridad 2: Si falta player1Id, consultar game_table_players ordenado por seat_number y joined_at
  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Prioridad 3: Si falta player2Id, consultar el siguiente asiento activo
  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Validar que ambos jugadores existen
  IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_PLAYERS_IN_SESSION');
  END IF;

  -- Validar que el usuario actual pertenece a la partida
  IF v_user_id::text != v_p1_id AND v_user_id::text != v_p2_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_A_PLAYER_IN_THIS_MATCH');
  END IF;

  -- Validar que estemos en fase de selección (ROUND_COMMIT / selecting)
  IF COALESCE(v_session.current_state->>'status', 'ROUND_COMMIT') NOT IN ('ROUND_COMMIT', 'selecting') AND
     COALESCE(v_session.current_state->>'phase', 'selecting') NOT IN ('ROUND_COMMIT', 'selecting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ROUND_NOT_ACCEPTING_CHOICES');
  END IF;

  -- 5. ANTI-DOUBLE-SUBMIT: Verificar si el jugador ya comprometió su jugada
  v_secret_choices := COALESCE(v_secret_row.secret_state->'rps_choices', '{}'::jsonb);
  IF (v_secret_choices ? v_user_id::text AND v_secret_choices->>v_user_id::text IS NOT NULL) OR
     (COALESCE((v_session.current_state->'playerChoices'->(v_user_id::text)->>'committed')::boolean, false) IS TRUE) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'ALREADY_COMMITTED',
      'message', 'Ya has enviado tu jugada para esta ronda'
    );
  END IF;

  -- 6. Guardar la jugada privada en game_session_secrets
  v_secret_choices := jsonb_set(v_secret_choices, ARRAY[v_user_id::text], to_jsonb(v_norm_choice));

  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(secret_state, '{rps_choices}', v_secret_choices),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  -- 7. Comprobar si ambos jugadores han comprometido su jugada
  v_c1 := v_secret_choices->>v_p1_id;
  v_c2 := v_secret_choices->>v_p2_id;

  IF v_c1 IS NOT NULL AND v_c2 IS NOT NULL THEN
    -- =========================================================================
    -- AMBOS JUGADORES HAN ELEGIDO: REVELACIÓN ATÓMICA Y DETERMINACIÓN DE RONDA
    -- =========================================================================

    -- Determinar ganador de la ronda
    IF v_c1 = v_c2 THEN
      v_round_winner := 'DRAW';
      v_round_winner_user_id := NULL;
    ELSIF (v_c1 = 'ROCK' AND v_c2 = 'SCISSORS') OR
          (v_c1 = 'PAPER' AND v_c2 = 'ROCK') OR
          (v_c1 = 'SCISSORS' AND v_c2 = 'PAPER') THEN
      v_round_winner := 'PLAYER1';
      v_round_winner_user_id := v_p1_id::uuid;
    ELSE
      v_round_winner := 'PLAYER2';
      v_round_winner_user_id := v_p2_id::uuid;
    END IF;

    -- Obtener y actualizar vidas (Mejor de 3 vidas)
    v_p1_lives := COALESCE((v_session.current_state->>'player1Lives')::int, 3);
    v_p2_lives := COALESCE((v_session.current_state->>'player2Lives')::int, 3);

    IF v_round_winner = 'PLAYER1' THEN
      v_p2_lives := GREATEST(0, v_p2_lives - 1);
    ELSIF v_round_winner = 'PLAYER2' THEN
      v_p1_lives := GREATEST(0, v_p1_lives - 1);
    END IF;

    -- Comprobar si la partida completa finalizó
    IF v_p1_lives <= 0 THEN
      v_match_winner := 'PLAYER2';
      v_winner_user_id := v_p2_id::uuid;
      v_is_game_over := true;
    ELSIF v_p2_lives <= 0 THEN
      v_match_winner := 'PLAYER1';
      v_winner_user_id := v_p1_id::uuid;
      v_is_game_over := true;
    ELSE
      v_match_winner := NULL;
      v_winner_user_id := NULL;
      v_is_game_over := false;
    END IF;

    v_curr_round := COALESCE((v_session.current_state->>'roundNumber')::int, (v_session.current_state->>'round')::int, 1);

    v_history_entry := jsonb_build_object(
      'roundNumber', v_curr_round,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'winner', v_round_winner,
      'winnerUserId', v_round_winner_user_id,
      'timestamp', FLOOR(EXTRACT(EPOCH FROM NOW()) * 1000)
    );

    v_new_history := COALESCE(v_session.current_state->'history', '[]'::jsonb) || v_history_entry;

    -- Construir nuevo estado público revelado
    v_new_state := v_session.current_state;
    v_new_state := jsonb_set(v_new_state, '{player1Choice}', to_jsonb(v_c1));
    v_new_state := jsonb_set(v_new_state, '{player2Choice}', to_jsonb(v_c2));
    v_new_state := jsonb_set(v_new_state, '{player1Lives}', to_jsonb(v_p1_lives));
    v_new_state := jsonb_set(v_new_state, '{player2Lives}', to_jsonb(v_p2_lives));
    v_new_state := jsonb_set(v_new_state, '{lives}', jsonb_build_object(v_p1_id, v_p1_lives, v_p2_id, v_p2_lives));
    v_new_state := jsonb_set(v_new_state, '{roundWinner}', to_jsonb(v_round_winner));
    v_new_state := jsonb_set(v_new_state, '{roundWinnerUserId}', to_jsonb(v_round_winner_user_id));
    v_new_state := jsonb_set(v_new_state, '{matchWinner}', to_jsonb(v_match_winner));
    v_new_state := jsonb_set(v_new_state, '{winnerUserId}', to_jsonb(v_winner_user_id));
    v_new_state := jsonb_set(v_new_state, '{status}', to_jsonb(CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END));
    v_new_state := jsonb_set(v_new_state, '{phase}', to_jsonb(CASE WHEN v_is_game_over THEN 'match_ended' ELSE 'round_result' END));
    v_new_state := jsonb_set(v_new_state, '{history}', v_new_history);
    v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{playerChoices}', jsonb_build_object(
      v_p1_id, jsonb_build_object('committed', true, 'choice', v_c1),
      v_p2_id, jsonb_build_object('committed', true, 'choice', v_c2)
    ));

    -- Actualizar sesión pública: current_turn_user_id permanece NULL para RPS
    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        status = CASE WHEN v_is_game_over THEN 'FINISHED'::session_status_enum ELSE 'ACTIVE'::session_status_enum END,
        winner_user_id = v_winner_user_id,
        turn_expires_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        turn_deadline_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        ended_at = CASE WHEN v_is_game_over THEN NOW() ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Si terminó la partida, cerrar mesa y liquidar mediante libro mayor contable
    IF v_is_game_over THEN
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          updated_at = NOW()
      WHERE id = v_session.table_id;

      PERFORM public.settle_game_session(
        p_session_id,
        ARRAY[v_winner_user_id],
        NULL::int,
        'rps_match_' || p_session_id::text
      );
    END IF;

    -- Registrar acción inmutable en game_actions
    INSERT INTO public.game_actions (
      session_id,
      user_id,
      sequence_number,
      action_type,
      payload,
      is_valid,
      server_state_hash,
      idempotency_key
    ) VALUES (
      p_session_id,
      v_user_id,
      COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
      'ROUND_REVEAL',
      jsonb_build_object(
        'round', v_curr_round,
        'player1Choice', v_c1,
        'player2Choice', v_c2,
        'roundWinner', v_round_winner,
        'isGameOver', v_is_game_over
      ),
      true,
      md5(v_new_state::text),
      'rps_reveal_' || p_session_id::text || '_rnd_' || v_curr_round::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'isGameOver', v_is_game_over,
      'winnerUserId', v_winner_user_id,
      'roundWinner', v_round_winner,
      'roundWinnerUserId', v_round_winner_user_id,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'bothChosen', true
    );

  ELSE
    -- =========================================================================
    -- SOLO UNO HA ELEGIDO: REGISTRAR COMMIT PROTEGIENDO EL SECRETO DEL JUGADOR
    -- =========================================================================
    v_player_choices := COALESCE(v_session.current_state->'playerChoices', '{}'::jsonb);
    v_player_choices := jsonb_set(
      v_player_choices,
      ARRAY[v_user_id::text],
      jsonb_build_object('committed', true)
    );

    v_new_state := v_session.current_state;
    v_new_state := jsonb_set(v_new_state, '{playerChoices}', v_player_choices);
    v_new_state := jsonb_set(v_new_state, '{player1Choice}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{player2Choice}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{status}', '"ROUND_COMMIT"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{phase}', '"selecting"'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
    v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', 'ROUND_COMMIT',
      'isGameOver', false,
      'bothChosen', false,
      'committed', true
    );
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) TO authenticated, anon, service_role;

-- 5. RPC: NEXT_RPS_ROUND_SECURE (REINICIO ATÓMICO CON RESOLUCIÓN SEGURA)
CREATE OR REPLACE FUNCTION public.next_rps_round_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_session RECORD;
  v_curr_round INT;
  v_new_round INT;
  v_new_state JSONB;
  v_p1_id TEXT;
  v_p2_id TEXT;
BEGIN
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  -- Solo avanzar si estaba en fase de resultado de ronda
  IF COALESCE(v_session.current_state->>'status', '') != 'ROUND_REVEAL' AND
     COALESCE(v_session.current_state->>'phase', '') != 'round_result' THEN
    RETURN jsonb_build_object('success', true, 'message', 'ALREADY_ADVANCED');
  END IF;

  v_curr_round := COALESCE((v_session.current_state->>'roundNumber')::int, (v_session.current_state->>'round')::int, 1);
  v_new_round := v_curr_round + 1;

  -- Identificar jugadores de forma determinista
  v_p1_id := NULLIF(TRIM(v_session.current_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_session.current_state->>'player2Id'), '');

  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  v_new_state := v_session.current_state;
  v_new_state := jsonb_set(v_new_state, '{roundNumber}', to_jsonb(v_new_round));
  v_new_state := jsonb_set(v_new_state, '{round}', to_jsonb(v_new_round));
  v_new_state := jsonb_set(v_new_state, '{player1Choice}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{player2Choice}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{roundWinner}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{roundWinnerUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{status}', '"ROUND_COMMIT"'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{phase}', '"selecting"'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{currentTurnUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{turnUserId}', 'null'::jsonb);
  v_new_state := jsonb_set(v_new_state, '{playerChoices}', jsonb_build_object(
    COALESCE(v_p1_id, 'player1'), jsonb_build_object('committed', false),
    COALESCE(v_p2_id, 'player2'), jsonb_build_object('committed', false)
  ));

  UPDATE public.game_sessions
  SET current_state = v_new_state,
      current_turn_user_id = NULL,
      turn_expires_at = NOW() + INTERVAL '15 seconds',
      turn_deadline_at = NOW() + INTERVAL '15 seconds',
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Limpiar cualquier secreto residual
  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(secret_state, '{rps_choices}', '{}'::jsonb),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  RETURN jsonb_build_object('success', true, 'round', v_new_round);
END;
$$;

GRANT EXECUTE ON FUNCTION public.next_rps_round_secure(UUID) TO authenticated, anon, service_role;

-- 6. RPC: PROCESS_EXPIRED_TURNS (DISTINCIÓN STRICTA ROUND_DEADLINE vs PLAYER_TURN_DEADLINE)
DROP FUNCTION IF EXISTS public.process_expired_turns();

CREATE OR REPLACE FUNCTION public.process_expired_turns()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_expired_row RECORD;
  v_table RECORD;
  v_p1_id UUID;
  v_p2_id UUID;
  v_p1_committed BOOLEAN;
  v_p2_committed BOOLEAN;
  v_winner_id UUID;
  v_loser_id UUID;
  v_secret_choices JSONB;
  v_idempotency_key VARCHAR(100);
  v_curr_round INT;
BEGIN
  -- ---------------------------------------------------------------------------
  -- A. PROCESAMIENTO DE EXPIRACIONES PARA JUEGOS SECUENCIALES (DOMINÓ, TRUCO, ETC.)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_turn_user_id, t.game_type, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND s.current_turn_user_id IS NOT NULL
      AND t.game_type NOT IN ('rock_paper_scissors', 'rps')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      v_idempotency_key := 'seq_timeout_' || v_expired_row.id::text || '_' || v_expired_row.current_turn_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::int::text;
      PERFORM public.record_turn_timeout_secure(
        v_expired_row.id,
        v_expired_row.current_turn_user_id,
        v_idempotency_key
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en juego secuencial %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;

  -- ---------------------------------------------------------------------------
  -- B. PROCESAMIENTO DE EXPIRACIONES PARA PIEDRA, PAPEL O TIJERA (ROUND_DEADLINE)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_state, s.created_at, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND t.game_type IN ('rock_paper_scissors', 'rps')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
      AND COALESCE(s.current_state->>'status', '') IN ('ROUND_COMMIT', 'selecting')
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      v_curr_round := COALESCE((v_expired_row.current_state->>'roundNumber')::int, 1);
      v_idempotency_key := 'rps_timeout_' || v_expired_row.id::text || '_rnd_' || v_curr_round::text;

      -- Identificar jugadores de forma determinista sin created_at
      v_p1_id := NULLIF(TRIM(v_expired_row.current_state->>'player1Id'), '')::uuid;
      v_p2_id := NULLIF(TRIM(v_expired_row.current_state->>'player2Id'), '')::uuid;

      IF v_p1_id IS NULL THEN
        SELECT user_id INTO v_p1_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;

      IF v_p2_id IS NULL THEN
        SELECT user_id INTO v_p2_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND user_id != v_p1_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;

      -- Consultar compromisos registrados
      SELECT secret_state->'rps_choices' INTO v_secret_choices
      FROM public.game_session_secrets
      WHERE session_id = v_expired_row.id;

      v_p1_committed := (v_secret_choices ? v_p1_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p1_id::text)->>'committed')::boolean, false);
      v_p2_committed := (v_secret_choices ? v_p2_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p2_id::text)->>'committed')::boolean, false);

      IF v_p1_committed AND NOT v_p2_committed THEN
        v_winner_id := v_p1_id;
        v_loser_id := v_p2_id;
      ELSIF v_p2_committed AND NOT v_p1_committed THEN
        v_winner_id := v_p2_id;
        v_loser_id := v_p1_id;
      ELSE
        v_winner_id := NULL;
        v_loser_id := NULL;
      END IF;

      IF v_winner_id IS NOT NULL THEN
        -- Victoria por abandono/timeout del oponente
        UPDATE public.game_sessions
        SET status = 'FINISHED'::session_status_enum,
            winner_user_id = v_winner_id,
            ended_at = NOW(),
            current_state = jsonb_set(
              jsonb_set(current_state, '{winnerUserId}', to_jsonb(v_winner_id)),
              '{abandonedBy}', to_jsonb(v_loser_id)
            ),
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_row.table_id;

        PERFORM public.settle_game_session(
          v_expired_row.id,
          ARRAY[v_winner_id],
          NULL::int,
          v_idempotency_key
        );
      ELSE
        -- Ninguno eligió dentro del plazo: Cancelación y reembolso seguro al 100%
        UPDATE public.game_sessions
        SET status = 'CANCELLED'::session_status_enum,
            ended_at = NOW(),
            current_state = jsonb_set(current_state, '{cancelReason}', '"ROUND_TIMEOUT_NO_CHOICES"'::jsonb),
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        UPDATE public.game_tables
        SET status = 'CLOSED'::table_status_enum,
            closed_at = NOW(),
            updated_at = NOW()
        WHERE id = v_expired_row.table_id;

        PERFORM public.refund_game_session(
          v_expired_row.id,
          'Tiempo de ronda agotado sin jugadas de ningún participante',
          v_idempotency_key
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en ronda simultánea RPS %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.process_expired_turns() TO authenticated, anon, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 146: 143_centralized_financial_settlement_and_held_balance_fix.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 143: SISTEMA FINANCIERO CENTRALIZADO Y AUDITORÍA FORENSE DE SALDOS RETENIDOS
-- ==============================================================================
-- 1. Tabla public.financial_rules (Fuente única de verdad para comisiones y premios)
-- 2. Función public.get_financial_rules()
-- 3. Función canónica public.universal_settle_game_session (90/10, captura de held_balance y abono de premio)
-- 4. Delegación de retrocompatibilidad para settle_game_session y settle_game_session_secure
-- 5. Función public.refund_game_session (Devolución íntegra 100% held_balance -> available_balance)
-- 6. Función public.rpc_claim_bingo_secure corregida (libera held_balance de todos los compradores de Bingo)
-- 7. Función public.refund_bingo_session_secure (Reembolso de cartones si se cancela la sala)
-- 8. Funciones de abandono actualizadas con enums válidos: abandon_game_secure y abandon_game_table_secure
-- 9. Corrección de admin_terminate_game_table para deducir held_balance en reembolsos
-- 10. Función de auditoría y conciliación forense de saldos huérfanos: audit_and_reconcile_held_balances()
-- ==============================================================================

-- 1. CREAR TABLA DE REGLAS FINANCIERAS
CREATE TABLE IF NOT EXISTS public.financial_rules (
  id TEXT PRIMARY KEY DEFAULT 'GLOBAL',
  rule_name TEXT NOT NULL UNIQUE DEFAULT 'GLOBAL_FINANCIAL_RULE',
  winner_percentage NUMERIC(5,2) NOT NULL DEFAULT 90.00,
  platform_fee_percentage NUMERIC(5,2) NOT NULL DEFAULT 10.00,
  is_active BOOLEAN NOT NULL DEFAULT true,
  description TEXT DEFAULT 'Regla financiera global de comisiones y premios (90% ganador / 10% plataforma)',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- RLS y permisos para financial_rules
ALTER TABLE public.financial_rules ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read on financial_rules" ON public.financial_rules;
CREATE POLICY "Allow public read on financial_rules"
  ON public.financial_rules FOR SELECT
  TO authenticated, anon
  USING (true);

DROP POLICY IF EXISTS "Allow admin manage on financial_rules" ON public.financial_rules;
CREATE POLICY "Allow admin manage on financial_rules"
  ON public.financial_rules FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = auth.uid() AND ur.role::text IN ('SUPER_ADMIN', 'ADMIN')
    )
  );

-- Configuración inicial por defecto
INSERT INTO public.financial_rules (id, rule_name, winner_percentage, platform_fee_percentage, is_active, description)
VALUES ('GLOBAL', 'GLOBAL_FINANCIAL_RULE', 90.00, 10.00, true, 'Regla financiera global de comisiones (90% ganador / 10% plataforma)')
ON CONFLICT (id) DO UPDATE SET
  winner_percentage = 90.00,
  platform_fee_percentage = 10.00,
  is_active = true,
  updated_at = NOW();

-- 2. FUNCIÓN DE LECTURA DE REGLAS FINANCIERAS
CREATE OR REPLACE FUNCTION public.get_financial_rules()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_rule RECORD;
BEGIN
  SELECT * INTO v_rule
  FROM public.financial_rules
  WHERE is_active = true
  ORDER BY (id = 'GLOBAL') DESC, created_at ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'winner_percentage', 90.00,
      'platform_fee_percentage', 10.00,
      'rule_name', 'DEFAULT_FALLBACK'
    );
  END IF;

  RETURN jsonb_build_object(
    'winner_percentage', v_rule.winner_percentage,
    'platform_fee_percentage', v_rule.platform_fee_percentage,
    'rule_name', v_rule.rule_name,
    'description', v_rule.description
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_financial_rules() TO authenticated, anon, service_role;

-- 3. FUNCIÓN AUTORITATIVA CENTRAL: universal_settle_game_session
CREATE OR REPLACE FUNCTION public.universal_settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[] DEFAULT ARRAY[]::UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_table RECORD;
  v_rule RECORD;
  v_winner_pct NUMERIC(5,2) := 90.00;
  v_platform_pct NUMERIC(5,2) := 10.00;
  v_entry_fee NUMERIC(14,2) := 0.00;
  v_gross_pool NUMERIC(14,2) := 0.00;
  v_platform_fee NUMERIC(14,2) := 0.00;
  v_prize_pool NUMERIC(14,2) := 0.00;
  v_individual_prize NUMERIC(14,2) := 0.00;
  v_effective_idempotency TEXT;
  v_settlement_id UUID;
  v_existing_settlement RECORD;
  v_winners_count INTEGER := 0;
  v_primary_winner_id UUID := NULL;
  v_winner_id UUID;
  v_player_id UUID;
  v_winner_wallet RECORD;
  v_player_wallet RECORD;
  v_total_players INTEGER := 0;
  v_table_players UUID[] := ARRAY[]::UUID[];
  v_settlement_type settlement_type_enum := 'STANDARD_PAYOUT'::settlement_type_enum;
  v_is_draw BOOLEAN := false;
BEGIN
  -- 1. Idempotencia estricta: Verificar si ya existe liquidación por clave o por sesión
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'stl_' || p_session_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id OR (idempotency_key IS NOT NULL AND idempotency_key = v_effective_idempotency)
  ORDER BY settled_at DESC
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'session_id', v_existing_settlement.session_id,
      'table_id', v_existing_settlement.table_id,
      'gross_pool', v_existing_settlement.gross_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'prize_pool', v_existing_settlement.prize_pool,
      'winner_user_id', COALESCE(p_winner_user_ids[1], NULL),
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  -- 2. Bloquear la sesión con FOR UPDATE
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: No se encontró la sesión especificada (%)', p_session_id;
  END IF;

  IF v_session.status::text IN ('FINISHED', 'CANCELLED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_settled', true,
      'session_id', p_session_id,
      'winner_user_id', v_session.winner_user_id
    );
  END IF;

  -- 3. Bloquear la mesa asociada
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: No se encontró la mesa asociada a la sesión.';
  END IF;

  -- 4. Leer Fuente Única de Verdad: Reglas Financieras Centralizadas
  SELECT * INTO v_rule
  FROM public.financial_rules
  WHERE is_active = true
  ORDER BY (id = 'GLOBAL') DESC, created_at ASC
  LIMIT 1;

  IF FOUND THEN
    v_winner_pct := COALESCE(v_rule.winner_percentage, 90.00);
    v_platform_pct := COALESCE(v_rule.platform_fee_percentage, 10.00);
  END IF;

  IF (v_winner_pct + v_platform_pct) != 100.00 THEN
    v_platform_pct := GREATEST(0.00, 100.00 - v_winner_pct);
  END IF;

  -- 5. Obtener todos los participantes con trazabilidad completa (mesa, ledger y ganadores)
  SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_table_players
  FROM (
    SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries WHERE reference_id = v_table.id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
    UNION
    SELECT unnest(p_winner_user_ids) AS u_id
  ) all_p
  WHERE u_id IS NOT NULL;

  v_winners_count := COALESCE(array_length(p_winner_user_ids, 1), 0);

  IF v_winners_count > 0 AND p_winner_user_ids[1] IS NOT NULL THEN
    v_primary_winner_id := p_winner_user_ids[1];
    v_is_draw := false;
    IF v_winners_count > 1 THEN
      v_settlement_type := 'SPLIT_PAYOUT'::settlement_type_enum;
    ELSE
      v_settlement_type := 'STANDARD_PAYOUT'::settlement_type_enum;
    END IF;
  ELSE
    v_settlement_type := 'DRAW_REFUND'::settlement_type_enum;
    v_is_draw := true;
  END IF;

  v_total_players := GREATEST(COALESCE(array_length(v_table_players, 1), 0), 2);
  v_entry_fee := COALESCE(v_table.entry_fee, 0.00);
  v_gross_pool := v_entry_fee * v_total_players;
  IF v_is_draw THEN
    v_platform_fee := 0.00;
    v_prize_pool := 0.00;
  ELSE
    v_platform_fee := ROUND(v_gross_pool * (v_platform_pct / 100.00), 2);
    v_prize_pool := v_gross_pool - v_platform_fee;
  END IF;

  -- 6. Insertar registro en game_settlements
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    gross_pool,
    platform_fee,
    prize_pool,
    total_distributed,
    settlement_type,
    idempotency_key,
    settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    v_gross_pool,
    v_platform_fee,
    v_prize_pool,
    CASE WHEN v_is_draw THEN v_gross_pool ELSE v_prize_pool END,
    v_settlement_type,
    v_effective_idempotency,
    NOW()
  );

  -- 7. GESTIÓN FINANCIERA ATÓMICA DE FONDOS RETENIDOS (held_balance)
  IF v_entry_fee > 0.00 AND v_table_players IS NOT NULL AND array_length(v_table_players, 1) > 0 THEN
    FOREACH v_player_id IN ARRAY v_table_players LOOP
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player_id
      FOR UPDATE;

      IF FOUND THEN
        IF v_is_draw THEN
          -- EMPATE TÉCNICO: Regresar saldo retenido a saldo disponible al 100%
          UPDATE public.wallets
          SET available_balance = available_balance + v_entry_fee,
              held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_player_wallet.available_balance + v_entry_fee,
            v_player_wallet.available_balance + v_entry_fee,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_refund_' || v_player_id::text,
            'Devolución de entrada por empate en ' || COALESCE(v_table.game_type::text, 'partida'),
            NOW()
          );
        ELSE
          -- PARTIDA NORMAL CON GANADOR: Capturar y descontar definitivamente held_balance
          UPDATE public.wallets
          SET held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_CAPTURE'::ledger_entry_type_enum,
            'DEBIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_player_wallet.available_balance,
            v_player_wallet.available_balance,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_capture_' || v_player_id::text,
            'Captura de entrada para liquidación en ' || COALESCE(v_table.game_type::text, 'partida'),
            NOW()
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 8. ACREDITACIÓN DE PREMIO A LOS GANADORES EN available_balance
  IF NOT v_is_draw AND v_winners_count > 0 AND v_prize_pool > 0.00 THEN
    v_individual_prize := ROUND(v_prize_pool / v_winners_count, 2);

    FOREACH v_winner_id IN ARRAY p_winner_user_ids LOOP
      IF v_winner_id IS NOT NULL THEN
        SELECT * INTO v_winner_wallet
        FROM public.wallets
        WHERE user_id = v_winner_id
        FOR UPDATE;

        IF FOUND THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_individual_prize,
              updated_at = NOW()
          WHERE id = v_winner_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_winner_wallet.id,
            v_winner_id,
            v_individual_prize,
            'VES',
            'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_winner_wallet.available_balance + v_individual_prize,
            v_winner_wallet.available_balance + v_individual_prize,
            v_winner_wallet.held_balance,
            v_effective_idempotency || '_win_' || v_winner_id::text,
            'Premio por victoria en partida (' || v_winner_pct::text || '% del pozo)',
            NOW()
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 9. Actualizar estado oficial de la sesión
  UPDATE public.game_sessions
  SET status = (CASE WHEN v_is_draw THEN 'CANCELLED' ELSE 'FINISHED' END)::session_status_enum,
      winner_user_id = v_primary_winner_id,
      winner_team = p_winner_team,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE id = p_session_id;

  -- 10. Actualizar estado de la mesa y jugadores
  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_table.id AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'table_id', v_table.id,
    'gross_pool', v_gross_pool,
    'platform_fee', v_platform_fee,
    'prize_pool', v_prize_pool,
    'winner_percentage', v_winner_pct,
    'platform_percentage', v_platform_pct,
    'winner_user_id', v_primary_winner_id,
    'is_draw', v_is_draw,
    'settlement_id', v_settlement_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.universal_settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, service_role, anon;

-- 4. RETROCOMPATIBILIDAD: settle_game_session
CREATE OR REPLACE FUNCTION public.settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
BEGIN
  RETURN public.universal_settle_game_session(
    p_session_id,
    p_winner_user_ids,
    p_winner_team,
    p_idempotency_key
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.settle_game_session(UUID, UUID[], INTEGER, TEXT) TO authenticated, service_role, anon;

-- RETROCOMPATIBILIDAD: settle_game_session_secure
CREATE OR REPLACE FUNCTION public.settle_game_session_secure(
  p_session_id UUID,
  p_winner_user_id UUID DEFAULT NULL,
  p_winner_team INTEGER DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_winner_array UUID[] := ARRAY[]::UUID[];
BEGIN
  IF p_winner_user_id IS NOT NULL THEN
    v_winner_array := ARRAY[p_winner_user_id];
  END IF;

  RETURN public.universal_settle_game_session(
    p_session_id,
    v_winner_array,
    p_winner_team,
    p_idempotency_key
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.settle_game_session_secure(UUID, UUID, INTEGER, TEXT) TO authenticated, service_role, anon;

-- 5. FUNCIÓN CENTRALIZADA DE REEMBOLSO: refund_game_session
CREATE OR REPLACE FUNCTION public.refund_game_session(
  p_session_id UUID,
  p_reason TEXT DEFAULT 'CANCELLED',
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_gross_pool NUMERIC(14,2) := 0.00;
  v_settlement_id UUID;
  v_player_id UUID;
  v_player_wallet RECORD;
  v_existing_settlement RECORD;
  v_effective_idempotency TEXT;
  v_refunded_count INT := 0;
  v_participants UUID[] := ARRAY[]::UUID[];
BEGIN
  v_caller_id := auth.uid();

  -- 1. Obtener y bloquear sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- 2. Idempotencia
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'refund_' || p_session_id::text || '_' || COALESCE(v_caller_id::text, 'sys')
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id AND settlement_type = 'ADMIN_CANCEL_REFUND'::settlement_type_enum;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  IF v_session.status = 'FINISHED'::session_status_enum THEN
    RAISE EXCEPTION 'INVALID_SESSION_STATUS: No se puede reembolsar una sesión ya liquidada y finalizada con ganador.';
  END IF;

  -- 3. Identificar TODOS los participantes que aportaron entrada
  SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_participants
  FROM (
    SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries WHERE reference_id = v_table.id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries WHERE reference_id = p_session_id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
  ) all_p
  WHERE u_id IS NOT NULL;

  v_gross_pool := COALESCE(v_table.entry_fee, 0.00) * GREATEST(COALESCE(array_length(v_participants, 1), 0), 1);

  -- 4. Registro de liquidación tipo ADMIN_CANCEL_REFUND
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    'ADMIN_CANCEL_REFUND'::settlement_type_enum,
    v_gross_pool,
    0.00,
    0.00,
    v_gross_pool,
    v_effective_idempotency,
    NOW()
  );

  -- 5. Liberación íntegra de saldos retenidos a disponible (held_balance -> available_balance)
  IF COALESCE(v_table.entry_fee, 0.00) > 0.00 AND v_participants IS NOT NULL THEN
    FOREACH v_player_id IN ARRAY v_participants LOOP
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player_id
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_table.entry_fee,
            held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
            updated_at = NOW()
        WHERE id = v_player_wallet.id;

        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          currency,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_type,
          reference_id,
          idempotency_key,
          description,
          actor_id,
          created_at
        ) VALUES (
          gen_random_uuid(),
          v_player_wallet.id,
          v_player_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          'VES',
          v_player_wallet.available_balance + v_table.entry_fee,
          v_player_wallet.available_balance + v_table.entry_fee,
          GREATEST(0.00, v_player_wallet.held_balance - v_table.entry_fee),
          'game_sessions',
          'game_session',
          p_session_id,
          v_effective_idempotency || '_refund_' || v_player_id::text,
          'Reembolso de entrada por empate o cancelación: ' || COALESCE(p_reason, 'Sin motivo'),
          v_caller_id,
          NOW()
        );

        v_refunded_count := v_refunded_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- 6. Actualización de Estados
  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_table.id AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'settlement_id', v_settlement_id,
    'refunded_count', v_refunded_count,
    'gross_refunded', v_gross_pool
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.refund_game_session(UUID, TEXT, TEXT) TO authenticated, service_role, anon;

-- 6. CORRECCIÓN ROBUSTA DE rpc_claim_bingo_secure
-- Liquidación autoritativa 90/10 y liberación de held_balance para TODOS los participantes
CREATE OR REPLACE FUNCTION public.rpc_claim_bingo_secure(
  p_session_id UUID,
  p_card_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_current_state JSONB;
  v_drawn_balls INT[];
  v_variant TEXT;
  v_purchase RECORD;
  v_user_cards JSONB;
  v_valid_bingo BOOLEAN := false;
  v_total_sales NUMERIC(14,2) := 0.00;
  v_winner_pool NUMERIC(14,2) := 0.00;
  v_platform_fee NUMERIC(14,2) := 0.00;
  v_winner_wallet RECORD;
  v_winner_profile RECORD;
  v_winner_name TEXT;
  v_winner_avatar TEXT;
  v_card_item JSONB;
  v_player_purchase RECORD;
  v_p_wallet RECORD;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USUARIO_NO_AUTENTICADO');
  END IF;

  -- 1. Bloquear la Sesión para Garantizar UN SOLO Ganador Atómico
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  v_current_state := COALESCE(v_session.current_state, '{}'::jsonb);

  -- Si la partida ya fue reclamada y tiene ganador
  IF (v_current_state->>'winnerUserId') IS NOT NULL AND (v_current_state->>'winnerUserId') <> '' THEN
    RETURN jsonb_build_object(
      'success', false,
      'claimed_already', true,
      'winner_user_id', v_current_state->>'winnerUserId',
      'error', 'El bingo ya fue reclamado y verificado por otro jugador.'
    );
  END IF;

  -- Extraer balotas jugadas
  SELECT ARRAY(
    SELECT jsonb_array_elements_text(COALESCE(v_current_state->'drawnBalls', '[]'::jsonb))::INT
  ) INTO v_drawn_balls;

  v_variant := COALESCE(v_current_state->>'variant', '75');

  -- 2. Obtener Cartones del Usuario para esta Mesa
  SELECT * INTO v_purchase
  FROM public.bingo_card_purchases
  WHERE game_table_id = v_session.table_id AND user_id = v_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'CARTON_NO_ENCONTRADO: No posees cartones registrados para esta mesa.');
  END IF;

  v_user_cards := v_purchase.cards_data;

  -- 3. Validar Canto de Bingo en Servidor (100% Server-Authoritative)
  IF array_length(v_drawn_balls, 1) IS NULL OR array_length(v_drawn_balls, 1) < 4 THEN
    RETURN jsonb_build_object('success', false, 'error', 'CANTO_FALSO: Se han extraído muy pocas balotas para completar Bingo.');
  END IF;

  FOR v_card_item IN SELECT jsonb_array_elements(v_user_cards) LOOP
    IF public.fn_validate_bingo_card_win(v_card_item, v_variant, v_drawn_balls) THEN
      v_valid_bingo := true;
      EXIT;
    END IF;
  END LOOP;

  IF NOT v_valid_bingo THEN
    RETURN jsonb_build_object('success', false, 'error', 'CANTO_FALSO: Tus cartones no completan un Bingo válido con las balotas extraídas.');
  END IF;

  -- 4. Calcular Pozo Total y Otorgar Premio (90% al Ganador, 10% Plataforma)
  SELECT COALESCE(SUM(total_cost), 0.00) INTO v_total_sales
  FROM public.bingo_card_purchases
  WHERE game_table_id = v_session.table_id;

  v_winner_pool := ROUND(v_total_sales * 0.90, 2);
  v_platform_fee := v_total_sales - v_winner_pool;

  IF v_winner_pool <= 0.00 THEN
    v_winner_pool := ROUND(COALESCE(v_purchase.total_cost, 25.00) * 0.90, 2);
  END IF;

  -- Actualizar billetera del ganador
  SELECT * INTO v_winner_wallet
  FROM public.wallets
  WHERE user_id = v_user_id
  FOR UPDATE;

  IF v_winner_wallet.id IS NULL THEN
    INSERT INTO public.wallets (user_id, available_balance, held_balance)
    VALUES (v_user_id, v_winner_pool, 0.00)
    RETURNING * INTO v_winner_wallet;
  ELSE
    UPDATE public.wallets
    SET available_balance = available_balance + v_winner_pool,
        updated_at = NOW()
    WHERE id = v_winner_wallet.id;
  END IF;

  -- Registrar Premio en ledger_entries oficial
  INSERT INTO public.ledger_entries (
    id,
    wallet_id,
    user_id,
    amount,
    currency,
    entry_type,
    direction,
    reference_id,
    reference_table,
    reference_type,
    balance_after,
    balance_after_available,
    balance_after_held,
    idempotency_key,
    description,
    created_at
  ) VALUES (
    gen_random_uuid(),
    v_winner_wallet.id,
    v_user_id,
    v_winner_pool,
    'VES',
    'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
    'CREDIT'::ledger_direction_enum,
    p_session_id,
    'game_sessions',
    'bingo_session',
    v_winner_wallet.available_balance + v_winner_pool,
    v_winner_wallet.available_balance + v_winner_pool,
    v_winner_wallet.held_balance,
    'bingo_prize_' || p_session_id::text || '_' || v_user_id::text,
    'Premio de Bingo ' || v_variant || ' Bolas (90% pozo)',
    NOW()
  );

  -- 5. LIBERACIÓN ATÓMICA DE SALDOS RETENIDOS DE TODOS LOS PARTICIPANTES DE ESTE BINGO
  -- Por cada usuario que compró cartones en esta mesa, descontar de held_balance y registrar captura
  FOR v_player_purchase IN
    SELECT user_id, SUM(total_cost) as total_purchase
    FROM public.bingo_card_purchases
    WHERE game_table_id = v_session.table_id
    GROUP BY user_id
  LOOP
    SELECT * INTO v_p_wallet
    FROM public.wallets
    WHERE user_id = v_player_purchase.user_id
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.wallets
      SET held_balance = GREATEST(0.00, held_balance - v_player_purchase.total_purchase),
          updated_at = NOW()
      WHERE id = v_p_wallet.id;

      INSERT INTO public.ledger_entries (
        id,
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        gen_random_uuid(),
        v_p_wallet.id,
        v_player_purchase.user_id,
        v_player_purchase.total_purchase,
        'VES',
        'TABLE_ENTRY_CAPTURE'::ledger_entry_type_enum,
        'DEBIT'::ledger_direction_enum,
        p_session_id,
        'game_sessions',
        'bingo_session',
        v_p_wallet.available_balance,
        v_p_wallet.available_balance,
        GREATEST(0.00, v_p_wallet.held_balance - v_player_purchase.total_purchase),
        'bingo_capture_' || p_session_id::text || '_' || v_player_purchase.user_id::text,
        'Captura de fondos retenidos por compra de cartones de Bingo',
        NOW()
      );
    END IF;
  END LOOP;

  -- 6. Obtener Perfil del Ganador
  SELECT first_name, last_name, avatar_url INTO v_winner_profile
  FROM public.profiles
  WHERE user_id = v_user_id;

  v_winner_name := TRIM(COALESCE(v_winner_profile.first_name || ' ' || v_winner_profile.last_name, 'Jugador Bingo'));
  v_winner_avatar := v_winner_profile.avatar_url;

  -- 7. Actualizar Estado de la Sesión y Mesa
  v_current_state := v_current_state || jsonb_build_object(
    'status', 'bingo_won',
    'winnerUserId', v_user_id,
    'winnerName', v_winner_name,
    'winnerAvatar', v_winner_avatar,
    'winnerPoolBs', v_winner_pool
  );

  UPDATE public.game_sessions
  SET status = 'FINISHED'::session_status_enum,
      winner_user_id = v_user_id,
      ended_at = NOW(),
      current_state = v_current_state,
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      finished_at = NOW(),
      updated_at = NOW()
  WHERE id = v_session.table_id;

  -- 8. Historial Dedicado de Bingo
  INSERT INTO public.bingo_winner_history (
    session_id,
    user_id,
    winner_name,
    prize_bs,
    photo_url
  ) VALUES (
    p_session_id,
    v_user_id,
    v_winner_name,
    v_winner_pool,
    NULL
  );

  -- Limpieza automática de registros antiguos de Bingo
  DELETE FROM public.bingo_winner_history WHERE created_at < NOW() - INTERVAL '7 days';

  RETURN jsonb_build_object(
    'success', true,
    'winner_user_id', v_user_id,
    'winner_name', v_winner_name,
    'winner_avatar', v_winner_avatar,
    'prize_bs', v_winner_pool,
    'variant', v_variant,
    'message', '¡Felicidades! Se te ha acreditado el premio de ' || v_winner_pool || ' Bs.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_claim_bingo_secure(UUID, UUID) TO authenticated, service_role, anon;

-- 7. FUNCIÓN PARA REEMBOLSAR SALAS DE BINGO CANCELADAS O SIN GANADOR
CREATE OR REPLACE FUNCTION public.refund_bingo_session_secure(
  p_session_id UUID,
  p_reason TEXT DEFAULT 'Cancelación de sala de Bingo'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_session RECORD;
  v_player_purchase RECORD;
  v_p_wallet RECORD;
  v_refunded_count INT := 0;
  v_total_refunded NUMERIC(14,2) := 0.00;
BEGIN
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  IF v_session.status = 'FINISHED'::session_status_enum THEN
    RETURN jsonb_build_object('success', false, 'error', 'SALA_YA_LIQUIDADA_CON_GANADOR');
  END IF;

  -- Reembolsar a todos los compradores de cartones de esta mesa
  FOR v_player_purchase IN
    SELECT user_id, SUM(total_cost) as total_purchase
    FROM public.bingo_card_purchases
    WHERE game_table_id = v_session.table_id
    GROUP BY user_id
  LOOP
    SELECT * INTO v_p_wallet
    FROM public.wallets
    WHERE user_id = v_player_purchase.user_id
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.wallets
      SET available_balance = available_balance + v_player_purchase.total_purchase,
          held_balance = GREATEST(0.00, held_balance - v_player_purchase.total_purchase),
          updated_at = NOW()
      WHERE id = v_p_wallet.id;

      INSERT INTO public.ledger_entries (
        id,
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        gen_random_uuid(),
        v_p_wallet.id,
        v_player_purchase.user_id,
        v_player_purchase.total_purchase,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        p_session_id,
        'game_sessions',
        'bingo_session',
        v_p_wallet.available_balance + v_player_purchase.total_purchase,
        v_p_wallet.available_balance + v_player_purchase.total_purchase,
        GREATEST(0.00, v_p_wallet.held_balance - v_player_purchase.total_purchase),
        'bingo_refund_' || p_session_id::text || '_' || v_player_purchase.user_id::text,
        'Reembolso íntegro por cancelación de sala de Bingo: ' || COALESCE(p_reason, 'Cancelación'),
        NOW()
      );

      v_refunded_count := v_refunded_count + 1;
      v_total_refunded := v_total_refunded + v_player_purchase.total_purchase;
    END IF;
  END LOOP;

  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_session.table_id;

  RETURN jsonb_build_object(
    'success', true,
    'refunded_count', v_refunded_count,
    'total_refunded', v_total_refunded
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.refund_bingo_session_secure(UUID, TEXT) TO authenticated, service_role, anon;

-- 8. ABANDONO SEGURO CON ENUMS VÁLIDOS: abandon_game_table_secure
CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_player RECORD;
  v_session RECORD;
  v_wallet RECORD;
  v_active_players_count INTEGER;
  v_remaining_player RECORD;
  v_effective_idempotency TEXT;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_session_is_active BOOLEAN := false;
  v_settle_result JSONB;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para abandonar la mesa.';
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || p_table_id::text || '_' || v_caller_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  -- 1. Obtener mesa con bloqueo pesimista
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: No se encontró la mesa especificada.';
  END IF;

  -- 2. Obtener sesión activa si existe
  IF p_session_id IS NOT NULL THEN
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE id = p_session_id
    FOR UPDATE;
  ELSE
    SELECT * INTO v_session
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status IN ('ACTIVE'::session_status_enum, 'READY'::session_status_enum, 'STARTING'::session_status_enum, 'PAUSED'::session_status_enum)
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF v_session.id IS NOT NULL AND v_session.status = 'ACTIVE'::session_status_enum THEN
    v_session_is_active := true;
  END IF;

  -- 3. Obtener registro del jugador
  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND user_id = v_caller_id
    AND status IN ('JOINED'::player_table_status_enum, 'READY'::player_table_status_enum, 'PLAYING'::player_table_status_enum)
  FOR UPDATE;

  IF NOT FOUND THEN
    SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
    FROM public.game_table_players
    WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

    RETURN jsonb_build_object(
      'success', true,
      'already_left', true,
      'table_id', p_table_id,
      'remaining_players', v_active_players_count
    );
  END IF;

  -- Marcar jugador como LEFT
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE id = v_player.id;

  -- 4. Reembolso pre-partida si la partida no ha comenzado
  -- Liberar de held_balance y restituir a available_balance con TABLE_ENTRY_REFUND
  IF NOT v_session_is_active AND COALESCE(v_table.entry_fee, 0.00) > 0.00 THEN
    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_caller_id
    FOR UPDATE;

    IF FOUND THEN
      UPDATE public.wallets
      SET available_balance = available_balance + v_table.entry_fee,
          held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
          updated_at = NOW()
      WHERE id = v_wallet.id;

      INSERT INTO public.ledger_entries (
        id,
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        gen_random_uuid(),
        v_wallet.id,
        v_caller_id,
        v_table.entry_fee,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        p_table_id,
        'game_tables',
        'game_table',
        v_wallet.available_balance + v_table.entry_fee,
        v_wallet.available_balance + v_table.entry_fee,
        GREATEST(0.00, v_wallet.held_balance - v_table.entry_fee),
        v_effective_idempotency || '_refund',
        'Reembolso por abandonar mesa antes del inicio',
        NOW()
      );

      v_refund_amount := v_table.entry_fee;
    END IF;
  END IF;

  -- 5. Contar jugadores restantes
  SELECT COUNT(DISTINCT user_id) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

  -- 6. Si la partida estaba activa
  IF v_session_is_active THEN
    IF v_active_players_count = 1 THEN
      SELECT user_id INTO v_remaining_player
      FROM public.game_table_players
      WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum
      LIMIT 1;

      IF v_remaining_player.user_id IS NOT NULL THEN
        v_settle_result := public.universal_settle_game_session(
          v_session.id,
          ARRAY[v_remaining_player.user_id],
          NULL,
          'forfeit_' || v_session.id::text || '_' || v_remaining_player.user_id::text
        );
      END IF;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;
    ELSIF v_active_players_count = 0 THEN
      -- Si ya no queda ningún jugador, reembolsar íntegramente
      PERFORM public.refund_game_session(
        v_session.id,
        'Abandono de todos los jugadores',
        v_effective_idempotency || '_all_abandon_refund'
      );
    END IF;
  ELSE
    -- Mesa en lobby
    IF v_active_players_count = 0 THEN
      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          current_players_count = 0,
          updated_at = NOW()
      WHERE id = p_table_id;
    ELSE
      UPDATE public.game_tables
      SET current_players_count = v_active_players_count,
          updated_at = NOW()
      WHERE id = p_table_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refund_amount', v_refund_amount,
    'remaining_players', v_active_players_count
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role, anon;

-- ABANDONO UNIVERSAL POR SESIÓN: abandon_game_secure
CREATE OR REPLACE FUNCTION public.abandon_game_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_game_type TEXT;
  v_opponent_id UUID;
  v_effective_idempotency TEXT;
  v_next_seq INT := 1;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTENTICADO');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || p_session_id::text || '_' || v_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  v_game_type := LOWER(COALESCE(v_table.game_type::text, v_session.game_type::text, ''));

  IF v_session.status::text IN ('FINISHED', 'CANCELLED') THEN
    RETURN jsonb_build_object('success', false, 'error', 'JUEGO_YA_FINALIZADO');
  END IF;

  -- Marcar jugador como ABANDONED
  UPDATE public.game_table_players
  SET status = 'ABANDONED'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_session.table_id
     AND user_id = v_user_id
     AND status::text NOT IN ('ABANDONED', 'LEFT');

  -- Lógica de liquidación por tipo de juego
  IF v_game_type IN ('atrapaito', 'chess', 'checkers', 'tictactoe', 'tic_tac_toe', 'rps', 'rock_paper_scissors', 'domino', 'domino_venezolano', 'truco', 'truco_venezolano', 'una_olla', 'unaolla') THEN
    SELECT user_id INTO v_opponent_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
       AND user_id != v_user_id
       AND status::text NOT IN ('ABANDONED', 'LEFT')
    LIMIT 1;

    IF v_opponent_id IS NOT NULL THEN
      -- Liquidar autoritativamente con el oponente como ganador
      PERFORM public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_opponent_id],
        NULL,
        v_effective_idempotency || '_settle'
      );
    ELSE
      -- Sin oponentes: reembolsar íntegramente
      PERFORM public.refund_game_session(
        p_session_id,
        'Abandono sin oponentes activos',
        v_effective_idempotency || '_refund'
      );
    END IF;
  ELSIF v_game_type = 'bingo' THEN
    -- En Bingo, abandonar solo desmarca al jugador sin alterar el pozo
    UPDATE public.game_sessions
    SET current_state = jsonb_set(
        COALESCE(current_state, '{}'::jsonb),
        '{abandonedPlayers}',
        COALESCE(current_state->'abandonedPlayers', '[]'::jsonb) || to_jsonb(v_user_id::text)
    ),
    updated_at = NOW()
    WHERE id = p_session_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Has abandonado la partida correctamente');
END;
$$;

GRANT EXECUTE ON FUNCTION public.abandon_game_secure(UUID, TEXT) TO authenticated, service_role, anon;

-- 9. CORRECCIÓN DE admin_terminate_game_table PARA DEDUCIR held_balance
CREATE OR REPLACE FUNCTION public.admin_terminate_game_table(
  p_table_id UUID,
  p_reason TEXT DEFAULT 'Terminada por administración',
  p_refund_players BOOLEAN DEFAULT true
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_table RECORD;
  v_player RECORD;
  v_player_wallet RECORD;
  v_refunded_count INT := 0;
  v_refund_amount NUMERIC(14,2);
  v_caller_id UUID;
  v_is_admin BOOLEAN;
  v_player_id UUID;
  v_participants UUID[] := ARRAY[]::UUID[];
BEGIN
  v_caller_id := auth.uid();

  IF v_caller_id IS NOT NULL THEN
    SELECT (
      public.is_admin(v_caller_id) OR 
      public.is_operator_or_above(v_caller_id) OR 
      EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = v_caller_id AND ur.role::text IN ('ADMIN', 'SUPER_ADMIN'))
    ) INTO v_is_admin;

    IF NOT v_is_admin THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'No tiene permisos de administrador para finalizar la mesa.'
      );
    END IF;
  END IF;

  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mesa no encontrada.');
  END IF;

  v_refund_amount := COALESCE(v_table.entry_fee, 0.00);

  IF p_refund_players AND v_refund_amount > 0.00 THEN
    SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_participants
    FROM (
      SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = p_table_id
      UNION
      SELECT user_id AS u_id FROM public.ledger_entries WHERE reference_id = p_table_id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
    ) all_p
    WHERE u_id IS NOT NULL;

    IF v_participants IS NOT NULL THEN
      FOREACH v_player_id IN ARRAY v_participants LOOP
        SELECT * INTO v_player_wallet FROM public.wallets WHERE user_id = v_player_id FOR UPDATE;
        IF FOUND THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_refund_amount,
              held_balance = GREATEST(0.00, held_balance - v_refund_amount),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_refund_amount,
            'VES',
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            p_table_id,
            'game_tables',
            'game_table',
            v_player_wallet.available_balance + v_refund_amount,
            v_player_wallet.available_balance + v_refund_amount,
            GREATEST(0.00, v_player_wallet.held_balance - v_refund_amount),
            'admin_term_' || p_table_id::text || '_' || v_player_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text,
            'Reembolso administrativo por cancelación de mesa: ' || COALESCE(p_reason, 'Cancelación'),
            NOW()
          );

          v_refunded_count := v_refunded_count + 1;
        END IF;
      END LOOP;
    END IF;
  END IF;

  UPDATE public.game_tables
  SET status = 'TERMINATED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = p_table_id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND status != 'LEFT'::player_table_status_enum;

  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id AND status NOT IN ('SETTLED', 'CANCELLED', 'FINISHED');

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refunded_count', v_refunded_count,
    'refund_amount', v_refund_amount,
    'reason', p_reason
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_terminate_game_table(UUID, TEXT, BOOLEAN) TO authenticated, service_role;

-- 10. FUNCIÓN DE CONCILIACIÓN FORENSE Y RESCATE DE SALDOS RETENIDOS HUÉRFANOS
-- Esta función audita y restituye cualquier saldo retenido que pertenezca a partidas o bingos que ya fueron cerrados o terminados.
CREATE OR REPLACE FUNCTION public.audit_and_reconcile_held_balances()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_wallet RECORD;
  v_reconciled_users INT := 0;
  v_total_released NUMERIC(14,2) := 0.00;
  v_active_holds NUMERIC(14,2) := 0.00;
  v_amount_to_release NUMERIC(14,2) := 0.00;
  v_report JSONB := '[]'::jsonb;
BEGIN
  -- Marcar mesas no finalizadas cuyo expires_at ya venció como EXPIRED
  UPDATE public.game_tables
  SET status = 'EXPIRED'::table_status_enum,
      updated_at = NOW()
  WHERE status::text IN ('OPEN', 'FULL', 'WAITING', 'STARTING', 'READY', 'SALES')
    AND expires_at IS NOT NULL
    AND expires_at < NOW();

  FOR v_wallet IN
    SELECT w.*
    FROM public.wallets w
    WHERE w.held_balance > 0.00
    FOR UPDATE
  LOOP
    -- Calcular cuánto saldo retenido corresponde a mesas REALMENTE ACTIVAS Y NO EXPIRADAS
    SELECT COALESCE(SUM(gt.entry_fee), 0.00) INTO v_active_holds
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    WHERE gtp.user_id = v_wallet.user_id
      AND gt.status::text IN ('OPEN', 'FULL', 'WAITING', 'STARTING', 'ACTIVE', 'READY', 'SALES', 'DRAWING')
      AND (gt.expires_at IS NULL OR gt.expires_at > NOW())
      AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING');

    -- Sumar compras de bingo en mesas aún no finalizadas ni expiradas
    v_active_holds := v_active_holds + COALESCE((
      SELECT SUM(bcp.total_cost)
      FROM public.bingo_card_purchases bcp
      JOIN public.game_tables gt ON gt.id = bcp.game_table_id
      WHERE bcp.user_id = v_wallet.user_id
        AND gt.status::text NOT IN ('CLOSED', 'EXPIRED', 'CANCELLED', 'TERMINATED')
        AND (gt.expires_at IS NULL OR gt.expires_at > NOW())
    ), 0.00);

    -- Si el held_balance supera lo que realmente está en juego activo, liberar el excedente huérfano
    IF v_wallet.held_balance > v_active_holds THEN
      v_amount_to_release := v_wallet.held_balance - v_active_holds;

      UPDATE public.wallets
      SET available_balance = available_balance + v_amount_to_release,
          held_balance = v_active_holds,
          updated_at = NOW()
      WHERE id = v_wallet.id;

      INSERT INTO public.ledger_entries (
        id,
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        gen_random_uuid(),
        v_wallet.id,
        v_wallet.user_id,
        v_amount_to_release,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        v_wallet.id,
        'wallets',
        'wallet_reconciliation',
        v_wallet.available_balance + v_amount_to_release,
        v_wallet.available_balance + v_amount_to_release,
        v_active_holds,
        'forensic_reconcile_' || v_wallet.id::text || '_' || EXTRACT(EPOCH FROM NOW())::text,
        'Conciliación forense y restitución de saldo retenido por partidas/bingo finalizados',
        NOW()
      );

      v_reconciled_users := v_reconciled_users + 1;
      v_total_released := v_total_released + v_amount_to_release;

      v_report := v_report || jsonb_build_object(
        'user_id', v_wallet.user_id,
        'released_amount', v_amount_to_release,
        'remaining_held', v_active_holds
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'reconciled_users_count', v_reconciled_users,
    'total_released_bs', v_total_released,
    'details', v_report
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.audit_and_reconcile_held_balances() TO authenticated, service_role;

-- 11. RECARGA DE ESQUEMA EN POSTGREST
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 147: 144_fix_rps_current_state_null_and_jsonb_safety.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ===============================================================================
-- MIGRACIÓN 144: Corrección Forense de RPS (current_state = NULL) y Blindaje JSONB
-- Proyecto: RASPANDO LA OLLA 🇻🇪 (PulsoPLAY)
-- Estado: SAFE_DEVELOPMENT_MODE = true
-- ===============================================================================
--
-- DIAGNÓSTICO Y CAUSA RAÍZ TÉCNICA:
-- 1. En PostgreSQL, la función nativa `jsonb_set(target, path, new_value)` retorna SQL NULL
--    si CUALQUIERA de sus argumentos es NULL.
-- 2. En `submit_rps_choice_secure` (migraciones 140, 141 y 142), las líneas:
--      v_new_state := jsonb_set(v_new_state, '{roundWinnerUserId}', to_jsonb(v_round_winner_user_id));
--      v_new_state := jsonb_set(v_new_state, '{matchWinner}', to_jsonb(v_match_winner));
--      v_new_state := jsonb_set(v_new_state, '{winnerUserId}', to_jsonb(v_winner_user_id));
--    evaluaban `to_jsonb(NULL)`. En PostgreSQL, `to_jsonb(NULL::text)` y `to_jsonb(NULL::uuid)`
--    retornan SQL NULL (no `'null'::jsonb`).
--    Al pasar SQL NULL como tercer argumento a `jsonb_set`, `jsonb_set` retorna SQL NULL.
--    Esto corrompía `v_new_state` a NULL en cualquier ronda donde no hubiese finalizado el partido
--    (donde matchWinner y winnerUserId son NULL) o en empates (roundWinnerUserId es NULL).
-- 3. Al ejecutar seguidamente:
--      UPDATE public.game_sessions SET current_state = v_new_state ...
--    PostgreSQL arrojaba la excepción fatal observada en producción:
--      "null value in column \"current_state\" of relation \"game_sessions\" violates not-null constraint"
-- 4. Vulnerabilidad secundaria en commits individuales (ELSE branch): Si `current_state->'playerChoices'`
--    era scalar JSON null (`'null'::jsonb`), `jsonb_set` fallaba con "cannot set path in scalar",
--    o si `v_session.current_state` no estaba inicializado como objeto, `v_new_state` se degradaba a NULL.
--
-- SOLUCIÓN ARQUITECTÓNICA Y REGLAS DE BLINDAJE:
-- 1. Reemplazar el encadenamiento frágil de `jsonb_set` por construcción declarativa e inmutable
--    con `jsonb_build_object` y el operador de fusión JSONB `||`:
--    `v_new_state := v_base_state || jsonb_build_object('roundWinnerUserId', v_round_winner_user_id, ...)`
--    En PostgreSQL, `jsonb_build_object('key', NULL)` genera válidamente `{"key": null}` (JSON null)
--    y NUNCA retorna SQL NULL.
-- 2. Blindaje con `COALESCE(v_session.current_state, '{}'::jsonb)` y validación `jsonb_typeof() = 'object'`
--    para asegurar que el estado base siempre sea un objeto JSON válido.
-- 3. Redundancia de seguridad: `IF v_new_state IS NULL THEN v_new_state := '{}'::jsonb; END IF;`
--    antes de cada UPDATE.
-- 4. Preservar estrictamente la arquitectura simultánea (COMMIT-REVEAL) de RPS sin turnos secuenciales
--    (`current_turn_user_id = NULL`).
-- 5. Integración con `public.universal_settle_game_session` para liquidación financiera centralizada.
-- ===============================================================================

-- 1. RPC: SUBMIT_RPS_CHOICE_SECURE (BLINDADA CONTRA NULL Y CORRUPCIÓN JSONB)
CREATE OR REPLACE FUNCTION public.submit_rps_choice_secure(
  p_session_id UUID,
  p_choice VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_user_id UUID;
  v_norm_choice VARCHAR;
  v_session RECORD;
  v_secret_row RECORD;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_secret_choices JSONB;
  v_secret_state JSONB;
  v_base_state JSONB;
  v_c1 TEXT;
  v_c2 TEXT;
  v_round_winner TEXT;
  v_round_winner_user_id UUID;
  v_p1_lives INT;
  v_p2_lives INT;
  v_match_winner TEXT;
  v_winner_user_id UUID;
  v_is_game_over BOOLEAN := false;
  v_new_state JSONB;
  v_history_entry JSONB;
  v_new_history JSONB;
  v_player_choices JSONB;
  v_curr_round INT;
  v_generated_seed VARCHAR(64);
BEGIN
  -- 1. Validar autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    BEGIN
      v_user_id := NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_user_id := NULL;
    END;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'AUTH_REQUIRED');
  END IF;

  -- Normalizar y validar jugada
  v_norm_choice := UPPER(TRIM(p_choice));
  IF v_norm_choice NOT IN ('ROCK', 'PAPER', 'SCISSORS') THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_CHOICE', 'valid', ARRAY['ROCK', 'PAPER', 'SCISSORS']);
  END IF;

  -- 2. Obtener y bloquear la sesión de juego
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  -- Blindaje de estado base: nunca NULL, nunca escalar
  v_base_state := COALESCE(v_session.current_state, '{}'::jsonb);
  IF jsonb_typeof(v_base_state) != 'object' THEN
    v_base_state := '{}'::jsonb;
  END IF;

  -- 3. Obtener o crear de forma segura el registro de secretos
  SELECT * INTO v_secret_row
  FROM public.game_session_secrets
  WHERE session_id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    BEGIN
      v_generated_seed := encode(extensions.gen_random_bytes(32), 'hex');
    EXCEPTION WHEN OTHERS THEN
      v_generated_seed := encode(public.gen_random_bytes(32), 'hex');
    END;

    INSERT INTO public.game_session_secrets (session_id, secret_state, server_seed)
    VALUES (p_session_id, '{}'::jsonb, v_generated_seed)
    RETURNING * INTO v_secret_row;
  END IF;

  v_secret_state := COALESCE(v_secret_row.secret_state, '{}'::jsonb);
  IF jsonb_typeof(v_secret_state) != 'object' THEN
    v_secret_state := '{}'::jsonb;
  END IF;

  -- 4. IDENTIFICAR JUGADORES 1 Y 2 DE FORMA CANÓNICA Y DETERMINISTA
  -- Prioridad 1: IDs registrados en el JSONB current_state de la partida
  v_p1_id := NULLIF(TRIM(v_base_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_base_state->>'player2Id'), '');

  -- Prioridad 2: Si falta player1Id, consultar game_table_players ordenado por seat_number y joined_at
  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Prioridad 3: Si falta player2Id, consultar el siguiente asiento activo
  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Validar que ambos jugadores existen
  IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_PLAYERS_IN_SESSION');
  END IF;

  -- Validar que el usuario actual pertenece a la partida
  IF v_user_id::text != v_p1_id AND v_user_id::text != v_p2_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_A_PLAYER_IN_THIS_MATCH');
  END IF;

  -- Validar que estemos en fase de selección (ROUND_COMMIT / selecting)
  IF COALESCE(v_base_state->>'status', 'ROUND_COMMIT') NOT IN ('ROUND_COMMIT', 'selecting') AND
     COALESCE(v_base_state->>'phase', 'selecting') NOT IN ('ROUND_COMMIT', 'selecting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ROUND_NOT_ACCEPTING_CHOICES');
  END IF;

  -- 5. ANTI-DOUBLE-SUBMIT: Verificar si el jugador ya comprometió su jugada
  v_secret_choices := COALESCE(v_secret_state->'rps_choices', '{}'::jsonb);
  IF jsonb_typeof(v_secret_choices) != 'object' THEN
    v_secret_choices := '{}'::jsonb;
  END IF;

  IF (v_secret_choices ? v_user_id::text AND v_secret_choices->>v_user_id::text IS NOT NULL) OR
     (COALESCE((v_base_state->'playerChoices'->(v_user_id::text)->>'committed')::boolean, false) IS TRUE) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'ALREADY_COMMITTED',
      'message', 'Ya has enviado tu jugada para esta ronda'
    );
  END IF;

  -- 6. Guardar la jugada privada en game_session_secrets mediante fusión atómica
  v_secret_choices := v_secret_choices || jsonb_build_object(v_user_id::text, v_norm_choice);

  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', v_secret_choices),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  -- 7. Comprobar si ambos jugadores han comprometido su jugada
  v_c1 := v_secret_choices->>v_p1_id;
  v_c2 := v_secret_choices->>v_p2_id;

  IF v_c1 IS NOT NULL AND v_c2 IS NOT NULL THEN
    -- =========================================================================
    -- AMBOS JUGADORES HAN ELEGIDO: REVELACIÓN ATÓMICA Y DETERMINACIÓN DE RONDA
    -- =========================================================================

    -- Determinar ganador de la ronda
    IF v_c1 = v_c2 THEN
      v_round_winner := 'DRAW';
      v_round_winner_user_id := NULL;
    ELSIF (v_c1 = 'ROCK' AND v_c2 = 'SCISSORS') OR
          (v_c1 = 'PAPER' AND v_c2 = 'ROCK') OR
          (v_c1 = 'SCISSORS' AND v_c2 = 'PAPER') THEN
      v_round_winner := 'PLAYER1';
      v_round_winner_user_id := v_p1_id::uuid;
    ELSE
      v_round_winner := 'PLAYER2';
      v_round_winner_user_id := v_p2_id::uuid;
    END IF;

    -- Obtener y actualizar vidas (Mejor de 3 vidas)
    v_p1_lives := COALESCE((v_base_state->>'player1Lives')::int, 3);
    v_p2_lives := COALESCE((v_base_state->>'player2Lives')::int, 3);

    IF v_round_winner = 'PLAYER1' THEN
      v_p2_lives := GREATEST(0, v_p2_lives - 1);
    ELSIF v_round_winner = 'PLAYER2' THEN
      v_p1_lives := GREATEST(0, v_p1_lives - 1);
    END IF;

    -- Comprobar si la partida completa finalizó
    IF v_p1_lives <= 0 THEN
      v_match_winner := 'PLAYER2';
      v_winner_user_id := v_p2_id::uuid;
      v_is_game_over := true;
    ELSIF v_p2_lives <= 0 THEN
      v_match_winner := 'PLAYER1';
      v_winner_user_id := v_p1_id::uuid;
      v_is_game_over := true;
    ELSE
      v_match_winner := NULL;
      v_winner_user_id := NULL;
      v_is_game_over := false;
    END IF;

    v_curr_round := COALESCE((v_base_state->>'roundNumber')::int, (v_base_state->>'round')::int, 1);

    v_history_entry := jsonb_build_object(
      'roundNumber', v_curr_round,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'winner', v_round_winner,
      'winnerUserId', v_round_winner_user_id,
      'timestamp', FLOOR(EXTRACT(EPOCH FROM NOW()) * 1000)
    );

    v_new_history := COALESCE(
      CASE WHEN jsonb_typeof(v_base_state->'history') = 'array' THEN v_base_state->'history' ELSE '[]'::jsonb END,
      '[]'::jsonb
    ) || v_history_entry;

    -- Construir nuevo estado público revelado usando jsonb_build_object (inmune a NULL)
    v_new_state := v_base_state || jsonb_build_object(
      'player1Id', v_p1_id,
      'player2Id', v_p2_id,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'player1Lives', v_p1_lives,
      'player2Lives', v_p2_lives,
      'lives', jsonb_build_object(v_p1_id, v_p1_lives, v_p2_id, v_p2_lives),
      'roundWinner', v_round_winner,
      'roundWinnerUserId', v_round_winner_user_id,
      'matchWinner', v_match_winner,
      'winnerUserId', v_winner_user_id,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'phase', CASE WHEN v_is_game_over THEN 'match_ended' ELSE 'round_result' END,
      'history', v_new_history,
      'currentTurnUserId', NULL::uuid,
      'turnUserId', NULL::uuid,
      'roundNumber', v_curr_round,
      'round', v_curr_round,
      'playerChoices', jsonb_build_object(
        v_p1_id, jsonb_build_object('committed', true, 'choice', v_c1),
        v_p2_id, jsonb_build_object('committed', true, 'choice', v_c2)
      )
    );

    -- Doble blindaje: el estado nunca puede ser NULL
    IF v_new_state IS NULL THEN
      v_new_state := '{}'::jsonb;
    END IF;

    -- Actualizar sesión pública: current_turn_user_id permanece NULL para RPS (juego simultáneo)
    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        winner_user_id = v_winner_user_id,
        turn_expires_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        turn_deadline_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        ended_at = CASE WHEN v_is_game_over THEN NOW() ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Si terminó la partida, liquidar mediante libro mayor contable universal
    -- (universal_settle_game_session se encarga de actualizar el status a FINISHED, cerrar la mesa y transferir fondos)
    IF v_is_game_over THEN
      PERFORM public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_user_id],
        NULL::int,
        'rps_match_' || p_session_id::text
      );
    END IF;

    -- Registrar acción inmutable en game_actions
    INSERT INTO public.game_actions (
      session_id,
      user_id,
      sequence_number,
      action_type,
      payload,
      is_valid,
      server_state_hash,
      idempotency_key
    ) VALUES (
      p_session_id,
      v_user_id,
      COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
      'ROUND_REVEAL',
      jsonb_build_object(
        'round', v_curr_round,
        'player1Choice', v_c1,
        'player2Choice', v_c2,
        'roundWinner', v_round_winner,
        'isGameOver', v_is_game_over
      ),
      true,
      md5(v_new_state::text),
      'rps_reveal_' || p_session_id::text || '_rnd_' || v_curr_round::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'isGameOver', v_is_game_over,
      'winnerUserId', v_winner_user_id,
      'roundWinner', v_round_winner,
      'roundWinnerUserId', v_round_winner_user_id,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'bothChosen', true
    );

  ELSE
    -- =========================================================================
    -- SOLO UNO HA ELEGIDO: REGISTRAR COMMIT PROTEGIENDO EL SECRETO DEL JUGADOR
    -- =========================================================================
    v_player_choices := CASE
      WHEN v_base_state->'playerChoices' IS NOT NULL AND jsonb_typeof(v_base_state->'playerChoices') = 'object'
      THEN v_base_state->'playerChoices'
      ELSE '{}'::jsonb
    END;

    v_player_choices := v_player_choices || jsonb_build_object(
      v_user_id::text,
      jsonb_build_object('committed', true)
    );

    v_new_state := v_base_state || jsonb_build_object(
      'player1Id', v_p1_id,
      'player2Id', v_p2_id,
      'playerChoices', v_player_choices,
      'player1Choice', NULL::text,
      'player2Choice', NULL::text,
      'status', 'ROUND_COMMIT',
      'phase', 'selecting',
      'currentTurnUserId', NULL::uuid,
      'turnUserId', NULL::uuid
    );

    -- Doble blindaje: el estado nunca puede ser NULL
    IF v_new_state IS NULL THEN
      v_new_state := '{}'::jsonb;
    END IF;

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'status', 'ROUND_COMMIT',
      'isGameOver', false,
      'bothChosen', false,
      'committed', true
    );
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) TO authenticated, anon, service_role;

-- 2. RPC: NEXT_RPS_ROUND_SECURE (REINICIO ATÓMICO Y BLINDADO)
CREATE OR REPLACE FUNCTION public.next_rps_round_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_session RECORD;
  v_base_state JSONB;
  v_curr_round INT;
  v_new_round INT;
  v_new_state JSONB;
  v_p1_id TEXT;
  v_p2_id TEXT;
BEGIN
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status::text NOT IN ('ACTIVE', 'active') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  v_base_state := COALESCE(v_session.current_state, '{}'::jsonb);
  IF jsonb_typeof(v_base_state) != 'object' THEN
    v_base_state := '{}'::jsonb;
  END IF;

  -- Solo avanzar si estaba en fase de resultado de ronda
  IF COALESCE(v_base_state->>'status', '') != 'ROUND_REVEAL' AND
     COALESCE(v_base_state->>'phase', '') != 'round_result' THEN
    RETURN jsonb_build_object('success', true, 'message', 'ALREADY_ADVANCED');
  END IF;

  v_curr_round := COALESCE((v_base_state->>'roundNumber')::int, (v_base_state->>'round')::int, 1);
  v_new_round := v_curr_round + 1;

  -- Identificar jugadores de forma determinista
  v_p1_id := NULLIF(TRIM(v_base_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_base_state->>'player2Id'), '');

  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status NOT IN ('LEFT')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Construir nuevo estado para la siguiente ronda de forma inmune a NULL
  v_new_state := v_base_state || jsonb_build_object(
    'player1Id', v_p1_id,
    'player2Id', v_p2_id,
    'roundNumber', v_new_round,
    'round', v_new_round,
    'player1Choice', NULL::text,
    'player2Choice', NULL::text,
    'roundWinner', NULL::text,
    'roundWinnerUserId', NULL::uuid,
    'status', 'ROUND_COMMIT',
    'phase', 'selecting',
    'currentTurnUserId', NULL::uuid,
    'turnUserId', NULL::uuid,
    'playerChoices', jsonb_build_object(
      COALESCE(v_p1_id, 'player1'), jsonb_build_object('committed', false),
      COALESCE(v_p2_id, 'player2'), jsonb_build_object('committed', false)
    )
  );

  IF v_new_state IS NULL THEN
    v_new_state := '{}'::jsonb;
  END IF;

  UPDATE public.game_sessions
  SET current_state = v_new_state,
      current_turn_user_id = NULL,
      turn_expires_at = NOW() + INTERVAL '15 seconds',
      turn_deadline_at = NOW() + INTERVAL '15 seconds',
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Limpiar cualquier secreto residual de la ronda previa
  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', '{}'::jsonb),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  RETURN jsonb_build_object('success', true, 'round', v_new_round);
END;
$$;

GRANT EXECUTE ON FUNCTION public.next_rps_round_secure(UUID) TO authenticated, anon, service_role;

-- 3. ACTUALIZACIÓN DE PROCESS_EXPIRED_TURNS (BLINDAJE DE CURRENT_STATE ANTE TIMEOUTS)
CREATE OR REPLACE FUNCTION public.process_expired_turns()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_expired_row RECORD;
  v_p1_id UUID;
  v_p2_id UUID;
  v_p1_committed BOOLEAN;
  v_p2_committed BOOLEAN;
  v_winner_id UUID;
  v_loser_id UUID;
  v_secret_choices JSONB;
  v_idempotency_key VARCHAR(100);
  v_curr_round INT;
  v_new_state JSONB;
BEGIN
  -- ---------------------------------------------------------------------------
  -- A. PROCESAMIENTO DE EXPIRACIONES PARA JUEGOS SECUENCIALES (DOMINÓ, TRUCO, ETC.)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_turn_user_id, t.game_type, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND s.current_turn_user_id IS NOT NULL
      AND t.game_type::text NOT IN ('rock_paper_scissors', 'rps', 'PIEDRA_PAPEL_TIJERA')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      v_idempotency_key := 'seq_timeout_' || v_expired_row.id::text || '_' || v_expired_row.current_turn_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::int::text;
      PERFORM public.record_turn_timeout_secure(
        v_expired_row.id,
        v_expired_row.current_turn_user_id,
        v_idempotency_key
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en juego secuencial %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;

  -- ---------------------------------------------------------------------------
  -- B. PROCESAMIENTO DE EXPIRACIONES PARA PIEDRA, PAPEL O TIJERA (ROUND_DEADLINE)
  -- ---------------------------------------------------------------------------
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_state, s.created_at, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active')
      AND t.game_type::text IN ('rock_paper_scissors', 'rps', 'PIEDRA_PAPEL_TIJERA')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
      AND COALESCE(s.current_state->>'status', '') IN ('ROUND_COMMIT', 'selecting')
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      v_curr_round := COALESCE((v_expired_row.current_state->>'roundNumber')::int, 1);
      v_idempotency_key := 'rps_timeout_' || v_expired_row.id::text || '_rnd_' || v_curr_round::text;

      -- Identificar jugadores de forma determinista sin created_at
      v_p1_id := NULLIF(TRIM(v_expired_row.current_state->>'player1Id'), '')::uuid;
      v_p2_id := NULLIF(TRIM(v_expired_row.current_state->>'player2Id'), '')::uuid;

      IF v_p1_id IS NULL THEN
        SELECT user_id INTO v_p1_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;

      IF v_p2_id IS NULL THEN
        SELECT user_id INTO v_p2_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND user_id != v_p1_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;

      -- Consultar compromisos registrados
      SELECT secret_state->'rps_choices' INTO v_secret_choices
      FROM public.game_session_secrets
      WHERE session_id = v_expired_row.id;

      v_p1_committed := (v_secret_choices ? v_p1_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p1_id::text)->>'committed')::boolean, false);
      v_p2_committed := (v_secret_choices ? v_p2_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p2_id::text)->>'committed')::boolean, false);

      IF v_p1_committed AND NOT v_p2_committed THEN
        v_winner_id := v_p1_id;
        v_loser_id := v_p2_id;
      ELSIF v_p2_committed AND NOT v_p1_committed THEN
        v_winner_id := v_p2_id;
        v_loser_id := v_p1_id;
      ELSE
        v_winner_id := NULL;
        v_loser_id := NULL;
      END IF;

      IF v_winner_id IS NOT NULL THEN
        -- Victoria por abandono/timeout del oponente: actualización inmune a NULL
        v_new_state := COALESCE(v_expired_row.current_state, '{}'::jsonb) || jsonb_build_object(
          'winnerUserId', v_winner_id,
          'abandonedBy', v_loser_id,
          'status', 'MATCH_ENDED',
          'phase', 'match_ended'
        );

        UPDATE public.game_sessions
        SET current_state = v_new_state,
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        PERFORM public.universal_settle_game_session(
          v_expired_row.id,
          ARRAY[v_winner_id],
          NULL::int,
          v_idempotency_key
        );
      ELSE
        -- Ninguno eligió dentro del plazo: Cancelación y reembolso seguro al 100%
        v_new_state := COALESCE(v_expired_row.current_state, '{}'::jsonb) || jsonb_build_object(
          'cancelReason', 'ROUND_TIMEOUT_NO_CHOICES',
          'status', 'MATCH_CANCELLED'
        );

        UPDATE public.game_sessions
        SET current_state = v_new_state,
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        PERFORM public.refund_game_session(
          v_expired_row.id,
          'Tiempo de ronda agotado sin jugadas de ningún participante',
          v_idempotency_key
        );
      END IF;

    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en ronda simultánea RPS %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.process_expired_turns() TO authenticated, anon, service_role, postgres;

COMMENT ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) IS 
'Registra jugadas en RPS mediante Commit-Reveal autoritativo en Supabase. Blindado contra NULL en current_state.';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 148: 145_central_game_availability_control.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 145: CONTROL CENTRAL DE DISPONIBILIDAD DE JUEGOS
-- ==============================================================================
-- 1. Tabla canónica public.game_configurations
-- 2. Sincronización automática is_active = enabled
-- 3. Población inicial de los 10 juegos soportados
-- 4. Función de comprobación rápida public.is_game_enabled(TEXT)
-- 5. RPC Administrativa public.admin_set_game_enabled(TEXT, BOOLEAN, TEXT)
-- 6. Configuración Realtime (REPLICA IDENTITY FULL y publicación supabase_realtime)
-- 7. Políticas de Seguridad RLS
-- 8. Protección en RPCs operativas (create_game_table_secure, join_table_transaction, start_game_session_secure)
-- ==============================================================================

-- 1. TABLA CANÓNICA DE CONFIGURACIÓN Y ESTADO OPERATIVO DE JUEGOS
CREATE TABLE IF NOT EXISTS public.game_configurations (
  game_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  short_description TEXT,
  icon_name TEXT DEFAULT 'Gamepad2',
  enabled BOOLEAN NOT NULL DEFAULT true,
  is_active BOOLEAN NOT NULL DEFAULT true,
  disabled_reason TEXT DEFAULT NULL,
  disabled_at TIMESTAMPTZ DEFAULT NULL,
  disabled_by UUID DEFAULT NULL,
  maintenance_message TEXT DEFAULT NULL,
  min_players SMALLINT NOT NULL DEFAULT 2,
  max_players SMALLINT NOT NULL DEFAULT 2,
  allowed_modes TEXT[] DEFAULT ARRAY['1v1']::TEXT[],
  min_entry_fee NUMERIC(10,2) NOT NULL DEFAULT 25.00,
  max_entry_fee NUMERIC(10,2) NOT NULL DEFAULT 5000.00,
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  display_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Asegurar columnas por si la tabla fue creada previamente con columnas faltantes
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS enabled BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS disabled_reason TEXT DEFAULT NULL;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS disabled_at TIMESTAMPTZ DEFAULT NULL;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS disabled_by UUID DEFAULT NULL;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS maintenance_message TEXT DEFAULT NULL;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS min_players SMALLINT NOT NULL DEFAULT 2;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS max_players SMALLINT NOT NULL DEFAULT 2;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS allowed_modes TEXT[] DEFAULT ARRAY['1v1']::TEXT[];
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS min_entry_fee NUMERIC(10,2) NOT NULL DEFAULT 25.00;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS max_entry_fee NUMERIC(10,2) NOT NULL DEFAULT 5000.00;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS config JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS display_order INT NOT NULL DEFAULT 0;
ALTER TABLE public.game_configurations ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

-- 2. TRIGGER PARA MANTENER SINCRONIZADOS enabled Y is_active
CREATE OR REPLACE FUNCTION public.sync_game_configuration_enabled_status()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.enabled IS DISTINCT FROM OLD.enabled THEN
    NEW.is_active := NEW.enabled;
  ELSIF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    NEW.enabled := NEW.is_active;
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_game_configuration_enabled_status ON public.game_configurations;
CREATE TRIGGER trg_sync_game_configuration_enabled_status
BEFORE UPDATE ON public.game_configurations
FOR EACH ROW
EXECUTE FUNCTION public.sync_game_configuration_enabled_status();

