-- 1. TABLA CANÓNICA DE HISTORIAL PÚBLICO DE PARTIDAS (REALTIME)
-- Corrige el error HTTP 404 en /rest/v1/public_match_history
-- Se utilizan columnas UUID directas sin restricciones de bloqueo externo para evitar esperas de bloqueo
CREATE TABLE IF NOT EXISTS public.public_match_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  game_type TEXT NOT NULL,
  table_id UUID NOT NULL,
  session_id UUID NOT NULL,
  winner_user_id UUID NULL,
  winner_name_snapshot TEXT NOT NULL,
  winner_avatar_snapshot TEXT NULL,
  players_snapshot JSONB NOT NULL DEFAULT '[]'::jsonb,
  final_score JSONB NOT NULL DEFAULT '{}'::jsonb,
  victories JSONB NOT NULL DEFAULT '{}'::jsonb,
  result_summary TEXT NOT NULL,
  finished_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_public_match_history_finished ON public.public_match_history(finished_at DESC);
CREATE INDEX IF NOT EXISTS idx_public_match_history_game ON public.public_match_history(game_type);

ALTER TABLE public.public_match_history ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS p_public_match_history_select ON public.public_match_history;
CREATE POLICY p_public_match_history_select ON public.public_match_history
  FOR SELECT TO anon, authenticated, service_role USING (true);

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables 
      WHERE pubname = 'supabase_realtime' AND tablename = 'public_match_history'
    ) THEN
      ALTER PUBLICATION supabase_realtime ADD TABLE public.public_match_history;
    END IF;
  END IF;
END $$;

-- 2. CORRECCIÓN DE AGREGACIÓN SQL EN GET_ACTIVE_TOURNAMENTS
-- Corrige el error HTTP 400 provocado por ORDER BY externo sin GROUP BY
CREATE OR REPLACE FUNCTION public.get_active_tournaments()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_tournaments JSONB;
BEGIN
  SELECT COALESCE(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', id,
          'name', name,
          'description', description,
          'game_type', game_type,
          'game_variant', game_variant,
          'entry_fee', entry_fee,
          'prize_pool', prize_pool,
          'max_participants', max_participants,
          'current_participants', current_participants,
          'start_date', start_date,
          'end_date', end_date,
          'registration_deadline', registration_deadline,
          'status', status,
          'prize_distribution', prize_distribution
        ) ORDER BY start_date ASC
      )
      FROM public.tournaments
      WHERE status IN ('REGISTRATION', 'ACTIVE')
    ),
    '[]'::jsonb
  ) INTO v_tournaments;

  RETURN jsonb_build_object('success', true, 'tournaments', v_tournaments);
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_active_tournaments() TO anon, authenticated, service_role;

-- 3. ELIMINAR SOBRECARGAS OBSOLETAS DE START_GAME_SESSION_SECURE
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, INT);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, INTEGER);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, INTEGER, UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, INT, UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INT);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INTEGER);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INT, UUID);
DROP FUNCTION IF EXISTS public.start_game_session_secure(UUID, JSONB, INTEGER, UUID);

-- 4. RECREACIÓN CANÓNICA AUTORITATIVA DE START_GAME_SESSION_SECURE
-- Erradica definitivamente:
-- a) 'column p.full_name does not exist' -> Utiliza columnas canónicas reales de profiles
-- b) Join erróneo por p.id -> Conecta canónicamente por p.user_id = gtp.user_id
-- c) Inserción en columnas inexistentes de game_sessions (game_id, game_state, turn_user_id)
-- d) Intento de asignación 'IN_GAME'::table_status_enum (utiliza 'ACTIVE'::table_status_enum)
-- e) Intento de actualización de columna inexistente game_started en game_tables
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id UUID,
  p_initial_state JSONB DEFAULT NULL,
  p_turn_duration_seconds INTEGER DEFAULT 30,
  p_initial_turn_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_table RECORD;
  v_session RECORD;
  v_players JSONB;
  v_unique_players INT;
  v_game_type TEXT;
  v_session_status TEXT;
  v_initial_state JSONB;
  v_host_id UUID;
  v_effective_turn_user_id UUID;
  v_deadline TIMESTAMPTZ;
  v_session_number INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NO_AUTENTICADO: Debes iniciar sesión para comenzar la partida.';
  END IF;

  -- 1. Bloquear y obtener la mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MESA_NO_ENCONTRADA: La mesa especificada no existe.';
  END IF;

  -- BLOQUEO DE SEGURIDAD BACKEND: VERIFICAR DISPONIBILIDAD DEL JUEGO
  IF NOT public.is_game_enabled(v_table.game_type::text) THEN
    RAISE EXCEPTION 'GAME_DISABLED: Este juego se encuentra temporalmente deshabilitado por el administrador.';
  END IF;

  -- Obtener host de manera segura soportando host_user_id y created_by
  v_host_id := COALESCE(
    (to_jsonb(v_table)->>'host_user_id')::uuid,
    (to_jsonb(v_table)->>'created_by')::uuid
  );

  IF v_host_id IS NOT NULL AND v_host_id != v_user_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = p_table_id AND user_id = v_user_id AND status::text IN ('JOINED', 'READY', 'PLAYING')
    ) THEN
      RAISE EXCEPTION 'NO_AUTORIZADO: Solo el creador o un jugador activo de la mesa puede iniciarla.';
    END IF;
  END IF;

  -- 2. Recolectar jugadores activos uniendo por user_id y utilizando columnas canónicas garantizadas
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', gtp.user_id,
      'user_id', gtp.user_id,
      'seat', gtp.seat_number,
      'seat_number', gtp.seat_number,
      'name', COALESCE(p.display_name, p.nombre_real, NULLIF(TRIM(p.first_name || ' ' || p.last_name), ''), 'Jugador ' || gtp.seat_number),
      'username', COALESCE(p.display_name, 'jugador_' || gtp.seat_number),
      'avatar', p.avatar_url,
      'avatar_url', p.avatar_url,
      'score', 0,
      'status', 'ACTIVE'
    ) ORDER BY gtp.seat_number ASC
  )
  INTO v_players
  FROM public.game_table_players gtp
  LEFT JOIN public.profiles p ON p.user_id = gtp.user_id
  WHERE gtp.table_id = p_table_id
    AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING');

  v_unique_players := COALESCE(jsonb_array_length(v_players), 0);

  IF v_unique_players < 1 THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: No hay jugadores activos en la mesa.';
  END IF;

  -- Para juegos multijugador competitivos, requerir al menos 2 jugadores excepto en Bingo, Polla, Modo Práctica o IA
  IF v_unique_players < 2 
     AND lower(v_table.game_type::text) NOT IN ('bingo', 'bingo_75', 'bingo_90', 'polla', 'polla_venezolana')
     AND COALESCE((v_table.config->>'isPractice')::boolean, false) IS NOT TRUE
     AND COALESCE((p_initial_state->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND COALESCE((v_table.config->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND v_table.min_players > 1
  THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: Se requieren al menos % jugadores para iniciar la partida (actualmente hay %).', v_table.min_players, v_unique_players;
  END IF;

  -- 3. Idempotencia estricta: Verificar si ya existe una sesión activa
  SELECT * INTO v_session FROM public.game_sessions 
  WHERE table_id = p_table_id 
    AND status::text NOT IN ('FINISHED', 'CANCELLED', 'SETTLED', 'ABANDONED')
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'alreadyActive', true,
      'already_active', true,
      'source', 'existing_db_session',
      'sessionId', v_session.id,
      'session_id', v_session.id,
      'tableId', p_table_id,
      'table_id', p_table_id,
      'status', v_session.status::text,
      'currentTurnUserId', v_session.current_turn_user_id,
      'current_turn_user_id', v_session.current_turn_user_id,
      'turnUserId', v_session.current_turn_user_id,
      'turnDeadlineAt', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turn_deadline_at', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turnDeadline', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'gameState', v_session.current_state,
      'game_state', v_session.current_state,
      'players', v_players
    );
  END IF;

  -- 4. Resolver tipo de juego, turno inicial y deadline
  v_game_type := lower(v_table.game_type::text);
  v_effective_turn_user_id := COALESCE(
    p_initial_turn_user_id,
    (p_initial_state->>'turnUserId')::uuid,
    (p_initial_state->>'currentTurnUserId')::uuid
  );

  IF v_effective_turn_user_id IS NULL AND v_players IS NOT NULL AND jsonb_array_length(v_players) > 0 THEN
    v_effective_turn_user_id := (v_players->0->>'user_id')::uuid;
  END IF;

  v_deadline := CASE 
    WHEN p_turn_duration_seconds > 0 
    THEN NOW() + (p_turn_duration_seconds || ' seconds')::interval 
    ELSE NULL 
  END;

  -- 5. Determinar estado inicial y estado de sesión
  IF v_game_type IN ('bingo', 'bingo_75', 'bingo_90') THEN
    v_session_status := 'WAITING';
    v_initial_state := jsonb_build_object(
      'status', 'SALES',
      'variant', COALESCE((to_jsonb(v_table)->>'game_variant'), '90'),
      'mode', COALESCE(((to_jsonb(v_table)->'config')->>'mode')::int, 90),
      'hostUserId', v_host_id,
      'seed', floor(random() * 1000000000)::int,
      'cards', '{}'::jsonb,
      'cardsPurchased', '{}'::jsonb,
      'playerNames', '{}'::jsonb,
      'drawnBalls', '[]'::jsonb,
      'currentBall', NULL,
      'callIntervalMs', 4000,
      'totalBalls', CASE WHEN COALESCE((to_jsonb(v_table)->>'game_variant'), '90') = '75' THEN 75 ELSE 90 END
    );
    IF p_initial_state IS NOT NULL AND jsonb_typeof(p_initial_state) = 'object' AND p_initial_state <> '{}'::jsonb THEN
      v_initial_state := v_initial_state || p_initial_state;
    END IF;
  ELSE
    v_session_status := 'ACTIVE';
    IF p_initial_state IS NOT NULL AND jsonb_typeof(p_initial_state) = 'object' AND p_initial_state <> '{}'::jsonb THEN
      v_initial_state := p_initial_state;
    ELSE
      v_initial_state := jsonb_build_object(
        'status', 'ACTIVE',
        'gameType', v_game_type,
        'tableId', p_table_id,
        'currentTurn', v_effective_turn_user_id,
        'turnDeadline', v_deadline,
        'round', 1,
        'players', v_players,
        'startedAt', NOW()
      );
    END IF;
  END IF;

  -- Calcular session_number secuencial
  SELECT COALESCE(MAX(session_number), 0) + 1 INTO v_session_number
  FROM public.game_sessions
  WHERE table_id = p_table_id;

  -- 6. Insertar la nueva sesión utilizando columnas canónicas verificadas
  INSERT INTO public.game_sessions (
    table_id,
    game_type,
    session_number,
    status,
    current_state,
    current_turn_user_id,
    turn_deadline_at,
    turn_expires_at,
    started_at,
    created_at,
    updated_at
  ) VALUES (
    p_table_id,
    v_table.game_type,
    v_session_number,
    v_session_status::session_status_enum,
    v_initial_state,
    v_effective_turn_user_id,
    v_deadline,
    v_deadline,
    NOW(),
    NOW(),
    NOW()
  ) RETURNING * INTO v_session;

  -- 7. Actualizar mesa a ACTIVE
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      started_at = COALESCE(started_at, NOW()),
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 8. Actualizar estado de jugadores activos a PLAYING
  UPDATE public.game_table_players
  SET status = 'PLAYING'::player_table_status_enum,
      updated_at = NOW()
  WHERE table_id = p_table_id
    AND status::text IN ('JOINED', 'READY');

  -- Retornar resultado integral estructurado
  RETURN jsonb_build_object(
    'success', true,
    'sessionId', v_session.id,
    'session_id', v_session.id,
    'tableId', p_table_id,
    'table_id', p_table_id,
    'status', v_session_status,
    'gameState', v_session.current_state,
    'game_state', v_session.current_state,
    'currentTurnUserId', v_effective_turn_user_id,
    'current_turn_user_id', v_effective_turn_user_id,
    'turnUserId', v_effective_turn_user_id,
    'turnDeadlineAt', v_deadline,
    'turn_deadline_at', v_deadline,
    'turnDeadline', v_deadline,
    'players', v_players,
    'alreadyActive', false,
    'already_active', false
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(UUID, JSONB, INTEGER, UUID) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 156: 152_fix_join_table_by_code_and_matchmaking_availability.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA — MIGRACIÓN 152: CORRECCIÓN DEFINITIVA DE UNIRSE POR CÓDIGO Y
-- FILTRADO AUTORITATIVO DE JUEGOS DISPONIBLES EN MATCHMAKING Y MESAS
-- ==============================================================================
-- 1. Corrige join_table_by_code_secure eliminando referencia a columna inexistente 'join_code'
-- 2. Implementa normalización estricta (trim, espacios internos, uppercase, prefijos TRK/PUB/MES)
-- 3. Valida disponibilidad del juego (is_game_enabled) impidiendo unirse si está deshabilitado
-- 4. Diferencia códigos de error: CODE_NOT_FOUND, GAME_DISABLED, TABLE_FULL, TABLE_CLOSED, etc.
-- 5. Devuelve únicamente campos seguros de la mesa (sin balances, wallets ni emails)
-- 6. Actualiza get_public_available_tables para filtrar juegos deshabilitados
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.join_table_by_code_secure(
  p_invite_code VARCHAR,
  p_idempotency_key VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  v_user_id UUID;
  v_normalized_code VARCHAR;
  v_raw_code VARCHAR;
  v_table RECORD;
  v_existing_seat SMALLINT;
  v_join_result JSONB;
BEGIN
  -- 1. Validar Usuario Autenticado
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para unirte a una mesa.';
  END IF;

  -- 2. Validar Código Vacío
  IF p_invite_code IS NULL OR trim(p_invite_code) = '' THEN
    RAISE EXCEPTION 'EMPTY_CODE: Introduce el código de la mesa.';
  END IF;

  -- 3. Normalización del código: trim, remover espacios internos y uppercase
  v_normalized_code := UPPER(regexp_replace(trim(p_invite_code), '\s+', '', 'g'));
  -- Extraer código base sin prefijos TRK-, PUB-, MES-
  v_raw_code := replace(replace(replace(v_normalized_code, 'TRK-', ''), 'PUB-', ''), 'MES-', '');

  -- 4. Buscar Mesa Real en game_tables con bloqueo FOR UPDATE
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE UPPER(invite_code) = v_normalized_code
     OR UPPER(invite_code) = 'TRK-' || v_raw_code
     OR UPPER(invite_code) = 'PUB-' || v_raw_code
     OR UPPER(invite_code) = 'MES-' || v_raw_code
     OR replace(replace(replace(UPPER(invite_code), 'TRK-', ''), 'PUB-', ''), 'MES-', '') = v_raw_code
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CODE_NOT_FOUND: No encontramos una mesa con ese código. Verifica el código e intenta nuevamente.';
  END IF;

  -- 5. Validar Disponibilidad del Juego (Administración Central)
  IF NOT public.is_game_enabled(v_table.game_type::text) THEN
    RAISE EXCEPTION 'GAME_DISABLED: Esta mesa pertenece a un juego que se encuentra temporalmente en mantenimiento.';
  END IF;

  -- 6. Validar Estado de la Mesa
  IF v_table.status = 'ACTIVE'::table_status_enum THEN
    RAISE EXCEPTION 'GAME_ALREADY_STARTED: Esta partida ya comenzó y no acepta nuevos jugadores.';
  END IF;

  IF v_table.status IN ('FINISHED'::table_status_enum, 'CLOSED'::table_status_enum, 'EXPIRED'::table_status_enum, 'CANCELLED'::table_status_enum) THEN
    RAISE EXCEPTION 'TABLE_CLOSED: Esta mesa ya no está disponible.';
  END IF;

  IF v_table.status NOT IN ('OPEN'::table_status_enum, 'WAITING'::table_status_enum, 'READY'::table_status_enum) THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: Esta mesa no está disponible para nuevos jugadores.';
  END IF;

  -- 7. Verificar si el usuario ya está dentro de la mesa
  SELECT seat_number INTO v_existing_seat
  FROM public.game_table_players
  WHERE table_id = v_table.id
    AND user_id = v_user_id
    AND status != 'LEFT'::player_table_status_enum;

  IF v_existing_seat IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_joined', true,
      'table_id', v_table.id,
      'name', v_table.name,
      'game_type', v_table.game_type,
      'seat_number', v_existing_seat,
      'current_players_count', v_table.current_players_count,
      'max_players', v_table.max_players,
      'status', v_table.status,
      'invite_code', v_table.invite_code,
      'message', 'Ya perteneces a esta mesa. Te estamos redirigiendo...'
    );
  END IF;

  -- 8. Verificar si la mesa está llena
  IF v_table.current_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: Esta mesa ya alcanzó el límite de jugadores.';
  END IF;

  -- 9. Ejecutar transacción de unión atómica con asignación automática de asiento
  v_join_result := public.join_table_transaction(
    v_table.id,
    NULL, -- p_seat_number = NULL -> busca automáticamente el primer asiento libre 1..max_players
    COALESCE(p_idempotency_key, 'join_code_' || v_table.id || '_' || v_user_id || '_' || extract(epoch from now()))
  );

  -- 10. Devolver respuesta segura y limpia (sin balances de anfitrión ni datos sensibles)
  RETURN jsonb_build_object(
    'success', true,
    'already_joined', false,
    'table_id', v_table.id,
    'name', v_table.name,
    'game_type', v_table.game_type,
    'game_variant', v_table.game_variant,
    'invite_code', v_table.invite_code,
    'entry_fee', v_table.entry_fee,
    'current_players_count', COALESCE((v_join_result->>'current_players_count')::int, v_table.current_players_count + 1),
    'max_players', v_table.max_players,
    'seat_number', (v_join_result->>'seat_number')::int,
    'player_id', (v_join_result->>'player_id')::text,
    'message', 'Te has unido exitosamente a la mesa.'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.join_table_by_code_secure(VARCHAR, VARCHAR) TO authenticated, service_role;

-- ------------------------------------------------------------------------------
-- Actualización de get_public_available_tables para excluir juegos deshabilitados
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.get_public_available_tables(
  p_game_type text DEFAULT NULL::text
)
RETURNS SETOF public.game_tables
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, auth
AS $$
  SELECT gt.*
  FROM public.game_tables gt
  WHERE (gt.visibility = 'PUBLIC'::table_visibility_enum OR gt.visibility IS NULL)
    AND gt.status = 'OPEN'::table_status_enum
    AND gt.closed_at IS NULL
    AND gt.current_players_count < gt.max_players
    AND (gt.expires_at IS NULL OR gt.expires_at > NOW())
    AND public.is_game_enabled(gt.game_type::text)
    AND (
      p_game_type IS NULL
      OR p_game_type = 'all'
      OR gt.game_type::text ILIKE p_game_type
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.game_sessions gs
      WHERE gs.table_id = gt.id
        AND (
          gs.ended_at IS NOT NULL
          OR gs.status::text IN ('SETTLED', 'FINISHED', 'CANCELLED', 'COMPLETED', 'ABANDONED', 'CLOSED', 'ACTIVE', 'IN_PROGRESS', 'IN_GAME')
        )
    )
  ORDER BY gt.created_at DESC;
$$;

GRANT EXECUTE ON FUNCTION public.get_public_available_tables(text) TO authenticated, anon, service_role;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 157: 153_forensic_audit_hardening_wallet_ledger_settlement_seats.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 153: AUDITORÍA FORENSE DE SEGUNDA PASADA
-- HARDENING FINANCIERO: WALLET + LEDGER (HOLD -> RELEASE -> CAPTURE)
-- SETTLEMENT 90/10 + GAME SETTLEMENT RECIPIENTS AUDIT
-- ASIGNACIÓN DE ASIENTOS CONCURRENTE (ROW-LEVEL SEAT RECLAIMING)
-- ABANDONO MULTIJUGADOR / EQUIPOS ROBUSTO Y REEMBOLSOS IDEMPOTENTES
-- ==============================================================================

-- 0. DROPS PREVIOS DE FUNCIONES PARA EVITAR CONFLICTOS DE DEFAULT PARAMETERS (ERROR 42P13)
DROP FUNCTION IF EXISTS public.universal_settle_game_session(UUID, UUID[], INT, TEXT);
DROP FUNCTION IF EXISTS public.refund_game_session(UUID, TEXT, TEXT);
DROP FUNCTION IF EXISTS public.refund_game_session(UUID, VARCHAR, VARCHAR);
DROP FUNCTION IF EXISTS public.abandon_game_secure(UUID, TEXT);
DROP FUNCTION IF EXISTS public.create_quick_match_table(UUID, TEXT, NUMERIC, INT, BOOLEAN);
DROP FUNCTION IF EXISTS public.join_table_transaction(UUID, SMALLINT, VARCHAR);

-- 1. CORRECCIÓN CANÓNICA DE join_table_transaction
-- Usa 'TABLE_ENTRY_HOLD' como tipo de ledger estandarizado, asigna entry_held_entry_id
-- y aplica limpieza a nivel de fila (ROW-LEVEL SEAT RECLAIM) de asientos con status = 'LEFT'
-- garantizando concurrencia total sin colisiones de asientos.
CREATE OR REPLACE FUNCTION public.join_table_transaction(
  p_table_id UUID,
  p_seat_number SMALLINT DEFAULT NULL,
  p_idempotency_key VARCHAR DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_table RECORD;
  v_existing_player RECORD;
  v_assigned_seat SMALLINT;
  v_seat_iter SMALLINT;
  v_wallet_id UUID;
  v_wallet_available NUMERIC;
  v_wallet_held NUMERIC;
  v_ledger_id UUID := NULL;
  v_player_id UUID;
  v_new_count INT;
  v_effective_key VARCHAR(100);
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED: Debes iniciar sesión para unirte a una mesa';
  END IF;

  -- 1. Bloqueo de la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa especificada no existe';
  END IF;

  -- BLOQUEO DE SEGURIDAD BACKEND: VERIFICAR DISPONIBILIDAD DEL JUEGO
  IF NOT public.is_game_enabled(v_table.game_type::text) THEN
    RAISE EXCEPTION 'GAME_DISABLED: Este juego se encuentra temporalmente deshabilitado por el administrador.';
  END IF;

  IF v_table.status::text NOT IN ('OPEN', 'WAITING', 'READY') THEN
    RAISE EXCEPTION 'TABLE_NOT_OPEN: La mesa no está abierta para nuevos jugadores (estado: %)', v_table.status;
  END IF;

  -- 2. Verificar si el usuario ya pertenece a esta mesa
  SELECT * INTO v_existing_player
  FROM public.game_table_players
  WHERE table_id = p_table_id AND user_id = v_user_id;

  IF FOUND AND v_existing_player.status IN ('JOINED', 'READY', 'PLAYING') THEN
    RETURN jsonb_build_object(
      'success', true,
      'table_id', p_table_id,
      'seat_number', v_existing_player.seat_number,
      'message', 'Ya perteneces a esta mesa',
      'is_already_joined', true,
      'current_players_count', v_table.current_players_count
    );
  END IF;

  IF v_table.current_players_count >= v_table.max_players THEN
    RAISE EXCEPTION 'TABLE_FULL: La mesa ya ha alcanzado su capacidad máxima';
  END IF;

  -- 3. Asignar asiento disponible (excluyendo a los que salieron)
  IF p_seat_number IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.game_table_players
      WHERE table_id = p_table_id
        AND seat_number = p_seat_number
        AND status != 'LEFT'::player_table_status_enum
    ) THEN
      RAISE EXCEPTION 'SEAT_TAKEN: El asiento % ya está ocupado', p_seat_number;
    END IF;
    v_assigned_seat := p_seat_number;
  ELSE
    v_assigned_seat := NULL;
    FOR v_seat_iter IN 1..v_table.max_players LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.game_table_players
        WHERE table_id = p_table_id
          AND seat_number = v_seat_iter
          AND status != 'LEFT'::player_table_status_enum
      ) THEN
        v_assigned_seat := v_seat_iter;
        EXIT;
      END IF;
    END LOOP;

    IF v_assigned_seat IS NULL THEN
      RAISE EXCEPTION 'NO_SEATS_AVAILABLE: No hay asientos disponibles en esta mesa';
    END IF;
  END IF;

  -- LIMPIEZA DE ASIENTO LIBERADO: Si un jugador anterior con status = 'LEFT' ocupaba este asiento,
  -- se libera la fila inactiva para evitar colisión de índice único
  DELETE FROM public.game_table_players
  WHERE table_id = p_table_id
    AND seat_number = v_assigned_seat
    AND status = 'LEFT'::player_table_status_enum
    AND user_id != v_user_id;

  -- 4. Validar saldo y retención (HOLD) si hay tarifa de entrada
  IF v_table.entry_fee > 0 THEN
    SELECT id, available_balance, held_balance
    INTO v_wallet_id, v_wallet_available, v_wallet_held
    FROM public.wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF v_wallet_id IS NULL THEN
      INSERT INTO public.wallets (user_id, available_balance, held_balance, currency)
      VALUES (v_user_id, 0.00, 0.00, 'VES')
      ON CONFLICT (user_id) DO NOTHING;

      SELECT id, available_balance, held_balance
      INTO v_wallet_id, v_wallet_available, v_wallet_held
      FROM public.wallets
      WHERE user_id = v_user_id
      FOR UPDATE;
    END IF;

    IF v_wallet_available < v_table.entry_fee THEN
      RAISE EXCEPTION 'INSUFFICIENT_FUNDS: Tu saldo disponible (% Bs.) no cubre la entrada (% Bs.)',
        COALESCE(v_wallet_available, 0.00), v_table.entry_fee;
    END IF;

    -- Movimiento atómico: Disminuye available_balance y aumenta held_balance
    UPDATE public.wallets
    SET available_balance = available_balance - v_table.entry_fee,
        held_balance = held_balance + v_table.entry_fee,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    v_effective_key := COALESCE(
      p_idempotency_key,
      'join_hold_' || p_table_id::text || '_' || v_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
    );

    -- Registrar en ledger como TABLE_ENTRY_HOLD (HOLD financiero)
    INSERT INTO public.ledger_entries (
      wallet_id,
      user_id,
      amount,
      currency,
      entry_type,
      direction,
      reference_table,
      reference_type,
      reference_id,
      description,
      idempotency_key,
      balance_after,
      balance_after_available,
      balance_after_held,
      created_at
    ) VALUES (
      v_wallet_id,
      v_user_id,
      v_table.entry_fee,
      'VES',
      'TABLE_ENTRY_HOLD'::ledger_entry_type_enum,
      'DEBIT'::ledger_direction_enum,
      'game_tables',
      'game_table',
      p_table_id,
      'Retención de entrada a mesa: ' || COALESCE(v_table.name, v_table.invite_code, p_table_id::text),
      v_effective_key,
      v_wallet_available - v_table.entry_fee,
      v_wallet_available - v_table.entry_fee,
      v_wallet_held + v_table.entry_fee,
      NOW()
    ) RETURNING id INTO v_ledger_id;
  END IF;

  -- 5. Insertar o reactivar registro del jugador en la mesa
  IF v_existing_player.id IS NOT NULL THEN
    UPDATE public.game_table_players
    SET status = 'JOINED'::player_table_status_enum,
        seat_number = v_assigned_seat,
        entry_held_entry_id = COALESCE(v_ledger_id, entry_held_entry_id),
        left_at = NULL,
        joined_at = NOW(),
        updated_at = NOW()
    WHERE id = v_existing_player.id
    RETURNING id INTO v_player_id;
  ELSE
    INSERT INTO public.game_table_players (
      table_id,
      user_id,
      seat_number,
      entry_held_entry_id,
      status,
      joined_at,
      updated_at
    ) VALUES (
      p_table_id,
      v_user_id,
      v_assigned_seat,
      v_ledger_id,
      'JOINED'::player_table_status_enum,
      NOW(),
      NOW()
    ) RETURNING id INTO v_player_id;
  END IF;

  -- 6. Actualizar contador de jugadores en la mesa
  SELECT COUNT(*) INTO v_new_count
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND status IN ('JOINED', 'READY', 'PLAYING');

  UPDATE public.game_tables
  SET current_players_count = v_new_count,
      status = CASE
        WHEN v_new_count >= v_table.max_players THEN 'FULL'::table_status_enum
        ELSE 'OPEN'::table_status_enum
      END,
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'player_id', v_player_id,
    'seat_number', v_assigned_seat,
    'current_players_count', v_new_count,
    'max_players', v_table.max_players,
    'status', CASE WHEN v_new_count >= v_table.max_players THEN 'FULL' ELSE 'OPEN' END
  );
END;
$$;

-- 2. MEJORA Y AUDITORÍA DE universal_settle_game_session
-- Vincula game_settlement_recipients, acepta TABLE_ENTRY_HOLD y BET_PLACED, y gestiona 90/10 exacto
CREATE OR REPLACE FUNCTION public.universal_settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[],
  p_winner_team INT DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_session RECORD;
  v_table RECORD;
  v_rule RECORD;
  v_winner_pct NUMERIC(5,2) := 90.00;
  v_platform_pct NUMERIC(5,2) := 10.00;
  v_entry_fee NUMERIC(14,2) := 0.00;
  v_gross_pool NUMERIC(14,2) := 0.00;
  v_platform_fee NUMERIC(14,2) := 0.00;
  v_prize_pool NUMERIC(14,2) := 0.00;
  v_individual_prize NUMERIC(14,2) := 0.00;
  v_effective_idempotency TEXT;
  v_settlement_id UUID;
  v_existing_settlement RECORD;
  v_winners_count INTEGER := 0;
  v_primary_winner_id UUID := NULL;
  v_winner_id UUID;
  v_player_id UUID;
  v_table_players UUID[];
  v_total_players INTEGER := 0;
  v_player_wallet RECORD;
  v_winner_wallet RECORD;
  v_is_draw BOOLEAN := false;
  v_settlement_type settlement_type_enum;
  v_ledger_entry_id UUID;
BEGIN
  -- 1. Obtener y bloquear la sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: La sesión de juego % no existe', p_session_id;
  END IF;

  -- 2. Idempotencia: Verificar si ya fue liquidada
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'settle_' || p_session_id::text
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'session_id', p_session_id,
      'table_id', v_existing_settlement.table_id,
      'gross_pool', v_existing_settlement.gross_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'prize_pool', v_existing_settlement.prize_pool,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  IF v_session.status = 'FINISHED'::session_status_enum THEN
    RAISE EXCEPTION 'SESSION_ALREADY_FINISHED: La sesión ya concluyó';
  END IF;

  -- 3. Obtener y bloquear la mesa
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: La mesa vinculada a la sesión no existe';
  END IF;

  -- 4. Obtener reglas de distribución (Por defecto 90% Ganador / 10% Plataforma)
  SELECT * INTO v_rule
  FROM public.settlement_rules
  WHERE (game_type IS NULL OR game_type = v_table.game_type::text)
    AND is_active = true
  ORDER BY game_type NULLS LAST
  LIMIT 1;

  IF FOUND AND v_rule.winner_percentage IS NOT NULL THEN
    v_winner_pct := v_rule.winner_percentage;
    v_platform_pct := COALESCE(v_rule.platform_fee_percentage, 100.00 - v_winner_pct);
  END IF;

  -- 5. Obtener todos los participantes con trazabilidad completa (mesa, ledger y ganadores)
  -- Acepta tanto TABLE_ENTRY_HOLD como el legacy BET_PLACED
  SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_table_players
  FROM (
    SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries 
    WHERE reference_id = v_table.id 
      AND entry_type IN ('TABLE_ENTRY_HOLD'::ledger_entry_type_enum, 'BET_PLACED'::ledger_entry_type_enum)
    UNION
    SELECT unnest(p_winner_user_ids) AS u_id
  ) all_p
  WHERE u_id IS NOT NULL;

  v_winners_count := COALESCE(array_length(p_winner_user_ids, 1), 0);
  IF v_winners_count > 0 AND p_winner_user_ids[1] IS NOT NULL THEN
    v_primary_winner_id := p_winner_user_ids[1];
    v_is_draw := false;
    IF v_winners_count > 1 THEN
      v_settlement_type := 'SPLIT_PAYOUT'::settlement_type_enum;
    ELSE
      v_settlement_type := 'STANDARD_PAYOUT'::settlement_type_enum;
    END IF;
  ELSE
    v_settlement_type := 'DRAW_REFUND'::settlement_type_enum;
    v_is_draw := true;
  END IF;

  v_total_players := GREATEST(COALESCE(array_length(v_table_players, 1), 0), 2);
  v_entry_fee := COALESCE(v_table.entry_fee, 0.00);
  v_gross_pool := v_entry_fee * v_total_players;

  IF v_is_draw THEN
    v_platform_fee := 0.00;
    v_prize_pool := 0.00;
  ELSE
    v_platform_fee := ROUND(v_gross_pool * (v_platform_pct / 100.00), 2);
    v_prize_pool := v_gross_pool - v_platform_fee;
  END IF;

  -- 6. Insertar registro en game_settlements
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    gross_pool,
    platform_fee,
    prize_pool,
    total_distributed,
    settlement_type,
    idempotency_key,
    settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    v_gross_pool,
    v_platform_fee,
    v_prize_pool,
    CASE WHEN v_is_draw THEN v_gross_pool ELSE v_prize_pool END,
    v_settlement_type,
    v_effective_idempotency,
    NOW()
  );

  -- 7. GESTIÓN FINANCIERA ATÓMICA DE FONDOS RETENIDOS (held_balance)
  IF v_entry_fee > 0.00 AND v_table_players IS NOT NULL AND array_length(v_table_players, 1) > 0 THEN
    FOREACH v_player_id IN ARRAY v_table_players LOOP
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player_id
      FOR UPDATE;

      IF FOUND THEN
        IF v_is_draw THEN
          -- EMPATE TÉCNICO (RELEASE): Regresar saldo retenido a saldo disponible al 100%
          UPDATE public.wallets
          SET available_balance = available_balance + v_entry_fee,
              held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_player_wallet.available_balance + v_entry_fee,
            v_player_wallet.available_balance + v_entry_fee,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_refund_' || v_player_id::text,
            'Devolución de entrada por empate en ' || COALESCE(v_table.game_type::text, 'partida'),
            NOW()
          );
        ELSE
          -- PARTIDA NORMAL CON GANADOR (CAPTURE): Capturar y descontar definitivamente held_balance
          UPDATE public.wallets
          SET held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_CAPTURE'::ledger_entry_type_enum,
            'DEBIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_player_wallet.available_balance,
            v_player_wallet.available_balance,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_capture_' || v_player_id::text,
            'Captura de entrada para liquidación en ' || COALESCE(v_table.game_type::text, 'partida'),
            NOW()
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 8. ACREDITACIÓN DE PREMIO A LOS GANADORES EN available_balance Y REGISTRO EN game_settlement_recipients
  IF NOT v_is_draw AND v_winners_count > 0 AND v_prize_pool > 0.00 THEN
    v_individual_prize := ROUND(v_prize_pool / v_winners_count, 2);

    FOREACH v_winner_id IN ARRAY p_winner_user_ids LOOP
      IF v_winner_id IS NOT NULL THEN
        SELECT * INTO v_winner_wallet
        FROM public.wallets
        WHERE user_id = v_winner_id
        FOR UPDATE;

        IF FOUND THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_individual_prize,
              updated_at = NOW()
          WHERE id = v_winner_wallet.id;

          v_ledger_entry_id := gen_random_uuid();

          INSERT INTO public.ledger_entries (
            id,
            wallet_id,
            user_id,
            amount,
            currency,
            entry_type,
            direction,
            reference_id,
            reference_table,
            reference_type,
            balance_after,
            balance_after_available,
            balance_after_held,
            idempotency_key,
            description,
            created_at
          ) VALUES (
            v_ledger_entry_id,
            v_winner_wallet.id,
            v_winner_id,
            v_individual_prize,
            'VES',
            'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_winner_wallet.available_balance + v_individual_prize,
            v_winner_wallet.available_balance + v_individual_prize,
            v_winner_wallet.held_balance,
            v_effective_idempotency || '_win_' || v_winner_id::text,
            'Premio por victoria en partida (' || v_winner_pct::text || '% del pozo)',
            NOW()
          );

          -- Registro detallado de receptor de liquidación
          INSERT INTO public.game_settlement_recipients (
            id,
            settlement_id,
            user_id,
            team_number,
            payout_amount,
            ledger_entry_id,
            payout_status,
            created_at
          ) VALUES (
            gen_random_uuid(),
            v_settlement_id,
            v_winner_id,
            p_winner_team,
            v_individual_prize,
            v_ledger_entry_id,
            'COMPLETED',
            NOW()
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 9. Actualizar estado oficial de la sesión
  UPDATE public.game_sessions
  SET status = (CASE WHEN v_is_draw THEN 'CANCELLED' ELSE 'FINISHED' END)::session_status_enum,
      winner_user_id = v_primary_winner_id,
      winner_team = p_winner_team,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE id = p_session_id;

  -- 10. Actualizar estado de la mesa y jugadores
  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_table.id AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'table_id', v_table.id,
    'gross_pool', v_gross_pool,
    'platform_fee', v_platform_fee,
    'prize_pool', v_prize_pool,
    'winner_percentage', v_winner_pct,
    'platform_percentage', v_platform_pct,
    'winner_user_id', v_primary_winner_id,
    'is_draw', v_is_draw,
    'settlement_id', v_settlement_id
  );
END;
$$;

-- 3. MEJORA Y AUDITORÍA DE abandon_game_secure
-- Soporta abandono 1v1 y equipos (2v2), liquidando al equipo oponente completo
CREATE OR REPLACE FUNCTION public.abandon_game_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_game_type TEXT;
  v_leaving_player RECORD;
  v_winner_ids UUID[] := ARRAY[]::UUID[];
  v_winning_team INT := NULL;
  v_effective_idempotency TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTENTICADO');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || p_session_id::text || '_' || v_user_id::text || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  v_game_type := LOWER(COALESCE(v_table.game_type::text, v_session.game_type::text, ''));

  IF v_session.status::text IN ('FINISHED', 'CANCELLED') THEN
    RETURN jsonb_build_object('success', false, 'error', 'JUEGO_YA_FINALIZADO');
  END IF;

  -- Obtener registro del jugador que abandona
  SELECT * INTO v_leaving_player
  FROM public.game_table_players
  WHERE table_id = v_session.table_id AND user_id = v_user_id;

  -- Marcar jugador como ABANDONED
  UPDATE public.game_table_players
  SET status = 'ABANDONED'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_session.table_id 
     AND user_id = v_user_id 
     AND status::text NOT IN ('ABANDONED', 'LEFT');

  -- Lógica de liquidación por tipo de juego
  IF v_game_type IN (
    'atrapaito', 'chess', 'checkers', 'tictactoe', 'tic_tac_toe', 
    'rps', 'rock_paper_scissors', 'domino', 'domino_venezolano', 
    'truco', 'truco_venezolano', 'una_olla', 'unaolla'
  ) THEN
    -- Si el juego tiene asignación de equipos (ej. Domino 2v2 o Truco 2v2)
    IF v_leaving_player.team_number IS NOT NULL THEN
      SELECT ARRAY_AGG(user_id), MAX(team_number)
      INTO v_winner_ids, v_winning_team
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND team_number != v_leaving_player.team_number
        AND status::text NOT IN ('ABANDONED', 'LEFT');
    ELSE
      -- Juego 1v1 o individual
      SELECT ARRAY_AGG(user_id)
      INTO v_winner_ids
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND user_id != v_user_id
        AND status::text NOT IN ('ABANDONED', 'LEFT');
    END IF;

    IF v_winner_ids IS NOT NULL AND array_length(v_winner_ids, 1) > 0 THEN
      -- Liquidar autoritativamente con el oponente o equipo oponente como ganador(es)
      PERFORM public.universal_settle_game_session(
        p_session_id,
        v_winner_ids,
        v_winning_team,
        v_effective_idempotency || '_settle'
      );
    ELSE
      -- Sin oponentes activos: reembolsar íntegramente
      PERFORM public.refund_game_session(
        p_session_id,
        'Abandono sin oponentes activos',
        v_effective_idempotency || '_refund'
      );
    END IF;

  ELSIF v_game_type = 'bingo' THEN
    -- En Bingo, abandonar solo desmarca al jugador sin alterar el pozo comunitario
    UPDATE public.game_sessions
    SET current_state = jsonb_set(
        COALESCE(current_state, '{}'::jsonb),
        '{abandonedPlayers}',
        COALESCE(current_state->'abandonedPlayers', '[]'::jsonb) || to_jsonb(v_user_id::text)
    ),
    updated_at = NOW()
    WHERE id = p_session_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true, 
    'message', 'Has abandonado la partida correctamente'
  );
END;
$$;

-- 4. MEJORA Y AUDITORÍA DE refund_game_session
-- Acepta TABLE_ENTRY_HOLD y BET_PLACED, idéntica trazabilidad
CREATE OR REPLACE FUNCTION public.refund_game_session(
  p_session_id UUID,
  p_reason TEXT DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_caller_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_gross_pool NUMERIC(14,2) := 0.00;
  v_settlement_id UUID;
  v_player_id UUID;
  v_player_wallet RECORD;
  v_existing_settlement RECORD;
  v_effective_idempotency TEXT;
  v_refunded_count INT := 0;
  v_participants UUID[] := ARRAY[]::UUID[];
BEGIN
  v_caller_id := auth.uid();

  -- 1. Obtener y bloquear sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SESSION_NOT_FOUND: Sesión % no encontrada', p_session_id;
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND: Mesa no encontrada';
  END IF;

  -- 2. Idempotencia
  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'refund_' || p_session_id::text || '_' || COALESCE(v_caller_id::text, 'sys')
  );

  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id AND settlement_type = 'ADMIN_CANCEL_REFUND'::settlement_type_enum;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  IF v_session.status = 'FINISHED'::session_status_enum THEN
    RAISE EXCEPTION 'INVALID_SESSION_STATUS: No se puede reembolsar una sesión ya liquidada y finalizada con ganador.';
  END IF;

  -- 3. Identificar TODOS los participantes que aportaron entrada (HOLD o legacy BET_PLACED)
  SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_participants
  FROM (
    SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries 
    WHERE reference_id = v_table.id 
      AND entry_type IN ('TABLE_ENTRY_HOLD'::ledger_entry_type_enum, 'BET_PLACED'::ledger_entry_type_enum)
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries 
    WHERE reference_id = p_session_id 
      AND entry_type IN ('TABLE_ENTRY_HOLD'::ledger_entry_type_enum, 'BET_PLACED'::ledger_entry_type_enum)
  ) all_p
  WHERE u_id IS NOT NULL;

  v_gross_pool := COALESCE(v_table.entry_fee, 0.00) * GREATEST(COALESCE(array_length(v_participants, 1), 0), 1);

  -- 4. Registro de liquidación tipo ADMIN_CANCEL_REFUND
  v_settlement_id := gen_random_uuid();
  INSERT INTO public.game_settlements (
    id,
    session_id,
    table_id,
    settlement_type,
    gross_pool,
    prize_pool,
    platform_fee,
    total_distributed,
    idempotency_key,
    settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    'ADMIN_CANCEL_REFUND'::settlement_type_enum,
    v_gross_pool,
    0.00,
    0.00,
    v_gross_pool,
    v_effective_idempotency,
    NOW()
  );

  -- 5. Liberación íntegra de saldos retenidos a disponible (held_balance -> available_balance)
  IF COALESCE(v_table.entry_fee, 0.00) > 0.00 AND v_participants IS NOT NULL THEN
    FOREACH v_player_id IN ARRAY v_participants LOOP
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player_id
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_table.entry_fee,
            held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
            updated_at = NOW()
        WHERE id = v_player_wallet.id;

        INSERT INTO public.ledger_entries (
          id,
          wallet_id,
          user_id,
          entry_type,
          direction,
          amount,
          currency,
          balance_after,
          balance_after_available,
          balance_after_held,
          reference_table,
          reference_type,
          reference_id,
          idempotency_key,
          description,
          actor_id,
          created_at
        ) VALUES (
          gen_random_uuid(),
          v_player_wallet.id,
          v_player_id,
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_table.entry_fee,
          'VES',
          v_player_wallet.available_balance + v_table.entry_fee,
          v_player_wallet.available_balance + v_table.entry_fee,
          GREATEST(0.00, v_player_wallet.held_balance - v_table.entry_fee),
          'game_sessions',
          'game_session',
          p_session_id,
          v_effective_idempotency || '_refund_' || v_player_id::text,
          'Reembolso de entrada por empate o cancelación: ' || COALESCE(p_reason, 'Sin motivo'),
          v_caller_id,
          NOW()
        );

        v_refunded_count := v_refunded_count + 1;
      END IF;
    END LOOP;
  END IF;

  -- 6. Actualización de Estados
  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = NOW(),
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = NOW(),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_table.id AND status != 'LEFT'::player_table_status_enum;

  RETURN jsonb_build_object(
    'success', true,
    'settlement_id', v_settlement_id,
    'refunded_count', v_refunded_count,
    'gross_refunded', v_gross_pool
  );
END;
$$;

-- 5. ACTUALIZAR RPC LEGACY create_quick_match_table PARA BLOQUEO POR ADMINISTRADOR
CREATE OR REPLACE FUNCTION public.create_quick_match_table(
  p_host_user_id UUID,
  p_game_type TEXT,
  p_entry_fee NUMERIC,
  p_max_players INT,
  p_is_private BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_table_id UUID;
  v_table_code TEXT;
BEGIN
  -- BLOQUEO DE SEGURIDAD BACKEND: VERIFICAR DISPONIBILIDAD DEL JUEGO
  IF NOT public.is_game_enabled(p_game_type) THEN
    RAISE EXCEPTION 'GAME_DISABLED: Este juego se encuentra temporalmente deshabilitado por el administrador.';
  END IF;

  -- Generar código único de mesa
  v_table_code := upper(substring(md5(random()::text || clock_timestamp()::text), 1, 6));
  
  -- Crear la mesa
  INSERT INTO public.game_tables (
    host_user_id,
    game_type,
    entry_fee,
    max_players,
    is_private,
    table_code,
    invite_code,
    status
  ) VALUES (
    p_host_user_id,
    p_game_type::game_type_enum,
    p_entry_fee,
    p_max_players,
    p_is_private,
    v_table_code,
    v_table_code,
    'OPEN'
  )
  RETURNING id INTO v_table_id;

  -- Agregar al host como primer jugador
  INSERT INTO public.game_table_players (
    table_id,
    user_id,
    seat_number,
    status
  ) VALUES (
    v_table_id,
    p_host_user_id,
    1,
    'JOINED'
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_id', v_table_id,
    'table_code', v_table_code,
    'game_type', p_game_type,
    'entry_fee', p_entry_fee
  );
END;
$$;

-- 6. RECARGAR CACHÉ DE ESQUEMA POSTGREST
NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 158: 154_fix_support_tickets_fk_ambiguity.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 154: CORRECCIÓN DE AMBIGÜEDAD EN RELACIONES FK DE SUPPORT_TICKETS
-- PROYECTO: RASPANDO LA OLLA 🇻🇪 / PulsoPLAY
-- ==============================================================================
-- Causa Raíz:
-- En migración 014 se creó 'support_tickets' con:
--   user_id UUID NOT NULL REFERENCES public.profiles(user_id)
-- Posteriormente en migración 133 se agregó:
--   ADD CONSTRAINT support_tickets_user_id_profiles_fkey
--   FOREIGN KEY (user_id) REFERENCES public.profiles(id)
-- Esta doble referencia sobre la columna 'user_id' (hacia profiles.user_id y hacia profiles.id)
-- provocaba el error de PostgREST:
-- "Could not embed because more than one relationship was found for 'support_tickets' and 'user_id'"
--
-- Solución:
-- 1. Eliminar la restricción errónea/redundante 'support_tickets_user_id_profiles_fkey'
--    que apuntaba indebidamente a profiles(id).
-- 2. Asegurar que la relación canónica y unívoca con profiles(user_id) permanezca limpia.
-- ==============================================================================

DO $$
BEGIN
  -- 1. Eliminar la restricción redundante/errónea que apunta a profiles(id)
  IF EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE constraint_name = 'support_tickets_user_id_profiles_fkey'
      AND table_name = 'support_tickets'
      AND table_schema = 'public'
  ) THEN
    ALTER TABLE public.support_tickets
    DROP CONSTRAINT support_tickets_user_id_profiles_fkey;
  END IF;

  -- 2. Verificar y asegurar relación canónica con profiles(user_id)
  IF NOT EXISTS (
    SELECT 1 
    FROM information_schema.table_constraints tc
    JOIN information_schema.constraint_column_usage ccu ON ccu.constraint_name = tc.constraint_name
    WHERE tc.table_name = 'support_tickets'
      AND tc.constraint_type = 'FOREIGN KEY'
      AND ccu.table_name = 'profiles'
      AND ccu.column_name = 'user_id'
  ) THEN
    ALTER TABLE public.support_tickets
    ADD CONSTRAINT support_tickets_user_id_canonical_fkey
    FOREIGN KEY (user_id) REFERENCES public.profiles(user_id) ON DELETE CASCADE;
  END IF;
END $$;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 159: 155_integral_financial_settlement_remediation_and_reconciliation.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 155: REMEDIACIÓN FINANCIERA INTEGRAL, AUTORITATIVA Y RECONCILIACIÓN
-- Proyecto: RASPANDO LA OLLA 🇻🇪 / PulsoPLAY
-- Propósito:
--   1. Eliminar de raíz el bloqueo SESSION_ALREADY_FINISHED permitiendo la liquidación
--      de sesiones concluidas en el juego que no han sido asentadas en game_settlements.
--   2. Separar formalmente el estado de juego (FINISHED) del estado financiero (SETTLED).
--   3. Validar de forma server-authoritative que el ganador pertenece a la mesa.
--   4. Consultar dinámicamente public.financial_rules (90/10 canónico oficial).
--   5. Garantizar que universal_settle_game_session y refund_game_session capturen o
--      reembolsen held_balance en wallets y asienten exactamente en ledger_entries.
--   6. Corregir timeout (expire_game_turn_secure) para que no silencie errores y use
--      la RPC universal.
--   7. Corregir cleanup_stale_user_game_participation para que restituya entradas
--      retenidas de mesas cerradas/huérfanas sin liquidar.
--   8. Añadir refund_bingo_table_secure para salas de bingo expiradas o canceladas.
--   9. Proporcionar funciones auditables e idempotentes de reconciliación forense
--      para recuperar y liquidar fondos históricos atrapados.
-- ==============================================================================

-- ==============================================================================
-- 0. AMPLIACIÓN DE LONGITUD DE IDEMPOTENCY_KEY EN TABLAS FINANCIERAS
-- ==============================================================================

DO $$
BEGIN
  ALTER TABLE public.ledger_entries ALTER COLUMN idempotency_key TYPE VARCHAR(255);
  ALTER TABLE public.game_settlements ALTER COLUMN idempotency_key TYPE VARCHAR(255);
EXCEPTION WHEN OTHERS THEN
  NULL;
END;
$$;

-- ==============================================================================
-- 1. UNIVERSAL SETTLE GAME SESSION (CANÓNICA, AUTORITATIVA Y SEGURA)
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.universal_settle_game_session(
  p_session_id UUID,
  p_winner_user_ids UUID[] DEFAULT ARRAY[]::UUID[],
  p_winner_team INT DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_session RECORD;
  v_table RECORD;
  v_rule RECORD;
  v_caller_id UUID;
  v_caller_role TEXT;
  v_existing_settlement RECORD;
  v_effective_idempotency TEXT;
  v_settlement_id UUID;
  v_entry_fee NUMERIC(14,2) := 0.00;
  v_table_players UUID[] := ARRAY[]::UUID[];
  v_total_players INT := 0;
  v_gross_pool NUMERIC(14,2) := 0.00;
  v_winner_pct NUMERIC(5,2) := 90.00;
  v_platform_pct NUMERIC(5,2) := 10.00;
  v_platform_fee NUMERIC(14,2) := 0.00;
  v_prize_pool NUMERIC(14,2) := 0.00;
  v_individual_prize NUMERIC(14,2) := 0.00;
  v_winners_count INT := 0;
  v_sanitized_winners UUID[] := ARRAY[]::UUID[];
  v_winner_id UUID;
  v_player_id UUID;
  v_primary_winner_id UUID := NULL;
  v_player_wallet RECORD;
  v_winner_wallet RECORD;
  v_settlement_type settlement_type_enum := 'STANDARD_PAYOUT'::settlement_type_enum;
  v_is_draw BOOLEAN := false;
  v_ledger_entry_id UUID;
  v_server_winner_id UUID := NULL;
BEGIN
  -- 1. Validar identificador de sesión
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  -- 2. Idempotencia base
  v_effective_idempotency := COALESCE(
    NULLIF(TRIM(p_idempotency_key), ''),
    'settle_session_' || p_session_id::text
  );

  -- 3. Bloqueo Pesimista de la Sesión
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 4. Verificación de liquidación previa (Idempotencia absoluta)
  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'session_id', p_session_id,
      'table_id', v_existing_settlement.table_id,
      'gross_pool', v_existing_settlement.gross_pool,
      'platform_fee', v_existing_settlement.platform_fee,
      'prize_pool', v_existing_settlement.prize_pool,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  -- NOTA FORENSE CRÍTICA:
  -- Ya NO se rechaza v_session.status = 'FINISHED'. Si la partida concluyó en el
  -- tablero pero no tiene fila en game_settlements, SE PROCEDE CON LA LIQUIDACIÓN.

  -- 5. Bloqueo de Mesa Asociada
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;

  v_entry_fee := COALESCE(v_table.entry_fee, 0.00);

  -- 6. Obtener Participantes Reales de la Mesa
  SELECT COALESCE(ARRAY_AGG(DISTINCT user_id), ARRAY[]::UUID[]) INTO v_table_players
  FROM (
    SELECT user_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id FROM public.ledger_entries
    WHERE reference_id = v_table.id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
    UNION
    SELECT v_table.host_user_id AS user_id WHERE v_table.host_user_id IS NOT NULL
  ) p_sub
  WHERE user_id IS NOT NULL;

  -- 7. Validación de Autorización del Invocador
  v_caller_id := auth.uid();
  v_caller_role := COALESCE(auth.role(), '');

  IF v_caller_id IS NOT NULL AND v_caller_role <> 'service_role' THEN
    IF NOT (v_caller_id = ANY(v_table_players)) AND v_caller_id <> v_table.host_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED_SETTLEMENT_CALLER');
    END IF;
  END IF;

  -- 8. Validar y Sanitizar Ganador(es) Server-Authoritative
  -- Comprobar si la sesión ya tiene un ganador oficial en BD
  v_server_winner_id := v_session.winner_user_id;
  IF v_server_winner_id IS NULL AND v_session.current_state ? 'winnerUserId' THEN
    BEGIN
      v_server_winner_id := (v_session.current_state->>'winnerUserId')::UUID;
    EXCEPTION WHEN OTHERS THEN
      v_server_winner_id := NULL;
    END;
  END IF;

  -- Sanitizar p_winner_user_ids
  IF p_winner_user_ids IS NOT NULL AND array_length(p_winner_user_ids, 1) > 0 THEN
    SELECT COALESCE(ARRAY_AGG(DISTINCT w_id), ARRAY[]::UUID[]) INTO v_sanitized_winners
    FROM UNNEST(p_winner_user_ids) AS w_id
    WHERE w_id IS NOT NULL;
  ELSIF v_server_winner_id IS NOT NULL THEN
    v_sanitized_winners := ARRAY[v_server_winner_id];
  END IF;

  -- Validar que todo ganador sanitizado sea un participante de la mesa
  IF array_length(v_sanitized_winners, 1) > 0 THEN
    FOREACH v_winner_id IN ARRAY v_sanitized_winners LOOP
      IF NOT (v_winner_id = ANY(v_table_players)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_WINNER_NOT_IN_TABLE');
      END IF;
    END LOOP;
  END IF;

  -- 9. Detección de Empate vs Victoria
  IF array_length(v_sanitized_winners, 1) IS NULL 
     OR array_length(v_sanitized_winners, 1) = 0 
     OR (v_session.current_state->>'isDraw')::boolean = true
     OR (v_session.current_state->>'winner')::text = 'DRAW' THEN
    v_is_draw := true;
    v_settlement_type := 'DRAW_REFUND'::settlement_type_enum;
  ELSE
    v_is_draw := false;
    v_settlement_type := CASE 
      WHEN array_length(v_sanitized_winners, 1) > 1 THEN 'SPLIT_PAYOUT'::settlement_type_enum
      ELSE 'STANDARD_PAYOUT'::settlement_type_enum
    END;
    v_winners_count := array_length(v_sanitized_winners, 1);
    v_primary_winner_id := v_sanitized_winners[1];
  END IF;

  -- 10. Consulta de Reglas Oficiales de Comisión (public.financial_rules)
  SELECT * INTO v_rule
  FROM public.financial_rules
  WHERE is_active = true
  ORDER BY created_at DESC
  LIMIT 1;

  IF FOUND AND v_rule.winner_percentage IS NOT NULL THEN
    v_winner_pct := v_rule.winner_percentage;
    v_platform_pct := COALESCE(v_rule.platform_fee_percentage, 100.00 - v_winner_pct);
  END IF;

  -- 11. Cálculo Matemático del Pozo
  v_total_players := GREATEST(COALESCE(array_length(v_table_players, 1), 0), 2);
  v_gross_pool := v_entry_fee * v_total_players;

  IF v_is_draw THEN
    v_platform_fee := 0.00;
    v_prize_pool := 0.00;
    v_individual_prize := 0.00;
  ELSE
    v_platform_fee := ROUND(v_gross_pool * (v_platform_pct / 100.00), 2);
    v_prize_pool := v_gross_pool - v_platform_fee;
    IF v_winners_count > 0 THEN
      v_individual_prize := ROUND(v_prize_pool / v_winners_count, 2);
    END IF;
  END IF;

  v_settlement_id := gen_random_uuid();

  -- 12. Movimientos Financieros Atómicos por Jugador
  -- Descontar de held_balance para TODOS los participantes
  FOREACH v_player_id IN ARRAY v_table_players LOOP
    IF v_player_id IS NOT NULL THEN
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_player_id
      FOR UPDATE;

      IF FOUND THEN
        IF v_is_draw THEN
          -- En caso de Empate: Reintegro de la entrada retenida a available_balance
          UPDATE public.wallets
          SET held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              available_balance = available_balance + v_entry_fee,
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id, wallet_id, user_id, amount, currency, entry_type, direction,
            reference_id, reference_table, reference_type,
            balance_after, balance_after_available, balance_after_held,
            idempotency_key, description, created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            p_session_id,
            'game_sessions',
            'game_session',
            v_player_wallet.available_balance + v_entry_fee + GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_player_wallet.available_balance + v_entry_fee,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_refund_' || v_player_id::text,
            'Reembolso íntegro de entrada por empate en partida',
            NOW()
          );
        ELSE
          -- En caso de Victoria: Captura definitiva de la entrada retenida
          UPDATE public.wallets
          SET held_balance = GREATEST(0.00, held_balance - v_entry_fee),
              updated_at = NOW()
          WHERE id = v_player_wallet.id;

          INSERT INTO public.ledger_entries (
            id, wallet_id, user_id, amount, currency, entry_type, direction,
            reference_id, reference_table, reference_type,
            balance_after, balance_after_available, balance_after_held,
            idempotency_key, description, created_at
          ) VALUES (
            gen_random_uuid(),
            v_player_wallet.id,
            v_player_id,
            v_entry_fee,
            'VES',
            'TABLE_ENTRY_CAPTURE'::ledger_entry_type_enum,
            'DEBIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_player_wallet.available_balance + GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_player_wallet.available_balance,
            GREATEST(0.00, v_player_wallet.held_balance - v_entry_fee),
            v_effective_idempotency || '_capture_' || v_player_id::text,
            'Captura de entrada para liquidación oficial de partida',
            NOW()
          );
        END IF;
      END IF;
    END IF;
  END LOOP;

  -- 13. Inserción de Registro en game_settlements (requerido previamente para las claves foráneas)
  INSERT INTO public.game_settlements (
    id, session_id, table_id, gross_pool, platform_fee, prize_pool, total_distributed,
    settlement_type, idempotency_key, settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    v_gross_pool,
    v_platform_fee,
    v_prize_pool,
    CASE WHEN v_is_draw THEN v_gross_pool ELSE v_prize_pool END,
    v_settlement_type,
    v_effective_idempotency,
    NOW()
  );

  -- 14. Acreditación de Premio al Ganador(es) y Registro de Receptores
  IF NOT v_is_draw AND v_winners_count > 0 AND v_prize_pool > 0.00 THEN
    FOREACH v_winner_id IN ARRAY v_sanitized_winners LOOP
      IF v_winner_id IS NOT NULL THEN
        SELECT * INTO v_winner_wallet
        FROM public.wallets
        WHERE user_id = v_winner_id
        FOR UPDATE;

        IF FOUND THEN
          UPDATE public.wallets
          SET available_balance = available_balance + v_individual_prize,
              updated_at = NOW()
          WHERE id = v_winner_wallet.id;

          v_ledger_entry_id := gen_random_uuid();

          INSERT INTO public.ledger_entries (
            id, wallet_id, user_id, amount, currency, entry_type, direction,
            reference_id, reference_table, reference_type,
            balance_after, balance_after_available, balance_after_held,
            idempotency_key, description, created_at
          ) VALUES (
            v_ledger_entry_id,
            v_winner_wallet.id,
            v_winner_id,
            v_individual_prize,
            'VES',
            'GAME_PRIZE_CREDIT'::ledger_entry_type_enum,
            'CREDIT'::ledger_direction_enum,
            v_settlement_id,
            'game_settlements',
            'game_settlement',
            v_winner_wallet.available_balance + v_individual_prize + v_winner_wallet.held_balance,
            v_winner_wallet.available_balance + v_individual_prize,
            v_winner_wallet.held_balance,
            v_effective_idempotency || '_win_' || v_winner_id::text,
            'Premio por victoria en partida (' || v_winner_pct::text || '% del pozo)',
            NOW()
          );

          INSERT INTO public.game_settlement_recipients (
            id, settlement_id, user_id, team_number, payout_amount,
            ledger_entry_id, payout_status, created_at
          ) VALUES (
            gen_random_uuid(),
            v_settlement_id,
            v_winner_id,
            p_winner_team,
            v_individual_prize,
            v_ledger_entry_id,
            'COMPLETED',
            NOW()
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- 15. Actualización Definitiva de Estado: SETTLED
  UPDATE public.game_sessions
  SET status = 'SETTLED'::session_status_enum,
      winner_user_id = v_primary_winner_id,
      winner_team = p_winner_team,
      ended_at = COALESCE(ended_at, NOW()),
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = COALESCE(closed_at, NOW()),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      updated_at = NOW()
  WHERE table_id = v_table.id;

  -- 16. Retorno de Éxito
  RETURN jsonb_build_object(
    'success', true,
    'is_idempotent_replay', false,
    'session_id', p_session_id,
    'table_id', v_table.id,
    'gross_pool', v_gross_pool,
    'platform_fee', v_platform_fee,
    'prize_pool', v_prize_pool,
    'settlement_id', v_settlement_id,
    'settlement_type', v_settlement_type::text,
    'winners_count', v_winners_count,
    'individual_prize', v_individual_prize,
    'winner_percentage', v_winner_pct,
    'platform_percentage', v_platform_pct
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.universal_settle_game_session(UUID, UUID[], INT, TEXT) TO authenticated, service_role, anon;

-- ==============================================================================
-- 2. REFUND GAME SESSION (SEGURO, IDEMPOTENTE Y SIN RECHAZO POR FINISHED)
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.refund_game_session(
  p_session_id UUID,
  p_reason TEXT DEFAULT 'Cancelación oficial de partida',
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_session RECORD;
  v_table RECORD;
  v_existing_settlement RECORD;
  v_effective_idempotency TEXT;
  v_settlement_id UUID;
  v_participants UUID[] := ARRAY[]::UUID[];
  v_user_id UUID;
  v_player_wallet RECORD;
  v_refund_amount NUMERIC(14,2) := 0.00;
  v_refunded_count INT := 0;
  v_caller_id UUID;
  v_caller_role TEXT;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(TRIM(p_idempotency_key), ''),
    'refund_session_' || p_session_id::text
  );

  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- Idempotencia: Si ya fue reembolsado o liquidado
  SELECT * INTO v_existing_settlement
  FROM public.game_settlements
  WHERE session_id = p_session_id;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'is_idempotent_replay', true,
      'settlement_id', v_existing_settlement.id
    );
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  v_refund_amount := COALESCE(v_table.entry_fee, 0.00);

  -- Obtener participantes
  SELECT COALESCE(ARRAY_AGG(DISTINCT u_id), ARRAY[]::UUID[]) INTO v_participants
  FROM (
    SELECT user_id AS u_id FROM public.game_table_players WHERE table_id = v_table.id
    UNION
    SELECT user_id AS u_id FROM public.ledger_entries
    WHERE reference_id = v_table.id AND entry_type = 'TABLE_ENTRY_HOLD'::ledger_entry_type_enum
    UNION
    SELECT v_table.host_user_id AS u_id WHERE v_table.host_user_id IS NOT NULL
  ) p_sub
  WHERE u_id IS NOT NULL;

  -- Validar que el invocador sea participante o servicio
  v_caller_id := auth.uid();
  v_caller_role := COALESCE(auth.role(), '');
  IF v_caller_id IS NOT NULL AND v_caller_role <> 'service_role' THEN
    IF NOT (v_caller_id = ANY(v_participants)) AND v_caller_id <> v_table.host_user_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED_CALLER');
    END IF;
  END IF;

  v_settlement_id := gen_random_uuid();

  -- Reembolsar a cada participante
  FOREACH v_user_id IN ARRAY v_participants LOOP
    IF v_user_id IS NOT NULL THEN
      SELECT * INTO v_player_wallet
      FROM public.wallets
      WHERE user_id = v_user_id
      FOR UPDATE;

      IF FOUND THEN
        UPDATE public.wallets
        SET held_balance = GREATEST(0.00, held_balance - v_refund_amount),
            available_balance = available_balance + v_refund_amount,
            updated_at = NOW()
        WHERE id = v_player_wallet.id;

        INSERT INTO public.ledger_entries (
          id, wallet_id, user_id, amount, currency, entry_type, direction,
          reference_id, reference_table, reference_type,
          balance_after, balance_after_available, balance_after_held,
          idempotency_key, description, created_at
        ) VALUES (
          gen_random_uuid(),
          v_player_wallet.id,
          v_user_id,
          v_refund_amount,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          p_session_id,
          'game_sessions',
          'game_session',
          v_player_wallet.available_balance + v_refund_amount + GREATEST(0.00, v_player_wallet.held_balance - v_refund_amount),
          v_player_wallet.available_balance + v_refund_amount,
          GREATEST(0.00, v_player_wallet.held_balance - v_refund_amount),
          v_effective_idempotency || '_refund_' || v_user_id::text,
          COALESCE(p_reason, 'Reembolso oficial de partida'),
          NOW()
        );

        v_refunded_count := v_refunded_count + 1;
      END IF;
    END IF;
  END LOOP;

  -- Registrar en game_settlements
  INSERT INTO public.game_settlements (
    id, session_id, table_id, gross_pool, platform_fee, prize_pool, total_distributed,
    settlement_type, idempotency_key, settled_at
  ) VALUES (
    v_settlement_id,
    p_session_id,
    v_table.id,
    v_refund_amount * GREATEST(v_refunded_count, 1),
    0.00,
    0.00,
    v_refund_amount * GREATEST(v_refunded_count, 1),
    'ADMIN_CANCEL_REFUND'::settlement_type_enum,
    v_effective_idempotency,
    NOW()
  );

  UPDATE public.game_sessions
  SET status = 'CANCELLED'::session_status_enum,
      ended_at = COALESCE(ended_at, NOW()),
      updated_at = NOW()
  WHERE id = p_session_id;

  UPDATE public.game_tables
  SET status = 'CLOSED'::table_status_enum,
      current_players_count = 0,
      closed_at = COALESCE(closed_at, NOW()),
      updated_at = NOW()
  WHERE id = v_table.id;

  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      updated_at = NOW()
  WHERE table_id = v_table.id;

  RETURN jsonb_build_object(
    'success', true,
    'is_idempotent_replay', false,
    'session_id', p_session_id,
    'settlement_id', v_settlement_id,
    'refunded_count', v_refunded_count,
    'refund_amount_per_player', v_refund_amount
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.refund_game_session(UUID, TEXT, TEXT) TO authenticated, service_role, anon;

-- ==============================================================================
-- 3. EXPIRE GAME TURN SECURE (TIMEOUT AUTORITATIVO SIN SILENCIAR ERRORES)
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_turn_user_id UUID;
  v_lives JSONB;
  v_curr_lives INT;
  v_player_order JSONB;
  v_player_count INT;
  v_winner_id UUID := NULL;
  v_settle_result JSONB;
  v_i INT;
BEGIN
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF v_session.status = 'SETTLED'::session_status_enum THEN
    RETURN jsonb_build_object('success', true, 'action', 'ALREADY_SETTLED');
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_turn_user_id := v_session.current_turn_user_id;

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_TURN');
  END IF;

  v_lives := COALESCE(v_state->'lives', '{}'::jsonb);
  v_curr_lives := COALESCE((v_lives->>v_turn_user_id::text)::INT, 1) - 1;
  v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::text], to_jsonb(v_curr_lives));
  v_state := jsonb_set(v_state, '{lives}', v_lives);

  v_player_order := COALESCE(v_state->'playerOrder', '[]'::jsonb);
  v_player_count := jsonb_array_length(v_player_order);

  -- Si se agotaron las vidas -> Ganador es el oponente
  IF v_curr_lives <= 0 AND v_player_count > 1 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID <> v_turn_user_id THEN
        v_winner_id := (v_player_order->>v_i)::UUID;
        EXIT;
      END IF;
    END LOOP;

    v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
    v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_winner_id::text));
    v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_LIVES_EXHAUSTED"'::jsonb);

    UPDATE public.game_sessions
    SET current_state = v_state,
        winner_user_id = v_winner_id,
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Liquidar partida con RPC universal de forma segura y autoritativa
    v_settle_result := public.universal_settle_game_session(
      p_session_id,
      ARRAY[v_winner_id],
      NULL,
      'timeout_settle_' || p_session_id::text || '_' || extract(epoch from now())::text
    );

    IF (v_settle_result->>'success')::boolean IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'TIMEOUT_SETTLEMENT_FAILED: ' || COALESCE(v_settle_result->>'error', 'Desconocido'),
        'details', v_settle_result
      );
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ENDED_BY_TIMEOUT',
      'winnerUserId', v_winner_id,
      'settlement', v_settle_result
    );
  END IF;

  -- Continuar el juego con siguiente turno si quedan vidas
  UPDATE public.game_sessions
  SET current_state = v_state,
      turn_deadline_at = NOW() + INTERVAL '30 seconds',
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object('success', true, 'action', 'LIVES_DECREMENTED', 'remainingLives', v_curr_lives);
END;
$$;

GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(UUID) TO authenticated, service_role, anon;

-- ==============================================================================
-- 4. CLEANUP STALE PARTICIPATION (RESTITUCIÓN DE ENTRADAS RETENIDAS)
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.cleanup_stale_user_game_participation(
  p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_id UUID;
  v_closed_tables INT := 0;
  v_table_id UUID;
  v_stale_player RECORD;
  v_wallet RECORD;
BEGIN
  v_user_id := COALESCE(p_user_id, auth.uid());
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USER_REQUIRED');
  END IF;

  -- 1) Para mesas cerradas/expiradas/canceladas sin liquidar, restituir la entrada retenida
  FOR v_stale_player IN (
    SELECT gtp.table_id, gt.entry_fee
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    WHERE gtp.user_id = v_user_id
      AND gtp.status <> 'LEFT'::player_table_status_enum
      AND gt.status::text IN ('CLOSED', 'EXPIRED', 'CANCELLED', 'TERMINATED')
      AND NOT EXISTS (
        SELECT 1 FROM public.game_settlements WHERE table_id = gt.id
      )
  ) LOOP
    IF v_stale_player.entry_fee > 0.00 THEN
      SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_user_id FOR UPDATE;
      IF FOUND AND v_wallet.held_balance >= v_stale_player.entry_fee THEN
        UPDATE public.wallets
        SET held_balance = GREATEST(0.00, held_balance - v_stale_player.entry_fee),
            available_balance = available_balance + v_stale_player.entry_fee,
            updated_at = NOW()
        WHERE id = v_wallet.id;

        INSERT INTO public.ledger_entries (
          id, wallet_id, user_id, amount, currency, entry_type, direction,
          reference_id, reference_table, reference_type,
          balance_after, balance_after_available, balance_after_held,
          idempotency_key, description, created_at
        ) VALUES (
          gen_random_uuid(),
          v_wallet.id,
          v_user_id,
          v_stale_player.entry_fee,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_stale_player.table_id,
          'game_tables',
          'game_table',
          v_wallet.available_balance + v_stale_player.entry_fee + GREATEST(0.00, v_wallet.held_balance - v_stale_player.entry_fee),
          v_wallet.available_balance + v_stale_player.entry_fee,
          GREATEST(0.00, v_wallet.held_balance - v_stale_player.entry_fee),
          'cleanup_refund_' || v_stale_player.table_id::text || '_' || v_user_id::text,
          'Reembolso automático de entrada por mesa cerrada/expirada',
          NOW()
        );
      END IF;
    END IF;
  END LOOP;

  -- 2) Marcar status LEFT en mesas inactivas
  UPDATE public.game_table_players gtp
  SET status = 'LEFT'::player_table_status_enum
  FROM public.game_tables gt
  WHERE gt.id = gtp.table_id
    AND gtp.user_id = v_user_id
    AND gtp.status <> 'LEFT'::player_table_status_enum
    AND gt.status::text IN ('CLOSED', 'EXPIRED', 'CANCELLED', 'TERMINATED');

  -- 3) Cerrar mesas huérfanas
  FOR v_table_id IN (
    SELECT DISTINCT gt.id
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    WHERE gtp.user_id = v_user_id
  ) LOOP
    PERFORM public.close_game_table_if_orphaned(v_table_id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_user_id
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_stale_user_game_participation(UUID) TO authenticated, service_role, anon;

-- ==============================================================================
-- 5. REEMBOLSO ATÓMICO PARA SALAS DE BINGO EXPIRADAS / CANCELADAS
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.refund_bingo_table_secure(
  p_table_id UUID,
  p_reason TEXT DEFAULT 'Cancelación/expiración de sala de bingo'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_table RECORD;
  v_purchase RECORD;
  v_wallet RECORD;
  v_refunded_total NUMERIC(14,2) := 0.00;
  v_refunded_count INT := 0;
BEGIN
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'BINGO_TABLE_NOT_FOUND');
  END IF;

  -- Comprobar que no haya sido ya liquidada con premio
  IF EXISTS (SELECT 1 FROM public.game_settlements WHERE table_id = p_table_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'BINGO_TABLE_ALREADY_SETTLED');
  END IF;

  FOR v_purchase IN (
    SELECT * FROM public.bingo_card_purchases
    WHERE game_table_id = p_table_id
    FOR UPDATE
  ) LOOP
    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_purchase.user_id
    FOR UPDATE;

    IF FOUND AND v_purchase.total_cost > 0.00 THEN
      UPDATE public.wallets
      SET held_balance = GREATEST(0.00, held_balance - v_purchase.total_cost),
          available_balance = available_balance + v_purchase.total_cost,
          updated_at = NOW()
      WHERE id = v_wallet.id;

      INSERT INTO public.ledger_entries (
        id, wallet_id, user_id, amount, currency, entry_type, direction,
        reference_id, reference_table, reference_type,
        balance_after, balance_after_available, balance_after_held,
        idempotency_key, description, created_at
      ) VALUES (
        gen_random_uuid(),
        v_wallet.id,
        v_purchase.user_id,
        v_purchase.total_cost,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'CREDIT'::ledger_direction_enum,
        p_table_id,
        'game_tables',
        'game_table',
        v_wallet.available_balance + v_purchase.total_cost + GREATEST(0.00, v_wallet.held_balance - v_purchase.total_cost),
        v_wallet.available_balance + v_purchase.total_cost,
        GREATEST(0.00, v_wallet.held_balance - v_purchase.total_cost),
        'bingo_refund_' || p_table_id::text || '_' || v_purchase.user_id::text,
        p_reason,
        NOW()
      );

      v_refunded_total := v_refunded_total + v_purchase.total_cost;
      v_refunded_count := v_refunded_count + 1;
    END IF;
  END LOOP;

  UPDATE public.game_tables
  SET status = 'CANCELLED'::table_status_enum,
      closed_at = COALESCE(closed_at, NOW()),
      updated_at = NOW()
  WHERE id = p_table_id;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'refunded_purchases_count', v_refunded_count,
    'refunded_total_amount', v_refunded_total
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.refund_bingo_table_secure(UUID, TEXT) TO authenticated, service_role;

-- ==============================================================================
-- 6. AUDITORÍA Y RECONCILIACIÓN FORENSE DE FONDOS HISTÓRICOS
-- ==============================================================================

-- A. Reconciliar sesiones que concluyeron en el juego con ganador pero no se liquidaron
CREATE OR REPLACE FUNCTION public.audit_and_reconcile_unsettled_game_sessions(
  p_dry_run BOOLEAN DEFAULT true
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_session RECORD;
  v_settled_count INT := 0;
  v_items JSONB := '[]'::jsonb;
  v_res JSONB;
BEGIN
  FOR v_session IN (
    SELECT gs.id AS session_id, gs.winner_user_id, gs.table_id, gt.entry_fee, gt.game_type
    FROM public.game_sessions gs
    JOIN public.game_tables gt ON gt.id = gs.table_id
    WHERE gs.status = 'FINISHED'::session_status_enum
      AND gs.winner_user_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.game_settlements st WHERE st.session_id = gs.id
      )
    ORDER BY gs.created_at ASC
  ) LOOP
    IF p_dry_run THEN
      v_items := v_items || jsonb_build_object(
        'session_id', v_session.session_id,
        'winner_user_id', v_session.winner_user_id,
        'table_id', v_session.table_id,
        'entry_fee', v_session.entry_fee,
        'game_type', v_session.game_type,
        'action_required', 'universal_settle_game_session'
      );
    ELSE
      v_res := public.universal_settle_game_session(
        v_session.session_id,
        ARRAY[v_session.winner_user_id],
        NULL,
        'forensic_reconciliation_settle_' || v_session.session_id::text
      );

      IF (v_res->>'success')::boolean = true THEN
        v_settled_count := v_settled_count + 1;
        v_items := v_items || jsonb_build_object(
          'session_id', v_session.session_id,
          'status', 'RECONCILED_AND_SETTLED',
          'settlement_id', v_res->>'settlement_id',
          'prize_pool', v_res->>'prize_pool'
        );
      ELSE
        v_items := v_items || jsonb_build_object(
          'session_id', v_session.session_id,
          'status', 'ERROR',
          'error', v_res->>'error'
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'processed_count', CASE WHEN p_dry_run THEN jsonb_array_length(v_items) ELSE v_settled_count END,
    'details', v_items
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.audit_and_reconcile_unsettled_game_sessions(BOOLEAN) TO authenticated, service_role;

-- B. Reconciliar retenciones huérfanas de mesas cerradas/canceladas sin partidas activas
CREATE OR REPLACE FUNCTION public.audit_and_reconcile_orphan_table_holds(
  p_dry_run BOOLEAN DEFAULT true
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $$
DECLARE
  v_user_wallet RECORD;
  v_active_holds NUMERIC(14,2) := 0.00;
  v_excess_held NUMERIC(14,2) := 0.00;
  v_rescued_count INT := 0;
  v_rescued_total NUMERIC(14,2) := 0.00;
  v_items JSONB := '[]'::jsonb;
BEGIN
  FOR v_user_wallet IN (
    SELECT w.id AS wallet_id, w.user_id, w.held_balance, w.available_balance
    FROM public.wallets w
    WHERE w.held_balance > 0.00
  ) LOOP
    -- Calcular retenciones legítimas activas: mesas donde el usuario está activamente jugando o listo
    SELECT COALESCE(SUM(gt.entry_fee), 0.00) INTO v_active_holds
    FROM public.game_table_players gtp
    JOIN public.game_tables gt ON gt.id = gtp.table_id
    WHERE gtp.user_id = v_user_wallet.user_id
      AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING')
      AND gt.status::text IN ('OPEN', 'FULL', 'STARTING', 'ACTIVE');

    v_excess_held := GREATEST(0.00, v_user_wallet.held_balance - v_active_holds);

    IF v_excess_held > 0.00 THEN
      IF p_dry_run THEN
        v_items := v_items || jsonb_build_object(
          'user_id', v_user_wallet.user_id,
          'current_held', v_user_wallet.held_balance,
          'active_holds', v_active_holds,
          'excess_held_to_rescue', v_excess_held
        );
      ELSE
        UPDATE public.wallets
        SET held_balance = GREATEST(0.00, held_balance - v_excess_held),
            available_balance = available_balance + v_excess_held,
            updated_at = NOW()
        WHERE id = v_user_wallet.wallet_id;

        INSERT INTO public.ledger_entries (
          id, wallet_id, user_id, amount, currency, entry_type, direction,
          reference_id, reference_table, reference_type,
          balance_after, balance_after_available, balance_after_held,
          idempotency_key, description, created_at
        ) VALUES (
          gen_random_uuid(),
          v_user_wallet.wallet_id,
          v_user_wallet.user_id,
          v_excess_held,
          'VES',
          'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
          'CREDIT'::ledger_direction_enum,
          v_user_wallet.wallet_id,
          'wallets',
          'wallet',
          v_user_wallet.available_balance + v_excess_held + GREATEST(0.00, v_user_wallet.held_balance - v_excess_held),
          v_user_wallet.available_balance + v_excess_held,
          GREATEST(0.00, v_user_wallet.held_balance - v_excess_held),
          'forensic_rescue_' || v_user_wallet.wallet_id::text || '_' || extract(epoch from now())::text,
          'Restitución y desbloqueo de saldo retenido huérfano por mesas canceladas/expiradas',
          NOW()
        );

        v_rescued_count := v_rescued_count + 1;
        v_rescued_total := v_rescued_total + v_excess_held;

        v_items := v_items || jsonb_build_object(
          'user_id', v_user_wallet.user_id,
          'rescued_amount', v_excess_held,
          'status', 'RESCUED'
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'rescued_count', CASE WHEN p_dry_run THEN jsonb_array_length(v_items) ELSE v_rescued_count END,
    'rescued_total', v_rescued_total,
    'details', v_items
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.audit_and_reconcile_orphan_table_holds(BOOLEAN) TO authenticated, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 160: 156_DEFINITIVE_TURN_TIMER_TIMEOUT_AND_TICTACTOE_RESOLUTION.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ============================================================================
-- MIGRACIÓN 156: DEFINITIVE TURN TIMER, TIMEOUT AND TICTACTOE RESOLUTION
-- ============================================================================
-- 1. Corrige la comparación de enums en game_type usando game_type::text
--    y los identificadores canónicos reales de public.game_type_enum:
--    ('BINGO', 'ATRAPAITO', 'DOMINO_VENEZOLANO', 'TRUCO_VENEZOLANO', 'DAMAS',
--     'POLLA_VENEZOLANA', 'TRES_EN_RAYA', 'PIEDRA_PAPEL_TIJERA', 'UNA_OLLA', 'CHESS')
-- 2. Establece public.fn_refresh_turn_expires_at() como la ÚNICA fuente autoritativa de deadlines.
-- 3. Evita la sobreescritura errónea del deadline cuando el turno no cambia.
-- 4. Corrige expire_game_turn_secure(UUID) con bloqueo FOR UPDATE, atómico e idempotente.
-- 5. Resuelve Tic Tac Toe / Tres en Raya: primero a 3 victorias (targetWins).
--    Timeout suma score al oponente, reinicia tablero si no se alcanzó la meta,
--    o finaliza y liquida si se alcanzaron 3 victorias.
-- 6. En estados terminales (FINISHED, SETTLED, CANCELLED, ABANDONED):
--    turn_expires_at = NULL, turn_deadline_at = NULL, current_turn_user_id = NULL.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- PARTE 1: Normalizar duraciones de turno de sesiones activas de forma segura
-- ----------------------------------------------------------------------------
-- Excluir explícitamente juegos con reglas de tiempo diferentes o sin turnos
UPDATE public.game_sessions
SET turn_duration_seconds = 30
WHERE status::text IN ('ACTIVE', 'WAITING', 'READY', 'PLAYING')
  AND game_type::text NOT IN ('CHESS', 'PIEDRA_PAPEL_TIJERA', 'BINGO', 'POLLA_VENEZOLANA')
  AND (turn_duration_seconds IS NULL OR turn_duration_seconds != 30);

UPDATE public.game_sessions
SET turn_duration_seconds = 15
WHERE status::text IN ('ACTIVE', 'WAITING', 'READY', 'PLAYING')
  AND game_type::text = 'CHESS'
  AND (turn_duration_seconds IS NULL OR turn_duration_seconds != 15);

-- ----------------------------------------------------------------------------
-- PARTE 2: Trigger Autoritativo Único: fn_refresh_turn_expires_at()
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_refresh_turn_expires_at()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_duration INT;
  v_status TEXT;
  v_old_status TEXT;
  v_turn_changed BOOLEAN := false;
  v_game_type_str TEXT;
BEGIN
  v_old_status := COALESCE(OLD.status::TEXT, 'UNKNOWN');
  v_status := COALESCE(NEW.status::TEXT, 'UNKNOWN');

  -- REGLA CRÍTICA 1: Prevenir flipping / reversión de estado terminal a activo
  IF UPPER(v_old_status) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED')
      AND UPPER(v_status) NOT IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    NEW.status := OLD.status;
    NEW.turn_deadline_at := NULL;
    NEW.turn_expires_at := NULL;
    NEW.current_turn_user_id := NULL;
    RETURN NEW;
  END IF;

  -- REGLA CRÍTICA 2: Si la sesión está en estado terminal, limpiar deadlines y turno
  IF UPPER(v_status) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    NEW.turn_deadline_at := NULL;
    NEW.turn_expires_at := NULL;
    NEW.current_turn_user_id := NULL;
    IF NEW.current_state IS NOT NULL THEN
      NEW.current_state := jsonb_set(NEW.current_state, '{turnExpiresAt}', 'null'::jsonb);
      NEW.current_state := jsonb_set(NEW.current_state, '{turnDeadlineAt}', 'null'::jsonb);
      NEW.current_state := jsonb_set(NEW.current_state, '{currentTurnUserId}', 'null'::jsonb);
      NEW.current_state := jsonb_set(NEW.current_state, '{turnUserId}', 'null'::jsonb);
    END IF;
    RETURN NEW;
  END IF;

  -- REGLA CRÍTICA 3: Solo refrescar si el juego está en estado activo / jugable
  IF UPPER(v_status) IN ('ACTIVE', 'WAITING', 'READY', 'SALES', 'DRAWING', 'PLAYING', 'ROUND_COMMIT') THEN
    -- Determinar tipo de juego
    v_game_type_str := COALESCE(NEW.game_type::TEXT, '');
    IF v_game_type_str = '' AND NEW.table_id IS NOT NULL THEN
      SELECT game_type::TEXT INTO v_game_type_str
      FROM public.game_tables
      WHERE id = NEW.table_id;
    END IF;

    -- Bingo y Polla no tienen temporizadores de turno individual
    IF UPPER(v_game_type_str) IN ('BINGO', 'POLLA_VENEZOLANA') THEN
      RETURN NEW;
    END IF;

    -- Detectar si hubo cambio de turno, inicio de partida o avance de ronda
    IF TG_OP = 'INSERT' THEN
      v_turn_changed := true;
    ELSIF (OLD.current_turn_user_id IS DISTINCT FROM NEW.current_turn_user_id)
       OR (OLD.turn_deadline_at IS NULL AND NEW.current_turn_user_id IS NOT NULL)
       OR (UPPER(v_old_status) NOT IN ('ACTIVE', 'PLAYING') AND UPPER(v_status) IN ('ACTIVE', 'PLAYING'))
       OR (COALESCE(OLD.current_state->>'round', '') IS DISTINCT FROM COALESCE(NEW.current_state->>'round', '')) THEN
      v_turn_changed := true;
    END IF;

    -- Determinar duración autoritativa
    IF UPPER(v_game_type_str) = 'CHESS' THEN
      v_duration := 15;
    ELSE
      v_duration := COALESCE(
        NULLIF((NEW.current_state->>'turnDurationSeconds'), '')::INT,
        NEW.turn_duration_seconds,
        30
      );
      IF v_duration <= 0 THEN
        v_duration := 30;
      END IF;
    END IF;

    NEW.turn_duration_seconds := v_duration;

    IF v_turn_changed THEN
      -- Generar NUEVO deadline autoritativo del servidor
      NEW.turn_expires_at := NOW() + (v_duration || ' seconds')::INTERVAL;
      NEW.turn_deadline_at := NEW.turn_expires_at;

      -- Sincronizar también en current_state
      IF NEW.current_state IS NOT NULL THEN
        NEW.current_state := jsonb_set(NEW.current_state, '{turnDurationSeconds}', to_jsonb(v_duration));
        NEW.current_state := jsonb_set(NEW.current_state, '{turnExpiresAt}', to_jsonb(to_char(NEW.turn_expires_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
        NEW.current_state := jsonb_set(NEW.current_state, '{turnDeadlineAt}', to_jsonb(to_char(NEW.turn_expires_at, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
        IF NEW.current_turn_user_id IS NOT NULL THEN
          NEW.current_state := jsonb_set(NEW.current_state, '{currentTurnUserId}', to_jsonb(NEW.current_turn_user_id::text));
          NEW.current_state := jsonb_set(NEW.current_state, '{turnUserId}', to_jsonb(NEW.current_turn_user_id::text));
        END IF;
      END IF;
    ELSE
      -- Si NO cambió de turno, PRESERVAR el deadline existente del servidor para no reiniciar el reloj
      IF TG_OP = 'UPDATE' AND OLD.turn_deadline_at IS NOT NULL THEN
        NEW.turn_deadline_at := OLD.turn_deadline_at;
        NEW.turn_expires_at := OLD.turn_expires_at;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- Vincular trigger tanto en INSERT como en UPDATE
DROP TRIGGER IF EXISTS trg_refresh_turn_expires_at ON public.game_sessions;
CREATE TRIGGER trg_refresh_turn_expires_at
BEFORE INSERT OR UPDATE ON public.game_sessions
FOR EACH ROW
EXECUTE FUNCTION public.fn_refresh_turn_expires_at();

-- ----------------------------------------------------------------------------
-- PARTE 3: expire_game_turn_secure(p_session_id uuid) Atómico e Idempotente
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_game_type_str TEXT;
  v_turn_user_id UUID;
  v_opponent_id UUID := NULL;
  v_player_order JSONB;
  v_player_count INT := 0;
  v_scores JSONB;
  v_opp_score INT := 0;
  v_target_wins INT := 3;
  v_curr_round INT := 1;
  v_duration INT := 30;
  v_new_deadline TIMESTAMPTZ;
  v_lives JSONB;
  v_curr_lives INT;
  v_settle_result JSONB;
  v_i INT;
  v_p RECORD;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  -- 1. Bloqueo Pesimista Estricto (FOR UPDATE)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 2. Idempotencia: Sesión ya cerrada, finalizada o liquidada
  IF UPPER(v_session.status::TEXT) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_FINALIZED',
      'status', v_session.status::text
    );
  END IF;

  -- 3. Idempotencia Temporal: Si el turno aún no ha expirado (margen de gracia de 1s)
  IF v_session.turn_deadline_at IS NOT NULL AND v_session.turn_deadline_at > (NOW() + INTERVAL '1 second') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_NOT_EXPIRED',
      'currentTurnUserId', v_session.current_turn_user_id,
      'turnDeadlineAt', v_session.turn_deadline_at
    );
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);

  -- 4. Determinar jugador en turno
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID,
    (v_state->>'currentTurnUserId')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_TURN');
  END IF;

  -- 5. Determinar tipo de juego canónico
  v_game_type_str := UPPER(COALESCE(v_session.game_type::TEXT, ''));
  IF v_game_type_str = '' THEN
    SELECT UPPER(game_type::TEXT) INTO v_game_type_str
    FROM public.game_tables
    WHERE id = v_session.table_id;
  END IF;

  -- 6. Resolver participantes y oponente de forma autoritativa
  v_player_order := COALESCE(v_state->'playerOrder', '[]'::jsonb);
  v_player_count := COALESCE(jsonb_array_length(v_player_order), 0);

  IF v_player_count = 0 THEN
    SELECT jsonb_agg(user_id ORDER BY seat_number ASC)
    INTO v_player_order
    FROM public.game_table_players
    WHERE table_id = v_session.table_id AND status != 'LEFT';
    v_player_count := COALESCE(jsonb_array_length(v_player_order), 0);
  END IF;

  -- Encontrar el oponente directo
  IF v_player_count > 0 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID <> v_turn_user_id THEN
        v_opponent_id := (v_player_order->>v_i)::UUID;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_opponent_id IS NULL THEN
    SELECT user_id INTO v_opponent_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id <> v_turn_user_id
      AND status != 'LEFT'
    LIMIT 1;
  END IF;

  -- Fallback de oponente desde current_state si los jugadores de la mesa ya cambiaron
  IF v_opponent_id IS NULL AND v_state ? 'playerSymbols' THEN
    BEGIN
      SELECT key::UUID INTO v_opponent_id
      FROM jsonb_each_text(v_state->'playerSymbols')
      WHERE key <> v_turn_user_id::text
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_opponent_id := NULL;
    END;
  END IF;

  IF v_opponent_id IS NULL AND v_state ? 'playerNames' THEN
    BEGIN
      SELECT key::UUID INTO v_opponent_id
      FROM jsonb_each_text(v_state->'playerNames')
      WHERE key <> v_turn_user_id::text
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_opponent_id := NULL;
    END;
  END IF;

  IF v_opponent_id IS NULL AND v_state ? 'scores' THEN
    BEGIN
      SELECT key::UUID INTO v_opponent_id
      FROM jsonb_each_text(v_state->'scores')
      WHERE key <> v_turn_user_id::text
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
      v_opponent_id := NULL;
    END;
  END IF;

  -- Si tras todos los fallbacks no existe oponente, cancelar la sesión huérfana de forma limpia
  IF v_opponent_id IS NULL THEN
    UPDATE public.game_sessions
    SET status = 'CANCELLED'::session_status_enum,
        turn_deadline_at = NULL,
        turn_expires_at = NULL,
        current_turn_user_id = NULL,
        updated_at = NOW()
    WHERE id = p_session_id;

    PERFORM public.refund_game_session(
      p_session_id,
      'Sesión huérfana cancelada por timeout sin oponente válido',
      'orphan_timeout_' || p_session_id::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', 'SESSION_CANCELLED_NO_OPPONENT',
      'sessionId', p_session_id
    );
  END IF;

  -- --------------------------------------------------------------------------
  -- CASO 1: TIC TAC TOE / TRES EN RAYA / LA VIEJA (Al mejor de 3 victorias)
  -- --------------------------------------------------------------------------
  IF v_game_type_str IN ('TRES_EN_RAYA', 'TICTACTOE', 'TIC_TAC_TOE') THEN
    v_target_wins := COALESCE(NULLIF(v_state->>'targetWins', '')::INT, 3);
    v_scores := COALESCE(v_state->'scores', '{}'::jsonb);
    v_opp_score := COALESCE((v_scores->>v_opponent_id::text)::INT, 0) + 1;
    v_scores := jsonb_set(v_scores, ARRAY[v_opponent_id::text], to_jsonb(v_opp_score));

    -- Comprobar si el oponente alcanzó la meta de victorias (3)
    IF v_opp_score >= v_target_wins THEN
      -- MATCH_ENDED: Finalizar partida definitivamente
      v_state := jsonb_set(v_state, '{scores}', v_scores);
      v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
      v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_opponent_id::text));
      v_state := jsonb_set(v_state, '{roundWinnerUserId}', to_jsonb(v_opponent_id::text));
      v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_TARGET_WINS_REACHED"'::jsonb);
      v_state := jsonb_set(v_state, '{turnExpiresAt}', 'null'::jsonb);
      v_state := jsonb_set(v_state, '{turnDeadlineAt}', 'null'::jsonb);
      v_state := jsonb_set(v_state, '{currentTurnUserId}', 'null'::jsonb);
      v_state := jsonb_set(v_state, '{turnUserId}', 'null'::jsonb);

      UPDATE public.game_sessions
      SET current_state = v_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_opponent_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          current_turn_user_id = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      -- Liquidación oficial universal
      v_settle_result := public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_opponent_id],
        NULL,
        'ttt_timeout_' || p_session_id::text || '_' || EXTRACT(EPOCH FROM NOW())::int::text
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'MATCH_ENDED_BY_TIMEOUT',
        'winnerUserId', v_opponent_id,
        'finalScores', v_scores,
        'settlement', v_settle_result
      );
    ELSE
      -- ROUND_RESULT: Avanzar a la siguiente ronda con tablero limpio
      v_curr_round := COALESCE(NULLIF(v_state->>'round', '')::INT, 1) + 1;
      v_duration := 30;
      v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

      v_state := jsonb_set(v_state, '{scores}', v_scores);
      v_state := jsonb_set(v_state, '{round}', to_jsonb(v_curr_round));
      v_state := jsonb_set(v_state, '{board}', '[null,null,null,null,null,null,null,null,null]'::jsonb);
      v_state := jsonb_set(v_state, '{winningLine}', 'null'::jsonb);
      v_state := jsonb_set(v_state, '{roundWinnerUserId}', to_jsonb(v_opponent_id::text));
      v_state := jsonb_set(v_state, '{moveHistory}', '[]'::jsonb);
      v_state := jsonb_set(v_state, '{status}', '"playing"'::jsonb);
      v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_opponent_id::text));
      v_state := jsonb_set(v_state, '{currentTurnUserId}', to_jsonb(v_opponent_id::text));
      v_state := jsonb_set(v_state, '{turnExpiresAt}', to_jsonb(to_char(v_new_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
      v_state := jsonb_set(v_state, '{turnDeadlineAt}', to_jsonb(to_char(v_new_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));

      UPDATE public.game_sessions
      SET current_state = v_state,
          current_turn_user_id = v_opponent_id,
          turn_duration_seconds = v_duration,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'ROUND_WON_BY_TIMEOUT',
        'roundWinnerUserId', v_opponent_id,
        'newRound', v_curr_round,
        'scores', v_scores,
        'nextTurnUserId', v_opponent_id,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- --------------------------------------------------------------------------
  -- CASO 2: AJEDREZ (CHESS) Y DAMAS (Damas timeout = victoria oponente)
  -- --------------------------------------------------------------------------
  IF v_game_type_str IN ('CHESS', 'DAMAS') THEN
    IF v_opponent_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'OPPONENT_NOT_FOUND');
    END IF;

    v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
    v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_opponent_id::text));
    v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_FORFEIT"'::jsonb);
    v_state := jsonb_set(v_state, '{turnExpiresAt}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{turnDeadlineAt}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{currentTurnUserId}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{turnUserId}', 'null'::jsonb);

    UPDATE public.game_sessions
    SET current_state = v_state,
        status = 'FINISHED'::session_status_enum,
        winner_user_id = v_opponent_id,
        turn_deadline_at = NULL,
        turn_expires_at = NULL,
        current_turn_user_id = NULL,
        ended_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    v_settle_result := public.universal_settle_game_session(
      p_session_id,
      ARRAY[v_opponent_id],
      NULL,
      'timeout_' || lower(v_game_type_str) || '_' || p_session_id::text || '_' || EXTRACT(EPOCH FROM NOW())::int::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ENDED_BY_TIMEOUT',
      'gameType', v_game_type_str,
      'winnerUserId', v_opponent_id,
      'settlement', v_settle_result
    );
  END IF;

  -- --------------------------------------------------------------------------
  -- CASO 3: OTROS JUEGOS SECUENCIALES (SISTEMA RESILIENTE DE VIDAS / ROTACIÓN)
  -- --------------------------------------------------------------------------
  v_lives := COALESCE(v_state->'lives', '{}'::jsonb);
  v_curr_lives := COALESCE((v_lives->>v_turn_user_id::text)::INT, 3) - 1;
  IF v_curr_lives < 0 THEN
    v_curr_lives := 0;
  END IF;
  v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::text], to_jsonb(v_curr_lives));
  v_state := jsonb_set(v_state, '{lives}', v_lives);

  IF v_curr_lives <= 0 AND v_opponent_id IS NOT NULL THEN
    -- Vidas agotadas: victoria definitiva para el oponente
    v_state := jsonb_set(v_state, '{status}', '"game_won"'::jsonb);
    v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_opponent_id::text));
    v_state := jsonb_set(v_state, '{finishReason}', '"TIMEOUT_LIVES_EXHAUSTED"'::jsonb);
    v_state := jsonb_set(v_state, '{turnExpiresAt}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{turnDeadlineAt}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{currentTurnUserId}', 'null'::jsonb);
    v_state := jsonb_set(v_state, '{turnUserId}', 'null'::jsonb);

    UPDATE public.game_sessions
    SET current_state = v_state,
        status = 'FINISHED'::session_status_enum,
        winner_user_id = v_opponent_id,
        turn_deadline_at = NULL,
        turn_expires_at = NULL,
        current_turn_user_id = NULL,
        ended_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    v_settle_result := public.universal_settle_game_session(
      p_session_id,
      ARRAY[v_opponent_id],
      NULL,
      'timeout_settle_' || p_session_id::text || '_' || EXTRACT(EPOCH FROM NOW())::int::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ENDED_BY_TIMEOUT',
      'winnerUserId', v_opponent_id,
      'settlement', v_settle_result
    );
  ELSE
    -- Aún quedan vidas: rotar turno al oponente con un nuevo deadline autoritativo
    v_duration := COALESCE(
      NULLIF((v_state->>'turnDurationSeconds'), '')::INT,
      v_session.turn_duration_seconds,
      30
    );
    v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

    v_state := jsonb_set(v_state, '{turnUserId}', to_jsonb(v_opponent_id::text));
    v_state := jsonb_set(v_state, '{currentTurnUserId}', to_jsonb(v_opponent_id::text));
    v_state := jsonb_set(v_state, '{turnExpiresAt}', to_jsonb(to_char(v_new_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
    v_state := jsonb_set(v_state, '{turnDeadlineAt}', to_jsonb(to_char(v_new_deadline, 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_opponent_id,
        turn_duration_seconds = v_duration,
        turn_deadline_at = v_new_deadline,
        turn_expires_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'LIVES_DECREMENTED',
      'remainingLives', v_curr_lives,
      'nextTurnUserId', v_opponent_id,
      'turnDeadlineAt', v_new_deadline
    );
  END IF;
END;
$function$;

-- ----------------------------------------------------------------------------
-- PARTE 4: expire_game_turn_secure() batch sin argumentos
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_row RECORD;
  v_count INT := 0;
  v_res JSONB;
BEGIN
  FOR v_row IN (
    SELECT gs.id
    FROM public.game_sessions gs
    JOIN public.game_tables gt ON gt.id = gs.table_id
    WHERE gs.status::text IN ('ACTIVE', 'READY', 'STARTING', 'PLAYING')
      AND gt.game_type::text NOT IN ('BINGO', 'POLLA_VENEZOLANA')
      AND gs.current_turn_user_id IS NOT NULL
      AND (
        (gs.turn_deadline_at IS NOT NULL AND gs.turn_deadline_at < NOW())
        OR
        (gs.turn_expires_at IS NOT NULL AND gs.turn_expires_at < NOW())
      )
    ORDER BY COALESCE(gs.turn_deadline_at, gs.turn_expires_at) ASC
    LIMIT 20
  ) LOOP
    BEGIN
      v_res := public.expire_game_turn_secure(v_row.id);
      IF (v_res->>'success')::boolean IS TRUE THEN
        v_count := v_count + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Error expirando sesión %: %', v_row.id, SQLERRM;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'expired_count', v_count,
    'processed_at', NOW()
  );
END;
$function$;

-- ----------------------------------------------------------------------------
-- PARTE 5: process_expired_turns() Actualizado para usar expire_game_turn_secure
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.process_expired_turns()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_expired_row RECORD;
  v_p1_id UUID;
  v_p2_id UUID;
  v_p1_committed BOOLEAN;
  v_p2_committed BOOLEAN;
  v_winner_id UUID;
  v_loser_id UUID;
  v_secret_choices JSONB;
  v_idempotency_key VARCHAR(100);
  v_curr_round INT;
  v_new_state JSONB;
BEGIN
  -- A. JUEGOS SECUENCIALES: Invocar expire_game_turn_secure autoritativo
  FOR v_expired_row IN
    SELECT s.id
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active', 'PLAYING', 'playing')
      AND s.current_turn_user_id IS NOT NULL
      AND t.game_type::text NOT IN ('rock_paper_scissors', 'rps', 'PIEDRA_PAPEL_TIJERA', 'BINGO', 'POLLA_VENEZOLANA')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      PERFORM public.expire_game_turn_secure(v_expired_row.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en juego secuencial %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;

  -- B. PIEDRA, PAPEL O TIJERA (ROUND_DEADLINE simultáneo)
  FOR v_expired_row IN
    SELECT s.id, s.table_id, s.current_state, s.created_at, s.turn_expires_at
    FROM public.game_sessions s
    JOIN public.game_tables t ON t.id = s.table_id
    WHERE s.status::text IN ('ACTIVE', 'active', 'PLAYING', 'playing')
      AND t.game_type::text IN ('rock_paper_scissors', 'rps', 'PIEDRA_PAPEL_TIJERA')
      AND (
        (s.turn_expires_at IS NOT NULL AND s.turn_expires_at < NOW())
        OR
        (s.turn_deadline_at IS NOT NULL AND s.turn_deadline_at < NOW())
      )
      AND COALESCE(s.current_state->>'status', '') IN ('ROUND_COMMIT', 'selecting')
    FOR UPDATE OF s SKIP LOCKED
  LOOP
    BEGIN
      v_curr_round := COALESCE((v_expired_row.current_state->>'roundNumber')::int, 1);
      v_idempotency_key := 'rps_timeout_' || v_expired_row.id::text || '_rnd_' || v_curr_round::text;

      v_p1_id := NULLIF(TRIM(v_expired_row.current_state->>'player1Id'), '')::uuid;
      v_p2_id := NULLIF(TRIM(v_expired_row.current_state->>'player2Id'), '')::uuid;
      IF v_p1_id IS NULL THEN
        SELECT user_id INTO v_p1_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;
      IF v_p2_id IS NULL THEN
        SELECT user_id INTO v_p2_id
        FROM public.game_table_players
        WHERE table_id = v_expired_row.table_id
          AND user_id != v_p1_id
          AND status NOT IN ('LEFT')
        ORDER BY seat_number ASC, joined_at ASC
        LIMIT 1;
      END IF;

      SELECT secret_state->'rps_choices' INTO v_secret_choices
      FROM public.game_session_secrets
      WHERE session_id = v_expired_row.id;

      v_p1_committed := (v_secret_choices ? v_p1_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p1_id::text)->>'committed')::boolean, false);
      v_p2_committed := (v_secret_choices ? v_p2_id::text) OR
                        COALESCE((v_expired_row.current_state->'playerChoices'->(v_p2_id::text)->>'committed')::boolean, false);

      IF v_p1_committed AND NOT v_p2_committed THEN
        v_winner_id := v_p1_id;
        v_loser_id := v_p2_id;
      ELSIF v_p2_committed AND NOT v_p1_committed THEN
        v_winner_id := v_p2_id;
        v_loser_id := v_p1_id;
      ELSE
        v_winner_id := NULL;
        v_loser_id := NULL;
      END IF;

      IF v_winner_id IS NOT NULL THEN
        v_new_state := COALESCE(v_expired_row.current_state, '{}'::jsonb) || jsonb_build_object(
          'winnerUserId', v_winner_id,
          'abandonedBy', v_loser_id,
          'status', 'MATCH_ENDED',
          'phase', 'match_ended'
        );
        UPDATE public.game_sessions
        SET current_state = v_new_state,
            status = 'FINISHED'::session_status_enum,
            winner_user_id = v_winner_id,
            turn_deadline_at = NULL,
            turn_expires_at = NULL,
            current_turn_user_id = NULL,
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        PERFORM public.universal_settle_game_session(
          v_expired_row.id,
          ARRAY[v_winner_id],
          NULL::int,
          v_idempotency_key
        );
      ELSE
        v_new_state := COALESCE(v_expired_row.current_state, '{}'::jsonb) || jsonb_build_object(
          'cancelReason', 'ROUND_TIMEOUT_NO_CHOICES',
          'status', 'MATCH_CANCELLED'
        );
        UPDATE public.game_sessions
        SET current_state = v_new_state,
            status = 'CANCELLED'::session_status_enum,
            turn_deadline_at = NULL,
            turn_expires_at = NULL,
            current_turn_user_id = NULL,
            updated_at = NOW()
        WHERE id = v_expired_row.id;

        PERFORM public.refund_game_session(
          v_expired_row.id,
          'Tiempo de ronda agotado sin jugadas de ningún participante',
          v_idempotency_key
        );
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[process_expired_turns] Error en ronda simultánea RPS %: %', v_expired_row.id, SQLERRM;
    END;
  END LOOP;
END;
$function$;

-- ----------------------------------------------------------------------------
-- PARTE 6: cron_expire_turns_loop() No-bloqueante
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.cron_expire_turns_loop()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  PERFORM public.expire_game_turn_secure();
  PERFORM public.detect_disconnected_players();
END;
$function$;




-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 161: 157_FIX_START_GAME_SESSION_PROFILES_COLUMN.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 157: CORRECCIÓN DEFINITIVA DE START_GAME_SESSION_SECURE
-- ==============================================================================
-- 1. Corrige 'p.username' inexistente en public.profiles reemplazándolo por
--    COALESCE(NULLIF(TRIM(p.display_name), ''), NULLIF(TRIM(p.first_name || ' ' || COALESCE(p.last_name, '')), ''), NULLIF(TRIM(p.nombre_real), ''), 'Jugador ' || gtp.seat_number)
-- 2. Corrige el cast erróneo 'table_player_status_enum' por el enum canónico real 'player_table_status_enum'.
-- ==============================================================================

CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id uuid,
  p_initial_state jsonb DEFAULT NULL::jsonb,
  p_turn_duration_seconds integer DEFAULT 30,
  p_initial_turn_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_table RECORD;
  v_session RECORD;
  v_players JSONB;
  v_unique_players INT;
  v_game_type TEXT;
  v_session_status TEXT;
  v_initial_state JSONB;
  v_host_id UUID;
  v_effective_turn_user_id UUID;
  v_deadline TIMESTAMPTZ;
  v_session_number INT;
  v_effective_duration INT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NO_AUTENTICADO: Debes iniciar sesión para comenzar la partida.';
  END IF;

  -- 1. Bloquear y obtener la mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MESA_NO_ENCONTRADA: La mesa especificada no existe.';
  END IF;

  v_host_id := v_table.host_user_id;
  v_effective_duration := COALESCE(p_turn_duration_seconds, 30);

  -- 2. Obtener lista autoritativa de jugadores utilizando columnas reales de profiles
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'userId', gtp.user_id,
        'user_id', gtp.user_id,
        'displayName', COALESCE(
          NULLIF(TRIM(p.display_name), ''),
          NULLIF(TRIM(p.first_name || ' ' || COALESCE(p.last_name, '')), ''),
          NULLIF(TRIM(p.nombre_real), ''),
          'Jugador ' || gtp.seat_number
        ),
        'seatNumber', gtp.seat_number,
        'seat_number', gtp.seat_number,
        'status', gtp.status
      ) ORDER BY gtp.seat_number ASC
    ),
    '[]'::jsonb
  ) INTO v_players
  FROM public.game_table_players gtp
  LEFT JOIN public.profiles p ON p.user_id = gtp.user_id
  WHERE gtp.table_id = p_table_id
    AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING');

  v_unique_players := COALESCE(jsonb_array_length(v_players), 0);
  IF v_unique_players < 1 THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: No hay jugadores activos en la mesa.';
  END IF;

  IF v_unique_players < 2
     AND lower(v_table.game_type::text) NOT IN ('bingo', 'bingo_75', 'bingo_90', 'polla', 'polla_venezolana')
     AND COALESCE((v_table.config->>'isPractice')::boolean, false) IS NOT TRUE
     AND COALESCE((p_initial_state->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND COALESCE((v_table.config->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND v_table.min_players > 1
  THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: Se requieren al menos % jugadores para iniciar la partida (actualmente hay %).', v_table.min_players, v_unique_players;
  END IF;

  -- 3. Idempotencia estricta: Verificar si ya existe una sesión activa
  SELECT * INTO v_session FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text NOT IN ('FINISHED', 'CANCELLED', 'SETTLED', 'ABANDONED')
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'alreadyActive', true,
      'already_active', true,
      'source', 'existing_db_session',
      'sessionId', v_session.id,
      'session_id', v_session.id,
      'tableId', p_table_id,
      'table_id', p_table_id,
      'status', v_session.status::text,
      'currentTurnUserId', v_session.current_turn_user_id,
      'current_turn_user_id', v_session.current_turn_user_id,
      'turnUserId', v_session.current_turn_user_id,
      'turnDurationSeconds', COALESCE(v_session.turn_duration_seconds, 30),
      'turnDeadlineAt', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turn_deadline_at', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turnDeadline', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'gameState', v_session.current_state,
      'game_state', v_session.current_state,
      'players', v_players
    );
  END IF;

  -- 4. Resolver tipo de juego, turno inicial y deadline
  v_game_type := lower(v_table.game_type::text);
  v_effective_turn_user_id := COALESCE(
    p_initial_turn_user_id,
    (p_initial_state->>'turnUserId')::uuid,
    (p_initial_state->>'currentTurnUserId')::uuid
  );

  IF v_effective_turn_user_id IS NULL AND v_players IS NOT NULL AND jsonb_array_length(v_players) > 0 THEN
    v_effective_turn_user_id := (v_players->0->>'user_id')::uuid;
  END IF;

  v_deadline := CASE
    WHEN v_effective_duration > 0
    THEN NOW() + (v_effective_duration || ' seconds')::interval
    ELSE NULL
  END;

  -- 5. Determinar estado inicial y estado de sesión
  IF v_game_type IN ('bingo', 'bingo_75', 'bingo_90') THEN
    v_session_status := 'WAITING';
    v_initial_state := jsonb_build_object(
      'status', 'SALES',
      'variant', COALESCE((to_jsonb(v_table)->>'game_variant'), '90'),
      'mode', COALESCE(((to_jsonb(v_table)->'config')->>'mode')::int, 90),
      'hostUserId', v_host_id,
      'seed', floor(random() * 1000000000)::int,
      'cards', '{}'::jsonb,
      'cardsPurchased', '{}'::jsonb,
      'drawnBalls', '[]'::jsonb,
      'currentBall', NULL,
      'players', v_players,
      'startedAt', NOW()
    );
  ELSIF v_game_type IN ('polla', 'polla_venezolana') THEN
    v_session_status := 'WAITING';
    v_initial_state := jsonb_build_object(
      'status', 'OPEN_PICKS',
      'fixtures', '[]'::jsonb,
      'predictions', '{}'::jsonb,
      'players', v_players,
      'startedAt', NOW()
    );
  ELSE
    v_session_status := 'ACTIVE';
    IF p_initial_state IS NOT NULL THEN
      v_initial_state := p_initial_state;
      -- Garantizar campos de turno autoritativos
      v_initial_state := jsonb_set(v_initial_state, '{turnDurationSeconds}', to_jsonb(v_effective_duration));
      IF v_effective_turn_user_id IS NOT NULL THEN
        v_initial_state := jsonb_set(v_initial_state, '{turnUserId}', to_jsonb(v_effective_turn_user_id::text));
        v_initial_state := jsonb_set(v_initial_state, '{currentTurnUserId}', to_jsonb(v_effective_turn_user_id::text));
      END IF;
    ELSE
      v_initial_state := jsonb_build_object(
        'status', 'PLAYING',
        'currentTurnUserId', v_effective_turn_user_id,
        'turnUserId', v_effective_turn_user_id,
        'turnDurationSeconds', v_effective_duration,
        'turnDeadline', v_deadline,
        'round', 1,
        'players', v_players,
        'startedAt', NOW()
      );
    END IF;
  END IF;

  -- Calcular session_number secuencial
  SELECT COALESCE(MAX(session_number), 0) + 1 INTO v_session_number
  FROM public.game_sessions
  WHERE table_id = p_table_id;

  -- 6. Insertar la nueva sesión utilizando columnas canónicas verificadas
  INSERT INTO public.game_sessions (
    table_id,
    game_type,
    session_number,
    status,
    current_state,
    current_turn_user_id,
    turn_duration_seconds,
    turn_deadline_at,
    turn_expires_at,
    started_at,
    created_at,
    updated_at
  ) VALUES (
    p_table_id,
    v_table.game_type,
    v_session_number,
    v_session_status::session_status_enum,
    v_initial_state,
    v_effective_turn_user_id,
    v_effective_duration,
    v_deadline,
    v_deadline,
    NOW(),
    NOW(),
    NOW()
  ) RETURNING * INTO v_session;

  -- 7. Actualizar mesa a ACTIVE
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 8. Actualizar participantes a PLAYING usando player_table_status_enum
  UPDATE public.game_table_players
  SET status = 'PLAYING'::player_table_status_enum,
      joined_at = COALESCE(joined_at, NOW())
  WHERE table_id = p_table_id
    AND status::text IN ('JOINED', 'READY');

  RETURN jsonb_build_object(
    'success', true,
    'alreadyActive', false,
    'already_active', false,
    'source', 'created_new_db_session',
    'sessionId', v_session.id,
    'session_id', v_session.id,
    'tableId', p_table_id,
    'table_id', p_table_id,
    'status', v_session.status::text,
    'currentTurnUserId', v_effective_turn_user_id,
    'current_turn_user_id', v_effective_turn_user_id,
    'turnUserId', v_effective_turn_user_id,
    'turnDurationSeconds', v_effective_duration,
    'turnDeadlineAt', v_deadline,
    'turn_deadline_at', v_deadline,
    'turnDeadline', v_deadline,
    'gameState', v_initial_state,
    'game_state', v_initial_state,
    'players', v_players
  );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(uuid, jsonb, integer, uuid) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 162: 158_rps_turn_coherence_and_timeout_delegation.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- MIGRACIÓN 158: COHERENCIA DE TURNOS EN JUEGOS SIMULTÁNEOS (RPS) Y DELEGACIÓN DE TIMEOUT
-- ==============================================================================
-- 1. start_game_session_secure:
--    Garantiza que para juegos simultáneos (Piedra, Papel o Tijera, Bingo, Polla),
--    NO se asigne arbitrariamente un jugador en current_turn_user_id ni turnUserId.
--    El valor devuelto y persistido es estrictamente NULL, manteniendo coherencia
--    absoluta con el protocolo Commit-Reveal y eliminando divergencias entre RPC y frontend.
--
-- 2. expire_game_turn_secure(p_session_id uuid):
--    Incorpora soporte autoritativo para Piedra, Papel o Tijera (RPS).
--    Si vence el deadline de la ronda commit (15s):
--    - Si un jugador envió su jugada y el otro no: el jugador cumplidor gana la partida
--      por inactividad/abandono del rival y se liquida oficialmente mediante universal_settle_game_session (90/10).
--    - Si ninguno envió su jugada: la partida se cancela y se reembolsa al 100% mediante refund_game_session.
-- ==============================================================================

-- 1. ACTUALIZACIÓN DE START_GAME_SESSION_SECURE CON PROTECCIÓN PARA JUEGOS SIMULTÁNEOS
CREATE OR REPLACE FUNCTION public.start_game_session_secure(
  p_table_id uuid,
  p_initial_state jsonb DEFAULT NULL::jsonb,
  p_turn_duration_seconds integer DEFAULT 30,
  p_initial_turn_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_table RECORD;
  v_session RECORD;
  v_players JSONB;
  v_unique_players INT;
  v_game_type TEXT;
  v_session_status TEXT;
  v_initial_state JSONB;
  v_host_id UUID;
  v_effective_turn_user_id UUID;
  v_deadline TIMESTAMPTZ;
  v_session_number INT;
  v_effective_duration INT;
  v_is_simultaneous BOOLEAN := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'NO_AUTENTICADO: Debes iniciar sesión para comenzar la partida.';
  END IF;

  -- 1. Bloquear y obtener la mesa
  SELECT * INTO v_table FROM public.game_tables WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'MESA_NO_ENCONTRADA: La mesa especificada no existe.';
  END IF;

  v_host_id := v_table.host_user_id;
  v_effective_duration := COALESCE(p_turn_duration_seconds, 30);

  -- 2. Obtener lista autoritativa de jugadores utilizando columnas reales de profiles
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'userId', gtp.user_id,
        'user_id', gtp.user_id,
        'displayName', COALESCE(
          NULLIF(TRIM(p.display_name), ''),
          NULLIF(TRIM(p.first_name || ' ' || COALESCE(p.last_name, '')), ''),
          NULLIF(TRIM(p.nombre_real), ''),
          'Jugador ' || gtp.seat_number
        ),
        'seatNumber', gtp.seat_number,
        'seat_number', gtp.seat_number,
        'status', gtp.status
      ) ORDER BY gtp.seat_number ASC
    ),
    '[]'::jsonb
  ) INTO v_players
  FROM public.game_table_players gtp
  LEFT JOIN public.profiles p ON p.user_id = gtp.user_id
  WHERE gtp.table_id = p_table_id
    AND gtp.status::text IN ('JOINED', 'READY', 'PLAYING');

  v_unique_players := COALESCE(jsonb_array_length(v_players), 0);
  IF v_unique_players < 1 THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: No hay jugadores activos en la mesa.';
  END IF;

  IF v_unique_players < 2
     AND lower(v_table.game_type::text) NOT IN ('bingo', 'bingo_75', 'bingo_90', 'polla', 'polla_venezolana')
     AND COALESCE((v_table.config->>'isPractice')::boolean, false) IS NOT TRUE
     AND COALESCE((p_initial_state->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND COALESCE((v_table.config->>'mode')::text, '') NOT IN ('VS_AI', 'PRACTICE', 'SOLO')
     AND v_table.min_players > 1
  THEN
    RAISE EXCEPTION 'JUGADORES_INSUFICIENTES: Se requieren al menos % jugadores para iniciar la partida (actualmente hay %).', v_table.min_players, v_unique_players;
  END IF;

  -- 3. Idempotencia estricta: Verificar si ya existe una sesión activa
  SELECT * INTO v_session FROM public.game_sessions
  WHERE table_id = p_table_id
    AND status::text NOT IN ('FINISHED', 'CANCELLED', 'SETTLED', 'ABANDONED')
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'alreadyActive', true,
      'already_active', true,
      'source', 'existing_db_session',
      'sessionId', v_session.id,
      'session_id', v_session.id,
      'tableId', p_table_id,
      'table_id', p_table_id,
      'status', v_session.status::text,
      'currentTurnUserId', v_session.current_turn_user_id,
      'current_turn_user_id', v_session.current_turn_user_id,
      'turnUserId', v_session.current_turn_user_id,
      'turnDurationSeconds', COALESCE(v_session.turn_duration_seconds, 30),
      'turnDeadlineAt', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turn_deadline_at', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'turnDeadline', COALESCE(v_session.turn_expires_at, v_session.turn_deadline_at),
      'gameState', v_session.current_state,
      'game_state', v_session.current_state,
      'players', v_players
    );
  END IF;

  -- 4. Resolver tipo de juego, turno inicial y deadline
  v_game_type := lower(v_table.game_type::text);
  v_is_simultaneous := v_game_type IN ('rock_paper_scissors', 'rps', 'piedra_papel_tijera', 'bingo', 'bingo_75', 'bingo_90', 'polla', 'polla_venezolana');

  IF v_is_simultaneous THEN
    -- En juegos simultáneos o Commit-Reveal, NO existe turno individual secuencial.
    v_effective_turn_user_id := NULL;
  ELSE
    v_effective_turn_user_id := COALESCE(
      p_initial_turn_user_id,
      (p_initial_state->>'turnUserId')::uuid,
      (p_initial_state->>'currentTurnUserId')::uuid
    );

    IF v_effective_turn_user_id IS NULL AND v_players IS NOT NULL AND jsonb_array_length(v_players) > 0 THEN
      v_effective_turn_user_id := (v_players->0->>'user_id')::uuid;
    END IF;
  END IF;

  v_deadline := CASE
    WHEN v_effective_duration > 0
    THEN NOW() + (v_effective_duration || ' seconds')::interval
    ELSE NULL
  END;

  -- 5. Determinar estado inicial y estado de sesión
  IF v_game_type IN ('bingo', 'bingo_75', 'bingo_90') THEN
    v_session_status := 'WAITING';
    v_initial_state := jsonb_build_object(
      'status', 'SALES',
      'variant', COALESCE((to_jsonb(v_table)->>'game_variant'), '90'),
      'mode', COALESCE(((to_jsonb(v_table)->'config')->>'mode')::int, 90),
      'hostUserId', v_host_id,
      'seed', floor(random() * 1000000000)::int,
      'cards', '{}'::jsonb,
      'cardsPurchased', '{}'::jsonb,
      'drawnBalls', '[]'::jsonb,
      'currentBall', NULL,
      'players', v_players,
      'startedAt', NOW()
    );
  ELSIF v_game_type IN ('polla', 'polla_venezolana') THEN
    v_session_status := 'WAITING';
    v_initial_state := jsonb_build_object(
      'status', 'OPEN_PICKS',
      'fixtures', '[]'::jsonb,
      'predictions', '{}'::jsonb,
      'players', v_players,
      'startedAt', NOW()
    );
  ELSE
    v_session_status := 'ACTIVE';
    IF p_initial_state IS NOT NULL THEN
      v_initial_state := p_initial_state;
      -- Garantizar campos de turno autoritativos
      v_initial_state := jsonb_set(v_initial_state, '{turnDurationSeconds}', to_jsonb(v_effective_duration));
      IF v_effective_turn_user_id IS NOT NULL THEN
        v_initial_state := jsonb_set(v_initial_state, '{turnUserId}', to_jsonb(v_effective_turn_user_id::text));
        v_initial_state := jsonb_set(v_initial_state, '{currentTurnUserId}', to_jsonb(v_effective_turn_user_id::text));
      ELSE
        -- Juegos simultáneos (RPS): asegurar valores canónicos nulos sin inventar turnos
        v_initial_state := jsonb_set(v_initial_state, '{turnUserId}', 'null'::jsonb);
        v_initial_state := jsonb_set(v_initial_state, '{currentTurnUserId}', 'null'::jsonb);
      END IF;
    ELSE
      v_initial_state := jsonb_build_object(
        'status', 'PLAYING',
        'currentTurnUserId', v_effective_turn_user_id,
        'turnUserId', v_effective_turn_user_id,
        'turnDurationSeconds', v_effective_duration,
        'turnDeadline', v_deadline,
        'round', 1,
        'players', v_players,
        'startedAt', NOW()
      );
    END IF;
  END IF;

  -- Calcular session_number secuencial
  SELECT COALESCE(MAX(session_number), 0) + 1 INTO v_session_number
  FROM public.game_sessions
  WHERE table_id = p_table_id;

  -- 6. Insertar la nueva sesión utilizando columnas canónicas verificadas
  INSERT INTO public.game_sessions (
    table_id,
    game_type,
    session_number,
    status,
    current_state,
    current_turn_user_id,
    turn_duration_seconds,
    turn_deadline_at,
    turn_expires_at,
    started_at,
    created_at,
    updated_at
  ) VALUES (
    p_table_id,
    v_table.game_type,
    v_session_number,
    v_session_status::session_status_enum,
    v_initial_state,
    v_effective_turn_user_id,
    v_effective_duration,
    v_deadline,
    v_deadline,
    NOW(),
    NOW(),
    NOW()
  ) RETURNING * INTO v_session;

  -- 7. Actualizar mesa a ACTIVE
  UPDATE public.game_tables
  SET status = 'ACTIVE'::table_status_enum,
      updated_at = NOW()
  WHERE id = p_table_id;

  -- 8. Actualizar participantes a PLAYING usando player_table_status_enum
  UPDATE public.game_table_players
  SET status = 'PLAYING'::player_table_status_enum,
      joined_at = COALESCE(joined_at, NOW())
  WHERE table_id = p_table_id
    AND status::text IN ('JOINED', 'READY');

  RETURN jsonb_build_object(
    'success', true,
    'alreadyActive', false,
    'already_active', false,
    'source', 'created_session',
    'sessionId', v_session.id,
    'session_id', v_session.id,
    'tableId', p_table_id,
    'table_id', p_table_id,
    'status', v_session.status::text,
    'currentTurnUserId', v_session.current_turn_user_id,
    'current_turn_user_id', v_session.current_turn_user_id,
    'turnUserId', v_session.current_turn_user_id,
    'turnDurationSeconds', v_session.turn_duration_seconds,
    'turnDeadlineAt', v_session.turn_expires_at,
    'turn_deadline_at', v_session.turn_expires_at,
    'turnDeadline', v_session.turn_expires_at,
    'gameState', v_session.current_state,
    'game_state', v_session.current_state,
    'players', v_players
  );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.start_game_session_secure(uuid, jsonb, integer, uuid) TO authenticated, service_role, anon;


-- 2. ACTUALIZACIÓN DE EXPIRE_GAME_TURN_SECURE CON SOPORTE PARA PIEDRA, PAPEL O TIJERA (RPS)
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_game_type_str TEXT;
  v_turn_user_id UUID;
  v_opponent_id UUID := NULL;
  v_player_order JSONB;
  v_player_count INT := 0;
  v_scores JSONB;
  v_opp_score INT := 0;
  v_target_wins INT := 3;
  v_curr_round INT := 1;
  v_duration INT := 30;
  v_new_deadline TIMESTAMPTZ;
  v_lives JSONB;
  v_curr_lives INT;
  v_settle_result JSONB;
  v_i INT;
  v_p RECORD;
  -- Variables específicas para RPS
  v_p1_id UUID;
  v_p2_id UUID;
  v_secret_choices JSONB;
  v_p1_committed BOOLEAN := false;
  v_p2_committed BOOLEAN := false;
  v_winner_id UUID := NULL;
  v_loser_id UUID := NULL;
  v_idempotency_key TEXT;
  v_new_state JSONB;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  -- 1. Bloqueo Pesimista Estricto (FOR UPDATE)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 2. Idempotencia: Sesión ya cerrada, finalizada o liquidada
  IF UPPER(v_session.status::TEXT) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_FINALIZED',
      'status', v_session.status::text
    );
  END IF;

  -- 3. Idempotencia Temporal: Si el turno aún no ha expirado (margen de gracia de 1s)
  IF v_session.turn_deadline_at IS NOT NULL AND v_session.turn_deadline_at > (NOW() + INTERVAL '1 second') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_NOT_EXPIRED',
      'currentTurnUserId', v_session.current_turn_user_id,
      'turnDeadlineAt', v_session.turn_deadline_at
    );
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_game_type_str := UPPER(COALESCE(v_session.game_type::TEXT, ''));

  -- =========================================================================
  -- CASO ESPECIAL: PIEDRA, PAPEL O TIJERA (Juego simultáneo Commit-Reveal)
  -- =========================================================================
  IF v_game_type_str IN ('ROCK_PAPER_SCISSORS', 'RPS', 'PIEDRA_PAPEL_TIJERA') THEN
    -- Solo aplica timeout si está en fase de compromiso
    IF COALESCE(v_state->>'status', '') NOT IN ('ROUND_COMMIT', 'selecting') AND
       COALESCE(v_state->>'phase', '') NOT IN ('ROUND_COMMIT', 'selecting') THEN
      RETURN jsonb_build_object('success', true, 'action', 'NOT_IN_COMMIT_PHASE', 'status', v_state->>'status');
    END IF;

    v_curr_round := COALESCE((v_state->>'roundNumber')::int, (v_state->>'round')::int, 1);
    v_idempotency_key := 'rps_timeout_' || p_session_id::text || '_rnd_' || v_curr_round::text;

    v_p1_id := NULLIF(TRIM(v_state->>'player1Id'), '')::uuid;
    v_p2_id := NULLIF(TRIM(v_state->>'player2Id'), '')::uuid;

    IF v_p1_id IS NULL THEN
      SELECT user_id INTO v_p1_id
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND status NOT IN ('LEFT')
      ORDER BY seat_number ASC, joined_at ASC
      LIMIT 1;
    END IF;

    IF v_p2_id IS NULL THEN
      SELECT user_id INTO v_p2_id
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND user_id != v_p1_id
        AND status NOT IN ('LEFT')
      ORDER BY seat_number ASC, joined_at ASC
      LIMIT 1;
    END IF;

    -- Obtener selecciones secretas autoritativas
    SELECT secret_state->'rps_choices' INTO v_secret_choices
    FROM public.game_session_secrets
    WHERE session_id = p_session_id;

    v_p1_committed := (v_secret_choices ? v_p1_id::text) OR
                      COALESCE((v_state->'playerChoices'->(v_p1_id::text)->>'committed')::boolean, false);
    v_p2_committed := (v_secret_choices ? v_p2_id::text) OR
                      COALESCE((v_state->'playerChoices'->(v_p2_id::text)->>'committed')::boolean, false);

    IF v_p1_committed AND NOT v_p2_committed THEN
      v_winner_id := v_p1_id;
      v_loser_id := v_p2_id;
    ELSIF v_p2_committed AND NOT v_p1_committed THEN
      v_winner_id := v_p2_id;
      v_loser_id := v_p1_id;
    ELSE
      v_winner_id := NULL;
      v_loser_id := NULL;
    END IF;

    IF v_winner_id IS NOT NULL THEN
      v_new_state := v_state || jsonb_build_object(
        'winnerUserId', v_winner_id,
        'abandonedBy', v_loser_id,
        'status', 'MATCH_ENDED',
        'phase', 'match_ended'
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_winner_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          current_turn_user_id = NULL,
          updated_at = NOW()
      WHERE id = p_session_id;

      PERFORM public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL::int,
        v_idempotency_key
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_TIMEOUT_SETTLED',
        'winnerUserId', v_winner_id,
        'abandonedBy', v_loser_id
      );
    ELSE
      -- Ninguno comprometió la jugada antes de que venciera el tiempo: reembolso íntegro
      v_new_state := v_state || jsonb_build_object(
        'cancelReason', 'ROUND_TIMEOUT_NO_CHOICES',
        'status', 'MATCH_CANCELLED'
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          status = 'CANCELLED'::session_status_enum,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          current_turn_user_id = NULL,
          updated_at = NOW()
      WHERE id = p_session_id;

      PERFORM public.refund_game_session(
        p_session_id,
        'Tiempo de ronda agotado sin jugadas de ningún participante',
        v_idempotency_key
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_TIMEOUT_REFUNDED'
      );
    END IF;
  END IF;

  -- =========================================================================
  -- JUEGOS SECUENCIALES TRADICIONALES
  -- =========================================================================
  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID,
    (v_state->>'currentTurnUserId')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_TURN');
  END IF;

  IF v_game_type_str = '' THEN
    v_game_type_str := 'GENERIC';
  END IF;

  -- Resolver lista ordenada de jugadores desde game_table_players
  SELECT jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)
  INTO v_player_order
  FROM public.game_table_players
  WHERE table_id = v_session.table_id
    AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED');

  v_player_count := COALESCE(jsonb_array_length(v_player_order), 0);

  IF v_player_count >= 2 THEN
    FOR v_i IN 0..(v_player_count - 1) LOOP
      IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
        v_opponent_id := (v_player_order->>((v_i + 1) % v_player_count))::UUID;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_opponent_id IS NULL THEN
    SELECT user_id INTO v_opponent_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id != v_turn_user_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  v_scores := COALESCE(v_state->'scores', jsonb_build_object(
    v_turn_user_id::TEXT, 0,
    COALESCE(v_opponent_id::TEXT, 'opp'), 0
  ));
  v_opp_score := COALESCE((v_scores->>v_opponent_id::TEXT)::INT, 0);
  v_target_wins := COALESCE((v_state->>'targetWins')::INT, 3);
  v_curr_round := COALESCE((v_state->>'round')::INT, 1);
  v_duration := COALESCE(v_session.turn_duration_seconds, 30);
  v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

  -- TIC TAC TOE / LA VIEJA
  IF v_game_type_str IN ('TIC_TAC_TOE', 'TICTACTOE', 'LA_VIEJA') THEN
    v_lives := COALESCE(v_state->'lives', jsonb_build_object(
      v_turn_user_id::TEXT, 3,
      COALESCE(v_opponent_id::TEXT, 'opp'), 3
    ));
    v_curr_lives := GREATEST(0, COALESCE((v_lives->>v_turn_user_id::TEXT)::INT, 3) - 1);
    v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::TEXT], to_jsonb(v_curr_lives));

    IF v_curr_lives <= 0 AND v_opponent_id IS NOT NULL THEN
      v_opp_score := v_target_wins;
      v_scores := jsonb_set(v_scores, ARRAY[v_opponent_id::TEXT], to_jsonb(v_opp_score));

      v_state := v_state || jsonb_build_object(
        'status', 'FINISHED',
        'phase', 'match_ended',
        'isGameOver', true,
        'winnerUserId', v_opponent_id,
        'scores', v_scores,
        'lives', v_lives,
        'abandonedBy', v_turn_user_id,
        'timeoutUserId', v_turn_user_id
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_opponent_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      SELECT public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_opponent_id],
        NULL::INT,
        'timeout_ttt_loss_' || p_session_id::TEXT || '_' || v_turn_user_id::TEXT
      ) INTO v_settle_result;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'MATCH_CONCLUDED_TIMEOUT',
        'winnerUserId', v_opponent_id,
        'timeoutUserId', v_turn_user_id,
        'settlement', v_settle_result
      );
    ELSE
      v_state := v_state || jsonb_build_object(
        'currentTurnUserId', v_opponent_id,
        'turnUserId', v_opponent_id,
        'turnDeadline', v_new_deadline,
        'lives', v_lives,
        'timeoutUserId', v_turn_user_id
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          current_turn_user_id = v_opponent_id,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      INSERT INTO public.game_actions (
        session_id,
        user_id,
        sequence_number,
        action_type,
        payload,
        is_valid,
        server_state_hash,
        idempotency_key
      ) VALUES (
        p_session_id,
        v_turn_user_id,
        COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
        'TURN_EXPIRED',
        jsonb_build_object(
          'expiredUserId', v_turn_user_id,
          'nextTurnUserId', v_opponent_id,
          'remainingLives', v_curr_lives,
          'turnDeadline', v_new_deadline
        ),
        true,
        md5(v_state::TEXT),
        'turn_expired_' || p_session_id::TEXT || '_' || v_turn_user_id::TEXT || '_' || EXTRACT(EPOCH FROM NOW())::TEXT
      );

      RETURN jsonb_build_object(
        'success', true,
        'action', 'TURN_ROTATED_PENALTY',
        'expiredUserId', v_turn_user_id,
        'nextTurnUserId', v_opponent_id,
        'remainingLives', v_curr_lives,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- DEMÁS JUEGOS SECUENCIALES: Rotación estándar
  v_state := v_state || jsonb_build_object(
    'currentTurnUserId', v_opponent_id,
    'turnUserId', v_opponent_id,
    'turnDeadline', v_new_deadline
  );

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_opponent_id,
      turn_deadline_at = v_new_deadline,
      turn_expires_at = v_new_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TURN_ROTATED',
    'expiredUserId', v_turn_user_id,
    'nextTurnUserId', v_opponent_id,
    'turnDeadlineAt', v_new_deadline
  );
END;
$function$;

GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(uuid) TO authenticated, service_role, anon;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 163: 159_sequential_turn_coherence_and_atrapaito_parchis_separation.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ==============================================================================
-- RASPANDO LA OLLA 🇻🇪 / PulsoPLAY — MIGRACIÓN 159
-- DESACOPLAMIENTO DEFINITIVO ATRAPAÍTO VS PARCHÍS & COHERENCIA DE TURNOS SECUENCIALES
-- ==============================================================================
-- 1. Agrega el tipo de juego canónico 'PARCHIS' a game_type_enum si no existe.
-- 2. Actualiza fn_normalize_game_type_enum conservando la firma (p_game_str TEXT)
--    y normalizando PARCHIS y ATRAPAITO por separado.
-- 3. Actualiza expire_game_turn_secure(p_session_id uuid) con coherencia estricta:
--    - Exclusión explícita de juegos no secuenciales (Bingo, Polla).
--    - En Piedra Papel Tijera (RPS): lógica simultánea de commit / timeout / liquidación.
--    - En Atrapaíto Criollo: alterna color ('BLUE' <-> 'RED') y rota al oponente.
--    - En Parchís: rota respetando playerOrder / asientos multijugador (2-4 jugadores).
--    - En Dominó, Truco, Ajedrez, Damas y Una Olla: rota al siguiente jugador.
--    - Clave de idempotencia determinística y segura (< 100 chars para varchar(100)).
-- ==============================================================================

-- 1. SOPORTE DE ENUM PARA PARCHÍS
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum
    WHERE enumtypid = 'public.game_type_enum'::regtype
      AND enumlabel = 'PARCHIS'
  ) THEN
    ALTER TYPE public.game_type_enum ADD VALUE 'PARCHIS';
  END IF;
END $$;

-- 2. NORMALIZACIÓN DE TIPOS DE JUEGO (Conservando nombre canónico de parámetro p_game_str TEXT)
CREATE OR REPLACE FUNCTION public.fn_normalize_game_type_enum(p_game_str TEXT)
RETURNS public.game_type_enum
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_normalized TEXT;
BEGIN
  IF p_game_str IS NULL THEN
    RAISE EXCEPTION 'INVALID_GAME_TYPE: El tipo de juego no puede ser nulo';
  END IF;

  v_normalized := UPPER(TRIM(p_game_str));
  v_normalized := REPLACE(v_normalized, '-', '_');

  CASE v_normalized
    WHEN 'DOMINO', 'DOMINO_VENEZOLANO', 'DOMINÓ', 'DOMINOES' THEN
      RETURN 'DOMINO_VENEZOLANO'::public.game_type_enum;

    WHEN 'TRUCO', 'TRUCO_VENEZOLANO' THEN
      RETURN 'TRUCO_VENEZOLANO'::public.game_type_enum;

    WHEN 'TIC_TAC_TOE', 'TRES_EN_RAYA', 'LA_VIEJA', 'VIEJA', 'TICTACTOE', '3_EN_RAYA' THEN
      RETURN 'TRES_EN_RAYA'::public.game_type_enum;

    WHEN 'ROCK_PAPER_SCISSORS', 'PIEDRA_PAPEL_TIJERA', 'PIEDRA_PAPEL_O_TIJERA', 'PPT', 'RPS' THEN
      RETURN 'PIEDRA_PAPEL_TIJERA'::public.game_type_enum;

    WHEN 'CHECKERS', 'DAMAS', 'DAMAS_VENEZOLANAS', 'DAMAS_ESPANOLAS', 'DAMAS_INTERNACIONALES' THEN
      RETURN 'DAMAS'::public.game_type_enum;

    WHEN 'BINGO', 'BINGO_ONLINE', 'BINGO_75', 'BINGO_90', 'BINGO_LATINO' THEN
      RETURN 'BINGO'::public.game_type_enum;

    WHEN 'POLLA', 'POLLA_VENEZOLANA', 'QUINIELA', 'POLLA_FUTBOL', 'POLLA_DEPORTIVA' THEN
      RETURN 'POLLA_VENEZOLANA'::public.game_type_enum;

    WHEN 'ATRAPAITO', 'ATRAPAITO_CRIOLLO', 'ATRAPA_AL_LADRON', 'ATRAPA_AL_MILLON', 'TRIVIA_ATRAPAITO', 'ATRAPA' THEN
      RETURN 'ATRAPAITO'::public.game_type_enum;

    WHEN 'PARCHIS', 'PARCHIS_VENEZOLANO', 'PARCHÍS', 'LUDO', 'LUDO_VENEZOLANO' THEN
      RETURN 'PARCHIS'::public.game_type_enum;

    WHEN 'CHESS', 'AJEDREZ' THEN
      RETURN 'CHESS'::public.game_type_enum;

    WHEN 'UNA_OLLA', 'UNA_OLLA_CARD_GAME', 'OLLA', 'RASPANDO_LA_OLLA', 'RASPANDO' THEN
      RETURN 'UNA_OLLA'::public.game_type_enum;

    ELSE
      BEGIN
        RETURN v_normalized::public.game_type_enum;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'INVALID_GAME_TYPE: Tipo de juego desconocido o no soportado: %', p_game_str;
      END;
  END CASE;
END;
$$;

-- 3. EXPIRE_GAME_TURN_SECURE CON COHERENCIA MULTIJUGADOR Y DESACOPLAMIENTO DEFINITIVO
CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_game_type_str TEXT;
  v_turn_user_id UUID;
  v_next_turn_user_id UUID := NULL;
  v_player_order JSONB;
  v_player_count INT := 0;
  v_scores JSONB;
  v_opp_score INT := 0;
  v_target_wins INT := 3;
  v_curr_round INT := 1;
  v_duration INT := 30;
  v_new_deadline TIMESTAMPTZ;
  v_lives JSONB;
  v_curr_lives INT;
  v_settle_result JSONB;
  v_i INT;
  -- Variables para RPS
  v_p1_id UUID;
  v_p2_id UUID;
  v_secret_choices JSONB;
  v_p1_committed BOOLEAN := false;
  v_p2_committed BOOLEAN := false;
  v_winner_id UUID := NULL;
  v_loser_id UUID := NULL;
  v_idempotency_key TEXT;
  v_new_state JSONB;
  -- Variables para Atrapaíto Criollo
  v_curr_color TEXT;
  v_next_color TEXT;
  -- Variables para Parchís
  v_parchis_order JSONB;
  v_parchis_len INT := 0;
  v_parchis_idx INT := -1;
  v_parchis_players JSONB;
  v_parchis_next_color TEXT;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  -- 1. Bloqueo Pesimista Estricto (FOR UPDATE)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 2. Idempotencia: Sesión ya cerrada, finalizada o liquidada
  IF UPPER(v_session.status::TEXT) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_FINALIZED',
      'status', v_session.status::text
    );
  END IF;

  -- 3. Idempotencia Temporal: Si el turno aún no ha expirado (margen de gracia de 1s)
  IF v_session.turn_deadline_at IS NOT NULL AND v_session.turn_deadline_at > (NOW() + INTERVAL '1 second') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_NOT_EXPIRED',
      'currentTurnUserId', v_session.current_turn_user_id,
      'turnDeadlineAt', v_session.turn_deadline_at
    );
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_game_type_str := UPPER(COALESCE(v_session.game_type::TEXT, ''));

  -- =========================================================================
  -- CASO 1: JUEGOS NO SECUENCIALES (BINGO, POLLA VENEZOLANA)
  -- =========================================================================
  IF v_game_type_str IN ('BINGO', 'POLLA_VENEZOLANA', 'POLLA') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'GAME_TYPE_NOT_HANDLED_BY_SEQUENTIAL_TIMEOUT',
      'gameType', v_game_type_str,
      'message', 'Bingo y Polla no operan bajo rotación secuencial individual de turnos.'
    );
  END IF;

  -- =========================================================================
  -- CASO 2: PIEDRA, PAPEL O TIJERA (Juego simultáneo Commit-Reveal)
  -- =========================================================================
  IF v_game_type_str IN ('ROCK_PAPER_SCISSORS', 'RPS', 'PIEDRA_PAPEL_TIJERA') THEN
    IF COALESCE(v_state->>'status', '') NOT IN ('ROUND_COMMIT', 'selecting') AND
       COALESCE(v_state->>'phase', '') NOT IN ('ROUND_COMMIT', 'selecting') THEN
      RETURN jsonb_build_object('success', true, 'action', 'NOT_IN_COMMIT_PHASE', 'status', v_state->>'status');
    END IF;

    v_curr_round := COALESCE((v_state->>'roundNumber')::int, (v_state->>'round')::int, 1);
    v_idempotency_key := 'rps_timeout_' || substr(p_session_id::text, 1, 8) || '_rnd_' || v_curr_round::text;

    v_p1_id := NULLIF(TRIM(v_state->>'player1Id'), '')::uuid;
    v_p2_id := NULLIF(TRIM(v_state->>'player2Id'), '')::uuid;

    IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
      SELECT
        (jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)->>0)::uuid,
        (jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)->>1)::uuid
      INTO v_p1_id, v_p2_id
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED');
    END IF;

    v_secret_choices := COALESCE(v_session.secret_choices, '{}'::jsonb);
    v_p1_committed := (v_secret_choices ? v_p1_id::text) AND (v_secret_choices->v_p1_id::text IS NOT NULL);
    v_p2_committed := (v_secret_choices ? v_p2_id::text) AND (v_secret_choices->v_p2_id::text IS NOT NULL);

    -- Si ambos se demoraron sin jugar: reseteo de la ronda
    IF (NOT v_p1_committed) AND (NOT v_p2_committed) THEN
      v_duration := COALESCE(v_session.turn_duration_seconds, 15);
      v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

      v_new_state := v_state || jsonb_build_object(
        'roundNumber', v_curr_round + 1,
        'phase', 'ROUND_COMMIT',
        'status', 'ROUND_COMMIT',
        'lastRoundResult', 'DRAW_DOUBLE_TIMEOUT',
        'timeoutUserId', NULL,
        'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          secret_choices = '{}'::jsonb,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_DOUBLE_TIMEOUT_RESET',
        'roundNumber', v_curr_round + 1,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;

    -- Uno sí jugó y el otro expiró
    IF v_p1_committed AND (NOT v_p2_committed) THEN
      v_winner_id := v_p1_id;
      v_loser_id := v_p2_id;
    ELSIF v_p2_committed AND (NOT v_p1_committed) THEN
      v_winner_id := v_p2_id;
      v_loser_id := v_p1_id;
    END IF;

    v_target_wins := COALESCE((v_state->>'targetWins')::int, 3);
    v_scores := COALESCE(v_state->'scores', jsonb_build_object(v_p1_id::text, 0, v_p2_id::text, 0));
    v_opp_score := COALESCE((v_scores->>v_winner_id::text)::int, 0) + 1;
    v_scores := jsonb_set(v_scores, ARRAY[v_winner_id::text], to_jsonb(v_opp_score));

    IF v_opp_score >= v_target_wins THEN
      v_new_state := v_state || jsonb_build_object(
        'status', 'FINISHED',
        'phase', 'match_ended',
        'isGameOver', true,
        'winnerUserId', v_winner_id,
        'scores', v_scores,
        'timeoutUserId', v_loser_id,
        'abandonedBy', v_loser_id
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_winner_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      SELECT public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL::INT,
        v_idempotency_key
      ) INTO v_settle_result;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_MATCH_CONCLUDED_TIMEOUT',
        'winnerUserId', v_winner_id,
        'timeoutUserId', v_loser_id,
        'settlement', v_settle_result
      );
    ELSE
      v_duration := COALESCE(v_session.turn_duration_seconds, 15);
      v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

      v_new_state := v_state || jsonb_build_object(
        'roundNumber', v_curr_round + 1,
        'phase', 'ROUND_COMMIT',
        'status', 'ROUND_COMMIT',
        'scores', v_scores,
        'lastRoundResult', 'TIMEOUT_AWARD',
        'lastRoundWinner', v_winner_id,
        'timeoutUserId', v_loser_id,
        'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          secret_choices = '{}'::jsonb,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_ROUND_AWARDED_TIMEOUT',
        'winnerUserId', v_winner_id,
        'timeoutUserId', v_loser_id,
        'newRound', v_curr_round + 1,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- =========================================================================
  -- CASO 3: VALIDACIÓN DE JUEGOS SECUENCIALES AUTORIZADOS
  -- =========================================================================
  IF v_game_type_str NOT IN (
    'TRES_EN_RAYA', 'TIC_TAC_TOE', 'TICTACTOE', 'LA_VIEJA',
    'ATRAPAITO', 'ATRAPAITO_CRIOLLO',
    'PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO',
    'DOMINO_VENEZOLANO', 'DOMINO',
    'TRUCO_VENEZOLANO', 'TRUCO',
    'CHESS', 'AJEDREZ',
    'DAMAS',
    'UNA_OLLA'
  ) THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'GAME_TYPE_NOT_HANDLED_BY_SEQUENTIAL_TIMEOUT',
      'gameType', v_game_type_str
    );
  END IF;

  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID,
    (v_state->>'currentTurnUserId')::UUID,
    (v_state->>'currentTurn')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_TURN');
  END IF;

  -- =========================================================================
  -- RESOLUCIÓN ORDENADA DEL SIGUIENTE TURNO (v_next_turn_user_id)
  -- =========================================================================
  -- Si el juego es Parchís y el estado incluye playerOrder explícito
  v_parchis_order := v_state->'playerOrder';
  IF v_game_type_str IN ('PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO') AND
     jsonb_typeof(v_parchis_order) = 'array' AND jsonb_array_length(v_parchis_order) >= 2 THEN
    v_parchis_len := jsonb_array_length(v_parchis_order);
    FOR v_i IN 0..(v_parchis_len - 1) LOOP
      IF (v_parchis_order->>v_i)::UUID = v_turn_user_id THEN
        v_next_turn_user_id := (v_parchis_order->>((v_i + 1) % v_parchis_len))::UUID;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  -- Fallback o estándar para demás juegos multijugador: consultar game_table_players
  IF v_next_turn_user_id IS NULL THEN
    SELECT jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)
    INTO v_player_order
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED');

    v_player_count := COALESCE(jsonb_array_length(v_player_order), 0);

    IF v_player_count >= 2 THEN
      FOR v_i IN 0..(v_player_count - 1) LOOP
        IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
          v_next_turn_user_id := (v_player_order->>((v_i + 1) % v_player_count))::UUID;
          EXIT;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- Fallback de seguridad: cualquier otro jugador activo en la mesa
  IF v_next_turn_user_id IS NULL THEN
    SELECT user_id INTO v_next_turn_user_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id != v_turn_user_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  v_scores := COALESCE(v_state->'scores', jsonb_build_object(
    v_turn_user_id::TEXT, 0,
    COALESCE(v_next_turn_user_id::TEXT, 'opp'), 0
  ));
  v_opp_score := COALESCE((v_scores->>v_next_turn_user_id::TEXT)::INT, 0);
  v_target_wins := COALESCE((v_state->>'targetWins')::INT, 3);
  v_curr_round := COALESCE((v_state->>'round')::INT, 1);
  v_duration := COALESCE(v_session.turn_duration_seconds, 30);
  v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

  -- Clave de idempotencia determinística (< 100 caracteres para el check uq_game_actions_idempotency)
  v_idempotency_key := 'to_' || substr(p_session_id::TEXT, 1, 8) || '_' || substr(v_turn_user_id::TEXT, 1, 8) || '_' || md5(p_session_id::TEXT || '_' || v_turn_user_id::TEXT || '_' || COALESCE(v_session.turn_deadline_at::TEXT, '0'));

  -- -------------------------------------------------------------------------
  -- SUB-RAMA A: TIC TAC TOE / LA VIEJA (Conteo de vidas y penalización)
  -- -------------------------------------------------------------------------
  IF v_game_type_str IN ('TIC_TAC_TOE', 'TICTACTOE', 'LA_VIEJA', 'TRES_EN_RAYA') THEN
    v_lives := COALESCE(v_state->'lives', jsonb_build_object(
      v_turn_user_id::TEXT, 3,
      COALESCE(v_next_turn_user_id::TEXT, 'opp'), 3
    ));
    v_curr_lives := GREATEST(0, COALESCE((v_lives->>v_turn_user_id::TEXT)::INT, 3) - 1);
    v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::TEXT], to_jsonb(v_curr_lives));

    IF v_curr_lives <= 0 AND v_next_turn_user_id IS NOT NULL THEN
      v_opp_score := v_target_wins;
      v_scores := jsonb_set(v_scores, ARRAY[v_next_turn_user_id::TEXT], to_jsonb(v_opp_score));

      v_state := v_state || jsonb_build_object(
        'status', 'FINISHED',
        'phase', 'match_ended',
        'isGameOver', true,
        'winnerUserId', v_next_turn_user_id,
        'scores', v_scores,
        'lives', v_lives,
        'abandonedBy', v_turn_user_id,
        'timeoutUserId', v_turn_user_id
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_next_turn_user_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      SELECT public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_next_turn_user_id],
        NULL::INT,
        'ttt_to_' || substr(p_session_id::TEXT, 1, 8) || '_' || substr(v_turn_user_id::TEXT, 1, 8)
      ) INTO v_settle_result;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'MATCH_CONCLUDED_TIMEOUT',
        'winnerUserId', v_next_turn_user_id,
        'timeoutUserId', v_turn_user_id,
        'settlement', v_settle_result
      );
    ELSE
      v_state := v_state || jsonb_build_object(
        'currentTurnUserId', v_next_turn_user_id,
        'turnUserId', v_next_turn_user_id,
        'turnDeadline', v_new_deadline,
        'lives', v_lives,
        'timeoutUserId', v_turn_user_id
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          current_turn_user_id = v_next_turn_user_id,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      INSERT INTO public.game_actions (
        session_id,
        user_id,
        sequence_number,
        action_type,
        payload,
        is_valid,
        server_state_hash,
        idempotency_key
      ) VALUES (
        p_session_id,
        v_turn_user_id,
        COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
        'TURN_EXPIRED',
        jsonb_build_object(
          'expiredUserId', v_turn_user_id,
          'nextTurnUserId', v_next_turn_user_id,
          'remainingLives', v_curr_lives,
          'turnDeadline', v_new_deadline
        ),
        true,
        md5(v_state::TEXT),
        v_idempotency_key
      )
      ON CONFLICT (idempotency_key) DO NOTHING;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'TURN_ROTATED_PENALTY',
        'expiredUserId', v_turn_user_id,
        'nextTurnUserId', v_next_turn_user_id,
        'remainingLives', v_curr_lives,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- -------------------------------------------------------------------------
  -- SUB-RAMA B: ATRAPAÍTO CRIOLLO (Canicas, Paredes de Bloqueo, 2 Jugadores BLUE/RED)
  -- -------------------------------------------------------------------------
  IF v_game_type_str IN ('ATRAPAITO', 'ATRAPAITO_CRIOLLO') THEN
    v_curr_color := UPPER(COALESCE(v_state->>'turn', 'BLUE'));
    IF v_curr_color = 'BLUE' THEN
      v_next_color := 'RED';
    ELSE
      v_next_color := 'BLUE';
    END IF;

    v_state := v_state || jsonb_build_object(
      'currentTurnUserId', v_next_turn_user_id,
      'turnUserId', v_next_turn_user_id,
      'currentTurn', v_next_turn_user_id,
      'turn', v_next_color,
      'action', 'MOVE',
      'pendingWall', NULL,
      'turnDeadline', v_new_deadline,
      'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
    );

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_deadline_at = v_new_deadline,
        turn_expires_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    INSERT INTO public.game_actions (
      session_id,
      user_id,
      sequence_number,
      action_type,
      payload,
      is_valid,
      server_state_hash,
      idempotency_key
    ) VALUES (
      p_session_id,
      v_turn_user_id,
      COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
      'TURN_EXPIRED',
      jsonb_build_object(
        'expiredUserId', v_turn_user_id,
        'nextTurnUserId', v_next_turn_user_id,
        'nextColor', v_next_color,
        'turnDeadline', v_new_deadline
      ),
      true,
      md5(v_state::TEXT),
      v_idempotency_key
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_ROTATED_ATRAPAITO',
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'nextColor', v_next_color,
      'turnDeadlineAt', v_new_deadline
    );
  END IF;

  -- -------------------------------------------------------------------------
  -- SUB-RAMA C: PARCHÍS / LUDO (Tablero Circular, Dados, 2 a 4 Jugadores)
  -- -------------------------------------------------------------------------
  IF v_game_type_str IN ('PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO') THEN
    v_parchis_players := v_state->'players';
    IF v_parchis_players IS NOT NULL AND (v_parchis_players->v_next_turn_user_id::TEXT) IS NOT NULL THEN
      v_parchis_next_color := v_parchis_players->v_next_turn_user_id::TEXT->'colors'->>0;
    END IF;

    v_state := v_state || jsonb_build_object(
      'currentTurnUserId', v_next_turn_user_id,
      'turnUserId', v_next_turn_user_id,
      'turnPhase', 'ROLL_DICE',
      'diceValue', NULL,
      'consecutiveSixes', 0,
      'turnDeadline', v_new_deadline,
      'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
    );

    IF v_parchis_next_color IS NOT NULL THEN
      v_state := jsonb_set(v_state, '{activeColor}', to_jsonb(v_parchis_next_color));
    END IF;

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_deadline_at = v_new_deadline,
        turn_expires_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    INSERT INTO public.game_actions (
      session_id,
      user_id,
      sequence_number,
      action_type,
      payload,
      is_valid,
      server_state_hash,
      idempotency_key
    ) VALUES (
      p_session_id,
      v_turn_user_id,
      COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
      'TURN_EXPIRED',
      jsonb_build_object(
        'expiredUserId', v_turn_user_id,
        'nextTurnUserId', v_next_turn_user_id,
        'activeColor', v_parchis_next_color,
        'turnDeadline', v_new_deadline
      ),
      true,
      md5(v_state::TEXT),
      v_idempotency_key
    )
    ON CONFLICT (idempotency_key) DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_ROTATED_PARCHIS',
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'activeColor', v_parchis_next_color,
      'turnDeadlineAt', v_new_deadline
    );
  END IF;

  -- -------------------------------------------------------------------------
  -- SUB-RAMA D: DEMÁS JUEGOS SECUENCIALES (DOMINÓ, TRUCO, AJEDREZ, DAMAS, UNA OLLA)
  -- -------------------------------------------------------------------------
  v_state := v_state || jsonb_build_object(
    'currentTurnUserId', v_next_turn_user_id,
    'turnUserId', v_next_turn_user_id,
    'turnDeadline', v_new_deadline,
    'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
  );

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_turn_user_id,
      turn_deadline_at = v_new_deadline,
      turn_expires_at = v_new_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  INSERT INTO public.game_actions (
    session_id,
    user_id,
    sequence_number,
    action_type,
    payload,
    is_valid,
    server_state_hash,
    idempotency_key
  ) VALUES (
    p_session_id,
    v_turn_user_id,
    COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
    'TURN_EXPIRED',
    jsonb_build_object(
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'turnDeadline', v_new_deadline
    ),
    true,
    md5(v_state::TEXT),
    v_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TURN_ROTATED',
    'expiredUserId', v_turn_user_id,
    'nextTurnUserId', v_next_turn_user_id,
    'turnDeadlineAt', v_new_deadline
  );
END;
$function$;

-- 4. PERMISOS Y RECARGA DE ESQUEMA
GRANT EXECUTE ON FUNCTION public.fn_normalize_game_type_enum(TEXT) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(uuid) TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 164: 160_fix_rps_timeout_and_round_coherence.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- MIGRACIÓN 160: CORRECCIÓN DEFINITIVA DE TIMEOUT, ESTADO Y COHERENCIA EN RPS
-- =============================================================================
-- 1. Corrige 'expire_game_turn_secure' para Piedra, Papel o Tijera (RPS):
--    - Elimina referencia a columna inexistente 'v_session.secret_choices'.
--    - Consulta 'secret_state->rps_choices' desde 'public.game_session_secrets'.
--    - Aplica sistema autoritativo de 3 vidas (Mejor de 3 Vidas).
--    - Limpia 'game_session_secrets' y resetea 'playerChoices', 'player1Choice',
--      'player2Choice', 'roundWinner' y 'roundWinnerUserId' al avanzar o reiniciar.
--    - Resuelve doble timeout como empate sin restar vidas y con nuevo plazo de 15s.
--    - Penaliza con -1 vida a quien expire y otorga la ronda a quien sí jugó.
--    - Si las vidas llegan a 0, liquida la partida atómicamente con 'universal_settle_game_session'.
-- 2. Asegura idempotencia en 'next_rps_round_secure' registrando 'ROUND_START' en game_actions.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.expire_game_turn_secure(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_session RECORD;
  v_state JSONB;
  v_game_type_str TEXT;
  v_turn_user_id UUID;
  v_next_turn_user_id UUID := NULL;
  v_player_order JSONB;
  v_player_count INT := 0;
  v_scores JSONB;
  v_opp_score INT := 0;
  v_target_wins INT := 3;
  v_curr_round INT := 1;
  v_duration INT := 30;
  v_new_deadline TIMESTAMPTZ;
  v_lives JSONB;
  v_curr_lives INT;
  v_settle_result JSONB;
  v_i INT;
  -- Variables para RPS
  v_p1_id UUID;
  v_p2_id UUID;
  v_p1_lives INT := 3;
  v_p2_lives INT := 3;
  v_is_game_over BOOLEAN := false;
  v_secret_choices JSONB;
  v_p1_committed BOOLEAN := false;
  v_p2_committed BOOLEAN := false;
  v_winner_id UUID := NULL;
  v_loser_id UUID := NULL;
  v_idempotency_key TEXT;
  v_new_state JSONB;
  -- Variables para Atrapaíto Criollo
  v_curr_color TEXT;
  v_next_color TEXT;
  -- Variables para Parchís
  v_parchis_order JSONB;
  v_parchis_len INT := 0;
  v_parchis_idx INT := -1;
  v_parchis_players JSONB;
  v_parchis_next_color TEXT;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  -- 1. Bloqueo Pesimista Estricto (FOR UPDATE)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  -- 2. Idempotencia: Sesión ya cerrada, finalizada o liquidada
  IF UPPER(v_session.status::TEXT) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_FINALIZED',
      'status', v_session.status::text
    );
  END IF;

  -- 3. Idempotencia Temporal: Si el turno aún no ha expirado (margen de gracia de 1s)
  IF v_session.turn_deadline_at IS NOT NULL AND v_session.turn_deadline_at > (NOW() + INTERVAL '1 second') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'TURN_NOT_EXPIRED',
      'currentTurnUserId', v_session.current_turn_user_id,
      'turnDeadlineAt', v_session.turn_deadline_at
    );
  END IF;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_game_type_str := UPPER(COALESCE(v_session.game_type::TEXT, ''));

  -- =========================================================================
  -- CASO 1: JUEGOS NO SECUENCIALES (BINGO, POLLA VENEZOLANA)
  -- =========================================================================
  IF v_game_type_str IN ('BINGO', 'POLLA_VENEZOLANA', 'POLLA') THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'GAME_TYPE_NOT_HANDLED_BY_SEQUENTIAL_TIMEOUT',
      'gameType', v_game_type_str,
      'message', 'Bingo y Polla no operan bajo rotación secuencial individual de turnos.'
    );
  END IF;

  -- =========================================================================
  -- CASO 2: PIEDRA, PAPEL O TIJERA (Juego simultáneo Commit-Reveal)
  -- =========================================================================
  IF v_game_type_str IN ('ROCK_PAPER_SCISSORS', 'RPS', 'PIEDRA_PAPEL_TIJERA') THEN
    IF COALESCE(v_state->>'status', '') NOT IN ('ROUND_COMMIT', 'selecting') AND
       COALESCE(v_state->>'phase', '') NOT IN ('ROUND_COMMIT', 'selecting') THEN
      RETURN jsonb_build_object('success', true, 'action', 'NOT_IN_COMMIT_PHASE', 'status', v_state->>'status');
    END IF;

    v_curr_round := COALESCE((v_state->>'roundNumber')::int, (v_state->>'round')::int, 1);
    v_idempotency_key := 'rps_timeout_' || substr(p_session_id::text, 1, 8) || '_rnd_' || v_curr_round::text;

    v_p1_id := NULLIF(TRIM(v_state->>'player1Id'), '')::uuid;
    v_p2_id := NULLIF(TRIM(v_state->>'player2Id'), '')::uuid;

    IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
      SELECT
        (jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)->>0)::uuid,
        (jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)->>1)::uuid
      INTO v_p1_id, v_p2_id
      FROM public.game_table_players
      WHERE table_id = v_session.table_id
        AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED');
    END IF;

    -- Obtener jugadas secretas autoritativas desde game_session_secrets
    SELECT secret_state->'rps_choices' INTO v_secret_choices
    FROM public.game_session_secrets
    WHERE session_id = p_session_id;

    v_secret_choices := COALESCE(v_secret_choices, '{}'::jsonb);
    v_p1_committed := (v_secret_choices ? v_p1_id::text) AND (v_secret_choices->>v_p1_id::text IS NOT NULL);
    v_p2_committed := (v_secret_choices ? v_p2_id::text) AND (v_secret_choices->>v_p2_id::text IS NOT NULL);

    -- Si ambos jugadores ya habían jugado, no expirar, avanzar a revelación
    IF v_p1_committed AND v_p2_committed THEN
      RETURN jsonb_build_object(
        'success', true,
        'action', 'BOTH_ALREADY_COMMITTED',
        'roundNumber', v_curr_round
      );
    END IF;

    -- SUB-CASO 2A: Si ambos se demoraron sin jugar -> Empate por doble timeout, reset de ronda sin pérdida de vidas
    IF (NOT v_p1_committed) AND (NOT v_p2_committed) THEN
      v_duration := COALESCE(v_session.turn_duration_seconds, 15);
      v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

      v_new_state := v_state || jsonb_build_object(
        'roundNumber', v_curr_round + 1,
        'round', v_curr_round + 1,
        'phase', 'selecting',
        'status', 'ROUND_COMMIT',
        'player1Choice', NULL::text,
        'player2Choice', NULL::text,
        'roundWinner', NULL::text,
        'roundWinnerUserId', NULL::uuid,
        'currentTurnUserId', NULL::uuid,
        'turnUserId', NULL::uuid,
        'lastRoundResult', 'DRAW_DOUBLE_TIMEOUT',
        'timeoutUserId', NULL::uuid,
        'playerChoices', jsonb_build_object(
          v_p1_id::text, jsonb_build_object('committed', false),
          v_p2_id::text, jsonb_build_object('committed', false)
        ),
        'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          current_turn_user_id = NULL,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      UPDATE public.game_session_secrets
      SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', '{}'::jsonb),
          updated_at = NOW()
      WHERE session_id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_DOUBLE_TIMEOUT_RESET',
        'roundNumber', v_curr_round + 1,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;

    -- SUB-CASO 2B: Uno sí jugó y el otro expiró -> El que jugó gana la ronda, el que expiró pierde 1 vida
    IF v_p1_committed AND (NOT v_p2_committed) THEN
      v_winner_id := v_p1_id;
      v_loser_id := v_p2_id;
    ELSIF v_p2_committed AND (NOT v_p1_committed) THEN
      v_winner_id := v_p2_id;
      v_loser_id := v_p1_id;
    END IF;

    v_p1_lives := COALESCE((v_state->>'player1Lives')::int, (v_state->'lives'->>v_p1_id::text)::int, 3);
    v_p2_lives := COALESCE((v_state->>'player2Lives')::int, (v_state->'lives'->>v_p2_id::text)::int, 3);

    IF v_loser_id = v_p1_id THEN
      v_p1_lives := GREATEST(0, v_p1_lives - 1);
    ELSE
      v_p2_lives := GREATEST(0, v_p2_lives - 1);
    END IF;

    v_scores := COALESCE(v_state->'scores', jsonb_build_object(v_p1_id::text, 0, v_p2_id::text, 0));
    v_opp_score := COALESCE((v_scores->>v_winner_id::text)::int, 0) + 1;
    v_scores := jsonb_set(v_scores, ARRAY[v_winner_id::text], to_jsonb(v_opp_score));

    v_is_game_over := (v_p1_lives <= 0 OR v_p2_lives <= 0);

    IF v_is_game_over THEN
      v_new_state := v_state || jsonb_build_object(
        'status', 'MATCH_ENDED',
        'phase', 'match_ended',
        'isGameOver', true,
        'matchWinner', CASE WHEN v_winner_id = v_p1_id THEN 'PLAYER1' ELSE 'PLAYER2' END,
        'winnerUserId', v_winner_id,
        'player1Lives', v_p1_lives,
        'player2Lives', v_p2_lives,
        'lives', jsonb_build_object(v_p1_id::text, v_p1_lives, v_p2_id::text, v_p2_lives),
        'scores', v_scores,
        'currentTurnUserId', NULL::uuid,
        'turnUserId', NULL::uuid,
        'timeoutUserId', v_loser_id,
        'abandonedBy', v_loser_id
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_winner_id,
          current_turn_user_id = NULL,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      UPDATE public.game_session_secrets
      SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', '{}'::jsonb),
          updated_at = NOW()
      WHERE session_id = p_session_id;

      SELECT public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL::INT,
        v_idempotency_key
      ) INTO v_settle_result;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_MATCH_CONCLUDED_TIMEOUT',
        'winnerUserId', v_winner_id,
        'timeoutUserId', v_loser_id,
        'settlement', v_settle_result
      );
    ELSE
      v_duration := COALESCE(v_session.turn_duration_seconds, 15);
      v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

      v_new_state := v_state || jsonb_build_object(
        'roundNumber', v_curr_round + 1,
        'round', v_curr_round + 1,
        'phase', 'selecting',
        'status', 'ROUND_COMMIT',
        'player1Choice', NULL::text,
        'player2Choice', NULL::text,
        'roundWinner', NULL::text,
        'roundWinnerUserId', NULL::uuid,
        'player1Lives', v_p1_lives,
        'player2Lives', v_p2_lives,
        'lives', jsonb_build_object(v_p1_id::text, v_p1_lives, v_p2_id::text, v_p2_lives),
        'currentTurnUserId', NULL::uuid,
        'turnUserId', NULL::uuid,
        'playerChoices', jsonb_build_object(
          v_p1_id::text, jsonb_build_object('committed', false),
          v_p2_id::text, jsonb_build_object('committed', false)
        ),
        'scores', v_scores,
        'lastRoundResult', 'TIMEOUT_AWARD',
        'lastRoundWinner', v_winner_id,
        'timeoutUserId', v_loser_id,
        'turnDeadlineAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
      );

      UPDATE public.game_sessions
      SET current_state = v_new_state,
          current_turn_user_id = NULL,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      UPDATE public.game_session_secrets
      SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', '{}'::jsonb),
          updated_at = NOW()
      WHERE session_id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'RPS_ROUND_AWARDED_TIMEOUT',
        'winnerUserId', v_winner_id,
        'timeoutUserId', v_loser_id,
        'newRound', v_curr_round + 1,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- =========================================================================
  -- CASO 3: VALIDACIÓN DE JUEGOS SECUENCIALES AUTORIZADOS
  -- =========================================================================
  IF v_game_type_str NOT IN (
    'TRES_EN_RAYA', 'TIC_TAC_TOE', 'TICTACTOE', 'LA_VIEJA',
    'ATRAPAITO', 'ATRAPAITO_CRIOLLO',
    'PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO',
    'DOMINO_VENEZOLANO', 'DOMINO',
    'TRUCO_VENEZOLANO', 'TRUCO',
    'CHESS', 'AJEDREZ',
    'DAMAS',
    'UNA_OLLA'
  ) THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'GAME_TYPE_NOT_HANDLED_BY_SEQUENTIAL_TIMEOUT',
      'gameType', v_game_type_str
    );
  END IF;

  v_turn_user_id := COALESCE(
    v_session.current_turn_user_id,
    (v_state->>'turnUserId')::UUID,
    (v_state->>'currentTurnUserId')::UUID,
    (v_state->>'currentTurn')::UUID
  );

  IF v_turn_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_TURN');
  END IF;

  -- =========================================================================
  -- RESOLUCIÓN ORDENADA DEL SIGUIENTE TURNO (v_next_turn_user_id)
  -- =========================================================================
  v_parchis_order := v_state->'playerOrder';
  IF v_game_type_str IN ('PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO') AND
     jsonb_typeof(v_parchis_order) = 'array' AND jsonb_array_length(v_parchis_order) >= 2 THEN
    v_parchis_len := jsonb_array_length(v_parchis_order);
    FOR v_i IN 0..(v_parchis_len - 1) LOOP
      IF (v_parchis_order->>v_i)::UUID = v_turn_user_id THEN
        v_next_turn_user_id := (v_parchis_order->>((v_i + 1) % v_parchis_len))::UUID;
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_next_turn_user_id IS NULL THEN
    SELECT jsonb_agg(user_id ORDER BY seat_number ASC, joined_at ASC)
    INTO v_player_order
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED');

    v_player_count := COALESCE(jsonb_array_length(v_player_order), 0);

    IF v_player_count >= 2 THEN
      FOR v_i IN 0..(v_player_count - 1) LOOP
        IF (v_player_order->>v_i)::UUID = v_turn_user_id THEN
          v_next_turn_user_id := (v_player_order->>((v_i + 1) % v_player_count))::UUID;
          EXIT;
        END IF;
      END LOOP;
    END IF;
  END IF;

  IF v_next_turn_user_id IS NULL THEN
    SELECT user_id INTO v_next_turn_user_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id != v_turn_user_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  v_scores := COALESCE(v_state->'scores', jsonb_build_object(
    v_turn_user_id::TEXT, 0,
    COALESCE(v_next_turn_user_id::TEXT, 'opp'), 0
  ));
  v_opp_score := COALESCE((v_scores->>v_next_turn_user_id::TEXT)::INT, 0);
  v_target_wins := COALESCE((v_state->>'targetWins')::INT, 3);
  v_curr_round := COALESCE((v_state->>'round')::INT, 1);
  v_duration := COALESCE(v_session.turn_duration_seconds, 30);
  v_new_deadline := NOW() + (v_duration || ' seconds')::INTERVAL;

  v_idempotency_key := 'to_' || substr(p_session_id::TEXT, 1, 8) || '_' || substr(v_turn_user_id::TEXT, 1, 8) || '_' || md5(p_session_id::TEXT || '_' || v_turn_user_id::TEXT || '_' || COALESCE(v_session.turn_deadline_at::TEXT, '0'));

  -- SUB-RAMA A: TIC TAC TOE / LA VIEJA
  IF v_game_type_str IN ('TIC_TAC_TOE', 'TICTACTOE', 'LA_VIEJA', 'TRES_EN_RAYA') THEN
    v_lives := COALESCE(v_state->'lives', jsonb_build_object(
      v_turn_user_id::TEXT, 3,
      COALESCE(v_next_turn_user_id::TEXT, 'opp'), 3
    ));
    v_curr_lives := GREATEST(0, COALESCE((v_lives->>v_turn_user_id::TEXT)::INT, 3) - 1);
    v_lives := jsonb_set(v_lives, ARRAY[v_turn_user_id::TEXT], to_jsonb(v_curr_lives));

    IF v_curr_lives <= 0 AND v_next_turn_user_id IS NOT NULL THEN
      v_opp_score := v_target_wins;
      v_scores := jsonb_set(v_scores, ARRAY[v_next_turn_user_id::TEXT], to_jsonb(v_opp_score));

      v_state := v_state || jsonb_build_object(
        'status', 'FINISHED',
        'phase', 'match_ended',
        'isGameOver', true,
        'winnerUserId', v_next_turn_user_id,
        'scores', v_scores,
        'lives', v_lives,
        'abandonedBy', v_turn_user_id,
        'timeoutUserId', v_turn_user_id
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          status = 'FINISHED'::session_status_enum,
          winner_user_id = v_next_turn_user_id,
          turn_deadline_at = NULL,
          turn_expires_at = NULL,
          ended_at = NOW(),
          updated_at = NOW()
      WHERE id = p_session_id;

      SELECT public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_next_turn_user_id],
        NULL::INT,
        v_idempotency_key
      ) INTO v_settle_result;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'MATCH_CONCLUDED_TIMEOUT',
        'winnerUserId', v_next_turn_user_id,
        'timeoutUserId', v_turn_user_id,
        'settlement', v_settle_result
      );
    ELSE
      v_opp_score := v_opp_score + 1;
      v_scores := jsonb_set(v_scores, ARRAY[v_next_turn_user_id::TEXT], to_jsonb(v_opp_score));

      v_state := v_state || jsonb_build_object(
        'round', v_curr_round + 1,
        'phase', 'playing',
        'board', jsonb_build_array(NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
        'winningLine', NULL,
        'scores', v_scores,
        'lives', v_lives,
        'turnUserId', v_next_turn_user_id,
        'currentTurnUserId', v_next_turn_user_id,
        'turnExpiresAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
      );

      UPDATE public.game_sessions
      SET current_state = v_state,
          current_turn_user_id = v_next_turn_user_id,
          turn_deadline_at = v_new_deadline,
          turn_expires_at = v_new_deadline,
          updated_at = NOW()
      WHERE id = p_session_id;

      RETURN jsonb_build_object(
        'success', true,
        'action', 'ROUND_AWARDED_TIMEOUT',
        'winnerUserId', v_next_turn_user_id,
        'timeoutUserId', v_turn_user_id,
        'newRound', v_curr_round + 1,
        'currentTurnUserId', v_next_turn_user_id,
        'turnDeadlineAt', v_new_deadline
      );
    END IF;
  END IF;

  -- SUB-RAMA B: ATRAPAÍTO CRIOLLO
  IF v_game_type_str IN ('ATRAPAITO', 'ATRAPAITO_CRIOLLO') THEN
    v_curr_color := COALESCE(v_state->>'activePlayerColor', 'RED');
    IF v_curr_color = 'RED' THEN
      v_next_color := 'BLUE';
    ELSE
      v_next_color := 'RED';
    END IF;

    v_state := v_state || jsonb_build_object(
      'currentTurnUserId', v_next_turn_user_id,
      'turnUserId', v_next_turn_user_id,
      'activePlayerColor', v_next_color,
      'turnExpiresAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
    );

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_deadline_at = v_new_deadline,
        turn_expires_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'ATRAPAITO_TURN_ROTATED',
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'nextColor', v_next_color,
      'turnDeadlineAt', v_new_deadline
    );
  END IF;

  -- SUB-RAMA C: PARCHÍS VENEZOLANO
  IF v_game_type_str IN ('PARCHIS', 'PARCHIS_VENEZOLANO', 'LUDO') THEN
    v_parchis_players := v_state->'players';
    v_parchis_next_color := NULL;

    IF jsonb_typeof(v_parchis_players) = 'array' THEN
      FOR v_i IN 0..(jsonb_array_length(v_parchis_players) - 1) LOOP
        IF (v_parchis_players->v_i->>'userId')::UUID = v_next_turn_user_id THEN
          v_parchis_next_color := v_parchis_players->v_i->>'color';
          EXIT;
        END IF;
      END LOOP;
    END IF;

    v_state := v_state || jsonb_build_object(
      'currentTurnUserId', v_next_turn_user_id,
      'turnUserId', v_next_turn_user_id,
      'currentTurn', v_next_turn_user_id,
      'activePlayerColor', COALESCE(v_parchis_next_color, v_state->>'activePlayerColor'),
      'hasRolled', false,
      'dice', '[]'::jsonb,
      'turnExpiresAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
    );

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_deadline_at = v_new_deadline,
        turn_expires_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'action', 'PARCHIS_TURN_ROTATED',
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'nextColor', v_parchis_next_color,
      'turnDeadlineAt', v_new_deadline
    );
  END IF;

  -- SUB-RAMA D: DOMINÓ, TRUCO, AJEDREZ, DAMAS, UNA OLLA
  v_state := v_state || jsonb_build_object(
    'currentTurnUserId', v_next_turn_user_id,
    'turnUserId', v_next_turn_user_id,
    'turnExpiresAt', EXTRACT(EPOCH FROM v_new_deadline) * 1000
  );

  UPDATE public.game_sessions
  SET current_state = v_state,
      current_turn_user_id = v_next_turn_user_id,
      turn_deadline_at = v_new_deadline,
      turn_expires_at = v_new_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  INSERT INTO public.game_actions (
    session_id,
    user_id,
    sequence_number,
    action_type,
    payload,
    is_valid,
    server_state_hash,
    idempotency_key
  ) VALUES (
    p_session_id,
    v_turn_user_id,
    COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
    'TURN_EXPIRED',
    jsonb_build_object(
      'expiredUserId', v_turn_user_id,
      'nextTurnUserId', v_next_turn_user_id,
      'turnDeadline', v_new_deadline
    ),
    true,
    md5(v_state::TEXT),
    v_idempotency_key
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'success', true,
    'action', 'TURN_ROTATED',
    'expiredUserId', v_turn_user_id,
    'nextTurnUserId', v_next_turn_user_id,
    'turnDeadlineAt', v_new_deadline
  );
END;
$function$;

-- Asegurar permisos de ejecución
GRANT EXECUTE ON FUNCTION public.expire_game_turn_secure(uuid) TO authenticated, service_role, anon;

NOTIFY pgrst, 'reload schema';



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 165: 161_definitive_rps_three_lives_and_flow_continuity.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- MIGRACIÓN 161: CORRECCIÓN DEFINITIVA DE PIEDRA, PAPEL O TIJERA (RPS)
-- REGLA DE ORO DE 3 VIDAS Y CONTINUIDAD AUTOMÁTICA DE RONDAS
-- =============================================================================
-- 1. Redefine 'next_rps_round_secure':
--    - Elimina referencias a columnas inexistentes en 'game_sessions'.
--    - Obtiene deterministamente 'player1Id' y 'player2Id' desde current_state
--      o desde 'game_table_players'.
--    - Preserva de forma fidedigna e inmutable las vidas actuales (player1Lives y player2Lives).
--    - Resetea choices, roundWinner, roundWinnerUserId, matchWinner y winnerUserId a NULL.
--    - Inicializa 'playerChoices' a committed: false para ambos jugadores.
--    - Establece status = 'ROUND_COMMIT', phase = 'selecting' y nuevo deadline de 15 segundos.
--    - Limpia la clave 'rps_choices' en 'game_session_secrets'.
--    - Inserta acción 'NEXT_ROUND' en 'game_actions' para broadcast en tiempo real.
-- 2. Redefine 'submit_rps_choice_secure':
--    - Ejecuta el sistema estricto de 3 vidas:
--      * Cada jugador comienza con 3 vidas.
--      * Una derrota de ronda = pierde 1 vida (GREATEST(0, vidas - 1)).
--      * Un empate (DRAW) = NINGÚN jugador pierde vidas.
--      * Ganar la ronda = no pierde vida.
--      * Si ambos jugadores tienen > 0 vidas:
--        status = 'ROUND_REVEAL', phase = 'round_result', isGameOver = false.
--      * ÚNICAMENTE cuando un jugador llega a 0 vidas:
--        status = 'MATCH_ENDED', phase = 'match_ended', isGameOver = true,
--        liquidación atómica con 'universal_settle_game_session'.
-- =============================================================================

-- 1. NEXT_RPS_ROUND_SECURE
CREATE OR REPLACE FUNCTION public.next_rps_round_secure(
  p_session_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_session RECORD;
  v_base_state JSONB;
  v_curr_round INT;
  v_new_round INT;
  v_new_state JSONB;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_p1_lives INT := 3;
  v_p2_lives INT := 3;
  v_deadline TIMESTAMPTZ;
BEGIN
  IF p_session_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_ID_REQUIRED');
  END IF;

  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF UPPER(v_session.status::text) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED') THEN
    RETURN jsonb_build_object('success', true, 'action', 'ALREADY_FINALIZED', 'status', v_session.status::text);
  END IF;

  v_base_state := COALESCE(v_session.current_state, '{}'::jsonb);
  IF jsonb_typeof(v_base_state) != 'object' THEN
    v_base_state := '{}'::jsonb;
  END IF;

  -- Si ya está en ROUND_COMMIT / selecting, devolver éxito idempotente
  IF COALESCE(v_base_state->>'status', '') = 'ROUND_COMMIT' OR
     COALESCE(v_base_state->>'phase', '') = 'selecting' THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'ALREADY_IN_COMMIT_PHASE',
      'round', COALESCE((v_base_state->>'roundNumber')::int, 1),
      'status', 'ROUND_COMMIT'
    );
  END IF;

  -- Identificar a los dos contendientes de forma determinista
  v_p1_id := NULLIF(TRIM(v_base_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_base_state->>'player2Id'), '');

  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  -- Si faltan jugadores no se puede avanzar ronda
  IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_PLAYERS');
  END IF;

  -- Preservar fidedignamente las vidas actuales
  v_p1_lives := COALESCE(
    (v_base_state->>'player1Lives')::int,
    (v_base_state->'lives'->>v_p1_id)::int,
    3
  );
  v_p2_lives := COALESCE(
    (v_base_state->>'player2Lives')::int,
    (v_base_state->'lives'->>v_p2_id)::int,
    3
  );

  -- Si alguno de los jugadores ya tiene 0 vidas, la partida no debe avanzar más
  IF v_p1_lives <= 0 OR v_p2_lives <= 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'action', 'MATCH_ALREADY_OVER',
      'player1Lives', v_p1_lives,
      'player2Lives', v_p2_lives
    );
  END IF;

  v_curr_round := COALESCE((v_base_state->>'roundNumber')::int, (v_base_state->>'round')::int, 1);
  v_new_round := v_curr_round + 1;
  v_deadline := NOW() + INTERVAL '15 seconds';

  -- Construir el nuevo estado limpio para la siguiente ronda
  v_new_state := v_base_state || jsonb_build_object(
    'player1Id', v_p1_id,
    'player2Id', v_p2_id,
    'player1Lives', v_p1_lives,
    'player2Lives', v_p2_lives,
    'lives', jsonb_build_object(v_p1_id, v_p1_lives, v_p2_id, v_p2_lives),
    'roundNumber', v_new_round,
    'round', v_new_round,
    'player1Choice', NULL::text,
    'player2Choice', NULL::text,
    'roundWinner', NULL::text,
    'roundWinnerUserId', NULL::uuid,
    'matchWinner', NULL::text,
    'winnerUserId', NULL::uuid,
    'status', 'ROUND_COMMIT',
    'phase', 'selecting',
    'currentTurnUserId', NULL::uuid,
    'turnUserId', NULL::uuid,
    'turnDurationSeconds', 15,
    'turnDeadlineAt', EXTRACT(EPOCH FROM v_deadline) * 1000,
    'playerChoices', jsonb_build_object(
      v_p1_id, jsonb_build_object('committed', false),
      v_p2_id, jsonb_build_object('committed', false)
    )
  );

  IF v_new_state IS NULL THEN
    v_new_state := '{}'::jsonb;
  END IF;

  UPDATE public.game_sessions
  SET current_state = v_new_state,
      current_turn_user_id = NULL,
      turn_expires_at = v_deadline,
      turn_deadline_at = v_deadline,
      updated_at = NOW()
  WHERE id = p_session_id;

  -- Limpiar las jugadas secretas de la ronda previa
  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', '{}'::jsonb),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  -- Notificar a ambos clientes en tiempo real a través de game_actions
  INSERT INTO public.game_actions (
    session_id,
    user_id,
    sequence_number,
    action_type,
    payload,
    is_valid,
    server_state_hash,
    idempotency_key
  ) VALUES (
    p_session_id,
    COALESCE(auth.uid(), v_p1_id::uuid),
    COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
    'NEXT_ROUND',
    jsonb_build_object(
      'round', v_new_round,
      'status', 'ROUND_COMMIT',
      'player1Lives', v_p1_lives,
      'player2Lives', v_p2_lives
    ),
    true,
    md5(v_new_state::text),
    'rps_next_round_' || p_session_id::text || '_rnd_' || v_new_round::text
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_round', v_new_round,
    'round', v_new_round,
    'status', 'ROUND_COMMIT',
    'player1Lives', v_p1_lives,
    'player2Lives', v_p2_lives
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.next_rps_round_secure(UUID) TO authenticated, anon, service_role;


-- 2. SUBMIT_RPS_CHOICE_SECURE (REGLA DE 3 VIDAS Y EVALUACIÓN DETERMINISTA)
CREATE OR REPLACE FUNCTION public.submit_rps_choice_secure(
  p_session_id UUID,
  p_choice VARCHAR
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_base_state JSONB;
  v_secret_row RECORD;
  v_secret_state JSONB;
  v_secret_choices JSONB;
  v_norm_choice VARCHAR;
  v_p1_id TEXT;
  v_p2_id TEXT;
  v_p1_lives INT;
  v_p2_lives INT;
  v_c1 VARCHAR;
  v_c2 VARCHAR;
  v_round_winner TEXT;
  v_round_winner_user_id UUID;
  v_is_game_over BOOLEAN := false;
  v_match_winner TEXT := NULL;
  v_winner_user_id UUID := NULL;
  v_curr_round INT;
  v_new_state JSONB;
  v_history_entry JSONB;
  v_new_history JSONB;
  v_generated_seed VARCHAR(64);
BEGIN
  -- 1. Autenticación y Autorización
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  END IF;

  -- 2. Normalización y Validación del Movimiento
  v_norm_choice := UPPER(TRIM(p_choice));
  IF v_norm_choice NOT IN ('ROCK', 'PAPER', 'SCISSORS') THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_CHOICE', 'message', 'La jugada debe ser ROCK, PAPER o SCISSORS');
  END IF;

  -- 3. Bloqueo de la Sesión (FOR UPDATE)
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_FOUND');
  END IF;

  IF UPPER(v_session.status::text) NOT IN ('ACTIVE', 'WAITING') THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESSION_NOT_ACTIVE');
  END IF;

  v_base_state := COALESCE(v_session.current_state, '{}'::jsonb);
  IF jsonb_typeof(v_base_state) != 'object' THEN
    v_base_state := '{}'::jsonb;
  END IF;

  -- Verificar tabla de secretos
  SELECT * INTO v_secret_row
  FROM public.game_session_secrets
  WHERE session_id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_generated_seed := encode(gen_random_bytes(32), 'hex');
    INSERT INTO public.game_session_secrets (session_id, secret_state, server_seed)
    VALUES (p_session_id, '{}'::jsonb, v_generated_seed)
    RETURNING * INTO v_secret_row;
  END IF;

  v_secret_state := COALESCE(v_secret_row.secret_state, '{}'::jsonb);
  IF jsonb_typeof(v_secret_state) != 'object' THEN
    v_secret_state := '{}'::jsonb;
  END IF;

  -- Identificar jugadores de forma determinista
  v_p1_id := NULLIF(TRIM(v_base_state->>'player1Id'), '');
  v_p2_id := NULLIF(TRIM(v_base_state->>'player2Id'), '');

  IF v_p1_id IS NULL THEN
    SELECT user_id::text INTO v_p1_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  IF v_p2_id IS NULL THEN
    SELECT user_id::text INTO v_p2_id
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND user_id::text != v_p1_id
      AND status::text NOT IN ('LEFT', 'CANCELLED', 'REPLACED')
    ORDER BY seat_number ASC, joined_at ASC
    LIMIT 1;
  END IF;

  IF v_p1_id IS NULL OR v_p2_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_PLAYERS_IN_SESSION');
  END IF;

  IF v_user_id::text != v_p1_id AND v_user_id::text != v_p2_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'NOT_A_PLAYER_IN_THIS_MATCH');
  END IF;

  -- Validar fase de selección
  IF COALESCE(v_base_state->>'status', 'ROUND_COMMIT') NOT IN ('ROUND_COMMIT', 'selecting') AND
     COALESCE(v_base_state->>'phase', 'selecting') NOT IN ('ROUND_COMMIT', 'selecting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ROUND_NOT_ACCEPTING_CHOICES');
  END IF;

  -- Anti-double submit
  v_secret_choices := COALESCE(v_secret_state->'rps_choices', '{}'::jsonb);
  IF jsonb_typeof(v_secret_choices) != 'object' THEN
    v_secret_choices := '{}'::jsonb;
  END IF;

  IF (v_secret_choices ? v_user_id::text AND v_secret_choices->>v_user_id::text IS NOT NULL) OR
     (COALESCE((v_base_state->'playerChoices'->(v_user_id::text)->>'committed')::boolean, false) IS TRUE) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'ALREADY_COMMITTED',
      'message', 'Ya has enviado tu jugada para esta ronda'
    );
  END IF;

  -- Guardar jugada privada en game_session_secrets
  v_secret_choices := v_secret_choices || jsonb_build_object(v_user_id::text, v_norm_choice);

  UPDATE public.game_session_secrets
  SET secret_state = jsonb_set(COALESCE(secret_state, '{}'::jsonb), '{rps_choices}', v_secret_choices),
      updated_at = NOW()
  WHERE session_id = p_session_id;

  v_c1 := v_secret_choices->>v_p1_id;
  v_c2 := v_secret_choices->>v_p2_id;

  -- =========================================================================
  -- EVALUACIÓN: ¿Ambos jugadores han elegido?
  -- =========================================================================
  IF v_c1 IS NOT NULL AND v_c2 IS NOT NULL THEN
    -- Determinar ganador de la ronda
    IF v_c1 = v_c2 THEN
      v_round_winner := 'DRAW';
      v_round_winner_user_id := NULL;
    ELSIF (v_c1 = 'ROCK' AND v_c2 = 'SCISSORS') OR
          (v_c1 = 'PAPER' AND v_c2 = 'ROCK') OR
          (v_c1 = 'SCISSORS' AND v_c2 = 'PAPER') THEN
      v_round_winner := 'PLAYER1';
      v_round_winner_user_id := v_p1_id::uuid;
    ELSE
      v_round_winner := 'PLAYER2';
      v_round_winner_user_id := v_p2_id::uuid;
    END IF;

    -- Extraer vidas previas (default 3)
    v_p1_lives := COALESCE((v_base_state->>'player1Lives')::int, (v_base_state->'lives'->>v_p1_id)::int, 3);
    v_p2_lives := COALESCE((v_base_state->>'player2Lives')::int, (v_base_state->'lives'->>v_p2_id)::int, 3);

    -- Regla de 3 Vidas: Solo el perdedor de la ronda pierde 1 vida. En empate, NADIE pierde vida.
    IF v_round_winner = 'PLAYER1' THEN
      v_p2_lives := GREATEST(0, v_p2_lives - 1);
    ELSIF v_round_winner = 'PLAYER2' THEN
      v_p1_lives := GREATEST(0, v_p1_lives - 1);
    END IF;

    -- Condición inequívoca de fin de partida: un jugador llega a 0 vidas
    IF v_p1_lives <= 0 THEN
      v_match_winner := 'PLAYER2';
      v_winner_user_id := v_p2_id::uuid;
      v_is_game_over := true;
    ELSIF v_p2_lives <= 0 THEN
      v_match_winner := 'PLAYER1';
      v_winner_user_id := v_p1_id::uuid;
      v_is_game_over := true;
    ELSE
      v_match_winner := NULL;
      v_winner_user_id := NULL;
      v_is_game_over := false;
    END IF;

    v_curr_round := COALESCE((v_base_state->>'roundNumber')::int, (v_base_state->>'round')::int, 1);

    v_history_entry := jsonb_build_object(
      'roundNumber', v_curr_round,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'winner', v_round_winner,
      'winnerUserId', v_round_winner_user_id,
      'timestamp', FLOOR(EXTRACT(EPOCH FROM NOW()) * 1000)
    );

    v_new_history := COALESCE(
      CASE WHEN jsonb_typeof(v_base_state->'history') = 'array' THEN v_base_state->'history' ELSE '[]'::jsonb END,
      '[]'::jsonb
    ) || v_history_entry;

    -- Construir nuevo estado público
    v_new_state := v_base_state || jsonb_build_object(
      'player1Id', v_p1_id,
      'player2Id', v_p2_id,
      'player1Choice', v_c1,
      'player2Choice', v_c2,
      'player1Lives', v_p1_lives,
      'player2Lives', v_p2_lives,
      'lives', jsonb_build_object(v_p1_id, v_p1_lives, v_p2_id, v_p2_lives),
      'roundWinner', v_round_winner,
      'roundWinnerUserId', v_round_winner_user_id,
      'matchWinner', v_match_winner,
      'winnerUserId', v_winner_user_id,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'phase', CASE WHEN v_is_game_over THEN 'match_ended' ELSE 'round_result' END,
      'history', v_new_history,
      'currentTurnUserId', NULL::uuid,
      'turnUserId', NULL::uuid,
      'roundNumber', v_curr_round,
      'round', v_curr_round,
      'playerChoices', jsonb_build_object(
        v_p1_id, jsonb_build_object('committed', true, 'choice', v_c1),
        v_p2_id, jsonb_build_object('committed', true, 'choice', v_c2)
      )
    );

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        current_turn_user_id = NULL,
        winner_user_id = v_winner_user_id,
        turn_expires_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        turn_deadline_at = CASE WHEN v_is_game_over THEN NULL ELSE NOW() + INTERVAL '15 seconds' END,
        ended_at = CASE WHEN v_is_game_over THEN NOW() ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_session_id;

    -- Liquidación atómica si el match concluyó
    IF v_is_game_over THEN
      PERFORM public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_user_id],
        NULL::int,
        'rps_match_' || p_session_id::text
      );
    END IF;

    -- Registrar acción inmutable en game_actions
    INSERT INTO public.game_actions (
      session_id,
      user_id,
      sequence_number,
      action_type,
      payload,
      is_valid,
      server_state_hash,
      idempotency_key
    ) VALUES (
      p_session_id,
      v_user_id,
      COALESCE((SELECT MAX(sequence_number) FROM public.game_actions WHERE session_id = p_session_id), 0) + 1,
      'ROUND_REVEAL',
      jsonb_build_object(
        'round', v_curr_round,
        'player1Choice', v_c1,
        'player2Choice', v_c2,
        'roundWinner', v_round_winner,
        'isGameOver', v_is_game_over,
        'player1Lives', v_p1_lives,
        'player2Lives', v_p2_lives
      ),
      true,
      md5(v_new_state::text),
      'rps_reveal_' || p_session_id::text || '_rnd_' || v_curr_round::text
    );

    RETURN jsonb_build_object(
      'success', true,
      'bothChosen', true,
      'committed', true,
      'phase', CASE WHEN v_is_game_over THEN 'match_ended' ELSE 'round_result' END,
      'status', CASE WHEN v_is_game_over THEN 'MATCH_ENDED' ELSE 'ROUND_REVEAL' END,
      'isGameOver', v_is_game_over,
      'player1Lives', v_p1_lives,
      'player2Lives', v_p2_lives,
      'roundWinner', v_round_winner,
      'player1Choice', v_c1,
      'player2Choice', v_c2
    );

  ELSE
    -- SOLO UN JUGADOR HA ELEGIDO HASTA AHORA
    v_new_state := v_base_state || jsonb_build_object(
      'player1Id', v_p1_id,
      'player2Id', v_p2_id,
      'playerChoices', jsonb_build_object(
        v_user_id::text, jsonb_build_object('committed', true)
      )
    );

    UPDATE public.game_sessions
    SET current_state = v_new_state,
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object(
      'success', true,
      'committed', true,
      'bothChosen', false,
      'phase', 'selecting',
      'status', 'ROUND_COMMIT',
      'message', 'Jugada registrada de forma segura. Esperando al contrincante.'
    );
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_rps_choice_secure(UUID, VARCHAR) TO authenticated, anon, service_role;



-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- MIGRACIÓN 166: 162_universal_authoritative_abandonment_system.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- ============================================================================
-- MIGRACIÓN 162: UNIVERSAL AUTHORITATIVE ABANDONMENT AND TURN REASSIGNMENT SYSTEM
-- ============================================================================
-- Motor Universal de Abandono Voluntario de Jugadores:
-- 1. Server-Authoritative con bloqueo 'FOR UPDATE' en game_sessions, game_tables
--    y game_table_players para prevenir carreras e inconsistencias concurrentes.
-- 2. Diferenciación estricta entre abandono voluntario inmediato y timeout/inactividad.
-- 3. Partidas 1v1 / Último Superviviente:
--    - Victoria inmediata otorgada al rival activo.
--    - Liquidación financiera autoritativa inmediata mediante universal_settle_game_session.
-- 4. Partidas por Equipos (Domino 2v2, Truco 2v2):
--    - Victoria inmediata otorgada al equipo contrario completo.
--    - Liquidación financiera autoritativa mediante universal_settle_game_session.
-- 5. Partidas Multijugador Individual (Parchís, etc. con 2+ rivales activos):
--    - La partida continúa con los jugadores restantes.
--    - Si el jugador que abandona tenía el turno activo, se reasigna inmediatamente
--      al siguiente jugador según playerOrder / asientos activos, actualizando
--      currentColor / turn / turn_deadline_at según corresponda.
-- 6. Cancelación / Reembolso Total:
--    - Si todos los jugadores abandonan (0 rivales activos), se cancela la sesión
--      y se reembolsan las entradas mediante refund_game_session.
-- 7. Salida Pre-Partida (Lobby / Waiting):
--    - abandon_game_table_secure libera la retención de entrada a available_balance
--      mediante TABLE_ENTRY_REFUND y cierra la mesa si queda desierta.
-- 8. Idempotencia y emisión de eventos:
--    - Registro atómico en game_actions con acción 'PLAYER_ABANDONED'.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.abandon_game_secure(
  p_session_id UUID,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $function$
DECLARE
  v_user_id UUID;
  v_session RECORD;
  v_table RECORD;
  v_game_type TEXT;
  v_leaving_player RECORD;
  v_effective_idempotency TEXT;
  v_state JSONB;
  v_abandoned_arr JSONB;
  -- Equipos
  v_opponent_team_players UUID[] := ARRAY[]::UUID[];
  v_winning_team INT := NULL;
  -- Jugadores individuales activos restantes
  v_active_players UUID[] := ARRAY[]::UUID[];
  v_active_count INT := 0;
  v_winner_id UUID := NULL;
  -- Turno y orden para multijugador
  v_next_turn_user_id UUID := NULL;
  v_new_deadline TIMESTAMPTZ := NULL;
  v_duration INT := 30;
  v_player_order JSONB;
  v_order_len INT := 0;
  v_i INT := 0;
  v_found_idx INT := -1;
  v_cand_id UUID;
  v_next_color TEXT := NULL;
  v_seq INT;
  v_action_payload JSONB;
BEGIN
  -- 1. Autenticación
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTENTICADO');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_' || substr(p_session_id::text, 1, 8) || '_' || substr(v_user_id::text, 1, 8) || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  -- 2. Bloqueo canónico: 1º game_sessions, 2º game_tables
  SELECT * INTO v_session
  FROM public.game_sessions
  WHERE id = p_session_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SESION_NO_ENCONTRADA');
  END IF;

  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = v_session.table_id
  FOR UPDATE;

  -- 3. Idempotencia: Sesión ya terminada
  IF UPPER(v_session.status::text) IN ('FINISHED', 'SETTLED', 'CANCELLED', 'ABANDONED', 'CLOSED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_finished', true,
      'status', v_session.status::text,
      'message', 'La partida ya finalizó previamente.'
    );
  END IF;

  -- 4. Verificar existencia e idempotencia del jugador
  SELECT * INTO v_leaving_player
  FROM public.game_table_players
  WHERE table_id = v_session.table_id AND user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'JUGADOR_NO_ENCONTRADO_EN_MESA');
  END IF;

  IF v_leaving_player.status::text IN ('ABANDONED', 'LEFT') THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_abandoned', true,
      'message', 'El jugador ya figura como retirado de la partida.'
    );
  END IF;

  -- 5. Marcar jugador como ABANDONED en game_table_players
  UPDATE public.game_table_players
  SET status = 'ABANDONED'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = v_session.table_id
    AND user_id = v_user_id;

  v_state := COALESCE(v_session.current_state, '{}'::jsonb);
  v_game_type := LOWER(COALESCE(v_table.game_type::text, v_session.game_type::text, ''));

  -- Registrar en JSONB del estado
  v_abandoned_arr := COALESCE(v_state->'abandonedPlayers', '[]'::jsonb);
  IF NOT (v_abandoned_arr @> to_jsonb(v_user_id::text)) THEN
    v_abandoned_arr := v_abandoned_arr || to_jsonb(v_user_id::text);
  END IF;
  v_state := jsonb_set(v_state, '{abandonedPlayers}', v_abandoned_arr);
  v_state := jsonb_set(v_state, '{lastAbandonedUserId}', to_jsonb(v_user_id::text));
  v_state := jsonb_set(v_state, '{lastAbandonedAt}', to_jsonb(NOW()::text));

  -- Calcular secuencia para game_actions
  SELECT COALESCE(MAX(sequence_number), 0) + 1 INTO v_seq
  FROM public.game_actions
  WHERE session_id = p_session_id;

  -- =========================================================================
  -- CASO A: JUEGOS COLECTIVOS (BINGO, POLLA VENEZOLANA)
  -- =========================================================================
  IF v_game_type IN ('bingo', 'polla_venezolana', 'polla') THEN
    UPDATE public.game_sessions
    SET current_state = v_state,
        updated_at = NOW()
    WHERE id = p_session_id;

    v_action_payload := jsonb_build_object(
      'userId', v_user_id,
      'isGameOver', false,
      'gameType', v_game_type,
      'reason', 'VOLUNTARY_ABANDON'
    );

    INSERT INTO public.game_actions (
      session_id, user_id, sequence_number, action_type, payload, action_data, idempotency_key, created_at
    ) VALUES (
      p_session_id, v_user_id, v_seq, 'PLAYER_ABANDONED', v_action_payload, v_action_payload, v_effective_idempotency || '_act', NOW()
    ) ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'isGameOver', false,
      'action', 'COLLECTIVE_GAME_ABANDONED',
      'message', 'Has salido de la sala de juego.'
    );
  END IF;

  -- =========================================================================
  -- CASO B: PARTIDAS POR EQUIPOS (ej: Domino 2v2 o Truco 2v2)
  -- =========================================================================
  IF v_leaving_player.team_number IS NOT NULL THEN
    SELECT ARRAY_AGG(user_id ORDER BY seat_number ASC), MAX(team_number)
    INTO v_opponent_team_players, v_winning_team
    FROM public.game_table_players
    WHERE table_id = v_session.table_id
      AND team_number != v_leaving_player.team_number
      AND status::text NOT IN ('ABANDONED', 'LEFT');

    IF v_opponent_team_players IS NOT NULL AND array_length(v_opponent_team_players, 1) > 0 THEN
      -- Victoria inmediata para el equipo contrario
      v_state := jsonb_set(v_state, '{isGameOver}', 'true'::jsonb);
      v_state := jsonb_set(v_state, '{winnerTeam}', to_jsonb(v_winning_team));
      v_state := jsonb_set(v_state, '{winnerReason}', '"OPPONENT_TEAM_BY_ABANDON"'::jsonb);

      -- Liquidación financiera autoritativa al equipo rival completo si hay pozo
      IF v_table.entry_fee > 0.00 THEN
        PERFORM public.universal_settle_game_session(
          p_session_id,
          v_opponent_team_players,
          v_winning_team,
          v_effective_idempotency || '_settle'
        );
      END IF;

      UPDATE public.game_sessions
      SET status = 'FINISHED'::session_status_enum,
          winner_team = v_winning_team,
          current_turn_user_id = NULL,
          turn_deadline_at = NULL,
          ended_at = NOW(),
          current_state = v_state,
          updated_at = NOW()
      WHERE id = p_session_id;

      UPDATE public.game_tables
      SET status = 'CLOSED'::table_status_enum,
          closed_at = NOW(),
          updated_at = NOW()
      WHERE id = v_session.table_id;

      v_action_payload := jsonb_build_object(
        'userId', v_user_id,
        'abandonedTeam', v_leaving_player.team_number,
        'winnerTeam', v_winning_team,
        'winnerUserIds', v_opponent_team_players,
        'isGameOver', true,
        'reason', 'OPPONENT_TEAM_BY_ABANDON'
      );

      INSERT INTO public.game_actions (
        session_id, user_id, sequence_number, action_type, payload, action_data, idempotency_key, created_at
      ) VALUES (
        p_session_id, v_user_id, v_seq, 'PLAYER_ABANDONED', v_action_payload, v_action_payload, v_effective_idempotency || '_act', NOW()
      ) ON CONFLICT DO NOTHING;

      RETURN jsonb_build_object(
        'success', true,
        'isGameOver', true,
        'winnerTeam', v_winning_team,
        'message', 'Has abandonado. Victoria otorgada al equipo rival.'
      );
    END IF;
  END IF;

  -- =========================================================================
  -- CASO C: PARTIDAS INDIVIDUALES (1v1 O MULTIJUGADOR INDIVIDUAL)
  -- =========================================================================
  SELECT ARRAY_AGG(user_id ORDER BY seat_number ASC, joined_at ASC)
  INTO v_active_players
  FROM public.game_table_players
  WHERE table_id = v_session.table_id
    AND user_id != v_user_id
    AND status::text NOT IN ('ABANDONED', 'LEFT');

  v_active_count := COALESCE(array_length(v_active_players, 1), 0);

  -- SUB-CASO C.1: NO QUEDAN JUGADORES ACTIVOS (0 RIVALES)
  IF v_active_count = 0 THEN
    IF v_table.entry_fee > 0.00 THEN
      PERFORM public.refund_game_session(
        p_session_id,
        'Abandono total sin jugadores activos restantes',
        v_effective_idempotency || '_refund'
      );
    END IF;

    UPDATE public.game_sessions
    SET status = 'CANCELLED'::session_status_enum,
        current_turn_user_id = NULL,
        turn_deadline_at = NULL,
        ended_at = NOW(),
        current_state = v_state || jsonb_build_object('isGameOver', true, 'isCancelled', true),
        updated_at = NOW()
    WHERE id = p_session_id;

    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = NOW(),
        updated_at = NOW()
    WHERE id = v_session.table_id;

    v_action_payload := jsonb_build_object(
      'userId', v_user_id,
      'isGameOver', true,
      'cancelled', true,
      'reason', 'ALL_PLAYERS_LEFT'
    );

    INSERT INTO public.game_actions (
      session_id, user_id, sequence_number, action_type, payload, action_data, idempotency_key, created_at
    ) VALUES (
      p_session_id, v_user_id, v_seq, 'PLAYER_ABANDONED', v_action_payload, v_action_payload, v_effective_idempotency || '_act', NOW()
    ) ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'isGameOver', true,
      'cancelled', true,
      'message', 'Partida cancelada: todos los jugadores abandonaron.'
    );

  -- SUB-CASO C.2: EXACTAMENTE 1 RIVAL ACTIVO RESTANTE (1v1 O ÚLTIMO SUPERVIVIENTE)
  ELSIF v_active_count = 1 THEN
    v_winner_id := v_active_players[1];

    -- Ajustes específicos según tipo de juego
    IF v_game_type IN ('rps', 'rock_paper_scissors', 'piedra_papel_tijera') THEN
      v_state := jsonb_set(v_state, '{status}', '"MATCH_ENDED"'::jsonb);
      v_state := jsonb_set(v_state, '{phase}', '"match_ended"'::jsonb);
      v_state := jsonb_set(v_state, '{isGameOver}', 'true'::jsonb);
      v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_winner_id::text));
      v_state := jsonb_set(
        v_state,
        '{matchWinner}',
        (CASE WHEN v_state->>'player1Id' = v_winner_id::text THEN '"player1"' ELSE '"player2"' END)::jsonb
      );
      DELETE FROM public.game_session_secrets WHERE session_id = p_session_id;
    ELSE
      v_state := jsonb_set(v_state, '{isGameOver}', 'true'::jsonb);
      v_state := jsonb_set(v_state, '{winnerUserId}', to_jsonb(v_winner_id::text));
      v_state := jsonb_set(v_state, '{winner}', to_jsonb(v_winner_id::text));
      v_state := jsonb_set(v_state, '{abandonedWinner}', to_jsonb(v_winner_id::text));
      v_state := jsonb_set(v_state, '{winnerReason}', '"OPPONENT_BY_ABANDON"'::jsonb);
    END IF;

    -- Liquidación financiera autoritativa inmediata al ganador si hay pozo
    IF v_table.entry_fee > 0.00 THEN
      PERFORM public.universal_settle_game_session(
        p_session_id,
        ARRAY[v_winner_id],
        NULL,
        v_effective_idempotency || '_settle'
      );
    END IF;

    UPDATE public.game_sessions
    SET status = 'FINISHED'::session_status_enum,
        winner_user_id = v_winner_id,
        current_turn_user_id = NULL,
        turn_deadline_at = NULL,
        ended_at = NOW(),
        current_state = v_state,
        updated_at = NOW()
    WHERE id = p_session_id;

    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = NOW(),
        updated_at = NOW()
    WHERE id = v_session.table_id;

    v_action_payload := jsonb_build_object(
      'userId', v_user_id,
      'isGameOver', true,
      'winnerId', v_winner_id,
      'winnerUserIds', ARRAY[v_winner_id],
      'reason', 'OPPONENT_BY_ABANDON'
    );

    INSERT INTO public.game_actions (
      session_id, user_id, sequence_number, action_type, payload, action_data, idempotency_key, created_at
    ) VALUES (
      p_session_id, v_user_id, v_seq, 'PLAYER_ABANDONED', v_action_payload, v_action_payload, v_effective_idempotency || '_act', NOW()
    ) ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'isGameOver', true,
      'winnerId', v_winner_id,
      'message', 'Has abandonado la partida. Victoria otorgada al rival.'
    );

  -- SUB-CASO C.3: DOS O MÁS RIVALES ACTIVOS RESTANTES (PARTIDA MULTIJUGADOR CONTINÚA)
  ELSE
    -- Reasignar turno si el turno actual pertenecía al jugador que abandona
    IF v_session.current_turn_user_id = v_user_id THEN
      -- Buscar en playerOrder si existe
      v_player_order := v_state->'playerOrder';
      IF jsonb_typeof(v_player_order) = 'array' AND jsonb_array_length(v_player_order) >= 2 THEN
        v_order_len := jsonb_array_length(v_player_order);
        -- Encontrar la posición del jugador que abandona
        FOR v_i IN 0..(v_order_len - 1) LOOP
          IF (v_player_order->>v_i)::UUID = v_user_id THEN
            v_found_idx := v_i;
            EXIT;
          END IF;
        END LOOP;

        -- Buscar el siguiente jugador que esté activo en v_active_players
        IF v_found_idx >= 0 THEN
          FOR v_i IN 1..v_order_len LOOP
            v_cand_id := (v_player_order->>((v_found_idx + v_i) % v_order_len))::UUID;
            IF v_cand_id = ANY(v_active_players) THEN
              v_next_turn_user_id := v_cand_id;
              EXIT;
            END IF;
          END LOOP;
        END IF;
      END IF;

      -- Fallback: buscar según seat_number en v_active_players
      IF v_next_turn_user_id IS NULL THEN
        SELECT user_id INTO v_next_turn_user_id
        FROM public.game_table_players
        WHERE table_id = v_session.table_id
          AND user_id = ANY(v_active_players)
          AND seat_number > v_leaving_player.seat_number
        ORDER BY seat_number ASC
        LIMIT 1;

        -- Wrap-around al asiento menor si no hay mayor
        IF v_next_turn_user_id IS NULL THEN
          SELECT user_id INTO v_next_turn_user_id
          FROM public.game_table_players
          WHERE table_id = v_session.table_id
            AND user_id = ANY(v_active_players)
          ORDER BY seat_number ASC
          LIMIT 1;
        END IF;
      END IF;

      -- Obtener color del siguiente jugador si el juego lo utiliza
      IF v_game_type IN ('parchis', 'parchis_venezolano', 'ludo', 'atrapaito', 'atrapaito_criollo', 'atrapaito_clasico') THEN
        -- Revisar si players en current_state tiene mapeo de colores
        IF jsonb_typeof(v_state->'players') = 'array' THEN
          SELECT (elem->>'color') INTO v_next_color
          FROM jsonb_array_elements(v_state->'players') AS elem
          WHERE (elem->>'id')::text = v_next_turn_user_id::text
             OR (elem->>'userId')::text = v_next_turn_user_id::text
          LIMIT 1;
        END IF;

        IF v_next_color IS NOT NULL THEN
          v_state := jsonb_set(v_state, '{currentColor}', to_jsonb(v_next_color));
          v_state := jsonb_set(v_state, '{turn}', to_jsonb(v_next_color));
        END IF;

        IF v_game_type IN ('parchis', 'parchis_venezolano', 'ludo') THEN
          v_state := jsonb_set(v_state, '{hasRolled}', 'false'::jsonb);
          v_state := jsonb_set(v_state, '{rolledValue}', 'null'::jsonb);
        END IF;
      END IF;

      v_duration := COALESCE(v_session.turn_duration_seconds, 30);
      v_new_deadline := NOW() + (v_duration || ' seconds')::interval;
    ELSE
      -- El turno pertenecía a otro jugador, conservar turno y deadline actual
      v_next_turn_user_id := v_session.current_turn_user_id;
      v_new_deadline := v_session.turn_deadline_at;
    END IF;

    UPDATE public.game_sessions
    SET current_state = v_state,
        current_turn_user_id = v_next_turn_user_id,
        turn_deadline_at = v_new_deadline,
        updated_at = NOW()
    WHERE id = p_session_id;

    v_action_payload := jsonb_build_object(
      'userId', v_user_id,
      'isGameOver', false,
      'remainingActivePlayers', v_active_count,
      'nextTurnUserId', v_next_turn_user_id,
      'turnDeadlineAt', v_new_deadline,
      'reason', 'PLAYER_ABANDONED_CONTINUE'
    );

    INSERT INTO public.game_actions (
      session_id, user_id, sequence_number, action_type, payload, action_data, idempotency_key, created_at
    ) VALUES (
      p_session_id, v_user_id, v_seq, 'PLAYER_ABANDONED', v_action_payload, v_action_payload, v_effective_idempotency || '_act', NOW()
    ) ON CONFLICT DO NOTHING;

    RETURN jsonb_build_object(
      'success', true,
      'isGameOver', false,
      'remainingActivePlayers', v_active_count,
      'nextTurnUserId', v_next_turn_user_id,
      'message', 'Has abandonado la partida. El juego continúa con los jugadores restantes.'
    );
  END IF;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;

CREATE OR REPLACE FUNCTION public.abandon_game_table_secure(
  p_table_id UUID,
  p_session_id UUID DEFAULT NULL,
  p_idempotency_key TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, pg_temp
AS $function$
DECLARE
  v_caller_id UUID;
  v_table RECORD;
  v_player RECORD;
  v_wallet RECORD;
  v_active_players_count INTEGER;
  v_effective_idempotency TEXT;
  v_target_session_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_AUTENTICADO');
  END IF;

  v_effective_idempotency := COALESCE(
    NULLIF(trim(p_idempotency_key), ''),
    'abn_tbl_' || substr(p_table_id::text, 1, 8) || '_' || substr(v_caller_id::text, 1, 8) || '_' || EXTRACT(EPOCH FROM NOW())::text
  );

  -- 1. Determinar ID de sesión objetivo si existe
  v_target_session_id := p_session_id;
  IF v_target_session_id IS NULL THEN
    SELECT id INTO v_target_session_id
    FROM public.game_sessions
    WHERE table_id = p_table_id
      AND status::text IN ('ACTIVE', 'READY', 'STARTING', 'in_progress', 'ROUND_COMMIT', 'ROUND_REVEAL', 'PLAYING')
    ORDER BY created_at DESC
    LIMIT 1;
  END IF;

  -- 2. Si hay sesión activa en curso, DELEGAR DIRECTAMENTE a abandon_game_secure
  IF v_target_session_id IS NOT NULL THEN
    RETURN public.abandon_game_secure(v_target_session_id, v_effective_idempotency);
  END IF;

  -- 3. Si NO hay sesión activa, es una salida de sala pre-partida (Lobby / Waiting)
  SELECT * INTO v_table
  FROM public.game_tables
  WHERE id = p_table_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'MESA_NO_ENCONTRADA');
  END IF;

  -- Verificar jugador en la mesa
  SELECT * INTO v_player
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND user_id = v_caller_id
  FOR UPDATE;

  IF NOT FOUND OR v_player.status::text IN ('LEFT', 'ABANDONED') THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_left', true,
      'table_id', p_table_id,
      'message', 'El jugador ya no se encuentra activo en la mesa.'
    );
  END IF;

  -- Marcar jugador como LEFT
  UPDATE public.game_table_players
  SET status = 'LEFT'::player_table_status_enum,
      left_at = NOW(),
      updated_at = NOW()
  WHERE table_id = p_table_id
    AND user_id = v_caller_id;

  -- 4. Reembolso pre-partida si la mesa tenía entry_fee retenido
  IF v_table.entry_fee > 0.00 THEN
    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_caller_id AND currency = 'VES'
    FOR UPDATE;

    IF FOUND AND v_wallet.held_balance >= v_table.entry_fee THEN
      UPDATE public.wallets
      SET available_balance = available_balance + v_table.entry_fee,
          held_balance = GREATEST(0.00, held_balance - v_table.entry_fee),
          updated_at = NOW()
      WHERE id = v_wallet.id;

      INSERT INTO public.ledger_entries (
        wallet_id,
        user_id,
        amount,
        currency,
        entry_type,
        direction,
        reference_id,
        reference_table,
        reference_type,
        balance_after,
        balance_after_available,
        balance_after_held,
        idempotency_key,
        description,
        created_at
      ) VALUES (
        v_wallet.id,
        v_caller_id,
        v_table.entry_fee,
        'VES',
        'TABLE_ENTRY_REFUND'::ledger_entry_type_enum,
        'RELEASE'::ledger_direction_enum,
        p_table_id,
        'game_tables',
        'TABLE_ENTRY_HOLD',
        v_wallet.available_balance + v_wallet.held_balance,
        v_wallet.available_balance + v_table.entry_fee,
        GREATEST(0.00, v_wallet.held_balance - v_table.entry_fee),
        v_effective_idempotency || '_refund',
        'Liberación de saldo retenido por salida voluntaria de sala pre-partida',
        NOW()
      );
    END IF;
  END IF;

  -- 5. Comprobar si la mesa quedó sin jugadores activos
  SELECT COUNT(*) INTO v_active_players_count
  FROM public.game_table_players
  WHERE table_id = p_table_id
    AND status::text NOT IN ('LEFT', 'ABANDONED');

  IF v_active_players_count = 0 THEN
    UPDATE public.game_tables
    SET status = 'CLOSED'::table_status_enum,
        closed_at = NOW(),
        updated_at = NOW()
    WHERE id = p_table_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'table_id', p_table_id,
    'player_user_id', v_caller_id,
    'remaining_players', v_active_players_count,
    'message', 'Has salido de la sala exitosamente.'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.abandon_game_secure(UUID, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.abandon_game_table_secure(UUID, UUID, TEXT) TO authenticated, service_role;
